section('46. Boarders come home able to use the lift (reported bug)');
// ============================================================
(function testElevatorAfterBoarding() {
  const sb = loadEngine();
  const c = makeCombat(sb);
  const { Game } = sb;
  const T = Game.__test;
  const player = c.player, enemy = c.enemy;

  const shaft = player.elevators.shafts[0];
  ok(!!shaft, 'the hull has a lift shaft');

  // Someone is INSIDE the cabin when the boarding party goes out.
  const rider = player.crew.find(cm => !cm.dead);
  shaft.board(rider, 0);
  ok(shaft.passenger === rider && rider._ridingShaft === shaft,
     'test setup: he really is in the cabin');

  T.boardingParty = T._makeParty(player, enemy, [rider]);
  ok(shaft.passenger === null,
     'launching the party takes him out of the cabin');
  ok(!rider._ridingShaft, 'and clears his passenger flag');

  // Bring him home the way the game does.
  enemy.addCrew(rider, true);
  player.crew = player.crew.filter(k => k !== rider);
  rider._ridingShaft = shaft;             // simulate the stale flag
  shaft.passenger = rider;
  T._recoverBoarders();

  ok(!rider._ridingShaft, 'coming home clears the stale cabin flag');
  ok(shaft.passenger === null, 'and frees the shaft for everybody else');

  // He can now actually plan a route to the other deck.
  const otherFloorY = player.floorWalkY(0, 0) === player.floorWalkY(1, 0)
    ? null : player.floorWalkY(0, 999);
  rider.y = player.floorWalkY(1, 0);
  rider.x = player.rooms[0].cx;
  const routed = rider.moveToOnShip(player, player.rooms[0].cx, player.floorWalkY(0, 999));
  ok(routed !== false, 'he can be routed to the deck below');
  ok(rider._waypoints.some(w => w.elevator),
     'and the route really goes through the lift');
})();

// ============================================================
section('47. Void spiders bite, and the bite carries');
// ============================================================
(function testSpiderBite() {
  const sb = loadEngine();
  const { Ship, CrewMember, Pest, CORP_KEYS, CORP_DEFS, Save } = sb;
  Save.load();          // dying crew reach for the graveyard

  ok(!CORP_KEYS.includes('spider') && !CORP_DEFS.spider,
     'a spider is not a corporation at all any more (update84)');
  ok(typeof sb.makeSpiders === 'undefined' && typeof sb.makeRats === 'undefined',
     'and nothing builds one as a crewman');

  /* update84: the bite is a DROP out of the duct, through the ship's
     own tick — the spider is a Pest, not a man in the brawl. */
  const ship = new Ship('frigate', true, 100, 100);
  const room = ship.rooms.find(r => r.system) || ship.rooms[0];
  const victim = new CrewMember({ name: 'Bitten' });
  victim.x = room.cx; victim.y = ship.floorWalkY(room.floor, room.cy);
  victim.roomId = room.id; victim.inRoom = true;
  ship.addCrew(victim, true);
  const sp = ship.addPest(new Pest({ kind: 'spider', roomId: room.id, x: room.cx }));
  ok(sp.isSpider && ship.pests.length === 1 && !ship.crew.includes(sp),
     'the spider is in the duct list, not the crew list');

  let bites = 0, hurt = false;
  for (let i = 0; i < 400 && !victim.virus; i++) {
    sp._pounceT = 0;                    // drop now
    const before = victim.hp;
    for (let k = 0; k < 12; k++) ship.pestTick(0.1);
    if (victim.hp < before) { hurt = true; bites++; }
    victim.hp = victim.maxHp;           // keep him upright so we test the BITE
  }
  ok(victim.virus, `a spider's drop eventually takes hold (after ${bites} bites)`);
  ok(hurt, 'and the bite itself hurt');
  ok(sp.alive && !sp.pouncing, 'and after each drop it is back up in the duct');

  // Ordinary crew infect nobody.
  const other = new CrewMember({ name: 'Clean' });
  const human = new CrewMember({ name: 'Human' });
  for (let i = 0; i < 200; i++) human.strike(other, 0.01);
  ok(!other.virus, 'ordinary crew do not carry it');

  ok('infected' in victim && 'virus' in victim,
     'the two illnesses are separate flags');

  const back = CrewMember.deserialise(JSON.parse(JSON.stringify(victim.serialise())));
  ok(back.virus === true, 'the virus survives a save');
})();

// ============================================================
section('48. Virus → egg → spiders, all of it on a clock');
// ============================================================
/* REWRITTEN FOR update69. This section used to call `_tickInfections()`
   once per imaginary fight and count battles. Both clocks are seconds
   now and both run off the ship's own update, which is the only clock
   in the game that runs during a contract and stops at the dock. */
(function testVirusLifecycle() {
  const sb = loadEngine();
  const { Ship, Save, Game, VIRUS_SECONDS, EGG_SECONDS } = sb;
  const T = Game.__test;
  Save.load(); Save.startRun();

  ok(VIRUS_SECONDS >= 120 && EGG_SECONDS >= 120,
     `both clocks leave time to do something about them (${VIRUS_SECONDS}s / ${EGG_SECONDS}s)`);

  const ship = new Ship('hauler', true, 0, 0);
  sb.makeStartingCrew().forEach(c => ship.addCrew(c));
  T.playerShip = ship;
  const victim = ship.crew[0];
  const victimName = victim.name, victimRoom = victim.roomId;
  victim.virus = true; victim.virusT = VIRUS_SECONDS;
  const crewAtStart = ship.crew.length;

  // Halfway through: still on his feet, and the clock has moved.
  for (let i = 0; i < 200; i++) ship.update(0.5);          // 100 s
  ok(ship.crew.includes(victim), 'he is still aboard after a hundred seconds');
  ok(victim.virusT < VIRUS_SECONDS - 90,
     `and the clock really is running (${victim.virusT.toFixed(0)}s left)`);

  /* IT CAN TAKE HIM AT ANY MOMENT, not only after a victory. Nothing
     here wins a fight, resolves an event or docks — the hull is simply
     flying, which is the player's whole point: "aby to moglo sie stac
     w kazdym momencie walki". */
  for (let i = 0; i < 500; i++) ship.update(0.5);          // well past the end
  ok(!ship.crew.includes(victim), 'the virus takes him mid-flight');

  /* AND THERE IS NO BODY. He does not die on the floor and leave a
     case as well — one man, one thing left behind. */
  ok(!ship.crew.some(c => c.name === victimName),
     'he leaves no corpse lying in the room');
  ok(!ship.cargo.items.some(it => it.def.tag === 'body'),
     'and no body bag either — there is nothing of him to bag');
  ok(ship.crew.length === crewAtStart - 1, 'the roster is one hand shorter');

  const egg = ship.cargo.items.find(it => it.def.tag === 'egg');
  ok(!!egg, 'what is left is the egg case');
  ok(egg.meta && egg.meta.roomId === victimRoom,
     'lying in the room where he fell, so the ship can draw it there');
  ok(egg.meta.hatchT > 0, `with its own clock started (${egg.meta.hatchT?.toFixed?.(0)}s)`);

  /* THE MEMORIAL SAYS WHAT HAPPENED. Small note, on the record the
     graveyard already keeps — not a second list. */
  const stone = Save.getGraveyard().find(g => g.name === victimName);
  ok(!!stone, 'he is on the memorial');
  ok(/egg case/.test(String(stone.killer)),
     `and the stone says what became of him (${stone.killer})`);
  ok(!stone.buried, 'nobody brought him home — there was nothing to bring');

  // ── The case splits, in the room it was lying in ──
  const crewBefore = ship.crew.length;
  for (let i = 0; i < 100; i++) ship.update(0.5);          // 50 s
  ok(ship.cargo.items.includes(egg), 'it does not hatch early');

  /* STOP THE CLOCK THE MOMENT IT SPLITS, so what is counted is what
     came out of the case and not where it has crawled to since. */
  let split = false;
  for (let i = 0; i < 900 && !split; i++) {
    ship.update(0.5);
    split = !ship.cargo.items.includes(egg);
  }
  ok(split, 'then the case splits');
  const loose = ship.pests.filter(p => p.isSpider && !p.dead);
  ok(loose.length >= 1 && loose.length <= 3,
     `1-3 spiders are loose in the ducts (${loose.length})`);
  ok(ship.crew.length === crewBefore, 'and not one of them joined the crew list (update84)');
  ok(loose.every(sp => sp.roomId === victimRoom),
     'they come out in the duct the case was in, not in a random module');

  // A ship with nobody left but spiders is lost.
  ship.crew.filter(c => c.isPlayer).forEach(c => { c.dead = true; });
  ok(T._playerCrewAliveCount() === 0,
     'a ship with only spiders left aboard counts as lost');

  /* AND THE CLOCK IS THE SHIP'S. A hull that is not flying is not
     ageing anybody: the base never calls update(), which is why this
     is the only place the countdown lives. */
  {
    const docked = new Ship('hauler', true, 0, 0);
    sb.makeStartingCrew().forEach(c => docked.addCrew(c));
    const man = docked.crew[0];
    man.virus = true; man.virusT = 5;
    ok(man.virusT === 5, 'a bitten man sitting in the base still has five seconds on him');
    ok(!man.dead, 'and nothing ages him while nobody flies the ship');
  }
})();

