section('187. Their people get better the deeper you go');
// ============================================================
(function testEnemyCrewScales() {
  const sb = loadEngine();
  const { makeEnemyCrew, SKILL_DEFS } = sb;

  const total = (crew) => crew.reduce((a, c) =>
    a + Object.values(c.skills).reduce((b, sk) => b + sk.level, 0), 0);

  const early = makeEnemyCrew(12, 'enemy_frigate', 1);
  const mid   = makeEnemyCrew(12, 'enemy_frigate', 3);
  const late  = makeEnemyCrew(12, 'enemy_frigate', 6);

  ok(total(early) < total(mid), `sector 3 crews beat sector 1 (${total(early)} → ${total(mid)})`);
  ok(total(mid)   < total(late), `and sector 6 beats sector 3 (${total(mid)} → ${total(late)})`);

  /* A MASTERED HAND EXISTS OUT THERE. Their gunners feed the same
     accessors ours do, so 3/3 on the other side means their guns really
     do charge faster. */
  const mastered = late.some(c => Object.values(c.skills).some(sk => sk.level >= 3));
  ok(mastered, 'deep in, some of them have mastered their trade');
  ok(early.every(c => Object.values(c.skills).every(sk => sk.level <= 1)),
     'while a sector-1 picket is still all beginners');

  // And no boarding party of three men called Vega.
  const party = makeEnemyCrew(8, 'enemy_raider', 4);
  ok(new Set(party.map(c => c.name)).size === party.length,
     `one hull, no repeated names (${party.map(c => c.name).join(', ')})`);
})();

// ============================================================
section('188. A Terra hand is four boxes, not five');
// ============================================================
(function testTerraHp() {
  const sb = loadEngine();
  const { CrewMember, CORP_DEFS, Renderer } = sb;
  initRenderer(sb);

  const terra = new CrewMember({ isPlayer: true, race: 'terra' });
  const other = new CrewMember({ isPlayer: true, race: 'aquarius' });
  ok(terra.maxHp === 80, `a Terra cyborg has 80 hit points (${terra.maxHp})`);
  ok(other.maxHp === 100, `and everybody else still has 100 (${other.maxHp})`);
  ok(CORP_DEFS.terra.maxHp === 80,
     'and the number lives in CORP_DEFS with the rest of the corporation');

  // It reads as four boxes on the very drawer the panels use.
  const ctx = Renderer.getCtx();
  function pips(c) {
    const out = [];
    const real = ctx.fillRect;
    ctx.fillRect = (x, y, w, h) => out.push(ctx.fillStyle);
    try { Renderer.drawPips(ctx, 0, 0, 100, 6, c.hp, c.maxHp, '#1aff8c'); }
    finally { ctx.fillRect = real; }
    return out;
  }
  ok(pips(terra).length === 4, `four boxes (${pips(terra).length})`);
  ok(pips(other).length === 5, `against five for the rest (${pips(other).length})`);

  /* update87 turned this round, at the player's ask: a Terra hand saved
     on 100 was saved on the WRONG frame (a random roll read the empty
     config — see the constructor) and comes back on 80. What an explicit
     maxHp still decides is the commander's bonus ON the right frame. */
  const veteran = new CrewMember({ isPlayer: true, race: 'terra', maxHp: 100, hp: 90 });
  ok(veteran.maxHp === 80 && veteran.hp === 80,
     `a Terra hand saved on 100 comes back on his 80 (${veteran.hp}/${veteran.maxHp})`);
  const boosted = new CrewMember({ isPlayer: true, race: 'terra', maxHp: 82, hp: 70, baseMaxHp: 80 });
  ok(boosted.maxHp === 82 && boosted.hp === 70, 'a commander\'s bonus on the right frame is kept');
  const bonusOld = new CrewMember({ isPlayer: true, race: 'terra', maxHp: 102, hp: 101, baseMaxHp: 100 });
  ok(bonusOld.baseMaxHp === 80 && bonusOld.maxHp === 82,
     `and on a wrong frame it is kept as the same share (${bonusOld.maxHp})`);

  /* THE ROLL, NOT ONLY THE EXPLICIT RACE. The bug was the random pick:
     a starting crew rolls its corporations, and every Terra among them
     had a hundred. Fifty crews: not one Terra over eighty. */
  let wrong = 0, seen = 0;
  for (let i = 0; i < 50; i++) sb.makeStartingCrew().forEach(c => {
    if (c.race === 'terra') { seen++; if (c.maxHp !== 80) wrong++; }
  });
  ok(seen > 0 && wrong === 0, `a rolled Terra is on eighty too (${seen} rolled, ${wrong} wrong)`);
})();

// ============================================================
section('189. The barracks card: boxes, and RENAME clear of the skills');
// ============================================================
(function testBarracksCard() {
  const sb = loadEngine();
  const { Base, BaseScreen, Save } = sb;
  const ctx = initRenderer(sb);
  Save.load();
  Base.earn(9000);
  let g = 0;
  while (Base.crew().length < 2 && g++ < 20) Base.hireRecruit();
  ok(Base.crew().length >= 1, `there are hands in the barracks (${Base.crew().length})`);
  BaseScreen.open();
  BaseScreen._set({ tab: 'CREW' });

  /* THE CARD DRAWS HP AS BOXES, like every other crew readout since
     update54 — the barracks was the one screen left on a bar, so the
     same man read two different ways depending on the screen. */
  const rects = [];
  const realFillRect = ctx.fillRect;
  ctx.fillRect = (x, y, w, h) => rects.push({ x, y, w, h, fill: ctx.fillStyle });
  try { BaseScreen.draw(ctx); } finally { ctx.fillRect = realFillRect; }

  /* A pip row is several narrow boxes of the same height on one line;
     the old bar was ONE wide box. Look for the row. */
  const row = rects.filter(r => r.h === 7 && r.w < 20 && r.w > 2);
  ok(row.length >= 4, `the HP readout is a row of small boxes (${row.length})`);
  ok(!rects.some(r => r.h === 7 && r.w === 68),
     'and the old 68-pixel bar is not drawn any more');

  /* RENAME MUST NOT SIT ON THE SKILL PIPS. update54 put it at x+300,
     y+40 — straight through the second column of skills, which run to
     about x+301 and down to y+60. Read the button's real rectangle and
     the real skill pips out of the same draw. */
  const btn = BaseScreen._zonesFor('rename')[0];
  ok(!!btn, 'the card has a RENAME button');
  const skillPips = rects.filter(r => r.w === 11 && r.h === 10);     // update155: the file's skill boxes
  ok(skillPips.length > 0, `the skill pips are on the card (${skillPips.length})`);

  /* CLEARANCE, NOT MERE NON-OVERLAP. A button whose border sits one
     pixel off a row of pips reads as being on top of them, and the
     first version of this assertion — plain rectangle intersection —
     passed on exactly that layout. Four pixels is the gap the card uses
     everywhere else, so anything tighter is a collision. */
  const MARGIN = 4;
  const touches = (r) =>
    r.x - MARGIN < btn.x + btn.w && r.x + (r.w ?? 0) + MARGIN > btn.x &&
    r.y - MARGIN < btn.y + btn.h && r.y + (r.h ?? 0) + MARGIN > btn.y;
  const hitPips = skillPips.filter(touches);
  ok(hitPips.length === 0,
     `RENAME keeps clear of every skill pip (${hitPips.length} too close)`);

  /* AND OF THE WRITING. The pips are only half the crew info on that
     card — the skill labels, the HP figure and the condition line are
     text, and a button drawn over them is exactly what the player
     reported. Text is measured off the same draw. */
  const texts = [];
  const realFillText = ctx.fillText;
  ctx.fillText = (t, tx, ty) => {
    const w = (String(t).length) * 6;      // the harness measures this way
    texts.push({ t: String(t), x: tx, y: ty - 8, w, h: 10 });
  };
  try { BaseScreen.draw(ctx); } finally { ctx.fillText = realFillText; }
  const hitText = texts.filter(t => t.t !== 'RENAME' && touches(t));
  ok(hitText.length === 0,
     `and clear of the crew's own writing (${hitText.map(t => t.t).join(', ') || 'none'})`);
})();


// ============================================================
section('190. He-3 is a mineral, and the ship cannot burn it');
// ============================================================
(function testHe3IsNotFuel() {
  const sb = loadEngine();
  const { CARGO_ITEMS, CargoGrid, Ship, Save, cargoRollTable } = sb;
  Save.load(); Save.startRun();

  const def = CARGO_ITEMS.he3_ore;
  ok(!!def, 'He-3 ore exists as a cargo item');
  ok(def.kind !== 'fuel',
     `and it is NOT of kind fuel (${def.kind}) — He2 is the fuel, He-3 is the mineral`);
  ok(def.tag === 'he3', 'it carries the tag the Gate counts by');
  ok(def.stackMax > 1, `it stacks (${def.stackMax})`);
  ok(def.unitValue > 0, `and it is worth money (${def.unitValue} CC)`);

  /* THE WHOLE POINT: a hold full of ore does not fly you anywhere.
     The conditions are those in which He2 WOULD have counted — a real
     hold, a real stack, read through the real accessor. */
  const ship = new Ship('hauler', true, 0, 0);
  ship.cargo.addStack('he3_ore', 8);
  ok(ship.cargo.countOfTag('he3') === 8,
     `eight units are aboard (${ship.cargo.countOfTag('he3')})`);
  ok(ship.fuelCount() === 0,
     `and the tank still reads empty (${ship.fuelCount()})`);

  // …while He2 in the same hold does count, so this cannot pass by the
  // fuel accessor being broken.
  ship.cargo.addStack('he2_small', 5);
  ok(ship.fuelCount() === 5, `He2 in the same hold does count (${ship.fuelCount()})`);

  // It drifts out there, and commoner deeper in.
  const w = (sector) => (cargoRollTable(sector).find(([k]) => k === 'he3_ore') || [, 0])[1];
  ok(w(1) > 0, `wrecks can hold it from sector 1 (${w(1)})`);
  ok(w(6) > w(1), `and hold more of it deeper in (${w(1)} → ${w(6)})`);

  /* countOfTag must not be fooled by a damaged crate — a cracked box is
     not inventory you can spend, exactly like countOf. */
  const g = new CargoGrid(4, 4);
  const it = g.addStack ? (g.addStack('he3_ore', 3), g.items[0]) : null;
  ok(g.countOfTag('he3') === 3, 'three on a clean shelf');
  it.damaged = true;
  ok(g.countOfTag('he3') === 0, 'and none once the crate is cracked');
})();

// ============================================================
section('191. A port sells ore, and charges only for what fits');
// ============================================================
(function testHe3Trade() {
  const sb = loadEngine();
  const { Station, Ship, Save, CargoGrid } = sb;
  Save.load(); Save.startRun();
  const run = Save.getRun();

  /* PORTS REALLY STOCK IT. The rest of this section plants ore by hand
     so the buying rules can be exercised deterministically — which
     means nothing here would notice a generator that never rolls any.
     Twelve ports, and some of them carry ore. */
  {
    let carrying = 0;
    for (let seed = 0; seed < 12; seed++) {
      if ((new Station(3, seed).stock.he3 ?? 0) > 0) carrying++;
    }
    ok(carrying > 0, `ports stock He-3 (${carrying} of 12 had some)`);
  }

  const st = new Station(3, 7);
  st.stock.he3 = 5;
  ok(st.he3Cost() > 0, `ore has a price (${st.he3Cost()} CC)`);

  const ship = new Ship('hauler', true, 0, 0);
  run.scrap = 5000;
  const before = run.scrap;
  const r = st.buyHe3(3, run, ship);
  ok(r.ok, `three units bought (${r.message})`);
  ok(ship.cargo.countOfTag('he3') === 3, 'and they are in the hold');
  ok(Save.getRun().scrap === before - st.he3Cost(3), 'paid for exactly three');
  ok(st.stock.he3 === 2, `and the port has two left (${st.stock.he3})`);

  /* IT IS NOT FUEL, AT THE TILL EITHER. `run.fuel` must not move —
     that was the whole reason for keeping the two apart. */
  ok(Save.getRun().fuel === run.fuel, 'the fuel figure did not move');

  // A full hold refuses BEFORE any money changes hands.
  {
    const tiny = new Ship('scout', true, 0, 0);
    let guard = 0;
    while (tiny.cargo.add('plating') && guard++ < 60) { /* pack it solid */ }
    const cash = Save.getRun().scrap;
    const r2 = st.buyHe3(2, Save.getRun(), tiny);
    ok(!r2.ok, `a full hold is refused (${r2.message})`);
    ok(Save.getRun().scrap === cash, 'and nothing was charged');
    ok(st.stock.he3 === 2, 'and the port still has its ore');
  }

  // An empty port sells nothing.
  st.stock.he3 = 0;
  ok(!st.buyHe3(1, Save.getRun(), ship).ok, 'a port with no ore sells none');
})();

// ============================================================
section('192. The map has an address');
// ============================================================
(function testRegions() {
  const sb = loadEngine();
  const { Save } = sb;

  Save.load(); Save.startRun();
  ok(Save.getRun().region === 'luna', `a new run flies over Luna (${Save.getRun().region})`);
  ok(Save.currentRegion().label === 'LUNA', 'and the region table names it');
  ok(Save.unlockedRegions().includes('luna'), 'Luna is unlocked from the start');

  /* MIGRATION. A save written before update56 has no region at all —
     it must come back as Luna, because there has never been anywhere
     else, and it must not be re-written on the next load. */
  {
    /* THE KEY MATTERS. The first version of this wrote the doctored save
       to 'moonwars_save' — the real one is 'moonwars_save_v1' — so
       `load()` re-read the ORIGINAL record and the assertion passed
       without the migration ever running. The breaking pass caught it
       by reverting the migration and watching this sail through. */
    const KEY = 'moonwars_save_v1';
    const raw = JSON.parse(sb.localStorage.getItem(KEY));
    ok(!!raw && !!raw.run, 'the save on disk has a run in it');
    delete raw.run.region;
    delete raw.unlockedRegions;
    sb.localStorage.setItem(KEY, JSON.stringify(raw));
    // Prove the doctored record is really what load() will read.
    ok(JSON.parse(sb.localStorage.getItem(KEY)).run.region === undefined,
       'and the copy on disk now has no region at all');
    Save.load();
    ok(Save.getRun().region === 'luna', 'an old save is migrated to Luna on load');
    ok(Save.unlockedRegions().length === 1, 'and gets the unlocked list it never had');
  }

  // The map says so, in the title, above the sector.
  {
    const { Renderer, SectorMap } = sb;
    const ctx = initRenderer(sb);
    const map = new SectorMap(2, 1234);
    const seen = captureText(ctx, () => Renderer.drawMapScreen(map)).map(d => d.t);
    ok(seen.some(t => /LUNA/.test(t) && /SECTOR/.test(t)),
       `the map is headed with the moon and the sector (${seen.find(t => /SECTOR/.test(t))})`);
  }
})();

