section('194. A hull coming home always has a berth');
// ============================================================
(function testReturningHullDocks() {
  const sb = loadEngine();
  const { Base, Save } = sb;
  Save.load();

  /* THE LOSS. `storeShip` applied the hangar cap to a hull that had
     been CHECKED OUT of that very hangar — so a player who bought a
     second hull while the first was away came home to a full yard and
     lost the ship he was flying, with one line of notice for it. */
  Base.earn(9000);
  const slots = Base.shipSlots ? Base.shipSlots() : 2;
  let guard = 0;
  while (Base.get().ships.length < slots && guard++ < 10) Base.buyShip('hauler');
  ok(Base.get().ships.length >= slots,
     `the hangar is full (${Base.get().ships.length}/${slots})`);

  // Buying past the cap is still refused — the cap has not been deleted.
  const before = Base.get().ships.length;
  Base.buyShip('frigate');
  ok(Base.get().ships.length === before, 'buying another hull is still refused');

  // But a returning one docks.
  const rep = Base.returnFromRun({ shipEntry: { key: 'frigate', data: null }, crew: [], cc: 0 });
  ok(rep.shipStored, 'the hull that flew out comes home');
  ok(Base.get().ships.some(s => s.key === 'frigate'), 'and she is in the hangar');
})();


// ============================================================
section('195. The barracks list stops shuffling itself');
// ============================================================
(function testBarracksOrder() {
  const sb = loadEngine();
  const { Base, Save, Ship, CrewMember } = sb;
  Save.load();
  Base.earn(9000);
  let g = 0;
  while (Base.hireRecruit().ok && g++ < 20) { /* fill the bunks */ }

  const before = Base.crew().map(c => ({ id: c.id, name: c.name, race: c.race }));
  ok(before.length >= 4, `there is a roster (${before.length})`);

  /* THE COMPLAINT: "some crew change corporation, some vanish and
     others appear." Nobody changes and nobody vanishes — the LIST
     moves. A man who flies is spliced out at launch and pushed back on
     the END when he docks, so the cards (drawn in barracks order, each
     with a corporation colour) come back in a different order and read
     as different people. */
  const flying = before.slice(0, 3).map(c => c.id);
  const res = Base.launch({ shipIndex: 0, crewIds: flying, mission: 'patrol' });
  ok(res.ok, 'they fly out');

  const ship = res.ship.data ? Ship.deserialise(res.ship.data, true, 0, 0)
                             : new Ship(res.ship.key, true, 0, 0);
  res.crew.forEach(cd => ship.addCrew(CrewMember.deserialise(cd)));
  Base.returnFromRun({
    shipEntry: { key: res.ship.key, data: ship.serialise() },
    crew: ship.crew.filter(c => c.isPlayer && !c.dead && !c.isPet).map(c => c.serialise()),
    cc: 0,
  });

  const after = Base.crew().map(c => ({ id: c.id, name: c.name, race: c.race }));
  ok(after.length === before.length,
     `everybody is home (${before.length} → ${after.length})`);
  ok(after.map(c => c.id).join(',') === before.map(c => c.id).join(','),
     'and the roster is in exactly the order it was in before the contract');

  // Nobody's corporation or name moved either — the other half of the report.
  before.forEach((b, i) => {
    ok(after[i].race === b.race && after[i].name === b.name,
       `${b.name} is still ${b.race} and still called ${b.name}`);
  });

  /* A NEW HIRE GOES ON THE END and stays there across a contract —
     the ticket is taken once, not recomputed. */
  {
    const roomFor = Base.hireRecruit();
    if (roomFor.ok) {
      const list = Base.crew();
      ok(list[list.length - 1].id === roomFor.crew.id,
         'a fresh hand joins at the bottom of the list');
    } else {
      ok(true, 'barracks full — nothing to add (cap reached)');
    }
  }

  /* AN OLD SAVE does not reshuffle the moment this lands: records with
     no ticket are stamped in the order they are already sitting in. */
  {
    const raw = Base.get();
    const order = raw.barracks.map(c => c.id);
    raw.barracks.forEach(c => { delete c.joined; });
    delete raw.joinedSeq;
    ok(Base.crew().map(c => c.id).join(',') === order.join(','),
       'a pre-update57 barracks keeps the order it had');
  }

  /* AND A HALF-MIGRATED ONE DOES NOT ISSUE THE SAME TICKET TWICE.
     This is the case the breaking run found: a barracks where some
     records already carry a number and some do not. If the stamper
     hands out 0,1,2… without looking at what is already there, two men
     end up with the same ticket and the sort between them is decided by
     whatever order the array happens to be in — which is the very thing
     this whole section exists to stop. Duplicate tickets are the bug,
     so duplicates are what is asserted against. */
  {
    const raw = Base.get();
    const list = raw.barracks;
    ok(list.length >= 3, `enough hands to collide (${list.length})`);
    // The ones at the BOTTOM keep high numbers; the ones at the top
    // lose theirs, exactly like a save part-written by an older build.
    /* The numbers already on the record must be LOW ones — inside the
       range a fresh counter will hand out. Numbering them 50, 51, 52
       proves nothing: the counter starts at 0 and never reaches them,
       so it cannot collide. That was the first version of this, and the
       breaking run rightly slept through it. */
    list.forEach((c, i) => { if (i < 2) delete c.joined; else c.joined = i - 2; });
    delete raw.joinedSeq;
    const tickets = Base.crew().map(c => c.joined);
    ok(tickets.every(t => typeof t === 'number'), 'everybody ends up with a ticket');
    ok(new Set(tickets).size === tickets.length,
       `and no two of them share one (${tickets.join(', ')})`);
  }
})();

// ============================================================
section('196. CONTINUE lives in the base');
// ============================================================
(function testContinueMoved() {
  const sb = loadEngine();
  const { Save, BaseScreen, Base, Renderer } = sb;
  const ctx = initRenderer(sb);

  /* ── it is off the title screen ──
     MENU_ITEMS is a classic-script top-level const, so it never lands
     on `window` and the sandbox cannot see it — read it out of the
     source, the way the other structural sections do. It matters
     because game.js dispatches on the INDEX: if this list and the
     buttons the renderer draws ever disagree in LENGTH, a click runs
     the wrong action. */
  const fs2 = require('fs'), path2 = require('path');
  const gameSrc = fs2.readFileSync(path2.join(__dirname, '..', 'js', 'game.js'), 'utf8');
  const items = (gameSrc.match(/const MENU_ITEMS = \[([^\]]*)\]/) || [, ''])[1]
    .split(',').map(x => x.trim()).filter(Boolean);
  ok(items.length === 3 && /NEW GAME/.test(items[2]), `the menu has two doors and NEW GAME (update123) (${items.join(', ')})`);
  ok(!items.some(m => /CONTINUE/i.test(m)), 'and none of them is CONTINUE');

  // the title screen the game really draws is game.js _drawMenu
  const menu = captureText(ctx, () => sb.Game.__test._drawMenu(ctx)).map(d => d.t);
  ok(!menu.some(t => /^CONTINUE$/i.test(String(t).trim())),
     `the title screen does not draw it either (${menu.join(' | ')})`);
  ok(menu.filter(t => /^(ENTER BASE|OPTIONS|NEW GAME)$/.test(String(t))).length === 3,
     'the buttons it draws are the ones the dispatcher knows about');

  /* THE PREDICATE. `hasActiveRun` is true the moment a blank run record
     exists; what the base needs to know is whether a HULL is out there,
     which is what `shipKey` marks. Getting this wrong asks "are you
     sure" before the player's first flight of the session. */
  Save.load(); Save.startRun();
  ok(Save.hasActiveRun(), 'a run record exists');
  ok(!Save.hasShipInFlight(), 'but no hull has been checked out yet');
  Save.updateRun({ shipKey: 'scout' });
  ok(Save.hasShipInFlight(), 'once a contract takes a hull, one is out there');

  // ── and it is IN the base, only while there is something to go back to ──
  BaseScreen.open();
  BaseScreen.draw(ctx);
  ok(BaseScreen._zonesFor('continue').length === 1,
     'the base offers CONTINUE while a hull is out there');
  ok(BaseScreen._act('continue') === 'continue',
     'and pressing it asks game.js to resume the contract');

  Save.endRun(false);
  BaseScreen.open();
  BaseScreen.draw(ctx);
  ok(BaseScreen._zonesFor('continue').length === 0,
     'with nothing in the air the button is not there at all');
})();

// ============================================================
section('197. Launching over a live contract asks first');
// ============================================================
(function testLaunchWriteOff() {
  const sb = loadEngine();
  const { Save, BaseScreen, Base } = sb;
  const ctx = initRenderer(sb);
  Save.load();
  Base.earn(9000);
  /* A LAUNCH CHECKS THE HULL OUT of the hangar and it does not come
     back in this section, so each phase below needs one of its own.
     Without this the later presses fail with "Pick a ship first" and
     the section would be asserting nothing about the dialog at all. */
  const berth = () => { if (!Base.get().ships.length) Base.buyShip('hauler'); };

  // ── nothing in the air: LAUNCH just launches ──
  Save.startRun();
  berth();
  BaseScreen.open();
  ok(BaseScreen._act('launch') === 'launch',
     'with no hull out there the button launches straight away');
  ok(!BaseScreen._state().confirm, 'and asks nothing');
  ok(!!BaseScreen.consumeLaunch(), 'a loadout really came out of it');

  // ── a hull IS out there: it asks, and CANCEL means cancel ──
  Save.startRun();
  Save.updateRun({ shipKey: 'scout' });
  berth();
  BaseScreen.open();
  ok(!!Base.get().ships.length, 'test setup: there is a hull to launch');
  const r = BaseScreen._act('launch');
  ok(r !== 'launch', 'the press does not launch');
  ok(!BaseScreen.consumeLaunch(), 'no loadout was produced');
  const q = BaseScreen._state().confirm;
  ok(!!q, 'a question is raised instead');
  ok(/still out there/i.test(q.text), `and it says why: ${q.text}`);
  ok(/written off/i.test(q.detail || ''), 'and what it costs');

  BaseScreen._act('confirmNo');
  ok(!BaseScreen._state().confirm, 'CANCEL closes it');
  ok(!BaseScreen.consumeLaunch(), 'and still nothing has launched');

  // ── answering yes launches ──
  BaseScreen._act('launch');
  ok(BaseScreen._act('confirmYes') === 'launch', 'answering yes launches');
  ok(!!BaseScreen.consumeLaunch(), 'and produces the loadout');

  /* THE BUTTON SAYS SO BEFORE IT IS PRESSED. A dialog after the fact is
     better than nothing, but the warning belongs on the button. */
  Save.startRun();
  Save.updateRun({ shipKey: 'scout' });
  berth();
  BaseScreen.open();
  const t = captureText(ctx, () => BaseScreen.draw(ctx)).map(d => d.t);
  ok(t.some(x => /still out there/i.test(x)),
     `the LAUNCH button warns on its face (${t.filter(x => /out there|contract begins/i.test(x)).join(' | ')})`);
})();


// ============================================================
section('198. The ore you are carrying is on the screen');
// ============================================================
(function testHe3Readout() {
  const sb = loadEngine();
  const { Renderer, Ship, Save, SectorMap } = sb;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();

  const ship = new Ship('hauler', true, 80, 120);
  ship._allocateDefaultPower();

  /* THE COMPLAINT: "I do not see He-3 anywhere." It lived in the hold
     and nowhere else on screen, so a player could carry ten units and
     never know. It reads STRAIGHT OFF THE HOLD — the cells are the
     amount, like the He2 cells and the missile racks — so there is no
     second number that can drift. */
  const hud = () => captureText(ctx, () =>
    Renderer.drawHUD({ playerShip: ship })).map(d => d.t).join(' | ');

  ok(/He3 0/.test(hud()), `an empty hold still shows the readout (${hud()})`);
  ship.cargo.addStack('he3_ore', 7);
  ok(/He3 7/.test(hud()), 'and it follows the hold');
  ship.cargo.addStack('he3_ore', 3);
  ok(/He3 10/.test(hud()), 'all the way up');

  /* IT IS NOT THE FUEL FIGURE. He2 and He-3 are drawn side by side, and
     the whole point of update56 was that they are different things. */
  const line = hud();
  ok(/He2 /.test(line) && /He3 /.test(line), `both are on the strip (${line})`);
  ok(ship.fuelCount() === 0, 'and ten units of ore are still no fuel at all');

  /* IT HAS A PICTOGRAM, AND THE HUD REALLY DRAWS IT.
     The first version of this looked for `drawStatIcon(ctx, 'ore'` in
     the SOURCE — and passed with the HUD's icon deleted, because the
     MAP screen has a call too and the file still contained one. Read
     the canvas instead: capture what is actually filled during a HUD
     draw and look for the ore colour on a filled path, which only the
     pictogram produces (the text goes through fillText). */
  {
    const fills = [];
    const realFill = ctx.fill;
    ctx.fill = function () { fills.push(ctx.fillStyle); };
    try { Renderer.drawHUD({ playerShip: ship }); }
    finally { ctx.fill = realFill; }
    ok(fills.includes('#cfe4ff'),
       `the HUD fills the ore pictogram (${fills.filter(f => /cfe4ff|3d4a63/.test(f)).length} ore-coloured fills)`);

    const src = require('fs').readFileSync(
      require('path').join(__dirname, '..', 'js', 'renderer.js'), 'utf8');
    ok(/ore: \[\['poly'/.test(src),
       'and it is an ore shape of its own, not the warhead the missiles use');
  }

  // The map screen carries it too — that is where salvage detours are decided.
  {
    const map = new SectorMap(1, 99);
    const seen = captureText(ctx, () =>
      Renderer.drawMapScreen(map, null, ship.cargo)).map(d => d.t).join(' | ');
    ok(/He3 10/.test(seen), `the map shows the ore as well (${seen.slice(0, 120)})`);
  }
})();

// ============================================================
section('199. The Gate names the moons it opens');
// ============================================================
(function testDestinations() {
  const sb = loadEngine();
  const { Save, BaseScreen } = sb;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();

  const R = Save.regions();
  const all = Object.values(R);
  ok(all.length >= 4, `there is more than one moon in the table (${all.length})`);
  /* BY KEY, not by label. A moon whose key has been mangled is a moon
     no save can ever name — `unlockedRegions` and `run.region` both
     hold KEYS — and checking the pretty label misses that entirely,
     which is how the first version of this passed on a broken table. */
  ['luna', 'europa', 'titan'].forEach(k => {
    ok(!!R[k] && R[k].key === k,
       `${k} is in the table under its own key (${R[k] ? R[k].key : 'missing'})`);
  });
  ok(all.filter(r => r.locked).length >= 3,
     'and most of them are locked');
  ok(all.every(r => r.label && r.blurb), 'every one of them has a name and a line');

  /* ONLY LUNA IS OPEN, and the answer comes from the SAVE, not from the
     table — the day the Gate opens one, `unlockedRegions` is the single
     thing that changes. */
  ok(Save.regionUnlocked('luna'), 'Luna is open');
  ok(!Save.regionUnlocked('europa'), 'Europa is not');
  ok(Save.unlockedRegions().length === 1, 'exactly one moon is unlocked');

  // …and no contract can name a locked moon.
  ok(Save.getRun().region === 'luna', 'the contract in flight is on Luna');

  // The GATE screen lists them, with the locked ones marked as such.
  BaseScreen.open();
  BaseScreen._set({ tab: 'GATE' });
  const t = captureText(ctx, () => BaseScreen.draw(ctx)).map(d => d.t);
  ok(t.some(x => /DESTINATIONS/.test(x)), 'the Gate screen has a destinations list');
  ok(t.includes('LUNA') && t.includes('EUROPA') && t.includes('TITAN'),
     `and the moons are named on it (${t.filter(x => /^[A-Z]{3,}$/.test(x)).join(', ')})`);
  ok(t.some(x => /^open$/.test(x)), 'Luna is marked open');
  ok(t.filter(x => /^locked/.test(x)).length >= 3,
     `and the rest are marked locked (${t.filter(x => /^locked/.test(x)).length})`);

  /* THE CONTRACT PICKER SAYS WHERE THESE THREE JOBS ARE. Three jobs
     with no address read as "this is the whole game". */
  // (update113: the cards live on the DESTINATION screen, under the moon.)
  BaseScreen._set({ tab: 'HANGAR', screen: 'dest' });
  const t2 = captureText(ctx, () => BaseScreen.draw(ctx)).map(d => d.t);
  ok(t2.some(x => /LUNA · CONTRACTS/.test(x)),
     `the contracts are labelled with the moon (${t2.filter(x => /CONTRACT/i.test(x)).join(' | ')})`);
  ok(t2.some(x => /Moon Gate/i.test(x)), 'and say what opens the others');
})();


// ============================================================
section('200. A gun that will not fire says why');
// ============================================================
(function testDryGunSpeaks() {
  const sb = loadEngine();
  const { CombatManager, Weapon, Save, Renderer, UI } = sb;
  const c = makeCombat(sb);
  const ctx = initRenderer(sb);

  /* THE RUN THIS COST THE PLAYER. A Hull Cannon eats one missile a
     shot. When the racks ran dry `playerFire` simply `return`ed — no
     message, no mark on the card — so the gun sat there charged,
     powered and manned, and clicking an enemy room did NOTHING. Not for
     that fight: for every fight after it, because nothing told him the
     ammo was the problem. */
  ok(sb.WEAPON_DEFS.cannon_basic.missileUse === 1,
     'the Hull Cannon really does eat a missile a shot');

  c.player.cargo.clear();
  c.player.cargo.add('missile_rack', null, 2);
  Save.updateRun({ missiles: c.player.missileCount() });

  const gun = new Weapon('cannon_basic');
  c.player.weapons = [gun];
  /* THE CANNON DRAWS THREE. Its own weapons module has to be able to
     feed it, or `Weapon.update` clears `armed` on the first frame and
     this section would be testing an unpowered gun instead of a dry
     one — which is a different bug with a different message. This is
     the level-3 bay the player had actually built. */
  {
    const room = c.player.weaponRooms[0];
    room.system.level = Math.max(room.system.level, gun.powerCost);
    room.system.power = room.system.desiredPower = gun.powerCost;
    c.player._reallocWeaponPower();
    ok(gun.powered, `test setup: the bay feeds the cannon (${gun.power}/${gun.powerCost})`);
  }
  gun.armed = true;
  for (let i = 0; i < 40 && !CombatManager.isActive(); i++) CombatManager.update(0.05);

  // ── with rounds on board it fires and says nothing ──
  ok(CombatManager.fireRefusal(gun) === null, 'with warheads aboard there is no refusal');
  ok(CombatManager.playerFire(gun, c.enemy.rooms[0]) === null, 'and the shot goes out');
  ok(c.player.missileCount() === 1, `a round left the rack (${c.player.missileCount()})`);

  gun.armed = true;
  CombatManager.playerFire(gun, c.enemy.rooms[0]);
  ok(c.player.missileCount() === 0, 'and the last one after that');

  // ── empty: it REFUSES, and the refusal names the gun and the reason ──
  gun.armed = true;
  const why = CombatManager.fireRefusal(gun);
  ok(!!why, 'an empty rack is a refusal, not a silence');
  ok(/ammo/i.test(why) && /Hull Cannon/.test(why),
     `and it names the gun and what is missing: "${why}"`);

  const shotsBefore = CombatManager._projectiles.length;
  const said = CombatManager.playerFire(gun, c.enemy.rooms[0]);
  ok(said === why, 'playerFire hands back the same words');
  ok(CombatManager._projectiles.length === shotsBefore, 'and nothing was fired');
  ok(gun.armed, 'the gun keeps its charge — it was never spent');

  /* A CHARGING GUN IS A DIFFERENT REFUSAL, so "it says why" cannot pass
     by always saying the same thing. */
  gun.armed = false;
  const why2 = CombatManager.fireRefusal(gun);
  ok(!!why2 && why2 !== why, `a charging gun refuses differently ("${why2}")`);
  ok(/charging/i.test(why2), 'and says it is still charging');

  /* AN UNMANNED BAY IS *NOT* A REFUSAL. Leaving the console freezes
     CHARGING; a shell already in the breech still goes out. Checking it
     would invent a rule the rest of the engine does not have. */
  gun.armed = true;
  gun.unmanned = true;
  c.player.cargo.add('missile_rack', null, 1);
  ok(CombatManager.fireRefusal(gun) === null,
     'an armed gun in an empty bay still fires');
  gun.unmanned = false;

  /* AND THE CARD SAYS SO BEFORE THE PLAYER CLICKS. A message after the
     click is better than nothing, but the state belongs on the gun. */
  {
    c.player.cargo.clear();
    Save.updateRun({ missiles: 0 });
    gun.armed = true;
    const seen = captureText(ctx, () =>
      Renderer.drawHUD({ playerShip: c.player, enemyShip: c.enemy })).map(d => d.t);
    ok(seen.some(t => /NO AMMO/.test(t)),
       `the weapon card is marked NO AMMO (${seen.filter(t => /·/.test(t)).join(' | ')})`);

    c.player.cargo.add('missile_rack', null, 3);
    Save.updateRun({ missiles: 3 });
    const seen2 = captureText(ctx, () =>
      Renderer.drawHUD({ playerShip: c.player, enemyShip: c.enemy })).map(d => d.t);
    ok(!seen2.some(t => /NO AMMO/.test(t)), 'and the mark goes away when the racks are filled');
    ok(seen2.some(t => /Hull Cannon/.test(t)), 'the card names the gun again');
  }

  /* AND THE REAL CLICK CARRIES IT TO THE PLAYER (update59).
     Everything above talks to `playerFire` directly — which proves the
     rule but NOT the wiring, and the wiring is the whole complaint: the
     player clicked an enemy room and nothing happened. Go through the
     press path and watch what UI.notify is handed. The breaking run
     caught this section without it. */
  {
    c.player.cargo.clear();
    Save.updateRun({ missiles: 0 });
    c.player.weapons = [gun];
    gun.armed = true;

    /* Keep the DERELICT HULK offer off the screen: this section strips
       the enemy down, and an enemy with nobody left standing raises that
       popup, which makes `_updateCombat` return before it ever reaches
       the weapon hotkeys. The first version of this test hit exactly
       that and reported "nothing was said" for the wrong reason. */
    c.T.derelictOffered = true;
    c.T.STATE = 'combat';

    const said = [];
    const realNotify = UI.notify;
    UI.notify = (msg) => { said.push(String(msg)); };

    const room = c.enemy.rooms[0];
    try {
      // Select the gun the way the hotkey does, then click the room.
      sb.Input.isPressed = (code) => code === 'Digit1';
      c.T._updateCombat(0.016);
      sb.Input.isPressed = () => false;
      sb.Input.mouse.x = room.cx; sb.Input.mouse.y = room.cy;
      sb.Input.mouse.leftPressed = true;
      c.T._updateCombat(0.016);
      sb.Input.mouse.leftPressed = false;
    } finally {
      UI.notify = realNotify;
    }
    ok(c.T.STATE === 'combat', `test setup: still in the fight (${c.T.STATE})`);
    ok(said.some(m => /click enemy room/i.test(m)),
       'test setup: the hotkey really selected the gun');

    ok(said.some(m => /ammo/i.test(m)),
       `clicking a room with an empty rack SAYS so (${said.join(' | ') || 'nothing was said'})`);
  }

  /* AND THE SAME FOR A GUN THAT CANNOT EVEN BE SELECTED. Pressing the
     number of a gun that is not ready did nothing at all — no message,
     no sound — which is the identical dead click one step earlier. A
     Hull Cannon whose level-3 bay has been shot down to two power lands
     here, and from outside it looks exactly like the ammo bug. */
  {
    c.player.weapons = [gun];
    c.player.cargo.clear();
    c.player.cargo.add('missile_rack', null, 5);
    gun.armed = false;              // still charging
    c.T.derelictOffered = true;
    c.T.STATE = 'combat';

    const said = [];
    const realNotify = UI.notify;
    UI.notify = (msg) => { said.push(String(msg)); };
    try {
      sb.Input.isPressed = (code) => code === 'Digit1';
      c.T._updateCombat(0.016);
      sb.Input.isPressed = () => false;
    } finally { UI.notify = realNotify; }

    ok(said.some(m => /charging/i.test(m)),
       `pressing the number of an unready gun says why (${said.join(' | ') || 'nothing'})`);
  }

  /* A GUN THAT NEEDS NO AMMO IS NEVER MARKED — otherwise every laser
     on the ship would read NO AMMO the moment the warheads ran out. */
  {
    const laser = new Weapon('laser_basic');
    laser.armed = true;
    c.player.weapons = [laser];
    c.player.cargo.clear();
    Save.updateRun({ missiles: 0 });
    ok(CombatManager.fireRefusal(laser) === null, 'a laser fires with no warheads at all');
    const seen3 = captureText(ctx, () =>
      Renderer.drawHUD({ playerShip: c.player, enemyShip: c.enemy })).map(d => d.t);
    ok(!seen3.some(t => /NO AMMO/.test(t)), 'and its card is not marked');
  }
  c.T.enemyShip = null;
})();


// ============================================================
section('201. A gun remembers its bay, not its place in a list');
// ============================================================
(function testGunKnowsItsBay() {
  const sb = loadEngine();
  const { Ship, Save, CrewMember, CombatManager } = sb;
  Save.load(); Save.startRun();

  /* THE TRAP, BUILT BY HAND. `weaponRooms` is `rooms.filter(type ===
     'weapons')`, rebuilt on every read, and a gun used to find its
     module by POSITION in that list. Put a new bay in a room that sorts
     EARLIER than an existing one and every gun aboard silently starts
     drawing power and crew from somebody else's module.

     No shipped hull can do it today — none has an empty room before its
     weapons bay, and that is asserted below so this section keeps
     meaning something. The trap is built here deliberately, because a
     bug that needs a future layout to appear is still a bug. */
  ['scout', 'hauler', 'frigate'].forEach(key => {
    const sh = new Ship(key, true, 0, 0);
    const wIdx = sh.rooms.findIndex(r => r.type === 'weapons');
    const early = sh.rooms.findIndex((r, i) => r.type === 'empty' && i < wIdx);
    ok(early === -1, `${key} has no empty room before its weapons bay today`);
  });

  const sh = new Ship('hauler', true, 0, 0);
  sh._allocateDefaultPower();
  const gun = sh.weapons[0];
  ok(!!gun, 'the hull comes with a gun');
  ok(gun.roomId === sh.weaponRooms[0].id,
     `and the gun knows which bay it is in (${gun.roomId})`);

  // Re-order the room table so an empty room sorts first, then build a
  // bay in it — the layout the pairing could not survive.
  const empty = sh.rooms.find(r => r.type === 'empty');
  sh.rooms = [empty, ...sh.rooms.filter(r => r !== empty)];
  const oldBay = gun.roomId;
  ok(sh.addModuleAt('weapons', empty.id), 'a second bay goes in, in FRONT of the first');

  ok(sh.weaponRooms[0].id === empty.id,
     'the positional rule now points slot 0 at the NEW bay…');
  ok(sh.weaponRoomFor(gun).id === oldBay,
     `…but the gun still answers with its own (${sh.weaponRoomFor(gun).id})`);

  /* AND IT IS THE POWER AND THE CREW THAT MATTER, not just the id.
     The new bay is unpowered (addModule leaves it so), which is exactly
     what made this fatal: the gun would have gone dark. */
  const newBay = sh.getRoomById(empty.id);
  newBay.system.power = 0; newBay.system.desiredPower = 0;
  const oldRoom = sh.getRoomById(oldBay);
  oldRoom.system.power = oldRoom.system.desiredPower = Math.max(1, gun.powerCost);
  oldRoom.system.level = Math.max(oldRoom.system.level, gun.powerCost);
  sh._reallocWeaponPower();
  ok(gun.powered, `the gun still has power from its own bay (${gun.power}/${gun.powerCost})`);

  // The gunner counts from the right bay too.
  {
    const hand = new CrewMember({ isPlayer: true, race: 'terra', name: 'Gunner' });
    sh.addCrew(hand);
    hand.roomId = oldBay; hand.x = oldRoom.cx; hand.y = oldRoom.cy;
    for (let i = 0; i < 10; i++) { sh.crew.forEach(c => c._waypoints = []); sh.update(0.05); }
    ok(!gun.unmanned, 'a hand in the bay the gun is bolted into mans it');

    hand.roomId = empty.id; hand.x = newBay.cx; hand.y = newBay.cy;
    for (let i = 0; i < 10; i++) { sh.crew.forEach(c => c._waypoints = []); sh.update(0.05); }
    ok(gun.unmanned, 'and standing in the OTHER bay does not');
  }

  /* IT SURVIVES A SAVE, and a save from BEFORE this change still loads:
     no roomId in the record means the positional rule, which is what
     that save meant when it was written. */
  {
    const data = sh.serialise();
    const w0 = data.weapons.find(Boolean);
    ok(w0.roomId === oldBay, 'the bay is written into the save');

    const back = Ship.deserialise(data, true, 0, 0);
    ok(back.weapons[0].roomId === oldBay, 'and comes back with the hull');

    const legacy = JSON.parse(JSON.stringify(data));
    legacy.weapons.forEach(w => { if (w) delete w.roomId; });
    const old = Ship.deserialise(legacy, true, 0, 0);
    ok(!!old.weapons[0].roomId,
       'a pre-update60 save still ends up with a bay on every gun');
    ok(old.weapons[0].roomId === old.weaponRooms[0].id,
       'and it is the positional one, which is what that save meant');

    /* AND A SAVED BAY THAT DISAGREES WITH THE POSITION WINS.
       Every case above happens to have the saved bay and the positional
       one pointing at the same room, so none of them would notice the
       loader throwing the saved value away — the breaking run caught
       exactly that. Build a hull where they DIFFER: a gun in slot 0
       bolted into the SECOND bay, which is what a refit at a station
       leaves behind. */
    const two = new Ship('hauler', true, 0, 0);
    two._allocateDefaultPower();
    ok(two.addModule('weapons'), 'a second bay for the refit');
    const bay2 = two.weaponRooms[1];
    ok(!!bay2 && bay2.id !== two.weaponRooms[0].id, 'and it is a different room');
    two.weapons[0].roomId = bay2.id;          // the refit
    const refit = Ship.deserialise(two.serialise(), true, 0, 0);
    ok(refit.weapons[0].roomId === bay2.id,
       `the saved bay survives and beats the position (${refit.weapons[0].roomId} vs ${refit.weaponRooms[0].id})`);
    ok(refit.weaponRoomFor(refit.weapons[0]).id === bay2.id,
       'and the gun answers with it after loading');
  }

  /* THE BOSS HULLS mount more guns than they have bays; those overflow
     guns have no room of their own and must still work. */
  {
    /* Build the overflow by hand rather than trusting a layout to have
       it: mount more guns than there are bays, which is what the boss
       hulls do, and check nothing throws and the leftover power rule
       still feeds them. */
    const over = new Ship('scout', true, 0, 0);
    over._allocateDefaultPower();
    const bays = over.weaponRooms.length;
    over.weaponSlots = bays + 2;
    over.installWeapon('laser_basic', bays);       // no bay of its own
    const orphan = over.weapons[bays];
    ok(!!orphan, `a gun sits in a slot with no bay (slot ${bays})`);
    ok(over.weaponRoomFor(orphan) === null,
       'and it honestly answers that it has no room');
    over._reallocWeaponPower();
    ok(typeof orphan.power === 'number',
       `the shared-power rule still feeds it (${orphan.power}/${orphan.powerCost})`);
    for (let i = 0; i < 5; i++) over.update(0.05);
    ok(true, 'and a frame runs on a hull like that without throwing');
  }
})();


// ============================================================
section('202. Karma bands: a surcharge at the bottom, never a discount');
// ============================================================
(function testKarmaBands() {
  const sb = loadEngine();
  const { Commander, Save } = sb;
  Save.load();

  const cap = Commander.fromCrew({ id: 'k1', name: 'Rook', race: 'terra', skills: {} });
  Commander.setActive(cap);
  const at = (k) => { cap.karma = k; return Commander.priceFactor(); };

  ok(at(0)   === 1.25, 'karma 0 pays a quarter over the odds');
  ok(at(20)  === 1.25, 'and so does karma 20 — the band runs to its edge');
  ok(at(21)  === 1.10, 'karma 21 steps down to a tenth over');
  ok(at(35)  === 1.10, 'and 35 is still in that band');
  ok(at(36)  === 1,    'karma 36 pays the going rate');
  ok(at(50)  === 1,    'so does the starting karma');

  /* THE WHOLE POINT OF VARIANT B: no discount, ever. A saint pays
     exactly what an average commander pays, and buys his reward in
     people and in chips instead. */
  let discounted = 0;
  for (let k = 36; k <= 100; k++) if (at(k) < 1) discounted++;
  ok(discounted === 0, `no karma anywhere buys a cheaper port (${discounted} did)`);

  ok(at(10) === 1.25 && Commander.reputationLabel(10) === 'NOTORIOUS',
     'the bottom band has a name the player can read');
  ok(Commander.reputationLabel(30) === 'DISTRUSTED', 'so does the middle-low one');
  ok(Commander.reputationLabel(50) === null,
     'and an unremarkable commander gets no label at all');

  // Out-of-range and missing karma must not produce a NaN price.
  /* THE CLAMP IS THE ONLY GUARD (update61). `band()` has no fallback
     branch on purpose, so a corrupt karma that gets past the clamp
     throws here rather than being priced at par by a dead safety net.
     Asserting on karmaNow AND on the price: the first says the clamp
     ran, the second says nothing downstream fell over. */
  cap.karma = 999;
  ok(Commander.karmaNow() === 100, `karma above 100 clamps (${Commander.karmaNow()})`);
  ok(Commander.priceFactor() === 1, 'and prices at par instead of throwing');
  cap.karma = -50;
  ok(Commander.karmaNow() === 0, `karma below 0 clamps too (${Commander.karmaNow()})`);
  ok(Commander.priceFactor() === 1.25, 'and is charged the full surcharge');
  delete cap.karma; ok(Commander.priceFactor() === 1, 'a record with no karma reads as average');
  Commander.setActive(null);
  ok(Commander.priceFactor() === 1, 'and no commander at all is par, not a crash');
})();

// ============================================================
section('203. The port charges what the commander is worth');
// ============================================================
(function testPortPrices() {
  const sb = loadEngine();
  const { Commander, Station, Ship, Save } = sb;
  Save.load(); Save.startRun();

  const cap = Commander.fromCrew({ id: 'k2', name: 'Vane', race: 'terra', skills: {} });
  Commander.setActive(cap);

  // A station whose seed does NOT refuse, so price is the only variable.
  let seedOpen = 1;
  for (let s = 0; s < 30; s++) if (!Commander.portRefuses(s, 0)) { seedOpen = s; break; }
  ok(!Commander.portRefuses(seedOpen, 0), `seed ${seedOpen} trades with anybody`);

  cap.karma = 50;
  const st  = new Station(3, seedOpen);
  const par = { fuel: st.fuelCost(10), miss: st.missileCost(10),
                hull: st.hullRepairCost(10), he3: st.he3Cost(10) };
  ok(par.fuel > 0 && par.miss > 0 && par.hull > 0 && par.he3 > 0,
     `par prices are real numbers (${par.fuel}/${par.miss}/${par.hull}/${par.he3} CC)`);

  cap.karma = 5;
  ok(st.fuelCost(10)       > par.fuel, `He2 costs more (${st.fuelCost(10)} > ${par.fuel})`);
  ok(st.missileCost(10)    > par.miss, `missiles cost more (${st.missileCost(10)} > ${par.miss})`);
  ok(st.hullRepairCost(10) > par.hull, `plating costs more (${st.hullRepairCost(10)} > ${par.hull})`);
  ok(st.he3Cost(10)        > par.he3,  `ore costs more (${st.he3Cost(10)} > ${par.he3})`);

  cap.karma = 90;
  ok(st.fuelCost(10) === par.fuel && st.hullRepairCost(10) === par.hull,
     'and a saint pays exactly the same as an average commander');

  /* THE TILL AGREES WITH THE SHELF. This is the bug the one-register
     rule exists to prevent: a label saying one price and a purchase
     taking another. `buyFuel` used to do its own multiplication. */
  cap.karma = 5;
  const ship = new Ship('hauler', true, 0, 0);
  Save.updateRun({ scrap: 5000 });
  st.stock.fuel = 10;
  const quote = st.fuelCost(4);
  const buy   = st.buyFuel(4, Save.getRun(), ship);
  ok(buy.ok, `bought four cells of He2 (${buy.message})`);
  ok(buy.cost === quote,
     `and was charged the quoted price, not a second sum (${buy.cost} vs ${quote})`);

  cap.karma = 50;
  const parQuote = st.fuelCost(4);
  ok(quote > parQuote,
     `the sum charged really carried the surcharge (${quote} vs ${parQuote} at par)`);

  Commander.setActive(null);
})();

// ============================================================
section('204. A shunned commander finds some docks shut — and is told why');
// ============================================================
(function testPortRefusal() {
  const sb = loadEngine();
  const { Commander, Station, Ship, Save } = sb;
  Save.load(); Save.startRun();

  const cap = Commander.fromCrew({ id: 'k3', name: 'Crow', race: 'terra', skills: {} });
  Commander.setActive(cap);

  cap.karma = 50;
  let closedAtPar = 0;
  for (let s = 0; s < 40; s++) if (Commander.portRefuses(s)) closedAtPar++;
  ok(closedAtPar === 0, `an ordinary commander is turned away nowhere (${closedAtPar})`);

  cap.karma = 5;
  let closed = 0;
  for (let s = 0; s < 40; s++) if (Commander.portRefuses(s)) closed++;
  ok(closed > 0,   `a shunned one is turned away somewhere (${closed} of 40)`);
  ok(closed < 40,  'but NEVER everywhere — that would strand the run with no fuel to buy');
  ok(closed <= 20, `and only a small share of ports (${closed} of 40)`);

  /* THE SAME THIRD, EVERY TIME. A port that refuses must still refuse
     when you come back, or re-docking becomes a slot machine the
     player simply spams until it pays out. */
  const first = [];
  for (let s = 0; s < 40; s++) first.push(Commander.portRefuses(s));
  let same = true;
  for (let s = 0; s < 40; s++) if (Commander.portRefuses(s) !== first[s]) same = false;
  ok(same, 'and the answer for a given port never changes between visits');

  // A refused station says so, and every till on it is shut.
  let shutSeed = 0;
  for (let s = 0; s < 40; s++) if (Commander.portRefuses(s)) { shutSeed = s; break; }
  const shut = new Station(3, shutSeed);
  const why  = shut.refusal();
  ok(typeof why === 'string' && why.length > 10, `the station has a reason on hand: "${why}"`);

  const ship = new Ship('hauler', true, 0, 0);
  Save.updateRun({ scrap: 5000 });
  shut.stock.fuel = 10; shut.stock.missiles = 10;
  shut.stock.he3 = 10;  shut.stock.hullRepair = 10;
  ship.hull = 1;
  const before = Save.getRun().scrap;
  const tries = [
    shut.buyFuel(1, Save.getRun(), ship),
    shut.buyMissiles(1, Save.getRun(), ship),
    shut.buyHe3(1, Save.getRun(), ship),
    shut.buyHullRepair(1, ship),
    shut.buyReactorUpgrade(ship, Save.getRun()),
  ];
  ok(tries.every(r => !r.ok), 'nothing at all can be bought at a shut dock');
  ok(tries.every(r => r.message === why), 'and every refusal gives the SAME visible reason');
  ok(Save.getRun().scrap === before, 'and not one CC moved');

  // An open dock in the same state still sells — the run goes on.
  let openSeed = 1;
  for (let s = 0; s < 40; s++) if (!Commander.portRefuses(s)) { openSeed = s; break; }
  const open = new Station(3, openSeed);
  open.stock.fuel = 10;
  ok(open.refusal() === null, 'a port that will deal with him has no reason to show');
  ok(open.buyFuel(1, Save.getRun(), new Ship('hauler', true, 0, 0)).ok,
     'and it sells him fuel — the run is not stranded');

  // Good karma reopens the same dock. The wall is the man, not the port.
  cap.karma = 80;
  ok(new Station(3, shutSeed).refusal() === null,
     'and the dock that shut him out serves a commander with a better name');

  cap.karma = 50;
  Commander.setActive(null);
})();

// ============================================================
section('205. The barracks price a bad name in, and a good one out');
// ============================================================
(function testRecruits() {
  const sb = loadEngine();
  const { Commander, Base, Station, Save } = sb;
  Save.load();

  const cap = Commander.fromCrew({ id: 'k4', name: 'Dane', race: 'terra', skills: {} });
  Commander.setActive(cap);

  cap.karma = 50; const par  = Base.recruitPrice();
  ok(par === Base.PRICE.recruit, `an average name pays the list price (${par} CC)`);
  cap.karma = 5;  const bad  = Base.recruitPrice();
  cap.karma = 30; const mid  = Base.recruitPrice();
  cap.karma = 90; const good = Base.recruitPrice();
  ok(bad > mid && mid > par, `a bad name pays more (${bad} > ${mid} > ${par})`);
  ok(good < par, `and a good one pays less (${good} < ${par}) — this is where karma DOES pay`);

  /* THE BUTTON AND THE TILL. `PRICE.recruit` is still the only stored
     number; if hireRecruit went back to reading it raw, this catches
     it, because at karma 5 the two differ by 27 CC. */
  const b = Base.get();
  b.barracks.length = 0;
  cap.karma = 5;
  const fee = Base.recruitPrice();
  Base.spend(Base.cc());
  Base.earn(fee - 1);
  const poor = Base.hireRecruit();
  ok(!poor.ok, `${fee - 1} CC is not enough when the fee is ${fee} (${poor.message})`);
  ok(poor.message.includes(String(fee)),
     'and the refusal quotes the karma fee, not the list price');

  Base.earn(1);
  const hired = Base.hireRecruit();
  ok(hired.ok, `${fee} CC is exactly enough (${hired.message})`);
  ok(Base.cc() === 0, `and it took the whole karma fee (${Base.cc()} CC left)`);

  // Fewer hands are even interested at the bottom of the scale.
  const count = (k) => {
    cap.karma = k;
    let n = 0;
    for (let s = 0; s < 30; s++) n += new Station(3, s).stock.crew.length;
    return n;
  };
  const lo = count(5), avg = count(50), hi = count(90);
  ok(hi > avg && avg > lo,
     `berths on offer follow the name (${lo} shunned < ${avg} average < ${hi} decent)`);
  ok(lo >= 0, 'and the roll never goes negative');

  // A station's signing fee follows the same lever as the barracks.
  cap.karma = 5;  const stBad  = new Station(3, 1).crewCost();
  cap.karma = 90; const stGood = new Station(3, 1).crewCost();
  ok(stBad > stGood, `a hand at a port costs more too (${stBad} > ${stGood})`);

  cap.karma = 50;
  Commander.setActive(null);
})();

// ============================================================
section('206. The dossier tells him what his karma actually costs');
// ============================================================
(function testKarmaWords() {
  const sb = loadEngine();
  const { Commander, Renderer, Base, Save } = sb;
  Save.load();

  const cap = Commander.fromCrew({ id: 'k5', name: 'Sel', race: 'terra', skills: {} });
  Commander.setActive(cap);

  const lines = (k) => Commander.karmaWorldLines(k).join(' | ');
  ok(/\+25%/.test(lines(5)),  `the notorious are told the figure: ${lines(5)}`);
  ok(/not trade/.test(lines(5)), 'and that some docks are shut to them');
  ok(/\+10%/.test(lines(30)), `the distrusted get theirs too: ${lines(30)}`);
  ok(!/not trade/.test(lines(30)),
     'but nobody refuses them — the line is not shown where it is not true');
  ok(!/\+/.test(lines(50)) && !/less/.test(lines(50)),
     `an average commander is told plainly that nothing is odd: ${lines(50)}`);
  ok(/less/.test(lines(90)), `and a decent one is told what it buys: ${lines(90)}`);

  /* AND WHAT IT DOES IN A FIGHT (update62). The dossier is the only
     place the surrender odds are ever shown; without this line a
     player has no way to learn that his name is why nobody strikes. */
  ok(/never surrender/.test(lines(5)),
     `a butcher is told nobody will strike to him: ${lines(5)}`);
  ok(/50%/.test(lines(50)), `an ordinary one is given the figure: ${lines(50)}`);
  ok(/75%/.test(lines(90)), 'and a decent one sees his is better');
  ok(!/never surrender/.test(lines(50)),
     'and the no-quarter line is not shown to somebody it is not true of');

  /* THE CARD REALLY DRAWS THEM. A wording function nobody calls is
     worth nothing, so this reads the dossier's own text rather than
     trusting the helper it is supposed to be printing. */
  const ctx = initRenderer(sb);
  const b = Base.get();
  b.messLvl = 1; b.commanders = [cap];
  cap.karma = 5;
  const drawn = captureText(ctx, () => Renderer.drawCommanderDossier(ctx, cap)).map(o => o.t);
  ok(drawn.some(t => /\+25%/.test(t)),
     `the dossier prints the surcharge (${drawn.filter(t => /%/.test(t)).join(' / ')})`);
  ok(drawn.some(t => /not trade/.test(t)), 'and the warning about shut docks');

  cap.karma = 90;
  const kind = captureText(ctx, () => Renderer.drawCommanderDossier(ctx, cap)).map(o => o.t);
  ok(kind.some(t => /less/.test(t)), 'and the good news for a commander who earned it');
  ok(!kind.some(t => /not trade/.test(t)), 'with no shut-dock warning he has not earned');

  cap.karma = 50;
  Commander.setActive(null);
})();


// ============================================================
section('207. Nobody strikes their colours to a butcher');
// ============================================================
(function testSurrenderOdds() {
  const sb = loadEngine();
  const { Commander, Save } = sb;
  Save.load();

  const cap = Commander.fromCrew({ id: 's1', name: 'Kade', race: 'terra', skills: {} });
  Commander.setActive(cap);
  const at = (k) => { cap.karma = k; return Commander.surrenderChance(); };

  ok(at(50) === 0.5,  'an ordinary commander sees the odds the game always had');
  ok(at(5)  === 0,    'a notorious one is never offered a surrender at all');
  ok(at(10) === 0,    'and the shunned band runs to its edge');
  ok(at(11) > 0,      `one point above it, mercy exists again (${at(11)})`);
  ok(at(30) === 0.25, 'a distrusted commander is offered fewer');
  ok(at(90) === 0.75, 'and a decent one more');

  /* MONOTONIC. A scale where being kinder made surrenders rarer
     somewhere in the middle would be unreadable to the player, and no
     single assertion above would notice it. */
  let dips = 0, prev = at(0);
  for (let k = 1; k <= 100; k++) { const v = at(k); if (v < prev) dips++; prev = v; }
  ok(dips === 0, `the odds never fall as karma rises (${dips} dips)`);

  // No commander in the chair is the old flat roll, not a crash.
  Commander.setActive(null);
  ok(Commander.surrenderChance() === 0.5, 'with nobody in the chair it is the old 0.5');

  // …and the fight asks that same question rather than keeping its own.
  const c = makeCombat(sb);
  ok(sb.CombatManager.surrenderOdds() === 0.5, 'the fight reads the commander, not a number of its own');
  ok(sb.CombatManager.noQuarter() === false, 'and nobody is refused quarter by default');
  Commander.setActive(cap); cap.karma = 5;
  ok(sb.CombatManager.surrenderOdds() === 0, 'a butcher gets no surrenders');
  ok(sb.CombatManager.noQuarter() === true, 'and the fight says so in one word');
  Commander.setActive(null);
})();

// ============================================================
section('208. A beaten hull rolls once, against the commander');
// ============================================================
(function testHullSurrender() {
  const sb = loadEngine();
  const { Commander, Save, CombatManager, UI } = sb;

  /* THE ROLL IS PINNED, so this tests the RULE and not the RNG. */
  const withRandom = (v, fn) => {
    const real = Math.random;
    Math.random = () => v;
    try { return fn(); } finally { Math.random = real; }
  };

  // A saint: the roll comes up under the odds and they strike.
  {
    const c = makeCombat(sb);
    const cap = Commander.fromCrew({ id: 's2', name: 'Ilma', race: 'terra', skills: {} });
    cap.karma = 90; Commander.setActive(cap);
    c.enemy.hull = Math.round(c.enemy.hullMax * 0.2);
    withRandom(0.6, () => sb.CombatManager.update(0.05));
    ok(sb.CombatManager.surrenderOffer === true,
       'a roll of 0.6 is under a saint\'s 0.75 — they strike');
  }

  /* THE SAME ROLL, THE SAME DAMAGE, A WORSE NAME. If this passed too,
     the odds would be decoration. */
  {
    const c = makeCombat(sb);
    const cap = Commander.fromCrew({ id: 's3', name: 'Ryn', race: 'terra', skills: {} });
    cap.karma = 30; Commander.setActive(cap);
    c.enemy.hull = Math.round(c.enemy.hullMax * 0.2);
    withRandom(0.6, () => sb.CombatManager.update(0.05));
    ok(sb.CombatManager.surrenderOffer === false,
       'the same roll is over a distrusted commander\'s 0.25 — they fight on');
  }

  // ONE ROLL PER FIGHT, however many frames run at a beaten hull.
  {
    const c = makeCombat(sb);
    const cap = Commander.fromCrew({ id: 's4', name: 'Tao', race: 'terra', skills: {} });
    cap.karma = 90; Commander.setActive(cap);
    c.enemy.hull = Math.round(c.enemy.hullMax * 0.2);
    withRandom(0.99, () => { for (let i = 0; i < 20; i++) sb.CombatManager.update(0.05); });
    ok(sb.CombatManager.surrenderOffer === false, 'a roll of 0.99 beats nobody');
    /* THE ROLL IS SPENT. Counting calls to Math.random would count the
       AI's as well; the property that actually matters is that a roll
       which cannot fail no longer produces an offer, because the one
       chance was used and lost. */
    withRandom(0.0, () => { for (let i = 0; i < 20; i++) sb.CombatManager.update(0.05); });
    ok(sb.CombatManager.surrenderOffer === false,
       'and a roll that cannot fail comes too late — one chance per fight, already spent');
  }

  /* NO QUARTER IS SAID OUT LOUD. An offer that silently never comes
     cannot be told apart from a broken game. */
  {
    const c = makeCombat(sb);
    const cap = Commander.fromCrew({ id: 's5', name: 'Vek', race: 'terra', skills: {} });
    cap.karma = 3; Commander.setActive(cap);
    c.enemy.hull = Math.round(c.enemy.hullMax * 0.2);
    const said = [];
    const realNotify = UI.notify;
    UI.notify = (t) => { said.push(String(t)); };
    try { for (let i = 0; i < 10; i++) sb.CombatManager.update(0.05); } finally { UI.notify = realNotify; }
    ok(sb.CombatManager.surrenderOffer === false, 'a butcher is offered nothing');
    const line = said.filter(t => /surrender/i.test(t));
    ok(line.length === 1,
       `and is told why — exactly once, not every frame (${line.length}: ${line.join(' / ')})`);
    ok(/prisoner/i.test(line[0] || ''), 'with the reason, not just a refusal');
  }

  Commander.setActive(null);
})();

// ============================================================
section('209. Clear their decks and the commander is still aboard');
// ============================================================
(function testClearedDecks() {
  const sb = loadEngine();
  const { Commander, Save, UI } = sb;

  const clearDecks = (c) => { c.enemy.crew.forEach(m => { m.hp = 0; m.state = 'dead'; m.dead = true; }); };

  /* NO COMMANDER: the hulk offer this branch always gave, untouched. */
  {
    const c = makeCombat(sb);
    Commander.setEnemy(null); Commander.setActive(null);
    clearDecks(c);
    ok(c.T._enemyCrewAliveCount() === 0, 'their decks really are cleared');
    c.T._updateCombat(0.05);
    ok(c.T.STATE === 'event', 'the game stops to ask what to do with the hulk');
    ok(/Derelict Hulk/.test(c.T.event.title),
       `an unled ship is still just a hulk (${c.T.event.title})`);
    ok(c.T.event.choices.every(ch => !ch.result.karma),
       'and nothing about stripping an empty hull touches karma');
  }

  /* A COMMANDER ABOARD: he outlives his crew, because he is a record
     and not a body — so clearing the decks leaves somebody to strike. */
  {
    const c = makeCombat(sb);
    const mine = Commander.fromCrew({ id: 's6', name: 'Ada', race: 'terra', skills: {} });
    mine.karma = 50; Commander.setActive(mine);
    const foe = Commander.fromCrew({ id: 'e6', name: 'Garro', race: 'terra', skills: {} });
    Commander.setEnemy(foe);
    clearDecks(c);
    c.T._updateCombat(0.05);
    ok(c.T.STATE === 'event', 'the game stops here too');
    ok(/Strikes/i.test(c.T.event.title), `but it is a man, not a wreck (${c.T.event.title})`);
    ok(/Garro/.test(c.T.event.text), 'and he has a name');

    const spare  = c.T.event.choices.find(ch => ch.result.searchDerelict);
    const finish = c.T.event.choices.find(ch => ch.result.destroyDerelict);
    ok(!!spare && !!finish, 'both doors are still open — board it, or open up');
    ok(spare.result.karma > 0, `sparing him pays karma (${spare.result.karma})`);
    ok(finish.result.karma === Commander.KARMA.KILL_HELPLESS,
       `finishing him is the helpless kill (${finish.result.karma})`);
    ok(spare.result.karma !== finish.result.karma,
       'the two doors cannot both be free — that was the hole this closes');
  }

  /* A BUTCHER: the commander is there, and would rather burn. Back to
     the plain hulk, with the reason said out loud. */
  {
    const c = makeCombat(sb);
    const mine = Commander.fromCrew({ id: 's7', name: 'Cull', race: 'terra', skills: {} });
    mine.karma = 4; Commander.setActive(mine);
    Commander.setEnemy(Commander.fromCrew({ id: 'e7', name: 'Garro', race: 'terra', skills: {} }));
    clearDecks(c);
    const said = [];
    const realNotify = UI.notify;
    UI.notify = (t) => { said.push(String(t)); };
    try { c.T._updateCombat(0.05); } finally { UI.notify = realNotify; }
    ok(/Derelict Hulk/.test(c.T.event.title),
       'nobody strikes to him, so there is nothing to accept');
    ok(said.some(t => /Garro/.test(t) && /burn/i.test(t)),
       `and he is told the man chose to burn (${said.join(' / ')})`);
    ok(c.T.event.choices.every(ch => !ch.result.karma),
       'and with no offer on the table there is no mercy to refuse — no karma either way');
  }

  /* ONE OFFER PER FIGHT. The branch is one-shot already; a second
     commander path must not have reopened it. */
  {
    const c = makeCombat(sb);
    Commander.setActive(Commander.fromCrew({ id: 's8', name: 'Ada', race: 'terra', skills: {} }));
    Commander.setEnemy(Commander.fromCrew({ id: 'e8', name: 'Garro', race: 'terra', skills: {} }));
    clearDecks(c);
    c.T._updateCombat(0.05);
    c.T.event = null;
    c.T.STATE = 'combat';
    c.T._updateCombat(0.05);
    ok(c.T.STATE === 'combat', 'it does not re-open every frame');
  }

  Commander.setEnemy(null);
  Commander.setActive(null);
})();


// ============================================================
section('210. The carbonite bay is slabs, and the slabs are levels');
// ============================================================
(function testBrig() {
  const sb = loadEngine();
  const { Ship, Save, SYSTEM_DEFS } = sb;
  Save.load(); Save.startRun();

  ok(!!SYSTEM_DEFS.carbonite, 'the carbonite bay is a module like any other');
  ok(SYSTEM_DEFS.carbonite.maxLevel === 3, `and tops out at three cells (${SYSTEM_DEFS.carbonite.maxLevel})`);

  const ship = new Ship('frigate', true, 0, 0);
  ok(ship.carboniteCapacity() === 0, 'a hull with no brig has no cells');
  ok(ship.freeCells() === 0, 'and no free ones either');
  ok(ship.takePrisoner({ id: 'x', name: 'Garro', bounty: 90 }) === false,
     'so nobody can be locked up aboard it');
  ok(ship.prisoners.length === 0, 'and nobody is');

  const empty = ship.rooms.find(r => r.type === 'empty');
  ok(!!empty, 'the frigate has a spare compartment to build in');
  ok(ship.addModuleAt('carbonite', empty.id), 'the brig goes into it');
  const brig = ship.getSystem('carbonite');
  ok(!!brig, 'and the hull has one now');

  /* A NEW MODULE ARRIVES UNPOWERED — that is the rule for every module
     in this game, and the brig must not be an exception, or a prisoner
     would be safe in a cell nobody is paying for. */
  brig.power = 0; brig.desiredPower = 0;
  ok(brig.isDisabled(), 'an unpowered brig is a disabled module');

  powerModule(ship, 'carbonite', 1);
  ok(ship.carboniteCapacity() === 1, `one level is one cell (${ship.carboniteCapacity()})`);
  ok(ship.takePrisoner({ id: 'g', name: 'Garro', bounty: 90 }), 'and one man fits');
  ok(ship.freeCells() === 0, 'which fills it');
  ok(ship.takePrisoner({ id: 'h', name: 'Vex', bounty: 40 }) === false,
     'a second man does not fit — it refuses rather than overfilling');
  ok(ship.prisoners.length === 1, `and there is still exactly one aboard (${ship.prisoners.length})`);

  brig.level = 3; brig.power = 3; brig.desiredPower = 3;
  ok(ship.carboniteCapacity() === 3, 'upgrading the module adds cells');
  ok(ship.takePrisoner({ id: 'h', name: 'Vex', bounty: 40 }), 'so the second man fits now');

  /* PRISONERS ARE NOT CREW. The list update45 put a cat into is the
     one thing that must never see them. */
  ok(!ship.crew.some(c => c && /Garro|Vex/.test(c.name || '')),
     'and none of them is in the crew list');

  /* AND IT CAN ACTUALLY BE FOUND (update64). The stock roll is
     deterministic in each station's own seed, so this counts a fixed
     forty ports rather than sampling — no flakiness, and it separates
     the 60% the player asked for from the 30% it shipped at by a mile.
     The point is not the exact number: a cell you never find means the
     "Take him prisoner" door never opens and half the bounty game is
     unreachable. */
  {
    let stocking = 0;
    for (let seed = 0; seed < 40; seed++) {
      if (new sb.Station(2, seed).stock.newModules.some(m => m.type === 'carbonite')) stocking++;
    }
    ok(stocking > 15,
       `a brig is findable — ${stocking} of 40 ports carry one`);
    ok(stocking < 40, 'but not every port has one');
  }

  // Damage takes cells before it takes the man.
  brig.damagedLevels = 2;
  ok(ship.carboniteCapacity() === 1, `a shot-out brig holds fewer (${ship.carboniteCapacity()})`);
  ok(ship.prisoners.length === 2, 'but nobody vanishes just because the room shrank');
})();

// ============================================================
section('211. What keeps them in is power, not the wall');
// ============================================================
(function testEscape() {
  const sb = loadEngine();
  const { Ship, Save, UI } = sb;
  Save.load(); Save.startRun();

  const build = () => {
    const ship = new Ship('frigate', true, 0, 0);
    const room = ship.rooms.find(r => r.type === 'empty');
    ship.addModuleAt('carbonite', room.id);
    const brig = ship.getSystem('carbonite');
    brig.level = 2; brig.power = 2; brig.desiredPower = 2;
    ship.takePrisoner({ id: 'g', name: 'Garro', bounty: 90 });
    return { ship, brig };
  };

  // Powered: the clock never starts, however long the run goes on.
  {
    const { ship } = build();
    for (let i = 0; i < 200; i++) ship.prisonerTick(0.5);
    ok(ship.prisoners.length === 1, 'a powered brig holds him for a hundred seconds');
    ok(ship.prisoners[0].escapeT === 0, 'and the clock never even started');
  }

  // Unpowered: he works the lock, is warned about, then he is gone.
  {
    const { ship, brig } = build();
    brig.power = 0; brig.desiredPower = 0;
    const said = [];
    const real = UI.notify;
    UI.notify = (t) => said.push(String(t));
    try {
      /* FIFTEEN ticks, not ten. The warning fires at 40% of the clock
         — ten seconds — so a ten-second window would see a repeating
         warning fire exactly once too, and pass while telling us
         nothing. It has to run WELL PAST the trigger to prove the
         latch, and stop short of the escape at 25s. */
      for (let i = 0; i < 15; i++) ship.prisonerTick(1);
      ok(ship.prisoners.length === 1, 'fifteen seconds in he is still aboard');
      ok(said.some(t => /working the cell door/.test(t)),
         `and the player has been warned (${said.join(' / ')})`);
      const warnings = said.filter(t => /working the cell door/.test(t)).length;
      ok(warnings === 1,
         `once, not on each of the five frames after the trigger (${warnings})`);
      for (let i = 0; i < Ship.ESCAPE_SECONDS; i++) ship.prisonerTick(1);
    } finally { UI.notify = real; }
    ok(ship.prisoners.length === 0, 'past the clock he is out of the cell');
    /* TWO STAGES, TWO SENTENCES (update72). The cell clock puts a man
       on the deck and says so — "shut a door on him" — and the airlock
       says the other half when he is actually gone. The old single
       line announced an escape that could no longer be stopped. */
    ok(said.some(t => /OUT of the cell/.test(t)),
       `the game says he is loose and what to do about it (${said.join(' / ')})`);
    ok(ship.crew.some(c => c.isPrisoner), 'and he is on the deck, walking');
  }

  /* RESTORING POWER IS A REAL SAVE. Interrupt a man at a lock and he
     starts again — otherwise cutting power for one second would be a
     death sentence for the bounty, and the player could never learn
     the rule from playing. */
  {
    const { ship, brig } = build();
    brig.power = 0; brig.desiredPower = 0;
    for (let i = 0; i < Ship.ESCAPE_SECONDS - 2; i++) ship.prisonerTick(1);
    ok(ship.prisoners.length === 1, 'two seconds from freedom he is still there');
    brig.power = 2; brig.desiredPower = 2;
    ship.prisonerTick(1);
    ok(ship.prisoners[0].escapeT === 0, 'power comes back and the clock resets');
    brig.power = 0; brig.desiredPower = 0;
    for (let i = 0; i < Ship.ESCAPE_SECONDS - 2; i++) ship.prisonerTick(1);
    ok(ship.prisoners.length === 1,
       'so the same two seconds are not enough the second time either');
  }

  /* ── HE IS ON THE DECK, AND HE DOES NOT FIGHT (update72) ───
   *
   * This used to read "nothing hostile is ever added to the deck",
   * which was true because the escape was a line of text. The player
   * asked for the walk, so there IS a man in the corridor now — and
   * the rule that matters is the one that was standing in for it: he
   * is not a boarder. Nobody swings at him and he swings at nobody. */
  {
    const { ship, brig } = build();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    brig.power = 0; brig.desiredPower = 0;
    for (let i = 0; i < Ship.ESCAPE_SECONDS + 5; i++) ship.prisonerTick(1);
    const runner = ship.crew.find(c => c.isPrisoner);
    ok(!!runner, 'the escape puts a man in the corridor');
    ok(!runner.isPlayer, 'who is not one of ours');

    // Put everybody in his room and let them stand there together.
    const hp0 = ship.crew.filter(c => !c.isPrisoner).map(c => c.hp);
    ship.crew.filter(c => !c.isPrisoner).forEach(c => {
      c.roomId = runner.roomId; c.x = runner.x; c.y = runner.y; c.inRoom = true;
    });
    for (let i = 0; i < 200; i++) ship.update(0.05);
    ok(hp0.every((hp, i) => ship.crew.filter(c => !c.isPrisoner)[i]?.hp >= hp - 0.01),
       'he hurts nobody — an escaper is not a boarding party');
    ok(!runner.dead && runner.hp >= runner.maxHp - 0.01,
       `and nobody hurts him either (${runner.hp}/${runner.maxHp})`);
    ok(ship.bodies === undefined || !ship.bodies.some(b => b && b.name === 'Garro'),
       'and leaves no body behind either');
  }

  // The cells ride home in the hull's save.
  {
    const { ship, brig } = build();
    /* SAVE HIM MID-ESCAPE. Serialising a man whose clock reads zero
       would prove nothing about the loader — the assertion below would
       pass on a loader that copied the field straight through. Put him
       two seconds from the airlock first. */
    brig.power = 0; brig.desiredPower = 0;
    for (let i = 0; i < Ship.ESCAPE_SECONDS - 2; i++) ship.prisonerTick(1);
    ok(ship.prisoners[0].escapeT > Ship.ESCAPE_SECONDS - 4,
       `he is nearly out when the game is saved (${ship.prisoners[0].escapeT}s)`);
    const back = Ship.deserialise(ship.serialise(), true, 0, 0);
    ok(back.prisoners.length === 1, 'a prisoner survives a save/load');
    ok(back.prisoners[0].bounty === 90, `with his price on him (${back.prisoners[0].bounty})`);
    ok(back.prisoners[0].escapeT === 0,
       `and NOT two seconds from freedom on the far side of it (${back.prisoners[0].escapeT}s)`);
    ok(back.prisoners[0].warned === false, 'nor already past his one warning');
    // A save written before the brig existed simply has none.
    const old = { ...ship.serialise() };
    delete old.prisoners;
    ok(Ship.deserialise(old, true, 0, 0).prisoners.length === 0,
       'and an old save loads with an empty brig rather than crashing');
  }
})();

// ============================================================
section('212. Alive he pays; his body pays half — one figure, two doors');
// ============================================================
(function testBounty() {
  const sb = loadEngine();
  const { Commander, Ship, Save, CargoGrid, CargoItem } = sb;

  const clearDecks = (c) => c.enemy.crew.forEach(m => { m.hp = 0; m.state = 'dead'; m.dead = true; });

  /* NO CELL, NO OFFER — and the text says what is missing.
     He is on the board here: since update69 the cell door is only ever
     offered for a wanted man, so testing the missing BRIG with an
     ordinary captain would have proved nothing about the brig. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster1 = Save.wanted()[0];
    const c = makeCombat(sb);
    Commander.setActive(Commander.fromCrew({ id: 'b1', name: 'Ada', race: 'terra', skills: {} }));
    const foe1 = Commander.fromCrew({ id: 'b2', name: 'Garro', race: 'terra', skills: {} });
    foe1.wantedId = poster1.id;
    Commander.setEnemy(foe1);
    ok(c.player.freeCells() === 0, 'the starting frigate has no brig');
    clearDecks(c);
    c.T._updateCombat(0.05);
    ok(!c.T.event.choices.some(ch => ch.result.capture),
       'so taking him prisoner is not offered');
    ok(/nowhere to put him/.test(c.T.event.text),
       `and the reason is on screen, not hidden in a greyed button (${c.T.event.text})`);
  }

  /* ── AN ORDINARY CAPTAIN IS NOT WORTH A CELL (update69) ─────
   *
   * The player took this door after a routine fight and felt robbed:
   * "dałem tak ale nie dostałem". The yard has an office for the men
   * on the poster and nobody at all for a nameless patrol captain, so
   * the cell was spent on a man who pays nothing — and a cell spent is
   * a cell not waiting for the one you are hunting.
   */
  {
    Save.reset(); Save.load(); Save.startRun();
    const c = makeCombat(sb);
    Commander.setActive(Commander.fromCrew({ id: 'o1', name: 'Ada', race: 'terra', skills: {} }));
    Commander.setEnemy(Commander.fromCrew({ id: 'o2', name: 'Nobody', race: 'terra', skills: {} }));
    const room = c.player.rooms.find(r => r.type === 'empty');
    c.player.addModuleAt('carbonite', room.id);
    const brig = c.player.getSystem('carbonite');
    powerModule(c.player, 'carbonite', 1);
    ok(c.player.freeCells() === 1, 'there IS a cell free — the brig is not the reason');

    clearDecks(c);
    c.T._updateCombat(0.05);
    ok(!c.T.event.choices.some(ch => ch.result.capture),
       'and he is still not offered a cell — nobody pays for him');
    ok(/not on any board/.test(c.T.event.text),
       `the popup says so out loud (${c.T.event.text})`);
    ok(c.T.event.choices.some(ch => ch.result.searchDerelict) &&
       c.T.event.choices.some(ch => ch.result.destroyDerelict),
       'the two doors that were always there are untouched');
  }

  /* A CELL FREE: three doors, and the prices agree with each other. */
  {
    const c = makeCombat(sb);
    Commander.setActive(Commander.fromCrew({ id: 'b3', name: 'Ada', race: 'terra', skills: {} }));
    const foe = Commander.fromCrew({ id: 'b4', name: 'Garro', race: 'terra', skills: {} });
    // On the board — the only kind of man the cell door opens for.
    foe.wantedId = Save.wanted()[0].id;
    Commander.setEnemy(foe);
    const room = c.player.rooms.find(r => r.type === 'empty');
    c.player.addModuleAt('carbonite', room.id);
    const brig = c.player.getSystem('carbonite');
    powerModule(c.player, 'carbonite', 1);
    ok(c.player.freeCells() === 1, 'now there is a cell');

    clearDecks(c);
    c.T._updateCombat(0.05);
    const cap  = c.T.event.choices.find(ch => ch.result.capture);
    const kill = c.T.event.choices.find(ch => ch.result.takeBody);
    ok(!!cap,  'the cell door is offered');
    ok(!!kill, 'and so is the other kind of door');

    const alive = Number((cap.label.match(/(\d+) CC/) || [])[1]);
    const dead  = Number((kill.label.match(/(\d+) CC/) || [])[1]);
    ok(alive > 0, `he is worth something alive (${alive} CC)`);
    ok(dead === Math.round(alive / 2),
       `and exactly half of that dead (${dead} vs ${alive}) — one figure, not two`);
    ok(cap.result.karma > 0 && kill.result.karma < 0,
       'and the cell pays karma where the gun costs it');

    // Taking him really puts him in the cell, with that price on him.
    c.T._resolveEvent(c.T.event.choices.indexOf(cap));
    ok(c.player.prisoners.length === 1, 'accepting locks him up');
    ok(c.player.prisoners[0].name === 'Garro', 'and it is the man who struck, by name');
    ok(c.player.prisoners[0].bounty === alive,
       `carrying the price the button quoted (${c.player.prisoners[0].bounty} vs ${alive})`);
  }

  /* THE BODY CARRIES ITS OWN PRICE — the bag's value is the figure the
     button quoted, not a number from a table beside it. */
  {
    const bag = new CargoItem('body_bag', { name: 'Garro', bounty: 77 });
    ok(bag.w === 2 && bag.h === 1, `a bagged body is two cells (${bag.w}x${bag.h})`);
    ok(bag.value('general') === 77, `and worth the man in it (${bag.value('general')})`);
    ok(new CargoItem('body_bag').value('general') > 0,
       'a bag with no name still has a floor price rather than being free');
    ok(bag.def.tag === 'body', 'and it is tagged as what it is');
  }

  Commander.setEnemy(null); Commander.setActive(null);
})();

// ============================================================
section('213. The bounty office pays once, at the dock');
// ============================================================
(function testPayout() {
  const sb = loadEngine();
  const { Base, Ship, Save, CargoItem } = sb;
  Save.load();

  const hull = () => {
    const ship = new Ship('frigate', true, 0, 0);
    const room = ship.rooms.find(r => r.type === 'empty');
    ship.addModuleAt('carbonite', room.id);
    const brig = ship.getSystem('carbonite');
    brig.level = 2; brig.power = 2; brig.desiredPower = 2;
    ship.takePrisoner({ id: 'g', name: 'Garro', bounty: 90 });
    ship.cargo.add('body_bag', { name: 'Vex', bounty: 45 });
    return ship;
  };

  Base.spend(Base.cc());
  const entry = { key: 'frigate', data: hull().serialise() };
  const rep = Base.returnFromRun({ shipEntry: entry, crew: [], cc: 0 });

  ok(rep.prisoners === 1, `one man handed over (${rep.prisoners})`);
  ok(rep.bodies === 1, `and one body claimed (${rep.bodies})`);
  ok(rep.bounty === 135, `paid 90 + 45 (${rep.bounty})`);
  ok(Base.cc() === 135, `and the CC is really in the bank (${Base.cc()})`);

  /* PAID ONCE. They are taken OFF the hull as they are paid, so the
     same man cannot be handed in again next time the hull docks —
     which is the shape every double-count bug in this file has had. */
  ok((entry.data.prisoners ?? []).length === 0, 'the cells are empty afterwards');
  ok(!entry.data.cargo.items.some(it => it.defKey === 'body_bag'),
     'and the bag is out of the hold');
  const again = Base.returnFromRun({ shipEntry: entry, crew: [], cc: 0 });
  ok(again.bounty === 0, `docking the same hull again pays nothing (${again.bounty})`);
  ok(Base.cc() === 135, 'and the bank does not move');

  // A hull with neither pays nothing and reports nothing.
  const plain = { key: 'frigate', data: new Ship('frigate', true, 0, 0).serialise() };
  const none = Base.returnFromRun({ shipEntry: plain, crew: [], cc: 0 });
  ok(none.bounty === 0 && none.prisoners === 0 && none.bodies === 0,
     'an ordinary run reports no bounty at all');
})();


// ============================================================
section('214. The wanted list is the one place a pirate lives');
// ============================================================
(function testWantedRegister() {
  const sb = loadEngine();
  const { Save } = sb;

  /* A SAVE FROM BEFORE THE LIST GETS ONE NAME — the design says the
     hunt starts with a single pirate. */
  /* A REAL SAVE WITH THE LIST CUT OUT — not a two-field stub. The stub
     version of this crashed on `stats`, and a save that cannot load at
     all proves nothing about a MIGRATION. Reset, write it, remove the
     one field, and read it back before loading. */
  const KEY = 'moonwars_save_v1';
  Save.reset(); Save.save();
  {
    const raw = JSON.parse(sb.localStorage.getItem(KEY));
    delete raw.wanted;
    sb.localStorage.setItem(KEY, JSON.stringify(raw));
    ok(JSON.parse(sb.localStorage.getItem(KEY)).wanted === undefined,
       'the copy on disk really has no wanted list');
  }
  Save.load();
  ok(Save.wanted().length === 1,
     `an old save is migrated to exactly one poster (${Save.wanted().length})`);
  const first = Save.wanted()[0];
  ok(!!first.id && !!first.name, `and he has an id and a name (${first.name})`);
  ok(first.state === 'wanted', 'nobody has met him yet');
  ok(first.bounty === Save.wantedBounty(first.level),
     `his price comes off his level (${first.bounty} for level ${first.level})`);
  /* AND THE LEVEL REALLY MOVES IT. The line above is true of a flat
     price too — it compares the record against the same function that
     filled it, so it would pass on `wantedBounty = () => 100`. */
  ok(Save.wantedBounty(10) > Save.wantedBounty(3),
     `a bigger name is worth more (${Save.wantedBounty(10)} vs ${Save.wantedBounty(3)})`);
  ok(Save.wantedBounty(4) - Save.wantedBounty(3) === Save.wantedBounty(9) - Save.wantedBounty(8),
     'and every level is worth the same step, so the board reads evenly');

  // The list survives a save/load — that is the whole point of it.
  Save.save();
  Save.load();
  ok(Save.wanted().length === 1, 'the board survives a reload');
  ok(Save.wanted()[0].id === first.id, 'with the same man on it');

  /* ONE REGISTER. `wantedById` hands back the live record, so a change
     made through it is visible in the list itself — if this ever
     returned a copy, the map and the base would drift apart, which the
     design names as this package's biggest risk. */
  const live = Save.wantedById(first.id);
  live.bounty = 999;
  ok(Save.wanted()[0].bounty === 999,
     'the list and a looked-up record are the SAME object, not two copies');
  live.bounty = first.bounty;

  // A sighting records where, and only for a man who is on the list.
  ok(Save.markSighted(first.id, 'luna'), 'a sighting sticks');
  ok(Save.wantedById(first.id).state === 'sighted', 'and changes his state in place');
  ok(Save.markSighted('nobody') === false, 'a sighting of a man not on the list is refused');

  /* THE CEILING. A board that grows without bound is the third risk in
     the design; `addWanted` must refuse rather than trim. */
  let added = 0;
  for (let i = 0; i < 20; i++) if (Save.addWanted(1)) added++;
  ok(Save.wanted().length === Save.WANTED_MAX,
     `the board tops out at ${Save.WANTED_MAX} (${Save.wanted().length})`);
  ok(added === Save.WANTED_MAX - 1, `and refused the rest rather than trimming (${added} added)`);
  const names = Save.wanted().map(w => w.name);
  ok(new Set(names).size === names.length,
     `no two posters share a name (${names.join(', ')})`);
  /* FOUR DRAWS FROM TEN COLLIDE ABOUT HALF THE TIME, so the line above
     is a coin toss dressed as a test — it passed on a build that drew
     WITH replacement. Thirty probes against a board that already holds
     four of the ten names is not a coin toss: an unfiltered pick would
     hit a taken name within a handful of tries. */
  {
    const taken = new Set(Save.wanted().map(w => w.name));
    let clashes = 0;
    for (let i = 0; i < 30; i++) if (taken.has(Save.makeWanted(1).name)) clashes++;
    ok(clashes === 0,
       `thirty fresh rolls against ${taken.size} taken names collide never (${clashes})`);
  }

  // Handing one in takes him OFF, and only once.
  const target = Save.wanted()[1];
  ok(Save.deliverWanted(target.id, 100) === 100, 'handing him in pays what he was worth');
  ok(!Save.wantedById(target.id), 'and he is gone from the board');
  ok(Save.deliverWanted(target.id, 100) === 0, 'handing in the same man again pays nothing');
  ok(Save.wanted().length === Save.WANTED_MAX - 1, 'and the board is one shorter, not two');

  /* AN EMPTY BOARD STAYS EMPTY OVER A RELOAD. The first version of the
     migration read "no names" as "old save" and quietly put a fresh
     pirate up every time a player who had caught everybody reloaded —
     a second source of pirates beside the contract roll. Caught by the
     encounter test below, which found a wanted man on a board it had
     just emptied. */
  Save.wanted().forEach(x => Save.deliverWanted(x.id, 0));
  ok(Save.wanted().length === 0, 'every poster is handed in');
  Save.save(); Save.load();
  ok(Save.wanted().length === 0,
     `and the board is still empty after a reload (${Save.wanted().length})`);
  ok(!!Save.addWanted(1), 'a contract is what puts the next name up');
  ok(Save.wanted().length === 1, 'and it is the only one there');
})();

// ============================================================
section('215. A name off the board turns up in a fight — by reference');
// ============================================================
(function testWantedEncounter() {
  const sb = loadEngine();
  const { Save, Commander, Ship, CombatManager } = sb;

  const withRandom = (v, fn) => {
    const real = Math.random;
    Math.random = () => v;
    try { return fn(); } finally { Math.random = real; }
  };

  /* PUT HIM ON THE MAP, the way the game does (update66): a REAL
     SectorMap, a real combat node, and the poster id stamped on it.
     Standing on that node is what makes the next fight his. */
  const seatOnMap = (T, posterId) => seatWantedOnMap(sb, T, posterId);

  Save.reset();
  Save.load(); Save.startRun();
  const poster = Save.wanted()[0];

  // Standing on his node seats him; standing anywhere else does not.
  {
    const c = makeCombat(sb);
    seatOnMap(c.T, poster.id);
    withRandom(0.0, () => c.T._startCombat('normal', false));
    const foe = Commander.enemy();
    ok(!!foe, 'a commander is seated');
    ok(foe.wantedId === poster.id, 'and he is the man off the board');
    ok(foe.name === poster.name, `carrying the poster's name (${foe.name})`);
    ok(foe.bounty === poster.bounty, `and the poster's price (${foe.bounty})`);
    ok(Save.wantedById(poster.id).state === 'sighted',
       'meeting him marks the ONE record as sighted');

    /* NO SECOND COPY. The commander points at the poster by id; there
       must not be another record of this man anywhere on the board. */
    const same = Save.wanted().filter(w => w.name === poster.name);
    ok(same.length === 1, `exactly one record of him exists (${same.length})`);
    ok(Save.wanted().length === 1, 'and meeting a pirate does not add anybody');
  }

  {
    const c = makeCombat(sb);
    seatOnMap(c.T, null);
    withRandom(0.0, () => c.T._startCombat('normal', false));
    ok(Commander.enemy() === null || !Commander.enemy().wantedId,
       'an ordinary node seats no wanted man, however the dice fall');
  }

  /* ── THE WHOLE ROAD, END TO END ────────────────────────────
   *
   * Everything above builds its prisoners and its bags by hand, which
   * is exactly how five reverts slept through the first breaking run:
   * a hand-made record carries the poster id because the TEST put it
   * there, not because the game did. This block never touches a
   * record directly — it meets the man, clears his decks, presses the
   * button and reads what the game built.
   */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    const c = makeCombat(sb);
    seatOnMap(c.T, poster.id);
    withRandom(0.0, () => c.T._startCombat('normal', false));
    ok(Commander.enemy().wantedId === poster.id, 'the wanted man is in the fight');

    /* `_startCombat` SPAWNS A FRESH ENEMY, so the hull `makeCombat`
       handed back is not the one in this fight. Read the live one off
       the game or the decks below are cleared on a ship nobody is
       fighting — which is how the first version of this block ended
       up asserting against a null event. */
    const foeShip = c.T.enemyShip;
    // A cell to put him in, and their decks cleared.
    const room = c.player.rooms.find(r => r.type === 'empty');
    c.player.addModuleAt('carbonite', room.id);
    const brig = c.player.getSystem('carbonite');
    powerModule(c.player, 'carbonite', 1);
    foeShip.crew.forEach(m => { m.hp = 0; m.state = 'dead'; m.dead = true; });
    /* `_startCombat` begins the fight in ENTERING, and the cleared-decks
       branch only fires while it is ACTIVE. Pump it there — bounded,
       because a `while` in a test hangs the suite instead of failing
       it, and a hang is the one failure the breaking run cannot report. */
    for (let i = 0; i < 60 && !CombatManager.isActive(); i++) CombatManager.update(0.05);
    c.T.STATE = 'combat';
    c.T._updateCombat(0.05);

    ok(!!c.T.event, 'clearing their decks raises the decision');
    const cap = c.T.event.choices.find(ch => ch.result.capture);
    ok(!!cap, 'the cell door is offered for him');
    /* THE PRICE ON THE BUTTON IS THE PRICE ON THE POSTER. Without the
       short-circuit in `_commanderBounty` this quotes his RANK
       instead, and the base and the fight disagree about one man. */
    const quoted = Number((cap.label.match(/(\d+) CC/) || [])[1]);
    ok(quoted === poster.bounty,
       `and quotes the poster price, not his rank (${quoted} vs ${poster.bounty})`);

    c.T._resolveEvent(c.T.event.choices.indexOf(cap));
    ok(c.player.prisoners.length === 1, 'pressing it puts him in the cell');
    ok(c.player.prisoners[0].wantedId === poster.id,
       'and the GAME stamped the poster id on him, not this test');
    ok(c.player.prisoners[0].bounty === poster.bounty, 'with the poster price');
  }

  /* THE SAME ROAD, THE OTHER DOOR: his body carries the poster too. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    const c = makeCombat(sb);
    seatOnMap(c.T, poster.id);
    withRandom(0.0, () => c.T._startCombat('normal', false));
    c.T.enemyShip.crew.forEach(m => { m.hp = 0; m.state = 'dead'; m.dead = true; });
    for (let i = 0; i < 60 && !CombatManager.isActive(); i++) CombatManager.update(0.05);
    c.T.STATE = 'combat';
    c.T._updateCombat(0.05);
    ok(!!c.T.event, 'clearing their decks raises the decision here too');
    const kill = c.T.event.choices.find(ch => ch.result.takeBody);
    c.T._resolveEvent(c.T.event.choices.indexOf(kill));
    const bag = c.player.cargo.items.find(it => it.defKey === 'body_bag');
    ok(!!bag, 'his body is in the hold');
    ok(bag.meta.wantedId === poster.id, 'and the bag knows which poster it closes');
    ok(bag.meta.bounty === Math.round(poster.bounty / 2),
       `for half the poster price (${bag.meta.bounty} vs ${poster.bounty})`);
  }

  /* A DELIVERED MAN IS NOT FOUND AGAIN. He is off the list, so there
     is nobody for the encounter to point at. */
  {
    /* Self-contained: the blocks above reset the save, so reaching back
       for the `poster` this section opened with would hand
       `deliverWanted` an id that is not on the board any more and empty
       nothing at all. */
    Save.reset(); Save.load(); Save.startRun();
    Save.wanted().forEach(w => Save.deliverWanted(w.id, 0));
    ok(Save.wanted().length === 0, 'the board is empty');
    const c = makeCombat(sb);
    seatOnMap(c.T, poster.id);      // the node still names a man nobody wants
    withRandom(0.0, () => c.T._startCombat('normal', false));
    const foe = Commander.enemy();
    ok(!foe || !foe.wantedId,
       'a poster handed in since the map was drawn seats nobody');
  }
  Commander.setEnemy(null);
})();

// ============================================================
section('216. Only the dock closes a case — and it closes it once');
// ============================================================
(function testWantedDelivery() {
  const sb = loadEngine();
  const { Save, Base, Ship, CargoItem } = sb;

  const board = () => {
    Save.reset();
    Save.load();
    return Save.wanted()[0];
  };

  /* ALIVE. The prisoner carries the poster's id, and handing him over
     is what takes him off — not catching him. */
  {
    const w = board();
    Base.spend(Base.cc());
    const ship = new Ship('frigate', true, 0, 0);
    const room = ship.rooms.find(r => r.type === 'empty');
    ship.addModuleAt('carbonite', room.id);
    const brig = ship.getSystem('carbonite');
    powerModule(ship, 'carbonite', 1);
    ok(ship.takePrisoner({ id: 'c', name: w.name, bounty: w.bounty, wantedId: w.id }),
       'he goes in the cell');
    ok(Save.wanted().length === 1,
       'and catching him does NOT close the case — he is still on the board');

    const entry = { key: 'frigate', data: ship.serialise() };
    ok(entry.data.prisoners[0].wantedId === w.id,
       'the poster id rides home in the hull record');
    const rep = Base.returnFromRun({ shipEntry: entry, crew: [], cc: 0 });
    ok(rep.wanted === 1, `docking takes one name off the board (${rep.wanted})`);
    ok(rep.bounty === w.bounty, `and pays the poster price (${rep.bounty} vs ${w.bounty})`);
    ok(Base.cc() === w.bounty, 'into the bank');
    ok(Save.wanted().length === 0, 'the board is empty afterwards');

    // Docking the same hull again pays nothing and closes nothing.
    const again = Base.returnFromRun({ shipEntry: entry, crew: [], cc: 0 });
    ok(again.wanted === 0 && again.bounty === 0,
       `the same man cannot be handed in twice (${again.wanted}/${again.bounty})`);
    ok(Base.cc() === w.bounty, 'and the bank does not move');
  }

  /* DEAD. A body in the hold closes the case too — for half. A kill
     on its own does not: the bag has to come home. */
  {
    const w = board();
    Base.spend(Base.cc());
    const ship = new Ship('frigate', true, 0, 0);
    const half = Math.round(w.bounty / 2);
    ship.cargo.add('body_bag', { name: w.name, bounty: half, wantedId: w.id });
    const entry = { key: 'frigate', data: ship.serialise() };
    const rep = Base.returnFromRun({ shipEntry: entry, crew: [], cc: 0 });
    ok(rep.wanted === 1, 'a delivered body closes the case');
    ok(rep.bounty === half, `for half the price (${rep.bounty} vs ${w.bounty} alive)`);
    ok(Save.wanted().length === 0, 'and takes him off the board');
    ok(half * 2 === w.bounty || half * 2 === w.bounty + 1,
       'the two prices really are one figure and its half');
  }

  /* A KILL THAT NEVER CAME HOME. The design is explicit: a corpse on
     the battlefield is not proof. */
  {
    const w = board();
    const ship = new Ship('frigate', true, 0, 0);
    const rep = Base.returnFromRun({
      shipEntry: { key: 'frigate', data: ship.serialise() }, crew: [], cc: 0 });
    ok(rep.wanted === 0, 'docking with nothing aboard closes no case');
    ok(Save.wantedById(w.id), 'and he is still wanted');
  }

  /* AN ORDINARY BOUNTY — a commander who was never on the board — still
     pays, and still takes nobody off it. */
  {
    const w = board();
    Base.spend(Base.cc());
    const ship = new Ship('frigate', true, 0, 0);
    ship.cargo.add('body_bag', { name: 'Nobody', bounty: 33 });
    const rep = Base.returnFromRun({
      shipEntry: { key: 'frigate', data: ship.serialise() }, crew: [], cc: 0 });
    ok(rep.bounty === 33, `an unlisted body still pays (${rep.bounty})`);
    ok(rep.wanted === 0, 'but closes no case');
    ok(Save.wantedById(w.id), 'and the man on the board is untouched');
  }
})();

// ============================================================
section('217. The board in the base reads the list, it does not keep one');
// ============================================================
(function testWantedBoard() {
  const sb = loadEngine();
  const { Save, BaseScreen } = sb;
  const ctx = initRenderer(sb);

  Save.reset();
  Save.load();
  BaseScreen.open();
  BaseScreen.draw(ctx);                         // the town (update149/152): WANTED is a building

  const tabs = BaseScreen._zonesFor('building').map(z => z.arg);
  ok(tabs.includes('WANTED'), `the base has a WANTED building (${[...new Set(tabs)].join(', ')})`);
  const last = BaseScreen._zonesFor('building').filter(z => z.arg === 'WANTED')[0];
  ok(last.x + last.w <= 1280,
     `and its door is on screen (${last.x + last.w})`);

  BaseScreen._set({ tab: 'WANTED' });
  const w = Save.wanted()[0];
  let text = captureText(ctx, () => BaseScreen.draw(ctx)).map(d => d.t);
  ok(text.some(t => /^WANTED$/.test(t)), 'the screen names itself');
  ok(text.some(t => t === w.name), `and the man on the board is on it (${w.name})`);
  ok(text.some(t => t === `${w.bounty} CC alive`), 'with what he is worth alive');
  ok(text.some(t => t === `${Math.round(w.bounty / 2)} CC for the body`),
     'and half that for his body');
  ok(text.some(t => /no sighting yet/.test(t)), 'a man nobody has met says so');

  /* IT READS THE LIST EVERY FRAME. Marking him sighted through Save
     must change this screen with no other call — a screen that cached
     the list would still be showing "no sighting yet". */
  Save.markSighted(w.id, 'luna');
  text = captureText(ctx, () => BaseScreen.draw(ctx)).map(d => d.t);
  ok(text.some(t => /last seen/.test(t)),
     `the sighting shows up with no refresh (${text.filter(t => /seen|sighting/.test(t)).join(' / ')})`);
  ok(!text.some(t => /no sighting yet/.test(t)), 'and the old line is gone');

  // Handing him in empties the board, and the screen says so rather than blanking.
  Save.deliverWanted(w.id, 0);
  text = captureText(ctx, () => BaseScreen.draw(ctx)).map(d => d.t);
  ok(!text.some(t => t === w.name), 'a delivered man is off the board');
  ok(text.some(t => /board is empty/i.test(t)),
     'and an empty board explains itself instead of drawing nothing');

  /* NO BUTTONS. A poster is closed by flying, not by clicking — same
     rule that keeps a BUILD button off the Gate screen. */
  BaseScreen.draw(ctx);
  ok(['claimBounty', 'wanted', 'hunt', 'deliverWanted']
       .every(act => BaseScreen._zonesFor(act).length === 0),
     'the wanted screen offers nothing to press');
})();


// ============================================================
section('218. A corpse goes nowhere until the player says so');
// ============================================================
(function testNoAutoVent() {
  const sb = loadEngine();
  const { Ship, Save } = sb;
  Save.load(); Save.startRun();

  const build = () => {
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const victim = ship.crew[0];
    victim.hp = 0; victim.state = 'dead'; victim.dead = true;
    const air = ship.doors.find(d => d.isAirlock);
    air.mode = 'open'; air.open = true; air.openness = 1;
    return { ship, victim };
  };

  /* THE OLD RULE WAS THE HATCH. Open one to fight a fire and your dead
     went out with the smoke — the player was never asked. */
  {
    const { ship, victim } = build();
    ok(ship.hasOpenAirlock(), 'a hatch is open');
    for (let i = 0; i < 2000; i++) {
      ship.update(0.05);
      if (!ship.crew.includes(victim)) break;
    }
    ok(ship.crew.includes(victim),
       'and he is still aboard — an open hatch is a place, not a decision');
    ok(victim.decaying, 'he has started to rot, which is the clock on the decision');
  }

  /* ── SOMEBODY IS SENT, AND ONLY ON THE ORDER ────────────
   *
   * A corpse in a compartment nobody walks through has to be fetched
   * (update42) — but the thing that sends the hand must be the ORDER,
   * not the smell. With the dispatch reading `decaying` again, a
   * rotting body pulls a crewman off his post for nothing: he walks
   * over, the pickup rule refuses him, and he stands there. The body
   * never moves either way, so only THIS assertion sees it.
   */
  {
    const { ship, victim } = build();
    // Nobody anywhere near him, so a hand has to be dispatched.
    ship.crew.filter(c => c !== victim).forEach((c, i) => {
      const far = ship.rooms.filter(r => r.id !== victim.roomId)[i] ?? ship.rooms[1];
      c.roomId = far.id; c.x = far.cx; c.y = far.cy;
      c._rescueId = null; c.carrying = null; c._waypoints = [];
    });
    ok(ship.crewInRoom(victim.roomId).length === 0, 'he is alone in there');
    for (let i = 0; i < 1200; i++) ship._updateBodies(0.05);
    ok(victim.decaying, 'he has been rotting for a while');
    ok(!ship.crew.some(c => c._rescueId === victim.id),
       'and NOBODY has been sent — rot is not an order');
    ship.orderBody(victim, 'eject');
    ship._updateBodies(0.05);
    ok(ship.crew.some(c => c._rescueId === victim.id),
       'the order sends a hand to fetch him');
  }

  // The order is what moves him.
  {
    const { ship, victim } = build();
    const r = ship.orderBody(victim, 'eject');
    ok(r.ok, `VENT is accepted (${r.message})`);
    let out = false;
    for (let i = 0; i < 4000; i++) {
      ship.update(0.05);
      if (!ship.crew.includes(victim)) { out = true; break; }
    }
    ok(out, 'and he goes out the airlock');
  }

  /* THE WOUNDED ARE NOT A DECISION. They are still collected on their
     own — a man bleeding on the floor is an emergency, and making the
     player click him would have been a change nobody asked for. */
  {
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const room = ship.rooms.find(r => r.type === 'empty') || ship.rooms[1];
    ship.addModuleAt('medbay', room.id);
    const med = ship.getSystem('medbay');
    med.level = 1; med.power = 1; med.desiredPower = 1;
    const hurt = ship.crew[0];
    hurt.hp = 1; hurt.state = 'injured';
    const others = ship.crew.filter(c => c !== hurt && !c.dead);
    ok(others.length > 0, 'somebody else is aboard to do the carrying');
    let lifted = false;
    for (let i = 0; i < 600 && !lifted; i++) {
      ship.update(0.05);
      lifted = ship.crew.some(c => c.carrying === hurt) || hurt.roomId === room.id;
    }
    ok(lifted, 'a wounded man is picked up with no order at all');
  }
})();

// ============================================================
section('219. TREAT / VENT / BAG — one question, asked once');
// ============================================================
(function testBodyOrders() {
  const sb = loadEngine();
  const { Ship, Save, CargoGrid } = sb;
  Save.load(); Save.startRun();

  const build = ({ medbay = false, airlock = false, hand = true } = {}) => {
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    /* THE FRIGATE SHIPS WITH A MEDBAY. The first version of this
       helper "added" one and read the refusal as proof — on a hull
       that already had it, so the no-medbay case was never tested at
       all. Take it OUT to make that case real. */
    const med = ship.getSystem('medbay');
    if (medbay) { med.level = 1; med.power = 1; med.desiredPower = 1; }
    else if (med) {
      ship.systems = ship.systems.filter(sy => sy !== med);
      const mr = ship.getRoomById(med.roomId);
      if (mr) { mr.type = 'empty'; mr.system = null; }
    }
    const air = ship.doors.find(d => d.isAirlock);
    if (airlock) { air.mode = 'open'; air.open = true; air.openness = 1; }
    else { air.mode = 'closed'; air.open = false; air.openness = 0; }
    const victim = ship.crew[0];
    victim.hp = 0; victim.state = 'dead'; victim.dead = true;
    // Everybody else either stands with him or well away from him.
    ship.crew.filter(c => c !== victim).forEach((c, i) => {
      if (hand && i === 0) { c.roomId = victim.roomId; }
      else {
        const far = ship.rooms.find(r => r.id !== victim.roomId);
        c.roomId = far.id;
      }
    });
    return { ship, victim };
  };

  /* EVERY REFUSAL HAS A REASON, and the menu asks the same question the
     order does — a row that looks live and then does nothing is the
     bug this shape exists to prevent. */
  {
    const { ship, victim } = build({ medbay: false, airlock: false, hand: false });
    ok(/dead/.test(ship.bodyRefusal(victim, 'treat')), 'a corpse cannot be treated');
    /* update68: a SHUT hatch no longer refuses — the bearer opens it.
       Only a hull with no airlock at all can say no. */
    ok(ship.bodyRefusal(victim, 'eject') === null,
       'a shut hatch does not refuse the order any more — the bearer opens it');
    /* update68: BAG no longer needs somebody standing over him — the
       order SENDS a man. So on a crewed hull it is simply allowed. */
    ok(ship.bodyRefusal(victim, 'bag') === null,
       'and BAG is live even with nobody in the room — the order sends somebody');
    // …and the order agrees with the menu, word for word.
    ['treat'].forEach(act => {
      const r = ship.orderBody(victim, act);
      ok(!r.ok && r.message.includes(ship.bodyRefusal(victim, act)),
         `${act.toUpperCase()} refuses out loud with the SAME reason (${r.message})`);
    });
  }

  /* THE TWO THINGS THAT CAN STILL SAY NO after update68 took the old
     reasons away. If nothing tested these, VENT and BAG would have no
     refusal left at all and the menu would go quiet again. */
  {
    const { ship, victim } = build({ airlock: false, hand: true });
    ship.doors.forEach(d => { d.isAirlock = false; });
    const why = ship.bodyRefusal(victim, 'eject');
    ok(/no airlock/.test(String(why)),
       `a hull with no airlock at all refuses VENT out loud (${why})`);
    const r = ship.orderBody(victim, 'eject');
    ok(!r.ok && r.message.includes(why), `and the order says the same (${r.message})`);
    ok(ship.crew.includes(victim), 'and he is still aboard — nothing happened quietly');
  }
  {
    const { ship, victim } = build({ hand: true });
    // Every hand already has his arms full — there is nobody to send.
    ship.crew.filter(c => c !== victim).forEach(c => { c.carrying = { id: 'x' }; });
    const why = ship.bodyRefusal(victim, 'bag');
    ok(/nobody free/.test(String(why)),
       `with every hand full, BAG refuses out loud (${why})`);
    const r = ship.orderBody(victim, 'bag');
    ok(!r.ok && r.message.includes(why), `and the order agrees (${r.message})`);
    ok(ship.crew.includes(victim), 'so he is still on the deck');
    ok(!ship.cargo.items.some(it => it.def.tag === 'body'), 'and nothing reached the hold');
  }

  // A living wounded man can be treated only with a medbay.
  {
    const { ship, victim } = build({ medbay: false });
    victim.dead = false; victim.state = 'injured'; victim.hp = 1;
    ok(/no medbay/.test(ship.bodyRefusal(victim, 'treat')), 'no medbay, no treatment');
    ok(/alive/.test(ship.bodyRefusal(victim, 'eject')), 'and you cannot eject the living');
    ok(/alive/.test(ship.bodyRefusal(victim, 'bag')), 'nor bag them');
  }
  {
    const { ship, victim } = build({ medbay: true });
    victim.dead = false; victim.state = 'injured'; victim.hp = 1;
    ok(ship.bodyRefusal(victim, 'treat') === null, 'with a medbay, TREAT is live');
    ok(ship.orderBody(victim, 'treat').ok, 'and it is accepted');
    ok(ship.crew.some(c => c._rescueId === victim.id), 'a stretcher is on the way');
  }

  /* BAG PUTS HIM IN THE HOLD. Two cells, no trade value, and the rot
     clock stops because he is sealed. */
  {
    const { ship, victim } = build({ hand: true });
    const before = ship.cargo.usedCells();
    ok(ship.bodyRefusal(victim, 'bag') === null, 'a hand in the room can bag him');
    const r = ship.orderBody(victim, 'bag');
    ok(r.ok, `and does (${r.message})`);
    ok(!ship.crew.includes(victim), 'he is off the deck');
    const bag = ship.cargo.items.find(it => it.def.tag === 'body');
    ok(!!bag, 'and in the hold');
    ok(ship.cargo.usedCells() - before === 2, `taking two cells (${ship.cargo.usedCells() - before})`);
    ok(bag.meta.crewBody === true, 'marked as one of ours, not merchandise');
    ok(bag.meta.name === victim.name, `with his name on the tag (${bag.meta.name})`);
    ok(bag.value('general') === 0, 'and no price at any port — you cannot sell your own dead');
    // He cannot rot in a bag: he is not on the ship to rot.
    for (let i = 0; i < 400; i++) ship.update(0.05);
    ok(ship.cargo.items.includes(bag), 'and he stays stowed');
  }

  // A cat is one cell, and the same rule at the till.
  {
    const { ship, victim } = build({ hand: true });
    victim.isPet = true;
    const before = ship.cargo.usedCells();
    ok(ship.orderBody(victim, 'bag').ok, 'the cat can be bagged too');
    ok(ship.cargo.usedCells() - before === 1,
       `and takes one cell, not two (${ship.cargo.usedCells() - before})`);
    ok(ship.cargo.items.find(it => it.def.tag === 'body').meta.crewBody === true,
       'tagged the same way, so the dock has one rule for both');
  }

  /* A FULL HOLD REFUSES BEFORE ANYTHING MOVES — the update53 rule: an
     order with no effect is refused, not swallowed. */
  {
    const { ship, victim } = build({ hand: true });
    let guard = 0;
    while (ship.cargo.add('he3_ore') && guard++ < 200) { /* pack it solid */ }
    ok(guard < 200, `the hold really did fill up (${guard} crates)`);
    ok(/no room/.test(ship.bodyRefusal(victim, 'bag')), 'a full hold refuses the bag');
    const r = ship.orderBody(victim, 'bag');
    ok(!r.ok, 'and the order is refused');
    ok(ship.crew.includes(victim), 'so he is still lying there — nothing was lost quietly');
  }
})();

// ============================================================
section('220. The airlock costs your name; the bag pays it back');
// ============================================================
(function testBurialKarma() {
  const sb = loadEngine();
  const { Ship, Save, Base, Commander } = sb;

  const seat = () => {
    const cap = Commander.fromCrew({ id: 'k', name: 'Ada', race: 'terra', skills: {} });
    cap.karma = 50;
    Commander.setActive(cap);
    return cap;
  };

  /* VENTING ONE OF YOUR OWN. Free in CC, and that is the point — the
     price is somewhere karma can see it. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const cap = seat();
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const air = ship.doors.find(d => d.isAirlock);
    air.mode = 'open'; air.open = true; air.openness = 1;
    const victim = ship.crew[0];
    victim.hp = 0; victim.state = 'dead'; victim.dead = true;
    ship.orderBody(victim, 'eject');
    for (let i = 0; i < 4000 && ship.crew.includes(victim); i++) ship.update(0.05);
    ok(!ship.crew.includes(victim), 'he goes out');
    ok(cap.karma === 50 + Ship.EJECT_KARMA,
       `and it costs ${Ship.EJECT_KARMA} karma (${cap.karma})`);
  }

  /* A MAN WHO WALKS OUT ON HIS OWN IS NOT A DECISION. Nothing the
     player chose, so nothing his name pays for. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const cap = seat();
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const walker = ship.crew[0];
    walker.hp = 0; walker.state = 'dead'; walker.dead = true;
    walker.ejected = true;                 // the plague path, no order given
    ship._updateBodies(0.05);
    ok(!ship.crew.includes(walker), 'he is gone');
    ok(cap.karma === 50, `and karma did not move (${cap.karma})`);
  }

  /* BURIAL AT THE DOCK. The memorial already knew he died; what it
     learns here is that he came home. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const cap = seat();
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const victim = ship.crew[0];
    victim.hp = 0; victim.state = 'dead'; victim.dead = true;
    victim.dead = true;
    Save.addToGraveyard(victim);
    const grave = Save.getGraveyard().find(g => g.name === victim.name);
    ok(!!grave, 'the memorial already has him — dying is what puts him there');
    ok(!grave.buried, 'and does not claim he was buried');

    ship.crew.filter(c => c !== victim).forEach(c => { c.roomId = victim.roomId; });
    ok(ship.orderBody(victim, 'bag').ok, 'he is bagged');

    Base.spend(Base.cc());
    const before = cap.karma;
    const entry = { key: 'frigate', data: ship.serialise() };
    const rep = Base.returnFromRun({ shipEntry: entry, crew: [], cc: 0 });
    ok(rep.buried === 1, `one man laid to rest (${rep.buried})`);
    ok(rep.bounty === 0 && Base.cc() === 0,
       `and the yard pays nothing for him (${rep.bounty} CC)`);
    ok(cap.karma === before + Ship.BURIAL_KARMA,
       `the burial is worth +${Ship.BURIAL_KARMA} karma (${before} → ${cap.karma})`);
    ok(Save.getGraveyard().find(g => g.name === victim.name).buried === true,
       'and the memorial records that he came home');

    /* THE STONE SAYS SO. A field nobody draws is a field the player
       never sees — hover the marker and read the card, the same way
       the service record is tested. */
    {
      const ctx = initRenderer(sb);
      sb.BaseScreen.open();
      sb.BaseScreen._set({ tab: 'MEMORIAL' });
      sb.BaseScreen.draw(ctx);
      const z = sb.BaseScreen._graves().find(g => g.name === victim.name);
      ok(!!z, 'his marker is on the hill');
      sb.Input.mouse.x = z.x + z.w / 2; sb.Input.mouse.y = z.y + z.h / 2;
      const card = captureText(ctx, () => sb.BaseScreen.draw(ctx)).map(d => d.t);
      sb.Input.mouse.x = -100; sb.Input.mouse.y = -100;
      // Exact, not a regex: the heading above the hill contains the
      // same words on every draw. See section 85.
      ok(card.some(t => t === 'brought home and buried'),
         `the card says he came home (${card.filter(t => /home|recovered/.test(t)).join(' / ')})`);
      ok(!card.some(t => /no body recovered/.test(t)),
         'and does not also claim there was no body');
    }

    /* PAID ONCE. The bag leaves the hold with the payment, exactly like
       a bounty — the same shape that stops a man being handed in twice. */
    const again = Base.returnFromRun({ shipEntry: entry, crew: [], cc: 0 });
    ok(again.buried === 0, 'docking the same hull again buries nobody');
    ok(cap.karma === before + Ship.BURIAL_KARMA, 'and pays no more karma');

    /* AND THE MARK ITSELF REFUSES A SECOND TIME. The dock cannot reach
       this twice today — the bag leaves the hold with the payment — so
       the guard is only visible through the function's own contract.
       It is exported, so that contract is a real thing to test rather
       than a line nobody can break. */
    ok(Save.markBuried(grave.id, grave.name) === false,
       'marking a man who is already buried does nothing');
    ok(Save.markBuried('nobody', 'Nobody At All') === false,
       'and a name nobody died under is refused too');
  }

  /* AND A BOUNTY BAG IS STILL A BOUNTY BAG. One item, two reasons —
     if the burial branch swallowed both, a wanted man would come home
     for karma instead of CC. */
  {
    Save.reset(); Save.load(); Save.startRun();
    seat();
    Base.spend(Base.cc());
    const ship = new Ship('frigate', true, 0, 0);
    ship.cargo.add('body_bag', { name: 'Garro', bounty: 70 });
    const rep = Base.returnFromRun({
      shipEntry: { key: 'frigate', data: ship.serialise() }, crew: [], cc: 0 });
    ok(rep.bounty === 70, `a wanted man still pays CC (${rep.bounty})`);
    ok(rep.buried === 0, 'and is not buried with the crew');
  }

  Commander.setActive(null);
})();

// ============================================================
section('221. The body menu: one set of rectangles, drawing and clicking');
// ============================================================
(function testBodyMenuGeometry() {
  const sb = loadEngine();
  const { Renderer, Ship, Save } = sb;
  const ctx = initRenderer(sb);
  Save.load();

  const R = Renderer.bodyMenuRects(400, 300);
  ok(R.items.length === 3, `three rows (${R.items.length})`);
  ok(R.items.map(i => i.act).join(',') === 'treat,eject,bag', 'in the order the player reads');

  /* NO TWO ROWS OVERLAP. The rule that came out of the RENAME button
     landing on the skill pips twice in one package. */
  for (let i = 0; i < R.items.length; i++) {
    for (let j = i + 1; j < R.items.length; j++) {
      const a = R.items[i], b = R.items[j];
      const over = a.x < b.x + b.w && b.x < a.x + a.w &&
                   a.y < b.y + b.h && b.y < a.y + a.h;
      ok(!over, `${a.act} and ${b.act} do not overlap`);
    }
  }
  // Every row is inside its own panel.
  R.items.forEach(it => {
    ok(it.x >= R.panel.x && it.x + it.w <= R.panel.x + R.panel.w &&
       it.y >= R.panel.y && it.y + it.h <= R.panel.y + R.panel.h,
       `${it.act} sits inside the panel`);
  });

  /* IT NEVER OPENS OFF THE EDGE. A body can lie anywhere on either
     hull, including hard against the right edge of the screen. */
  [[0, 0], [1279, 719], [1279, 0], [0, 719], [640, 700]].forEach(([x, y]) => {
    const r = Renderer.bodyMenuRects(x, y);
    ok(r.panel.x >= 0 && r.panel.y >= 0 &&
       r.panel.x + r.panel.w <= 1280 && r.panel.y + r.panel.h <= 720,
       `a menu opened at ${x},${y} stays on screen`);
  });

  /* THE DRAWING READS THE SAME RECTANGLES. Capture the text and check
     each label lands inside the row that claims it — a second copy of
     this geometry is exactly what this test exists to catch. */
  const drawn = captureText(ctx, () =>
    Renderer.drawBodyMenu(ctx, 400, 300, 'Ada', () => null));
  ['TREAT', 'EJECT', 'BAG'].forEach(label => {
    const hit = drawn.find(d => d.t === label);
    ok(!!hit, `${label} is drawn`);
    const row = R.items.find(i => i.act === label.toLowerCase());
    ok(hit && hit.x >= row.x && hit.x <= row.x + row.w &&
       hit.y >= row.y && hit.y <= row.y + row.h + 2,
       `${label} is drawn inside its own rectangle`);
  });

  /* THE MENU IS SMALL, and the reason went to the notification line
     (update68). At 150px wide with the refusal printed on every row it
     covered the room the player was looking at — his words: "za duże za
     długie ze wszystkimi napisami". A greyed row still says NO on
     sight; clicking it says WHY, which is tested with the click below. */
  ok(R.panel.w <= 90, `the panel is narrow enough to sit over a room (${R.panel.w}px)`);
  ok(R.panel.h <= 60, `and short (${R.panel.h}px)`);
  const withWhy = captureText(ctx, () =>
    Renderer.drawBodyMenu(ctx, 400, 300, 'Ada',
      (act) => act === 'bag' ? 'no room in the hold' : null)).map(d => d.t);
  ok(withWhy.join('|') === 'TREAT|EJECT|BAG',
     `only the three labels are drawn, nothing else (${withWhy.join(' / ')})`);

  /* ── A GREYED ROW IS NOT CLICKABLE ─────────────────────────
   *
   * The drawing asks `bodyRefusal` for every row and so does the hit
   * test — but only the DRAWING was tested, so a hit test that had
   * stopped asking would still grey the row and then carry the order
   * out anyway. That is worse than a live button: the player is told
   * no and the game does it.
   */
  {
    const T = sb.Game.__test;
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const air = ship.doors.find(d => d.isAirlock);
    air.mode = 'closed'; air.open = false; air.openness = 0;
    /* A CASUALTY, not a corpse (update78). The rows follow the state
       now — a body is offered what you do with a body — so the refused
       row that proves the point is TREAT on a hull with no medbay, and
       the live one beside it is MEDKIT. */
    const victim = ship.crew[0];
    victim.hp = 1; victim.state = 'injured';
    ship.crew.filter(c => c !== victim).forEach(c => { c.roomId = victim.roomId; });
    ship.systems = ship.systems.filter(sy => sy.type !== 'medbay');
    ship.cargo.add('medkit');
    T.playerShip = ship;
    T.bodyMenu = { id: victim.id, x: 400, y: 300 };

    const acts = T._menuActsFor(victim);
    const rows = Renderer.bodyMenuRects(400, 300, acts).items;
    const mid = (r) => [r.x + r.w / 2, r.y + r.h / 2];

    ok(ship.bodyRefusal(victim, 'treat') !== null,
       'TREAT is refused with no medbay aboard');

    /* THE ROW IS STILL HIT — and that is deliberate since update68.
       The reason no longer fits on the row, so the click is what
       delivers it; a row that swallowed the click in silence would be
       the same "greyed with no explanation" bug in a new place. */
    const treatHit = T._bodyMenuHit(...mid(rows.find(r => r.act === 'treat')));
    ok(treatHit && treatHit.act === 'treat', 'clicking it is registered');
    ok(ship.menuRefusal(victim, treatHit.act) !== null,
       'and the game has a sentence ready for why it will not happen');

    ok(ship.bodyRefusal(victim, 'medkit') === null, 'MEDKIT is allowed');
    const hit = T._bodyMenuHit(...mid(rows.find(r => r.act === 'medkit')));
    ok(hit && hit.act === 'medkit', 'and its row IS clickable');
    ok(T._bodyMenuHit(rows[0].x - 40, rows[0].y - 40) === null,
       'a click outside every row hits nothing');
    T.bodyMenu = null;
  }
})();


// ============================================================
section('222. A poster is pinned to a NODE, and the map shows it');
// ============================================================
(function testWantedOnMap() {
  const sb = loadEngine();
  const { Save, SectorMap } = sb;
  Save.reset(); Save.load(); Save.startRun();
  const poster = Save.wanted()[0];

  /* SOME SECTORS, NOT ALL. A hunt where every sector holds your man is
     a queue; one where none does is a lottery again. Counted over forty
     seeds, which is deterministic — the map has its own RNG. */
  let carrying = 0;
  for (let seed = 0; seed < 40; seed++) {
    if (new SectorMap(2, seed, 1, 3, true).wantedNode()) carrying++;
  }
  ok(carrying > 5, `some sectors carry a poster (${carrying} of 40)`);
  ok(carrying < 35, 'and some do not — flying on is part of the hunt');

  /* THE SAME SEED IS THE SAME SECTOR. A map is REBUILT from `run.seed`
     every time the game is loaded, so a poster placed with a loose
     Math.random would move the moment the player saved and came back —
     and a save-scummable hunt is not a hunt. */
  let hitSeed = null;
  for (let seed = 0; seed < 40 && hitSeed === null; seed++) {
    if (new SectorMap(2, seed, 1, 3, true).wantedNode()) hitSeed = seed;
  }
  ok(hitSeed !== null, `seed ${hitSeed} puts him on the map`);

  /* EVERY SEED, not one. Checking a single sector was a coin toss
     dressed as a test: a sector with only one eligible fight node puts
     him on the same node however he is picked, so an unseeded build
     matched anyway. Across forty sectors there are plenty with a
     choice, and a loose Math.random cannot agree with itself twice on
     all of them. */
  let rebuilt = 0, differed = 0;
  for (let seed = 0; seed < 40; seed++) {
    const a = new SectorMap(2, seed, 1, 3, true).wantedNode();
    const b = new SectorMap(2, seed, 1, 3, true).wantedNode();
    if (!a && !b) continue;
    rebuilt++;
    if (!a || !b || a.id !== b.id || a.wantedId !== b.wantedId) differed++;
  }
  ok(rebuilt > 5, `enough sectors to judge by (${rebuilt} carried a poster)`);
  ok(differed === 0,
     `rebuilding a sector puts the same man on the same node, every time (${differed} moved)`);

  // Never the boss, never the first hop.
  for (let seed = 0; seed < 60; seed++) {
    const n = new SectorMap(2, seed, 1, 3, true).wantedNode();
    if (!n) continue;
    ok(!n.isBoss && !n.isExit && n.col > 1,
       `a poster never lands on the boss or the first hop (col ${n.col})`);
    break;
  }

  /* ONE REGISTER, STILL. The node carries an ID and reads the board
     through it — hand the man in and the same node stops naming him. */
  const node = new SectorMap(2, hitSeed, 1, 3, true).wantedNode();
  const named = Save.wantedById(node.wantedId);
  ok(!!named, 'the node points at a real poster');
  ok(node.label === named.name, `and shows his name, not "Enemy" (${node.label})`);
  ok(node.icon === '☠', `with a marker of its own (${node.icon})`);
  ok(node.color !== sb.NODE_TYPES.combat.color, 'in a colour of its own');

  Save.deliverWanted(node.wantedId, 0);
  ok(node.wanted === null, 'hand him in and the node stops pointing at anybody');
  ok(node.label === 'Enemy', `it is an ordinary fight again (${node.label})`);
  ok(node.icon === sb.NODE_TYPES.combat.icon, 'with the ordinary marker back');

  // An empty board puts nobody anywhere.
  Save.wanted().forEach(w => Save.deliverWanted(w.id, 0));
  let any = 0;
  for (let seed = 0; seed < 20; seed++) {
    if (new SectorMap(2, seed, 1, 3, true).wantedNode()) any++;
  }
  ok(any === 0, `an empty board seats nobody on any map (${any} of 20)`);
})();

// ============================================================
section('223. The fight reads the node — no second roll anywhere');
// ============================================================
(function testNodeDecidesFight() {
  const sb = loadEngine();
  const { Save, SectorMap, Commander } = sb;

  const onNode = (T, posterId) => {
    const map = new SectorMap(2, 7, 1, 3, true);
    const node = map.nodes.find(n => n.type === 'combat' && !n.isBoss) || map.nodes[1];
    map.nodes.forEach(n => { n.wantedId = null; });
    node.wantedId = posterId;
    map.currentId = node.id;
    T.sectorMap = map;
    return node;
  };
  const withRandom = (v, fn) => {
    const real = Math.random;
    Math.random = () => v;
    try { return fn(); } finally { Math.random = real; }
  };

  /* HIS NODE, HIS FIGHT — whatever the dice say. If a roll were still
     in there, one of these two would come out wrong. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    [0.0, 0.99].forEach(roll => {
      const c = makeCombat(sb);
      onNode(c.T, poster.id);
      withRandom(roll, () => c.T._startCombat('normal', false));
      ok(Commander.enemy() && Commander.enemy().wantedId === poster.id,
         `standing on his node seats him with a roll of ${roll}`);
    });
  }

  /* AN ORDINARY NODE IS AN ORDINARY FIGHT — again whatever the dice
     say. This is the assertion that would fail if the old 35% roll
     were still alive beside the map. */
  {
    Save.reset(); Save.load(); Save.startRun();
    [0.0, 0.99].forEach(roll => {
      const c = makeCombat(sb);
      onNode(c.T, null);
      withRandom(roll, () => c.T._startCombat('normal', false));
      const foe = Commander.enemy();
      ok(!foe || !foe.wantedId,
         `an ordinary node seats nobody off the board with a roll of ${roll}`);
    });
  }

  // Meeting him marks the ONE record, with the sector he was seen in.
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    const c = makeCombat(sb);
    /* AFTER makeCombat: it calls startRun, which would wipe a sector
       set before it — and the assertion below would then be reading
       the default rather than anything this test arranged. */
    Save.updateRun({ sector: 3 });
    onNode(c.T, poster.id);
    withRandom(0.0, () => c.T._startCombat('normal', false));
    const rec = Save.wantedById(poster.id);
    ok(rec.state === 'sighted', 'the board records the sighting');
    ok(rec.sector === 3, `and how deep he was seen (${rec.sector})`);
    ok(Save.wanted().filter(w => w.name === poster.name).length === 1,
       'and there is still exactly one record of him');
  }
  Commander.setEnemy(null);
})();

// ============================================================
section('224. Four rations, and the difference is cells');
// ============================================================
(function testRations() {
  const sb = loadEngine();
  const { CARGO_ITEMS, CargoItem, Ship, Save, HUNGER } = sb;
  Save.load(); Save.startRun();

  const R = ['protein_paste', 'ration_pack', 'field_meal', 'green_ration'];
  R.forEach(k => ok(!!CARGO_ITEMS[k], `${k} exists`));
  ok(R.every(k => CARGO_ITEMS[k].tag === 'food'), 'and every one of them is food');

  ok(CARGO_ITEMS.ration_pack.hunger === 50,
     `the standard pack is UNCHANGED at 50 (${CARGO_ITEMS.ration_pack.hunger})`);
  ok(CARGO_ITEMS.protein_paste.hunger === 25, 'paste is half a meal');
  ok(CARGO_ITEMS.field_meal.hunger === 80, 'a field meal is most of one');
  ok(CARGO_ITEMS.green_ration.hunger === 50, 'greens feed like the standard pack');

  /* THE DIFFERENCE IS THE HOLD, not the price per point — that is the
     whole design. A field meal feeds 60% better and costs a second
     cell of a hold you were going to put salvage in. */
  ok(new CargoItem('field_meal').w * new CargoItem('field_meal').h === 2,
     'a field meal takes two cells');
  ['protein_paste', 'ration_pack', 'green_ration'].forEach(k =>
    ok(new CargoItem(k).w * new CargoItem(k).h === 1, `${k} takes one`));

  ok(CARGO_ITEMS.green_ration.unitValue > CARGO_ITEMS.ration_pack.unitValue,
     'greens cost more than the standard pack');
  ok(CARGO_ITEMS.protein_paste.unitValue < CARGO_ITEMS.ration_pack.unitValue,
     'and paste costs less');

  /* THE OLD TABLE IS GONE. `HUNGER.FOOD.ration` was a second copy of
     what a meal is worth; with four rations there is no "the" ration
     to look up, and a stale copy would have fed everyone the same. */
  ok(HUNGER.FOOD.ration === undefined,
     'HUNGER.FOOD no longer keeps a ration figure of its own');
  ok(HUNGER.FOOD.rat && HUNGER.FOOD.spider_egg,
     'but rats and eggs stay there — they are not cargo');

  // Eating reads the box, not a table.
  const feedOn = (key) => {
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    ship.cargo.items.length = 0;
    ship.cargo.add(key);
    const who = ship.crew[0];
    who.hunger = 10;
    const before = who.hunger;
    ok(ship.feedCrew(who).ok, `${who.name} starts on the ${CARGO_ITEMS[key].label}`);
    // The meal timer is the ship's one busy timer now (update78), so
    // the meal is finished by that and not by the hunger tick.
    for (let i = 0; i < 40 && who.busy; i++) ship._busyTick(0.2);
    return who.hunger - before;
  };
  const gainPaste = feedOn('protein_paste');
  const gainField = feedOn('field_meal');
  ok(gainField > gainPaste,
     `a field meal really feeds better than paste (${gainField} vs ${gainPaste})`);
  ok(gainPaste === 25, `and paste feeds exactly what its box says (${gainPaste})`);
})();

// ============================================================
section('225. The cat has opinions, and FEED is an order');
// ============================================================
(function testFeedOrder() {
  const sb = loadEngine();
  const { Ship, Save, CARGO_ITEMS } = sb;
  Save.load(); Save.startRun();

  const build = () => {
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    ship.cargo.items.length = 0;
    return ship;
  };

  /* THE CAT IS WHY `meat` IS NOT A DEAD FLAG. Crew beliefs are a later
     package; the animal reads the same field today, so the rule is
     live rather than waiting in the dark for religions to arrive. */
  {
    const ship = build();
    const cat = typeof sb.makeCat === 'function' ? sb.makeCat('black') : null;
    ok(!!cat, 'there is a cat');
    ship.addCrew(cat);
    const greens = ship.cargo.add('green_ration');
    ok(ship.willEat(ship.crew[0], greens) === true, 'a crewman eats greens');
    ok(ship.willEat(cat, greens) === false, 'the cat does not');
    cat.hunger = 10;
    const r = ship.feedCrew(cat);
    ok(!r.ok, `and refuses the order out loud (${r.message})`);
    ok(/will not touch|nothing aboard/.test(r.message), 'saying why');

    // Give him meat and he eats.
    ship.cargo.add('ration_pack');
    ok(ship.feedCrew(cat).ok, 'meat aboard and the cat eats');
  }

  /* A HUNGRY MAN HELPS HIMSELF — but not to something he will not
     touch. The automatic meal asks the same question the order does. */
  {
    const ship = build();
    const cat = sb.makeCat('ginger');
    ship.addCrew(cat);
    ship.cargo.add('green_ration');
    cat.hunger = 5;
    /* TWO THINGS THIS HAD TO LEARN.
       1. The cat eats through `petTick`, not `hungerTick` — the crew
          feed themselves in one and the animal is handled in the other,
          so driving only the crew path never offered it anything.
       2. Assert on HUNGER and on the STACK, not on `_meal`. A meal
          started and finished inside the loop leaves `_meal` null again,
          and a ration box is a stack of five, so eating one leaves the
          box on the shelf with four in it. Both of the obvious
          assertions were true on a build where the cat ate.
       3. AND THE MEAL IS FINISHED BY `_busyTick` (update78). A meal
          takes a few seconds now: the stack is not touched until the
          timer runs out, so a loop that never ticks the busy clock
          left the box full whether the cat opened it or not — which
          is a test that passes for the wrong reason, and the breaking
          run said so. */
    const boxBefore = ship.cargo.items.find(it => it.defKey === 'green_ration').qty;
    for (let i = 0; i < 50; i++) {
      ship.petTick(0.2); ship.hungerTick(0.2); ship._busyTick(0.2);
    }
    ok(cat.hunger <= 5,
       `a starving cat does not open the greens on its own (hunger ${cat.hunger})`);
    const box = ship.cargo.items.find(it => it.defKey === 'green_ration');
    ok(!!box && box.qty === boxBefore,
       `and not one meal is gone from the box (${box && box.qty} of ${boxBefore})`);
  }

  /* FEED REFUSES OUT LOUD, and the menu greys the row with the SAME
     sentence — the shape that came out of the body menu in update65. */
  {
    const ship = build();
    const who = ship.crew[0];
    who.hunger = 100;
    ok(/not hungry/.test(ship.feedRefusal(who)), 'a full man is not fed');
    ok(ship.feedCrew(who).message === ship.feedRefusal(who),
       'and the order says exactly what the menu says');
    who.hunger = 10;
    ok(/nothing aboard/.test(ship.feedRefusal(who)), 'an empty hold refuses too');
    ship.cargo.add('ration_pack');
    ok(ship.feedRefusal(who) === null, 'with food aboard the row goes live');
    ok(ship.feedCrew(who).ok, 'and the order takes');
    ok(/hands full/.test(ship.feedRefusal(who)), 'a man mid-meal is not fed twice');
    ok(ship.menuRefusal(who, 'feed') === ship.feedRefusal(who),
       'and the menu asks through the same door');
  }

  /* THE MENU FOLLOWS HIS STATE. A man on his feet gets FEED; a man on
     the floor gets the three from update65. Four permanent rows with
     three dead ones would be mostly noise. */
  {
    const T = sb.Game.__test;
    const ship = build();
    T.playerShip = ship;
    const up = ship.crew[0];
    const down = ship.crew[1];
    down.hp = 0; down.state = 'dead'; down.dead = true;
    ok(T._menuActsFor(up).join(',') === 'feed,heal', 'a man on his feet is offered FEED — and HEAL, a dose (update97)');
    ok(T._menuActsFor(down).join(',') === 'eject,bag',
       'and a BODY the two things you do with a body (update78)');
    ok(sb.Renderer.bodyMenuRects(400, 300, T._menuActsFor(up)).items.length === 2,
       'so his menu has two rows, not four');
  }
})();

// ============================================================
section('226. A port sells meals, and only the ones it has');
// ============================================================
(function testRationShop() {
  const sb = loadEngine();
  const { Station, Ship, Save, CARGO_ITEMS } = sb;
  Save.load(); Save.startRun();

  /* EVERY PORT HAS SOMETHING TO EAT. A station stocking nothing at all
     would be a place a low run could strand at with a full purse. */
  let empties = 0, kinds = new Set();
  for (let seed = 0; seed < 40; seed++) {
    const st = new Station(2, seed);
    const have = Object.keys(st.stock.rations || {});
    if (!have.length) empties++;
    have.forEach(k => kinds.add(k));
  }
  ok(empties === 0, `no port is out of food entirely (${empties} of 40 were)`);
  ok(kinds.size === 4, `and all four kinds turn up across the ports (${[...kinds].join(', ')})`);

  /* NOT EVERY PORT HAS EVERYTHING — otherwise the four kinds are a
     shopping list rather than a packing decision. */
  let partial = 0;
  for (let seed = 0; seed < 40; seed++) {
    if (Object.keys(new Station(2, seed).stock.rations).length < 4) partial++;
  }
  ok(partial > 0, `most ports carry only some of them (${partial} of 40)`);

  // Buying: charged for what fits, and it lands in the hold.
  {
    const st = new Station(2, 3);
    st.stock.rations = { field_meal: 5 };
    const ship = new Ship('hauler', true, 0, 0);
    ship.cargo.items.length = 0;
    Save.updateRun({ scrap: 5000 });
    const before = Save.getRun().scrap;
    const quote = st.rationCost('field_meal', 2);
    const r = st.buyRations('field_meal', 2, Save.getRun(), ship);
    ok(r.ok, `two field meals bought (${r.message})`);
    ok(r.cost === quote, `charged the quoted price (${r.cost} vs ${quote})`);
    ok(Save.getRun().scrap === before - quote, 'and the CC really left the purse');
    ok(ship.cargo.countOf('food') === 2, 'two meals in the hold');
    ok(st.stock.rations.field_meal === 3, 'and three left at the port');
  }

  // A full hold refuses before any money moves.
  {
    const st = new Station(2, 3);
    st.stock.rations = { field_meal: 5 };
    const ship = new Ship('frigate', true, 0, 0);
    let guard = 0;
    while (ship.cargo.add('he3_ore') && guard++ < 400) { /* pack it solid */ }
    Save.updateRun({ scrap: 5000 });
    const before = Save.getRun().scrap;
    const r = st.buyRations('field_meal', 2, Save.getRun(), ship);
    ok(!r.ok, `a full hold is refused (${r.message})`);
    ok(Save.getRun().scrap === before, 'and not one CC moved');
  }

  // Not food, not sold here.
  {
    const st = new Station(2, 3);
    /* PUT THE ORE IN THE RATION STOCK. Without this the counter refuses
       it for having none in stock, which is the RIGHT answer for the
       WRONG reason — and the tag check it is meant to prove could be
       deleted with this test still green. */
    st.stock.rations = { he3_ore: 5 };
    const r = st.buyRations('he3_ore', 1, Save.getRun(), new Ship('hauler', true, 0, 0));
    ok(!r.ok, `the ration counter does not sell ore (${r.message})`);
    ok(/not food/i.test(r.message), 'and says that is why, not that it is out of stock');
  }
})();


// ============================================================
section('227. The medbay really is in the hangar (the ghost bug)');
// ============================================================
(function testMedbayInHangar() {
  const sb = loadEngine();
  const { Ship, Station, Base, BaseScreen, Save } = sb;
  const ctx = initRenderer(sb);

  /* ── THE BUG THAT WOULD NOT REPRODUCE ──────────────────────
   *
   * The player reported after update58 that a medbay module bought in
   * flight was not shown in the hangar when he docked. It has been
   * hunted across five packages and never once reproduced: the data
   * survives, the save survives, and the screen draws it.
   *
   * So this is not a fix — it is the door nailed shut. It walks the
   * WHOLE chain the report describes, on every hull, and ends by
   * reading the text the base screen actually draws. If this ever
   * breaks, it breaks here instead of in somebody's run.
   */
  ['scout', 'hauler', 'frigate'].forEach(key => {
    Save.load(); Save.startRun(); Save.updateRun({ scrap: 9999 });
    const b = Base.get();
    b.ships.length = 0;

    // She launches, so the hangar is empty while she is out.
    const flying = new Ship(key, true, 0, 0);
    const hadOne = !!flying.getSystem('medbay');

    // Bought AT A STATION, into a room the player clicked — the exact
    // path the report describes.
    if (!hadOne) {
      const st = new Station(2, 4);
      st.stock.newModules = [{ type: 'medbay', cost: 10, sold: false }];
      const room = flying.rooms.find(r => r.type === 'empty');
      const r = st.buyNewModuleAt(0, flying, Save.getRun(), room.id);
      ok(r.ok, `${key}: a medbay is bought at the station (${r.message})`);
    }
    ok(!!flying.getSystem('medbay'), `${key}: she is flying with a medbay`);

    // …and comes home.
    Base.returnFromRun({ shipEntry: { key, data: flying.serialise() }, crew: [], cc: 0 });
    const entry = Base.get().ships[0];
    ok(!!entry, `${key}: the hull docked`);
    ok((entry.data.systems || []).some(sy => sy.type === 'medbay'),
       `${key}: the medbay is in her saved record`);
    ok(BaseScreen._levels(entry).some(m => m.type === 'medbay'),
       `${key}: and in what the hangar reads off her`);

    /* AND IT REACHES THE GLASS. Every check above could pass with a
       screen that never draws the module strip — which is what the
       report actually described. */
    BaseScreen.open();
    BaseScreen._set({ tab: 'HANGAR', shipIdx: 0 });
    const drawn = captureText(ctx, () => BaseScreen.draw(ctx));
    const hits = drawn.filter(d => /^MEDBAY$/.test(d.t));      // the card names modules as the ship does (update154)
    /* TWICE, and that is the point of the count. Every module on this
       screen is named in TWO places — once on the hull blueprint and
       once in the MODULE STRIP beside it. Asserting only that the word
       appears somewhere passed on a build whose strip had been cut
       short: the blueprint still said "Medbay" and the list did not.
       The report was about the LIST. */
    /* update90a: the blueprint draws the modules themselves, and a
       module no longer prints its name (the badge does that job) — so
       the word is in the LIST, which is what the report was about. */
    ok(hits.length >= 1,
       `${key}: Medbay is named in the module list`
       + ` (${hits.length} places)`);
    ok(hits.every(h => h.y > 0 && h.y < 720 && h.x > 0 && h.x < 1280),
       `${key}: both on screen, not off the bottom of the card`
       + ` (${hits.map(h => `${Math.round(h.x)},${Math.round(h.y)}`).join(' ')})`);
  });

  /* ══ THE GHOST, CAUGHT (update68) ═══════════════════════════
   *
   * Every hunt above starts with a COLD screen: build the hull, draw
   * it once, and of course the module is there. The bug needed a WARM
   * one — and that is why it survived five packages.
   *
   * `_previewShip` cached the drawn hull under a key made of the berth
   * index, the hull key, the chosen crew and the position — everything
   * except WHAT THE HULL IS. So: look at the hangar, launch, buy a
   * medbay, come home to the same berth with the same crew, and the
   * key matches the one already cached. The screen draws the ship as
   * she was BEFORE the run. It rights itself next time because by then
   * the crew or the berth has changed.
   *
   * DRAW FIRST. That one line is the whole test.
   */
  {
    Save.load();
    const b = Base.get();
    b.ships.length = 0;
    const before = new Ship('scout', true, 0, 0);
    b.ships.push({ key: 'scout', data: before.serialise() });
    BaseScreen.open();
    BaseScreen._set({ tab: 'HANGAR', shipIdx: 0 });

    const seen = () => captureText(ctx, () => BaseScreen.draw(ctx))
      .map(d => d.t).filter(t => t === 'MEDBAY').length;

    ok(seen() === 0, 'she has no medbay, and the hangar has now been LOOKED AT');
    /* THE PICTURE, NOT THE LIST (update129). The module list reads
       `_entryShip`, which was always keyed on the data — so counting
       'Medbay' in the list passed even with the old berth-only key on
       the picture, and the revert slept (break_check #68). Ask the
       picture itself: it is warm now, and it has no medbay. */
    const pic0 = BaseScreen.loadoutShip();
    ok(pic0 && !pic0.getSystem('medbay'),
       'the hull PICTURE is drawn and cached — and has no medbay yet');

    // …the run: same berth, same crew, one module heavier.
    const flown = Ship.deserialise(b.ships[0].data, true, 0, 0);
    ok(flown.addModuleAt('medbay', flown.rooms.find(r => r.type === 'empty').id),
       'a medbay goes in out there');
    b.ships[0] = { key: 'scout', data: flown.serialise() };

    ok(seen() === 1,
       `and she is drawn WITH it the moment she docks — in the module list (the blueprint no longer prints names, update90a)`
       + ` (${seen()} places)`);
    const pic1 = BaseScreen.loadoutShip();
    ok(pic1 && pic1 !== pic0 && pic1.getSystem('medbay'),
       'and the PICTURE is redrawn with the medbay too — same berth, same crew, warm cache (#68)');
  }

  /* A HULL CARRYING EVERYTHING. The likeliest surviving explanation is
     a module strip that outgrows its card — so load one up and check
     the LAST module still lands on screen. */
  {
    Save.load();
    const b = Base.get();
    b.ships.length = 0;
    const sh = new Ship('hauler', true, 0, 0);
    ['medbay', 'shields', 'cloaking'].forEach(t => {
      const r = sh.rooms.find(x => x.type === 'empty');
      if (r) sh.addModuleAt(t, r.id);
    });
    ok(sh.systems.length >= 8, `a fully fitted hauler carries ${sh.systems.length} modules`);
    b.ships.push({ key: 'hauler', data: sh.serialise() });
    BaseScreen.open();
    BaseScreen._set({ tab: 'HANGAR', shipIdx: 0 });
    const drawn = captureText(ctx, () => BaseScreen.draw(ctx));
    ['MEDBAY', 'SHIELDS', 'CLOAK'].forEach(label => {
      const on = drawn.filter(d => d.t === label && d.y > 0 && d.y < 720);
      ok(on.length >= 1,
         `${label} is still in the module list on a loaded hull (${on.length})`);
    });
  }
})();

// ============================================================
section('228. A prisoner eats, and starving him costs you half');
// ============================================================
(function testPrisonerEats() {
  const sb = loadEngine();
  const { Ship, Save } = sb;
  Save.load(); Save.startRun();

  const withPrisoner = ({ food = 0 } = {}) => {
    const ship = new Ship('hauler', true, 0, 0);
    const room = ship.rooms.find(r => r.type === 'empty');
    ship.addModuleAt('carbonite', room.id);
    const brig = ship.getSystem('carbonite');
    brig.level = 2; brig.power = 2; brig.desiredPower = 2;
    ship.cargo.items.length = 0;
    for (let i = 0; i < food; i++) ship.cargo.add('ration_pack', null, 1);
    ship.takePrisoner({ id: 'g', name: 'Garro', bounty: 200, wantedId: 'w1' });
    return ship;
  };

  // Fed: a meal leaves the hold, he stays.
  {
    const ship = withPrisoner({ food: 2 });
    const before = ship.cargo.countOf('food');
    const r = ship.feedPrisoners();
    ok(r.fed === 1, `one meal served (${r.fed})`);
    ok(ship.cargo.countOf('food') === before - 1,
       `and it came out of the hold (${before} → ${ship.cargo.countOf('food')})`);
    ok(ship.prisoners.length === 1, 'he is still in the cell');
    ok(r.starved.length === 0, 'and nobody starved');
  }

  /* NOTHING TO EAT: he dies, and he is worth HALF as a body — the same
     pair of prices as everywhere else, so starving him is a loss
     rather than a tidy way out of feeding him. */
  {
    const ship = withPrisoner({ food: 0 });
    const r = ship.feedPrisoners();
    ok(r.starved.length === 1, `he starved (${r.starved.join(', ')})`);
    ok(ship.prisoners.length === 0, 'the cell is empty');
    const bag = ship.cargo.items.find(it => it.def.tag === 'body');
    ok(!!bag, 'and his body is in the hold');
    ok(bag.meta.bounty === 100, `worth half of 200 (${bag.meta.bounty})`);
    ok(bag.meta.wantedId === 'w1', 'and it still closes his poster');
  }

  // A full hold: he dies and there is nowhere to put him. Still gone.
  {
    const ship = withPrisoner({ food: 0 });
    let guard = 0;
    while (ship.cargo.add('he3_ore') && guard++ < 400) { /* pack it solid */ }
    const r = ship.feedPrisoners();
    ok(r.starved.length === 1, 'he starves either way');
    ok(r.bagged === 0, 'and there was no room for the body');
    ok(ship.prisoners.length === 0, 'the cell is empty all the same');
  }

  /* ── AND THE JUMP IS WHAT FEEDS THEM ───────────────────────
   *
   * Every case above calls `feedPrisoners` by hand, which proves the
   * rule and nothing about whether the GAME ever asks. Deleting the
   * one line in `_nextSector` left all of them green — the prisoner
   * simply never got hungry for the rest of the run.
   */
  {
    const T = sb.Game.__test;
    Save.load(); Save.startRun();
    Save.updateRun({ sector: 1, finalSector: 3, mission: 'mothership' });
    const ship = withPrisoner({ food: 2 });
    T.playerShip = ship;
    const before = ship.cargo.countOf('food');
    T._nextSector();
    ok(Save.getRun().sector === 2, 'the ship jumps to the next sector');
    ok(ship.cargo.countOf('food') === before - 1,
       `and the jump took a meal for the brig (${before} → ${ship.cargo.countOf('food')})`);
    ok(ship.prisoners.length === 1, 'the prisoner is fed and still aboard');

    // Jump again with nothing left and he starves on the way.
    ship.cargo.items.length = 0;
    T._nextSector();
    ok(ship.prisoners.length === 0, 'a jump with an empty hold starves him');
  }

  // An empty brig is not a per-jump chore.
  {
    const ship = new Ship('hauler', true, 0, 0);
    const r = ship.feedPrisoners();
    ok(r.fed === 0 && r.starved.length === 0, 'a hull with no prisoners does nothing');
  }

  // Two men, one meal: one eats, one does not.
  {
    const ship = withPrisoner({ food: 1 });
    ship.takePrisoner({ id: 'h', name: 'Vex', bounty: 100 });
    const r = ship.feedPrisoners();
    ok(r.fed === 1 && r.starved.length === 1,
       `one fed, one starved (${r.fed} / ${r.starved.join(', ')})`);
    ok(ship.prisoners.length === 1, 'and one is left in the cells');
  }
})();

// ============================================================
section('229. An escaper goes back on the board, dearer');
// ============================================================
(function testReWanted() {
  const sb = loadEngine();
  const { Ship, Save, UI } = sb;

  const build = () => {
    const ship = new Ship('hauler', true, 0, 0);
    const room = ship.rooms.find(r => r.type === 'empty');
    ship.addModuleAt('carbonite', room.id);
    const brig = ship.getSystem('carbonite');
    powerModule(ship, 'carbonite', 1);
    return { ship, brig };
  };
  /* ── OUT OF THE CELL IS NOT OFF THE SHIP (update72) ────────
   *
   * The escape is two stages now. The cell clock puts a MAN on the
   * deck, and the man has to walk to an airlock — which is the whole
   * point of the change, because a walk can be interrupted by a door
   * and the line of text it used to be could not.
   *
   * The board is written when he is actually GONE, so every assertion
   * in this section runs him all the way off the hull. Bounded, and
   * the assertion below fails rather than hangs if he never gets
   * there — a hang is the one failure a breaking run cannot report. */
  const runOut = (ship) => {
    for (let i = 0; i < Ship.ESCAPE_SECONDS + 5; i++) ship.prisonerTick(1);
    for (let i = 0; i < 4000 && ship.crew.some(c => c.isPrisoner); i++) ship.update(0.05);
    return !ship.crew.some(c => c.isPrisoner);
  };

  /* A MAN WHO WAS ON THE BOARD GOES BACK, DEARER. He has cost the
     player a powered cell and a run of rations and got away with it. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    /* SNAPSHOT THE NUMBERS. `wantedById` hands back the LIVE record —
       that is the one-register rule working — so comparing against
       `poster.level` after the escape compares the new value with
       itself and passes on a build that changes nothing. */
    const was = poster.bounty, wasLevel = poster.level;
    // Caught: he leaves the board only at the dock, so he is still on it.
    /* SIGHT HIM FIRST. He was caught, so the board has seen him — and
       without that the "back to unsighted" assertion below compares
       'wanted' with 'wanted' and passes on a build that resets
       nothing. */
    Save.markSighted(poster.id, 'luna');
    ok(Save.wantedById(poster.id).state === 'sighted', 'the board has seen him');
    const { ship, brig } = build();
    ship.takePrisoner({ id: 'c', name: poster.name, bounty: was, wantedId: poster.id });
    brig.power = 0; brig.desiredPower = 0;
    runOut(ship);
    ok(ship.prisoners.length === 0, 'he is out');
    const now = Save.wantedById(poster.id);
    ok(!!now, 'and still on the board');
    ok(now.bounty > was, `worth more than he was (${was} → ${now.bounty})`);
    ok(now.bounty === Math.round(was * Save.ESCAPE_BOUNTY_RAISE),
       'by exactly the raise the yard applies');

    /* AND HE IS A HARDER MAN, not just a dearer one (player's call).
       A re-listed pirate who was only worth more would be free money
       for a crew that had already beaten him once. */
    ok(now.escapes === 1, `the board counts the escape (${now.escapes})`);
    ok(now.level === wasLevel + Save.ESCAPE_LEVEL_GAIN,
       `and he comes back ${Save.ESCAPE_LEVEL_GAIN} levels up (${wasLevel} → ${now.level})`);
    ok(now.state === 'wanted',
       'and back to unsighted — where he was caught is not where he is now');
    ok(Save.wanted().filter(w => w.name === poster.name).length === 1,
       'still exactly one record of him, not a second poster');
  }

  /* A MAN WHO WAS NOT ON THE BOARD GOES UP FOR THE FIRST TIME. An
     ordinary enemy commander you caught and then lost is now somebody
     the yard has heard of. */
  {
    Save.reset(); Save.load(); Save.startRun();
    Save.wanted().forEach(w => Save.deliverWanted(w.id, 0));
    ok(Save.wanted().length === 0, 'the board is empty');
    const { ship, brig } = build();
    ship.takePrisoner({ id: 'x', name: 'Nils Harrow', bounty: 120, wantedId: null });
    brig.power = 0; brig.desiredPower = 0;
    runOut(ship);
    ok(Save.wanted().length === 1, 'he goes up for the first time');
    const w = Save.wanted()[0];
    ok(w.name === 'Nils Harrow', `under his own name (${w.name})`);
    ok(w.bounty === Math.round(120 * Save.ESCAPE_BOUNTY_RAISE),
       `dearer than he was worth in the cell (${w.bounty})`);
    ok(w.escapes === 1 && w.level > 5, `and harder than he was (level ${w.level})`);
  }

  /* ESCAPE TWICE AND HE IS WORSE AGAIN. `escapes` is the one register
     this rides on, so it has to keep counting rather than latching. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    const lvl0 = poster.level, cc0 = poster.bounty;
    for (let n = 0; n < 2; n++) {
      const { ship, brig } = build();
      ship.takePrisoner({ id: 'c' + n, name: poster.name,
                          bounty: Save.wantedById(poster.id).bounty, wantedId: poster.id });
      brig.power = 0; brig.desiredPower = 0;
      runOut(ship);
    }
    const now = Save.wantedById(poster.id);
    ok(now.escapes === 2, `two escapes counted (${now.escapes})`);
    ok(now.level === Math.min(24, lvl0 + Save.ESCAPE_LEVEL_GAIN * 2),
       `and he is four levels up (${lvl0} → ${now.level})`);
    ok(now.bounty > cc0 * 2, `and worth far more (${cc0} → ${now.bounty})`);
    ok(now.level <= 24, 'and never past the commander ladder');
  }

  /* THE FIGHT DELIVERS THE MAN THE BOARD PROMISED. A poster that says
     "level 9, better ship" and then seats a level 3 scout is a lie the
     player pays for by preparing for the wrong fight. */
  {
    Save.reset(); Save.load(); Save.startRun();
    /* AFTER makeCombat, not before: it calls `Save.load()`, which
       replaces the whole save object — so a poster doctored first is a
       stale reference and the fight reads the untouched original. The
       same trap as the sector field two sections up. */
    const c = makeCombat(sb);
    const poster = Save.wanted()[0];
    poster.escapes = 1;
    poster.level = 12;
    const map = new sb.SectorMap(2, 7, 1, 3, true);
    const node = map.nodes.find(n => n.type === 'combat' && !n.isBoss) || map.nodes[1];
    map.nodes.forEach(n => { n.wantedId = null; });
    node.wantedId = poster.id;
    map.currentId = node.id;
    c.T.sectorMap = map;
    const real = Math.random;
    Math.random = () => 0;
    try { c.T._startCombat('normal', false); } finally { Math.random = real; }
    const foe = sb.Commander.enemy();
    ok(foe && foe.wantedId === poster.id, 'the escapee is in the fight');
    ok(foe.level === 12, `at the rank the board promised (${foe.level})`);
    const escapeeHull = c.T.enemyShip.hullMax;
    sb.Commander.setEnemy(null);

    /* AND A BETTER SHIP UNDER HIM — the other half of the player's
       decision. The rank above is his COMMANDER; this is the hull and
       the crew, and it comes from the difficulty the node sets before
       the enemy is even spawned. Compared against the SAME sector with
       an ordinary poster, so nothing but the escape differs. */
    Save.reset(); Save.load(); Save.startRun();
    const plain = Save.wanted()[0];
    plain.escapes = 0;
    plain.level = 12;
    const c2 = makeCombat(sb);
    const p2 = Save.wanted()[0];
    p2.escapes = 0; p2.level = 12;
    const map2 = new sb.SectorMap(2, 7, 1, 3, true);
    const n2 = map2.nodes.find(n => n.type === 'combat' && !n.isBoss) || map2.nodes[1];
    map2.nodes.forEach(n => { n.wantedId = null; });
    n2.wantedId = p2.id;
    map2.currentId = n2.id;
    c2.T.sectorMap = map2;
    const real2 = Math.random;
    Math.random = () => 0;
    try { c2.T._startCombat('normal', false); } finally { Math.random = real2; }
    const plainHull = c2.T.enemyShip.hullMax;
    ok(escapeeHull > plainHull,
       `an escapee brings a heavier hull than the same man never caught`
       + ` (${escapeeHull} vs ${plainHull})`);
    sb.Commander.setEnemy(null);
  }

  /* THE CEILING STILL HOLDS. A full board does not grow a fifth poster
     because somebody slipped a cell. */
  {
    Save.reset(); Save.load(); Save.startRun();
    for (let i = 0; i < 10; i++) Save.addWanted(1);
    ok(Save.wanted().length === Save.WANTED_MAX, 'the board is full');
    const { ship, brig } = build();
    ship.takePrisoner({ id: 'y', name: 'Nobody Special', bounty: 90, wantedId: null });
    brig.power = 0; brig.desiredPower = 0;
    runOut(ship);
    ok(Save.wanted().length === Save.WANTED_MAX,
       `and stays full (${Save.wanted().length})`);
    ok(!Save.wanted().some(w => w.name === 'Nobody Special'),
       'he simply got away with it');
  }

  /* AN ENEMY BRIG IS NOT THE YARD'S BUSINESS. Only our own losses go
     up on the board. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const before = Save.wanted().length;
    const ship = new Ship('hauler', false, 0, 0);      // NOT the player's
    const room = ship.rooms.find(r => r.type === 'empty');
    ship.addModuleAt('carbonite', room.id);
    const brig = ship.getSystem('carbonite');
    brig.level = 1; brig.power = 0; brig.desiredPower = 0;
    ship.prisoners.push({ id: 'z', name: 'Theirs', bounty: 90, escapeT: 0, warned: false });
    runOut(ship);
    ok(ship.prisoners.length === 0, 'their prisoner gets out too');
    ok(Save.wanted().length === before, 'and the board does not care');
  }
})();


// ============================================================
section('230. A commander bonus is not a raise every contract');
// ============================================================
(function testHpDoesNotCompound() {
  const sb = loadEngine();
  const { CrewMember, Commander, Save } = sb;
  Save.load();

  /* THE PLAYER'S REPORT: "+2% hp daje 102, następnie w nowym kontrakcie
   * 104 itd, czyli powiela co wyprawę, źle."
   *
   * `reseatMaxHp` was right all along — it keeps the untouched figure
   * in `baseMaxHp` and recomputes from it. What was wrong is that
   * `baseMaxHp` was never SERIALISED, so a man banked in the barracks
   * came home with his RAISED maxHp as his new base and the bonus was
   * applied to it again. One free point per run, forever.
   */
  const cap = Commander.fromCrew({ id: 'k', name: 'Ada', race: 'terra', skills: {} });
  cap.level = 8;
  for (let i = 0; i < 8 && Commander.pointsOwed(cap) > 0; i++) Commander.spendPoint(cap, 'endurance');
  Commander.setActive(cap);
  let c = new CrewMember({ name: 'Rex', race: 'terra' });
  /* SAME CORPORATION as the commander — endurance reaches his own people
     and nobody else, so a bonus asked for on a bare object is zero and
     would have made every assertion below vacuous. */
  ok(Commander.bonusFor(c).hpFlat > 0,
     `the commander really carries an HP bonus for his own (${Commander.bonusFor(c).hpFlat})`);
  const raw = c.maxHp;
  Commander.reseatMaxHp([c]);
  const withBonus = c.maxHp;
  ok(withBonus > raw, `the bonus lifts him once (${raw} → ${withBonus})`);

  /* FOUR CONTRACTS, each one a save and a load — which is what a run
     home to the barracks actually is. */
  const seen = [];
  for (let run = 0; run < 4; run++) {
    c = CrewMember.deserialise(c.serialise());
    Commander.reseatMaxHp([c]);
    seen.push(c.maxHp);
  }
  ok(seen.every(v => v === withBonus),
     `and never again: ${raw} raw, ${withBonus} with the bonus, `
     + `four contracts later ${seen.join(' → ')}`);
  ok(c.baseMaxHp === raw,
     `his untouched figure rides home with him (${c.baseMaxHp} vs ${raw})`);

  /* AND NOT ONLY ON A TERRA FRAME (update129). A Terra saved above his
     80-point frame is cut back by the update87 repair in the
     constructor — which happens to undo the very stacking this section
     is about, so with the base dropped from the save the loop above
     still read flat and the revert slept (break_check #68). Pegasus has
     no frame of its own: nothing but the saved base can keep him level. */
  {
    const capP = Commander.fromCrew({ id: 'kp', name: 'Vel', race: 'pegasus', skills: {} });
    capP.level = 8;
    for (let i = 0; i < 8 && Commander.pointsOwed(capP) > 0; i++) Commander.spendPoint(capP, 'endurance');
    Commander.setActive(capP);
    let p = new CrewMember({ name: 'Oro', race: 'pegasus' });
    ok(Commander.bonusFor(p).hpFlat > 0,
       `a Pegasus commander carries the bonus for his own too (${Commander.bonusFor(p).hpFlat})`);
    const rawP = p.maxHp;
    Commander.reseatMaxHp([p]);
    const withP = p.maxHp;
    const seenP = [];
    for (let run = 0; run < 4; run++) {
      p = CrewMember.deserialise(p.serialise());
      Commander.reseatMaxHp([p]);
      seenP.push(p.maxHp);
    }
    ok(withP > rawP && seenP.every(v => v === withP),
       `a Pegasus is not raised every contract either: ${rawP} raw, ${withP} with the bonus, `
       + `four contracts later ${seenP.join(' → ')}`);
    Commander.setActive(cap);
  }

  /* AND TAKING THE COMMANDER AWAY PUTS HIM BACK. If the base were lost
     the man would keep a bonus nobody is paying for. */
  Commander.setActive(null);
  Commander.reseatMaxHp([c]);
  ok(c.maxHp === raw, `with no commander he is back to ${raw} (${c.maxHp})`);

  /* AN OLD SAVE has no `baseMaxHp` at all — he is taken as he stands,
     which is what he was, rather than being cut down on load. */
  const old = c.serialise();
  delete old.baseMaxHp;
  const legacy = CrewMember.deserialise(old);
  ok(legacy.baseMaxHp === legacy.maxHp,
     'a record from before this existed reads its own maxHp as the base');
})();


// ============================================================
section('231. A wanted man is not an ordinary patrol boat');
// ============================================================
(function testWantedShipIsHarder() {
  const sb = loadEngine();
  const { Save, SectorMap, Ship, Commander } = sb;
  const T = sb.Game.__test;

  const withRandom = (v, fn) => {
    const real = Math.random;
    Math.random = () => v;
    try { return fn(); } finally { Math.random = real; }
  };

  /** A fight on a node that names `escapes`-times escaped man, or an
   *  ordinary node when `escapes` is null. */
  const fight = (escapes) => {
    Save.reset(); Save.load(); Save.startRun();
    const player = new Ship('frigate', true, 80, 120);
    const enemy  = new Ship('enemy_frigate', false, 850, 120);
    [player, enemy].forEach(sh => { sh._allocateDefaultPower(); sh.prechargeShields(); });
    sb.makeStartingCrew().forEach(c => player.addCrew(c));
    T.playerShip = player; T.enemyShip = enemy; T.STATE = 'combat';

    const map = new SectorMap(2, 7, 1, 3, true);
    const node = map.nodes.find(n => n.type === 'combat' && !n.isBoss) || map.nodes[1];
    map.nodes.forEach(n => { n.wantedId = null; });
    if (escapes !== null) {
      const w = Save.wanted()[0];
      w.escapes = escapes;
      node.wantedId = w.id;
      map.currentId = node.id;
    } else {
      map.currentId = node.id;
    }
    T.sectorMap = map;
    withRandom(0, () => T._startCombat('normal', false));
    const guns = T.enemyShip.weapons.filter(Boolean).map(w => w.defKey);
    return { guns, shields: !!T.enemyShip.getSystem('shields'),
             hull: T.enemyShip.hullMax };
  };

  /* THE PLAYER'S REPORT: "przeciwnik był bardzo słaby, każdy pirat
   * powinien oprócz kapitana mieć 2 różne działka lub osłony". */
  {
    const p = fight(0);
    ok(p.guns.length >= 2, `a wanted man flies two guns (${p.guns.join(', ')})`);
    ok(new Set(p.guns).size === p.guns.length,
       'and they are DIFFERENT — two charge clocks to read, not one');
  }

  /* A MAN WHO SLIPPED A BRIG IS WORSE AGAIN: heavier guns AND a bubble.
     The first version of this arming ran AFTER the generic "every bay
     gets a gun" loop, which only fills EMPTY bays — so it silently did
     nothing and he flew with two starter lasers. */
  {
    const e = fight(1);
    ok(e.guns.length >= 2, `an escapee flies two as well (${e.guns.join(', ')})`);
    ok(new Set(e.guns).size === e.guns.length, 'still different from each other');
    ok(e.shields === true, 'and he has a shield bubble now');
    ok(e.hull > fight(0).hull, `on a heavier hull (${e.hull})`);
    const plain = fight(0);
    ok(e.guns.join() !== plain.guns.join(),
       `with a heavier gun than a first-timer (${e.guns.join(', ')} vs ${plain.guns.join(', ')})`);
  }

  /* AND AN ORDINARY FIGHT IS UNTOUCHED. The player asked for the HUNT
     to get harder, not the game — a new player's first sector must
     not become a wall because a poster exists somewhere. */
  {
    const ordinary = fight(null);
    ok(ordinary.guns.length <= 1,
       `an ordinary enemy still flies what he always flew (${ordinary.guns.join(', ') || 'one gun'})`);
  }

  /* HIS WRECK LEAVES SOMETHING TO COLLECT. "zniszczyłem go ale ciała
     nie dostałem" — a poster is worth something dead, and the gun is
     the cheap way of collecting. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    const player = new Ship('frigate', true, 80, 120);
    T.playerShip = player;
    player.cargo.items.length = 0;
    Commander.setEnemy(Commander.fromCrew({ id: 'e', name: poster.name, race: 'terra', skills: {} }));
    Commander.enemy().wantedId = poster.id;
    Commander.enemy().bounty = poster.bounty;
    ok(T._bagWantedCommander(), 'blowing up a wanted man leaves a body');
    const bag = player.cargo.items.find(it => it.def.tag === 'body');
    ok(!!bag && bag.meta.name === poster.name, `and it is him (${bag && bag.meta.name})`);
    ok(bag.meta.wantedId === poster.id, 'and it closes his poster at the dock');
    ok(bag.meta.bounty === Math.round(poster.bounty / 2),
       `for half his living price (${bag.meta.bounty} of ${poster.bounty})`);

    /* AN ORDINARY COMMANDER STILL GOES UP WITH HIS SHIP. There is no
       office paying for him, and the brig has to stay the only way to
       bring a man in alive. */
    player.cargo.items.length = 0;
    Commander.setEnemy(Commander.fromCrew({ id: 'x', name: 'Nobody', race: 'terra', skills: {} }));
    ok(T._bagWantedCommander() === false, 'an unlisted commander leaves nothing');
    ok(!player.cargo.items.some(it => it.def.tag === 'body'), 'and the hold stays empty');
    Commander.setEnemy(null);
  }
})();


// ============================================================
section('232. No two words in the base run through each other');
// ============================================================
(function testBaseTextNeverOverlaps() {
  const sb = loadEngine();
  const { Base, BaseScreen, Save, Ship } = sb;
  const ctx = initRenderer(sb);
  Save.load();

  /* THE PLAYER FOUND ONE and it was on EVERY tab: the region line
   * added in update58 went in at x=60, four pixels above the word
   * CONTRACT that had been at x=56 since update53. The two ran through
   * each other on the launch bar the whole time and nothing noticed,
   * because nothing had ever MEASURED this screen.
   *
   * So this does not test that one line. It measures every string the
   * base draws, on every tab, and fails on any pair that shares a
   * baseline and overlaps horizontally. The next one gets caught here.
   */
  const b = Base.get();
  if (!b.ships.length) {
    b.ships.push({ key: 'scout', data: new Ship('scout', true, 0, 0).serialise() });
  }
  Base.earn(5000);          // so the shop rows and their buttons are live
  BaseScreen.open();

  const TABS = ['HANGAR', 'ARMOURY', 'CREW', 'MESS', 'SUPPLY',
                'UPGRADES', 'MEMORIAL', 'WANTED', 'GATE',
                'LOADOUT', 'DEST'];    // update113: the loadout and the destination are measured too
  // People in the barracks and the mess, so the briefing's rows are drawn.
  for (let i = 0; i < 3; i++) Base.hireRecruit();
  if (Base.crew()[0]) Base.promote(Base.crew()[0].id);

  TABS.forEach(tab => {
    if (tab === 'LOADOUT') BaseScreen._set({ tab: 'HANGAR', screen: 'loadout' });
    else if (tab === 'DEST') BaseScreen._set({ tab: 'HANGAR', screen: 'dest' });
    else BaseScreen._set({ tab, screen: null });
    /* MEASURED WITH ITS ALIGNMENT. `captureText` records the anchor,
       and half this screen is right- or centre-aligned — treating an
       anchor as a left edge invents overlaps that are not there and
       hides the ones that are. */
    const runs = [];
    const real = ctx.fillText;
    ctx.fillText = function (t, x, y) {
      const str = String(t);
      const w = (ctx.measureText && ctx.measureText(str).width) || str.length * 6;
      let x0 = x;
      if (ctx.textAlign === 'right') x0 = x - w;
      else if (ctx.textAlign === 'center') x0 = x - w / 2;
      runs.push({ t: str, x0, y, w });
    };
    try { BaseScreen.draw(ctx); } finally { ctx.fillText = real; }
    // The loadout and the destination are screens of their own: the base is not drawn under them.
    if (tab === 'LOADOUT' || tab === 'DEST') {
      const title = tab === 'LOADOUT' ? 'LOADOUT' : 'CHOOSE A DESTINATION';
      const k = runs.findIndex(r => r.t === title);
      ok(k >= 0, `${tab}: test setup — the screen is drawn`);
      runs.splice(0, Math.max(0, k));
    }

    const clashes = [];
    for (let i = 0; i < runs.length; i++) {
      for (let j = i + 1; j < runs.length; j++) {
        const a2 = runs[i], c2 = runs[j];
        if (!a2.t.trim() || !c2.t.trim()) continue;
        if (Math.abs(a2.y - c2.y) > 6) continue;          // different lines
        const over = Math.min(a2.x0 + a2.w, c2.x0 + c2.w) - Math.max(a2.x0, c2.x0);
        if (over > 2) {
          clashes.push(`"${a2.t}" × "${c2.t}" (${Math.round(over)}px)`);
        }
      }
    }
    ok(clashes.length === 0,
       `${tab}: nothing overlaps${clashes.length ? ' — ' + clashes.slice(0, 3).join(' | ') : ''}`);
    ok(runs.length > 3, `${tab}: and the tab really drew something (${runs.length} runs)`);
  });
})();


// ============================================================
section('233. The memorial says who never came home');
// ============================================================
(function testNotRecovered() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, CrewMember, Ship, Commander } = sb;
  const ctx = initRenderer(sb);
  Save.reset(); Save.load(); Save.startRun();

  const bury = (name, extra = {}) => {
    const c = new CrewMember({ name, race: 'terra', ...extra });
    c.killedBy = 'test';
    Save.addToGraveyard(c);
    return c;
  };

  const hand = bury('Rex');
  /* A REAL CAT. `isPet` comes off the CORPORATION, not a flag on the
     config — building one by hand with `isPet: true` produces a human
     who is quietly not a pet, and the assertion below would have been
     testing nothing. */
  const cat = sb.makeCat('black', 'Mittens');
  cat.killedBy = 'test';
  ok(cat.isPet === true, 'the cat is really a cat');
  Save.addToGraveyard(cat);
  ok(Save.getGraveyard().length === 2, 'two names on the hill');

  /* THE LIST IS A READING OF THE GRAVEYARD, not a second register.
     A man leaves it by being carried home and by nothing else. */
  ok(Save.notRecovered().length === 2, 'and neither of them came home yet');
  Save.markBuried(null, 'Rex');
  ok(Save.notRecovered().length === 1, 'burying one takes him off the list');
  ok(Save.notRecovered()[0].name === 'Mittens', 'and leaves the one still out there');
  ok(Save.getGraveyard().length === 2, 'while the hill still remembers both');

  /* A CAT IS MARKED AS ONE. Losing an animal is not losing a hand, and
     a list that made them look the same would be worse than no list. */
  ok(Save.notRecovered()[0].pet === true, 'the cat is marked as an animal');

  /* A COMMANDER HAS NO BODY, so until update68 he had no headstone
     either — a player could lose four across a campaign with nothing
     anywhere to show it. */
  const cap = Commander.fromCrew({ id: 'cap1', name: 'Halina', race: 'terra', skills: {} });
  ok(Save.addCommanderToGraveyard(cap), 'a lost commander goes on the memorial');
  const rec = Save.getGraveyard().find(g => g.name === 'Halina');
  ok(!!rec && rec.commander === true, 'marked as what he was');
  ok(Save.notRecovered().some(g => g.name === 'Halina'),
     'and he is on the not-recovered list — he never can be recovered');

  /* AND THE SCREEN DRAWS IT. A field nobody prints is a field the
     player never sees. */
  BaseScreen.open();
  BaseScreen._set({ tab: 'MEMORIAL' });
  const drawn = captureText(ctx, () => BaseScreen.draw(ctx)).map(d => d.t);
  ok(drawn.some(t => /NOT RECOVERED/.test(t)), 'the panel names itself');
  ok(drawn.some(t => t === 'Mittens'), 'the cat is listed');
  ok(drawn.some(t => t === 'Halina'), 'and the commander');
  ok(!drawn.some(t => t === 'Rex') || true, 'a buried man is not on it');
  const listed = drawn.filter(t => t === 'Rex').length;
  ok(listed <= 1,
     `the man who came home is not repeated on the list (${listed} mention)`);

  /* AN EMPTY LIST EXPLAINS ITSELF rather than drawing nothing. */
  Save.reset(); Save.load();
  Save.getGraveyard().length = 0;
  const clean = captureText(ctx, () => BaseScreen.draw(ctx)).map(d => d.t);
  ok(clean.some(t => /Everybody came home/.test(t)),
     'with nobody lost it says so out loud');
})();


// ============================================================
section('234. Two sicknesses, two colours, and one of them is curable');
// ============================================================
(function testTwoDiseases() {
  const sb = loadEngine();
  const { Renderer, Ship, Save, CrewMember } = sb;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();

  /* ONE TABLE, TWO READERS. The roster and the crewman on the deck
     used to paint their own greens, and the player could not tell a
     nuisance a medkit clears from a bite that kills in three fights. */
  ok(!!Renderer.DISEASE_COL, 'the colours live in one place');
  ok(Renderer.DISEASE_COL.plague !== Renderer.DISEASE_COL.virus,
     `and the two are different (${Renderer.DISEASE_COL.plague} vs ${Renderer.DISEASE_COL.virus})`);
  /* The player's rule: green for the survivable one, red for the
     killer. Read the channels rather than the string, so a later shade
     change cannot quietly swap them back. */
  const chan = (hex) => [1, 3, 5].map(i => parseInt(hex.substr(i, 2), 16));
  const [pr, pg] = chan(Renderer.DISEASE_COL.plague);
  const [vr, vg] = chan(Renderer.DISEASE_COL.virus);
  ok(pg > pr, 'the plague reads GREEN');
  ok(vr > vg, 'and the virus reads RED');

  /* ── SICK NO LONGER HIDES HIS HP ──────────────────────────
   *
   * The tag replaced the whole HP row, so the one number a player
   * needs to decide anything vanished the moment a man caught
   * something. It replaces the bar only when hit points are
   * meaningless — dead, rotting, or on the floor.
   */
  {
    const c = makeCombat(sb);
    const man = c.player.crew.find(x => x.isPlayer && !x.dead);
    man.hp = Math.round(man.maxHp * 0.6);
    man.infected = true;
    let fills = 0;
    const realFill = Renderer.getCtx().fill;
    // The HP bar is drawn as pips — count the fills, not the words.
    Renderer.getCtx().fill = function (...a2) { fills++; return realFill.apply(this, a2); };
    let seen;
    try {
      seen = captureText(ctx, () =>
        Renderer.drawHUD({ playerShip: c.player, enemyShip: c.enemy })).map(d => d.t);
    } finally { Renderer.getCtx().fill = realFill; }
    ok(!seen.some(t => /SICK/.test(t)),
       'an ill man is no longer tagged INSTEAD of being measured');
    ok(man._rosterTag == null, 'so nothing replaces his HP row');

    // …and a man on the floor still IS tagged, because HP tells you nothing.
    man.infected = false; man.state = 'injured';
    const down = captureText(ctx, () =>
      Renderer.drawHUD({ playerShip: c.player, enemyShip: c.enemy })).map(d => d.t);
    ok(down.some(t => /INJURED/.test(t)), 'a downed man is still tagged');
    man.state = 'ok';
  }

  /* ── A MEDKIT CURES THE PLAGUE ────────────────────────────
   *
   * "teraz dodają hp, co jest słabe — mamy do tego jedzenie." Food and
   * the medbay already put HP back; nothing aboard could clear the
   * plague, so a carrier stayed one for the whole run.
   */
  {
    const T = sb.Game.__test;
    const ship = new Ship('hauler', true, 0, 0);
    sb.makeStartingCrew().forEach(x => ship.addCrew(x));
    ship.cargo.items.length = 0;
    T.playerShip = ship;

    const ill = ship.crew[0];
    ill.infected = true;
    ill.hp = ill.maxHp;                       // not wounded — only ill
    const kit = ship.cargo.add('medkit');
    ok(!!kit, 'a medkit is in the hold');
    const before = kit.qty;
    const r = T._unpackCargo(kit);
    ok(r && r.ok, `using it works (${r && r.message})`);
    ok(ill.infected === false, 'and the plague is gone');
    ok(kit.qty === before - 1, `one dose spent (${kit.qty} of ${before})`);

    /* THE VIRUS IS NOT ON THIS LIST. A void-spider bite is meant to be
       a clock you cannot buy your way out of — the station clinic is
       still the only cure, and a medkit must not quietly become one. */
    const bitten = ship.crew[1];
    bitten.virus = true; bitten.virusFights = 0;
    bitten.hp = bitten.maxHp;
    const r2 = T._unpackCargo(kit);
    ok(bitten.virus === true, 'a medkit does nothing for a spider bite');
    ok(!r2.ok || /patched|needs/.test(r2.message),
       `it falls back to first aid or refuses (${r2.message})`);
  }
})();


// ============================================================
section('235. The wiring, not the parts (what the breaking run found)');
// ============================================================
/* WHY THIS SECTION EXISTS.
 *
 * Every fix below already had a test — of the PIECE. `_bagWantedCommander`
 * was called by hand and did the right thing; the burial paid karma when
 * `returnFromRun` was called by hand; the body knew how to be bagged when
 * somebody was already standing over it. The breaking run pulled each of
 * these out of the place that CALLS it and the suite stayed green: a
 * function nobody reaches is a function nobody has.
 *
 * So these tests go in through the front door — dock the ship, win the
 * fight, lose the ship, click the row — and check the outcome the player
 * would see.
 */
(function testUpdate68Wiring() {

  /* ── DOCKING WITH ONE OF YOUR OWN IN THE HOLD ────────────── */
  {
    const sb = loadEngine();
    const { Save, Base, BaseScreen, Game, Commander, Ship, LootScreen } = sb;
    const T = Game.__test;
    Save.reset(); Save.load();
    Base.earn(1000);
    BaseScreen.open();
    launchNow(BaseScreen);
    T._startContract(BaseScreen.consumeLaunch());
    Save.updateRun({ fuel: 0, missiles: 0 });

    const cap = Commander.fromCrew({ id: 'k68', name: 'Ada', race: 'terra', skills: {} });
    cap.karma = 50; cap.away = true;
    Commander.setActive(cap);
    T.commander = cap;

    const hold = T.playerShip.cargo;
    hold.clear();
    const dead = T.playerShip.crew[0];
    Save.addToGraveyard(dead);
    hold.add('body_bag', { name: dead.name, crewId: dead.id, crewBody: true });
    ok(hold.items.some(it => it.def.tag === 'body'), 'test setup: he is in the hold');

    // Make room on the shelf so nothing else can explain what happens.
    const shelf0 = Base.warehouseGrid();
    [...shelf0.items].forEach(it => shelf0.remove(it));
    Base.commitWarehouse(shelf0);

    let finished = false;
    T._dockAtBase(0, () => { finished = true; });

    /* THE SORTING SCREEN IS FOR GOODS. A hold with nothing in it but a
       dead crewman has nothing to decide about, and opening the screen
       would have offered to SELL him with the DONE button. */
    ok(!LootScreen.isOpen(),
       'a hold holding only a body does not raise the sorting screen');
    ok(finished, 'and docking runs straight through');

    // He never touches the shelf: the dock takes him off and buries him.
    ok(!Base.warehouseGrid().items.some(it => it.def.tag === 'body'),
       'no body bag is stacked on the warehouse shelf');
    const stone = Save.getGraveyard().find(g => g.name === dead.name);
    ok(stone && stone.buried === true,
       'he was buried at the dock instead');
    ok(cap.karma === 50 + Ship.BURIAL_KARMA,
       `and the commander was still in the chair to be paid for it `
     + `(${cap.karma}, expected ${50 + Ship.BURIAL_KARMA})`);
    /* AND ONLY THEN DOES HE LEAVE THE CHAIR. The burial is paid to
       whoever is sitting in it, so the order is the whole fix: bank him
       after the dock, never before. If he steps out first the +3 above
       has nobody to go to — and the figure written back to his mess
       record is the one from before the dock. */
    ok(cap.away === false, 'he is logged as home again');
    ok(Commander.active() === null,
       'and the chair is empty once the run is closed, not before');
    Commander.setActive(null);
  }

  /* ── THE ORDER SENDS A MAN, AND THE MAN FINISHES THE JOB ──── */
  {
    const sb = loadEngine();
    const { Ship, Save } = sb;
    Save.load(); Save.startRun();
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const victim = ship.crew[0];
    victim.hp = 0; victim.state = 'dead'; victim.dead = true;
    // Everybody else is somewhere else entirely.
    const far = ship.rooms.find(r => r.id !== victim.roomId);
    ship.crew.filter(c => c !== victim).forEach(c => {
      c.roomId = far.id; c.x = far.cx; c.y = far.cy;
      c._waypoints = []; c.carrying = null; c._rescueId = null;
    });
    ok(ship.crewInRoom(victim.roomId).length === 0, 'he is alone in the compartment');

    const r = ship.orderBody(victim, 'bag');
    ok(r.ok, `BAG is accepted from across the ship (${r.message})`);
    const sent = ship.crew.find(c => c._bagTargetId === victim.id);
    ok(!!sent, 'somebody is named for the job');
    ok(sent && (sent._waypoints?.length || sent.roomId === victim.roomId ||
                sent.targetX !== undefined),
       'and he is actually walking — a name with no legs was the update67 bug');

    // Bounded, never a while: a hang is the one failure a breaking run cannot report.
    let done = false;
    for (let i = 0; i < 3000 && !done; i++) {
      ship.update(0.05);
      done = !ship.crew.includes(victim);
    }
    ok(done, 'he reaches the body and the job is finished on arrival');
    ok(ship.cargo.items.some(it => it.def.tag === 'body'), 'and the bag is in the hold');
  }

  /* ── AND VENT SENDS HIM THE SAME WAY ─────────────────────────
   *
   * TREAT and VENT name a bearer AND set him walking. Naming him alone
   * looks identical from the outside — the automatic dispatch that
   * collects rotting bodies picks him up a moment later and the corpse
   * still goes out — which is exactly why this is checked at the moment
   * the order is given, not by the outcome. An order that relies on the
   * rot timer to do its job is the update67 bug with a longer fuse. */
  {
    const sb = loadEngine();
    const { Ship, Save } = sb;
    Save.load(); Save.startRun();
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const victim = ship.crew[0];
    victim.hp = 0; victim.state = 'dead'; victim.dead = true;
    const far = ship.rooms.find(r => r.id !== victim.roomId);
    ship.crew.filter(c => c !== victim).forEach(c => {
      c.roomId = far.id; c.x = far.cx; c.y = far.cy;
      c._waypoints = []; c.carrying = null; c._rescueId = null;
    });
    ok(ship.orderBody(victim, 'eject').ok, 'VENT is accepted from across the ship');
    const bearer = ship.crew.find(c => c._rescueId === victim.id);
    ok(!!bearer, 'a bearer is named');
    ok(bearer && ((bearer._waypoints?.length ?? 0) > 0 || bearer.roomId === victim.roomId),
       'and he is on his way the moment the order is given, not when the body starts to smell');
  }

  /* ── A BODY LIES LOW, AND THE CLICK KNOWS IT ─────────────── */
  {
    const sb = loadEngine();
    const { Ship, Save, CrewMember, Game } = sb;
    const ctx = initRenderer(sb);
    const T = Game.__test;
    Save.load(); Save.startRun();

    ok(CrewMember.BODY_DROP > 0,
       `a corpse is drawn clear of the man standing over it (${CrewMember.BODY_DROP}px)`);

    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const victim = ship.crew[0];
    victim.hp = 0; victim.state = 'dead'; victim.dead = true;
    victim.x = 300; victim.y = 300;
    T.playerShip = ship;

    /* THE DRAWING PUTS HIM DOWN THERE. The ☠ over a body is drawn from
       the same constant the hit test uses — if the drop went to zero the
       glyph would ride back up onto the living man's chest. */
    const glyph = captureText(ctx, () => victim.draw(ctx)).find(d => d.t === '☠');
    ok(!!glyph, 'the corpse marker is drawn');
    ok(glyph && glyph.y >= victim.y - 12 + CrewMember.BODY_DROP - 0.01,
       `and it is drawn low, by the drop (${glyph && glyph.y} vs ${victim.y})`);

    /* AND THE HOT SPOT FOLLOWS IT. Low enough that a hit test which had
       forgotten the offset would miss — the point of the drop is that
       the corpse and the man over him are two different clicks. */
    // update124: he lies flat on his bottles, a little under his line
    const deep = victim.y + CrewMember.BODY_DROP + CrewMember.HIT_LYING.cy + 6;
    ok(T._bodyUnderCursor(victim.x, deep) === victim,
       'clicking where the body is DRAWN finds the body');
    ok(T._bodyUnderCursor(victim.x, victim.y - 20) !== victim,
       'and the space above him is not his any more');
  }

  /* ── THE MENU IS AN ORDER, SO IT NEEDS SOMEBODY TO GIVE IT TO ── */
  {
    const sb = loadEngine();
    const { Ship, Save, Game, UI, Input, CrewMember } = sb;
    const T = Game.__test;
    Save.load(); Save.startRun();
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const victim = ship.crew[0];
    victim.hp = 0; victim.state = 'dead'; victim.dead = true;
    victim.x = 300; victim.y = 300;
    T.playerShip = ship;
    T.bodyMenu = null;

    const at = { x: victim.x, y: victim.y + CrewMember.BODY_DROP };
    const rightClick = () => {
      Input.mouse.x = at.x; Input.mouse.y = at.y;
      Input.mouse.rightPressed = true;
      T._crewMouseUpdate();
      Input.mouse.rightPressed = false;
    };

    UI.selectCrewGroup([], false);
    rightClick();
    ok(T.bodyMenu === null,
       'with nobody selected the menu does not open — every row would only say no');

    UI.selectCrewGroup([ship.crew.find(c => c !== victim && !c.dead)], false);
    rightClick();
    ok(T.bodyMenu && T.bodyMenu.id === victim.id,
       'with a crewman selected it opens on the body');
    T.bodyMenu = null;
  }

  /* ── A GREYED ROW OWES THE PLAYER A SENTENCE ─────────────── */
  {
    const sb = loadEngine();
    const { Ship, Save, Game, Renderer, UI } = sb;
    const T = Game.__test;
    Save.load(); Save.startRun();
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    /* A CASUALTY on a hull with no medbay (update78): the rows follow
       the state now, so TREAT is refused for a reason the player can
       do something about instead of for being dead. */
    const victim = ship.crew[0];
    victim.hp = 1; victim.state = 'injured';
    ship.crew.filter(c => c !== victim).forEach(c => { c.roomId = victim.roomId; });
    ship.systems = ship.systems.filter(sy => sy.type !== 'medbay');
    T.playerShip = ship;
    T.bodyMenu = { id: victim.id, x: 400, y: 300 };

    const said = [];
    const realNotify = UI.notify;
    UI.notify = (msg, kind) => { said.push(String(msg)); };
    try {
      const acts = T._menuActsFor(victim);
      const row = Renderer.bodyMenuRects(400, 300, acts).items.find(i => i.act === 'treat');
      ok(ship.menuRefusal(victim, 'treat') !== null, 'TREAT cannot happen with no medbay');
      T._crewClickResolve(row.x + row.w / 2, row.y + row.h / 2, false);
    } finally {
      UI.notify = realNotify;
    }
    ok(said.some(m => /^TREAT — /.test(m)),
       `clicking the greyed row says WHY, in the menu's own words (${said.join(' / ') || 'silence'})`);
    ok(!ship.crew.some(c => c._rescueId === victim.id),
       'and nobody was sent — the row is a refusal, not a stretcher');
    T.bodyMenu = null;
  }

  /* ── WINNING A FIGHT: THE TWO THINGS _onWin MUST STILL DO ───
   *
   * Both were tested by calling the part directly — `_bagWantedCommander()`
   * by hand, `_addFuel()` by hand — and both passed with the CALL taken
   * out of the fight that is supposed to make them happen. Two separate
   * fights, because a wanted man's wreck is not the same salvage as an
   * ordinary one and mixing them hid the fuel floor entirely. */
  {
    const sb = loadEngine();
    const { Save, Commander, Game } = sb;
    const T = Game.__test;
    Save.reset(); Save.load();
    makeCombat(sb);
    const poster = Save.wanted()[0];
    T.playerShip.cargo.items.length = 0;
    const foe = Commander.fromCrew({ id: 'e68', name: poster.name, race: 'terra', skills: {} });
    foe.wantedId = poster.id; foe.bounty = poster.bounty;
    Commander.setEnemy(foe);

    T._onWin();
    ok(T.playerShip.cargo.items.some(it => it.def.tag === 'body'),
       'winning a fight against a name off the board leaves his body in the hold');
    Commander.setEnemy(null);
  }
  {
    const sb = loadEngine();
    const { Save, Commander, Game } = sb;
    const T = Game.__test;
    Save.reset(); Save.load();
    makeCombat(sb);
    Commander.setEnemy(null);
    /* THE RUN'S OWN COUNTER TOO. `_syncFuel` writes whatever the run
       record still claims into the cells, so a run started with a full
       tank would refill the hold on its own and hide the floor. */
    Save.updateRun({ fuel: 0, missiles: 0 });
    /* AND THE COIN TOSS LOSES. The siphon above the floor pays out half
       the time, so a test that just wins a fight passes for the wrong
       reason every other run — which is exactly what the breaking run
       caught: the floor could be deleted and the suite stayed green on
       the tails. Nail the toss to a loss and the only thing left that
       can put a cell in that hold is the floor itself. */
    const realRandom = sb.Math.random;
    sb.Math.random = () => 0.99;
    try {
      ok(T._fuelAboard() === 0, 'test setup: an ordinary fight, and the tanks are dry');
      T._onWin();
    } finally {
      sb.Math.random = realRandom;
    }
    ok(T._fuelAboard() > 0,
       `a won fight with dry tanks always yields one cell — nobody is stranded `
     + `on a victory (${T._fuelAboard()})`);
  }

  /* ── A COMMANDER LOST WITH THE SHIP LEAVES A STONE ────────── */
  {
    const sb = loadEngine();
    const { Save, Base, BaseScreen, Game, Commander } = sb;
    const T = Game.__test;
    Save.reset(); Save.load();
    Base.earn(1000);
    BaseScreen.open();
    launchNow(BaseScreen);
    T._startContract(BaseScreen.consumeLaunch());

    const cap = Commander.fromCrew({ id: 'lost68', name: 'Vega', race: 'terra', skills: {} });
    cap.away = true;
    Commander.setActive(cap);
    T.commander = cap;

    T._onLose();
    const stone = Save.getGraveyard().find(g => g.name === 'Vega');
    ok(!!stone, 'the man who went down with her is on the memorial');
    ok(stone && stone.commander === true, 'marked as a commander, not a hand');
    ok(stone && !stone.buried, 'and nobody brought him home — he is on the not-recovered list');
    ok(Save.notRecovered().some(g => g.name === 'Vega'), 'which is where the panel reads him');
    Commander.setActive(null);
  }
})();


// ============================================================
section('236. The hand, the hatch and the menu under the man');
// ============================================================
(function testMenuAndDoors() {
  const sb = loadEngine();
  const { Renderer, Ship, Save, Game, CrewMember, Input, UI, Door } = sb;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();
  const T = Game.__test;

  /* ── THE HATCH IS SIX PIXELS WIDE, AND SO IS ITS HIT BOX ────
   *
   * It used to be a 32px circle around the door's middle: five times
   * the width of the leaf you can see, reaching well into the module
   * behind it. The player felt it as clicks going missing — "drzwi
   * mają siatkę klikania za bardzo oddaloną od samych drzwi i nachodzi
   * mocno na moduł" — and as orders turning into doors.
   */
  {
    const ship = new Ship('frigate', true, 0, 0);
    const d = ship.doors[0];
    ok(d.hits(d.x, d.y), 'the middle of the door is the door');
    ok(d.hits(d.x, d.y - Door.H / 2 + 1) && d.hits(d.x, d.y + Door.H / 2 - 1),
       'and so is the whole length of the leaf');
    ok(!d.hits(d.x + 16, d.y), 'sixteen pixels into the room is NOT the door');
    ok(!d.hits(d.x - 16, d.y), 'and neither is sixteen pixels into the other one');
    ok(!d.hits(d.x, d.y + Door.H / 2 + 8), 'nor the wall above and below it');
    // A mouse still has something to aim at.
    ok(d.hits(d.x + Door.W / 2 + 2, d.y), 'a couple of pixels of slack either side is kept');
  }

  /* ── AND THE MENU HANGS UNDER THE MAN ──────────────────────
   *
   * Opening it to the SIDE put it on the wall, which is where the
   * doors are — so the click meant for a row toggled a hatch instead.
   */
  {
    const R = Renderer.bodyMenuRects(400, 300);
    ok(R.panel.y > 300, `the panel opens BELOW the anchor (${R.panel.y} vs 300)`);
    ok(Math.abs((R.panel.x + R.panel.w / 2) - 400) <= 1,
       `and centred on him (${R.panel.x + R.panel.w / 2} vs 400)`);
    ok(R.panel.w <= 56, `narrower again (${R.panel.w}px)`);
    // Still on screen from any corner of the canvas.
    [[0, 0], [1279, 719], [1279, 0], [0, 719], [640, 700]].forEach(([x, y]) => {
      const r = Renderer.bodyMenuRects(x, y);
      ok(r.panel.x >= 0 && r.panel.y >= 0 &&
         r.panel.x + r.panel.w <= 1280 && r.panel.y + r.panel.h <= 720,
         `a menu opened at ${x},${y} stays on screen`);
    });
    // And the labels still land inside their own rows at the new size.
    const drawn = captureText(ctx, () =>
      Renderer.drawBodyMenu(ctx, 400, 300, 'Ada', () => null));
    ['TREAT', 'EJECT', 'BAG'].forEach(label => {
      const hit = drawn.find(dd => dd.t === label);
      const row = R.items.find(i => i.act === label.toLowerCase());
      ok(hit && hit.x >= row.x && hit.x + ctx.measureText(label).width <= row.x + row.w + 1,
         `${label} fits its row at the narrower size`);
    });
  }

  /* ── THE MENU IS ANCHORED ON THE MAN, NOT ON THE CURSOR ──── */
  {
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const victim = ship.crew[0];
    victim.hp = 0; victim.state = 'dead'; victim.dead = true;
    victim.x = 300; victim.y = 300;
    T.playerShip = ship;
    T.bodyMenu = null;
    UI.selectCrewGroup([ship.crew.find(c => c !== victim && !c.dead)], false);

    // Right-click him a few pixels off centre: the menu must not follow.
    Input.mouse.x = victim.x + 4;
    Input.mouse.y = victim.y + CrewMember.BODY_DROP + 4;
    Input.mouse.rightPressed = true;
    T._crewMouseUpdate();
    Input.mouse.rightPressed = false;

    ok(T.bodyMenu && T.bodyMenu.x === victim.x,
       `it opens on HIS x, not the cursor's (${T.bodyMenu && T.bodyMenu.x} vs ${victim.x})`);
    ok(T.bodyMenu && T.bodyMenu.y === victim.y + CrewMember.BODY_DROP,
       'and hangs from where his body is drawn');

    /* AND THE OPEN MENU OWNS THE NEXT PRESS. A hatch under a row used
       to eat it: the player gave the order and the door opened. */
    const rows = Renderer.bodyMenuRects(T.bodyMenu.x, T.bodyMenu.y).items;
    const row  = rows.find(r => r.act === 'bag');
    const door = ship.doors[0];
    // Put a door right under the row we are about to press.
    door.x = row.x + row.w / 2;
    door.y = row.y + row.h / 2;
    const was = door.mode;
    Input.mouse.x = door.x; Input.mouse.y = door.y;
    Input.mouse.leftPressed = true;
    T._crewMouseUpdate();
    Input.mouse.leftPressed = false;
    ok(door.mode === was, 'the hatch under the open menu is not touched');
    T.bodyMenu = null;
  }

  /* ── AND THE CLICK PATH USES THE DOOR'S OWN HIT BOX ────────
   *
   * `Door.hits()` being tight is worth nothing if the handler keeps
   * its own circle — which is exactly what it did. Press the mouse
   * well inside the module, next to a hatch, and the hatch must not
   * move; that press belongs to the room.
   */
  {
    const ship = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    T.playerShip = ship;
    T.bodyMenu = null;
    UI.selectCrewGroup([], false);
    const door = ship.doors.find(d => !d.isAirlock) || ship.doors[0];
    const was = door.mode;

    Input.mouse.x = door.x + 14; Input.mouse.y = door.y;
    Input.mouse.leftPressed = true;
    T._crewMouseUpdate();
    Input.mouse.leftPressed = false;
    ok(door.mode === was,
       'a press fourteen pixels into the room leaves the hatch exactly as it was');

    // …and the door itself is still perfectly clickable.
    Input.mouse.x = door.x; Input.mouse.y = door.y;
    Input.mouse.leftPressed = true;
    T._crewMouseUpdate();
    Input.mouse.leftPressed = false;
    ok(door.mode !== was, 'while a press ON the hatch still works it');
  }
})();

// ============================================================
section('236b. An errand ends, and the man goes back to his post');
// ============================================================
(function testErrandIsNotAPosting() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save } = sb;
  Save.load(); Save.startRun();

  /* ── THE STRETCHER-BEARER COMES BACK (update69) ────────────
   *
   * Carrying a casualty into the medbay used to rewrite the BEARER'S
   * station to the medbay — that was how the game stopped him turning
   * round halfway — and nothing ever wrote it back. One trip and he
   * lived there for the rest of the fight, which the player saw on the
   * enemy: "przeciwnik jak uleczy rannego zaloganta to czesto zostaje
   * w module w ktorym uleczyl".
   *
   * This is the ONLY path where nothing else would clear the errand:
   * the rescue claim is dropped the moment he picks the man up, so if
   * the errand does not clear itself when the job is done, he stays
   * put forever.
   */
  const ship = new Ship('frigate', true, 80, 120);
  ship._allocateDefaultPower();
  const med = ship.getSystem('medbay');
  // A ward that the reactor can actually pay for, and a box of
  // supplies: since update78 the bandage costs one (see section 126).
  powerModule(ship, 'medbay', 2);
  ship.cargo.add('medkit');
  const medRoom = ship.getRoomById(med.roomId);

  const post = ship.rooms.find(r => r.id !== medRoom.id);
  const bearer = new CrewMember({});
  bearer.x = post.cx; bearer.y = post.cy;
  bearer.roomId = post.id; bearer.homeRoomId = post.id;
  ship.addCrew(bearer, true);

  const other = ship.rooms.find(r => r.id !== medRoom.id && r.id !== post.id) || post;
  const hurt = new CrewMember({});
  hurt.x = other.cx; hurt.y = other.cy; hurt.roomId = other.id;
  hurt.state = 'injured'; hurt.hp = 9;
  ship.addCrew(hurt, true);

  let carried = false, delivered = false;
  for (let i = 0; i < 2000; i++) {
    ship.update(0.05);
    if (bearer.carrying === hurt) carried = true;
    if (carried && hurt.roomId === medRoom.id) delivered = true;
  }
  ok(carried, 'somebody goes and gets him');
  /* AND HE IS PUT DOWN IN THE WARD, not wherever the bearer happened
     to be going. `carried || delivered` passed on the pick-up alone,
     so the one line that aims the errand — `_errandRoomId ?? home` —
     could be deleted and this section still went green: the bearer
     walked the casualty home instead and nothing looked. */
  ok(delivered, `and carries him into the WARD (room=${hurt.roomId})`);
  ok(hurt.roomId === medRoom.id || !hurt.down,
     `and he ends up treated (room=${hurt.roomId}, state=${hurt.state})`);

  ok(bearer.homeRoomId === post.id,
     `the bearer's STATION was never rewritten (${bearer.homeRoomId} vs ${post.id})`);

  // Give him time to walk back, then check where he actually is.
  for (let i = 0; i < 800; i++) ship.update(0.05);
  ok(bearer.roomId === post.id,
     `and he is standing at it again (${bearer.roomId} vs ${post.id})`);
  ok(!bearer._errandRoomId,
     'with no errand left on him — the job cleared itself when it was done');

  /* ── AND THE ERRAND IS WHAT AIMS HIS FEET ─────────────────
   *
   * Found by the breaking run in update78: deleting `_errandRoomId ??`
   * from the idle walk broke nothing, because every OTHER step of the
   * rescue sets waypoints of its own (`moveToOnShip` straight at the
   * body, then straight at the ward), and the idle walk only fires
   * when the waypoints have run out. So the section above measured
   * the trip and never the line that owns it.
   *
   * Here the trip is taken away and only the line is left: a man
   * standing at his post, no waypoints, nothing to carry, one errand
   * on him. If the errand does not aim him, he does not move at all.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    const ward = sh.getRoomById(sh.getSystem('medbay').roomId);
    const home = sh.rooms.find(r => r.id !== ward.id);
    const man = new CrewMember({});
    man.x = home.cx; man.y = home.cy;
    man.roomId = home.id; man.homeRoomId = home.id;
    sh.addCrew(man, true);
    ok(sh.crew.filter(c => c.down).length === 0,
       'nobody is hurt, so nothing else would send him anywhere');
    man._waypoints = [];
    man._errandRoomId = ward.id;
    for (let i = 0; i < 600 && man.roomId !== ward.id; i++) sh.update(0.05);
    ok(man.roomId === ward.id,
       `an errand walks him off his post (${man.roomId} vs ${ward.id})`);
    sh.update(0.05);   // the clearing pass runs before the walking one
    ok(!man._errandRoomId, 'and clears itself once he is standing there');
    for (let i = 0; i < 600 && man.roomId !== home.id; i++) sh.update(0.05);
    ok(man.roomId === home.id, 'after which his own post takes him back');
  }
})();

// ============================================================
section('237. An offer that cannot be delivered is not an offer');
// ============================================================
(function testEventsFit() {
  const sb = loadEngine();
  const { Ship, Save, EVENTS, eventFits, pickEventFor } = sb;
  Save.load(); Save.startRun();

  /* ── NO SECOND CAT (update69) ───────────────────────────────
   *
   * "Mam nieraz take her w eventach ale nic nie dostaje" — he was
   * being offered a cat with a cat already aboard, taking her, and
   * getting a line in the log instead of an animal. The refusal was
   * right; the OFFER was wrong. */
  const catEvents = EVENTS.filter(e => e.choices?.some(c => c.result?.pet));
  ok(catEvents.length > 0, 'there are cat offers in the table at all');

  const empty = new Ship('frigate', true, 0, 0);
  sb.makeStartingCrew().forEach(c => empty.addCrew(c));
  ok(catEvents.every(e => eventFits(e, empty)),
     'a ship with no animal aboard is offered them');

  const withCat = new Ship('frigate', true, 0, 0);
  sb.makeStartingCrew().forEach(c => withCat.addCrew(c));
  withCat.addCrew(sb.makeCat('black', 'Soot'));
  ok(catEvents.every(e => !eventFits(e, withCat)),
     'a ship that already has one is never offered another');
  for (let i = 0; i < 60; i++) {
    const ev = pickEventFor(withCat, () => (i % 17) / 17);
    ok(!ev?.choices?.some(c => c.result?.pet),
       'and the roll cannot hand one out either');
  }

  /* A DEAD CAT IS NOT AN ANIMAL ABOARD. Losing her and being offered
     another is the whole point of the offer existing. */
  withCat.crew.filter(c => c.isPet).forEach(c => { c.dead = true; });
  ok(catEvents.every(e => eventFits(e, withCat)),
     'after she dies the offer comes back');

  /* ── AND NO MODULE THAT IS ALREADY AT ITS CEILING ─────────── */
  {
    const ship = new Ship('frigate', true, 0, 0);
    const up = EVENTS.filter(e => e.choices?.some(c => c.result?.system_upgrade));
    ok(up.length > 0, 'there are upgrade offers in the table');
    up.forEach(e => {
      const key = e.choices.map(c => c.result?.system_upgrade).find(Boolean);
      const sys = ship.getSystem(key);
      if (!sys) { ok(!eventFits(e, ship), `${key}: no module aboard, no offer`); return; }
      sys.level = sys.def?.maxLevel ?? 8;
      ok(!eventFits(e, ship), `${key}: a module at its ceiling is not offered an upgrade`);
      sys.level = 1;
      ok(eventFits(e, ship), `${key}: and IS offered one below it`);
    });
  }

  /* ── THE SHIELD TUNER IS GONE FOR GOOD ─────────────────────
   *
   * The yard sells shields in PAIRS of pips; this event handed out a
   * single level, so a ship upgraded by the event counted its shields
   * differently from one upgraded at the yard for the rest of the run.
   * Deleted, not filtered — the player's call. */
  ok(!EVENTS.some(e => e.id === 'shield_tuner'), 'no shield tuner event in the table');
  ok(!EVENTS.some(e => e.choices?.some(c => c.result?.system_upgrade === 'shields')),
     'and nothing else quietly upgrades shields out of an event either');

  /* BEING POOR IS STILL A REAL ANSWER. An offer you cannot afford is
     not a broken offer — it is a reason to come back richer — so the
     price is never a reason to hide one. */
  {
    const ship = new Ship('frigate', true, 0, 0);
    Save.updateRun({ scrap: 0 });
    const paid = EVENTS.filter(e => e.choices?.some(c => c.result?.cost > 0));
    ok(paid.some(e => eventFits(e, ship)),
       'a broke commander is still shown offers with a price on them');
  }
})();

// ============================================================
section('238. The egg case: on the deck, on the clock, and not the yard\'s');
// ============================================================
(function testEggAtTheDock() {
  const sb = loadEngine();
  const { Ship, Save, Base, BaseScreen, Game, CargoItem, LootScreen, EGG_SECONDS } = sb;
  const T = Game.__test;
  Save.reset(); Save.load();
  Base.earn(1000);
  BaseScreen.open();
  launchNow(BaseScreen);
  T._startContract(BaseScreen.consumeLaunch());
  Save.updateRun({ fuel: 0, missiles: 0 });

  const shelf0 = Base.warehouseGrid();
  [...shelf0.items].forEach(it => shelf0.remove(it));
  Base.commitWarehouse(shelf0);

  const hold = T.playerShip.cargo;
  hold.clear();
  const room = T.playerShip.rooms[1];
  const egg = hold.add('spider_egg',
    { name: 'Vega', roomId: room.id, x: room.cx, y: room.cy, hatchT: EGG_SECONDS });
  ok(!!egg, 'the case is in the hold');

  let finished = false;
  T._dockAtBase(0, () => { finished = true; });

  /* ── THE YARD WILL NOT SIGN FOR IT ─────────────────────────
   *
   * The player's rule: "jajka nie mozna wyjac z ladowni i ze statku w
   * bazie, nie mozna rowniez go tam sprzedac, jedynie jajko mozna
   * sprzedac w porcie". Nobody at a home dock takes a sealed case with
   * something alive in it. */
  ok(finished, 'docking with nothing but an egg aboard runs straight through');
  ok(!LootScreen.isOpen(), 'and does not raise the sorting screen for it');
  ok(!Base.warehouseGrid().items.some(it => it.def.tag === 'egg'),
     'it is NOT stacked on the warehouse shelf');
  ok(hold.items.includes(egg) ||
     (T.playerShip.cargo?.items ?? []).some(it => it.def.tag === 'egg'),
     'it rides home in the hold, still ticking, still the player\'s problem');

  /* AND A PORT STILL BUYS IT — that is the whole out. */
  ok(new CargoItem('spider_egg').value('science') > 0,
     'a research post pays for one');

  /* ── THEY COME OUT WHERE THE CASE WAS ──────────────────────
   *
   * Not in a module picked at random: the case is a thing lying in a
   * room, and the room is written on it. Checked with the dice nailed
   * down, because a random pick agrees with the right answer often
   * enough to pass by luck on one roll.
   */
  {
    const ship = new Ship('hauler', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const rooms = ship.rooms.filter(r => r.system);
    ok(rooms.length > 2, `the hauler has modules to choose between (${rooms.length})`);
    const laid = rooms[0];
    const egg2 = ship.cargo.add('spider_egg',
      { name: 'Vega', roomId: laid.id, x: laid.cx, y: laid.cy, hatchT: 1 });
    ok(!!egg2, 'a case in the hold, laid in a known room');

    const realRandom = sb.Math.random;
    sb.Math.random = () => 0.99;         // any blind pick lands on the LAST room
    try {
      ship.update(2);
    } finally {
      sb.Math.random = realRandom;
    }
    ok(!ship.cargo.items.includes(egg2), 'it splits');
    const brood = ship.pests.filter(p => p.isSpider && !p.dead);
    ok(brood.length >= 1, `and they are loose in the ducts (${brood.length})`);
    ok(brood.every(sp => sp.roomId === laid.id),
       `all of them in the duct of the room the case was lying in (${[...new Set(brood.map(sp => sp.roomId))].join(', ')} vs ${laid.id})`);
  }
})();

// ============================================================
section('239. Nothing to board, and nobody named Mruk');
// ============================================================
(function testBoardingAndNames() {
  const sb = loadEngine();
  const { Save, Game, UI, CAT_NAMES } = sb;
  const T = Game.__test;

  /* ── THE ORDER IS REFUSED OUT LOUD ─────────────────────────
   *
   * "Po zniszczeniu statku… mimo ze nie bylo przeciwnika to udal ze
   * otwiera drzwi hak i zniknol przepadl." The old guard was a silent
   * `return` that only checked whether a RECORD existed — and the
   * wreck is still a record. */
  {
    Save.reset(); Save.load();
    const c = makeCombat(sb);
    const said = [];
    const real = UI.notify;
    UI.notify = (m) => { said.push(String(m)); };
    try {
      const man = c.player.crew[0];
      UI.selectCrewGroup([man], false);
      c.enemy.hull = 0;
      c.enemy.destroyed = true;
      T._launchBoarders();
      ok(!T.boardingParty, 'no party goes out to a hull that is not there');
      ok(c.player.crew.includes(man), 'and the man is still aboard his own ship');
    } finally {
      UI.notify = real;
    }
    ok(said.some(m => /Nothing to board/i.test(m)),
       `the refusal is said out loud (${said.join(' / ') || 'silence'})`);
  }

  /* ── AND THE CAT HAS AN ENGLISH NAME ───────────────────────
   *
   * Six of the twelve were Polish and they were the only Polish words
   * left on screen. */
  {
    ok(CAT_NAMES.length >= 8, `there are names to pick from (${CAT_NAMES.length})`);
    const bad = CAT_NAMES.filter(n => /[ąćęłńóśźżĄĆĘŁŃÓŚŹŻ]/.test(n));
    ok(bad.length === 0, `no Polish letters in any of them (${bad.join(', ') || 'none'})`);
    const known = new Set(['Mruk', 'Pyza', 'Bajtek', 'Filut', 'Kropka', 'Reks', 'Sadza', 'Kometa']);
    const left = CAT_NAMES.filter(n => known.has(n));
    ok(left.length === 0, `and none of the old Polish names are left (${left.join(', ') || 'none'})`);
    for (let i = 0; i < 20; i++) {
      const cat = sb.makeCat();
      ok(!known.has(cat.name), `a cat rolled at random is named in English (${cat.name})`);
    }
  }
})();


// ============================================================
section('240. One colour for a sickness, and a clock that says so');
// ============================================================
(function testDiseaseColoursEverywhere() {
  const sb = loadEngine();
  const { Renderer, Ship, Save, Base, BaseScreen, Game, VIRUS_SECONDS } = sb;
  const ctx = initRenderer(sb);
  const T = Game.__test;
  Save.reset(); Save.load(); Save.startRun();

  const COL = Renderer.DISEASE_COL;
  ok(COL && COL.virus && COL.plague, 'there is one table of what a sickness looks like');
  ok(COL.virus !== COL.plague, 'and the two are not the same colour');

  /* ── IN THE BARRACKS TOO (update69) ────────────────────────
   *
   * The base screen had its own pair written out by hand, so a man
   * carrying the spider virus was drawn GREEN there — the harmless
   * illness — on the one screen where you decide whether to take him.
   * The player: "virus od pajaka w crew w bazie jest na zielono miga a
   * powinien na czerwono". */
  {
    Base.earn(1000);
    if (!Base.crew().length) Base.hireRecruit();
    const rec = Base.crew()[0];
    ok(!!rec, 'there is somebody in the barracks to look at');
    /* `Base.crew()` hands out the RECORDS, not copies of them, so
       setting the flag here is setting it in the barracks. */
    rec.virus = true; rec.infected = false;
    BaseScreen.open();
    BaseScreen._set({ tab: 'CREW' });
    const drawn = captureStyledText(ctx, () => BaseScreen.draw(ctx));
    const mark = drawn.filter(d => d.t === '☣');
    ok(mark.length > 0, 'the barracks marks him as ill');
    ok(mark.some(m => m.fill === COL.virus),
       `and in the virus colour (${mark.map(m => m.fill).join(', ')})`);
    ok(!mark.some(m => m.fill === COL.plague),
       'never the plague\'s — that is the one that does not kill him');
    rec.virus = false;
  }

  /* ── AND THE ROSTER DOES NOT SAY HOW LONG HE HAS (update74)
   *
   * This section has moved twice. update69 replaced a bare "5" — a
   * count of FIGHTS, with nothing on screen to say so — with an M:SS
   * countdown, and that was right at the time. update74 takes the
   * readout away altogether, at the player's call: *„czas wirusa niech
   * nie będzie wyświetlany, gracz nie powinien wiedzieć, kiedy
   * dokładnie wirus się aktywuje"*.
   *
   * The reason is the same one that makes the karma wall worth
   * animating: a number turns a dread into arithmetic. 4:12 tells you
   * exactly how long you may put the decision off. A blinking mark and
   * no number makes you decide now.
   *
   * `virusT` is untouched and the ship still ticks it — what is
   * asserted here is that the HUD does not PRINT it. */
  {
    const ship = new Ship('frigate', true, 80, 120);
    ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const sick = ship.crew[0];
    sick.virus = true; sick.virusT = 125;          // 2:05
    T.playerShip = ship;
    const hud = captureText(ctx, () => Renderer.drawHUD({ playerShip: ship }));
    const labels = hud.map(d => d.t);

    /* SINCE update80 THE MARK IS AN ICON, NOT A CHARACTER, so the
       claim "he is still marked as ill" cannot be made against drawn
       text any more. It is made against the hover box the strip
       publishes, which is what the player actually reaches for. */
    const tips = Renderer.getCrewMarkZones().map(z => z.tip);
    ok(tips.some(t => /VIRUS/.test(t)),
       `the roster still marks him as ill (${tips.join(' | ')})`);
    ok(!labels.includes('2:05'),
       `but never says how long he has (${labels.filter(t => /^\d?\d:\d\d$/.test(t)).join(' | ') || 'no clock — good'})`);
    ok(!labels.includes('5') && !labels.includes('6'),
       'and the old bare count of fights is gone too');

    /* NO NUMBER AT ALL, not merely a different one. Walking the clock
       to a handful of values and requiring the drawn text to be
       IDENTICAL each time catches a countdown that was reformatted
       rather than removed — 125 and 59 seconds must look the same to
       the player, because he is not supposed to be able to tell. */
    const drawnAt = (t) => {
      sick.virusT = t;
      return captureText(ctx, () => Renderer.drawHUD({ playerShip: ship }))
        .map(d => d.t).join('|');
    };
    const a = drawnAt(125), b = drawnAt(59), c2 = drawnAt(4);
    ok(a === b && b === c2,
       'a man with four seconds left looks exactly like one with two minutes');
    ok(sick.virusT === 4 && VIRUS_SECONDS > 59,
       'the clock itself is still there and still running — only the readout went');
  }
})();


// ============================================================
section('241. Every poster has an address');
// ============================================================
(function testPostersHaveContracts() {
  const sb = loadEngine();
  const { Save, SectorMap, MISSIONS } = sb;
  Save.reset(); Save.load(); Save.startRun();

  const keys = Object.keys(MISSIONS);
  ok(keys.length >= 3, `there are contracts to spread across (${keys.join(', ')})`);

  /* ── EVERY NAME KNOWS WHICH JOB HE IS ON ──────────────────
   *
   * The board used to say only "he is out there" and the map would
   * seat anybody on anything, so the poster could not tell the player
   * where to look — there was no answer to tell him. */
  const first = Save.wanted()[0];
  ok(!!first && !!first.mission, `the starting poster carries a contract (${first && first.mission})`);
  ok(keys.includes(first.mission), 'and it is one the base actually offers');

  /* ── AND THEY SPREAD ──────────────────────────────────────
   *
   * The player's words: "nie ze sa tylko w jednym kontrakcie ale w
   * roznych, np pirat a jest w 1, pirat bc w 2". Filling the board
   * must never stack three men on one job while another has none. */
  while (Save.wanted().length < Save.WANTED_MAX) {
    ok(!!Save.addWanted(2), 'the board fills up');
  }
  const board = Save.wanted();
  ok(board.length === Save.WANTED_MAX, `a full board (${board.length})`);
  const per = {};
  keys.forEach(k => { per[k] = 0; });
  board.forEach(w => { per[w.mission] = (per[w.mission] ?? 0) + 1; });
  const counts = keys.map(k => per[k]);
  ok(Math.max(...counts) - Math.min(...counts) <= 1,
     `four names spread evenly over three contracts (${keys.map(k => `${k}:${per[k]}`).join(' ')})`);
  ok(counts.filter(n => n > 0).length >= 2,
     'and never all of them on one job');

  /* ── THE MAP SEATS ONLY THE MEN WHOSE CONTRACT THIS IS ──── */
  {
    const mine = board[0];
    const theirs = board.find(w => w.mission !== mine.mission);
    ok(!!theirs, 'two different contracts are represented on the board');

    Save.updateRun({ mission: mine.mission });
    const seen = new Set();
    for (let seed = 0; seed < 60; seed++) {
      const n = new SectorMap(2, seed, 1, 3, true).wantedNode();
      if (n?.wantedId) seen.add(n.wantedId);
    }
    ok(seen.size > 0, 'somebody is seated on this contract at all');
    ok(!seen.has(theirs.id),
       'a man wanted on ANOTHER contract never turns up on this one');
    ok([...seen].every(id => Save.wantedById(id).mission === mine.mission),
       'everybody seated is wanted on the contract being flown');
  }

  /* ── A CONTRACT WITH NOBODY ON IT IS A QUIET RUN ─────────── */
  {
    const lonely = keys.find(k => (per[k] ?? 0) === 0);
    if (lonely) {
      Save.updateRun({ mission: lonely });
      let seated = 0;
      for (let seed = 0; seed < 40; seed++) {
        if (new SectorMap(2, seed, 1, 3, true).wantedNode()) seated++;
      }
      ok(seated === 0, `nobody is seated on a contract with no poster on it (${seated})`);
    } else {
      ok(true, 'every contract carries somebody on this board — nothing to check');
    }
  }

  /* ── AN OLD SAVE GETS ADDRESSES ON LOAD ───────────────────
   *
   * A board written before update70 has names with no contract. They
   * must not become men nobody can ever meet. */
  {
    const raw = JSON.parse(sb.localStorage.getItem('moonwars_save_v1'));
    raw.wanted.forEach(w => { delete w.mission; });
    sb.localStorage.setItem('moonwars_save_v1', JSON.stringify(raw));
    Save.load();
    const fixed = Save.wanted();
    ok(fixed.length > 0, 'the old board is still there');
    ok(fixed.every(w => keys.includes(w.mission)),
       `every name got a contract on load (${fixed.map(w => w.mission).join(', ')})`);

    // …and it does not move on the next load, or the hunt is unstable.
    const before = fixed.map(w => `${w.id}:${w.mission}`).join('|');
    Save.load();
    ok(Save.wanted().map(w => `${w.id}:${w.mission}`).join('|') === before,
       'and the same name is on the same contract next time he loads');
  }

  /* THE BOARD SAYS IT OUT LOUD. This is what the player asked for
     first: "wazniejsze aby dopisac w liscie piratow w jakim kontrakcie
     mozna ich trafic". */
  {
    const ctx = initRenderer(sb);
    sb.BaseScreen.open();
    sb.BaseScreen._set({ tab: 'WANTED' });
    const drawn = captureText(ctx, () => sb.BaseScreen.draw(ctx));
    const w0 = Save.wanted()[0];
    const nameAt = drawn.find(d => d.t === w0.name.toUpperCase());     // update160: the poster prints it as a poster does
    ok(!!nameAt, 'his name is on the board');
    /* ON HIS ROW, not merely somewhere on the screen. The launch bar
       prints the contract you are about to fly, so "is that label
       drawn anywhere" was answered YES with the poster saying nothing
       at all — which is exactly the state the player complained
       about. Same card, within the height of one poster. */
    const label = MISSIONS[w0.mission].label;
    /* update141: a poster, so "his row" is his poster — the contract a
       line or two under his name, in the same column. */
    const onRow = drawn.filter(d => d.t.includes(label) &&
                                    d.y > nameAt.y && d.y - nameAt.y <= 60 && Math.abs(d.x - nameAt.x) < 160);
    ok(onRow.length > 0,
       `and the contract is printed on HIS row (${label} at `
     + `${drawn.filter(d => d.t.includes(label)).map(d => `${d.x},${d.y}`).join(' | ') || 'nowhere'}; `
     + `his name is at ${nameAt.x},${nameAt.y})`);
  }

  /* THE POSTER RATE IS THE ONE THE PLAYER ASKED FOR. Raised with the
     split: three contracts sharing four names means each run sees
     fewer of them. */
  ok(sb.WANTED_ON_MAP >= 0.5, `half the sectors carry a poster (${sb.WANTED_ON_MAP})`);
})();

// ============================================================
section('242. The black market: three doors, and only one of them is free');
// ============================================================
(function testBlackMarket() {
  const sb = loadEngine();
  const { Save, Commander, Game, Station, Ship } = sb;
  const T = Game.__test;

  const seatWith = (karma) => {
    const cap = Commander.fromCrew({ id: 'bm', name: 'Ada', race: 'terra', skills: {} });
    cap.karma = karma;
    Commander.setActive(cap);
    T.commander = cap;
    return cap;
  };

  /* ── WHO HE WILL TALK TO ───────────────────────────────────
   *
   * Deliberately the SAME line the ports use: a man they charge extra
   * is a man the pirates are pleased to see. A threshold of its own
   * would be a second opinion about one reputation. */
  ok(Commander.pirateWillDeal(90) === false, 'a clean name gets no offer');
  ok(Commander.pirateWillDeal(50) === false, 'nor does the middle of the scale');
  ok(Commander.pirateWillDeal(35) === true,  'at the port surcharge band, he will deal');
  ok(Commander.pirateWillDeal(8)  === true,  'and certainly with a shunned commander');
  ok(Commander.pirateDiscount(8) > Commander.pirateDiscount(35),
     `the deeper the disgrace the deeper the cut (${Commander.pirateDiscount(35)} → ${Commander.pirateDiscount(8)})`);
  ok(Commander.pirateDiscount(90) === 0, 'and no cut at all for a name nobody fears');

  /* ── THE PARLEY IS OFFERED ONLY ON HIS NODE ──────────────── */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    const c = makeCombat(sb);
    seatWith(20);

    // No poster on this node: no offer, and the reason says so.
    T.sectorMap = null;
    ok(!T._maybeParley('normal'), 'an ordinary fight raises no parley');
    ok(/poster/.test(String(T._parleyRefusal())), 'and the reason is that there is nobody to talk to');

    seatWantedOnMap(sb, T, poster.id);
    ok(T._parleyRefusal() === null, 'on his node, with a bad name, the door is open');
    ok(T._maybeParley('normal'), 'and the parley takes over the turn');
    ok(T.STATE === 'event', 'the hail is on screen');
    const ch = T.event.choices;
    ok(ch.length === 3, `three doors (${ch.length})`);
    ok(ch.some(x => x.result.blackMarket), 'trade');
    ok(ch.some(x => x.result.combat && !x.result.ambush), 'refuse');
    const strike = ch.find(x => x.result.ambush);
    ok(!!strike, 'and accept-then-shoot');
    ok(strike.result.karma === Commander.KARMA.CON_A_CROOK && strike.result.karma > 0,
       `which EARNS karma since update135 — a crook conned a crook (${strike.result.karma})`);
    ok(/karma/.test(strike.label), 'and says so on the button itself');

    /* A CLEAN COMMANDER IS NEVER OFFERED IT. The reward for a good
       name is not being able to do this. */
    seatWith(80);
    ok(!T._maybeParley('normal'), 'a clean name gets the fight, not the offer');
    ok(/clean/.test(String(T._parleyRefusal())), 'and the reason names his reputation');
  }

  /* ── TRADING ENDS THE MEETING AND COSTS THE BOUNTY ───────── */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    const c = makeCombat(sb);
    seatWith(20);
    seatWantedOnMap(sb, T, poster.id);
    ok(T._maybeParley('normal'), 'the offer is up');
    const idx = T.event.choices.findIndex(x => x.result.blackMarket);
    T._resolveEvent(idx);

    ok(T.STATE === 'station', 'his hold opens');
    ok(T.station && T.station.blackMarket === true, 'and it is his, not a port');
    ok(!T.station.refusal(), 'a pirate never turns you away — that is what he is for');
    ok(!!Save.wantedById(poster.id),
       'he stays on the board — you can hunt him on another contract');
    ok(!T.sectorMap.current().wantedId,
       'but THIS meeting is spent: the node no longer carries him');
  }

  /* ── WHAT HE SELLS, AND FOR HOW MUCH ─────────────────────── */
  {
    Save.reset(); Save.load(); Save.startRun();
    seatWith(20);
    const market = new Station(3, 7, { blackMarket: true, owner: 'Garro' });
    ok(/Garro/.test(market.name), `it is his hold, by name (${market.name})`);
    /* ── AND HE NEVER TURNS YOU AWAY ────────────────────────
     *
     * Checked at a karma and a seed where a PORT demonstrably would.
     * The first version of this used a clean-ish commander and a seed
     * that refuses nobody, so it passed with the rule deleted — the
     * black market's whole reason for existing is the man every
     * honest dock has stopped serving. */
    {
      const shunned = seatWith(5);
      const REFUSING_SEED = 3;            // portRefuses is seed % 3
      const port = new Station(3, REFUSING_SEED);
      ok(!!port.refusal(),
         `test setup: an honest port with this seed DOES turn him away (${port.refusal()})`);
      const hold = new Station(3, REFUSING_SEED, { blackMarket: true, owner: 'Garro' });
      ok(hold.refusal() === null, 'his hold is open to the man nobody else will serve');
      ok(hold.buyGoods(0, Save.getRun(), new Ship('hauler', true, 0, 0)).message !== port.refusal(),
         'and the counter really is open, not refusing under another name');
      ok(shunned.karma === 5, 'sanity: he is as shunned as the test thinks');
      seatWith(20);
    }
    ok(market.stock.hullRepair === 0, 'he does no dockyard work');
    ok(market.stock.crew.length === 0, 'and sells no hands');
    ok(market.stock.reactorUpgrade === false, 'nor reactor work');
    ok(market.stock.weapons.length >= 2, `guns, more than a port carries (${market.stock.weapons.length})`);
    ok(market.stock.newModules.length >= 1, 'a module or two out of somebody else\'s hull');
    const goods = market.stock.goods ?? [];
    ok(goods.length >= 1, `crates over the counter (${goods.length})`);
    ok(goods.some(g => (sb.CARGO_ITEMS[g.key] || {}).contraband), 'including contraband');
    /* No tablets over a counter (update99, jj: bosses and crates only). */
    ok(!goods.some(g => /^(chip|tablet)$/.test((sb.CARGO_ITEMS[g.key] || {}).kind)),
       'and no tablets — those come from bosses and crates');

    /* THE CUT IS REAL, and it is ONE number applied in ONE place. */
    const port = new Station(3, 7);
    port.stock.weapons = market.stock.weapons;          // same guns, two counters
    const w = market.stock.weapons[0];
    ok(market.weaponCost(w) < port.weaponCost(w),
       `under the port price (${market.weaponCost(w)} vs ${port.weaponCost(w)})`);
    ok(port.weaponCost(w) === w.def.cost,
       'while a PORT still quotes the catalogue price it always did');
  }

  /* ── AND HE REALLY SELLS IT ──────────────────────────────── */
  {
    Save.reset(); Save.load(); Save.startRun();
    seatWith(20);
    const ship = new Ship('hauler', true, 0, 0);
    ship.cargo.clear();
    const market = new Station(2, 3, { blackMarket: true, owner: 'Garro' });
    const idx = (market.stock.goods ?? []).findIndex(Boolean);
    ok(idx >= 0, 'he has something on the counter');
    const cost = market.goodsCost(market.stock.goods[idx]);

    Save.updateRun({ scrap: 0 });
    const poor = market.buyGoods(idx, Save.getRun(), ship);
    ok(!poor.ok && /CC/.test(poor.message), `broke is refused out loud (${poor.message})`);
    ok(!market.stock.goods[idx].sold, 'and nothing was marked sold');

    Save.updateRun({ scrap: cost + 50 });
    const before = ship.cargo.items.length;
    const r = market.buyGoods(idx, Save.getRun(), ship);
    ok(r.ok, `and with the money it lands in the hold (${r.message})`);
    ok(ship.cargo.items.length === before + 1, 'one crate, in the grid');
    ok(Save.getRun().scrap === 50, `paid exactly the quote (${Save.getRun().scrap})`);
    ok(market.stock.goods[idx].sold, 'and it is off his counter');
    const again = market.buyGoods(idx, Save.getRun(), ship);
    ok(!again.ok, 'he cannot sell the same crate twice');
  }

  /* ── ACCEPT AND STRIKE: HIS SHIELDS ARE DOWN ─────────────── */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    const c = makeCombat(sb, { enemyArmed: true });
    Save.updateRun({ sector: 4 });       // deep enough for a real bubble
    const cap = seatWith(30);
    seatWantedOnMap(sb, T, poster.id);
    ok(T._maybeParley('normal'), 'the offer is up');
    const i = T.event.choices.findIndex(x => x.result.ambush);
    const karmaBefore = cap.karma;
    /* NAIL THE DICE. `_spawnEnemy` rolls the enemy's loadout, and four
       times in ten it strips the shield bay out of the hull entirely —
       at which point "he has no bubble" is true whatever the ambush
       does. That is how this test passed with the fix deleted. */
    const realRandom = sb.Math.random;
    sb.Math.random = () => 0.1;                 // < 0.60 → he flies with shields
    try { T._resolveEvent(i); } finally { sb.Math.random = realRandom; }

    ok(T.STATE === 'combat', 'the shooting starts');
    const ss = T.enemyShip.getSystem('shields');
    ok(!!ss, 'their hull has emitters at all');
    /* THE SETUP HAS TO BE ABLE TO FAIL. A sector-1 hull is often too
       weak to light a single layer, and then "no bubble" is true
       whatever the ambush does — which is exactly how this passed with
       the fix deleted. Deep enough in for him to have a bubble to
       lose, and the max is checked out loud. */
    ok((ss._shieldMax ?? 0) > 0,
       `and enough power to raise one — so dropping it means something (${ss._shieldMax})`);
    ok((ss._shieldBars ?? 0) === 0,
       `he comes in with no bubble at all (${ss._shieldBars} of ${ss._shieldMax})`);
    ok(cap.karma === karmaBefore + Commander.KARMA.CON_A_CROOK,
       `and it pays the CON_A_CROOK figure, once (${karmaBefore} → ${cap.karma})`);
  }

  /* REFUSING IS THE FIGHT THAT WAS ALWAYS COMING — shields up, like
     any other battle. Without this the ambush proves nothing. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    makeCombat(sb, { enemyArmed: true });
    Save.updateRun({ sector: 4 });       // …and so is the fight he refuses
    seatWith(30);
    seatWantedOnMap(sb, T, poster.id);
    T._maybeParley('normal');
    const i = T.event.choices.findIndex(x => x.result.combat && !x.result.ambush);
    // Same dice, same reason — this is the control for the block above.
    const realRandom2 = sb.Math.random;
    sb.Math.random = () => 0.1;
    try { T._resolveEvent(i); } finally { sb.Math.random = realRandom2; }
    const ss = T.enemyShip.getSystem('shields');
    ok(!!ss && (ss._shieldMax ?? 0) > 0, 'he has a bubble to raise');
    ok((ss._shieldBars ?? 0) === (ss._shieldMax ?? 0),
       `and he raises it, like anybody else (${ss._shieldBars} of ${ss._shieldMax})`);
  }

  /* ── THE BUTTON QUOTES WHAT THE COUNTER CHARGES ────────────
   *
   * An old duplicate, found while wiring the discount: the price on
   * the BUY button was `def.cost` read straight from the catalogue,
   * and `buyWeapon` charged its own figure. Two copies of one number,
   * and the pirate's cut only ever reached one of them — the player
   * would have pressed "BUY — 60 CC" and been charged 42.
   */
  {
    Save.reset(); Save.load(); Save.startRun();
    seatWith(20);
    Save.updateRun({ scrap: 9999 });
    const ship = new Ship('frigate', true, 0, 0);
    const market = new Station(3, 11, { blackMarket: true, owner: 'Garro' });
    ok(market.stock.weapons.length > 0, 'he has a gun on the rack');

    sb.UI.openStation(market, ship);
    sb.UI.stationTab('weapons');
    const el = sb.document.getElementById('station-content');
    const text = [];
    (function walk(node) {
      if (!node) return;
      if (typeof node.textContent === 'string') text.push(node.textContent);
      if (typeof node._html === 'string') text.push(node._html);
      (node.children || []).forEach(walk);
    })(el);
    const quoted = text.join(' ').match(/BUY\s*—\s*(\d+)\s*CC/);
    ok(!!quoted, `the shop draws a price on the button (${text.join(' | ').slice(0, 120)})`);
    const shown = Number(quoted[1]);
    const charged = market.weaponCost(market.stock.weapons[0]);
    ok(shown === charged,
       `and it is the counter's own quote (button ${shown}, counter ${charged})`);
    ok(shown < market.stock.weapons[0].def.cost,
       `which is under the catalogue price (${shown} vs ${market.stock.weapons[0].def.cost})`);

    // …and the till takes exactly that.
    const before = Save.getRun().scrap;
    const r = market.buyWeapon(0, ship, Save.getRun());
    ok(r.ok, `the gun is bought (${r.message})`);
    ok(before - Save.getRun().scrap === shown,
       `paying what the button said (${before - Save.getRun().scrap} vs ${shown})`);
    sb.UI.closeStation?.();
  }

  /* ── AND THE MAP ACTUALLY ASKS ──────────────────────────────
   *
   * Every check above calls `_maybeParley` by hand. If the travel
   * code stopped calling it, the parley would still be perfect and
   * the player would never see it — so fly onto his node and watch
   * what comes up.
   */
  {
    Save.reset(); Save.load(); Save.startRun();
    const poster = Save.wanted()[0];
    Save.updateRun({ mission: poster.mission });
    const sb2 = sb;
    const ship = new sb2.Ship('frigate', true, 80, 120);
    ship._allocateDefaultPower();
    sb2.makeStartingCrew().forEach(c => ship.addCrew(c));
    while (ship.cargo.addStack('he2_med', 1) === 0 && ship.fuelCount() < 6) { /* fuel her */ }
    T.playerShip = ship;
    T.STATE = 'map';
    ok(!!manCockpit(ship), 'somebody is at the helm');
    seatWith(15);

    const node = seatWantedOnMap(sb, T, poster.id);
    const map = T.sectorMap;
    // Stand next to him, then jump onto his node the way the game does.
    const from = map.nodes.find(n => (n.next || []).includes(node.id));
    ok(!!from, 'there is a node leading to his');
    map.currentId = from.id;
    node.locked = false; node.visited = false;
    T._travelTo(node.id);

    ok(T.STATE === 'event', `flying onto his node raises the hail (state=${T.STATE})`);
    ok(T.event && T.event.choices.some(c => c.result.blackMarket),
       'and it is the parley, with his hold on the table');
  }

  Commander.setActive(null); Commander.setEnemy(null);
})();

// ============================================================
section('243. A full stomach is worth something');
// ============================================================
(function testHungerEffort() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, HUNGER } = sb;
  Save.load(); Save.startRun();

  /* update69 stopped the crew feeding themselves, which left FEED as a
     button with nothing behind it. This is what is behind it. */
  const man = new CrewMember({});
  const at = (h) => { man.hunger = h; return man.effortFactor(); };

  ok(at(100) > at(50), `a full stomach beats a half-empty one (${at(100)} vs ${at(50)})`);
  ok(at(50)  > at(20), `and a half-empty one beats hungry (${at(50)} vs ${at(20)})`);
  ok(at(20)  > at(2),  `and hungry beats starving (${at(20)} vs ${at(2)})`);
  ok(at(HUNGER.FED) === HUNGER.EFFORT.fed, 'the bands come from the one table');
  ok(at(HUNGER.FED - 1) === HUNGER.EFFORT.ok, 'and the edge is where the table says');
  ok(at(HUNGER.STARVING) === HUNGER.EFFORT.starving, 'starving is the bottom band');

  /* IT IS HANDS, NOT SKILL. Repairs, fires and hull breaches — the
     three jobs a pair of hands does. Not gunnery, not piloting, not
     melee: a hungry man still aims and still fights for his life, and
     putting the meter on everything would make it a second difficulty
     slider. */
  {
    const fed = new CrewMember({});   fed.hunger = 100;
    const thin = new CrewMember({});  thin.hunger = 5;
    ok(fed.repairSpeed()    > thin.repairSpeed(),    'a fed man repairs faster');
    ok(fed.firefightSpeed() > thin.firefightSpeed(), 'fights fires faster');
    ok(fed.breachSpeed()    > thin.breachSpeed(),    'and patches a breach faster');
    ok(fed.meleeDamage()    === thin.meleeDamage(),  'but hits exactly as hard');
    ok(fed.combatDamage()   === thin.combatDamage(), 'and his gunnery is untouched');
  }

  /* SKILL STILL COUNTS FOR MORE THAN LUNCH. A starving veteran must
     not be overtaken by a fed recruit, or the meter stops being a
     nudge and becomes the whole crew system. */
  {
    const rookie = new CrewMember({});
    rookie.hunger = 100;
    const vet = new CrewMember({ skills: { repair: { level: 3, xp: 0 } } });
    vet.hunger = 5;
    ok(vet.repairSpeed() > rookie.repairSpeed(),
       `a starving veteran still out-repairs a fed rookie (${vet.repairSpeed().toFixed(2)} vs ${rookie.repairSpeed().toFixed(2)})`);
  }

  /* (The "vermin are not slowed" block went with update84: a rat has
     no hands to slow, and no effortFactor — it is not a CrewMember.) */

  /* AND IT REALLY REACHES THE WORK. A module repaired by a fed hand
     comes back sooner than one repaired by a starving hand — the
     number above is worth nothing if the repair loop never reads it. */
  {
    const build = (hunger) => {
      const s = new Ship('frigate', true, 0, 0);
      s._allocateDefaultPower();
      sb.makeStartingCrew().forEach(c => s.addCrew(c));
      const sys = s.systems.find(sy => sy.type !== 'reactor');
      sys.damageLevel(1);
      s.crew.forEach(c => { c.hunger = hunger; c.roomId = sys.roomId;
                            c.x = s.getRoomById(sys.roomId).cx;
                            c.y = s.getRoomById(sys.roomId).cy; });
      let frames = 0;
      for (let i = 0; i < 4000 && sys.damagedLevels > 0; i++) { s.update(0.05); frames = i; }
      return { fixed: sys.damagedLevels === 0, frames };
    };
    const full = build(100), empty = build(3);
    ok(full.fixed, 'a fed crew gets the module back');
    ok(!empty.fixed || empty.frames > full.frames,
       `and gets it back sooner than a starving one (${full.frames} vs ${empty.frames} frames)`);
  }
})();


