section('244. Side objectives — RETIRED in update161: jobs from DISPATCH replaced them (jj: "okno celów — powinniśmy je brać jak misje do wyboru")');
// ============================================================
(function testObjectivesRetired() {
  const sb = loadEngine();
  const { Save } = sb;
  Save.reset(); Save.load(); Save.startRun();
  ok(['RUN_GOAL_DEFS', 'rollRunGoals', 'runGoals', 'goalEvent', 'payRunGoal'].every(k => Save[k] === undefined), 'no side objectives in the save layer');
  ok(Array.isArray(Save.getRun().jobs) && !('goals' in Save.getRun()), 'a run carries its jobs, not goals');
  const src = ['game.js', 'crew.js', 'fire.js', 'ship.js'].map(f => require('fs').readFileSync(require('path').join(__dirname, '..', 'js', f), 'utf8')).join('\n');
  ok(!/goalEvent|_payRunGoals|rollRunGoals/.test(src), 'and nothing counts kills, hulls, wrecks or fires for them any more');
})();

// ============================================================
section('245. Two contracts at the edges of karma');
// ============================================================
(function testKarmaContracts() {
  const sb = loadEngine();
  const { Base, BaseScreen, Save, Game, MISSIONS, Commander, Chips, Ship } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);

  const seat = (karma) => {
    const cap = Commander.fromCrew({ id: 'kc', name: 'Ada', race: 'terra', skills: {} });
    cap.karma = karma;
    Commander.setActive(cap);
    T.commander = cap;
    return cap;
  };

  const relief = MISSIONS.relief, dirty = MISSIONS.runners;
  ok(!!relief && !!dirty, 'both edge contracts exist');

  /* ── VARIANT A: THEY ARE EXTRA, NOTHING IS TAKEN AWAY ──────
   *
   * The three jobs are a difficulty ladder — one, two and three
   * sectors — so gating any of them would remove the game from a
   * commander rather than offer him a choice. */
  ['courier', 'patrol', 'mothership'].forEach(id => {
    ok(!MISSIONS[id].karmaGate, `${id} is never closed by karma`);
    [2, 20, 50, 80, 99].forEach(k => {
      ok(sb.missionRefusal(MISSIONS[id], k) === null,
         `${id} is open at karma ${k}`);
    });
  });

  /* ── THE THRESHOLDS ARE THE BOARD'S OWN WALL ──────────────
   *
   * `Chips.wallColumn` already cuts karma into five bands and the
   * commander can SEE that line on his CPU board. Reading it here
   * means the yard and the board agree by construction; a pair of new
   * numbers would have been a second opinion to keep in step. */
  {
    for (let k = 0; k <= 100; k += 1) {
      const col = Chips.wallColumn(k);
      const hiOpen = sb.missionRefusal(relief, k) === null;
      const loOpen = sb.missionRefusal(dirty, k) === null;
      ok(hiOpen === (col >= 4), `relief at karma ${k} follows the wall (col ${col})`);
      ok(loOpen === (col <= 2), `no-questions at karma ${k} follows the wall (col ${col})`);
      if (k > 4 && k < 96) k += 9;        // sample, but cross every band edge
    }
    ok(sb.missionRefusal(relief, 50) !== null && sb.missionRefusal(dirty, 50) !== null,
       'and the middle of the scale is offered neither — that is the point of the middle');
  }

  /* ── A CLOSED CONTRACT SAYS WHY, ON THE CARD ─────────────── */
  {
    Save.reset(); Save.load();
    seat(50);
    BaseScreen.open();
    BaseScreen._set({ screen: 'dest' });   // the contract board is on the destination screen (update113)
    const marks = captureText(ctx, () => BaseScreen.draw(ctx));
    const drawn = marks.map(d => d.t);
    ok(drawn.some(t => t.includes(relief.label)), 'the relief run is still on the board');
    /* ── THE WHOLE SENTENCE, NOT ITS FIRST HALF (update73) ────
     *
     * update71 drew the reason on ONE line under the blurb, and with
     * five contracts squeezing the cards to 180px the player read
     * "They will not hand their pe…". Every test here passed: a
     * clipped string overlaps nothing. It took a SCREENSHOT of the
     * running game to see it — so the assertion is now the thing that
     * was actually wrong, which is whether the sentence is all there.
     */
    const joined = drawn.join(' ');
    [sb.missionRefusal(relief, 50), sb.missionRefusal(dirty, 50)].forEach(reason => {
      const missing = String(reason).replace(/[.,]/g, '').split(/\s+/)
        .filter(w => w.length > 2 && !joined.includes(w));
      ok(missing.length === 0,
         `the whole reason is on the card, word for word (missing: ${missing.join(' ') || 'nothing'})`);
    });
    /* NOT a blanket "no ellipsis anywhere": the contract TITLES are
       clipped by design when five cards share the bar ("Strike on
       Ap…"), and a clipped NAME is still a name you can recognise and
       click. What must never be cut is the sentence explaining a door
       you cannot open — which is what the loop above checks. */
    ok(!drawn.some(t => /bonus 20 CC/.test(t)),
       'a shut contract does not advertise its bonus — the reason takes that line');

    /* AND IT CANNOT BE PICKED. A card that says "closed" and then
       accepts the click is the greyed-button bug from update68 in a
       new place: the game tells him no and does it anyway. Pressed at
       the REAL rectangle — the same loop the player's mouse goes
       through, not a private hit test. */
    {
      const before = BaseScreen._state().mission;
      const card = marks.find(d => d.t.includes(relief.label));
      ok(!!card, 'the relief card is on screen to be pressed');
      sb.Input.mouse.x = card.x + 10;
      sb.Input.mouse.y = card.y + 4;
      sb.Input.mouse.leftPressed = true;
      BaseScreen.update(0.016);
      sb.Input.mouse.leftPressed = false;
      ok(BaseScreen._state().mission === before,
         `pressing a shut contract changes nothing (${BaseScreen._state().mission})`);
      ok(BaseScreen._state().mission !== 'relief', 'it is certainly not selected');
    }
  }

  /* ── AND AN OPEN CARD'S BLURB STOPS ABOVE THE BONUS LINE ──
   *
   * The shut card's reason moved down into the card body (above), and
   * the OPEN card kept its two-line cap plus the bonus figure. Those
   * two facts are one layout, so they are tested in one place: with
   * five contracts the cards are 180px wide and an uncapped blurb
   * takes a THIRD line 12px above a figure drawn on a 13px rhythm —
   * the words sit on top of each other.
   *
   * Measured against the bonus text's own baseline, not a constant:
   * move either and the test follows. */
  {
    Save.reset(); Save.load();
    seat(50);
    BaseScreen.open();
    BaseScreen._set({ screen: 'dest' });   // the contract board is on the destination screen (update113)
    const marks = captureText(ctx, () => BaseScreen.draw(ctx));
    const LINE = 13;
    let cardsChecked = 0;
    ['courier', 'patrol', 'mothership'].forEach(id => {
      const m = MISSIONS[id];
      const bonus = marks.find(d => d.t.includes(`bonus ${m.ccBonus} CC`));
      ok(!!bonus, `${id} shows its bonus figure`);
      if (!bonus) return;
      const title = marks.find(d => d.x === bonus.x && d.t.includes(m.label.slice(0, 8)));
      ok(!!title, `${id} shows its name above that figure`);
      if (!title) return;
      /* Everything drawn in this card's column between the name and
         the figure is the blurb, whatever it wrapped into. */
      const blurb = marks.filter(d => d.x === bonus.x && d.y > title.y && d.y < bonus.y);
      ok(blurb.length > 0, `${id} prints a blurb at all (${blurb.length} lines)`);
      ok(blurb.some(d => m.blurb.includes(d.t.replace(/…$/, '').trim())),
         `${id}'s blurb is really the mission's own words`);
      const lowest = Math.max(...blurb.map(d => d.y));
      ok(bonus.y - lowest >= LINE,
         `${id}: the blurb stops a clear line above the bonus (gap ${bonus.y - lowest}px, needs ${LINE})`);
      cardsChecked++;
    });
    ok(cardsChecked === 3, `all three open cards were measured (${cardsChecked})`);
    /* AND THE CARDS REALLY ARE THE NARROW ONES. If some future change
       drops the two gated contracts off the board the cards go wide,
       the blurb fits in two lines by luck, and this whole measurement
       stops meaning anything. */
    ok(Base.missions().length === 5,
       `five contracts share the bar, so the cards are the narrow ones (${Base.missions().length})`);
  }

  /* ── AND A SHUT CONTRACT CANNOT BE FLOWN ──────────────────
   *
   * Checked at the LAUNCH as well as on the card: karma moves during a
   * run, so the job a commander picked can be one he no longer
   * qualifies for by the time he presses the button. */
  {
    Save.reset(); Save.load();
    Base.earn(2000);
    seat(50);
    const r = Base.launch({ shipIndex: 0, crewIds: [], mission: 'relief' });
    ok(!r.ok, 'a middling commander cannot launch the relief run');
    ok(/will not hand their people/.test(r.message),
       `and the refusal is the card's own sentence (${r.message})`);
    const r2 = Base.launch({ shipIndex: 0, crewIds: [], mission: 'runners' });
    ok(!r2.ok && /clean record/.test(r2.message), 'nor the dirty one');

    seat(90);
    const r3 = Base.launch({ shipIndex: 0, crewIds: [], mission: 'relief' });
    ok(r3.ok, `a decent name gets the relief run (${r3.message || 'launched'})`);
  }

  /* ── WHAT THEY PAY, AND WHEN ──────────────────────────────
   *
   * Delivering is the deed. Both settle at the END of the contract,
   * like the CC bonus — and before the commander leaves the chair,
   * which is the update68 rule about burial karma, same chair. */
  {
    Save.reset(); Save.load();
    Base.earn(2000);
    const cap = seat(90);
    BaseScreen.open();
    BaseScreen._set({ mission: 'relief' });
    launchNow(BaseScreen);
    T._startContract(BaseScreen.consumeLaunch());
    /* The launch seats whoever was picked in the mess — nobody, here —
       so the man whose karma is being tested takes the chair after it. */
    T.commander = cap;
    ok(Save.getRun().mission === 'relief', 'flying the relief run');
    ok(cap.karma === 90, 'and nothing has been paid for signing it');

    const holdBefore = T.playerShip.cargo.items.length;
    T._finishContract();
    ok(cap.karma === 90 + Commander.KARMA.RESCUE_AT_COST,
       `bringing them out pays the rescue figure (90 → ${cap.karma})`);
    ok(relief.ccBonus < MISSIONS.patrol.ccBonus,
       `and the CC is thin on purpose (${relief.ccBonus} vs ${MISSIONS.patrol.ccBonus})`);
    const shelf = Base.warehouseGrid();
    const chipHere = shelf.items.some(it => it.def.kind === 'tablet') ||
                     (T.playerShip.cargo.items.length > holdBefore);
    ok(chipHere, 'and whatever was left in their lab came home with you');
  }

  {
    Save.reset(); Save.load();
    Base.earn(2000);
    const cap = seat(20);
    BaseScreen.open();
    BaseScreen._set({ mission: 'runners' });
    launchNow(BaseScreen);
    T._startContract(BaseScreen.consumeLaunch());
    /* The launch seats whoever was picked in the mess — nobody, here —
       so the man whose karma is being tested takes the chair after it. */
    T.commander = cap;
    ok(Save.getRun().mission === 'runners', 'flying the dirty one');
    ok(cap.karma === 20, 'signing costs nothing');

    T._finishContract();
    ok(cap.karma === 20 + Commander.KARMA.ROBBERY,
       `delivering the crates is what costs him (20 → ${cap.karma})`);
    ok(dirty.ccBonus > MISSIONS.mothership.ccBonus,
       `and it pays better than the longest honest job (${dirty.ccBonus} vs ${MISSIONS.mothership.ccBonus})`);
    ok(dirty.boss === 'elite', 'with a warlord\'s escort at the end of it');
  }

  Commander.setActive(null);
})();


// ============================================================
section('246. People who are not crew: the cell block, both ways');
// ============================================================
(function testCaptivesAndEscapees() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Game, Base, BaseScreen, Commander, Renderer, UI } = sb;
  const T = Game.__test;

  /* ── ONE FLAG, AND WHAT IT MEANS ──────────────────────────
   *
   * `isPrisoner` is NOT another `isBeast`. A prisoner is a man: he has
   * a name, he can be rescued, and once he is home he is a hand like
   * anybody else. The flag says only "not part of this crew today". */
  {
    const p = new CrewMember({ isPrisoner: true, isPlayer: false });
    ok(p.isPrisoner === true, 'the flag exists');
    ok(!p.isPet, 'and a prisoner is not an animal');
    const back = CrewMember.deserialise(JSON.parse(JSON.stringify(p.serialise())));
    ok(back.isPrisoner === true, 'it survives a save — a hull banked mid-escape keeps him');
  }

  /* ── NOBODY FIGHTS A MAN IN HANDCUFFS, EITHER WAY ─────────
   *
   * The rule that makes the whole feature safe: a boarding party sent
   * to free somebody must not beat him to death on arrival, and he
   * must not swing at the people rescuing him. */
  {
    /* ON A HULL WHERE NOBODY IS BEING RESCUED. Standing a boarder in
       an enemy cell block FREES the man — which would mask the rule
       being tested here, because a freed man is nobody's enemy. So:
       the ship is ours, the prisoner is one who has just broken OUT of
       our brig, and our crew are standing on top of him. */
    const ship = new Ship('frigate', true, 0, 0);
    const room = ship.rooms[1];
    const captive = new CrewMember({ isPlayer: false, isPrisoner: true, name: 'Held' });
    captive._breakingOut = true;
    captive.roomId = room.id; captive.x = room.cx; captive.y = room.cy;
    ship.addCrew(captive, true);
    const boarder = new CrewMember({ isPlayer: true, name: 'Ours' });
    boarder.roomId = room.id; boarder.x = room.cx; boarder.y = room.cy;
    ship.addCrew(boarder, true);

    const hp0 = captive.hp, bhp0 = boarder.hp;
    for (let i = 0; i < 200; i++) {
      // He is walking for an airlock; keep the two of them in contact,
      // or the fight that must not happen never had the chance to.
      boarder.roomId = captive.roomId; boarder.x = captive.x; boarder.y = captive.y;
      boarder.inRoom = true;
      ship.update(0.05);
    }
    ok(captive.hp >= hp0 - 0.01, `nobody strikes the prisoner (${captive.hp}/${hp0})`);
    ok(boarder.hp >= bhp0 - 0.01, `and he strikes nobody (${boarder.hp}/${bhp0})`);
    /* AND STANDING NEXT TO HIM IS NOT A RESCUE. Freeing is for men
       held in somebody ELSE'S cell; a man who has just kicked our own
       cell door open is not waiting to be let out of it, and walking
       up to him must not quietly recruit him. */
    ok(captive.isPrisoner && !captive.isPlayer,
       'a man breaking OUT of our brig is not "rescued" by his own guards');
    ok(!captive.rescued, 'and the dock is not told he was');
  }

  /* ── WALKING IN IS THE RESCUE ─────────────────────────────
   *
   * No order and no button: sending people across a vacuum to a hull
   * with a brig on it IS the decision. What he BECOMES is the trick —
   * one of ours, standing on their deck — because the recovery that
   * brings a boarding party home already sweeps those up. */
  {
    const enemy = new Ship('enemy_frigate', false, 850, 120);
    const room = enemy.rooms[1];
    const captive = new CrewMember({ isPlayer: false, isPrisoner: true, name: 'Held' });
    captive.roomId = room.id; captive.x = room.cx; captive.y = room.cy;
    enemy.addCrew(captive, true);

    enemy.update(0.05);
    ok(captive.isPrisoner, 'nobody there, nobody freed');

    const boarder = new CrewMember({ isPlayer: true, name: 'Ours' });
    boarder.roomId = room.id; boarder.x = room.cx; boarder.y = room.cy;
    enemy.addCrew(boarder, true);
    enemy.update(0.05);

    ok(!captive.isPrisoner, 'a boarder in the cell block frees him');
    ok(captive.isPlayer === true, 'and he is ours from that moment');
    ok(captive.rescued === true, 'marked as somebody you got out, for the dock to read');
    ok(captive.race !== 'hostile', `and drawn as one of ours, not in their red (${captive.race})`);
  }

  /* ── A MAN IN THEIR CELL IS NOT A DEFENDER ────────────────
   *
   * Counting him would mean their decks were never cleared, so the
   * derelict branch — and the commander's surrender with it — could
   * never fire on a hull that happened to be carrying prisoners. */
  {
    const c = makeCombat(sb);
    c.enemy.crew.filter(k => !k.isPlayer).forEach(k => { k.hp = 0; k.state = 'dead'; k.dead = true; });
    const room = c.enemy.rooms[1];
    const captive = new CrewMember({ isPlayer: false, isPrisoner: true, name: 'Held' });
    captive.roomId = room.id; captive.x = room.cx; captive.y = room.cy;
    c.enemy.addCrew(captive, true);
    ok(T._enemyCrewAliveCount() === 0,
       `their decks read as cleared with a prisoner still aboard (${T._enemyCrewAliveCount()})`);
  }

  /* ── THEY ARE SEATED WHERE THEY CAN BE FOUND ──────────────
   *
   * Only on a hull with a brig — the module is drawn on the enemy
   * blueprint, so a player who has learned to read it knows there is
   * something to send people across FOR before he sends them. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const c = makeCombat(sb);
    let carrying = 0, heldWithoutBrig = 0;
    for (let i = 0; i < 60; i++) {
      T._spawnEnemy('normal');
      const brig = T.enemyShip.getSystem('carbonite');
      const held = T.enemyShip.crew.filter(k => k.isPrisoner).length;
      if (held) {
        carrying++;
        if (!brig) heldWithoutBrig++;
      }
    }
    /* NO LAYOUT IN THE GAME SHIPS WITH A BRIG — which is why the first
       version of this feature seated nobody, ever, on any hull, and
       why the breaking run could not tell "never" from "always". A
       hull that is carrying prisoners is GIVEN a cell block, so the
       player can read it off their blueprint before he sends anybody
       across. */
    ok(heldWithoutBrig === 0,
       `nobody is ever held on a hull with no cell block (${heldWithoutBrig})`);
    ok(carrying > 4, `some hulls carry prisoners (${carrying} of 60)`);

    /* THE ROLL ITSELF, with the dice nailed down. Counting hulls is not
       enough to see it: whether a cell block can be FITTED depends on
       the loadout leaving a bay free, so the rate the sample shows is
       two dice multiplied together and "always" looks much like
       "sometimes". Force the roll either way instead. */
    {
      /* THE ROLL ON ITS OWN, on a hull prepared by hand.
         Stubbing the dice around a whole `_spawnEnemy` cannot answer
         this: the SAME `Math.random` picks the loadout first, so a
         value low enough to win the captive roll is also low enough to
         fit shields — and a hull with shields has no bare bay to put
         cells in. The two rolls are anti-correlated under a constant
         stub, which is a trap worth writing down. */
      const prep = () => {
        T._spawnEnemy('normal');
        const sh = T.enemyShip.getSystem('shields');
        if (sh) {
          const r = T.enemyShip.getRoomById(sh.roomId);
          T.enemyShip.systems = T.enemyShip.systems.filter(sy => sy !== sh);
          if (r) { r.system = null; r.type = 'empty'; }
        }
        const cl = T.enemyShip.getSystem('cloaking');
        if (cl) {
          const r = T.enemyShip.getRoomById(cl.roomId);
          T.enemyShip.systems = T.enemyShip.systems.filter(sy => sy !== cl);
          if (r) { r.system = null; r.type = 'empty'; }
        }
        return T.enemyShip.rooms.some(r => r.type === 'empty');
      };
      const realRandom = sb.Math.random;
      let cold = 0, hot = 0, tries = 0;
      try {
        for (let i = 0; i < 12; i++) {
          if (!prep()) continue;
          tries++;
          sb.Math.random = () => 0.99;          // over the threshold
          cold += T._seatCaptives();
          sb.Math.random = () => 0.01;          // under it
          hot += T._seatCaptives();
          sb.Math.random = realRandom;
        }
      } finally { sb.Math.random = realRandom; }
      ok(tries > 0, `hulls with a bare bay to prepare (${tries})`);
      ok(cold === 0, `a losing roll seats nobody, every time (${cold})`);
      ok(hot > 0, `and a winning one fills the cells (${hot})`);
    }
  }

  /* ── AND THE YARD PAYS FOR THEM IN THE ONLY COIN IT HAS ──── */
  {
    Save.reset(); Save.load();
    Base.earn(1000);
    BaseScreen.open();
    launchNow(BaseScreen);
    T._startContract(BaseScreen.consumeLaunch());
    const cap = Commander.fromCrew({ id: 'r1', name: 'Ada', race: 'terra', skills: {} });
    cap.karma = 50; cap.away = true;
    Commander.setActive(cap); T.commander = cap;

    const saved = new CrewMember({ isPlayer: true, name: 'Held' });
    saved.rescued = true;
    T.playerShip.addCrew(saved);

    const bunks = Base.crew().length;
    T._dockAtBase(0, () => {});
    ok(cap.karma === 50 + Commander.KARMA.RESCUE_AT_COST,
       `bringing one home pays the rescue figure (50 → ${cap.karma})`);
    ok(Base.crew().some(k => k.name === 'Held') || Base.crew().length === bunks,
       'and he goes into a bunk — or is turned away if there is none, out loud');
    Commander.setActive(null);
  }

  /* ══ AND NOW THE OTHER SIDE OF THE SAME FLAG ══════════════
   *
   * An escaper out of YOUR cell. update67 made this a line of text:
   * the clock ran out, a notification appeared, the man ceased to
   * exist. The player's design said otherwise — he runs for an airlock
   * and a door can stop him — and text cannot be interrupted. */
  const jail = () => {
    const ship = new Ship('hauler', true, 0, 0);
    const room = ship.rooms.find(r => r.type === 'empty');
    ship.addModuleAt('carbonite', room.id);
    const brig = ship.getSystem('carbonite');
    powerModule(ship, 'carbonite', 1);
    ship.takePrisoner({ id: 'p1', name: 'Garro', bounty: 120, wantedId: null });
    return { ship, brig };
  };

  {
    Save.reset(); Save.load(); Save.startRun();
    const { ship, brig } = jail();
    brig.power = 0; brig.desiredPower = 0;
    for (let i = 0; i < Ship.ESCAPE_SECONDS + 5; i++) ship.prisonerTick(1);
    const runner = ship.crew.find(k => k.isPrisoner);
    ok(!!runner, 'the cell clock puts a MAN in the corridor');
    ok(runner.name === 'Garro', 'with the name that was in the cell');
    ok(ship.prisoners.length === 0, 'and the cell is empty');

    /* A SHUT DOOR IS THE WHOLE POINT. Seal the hull and he is still
       aboard when the clock has long run out — that is the real time
       the player was promised. */
    /* HE PICKS THE OUTER LOCK LIKE ANY INTRUDER — the same
       `Door.HACK_TIME` a boarding party pays for a strange door. So a
       player holding the hatch shut is buying SECONDS, not immunity,
       and those seconds are the whole mechanic: enough to get a hand
       to him, not enough to forget about him. */
    ship.doors.forEach(d => { d.mode = 'closed'; d.open = false; d.openness = 0; });
    for (let i = 0; i < 20; i++) {
      ship.doors.forEach(d => { d.mode = 'closed'; d.open = false; d.hacked = { player: false, enemy: false }; d.hackT = 0; });
      ship.update(0.05);
    }
    ok(ship.crew.includes(runner),
       'a hatch held shut in his face keeps him aboard while it is held');

    /* AND PICKING THAT LOCK COSTS HIM THE SAME AS ANY INTRUDER.
       Let go of the hatch and time him: under `Door.HACK_TIME` would
       mean the door was never really in his way, which is the whole
       promise of the walk. */
    {
      /* TIMED FROM THE HATCH, not from the brig: standing him in the
         airlock's own compartment takes the WALK out of the figure, so
         what is left is the lock. Under `Door.HACK_TIME` means the
         door was never in his way, which is the whole promise of
         making the escape a walk in the first place. */
      const air = ship.doors.find(d => d.isAirlock);
      const room = ship.getRoomById(air.roomA);
      runner.roomId = room.id;
      runner.x = room.cx; runner.y = ship.floorWalkY(room.floor, room.cy);
      runner._waypoints = [];
      ship.doors.forEach(d => { d.hacked = { player: false, enemy: false }; d.hackT = 0;
                                d.mode = 'closed'; d.open = false; d.openness = 0; });
      let frames = 0;
      while (frames < 4000 && ship.crew.includes(runner)) { ship.update(0.05); frames++; }
      ok(!ship.crew.includes(runner), 'with nobody holding it he does get out');
      ok(frames * 0.05 >= sb.Door.HACK_TIME,
         `and it cost him the same as any strange lock — ${(frames * 0.05).toFixed(1)}s `
       + `against ${sb.Door.HACK_TIME}s`);
    }
  }

  /* ── AND HE DOES NOT DO THE SHIP'S WORK ON THE WAY OUT ─────
   *
   * He leaves the crew AI before any of it. A prisoner who fell
   * through into the normal duties would stop to carry a body or
   * repair a module for the people whose cell he has just left. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const { ship, brig } = jail();
    brig.power = 0; brig.desiredPower = 0;
    for (let i = 0; i < Ship.ESCAPE_SECONDS + 5; i++) ship.prisonerTick(1);
    const runner = ship.crew.find(k => k.isPrisoner);
    ok(!!runner, 'he is loose');

    /* AND A CORNERED MAN GOES BACK IN THE CELL. One row on the menu
       that is already there — the reward for having watched. */
    ok(ship.cellRefusal(runner) !== null, 'with the brig dark there is nowhere to put him');
    brig.power = 1; brig.desiredPower = 1;
    ok(ship.cellRefusal(runner) === null, 'power it and there is');
    const r = ship.returnToCell(runner);
    ok(r.ok, `and he goes back (${r.message})`);
    ok(ship.prisoners.length === 1, 'the cell has him again');
    ok(!ship.crew.includes(runner), 'and the corridor does not');
    ok(ship.prisoners[0].name === 'Garro', 'the same man, by name');
  }

  /* ── AND HE DOES NOT DO THE SHIP'S WORK ON THE WAY OUT ─────
   *
   * His own crew loop hands out repairs, fires and stretchers. A
   * prisoner who fell through into it would stop to fix the module of
   * the ship he is trying to get off — so he leaves that loop too, and
   * this is the block that proves it. Its own hull, because powering a
   * brig and a medbay on one hauler reactor is a fight over watts that
   * has nothing to do with what is being tested. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const { ship, brig } = jail();
    brig.power = 0; brig.desiredPower = 0;
    for (let i = 0; i < Ship.ESCAPE_SECONDS + 5; i++) ship.prisonerTick(1);
    const runner = ship.crew.find(k => k.isPrisoner);
    ok(!!runner, 'he is loose');

    /* HOLD HIM STILL AND OFFER HIM THE WORK. A man walking for an
       airlock is a man who never meets the job, so "he did no work"
       would be true of somebody who was never asked: take the airlocks
       off this hull and he stands where he is, with a shot-out module
       and a casualty in his own compartment. */
    ship.doors.forEach(d => { d.isAirlock = false; });
    const sys = ship.systems.find(sy => sy.roomId === runner.roomId && sy.type !== 'reactor')
             || ship.systems.find(sy => sy.type !== 'reactor' && sy.roomId);
    runner.roomId = sys.roomId;
    const sroom = ship.getRoomById(sys.roomId);
    runner.x = sroom.cx; runner.y = ship.floorWalkY(sroom.floor, sroom.cy);
    runner._waypoints = [];
    const broken0 = sys.damagedLevels;

    const hurt = new CrewMember({ isPlayer: true, name: 'Down' });
    hurt.roomId = runner.roomId; hurt.x = runner.x; hurt.y = runner.y;
    hurt.state = 'injured'; hurt.hp = 1;
    ship.addCrew(hurt, true);

    /* AND A CORPSE WITH A BURIAL ORDER ON IT, which is the one job
       the SHIP hands out rather than the crew loop — two different
       loops, two different guards, and a prisoner has to leave both. */
    const corpse = new CrewMember({ isPlayer: true, name: 'Gone' });
    corpse.roomId = runner.roomId; corpse.x = runner.x + 4; corpse.y = runner.y;
    ship.addCrew(corpse, true);
    corpse.killOutright('test');
    corpse.bodyOrder = 'eject';

    /* ── THE BODY FIRST, ON A QUIET DECK ─────────────────────
     *
     * A DAMAGED module in the same compartment suppresses body-lifting
     * for everybody (the update38 rule: emergencies first), so with
     * both offered at once the corpse test proved nothing — it passed
     * on a build where a prisoner will happily carry your dead. The
     * two jobs are offered one at a time. */
    for (let i = 0; i < 300; i++) ship.update(0.05);
    ok(!runner.carrying,
       'he does not pick up the body lying at his feet — he is not this ship\'s stretcher party');
    ok(!runner._rescueId && !runner._bagTargetId, 'nor is he sent on its errands');
    ok(ship.crew.includes(corpse), 'and the corpse is exactly where it fell');

    // …and now the broken module, with the body cleared away.
    ship.crew = ship.crew.filter(c => c !== corpse);
    sys.damageLevel(1);
    const broken1 = sys.damagedLevels;
    ok(broken1 > 0, 'a module in his compartment is shot out');
    for (let i = 0; i < 300; i++) ship.update(0.05);
    ok(runner.task !== 'repair', `and he does no repairs (${runner.task})`);
    ok(sys.damagedLevels >= broken1,
       `their module is exactly as broken as he found it (${sys.damagedLevels} of ${broken1})`);
    ok(runner.task !== 'repair', `and does no repairs (${runner.task})`);
    ok(sys.damagedLevels >= broken0,
       `their module is exactly as broken as he found it (${sys.damagedLevels} of ${broken0})`);

  }

  /* THE MENU OFFERS EXACTLY THAT ONE ROW, and the click reaches it. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const { ship, brig } = jail();
    sb.makeStartingCrew().forEach(k => ship.addCrew(k));
    brig.power = 0; brig.desiredPower = 0;
    for (let i = 0; i < Ship.ESCAPE_SECONDS + 5; i++) ship.prisonerTick(1);
    const runner = ship.crew.find(k => k.isPrisoner);
    T.playerShip = ship;

    const rows = T._menuActsFor(runner);
    ok(rows.join(',') === 'cell',
       `one row, and it is the cell (${rows.join(',') || 'none'})`);
    ok(!rows.includes('feed') && !rows.includes('bag'),
       'he is not fed and not bagged while he is alive');

    // The right-click has to find him at all — he is not `isPlayer`.
    const found = T._bodyUnderCursor(runner.x, runner.y);
    ok(found === runner,
       `and the cursor finds him, so the row can be reached (${found ? found.name + ' at ' + Math.round(found.x) + ',' + Math.round(found.y) : 'nobody'}; he is at ${Math.round(runner.x)},${Math.round(runner.y)})`);
  }

  /* THE BOARD IS WRITTEN WHEN HE IS GONE, NOT WHEN HE IS LOOSE.
     update67 wrote it the instant the cell door opened, which is why
     trapping him could never have meant anything. */
  {
    Save.reset(); Save.load(); Save.startRun();
    const before = Save.wanted().length;
    const { ship, brig } = jail();
    brig.power = 0; brig.desiredPower = 0;
    for (let i = 0; i < Ship.ESCAPE_SECONDS + 5; i++) ship.prisonerTick(1);
    ok(Save.wanted().length === before,
       'a man in the corridor is not yet a man on the board');

    /* THE SECOND SENTENCE. The first one — "he is out of the cell" —
       is tested above; this is the one that closes the story, and it
       is the only place the new bounty is ever said out loud. */
    const saidOnLeaving = [];
    const realNotify = UI.notify;
    UI.notify = (m) => { saidOnLeaving.push(String(m)); };
    let gone = false;
    try {
      for (let i = 0; i < 4000 && !gone; i++) {
        ship.update(0.05);
        gone = !ship.crew.some(k => k.isPrisoner);
      }
    } finally { UI.notify = realNotify; }
    ok(gone, 'he reaches an airlock and goes');
    ok(Save.wanted().length === before + 1, 'and THEN the yard hears about him');
    ok(saidOnLeaving.some(t => /out the airlock/.test(t)),
       `and the game says he is away, with what it cost (${saidOnLeaving.join(' / ') || 'silence'})`);

    /* AND HIS POSTER HAS AN ADDRESS. update70 gave every name a
       contract; this branch builds its record by hand, so it had to be
       told — a poster with no contract is a man no map can ever
       seat. */
    const fresh = Save.wanted().find(w => w.name === 'Garro');
    ok(!!fresh, 'he is up under his own name');
    ok(!!fresh.mission && !!sb.MISSIONS[fresh.mission],
       `on a contract you can actually fly (${fresh.mission})`);
  }
})();

// ============================================================
section('247. The tile grid, the ceiling duct and a hull with a profile');
// ============================================================
(function testTileGrid() {
  const sb = loadEngine();
  const { Ship, SHIP_LAYOUTS, HULL_GRID } = sb;
  const G = HULL_GRID;

  /* ── EVERY LENGTH IS A WHOLE NUMBER OF TILES ──────────────
   *
   * This is the assertion the art kit rests on. A handful of 10x10
   * squares — a corner, an edge, a floor plate, a duct — can only
   * cover every hull in the game if nothing in the grid is 47 wide.
   * Nudge one number by a pixel for one screen and this fails, which
   * is the point: the drift update41 killed came back one hull at a
   * time precisely because nothing ever said no. */
  ok(G.TILE > 0, `there is a tile (${G.TILE}px)`);
  ['MODULE_W', 'MODULE_H', 'VENT_H', 'DECK_GAP', 'DECK_PITCH',
   'SHAFT_W', 'MARGIN', 'ENGINE_W', 'PROW_W'].forEach(k => {
    ok(Number.isInteger(G[k] / G.TILE),
       `${k} is a whole number of tiles (${G[k]} = ${G[k] / G.TILE} x ${G.TILE})`);
  });

  /* And so is every room the hull builder lays down — the grid is
     only one source if the rooms actually come out of it. */
  Object.entries(SHIP_LAYOUTS).forEach(([k, L]) => {
    L.rooms.forEach(r => {
      ok(Number.isInteger(r.x / G.TILE) && Number.isInteger(r.y / G.TILE),
         `${k}/${r.id} sits on the tile grid (${r.x}, ${r.y})`);
    });
  });

  /* ── THE MODULE LIES DOWN ─────────────────────────────────
     80x72 read as a cell. The compartment is wider than it is tall
     now, and that is a design claim worth failing over rather than a
     pair of numbers that happen to be what they are today. */
  ok(G.MODULE_W > G.MODULE_H,
     `a compartment is wider than it is tall (${G.MODULE_W}x${G.MODULE_H})`);

  /* ── THE DUCT IS INSIDE THE MODULE, AND NOBODY WALKS IN IT ─ */
  {
    ok(G.VENT_H > 0 && G.VENT_H < G.MODULE_H,
       `the duct is a strip inside the module (${G.VENT_H} of ${G.MODULE_H})`);
    ok(G.DECK_GAP === 0,
       'and it IS the gap between decks — there is no second gap to keep in step');

    const ship = new Ship('scout', true, 0, 0);
    ship.rooms.forEach(r => {
      /* UNDER THE DECK SINCE update120 (jj): the duct is the module's
         bottom strip, the crew walk on its lid. */
      ok(r.ventY === r.y + r.h - G.VENT_H && r.ventH === G.VENT_H,
         `${r.id}: the duct runs under the deck`);
      ok(r.floorTop === r.y && r.floorH === r.h - G.VENT_H,
         `${r.id}: the room the crew stand in is above it`);
      /* THE ONE THAT MATTERS. A man standing in the duct is a man
         standing in the ceiling, and it is the reason `walkOffset()`
         measures from the interior rather than from the module. */
      const feet = ship.floorWalkY(r.floor, r.cy);
      ok(feet > r.floorTop && feet < r.y + r.h,
         `${r.id}: the crew's feet are on the deck, not in the duct (${feet} in ${r.floorTop}..${r.y + r.h})`);
    });

    /* ── THE DUCT'S THICKNESS MUST NOT MOVE THE CREW ────────
     *
     * The bounds above are too loose on their own, and the breaking
     * run said so: `MODULE_H * WALK_FRAC` puts the feet at 39 in a
     * 60px module, which is still below the duct and still above the
     * floor, so it slipped through.
     *
     * The property that actually distinguishes the two is this one:
     * the crew stand at a fixed fraction of the WALKABLE height, so
     * making the duct thicker must not change where they stand
     * RELATIVE TO THE DECK THEY ARE ON. Measured by thickening the
     * duct and asking again — an independent question, not the
     * formula asked twice.
     *
     *   right:  17.5/50 = 0.35   and   14/40 = 0.35
     *   wrong:  21.0/50 = 0.42   and   21/40 = 0.53
     */
    {
      const was = G.VENT_H;
      const ratio = () => {
        const s = new Ship('scout', true, 0, 0);
        const r = s.rooms[0];
        return (s.floorWalkY(r.floor, r.cy) - r.floorTop) / r.floorH;   // within the walkable room (update120)
      };
      const thin = ratio();
      G.VENT_H = was * 2;
      const thick = ratio();
      G.VENT_H = was;
      ok(Math.abs(thin - thick) < 0.001,
         `a thicker duct does not shift the crew off the deck (${thin.toFixed(3)} vs ${thick.toFixed(3)})`);
      ok(Math.abs(ratio() - thin) < 1e-9, 'and the duct is put back afterwards');
    }

    /* A FITTED MODULE OCCUPIES THE INTERIOR TOO — the badge used to
       be drawn at `room.y + 3`, which is now behind the grille. */
    ship.systems.filter(s => s.roomId).forEach(s => {
      const r = ship.getRoomById(s.roomId);
      ok(s.roomY === r.floorTop && s.roomH === r.floorH,
         `${s.label} is fitted into the compartment, not into the ceiling`);
    });
  }

  /* ── ONE DEFINITION OF THE WALK LINE ──────────────────────
   *
   * `walkOffset()` had two other copies before this package — one in
   * the hull builder's lift stops, one written out longhand in
   * `floorWalkY`. They agreed only while the ceiling was walkable.
   * Asserted by asking the LIFT and the CREW independently and
   * requiring the same answer. */
  Object.keys(SHIP_LAYOUTS).forEach(k => {
    const ship = new Ship(k, true, 0, 0);
    (ship.layout.elevators ?? []).forEach(ev => {
      ev.floors.forEach(fy => {
        ok(ship.rooms.some(r => Math.abs(ship.floorWalkY(r.floor, r.cy) - fy) < 0.01),
           `${k}: the lift stops where somebody can step off it (${fy.toFixed(1)})`);
      });
    });
  });

  /* ── TWO HULLS STILL FIT ON THE CANVAS ────────────────────
   *
   * The camera never zooms — `Camera.setZoom` is called from nowhere
   * in the game — so both hulls are drawn 1:1 into 1280 and this is
   * a hard wall, not a preference. Measured against the WIDEST hull
   * on each side, because that is the pair that decides it.
   *
   * It was 120px wide modules that this killed: two four-column hulls
   * came to 1268 of 1280 and left twelve pixels for the shells.
   */
  {
    /* Every hull the yard sells (update95 added three) — was a list
       typed out here, which a new hull for sale would have walked past. */
    const PLAYER = Object.keys(sb.SHIP_CATALOG ?? {}).filter(k => SHIP_LAYOUTS[k]);
    const ENEMY  = Object.keys(SHIP_LAYOUTS).filter(k => !PLAYER.includes(k));
    ok(PLAYER.length >= 2 && ENEMY.length >= 2, 'both sides have hulls to pick from');

    /* What the hull really covers (update121): its plate, its nose and its
       nacelles — which are on top and underneath now, their nozzles a
       little past the stern. */
    const span = (k, isP, wx) => {
      const sh = new Ship(k, isP, wx, 0), g = sh.hullArtGeometry(), b = g.bounds;
      const xs = [b.x - G.MARGIN, b.x + b.w + G.MARGIN, ...g.engines.flatMap(e => [e.x, e.x + e.w]),
                  ...g.prows.flatMap(p => [p.x, p.x + p.w])];
      return [Math.min(...xs), Math.max(...xs)];
    };
    const widest = (keys, isP, wx) => keys.reduce((best, k) => {
      const s = span(k, isP, wx);
      return (s[1] - s[0]) > (best[1] - best[0]) ? s : best;
    }, [0, 0]);

    const p = widest(PLAYER, true,  Ship.PLAYER_STATION.x);
    const e = widest(ENEMY,  false, Ship.ENEMY_STATION.x);
    ok(p[0] >= 0, `the widest hull's stern is on screen (${p[0].toFixed(0)})`);
    ok(e[1] <= 1280, `the widest enemy's stern is on screen (${e[1].toFixed(0)})`);
    ok(e[0] > p[1],
       `and they do not overlap (gap ${(e[0] - p[1]).toFixed(0)}px)`);
    /* A gap the shells have to cross. Two hulls touching is not a
       fight, it is a diagram. */
    ok(e[0] - p[1] >= 40,
       `with room between them for the shooting (${(e[0] - p[1]).toFixed(0)}px)`);

    /* AND THE ORDERS PANEL IS NOT UNDER THE SHIP. It ends around
       x=120; a hull drawn over it is a hull you cannot give orders
       through. This is what stops the player being slid left to make
       room, so it is written down rather than remembered. */
    ok(p[0] >= 125, `the hull clears the orders panel (${p[0].toFixed(0)} >= 125)`);
  }

  /* ── A HULL WITH A PROFILE ────────────────────────────────
   *
   * Bastet grew a spur: a fourth bay on the upper deck with nothing
   * under it. The test is not "she has seven rooms" — she has six,
   * the free bay MOVED — it is that her bounding box contains a grid
   * square with no module in it. That is the fact the hull plate has
   * to cope with, and the reason it can no longer be one rectangle
   * drawn around `roomBounds()`.
   */
  {
    const ship = new Ship('scout', true, 0, 0);
    const cells = new Set(ship.rooms.map(r => `${r.x},${r.y}`));
    const xs = [...new Set(ship.rooms.map(r => r.x))];
    const ys = [...new Set(ship.rooms.map(r => r.y))];
    let holes = 0;
    xs.forEach(x => ys.forEach(y => { if (!cells.has(`${x},${y}`)) holes++; }));
    ok(holes > 0, `the starter hull is not a rectangle — ${holes} empty square(s) inside her bounds`);

    /* AND THE FREE BAY IS STILL EXACTLY ONE. The first attempt at the
       spur ADDED a bay instead of moving it, which quietly handed the
       starter ship two free modules — and "the empty bay is the first
       real refit decision" stops being true at two. */
    const empties = ship.rooms.filter(r => r.type === 'empty');
    ok(empties.length === 1,
       `and she still has exactly one bay to fit something into (${empties.length})`);
    ok(empties[0].floor === Math.max(...ship.rooms.map(r => r.floor)),
       'which is the spur, on the top deck');
  }

  /* ── AND THE PLATE IS THE UNION OF THE MODULES ────────────
   *
   * Asserted on what is DRAWN, not on the source: every module puts
   * its own rounded rectangle into the hull path, and so does every
   * lift trunk. Miss the trunks and the plate has a ten-pixel notch
   * bitten out of it at each lift — SHAFT_W is 30 and the modules
   * either side are grown by MARGIN, which is 10 a side.
   *
   * One rectangle around the bounding box would satisfy nothing here,
   * which is the point: that is what this replaced. */
  {
    const ctx = initRenderer(sb);
    const ship = new Ship('scout', true, 0, 0);
    const rects = [];
    const real = ctx.roundRect;
    ctx.roundRect = function (x, y, w, h) { rects.push({ x, y, w, h }); };
    try { ship.draw(ctx); } finally { ctx.roundRect = real; }

    ship.rooms.forEach(r => {
      ok(rects.some(q => Math.abs(q.x - (r.x - G.MARGIN)) < 0.01 &&
                         Math.abs(q.y - (r.y - G.MARGIN)) < 0.01),
         `${r.id} puts its own square into the hull plate`);
    });
    /* THE TRUNK RECTANGLE IS THE FULL HEIGHT OF THE HULL, and that
       clause is load-bearing. Without it the assertion was satisfied
       by the LIFT'S OWN CABIN — `elevators.draw` puts a 22px rounded
       rect on the same centre line — so deleting the plate's trunk
       loop left this passing on somebody else's rectangle. The
       breaking run caught it; the suite did not. */
    const bb = ship.roomBounds();
    const shafts = ship.elevators?.shafts ?? [];
    ok(shafts.length > 0, `the starter hull has a lift trunk to test (${shafts.length})`);
    shafts.forEach(sh => {
      ok(rects.some(q => Math.abs((q.x + q.w / 2) - sh.x) < 0.01 &&
                         Math.abs(q.w - (G.SHAFT_W + G.MARGIN * 2)) < 0.01 &&
                         q.h >= bb.h),
         `the plate crosses the lift trunk at ${sh.x} instead of notching around it`);
    });
  }
})();


// ============================================================
section('249. The salvage clock is one number, and a shorter one');
// ============================================================
(function testLootClock() {
  const sb = loadEngine();
  const { Ship, Save, LootScreen, Game } = sb;
  const T = Game.__test;

  /* ── ONE NUMBER ───────────────────────────────────────────
   *
   * Fifty seconds was written out in FIVE places in game.js — three
   * `?? 50` defaults, the `_wreckSecs` initialiser and a floor of 20 —
   * so shortening it meant finding all five and changing four of them
   * would have left a derelict that still gave you the old minute.
   *
   * Asserted by asking the SCREEN, through the same call the map makes
   * when the player docks with a wreck. Reading the constant back to
   * itself would prove nothing. */
  Save.reset(); Save.load(); Save.startRun();
  T.playerShip = new Ship('frigate', true, 80, 120);
  sb.makeStartingCrew().forEach(c => T.playerShip.addCrew(c));

  ok(Ship.LOOT_SECONDS > 0, `there is a salvage clock (${Ship.LOOT_SECONDS}s)`);
  ok(Ship.LOOT_SECONDS_MIN > 0 && Ship.LOOT_SECONDS_MIN < Ship.LOOT_SECONDS,
     `with a floor under it (${Ship.LOOT_SECONDS_MIN}s)`);

  /* ── AND A SHORTER ONE ────────────────────────────────────
   *
   * The player's report: *„za dużo mamy teraz czasu do namysłu"*. In
   * fifty seconds a hold is solved like a Tetris board, at leisure,
   * which is the opposite of what a clock on a derelict is for.
   *
   * Written as "less than the fifty it was" rather than "equal to 30",
   * so tuning the dial does not break the test but UNDOING the change
   * does — the point is the direction, not the digit. */
  ok(Ship.LOOT_SECONDS < 50,
     `and it is shorter than the fifty that was too long (${Ship.LOOT_SECONDS}s)`);

  /* ── AND THE TOP BUTTONS CLEAR THE OBJECTIVE LINE ─────────
   *
   * "OBJ nachodzi na SHOW MAP i CARGO": the run-goal line sits at y 40
   * with a height of 17 and SHOW MAP sat at y 42, drawn straight
   * through it.
   *
   * Measured against `Renderer.runGoalsBox()` — the line's own
   * description — so this is two rectangles being asked whether they
   * touch, not two sets of coordinates typed in twice and compared
   * with each other.
   *
   * The second clause is the one that will save somebody later: the
   * buttons must sit in the SAME place whether or not the contract
   * carries objectives. Placing them under the line only when the line
   * has something on it would pass the overlap test and give the
   * player a button that moves between contracts. */
  {
    const box = sb.Renderer.runGoalsBox();
    const overlaps = (a, b) =>
      a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    const line = { x: 470, y: box.y, w: box.w, h: box.h };

    Save.updateRun({ jobs: [{ id: 'jx', kind: 'cargo', client: 'Test Co.', crates: 1, port: 'any', sector: 1, pay: 50, fine: 25, state: 'aboard' }] });   // update161: the line carries jobs
    const map = T._mapToggleRect(), hold = T._holdBtnRect();
    ok(!overlaps(map, line),
       `SHOW MAP clears the objective line (button y ${map.y}, line ends ${line.y + line.h})`);
    ok(!overlaps(hold, line), `and so does CARGO (y ${hold.y})`);
    /* SIDE BY SIDE since update74 — stacking them put CARGO through
       the green "CHOOSE YOUR STARTING LANE" banner, which is the first
       thing a player sees in a run. They must not overlap EACH OTHER
       either, which is what this asks. */
    ok(!overlaps(map, hold), 'and the two buttons do not sit on top of one another');
    ok(hold.y === map.y, 'they share a row');
    ok(hold.x >= map.x + map.w, 'with CARGO beside SHOW MAP, not under it');

    /* AND THE WHOLE STRIP STILL CLEARS THE MAP PANEL, which starts at
       y 115. That is the wall the second row ran into. */
    ok(map.y + map.h <= 115,
       `the button row ends above the map panel (${map.y + map.h})`);

    Save.updateRun({ goals: [] });
    ok(T._mapToggleRect().y === map.y && T._holdBtnRect().y === hold.y,
       'and neither moves on a contract with no objectives at all');
  }

  {
    T._startWreckBoarding(2);
    T._wreckCleared?.();
    const left = LootScreen.secondsLeft();
    ok(left !== null, 'boarding a derelict puts the player on a clock');
    ok(left === Ship.LOOT_SECONDS,
       `and it is the one number, not a copy of it (${left} vs ${Ship.LOOT_SECONDS})`);
  }
})();


// ============================================================
section('248. Drawn art overrides the generated art, and never hangs the boot');
// ============================================================
(function testArtLoader() {
  const sb = loadEngine();
  const { Assets, HULL_GRID } = sb;
  const G = HULL_GRID;

  /* ── THE DUCT IS TWO TILES AND THE DECK DID NOT MOVE ──────
   *
   * update73 chose one tile by eye and the eye was wrong — the sprites
   * that are going to live up there were rendered in a browser and
   * their pixels counted (browser_test.js asserts that measurement
   * against real ink; this is the geometry half).
   *
   * The clause that matters is the SECOND one. The module grew and
   * the interior did not, so every number the crew touch — the walk
   * line, the doors, the standing spots — is exactly where it was. */
  /* ── EVERY MODULE WEARS ITS OWN BADGE (update74) ──────────
   *
   * Five of them did not. The reactor and the cloak both showed
   * ENGINES, the repair bay and the brig both showed the MEDBAY
   * cross, and the artillery showed the ordinary gun — five
   * compartments lying about what they are, on a screen whose only
   * job is to tell you what a hull is made of.
   *
   * Two assertions, and the second is the one that keeps it: a name
   * that no generator answers to is a silent fallback to nothing. */
  {
    const seen = new Map();
    Object.entries(sb.SYSTEM_DEFS).forEach(([type, def]) => {
      ok(!!def.icon, `${type} names an icon`);
      const other = seen.get(def.icon);
      ok(!other, `${type} does not borrow ${other || ''}'s badge (${def.icon})`);
      seen.set(def.icon, type);
    });
  }

  ok(G.VENT_H === 2 * G.TILE, `the duct is two tiles (${G.VENT_H})`);
  ok(G.MODULE_H - G.VENT_H === 50,
     `and the deck is still fifty pixels of walkable room (${G.MODULE_H - G.VENT_H})`);

  /* ── THE LOADER ───────────────────────────────────────────
   *
   * The rule it exists to keep: a file OVERRIDES a generated sprite,
   * it never replaces the generator. The game has to boot with no art
   * at all, because today it has none and on the day a file fails to
   * load it still has to start.
   *
   * Driven through fake `fetch` and `Image`, with a 30ms timeout
   * passed in — the real one is four seconds, and four seconds inside
   * a suite that a breaking run executes four hundred times is
   * twenty-six minutes of nothing.
   */
  const NAME = 'icon_medbay';
  const realFetch = sb.fetch, realImage = sb.Image;
  const restore = () => { sb.fetch = realFetch; sb.Image = realImage; };

  const manifest = (body) => {
    sb.fetch = () => Promise.resolve({ ok: true, json: () => Promise.resolve(body) });
  };
  /** An Image that succeeds, fails, or — the interesting one — never
   *  answers at all, which is the shape of a boot that never finishes. */
  const imageThat = (how) => {
    sb.Image = class {
      constructor() { this.width = 0; this.height = 0; }
      set src(_v) {
        if (how === 'never') return;
        setTimeout(() => {
          if (how === 'load') { this.width = 8; this.height = 8; this.onload?.(); }
          else this.onerror?.();
        }, 0);
      }
    };
  };

  const run = async () => {
    /* ── FIRST, THROUGH THE FRONT DOOR ──────────────────────
     *
     * `Assets.init()` with art already on the shelf: this asserts that
     * the boot sequence WIRES THE LOADER UP AT ALL, which calling
     * `_loadDrawnArt` by hand can never show. A breaking run made the
     * point — deleting the call from `init()` left every direct test
     * below still passing. */
    manifest([NAME]); imageThat('load');
    await Assets.init();
    ok(Assets.source(NAME) === 'file',
       `booting with art on the shelf uses it (${Assets.source(NAME)})`);
    ok(Assets.fromFiles().includes(NAME), 'and says which sprites are drawn');

    /* Now the generated floor, which is what everything else is
       measured against. A fresh sandbox, booted with no art at all. */
    const clean = loadEngine();
    await clean.Assets.init();

    /* AND EVERY BADGE A MODULE ASKS FOR IS ACTUALLY DRAWN. The five
       new names of update74 mean nothing if no generator answers to
       them: `Assets.get` warns and returns null, the icon silently
       does not appear, and the module looks blank instead of wrong —
       which is harder to notice, not easier. */
    Object.entries(clean.SYSTEM_DEFS).forEach(([type, def]) => {
      ok(clean.Assets.has(def.icon),
         `${type}'s badge ${def.icon} is a sprite that exists`);
    });
    const generated = clean.Assets.get(NAME);
    ok(!!generated, 'booted with no art, the sprite is generated');
    ok(clean.Assets.source(NAME) === 'generated',
       `and says so (${clean.Assets.source(NAME)})`);

    /* 1. NO MANIFEST, NO REQUESTS, NO CHANGE — today's state.
          Asked of the CLEAN sandbox, whose sprite is still the drawn
          one, so "untouched" means something. */
    clean.fetch = () => Promise.resolve({ ok: false });
    ok(await clean.Assets._loadDrawnArt(null, 30) === 0, 'no manifest: nothing is loaded');
    ok(clean.Assets.get(NAME) === generated, 'and the generated sprite is untouched');

    /* 2. A FILE OVERRIDES IT — same sandbox, so the swap is visible. */
    clean.fetch = () => Promise.resolve({ ok: true, json: () => Promise.resolve([NAME]) });
    clean.Image = sb.Image;                       // the one that loads
    ok(await clean.Assets._loadDrawnArt(null, 30) === 1, 'a listed file is taken');
    ok(clean.Assets.get(NAME) !== generated, 'and the sprite really changed');
    ok(clean.Assets.source(NAME) === 'file', 'the registry knows it is drawn art');

    /* 3. A MISSING FILE IS NOT AN ERROR — the generated art stands. */
    manifest(['no_such_sprite']); imageThat('error');
    ok(await Assets._loadDrawnArt(null, 30) === 0,
       'a name with no file behind it loads nothing');
    ok(Assets.source('no_such_sprite') !== 'file',
       'and is not claimed as drawn art');

    /* 4. THE ONE THAT MATTERS: A FILE THAT NEVER ANSWERS.
       Without the timeout this promise never settles and the suite
       stops responding instead of failing — the one failure a
       breaking run cannot report. Bounded here by the clock. */
    manifest(['hangs']); imageThat('never');
    const t0 = Date.now();
    const got = await Assets._loadDrawnArt(null, 30);
    const spent = Date.now() - t0;
    ok(got === 0, 'a file that never answers loads nothing');
    ok(spent < 2000, `and lets go of the boot (${spent}ms, timeout was 30)`);

    /* 5. RUBBISH IN THE MANIFEST IS NOT A CRASH. */
    for (const body of [null, 42, 'nope', { nope: 1 }, [1, 2, 3]]) {
      manifest(body);
      let threw = false;
      try { await Assets._loadDrawnArt(null, 30); } catch (_) { threw = true; }
      ok(!threw, `a manifest of ${JSON.stringify(body)} does not throw`);
    }

    /* 6. AND THE OBJECT FORM IS READ, so the file can explain itself
          — JSON has no comments and art/manifest.json carries a note. */
    manifest({ _readme: ['…'], sprites: [NAME] });
    imageThat('load');
    ok(await Assets._loadDrawnArt(null, 30) === 1,
       'the {sprites:[…]} form works as well as the bare array');

    restore();
  };

  /* Registered, not fired and forgotten — see `asyncSection` at the
     top of this file. A breaking run proved the difference: with the
     timeout taken out of the loader this section stopped half-way and
     the suite still printed a clean total. */
  asyncSection('248. the art loader', async () => {
    try { await run(); } finally { restore(); }
  });
})();


// ============================================================
section('250. A gun is on a mount or in a crate — there is no third place');
// ============================================================
(function testNoWeightlessRack() {
  const sb = loadEngine();
  const { Ship, Save, Station, Game, CargoItem, cargoCrateForWeapon, WEAPON_DEFS } = sb;
  const T = Game.__test;
  Save.load(); Save.startRun();

  /* ── THE REGISTER IS GONE, NOT JUST UNUSED ────────────────
   *
   * `weaponCargo` was a bare list of gun keys that weighed nothing and
   * was drawn nowhere. Asked from BOTH ends, because either half alone
   * passes for the wrong reason: the field must be absent on a live
   * ship AND absent from what she writes to the save. Leaving it out
   * of the save while still keeping it in memory would look fixed for
   * exactly as long as nobody reloaded. */
  const ship = new Ship('hauler', true, 0, 0);
  ok(ship.weaponCargo === undefined, 'a ship has no weightless rack');
  const ser = ship.serialise();
  ok(!('weaponCargo' in ser), 'and does not write one into the save');

  /* ── AN OLD SAVE IS EMPTIED INTO THE HOLD ─────────────────
   *
   * Somebody mid-contract when this shipped has guns on the old rack.
   * They must arrive as crates, and — the part that is easy to get
   * wrong — they must survive the hold being REPLACED by the saved
   * one two lines later in deserialise. */
  const legacy = { ...ser, weaponCargo: ['ion_basic'] };
  const back = Ship.deserialise(legacy, true, 0, 0);
  ok(back.boxedGuns().some(c => c.meta === 'ion_basic'),
     'a gun off the old rack comes back as a crate in the hold');
  ok(back.weaponCargo === undefined, 'and the rack is not recreated to hold it');
  ok(!('weaponCargo' in back.serialise()),
     'so the next save no longer carries it at all');

  /* ── A SALE THAT CANNOT BE DELIVERED DOES NOT HAPPEN ──────
   *
   * The shop charged first and stowed afterwards, which was harmless
   * only because the rack always had room. With the hold as the only
   * destination the order matters: a full ship must keep her money. */
  const st = new Station(2, 11);
  const buyer = new Ship('scout', true, 0, 0);
  buyer.weaponRooms.forEach((r, i) => {
    if (!buyer.weapons[i]) buyer.installWeapon('laser_basic', i);
  });
  while (buyer.cargo.add('he2_small')) { /* pack it solid */ }
  st.stock.weapons = [{ key: 'ion_basic', def: WEAPON_DEFS.ion_basic, sold: false }];
  Save.updateRun({ scrap: 500 });
  const purse = Save.getRun().scrap;
  const deal = st.buyWeapon(0, buyer, Save.getRun());
  ok(deal.ok === false, `a full ship cannot buy a gun (${deal.message})`);
  ok(Save.getRun().scrap === purse, 'and is not charged for it');
  ok(st.stock.weapons[0].sold === false, 'and the gun is still on the shelf');

  /* ── A GUN HANDED OVER LANDS WHERE HE CAN SEE IT ──────────
   *
   * The player's report: a crew that surrenders and gives up its gun
   * gave him nothing. The gun existed — on the rack, drawn nowhere.
   * Driven through the real event resolver, not by calling the stow
   * helper, because the bug was in the CALLER. */
  const me = new Ship('hauler', true, 0, 0);
  T.playerShip = me;
  const boxedBefore = me.boxedGuns().length;
  T.event = { title: 'x', text: 'x',
              choices: [{ label: 'take it', result: { weaponReward: 'missile_basic' } }] };
  T._resolveEvent(0);
  ok(me.boxedGuns().some(c => c.meta === 'missile_basic'),
     'a gun given to you is a crate in your hold');
  ok(me.boxedGuns().length === boxedBefore + 1, 'exactly one of it');

  /* ── AND SELLING IT GIVES THE CELLS BACK ──────────────────
   * The crate is the thing that moves. If selling only removed a key
   * from a list, the space would stay occupied for ever. */
  const crate = me.boxedGuns()[0];
  const cellsUsed = me.cargo.usedCells();
  const sale = st.sellCargoWeapon(me, Save.getRun(), crate);
  ok(sale.ok, `a boxed gun sells (${sale.message})`);
  ok(me.cargo.usedCells() < cellsUsed,
     `and the hold has the cells back (${cellsUsed} → ${me.cargo.usedCells()})`);

  /* ── A SPARE GUN THAT WILL NOT FIT GOES BACK ON THE SHELF ─
   *
   * The armoury hands the crate over at launch — it is off the shelf
   * before the hull is even built. So a gun that then finds no room in
   * the hold must be PUT BACK, not dropped: doing nothing here would
   * destroy a gun the player owns, quietly, on the launch pad. */
  {
    const sb3 = loadEngine();
    const T3 = sb3.Game.__test;
    const { Base, Save: S3, CargoGrid } = sb3;
    S3.load(); Base.earn(3000);
    ok(Base.storeWeapon('ion_basic'), 'a spare gun waits on the armoury shelf');
    sb3.BaseScreen.open();
    const res = Base.launch({ shipIndex: 0, crewIds: [], fuel: 2, missiles: 0,
                              mission: 'patrol', weapons: [0] });
    ok(res.ok && res.spareGuns.length === 1, 'and is picked up for the flight');
    ok(Base.armoury().length === 0, 'so the shelf is empty while she flies');

    // Fill every mount and every cell, so the gun has nowhere to go.
    const probe = new sb3.Ship(res.ship.key, true, 0, 0);
    probe.weaponRooms.forEach((r, i) => {
      if (!probe.weapons[i]) probe.installWeapon('laser_basic', i);
    });
    const packed = new CargoGrid(probe.cargo.cols, probe.cargo.rows);
    while (packed.add('he2_small')) { /* solid */ }
    T3._startContract({ ...res, ship: { key: res.ship.key, data: probe.serialise() },
                        hold: packed.serialise() });

    ok(T3.playerShip.boxedGuns().length === 0, 'it could not be boxed');
    ok(Base.armoury().includes('ion_basic'),
       `so it is back on the shelf rather than gone (${Base.armoury().join(',')})`);
  }

  /* A crate from somewhere else is refused — the station works on THIS
     hold, and an index into a list would have had no way to tell. */
  const stranger = new CargoItem(cargoCrateForWeapon('ion_basic'), 'ion_basic');
  ok(st.sellCargoWeapon(me, Save.getRun(), stranger).ok === false,
     'a crate that is not in this hold cannot be sold out of it');
  /* Fitted, too — and into a FREE mount, so the refusal cannot come
     from "that bay is occupied" instead. My first version pointed at
     bay 0 with a gun already in it and passed for that reason. */
  const freeBay = me.weaponRooms.findIndex((r, i) => !me.weapons[i]);
  ok(freeBay !== -1 || !!me.uninstallWeapon(0), 'clear a mount to fit into');
  const bay = me.weaponRooms.findIndex((r, i) => !me.weapons[i]);
  ok(bay !== -1, 'there is an empty bay now');
  const nope = st.installFromCargo(me, stranger, bay);
  ok(nope.ok === false, 'a crate from another hold cannot be fitted either');
  ok(/not in this hold/.test(nope.message),
     `and it is refused for the RIGHT reason (${nope.message})`);
})();

// ============================================================
section('251. Stripping an enemy hull is not the same act as unbolting a gun');
// ============================================================
(function testScrapVsUninstall() {
  const sb = loadEngine();
  const { Ship, Save } = sb;
  Save.load(); Save.startRun();

  /* Enemy setup swaps the layout's default gun out before anybody sees
     her. It used to call `uninstallWeapon` and rely on the gun landing
     on a rack nothing read — destruction by side effect, inside a
     function whose whole promise is that the gun is KEPT.
     Two assertions, one per half of the difference. */
  const foe = new Ship('scout', false, 0, 0);
  const had = foe.weapons[0]?.defKey;
  ok(!!had, 'an enemy hull comes with a gun fitted');
  ok(foe.scrapWeapon(0) === true, 'stripping the bay works');
  ok(!foe.weapons[0], 'the bay is empty');
  ok(foe.boxedGuns().length === 0,
     'and the stripped gun did NOT become loot in her hold');

  // The keeping kind, on a ship with room, does the opposite.
  const mine = new Ship('hauler', true, 0, 0);
  const keep = mine.weapons[0]?.defKey;
  ok(mine.uninstallWeapon(0) === keep, 'unbolting a gun returns it');
  ok(mine.boxedGuns().some(c => c.meta === keep), 'and it is boxed in the hold');

  /* AND THE REAL CALLER USES THE RIGHT ONE. The two above prove the
     two functions differ; this proves enemy setup calls the one that
     destroys. A man off the wanted board is re-armed with a matched
     pair, which means unbolting the starter laser his layout came
     with — and if that unbolt STOWS it, the player finds a free gun in
     the wreck that was never meant to exist.
     Driven through a real poster on a real node, because the swap is
     gated on the node carrying a wanted id and not on difficulty —
     my first attempt asked for a 'hard' fight, never reached this code
     at all, and passed. */
  const sb2 = loadEngine();
  const T2 = sb2.Game.__test;
  sb2.Save.load(); sb2.Save.startRun();
  T2.playerShip = new sb2.Ship('hauler', true, 0, 0);
  const poster = sb2.Save.wanted()[0];
  ok(!!poster, 'there is a man on the board to go looking for');
  /* A man who has SLIPPED ONCE, deliberately: he is re-armed with a
     heavy laser in bay 1, so the bay's starter gun is always the wrong
     one and always has to come off. A first-timer gets a plain laser
     there — the same gun the layout already fitted — so the swap skips
     the bay entirely and nothing is unbolted at all. Written as
     "always" rather than "usually" because the first version of this
     test failed about one run in three: the hull is picked at random
     and some of them have a single bay. */
  poster.escapes = 1;
  seatWantedOnMap(sb2, T2, poster.id);
  T2._startCombat('normal', false);
  const foe2 = T2.enemyShip;
  ok(!!foe2, 'and standing on his node starts his fight');
  const barrels = foe2.weapons.filter(Boolean).map(w => w.defKey);
  ok(barrels[0] === 'laser_heavy',
     `the bay that had his layout's gun now has the heavy one (${barrels.join(',')})`);
  ok(foe2.boxedGuns().length === 0,
     'and the gun it came with is GONE, not boxed into his hold as loot');
})();

// ============================================================
section('252. The floor tile is cropped at the wall, not squashed');
// ============================================================
(function testFloorTileCrop() {
  const sb = loadEngine();
  const { Assets } = sb;

  /* A room is never a whole number of 48px tiles wide, so the last
     tile in every row is a part tile. Both drawers used to shrink the
     DESTINATION and leave the SOURCE whole, which squeezes the whole
     picture into the strip. Generated noise hid it; drawn plating
     would have shown a compressed row down one side of every room in
     the game.
     Recorded through a fake context, because the bug is in the
     ARGUMENTS — reading pixels off a near-uniform tile is exactly how
     this survived two updates. */
  const calls = [];
  const ctx = { drawImage: (...a) => calls.push(a) };
  const sprite = { width: 96, height: 96 };     // 2 source px per screen px

  Assets.tileRect(ctx, sprite, 0, 0, 100, 48, 48);
  ok(calls.length === 3, `a 100px row needs three tiles (${calls.length})`);

  const last = calls[calls.length - 1];
  const [, sx, sy, sw, sh, , , dw, dh] = last;
  ok(dw === 4, `the part tile is 4px wide on screen (${dw})`);
  ok(sw === 8, `and reads 8 source px, not the whole 96 (${sw})`);
  ok(sw / dw === sprite.width / 48,
     'so source and destination shrink together — no squash');
  ok(sx === 0 && sy === 0, 'cropped from the corner, so the pattern lines up');
  ok(sh === 96 && dh === 48, 'and a full-height tile still reads full height');

  // Nothing is drawn for an empty rectangle, and — the one that
  // matters — a zero cell REFUSES instead of looping for ever. A hang
  // is the single failure a breaking run cannot report, so this guard
  // is the one part of the function that cannot be left to the loop.
  calls.length = 0;
  Assets.tileRect(ctx, sprite, 0, 0, 0, 48, 48);
  ok(calls.length === 0, 'an empty rectangle draws nothing');
  Assets.tileRect(ctx, sprite, 0, 0, 100, 48, 0);
  ok(calls.length === 0,
     'and a zero tile size returns instead of hanging the frame');
})();

// ============================================================
section('253. SPACE stops the world, not the player');
// ============================================================
(function testPause() {
  const sb = loadEngine();
  const { Game, Input, Renderer } = sb;
  const T = Game.__test;
  const c = makeCombat(sb);

  /* ── WHERE IT MEANS ANYTHING ──────────────────────────────
   * Asked from both ends: the two screens with a clock the player
   * thinks against say yes, and the wreck — whose clock IS the
   * pressure — says no. Testing only the yes half would pass with a
   * function that returned true for everything. */
  T.STATE = 'combat'; ok(T._canPause() === true,  'a fight can be paused');
  T.STATE = 'map';    ok(T._canPause() === true,  'so can the map');
  T.STATE = 'loot';   ok(T._canPause() === false, 'the salvage clock cannot');
  T.STATE = 'station';ok(T._canPause() === false, 'and neither can a station');

  // SPACE toggles it, and only where it means something.
  T.STATE = 'combat'; T.paused = false;
  const realPressed = Input.isPressed;
  const tap = (code) => {
    Input.isPressed = (k) => k === code;
    try { T._step(0.05); } finally { Input.isPressed = realPressed; }
  };
  tap('Space');
  ok(T.paused === true, 'SPACE pauses the fight');
  tap('Space');
  ok(T.paused === false, 'and SPACE again resumes it');
  // …and the key it replaced does nothing at all any more.
  tap('KeyP');
  ok(T.paused === false, 'P is not a second pause key');

  /* ── THE WORLD STOPS ──────────────────────────────────────
   * A man walking across the ship is the clock everybody can see.
   * Both directions, because "he did not move" also happens when the
   * order never took. */
  const man = c.player.crew.find(x => x.isPlayer && !x.dead);
  const far = c.player.rooms.find(r => r.id !== man.roomId);
  ok(!!man && !!far, 'there is somebody to send somewhere');
  ok(man.moveToOnShip(c.player, ...c.player.stationSlot(far, 0)),
     'and a route to send him along');
  const x0 = man.x, y0 = man.y;
  T.STATE = 'combat'; T.paused = true;
  for (let i = 0; i < 10; i++) T._step(0.05);
  ok(man.x === x0 && man.y === y0, 'paused, he does not take a step');
  T.paused = false;
  for (let i = 0; i < 10; i++) T._step(0.05);
  ok(man.x !== x0 || man.y !== y0, 'and running, he does');

  /* ── THE PLAYER DOES NOT ──────────────────────────────────
   * The whole point of this kind of pause. Selecting a crewman goes
   * through the same click path as every order, so if selection works
   * while paused, orders do. */
  T.paused = true;
  const other = c.player.crew.find(x => x.isPlayer && x !== man && !x.dead);
  ok(!!other, 'there is a second man to select');
  const ctx = initRenderer(sb);
  sb.UI.setSelectedCrew?.(man);
  Renderer.drawHUD({ playerShip: c.player });
  const zone = Renderer.getPowerClickZones().find(z => z.crewRef === other);
  ok(!!zone, 'his row is on screen');
  Input.mouse.x = zone.x + zone.w / 2; Input.mouse.y = zone.y + zone.h / 2;
  Input.mouse.leftPressed = true;
  T._step(0.05);
  Input.mouse.leftPressed = false; Input.mouse.x = -100; Input.mouse.y = -100;
  ok(sb.UI.getSelectedCrew() === other,
     'a click still selects a crewman while the game is paused');

  // Leaving a pausable screen cannot leave a pause switched on behind it.
  T.paused = true; T.STATE = 'station'; T._step(0.05);
  ok(T.paused === false, 'walking into a station clears the pause');

  /* ── AND SPACE MEANS ONLY THIS ────────────────────────────
   *
   * The lesson of TAB in update74: one key doing two jobs depending on
   * which screen is on top comes back as a bug report. Space used to
   * jump out of a won fight and dismiss the outcome screen; both moved
   * to Enter, and both had a button for it already.
   *
   * Read off the source of the two exits, because driving a won fight
   * to the state where the key matters takes half a battle and the
   * claim is about which key is WIRED, not about what it does. */
  {
    const fsP = require('fs'), pathP = require('path');
    const src = fsP.readFileSync(pathP.join(__dirname, '..', 'js', 'game.js'), 'utf8');
    const exits = src.split('\n').filter(l => /_combatTimer > 1\.0|_outcomeTimer > 1\.0/.test(l))
      .map((l, i, arr) => arr.slice(i, i + 3).join(' ')).slice(0, 2).join(' | ');
    ok(!/_combatTimer > 1\.0[^\n]*isPressed\('Space'\)/.test(src),
       'leaving a won fight is not on SPACE any more');
    ok(!/_outcomeTimer > 1\.0[^\n]*isPressed\('Space'\)/.test(src),
       'and neither is dismissing the outcome screen');
    ok(/Input\.isPressed\('Enter'\)/.test(src),
       `Enter carries them instead (${exits.slice(0, 80)}…)`);
  }

  /* ── AND THE BANNER DOES NOT COVER THE SHIP ───────────────
   * It used to paint the entire screen at 70% and write PAUSED across
   * the middle — the right drawing for a pause you cannot act in. You
   * cannot give an order to a ship you cannot see. */
  /* Every rectangle it asks for, whichever call it uses. Capturing
     only `fillRect` would have gone green the moment the banner was
     redrawn with `roundRect` — which is exactly what happened while
     this section was being written: the assertion stayed, the drawing
     moved out from under it, and it passed by measuring nothing. */
  const fills = [];
  const realFR = ctx.fillRect, realRR = ctx.roundRect;
  ctx.fillRect  = function (x, y, w, h) { fills.push({ x, y, w, h }); };
  ctx.roundRect = function (x, y, w, h) { fills.push({ x, y, w, h }); };
  try { T._drawPause(ctx); }
  finally { ctx.fillRect = realFR; ctx.roundRect = realRR; }
  const W = Renderer.getWidth(), H = Renderer.getHeight();
  ok(fills.length > 0, 'the banner draws something at all');
  const covers = fills.filter(f => f.w >= W * 0.9 && f.h >= H * 0.5);
  ok(covers.length === 0,
     `nothing is painted over the play area (${fills.map(f => `${f.w}x${f.h}`).join(' ')})`);
  const tallest = fills.reduce((m, f) => Math.max(m, f.h), 0);
  ok(tallest <= 40, `it is a band, not a curtain (${tallest}px tall)`);

  /* AND IT IS OUT OF THE WAY. Centred across the bottom, it sat on the
     weapon panel's AUTO button — a control the player uses WHILE
     paused. The right-hand corner is the empty one. */
  ok(fills.every(f => f.x >= W * 0.55),
     `and it keeps to the right-hand corner (leftmost ${Math.min(...fills.map(f => f.x))})`);
  ok(fills.every(f => f.y + f.h <= H), 'and stays on the screen');
})();

// ============================================================
section('254. The mark strip says what is wrong with him, and what he is doing');
// ============================================================
(function testCrewMarks() {
  const sb = loadEngine();
  const { Renderer, Ship, CrewMember, Save } = sb;
  Save.load(); Save.startRun();
  const ship = new Ship('hauler', true, 0, 0);
  sb.makeStartingCrew().forEach(c => ship.addCrew(c));
  ship.assignStations();
  const man = ship.crew[0];

  const keys = (c, sh = ship) => Renderer.crewMarks(c, sh).map(m => m.key);

  /* ── BOTH DISEASES AT ONCE ────────────────────────────────
   *
   * THE regression this section exists for. The old drawing asked
   * `c.virus ? … : c.infected ? … : null`, so a man carrying both
   * showed only the virus and the plague was invisible until he was
   * cured of the worse thing.
   *
   * Asserted on the KEYS, not on the count: two marks of the same
   * colour would satisfy "there are two of them". */
  man.virus = true; man.infected = true;
  const both = keys(man);
  ok(both.includes('virus') && both.includes('plague'),
     `a man with both shows both (${both.join(',')})`);
  man.virus = false;
  ok(keys(man).includes('plague') && !keys(man).includes('virus'),
     'and one alone shows one');
  man.infected = false;
  ok(!keys(man).some(k => k === 'virus' || k === 'plague'), 'a well man shows neither');

  /* ── HUNGER, OFF THE SAME BANDS THE WORK SPEED READS ──────
   * Not a second set of thresholds: the mark must change exactly where
   * `effortFactor()` changes, or the picture and the maths disagree. */
  const HUNGER = sb.HUNGER;
  man.hunger = 100;
  ok(!keys(man).some(k => /hung|starv/.test(k)), 'a fed man carries no hunger mark');
  man.hunger = HUNGER.HUNGRY - 1;
  ok(keys(man).includes('hungry'), 'below the HUNGRY band he does');
  ok(man.effortFactor() < 1, 'and that is exactly where he starts working slower');
  man.hunger = HUNGER.STARVING;
  ok(keys(man).includes('starving'), 'and starving is its own mark');
  man.hunger = 100;

  /* ── WHICH MODULE HE IS WORKING ───────────────────────────
   *
   * The game has paid the skill bonus to ONE man per module since
   * update43 — the one at the console — and never drew it. Both ends
   * again: the operator gets the mark, the man standing beside him in
   * the same room does NOT, because that is the rule the maths uses. */
  const op = ship.rooms.map(r => ship.consoleOperator(r.id)).find(Boolean);
  ok(!!op, 'somebody is at a console');
  const opMark = Renderer.crewMarks(op, ship).find(m => m.key === 'console');
  ok(!!opMark, 'the man at the console is marked with his module');
  ok(/WORKING /.test(opMark.tip), `and the tip names it (${opMark.tip})`);
  ok(opMark.glyph !== '?', 'with a real glyph, not a question mark');

  /* AND EVERY MODULE HAS ONE. A missing glyph is not an error, it is a
     '?' — the module looks broken rather than absent, which is harder
     to notice. Same shape as the icon-name check from update74. */
  Object.keys(sb.SYSTEM_DEFS).forEach(type => {
    ok(Renderer.systemGlyph(type) !== '?', `${type} has a glyph of its own`);
  });

  const mate = new CrewMember({ name: 'Mate' });
  ship.addCrew(mate);
  mate.roomId = op.roomId; mate.x = op.x + 12; mate.y = op.y;
  ok(ship.consoleOperator(op.roomId) === op, 'the console is still his');
  ok(!keys(mate).includes('console'),
     'the second man in the room is NOT marked as working it');

  /* ── A MAN WHO IS NOT ABOARD ──────────────────────────────
   * And the trap underneath it: room ids are per-ship, so asking OUR
   * ship about a boarder's room id matches by coincidence and would
   * have put a module mark on a man standing on the enemy hull. */
  op._awayTeam = true;
  const awayKeys = keys(op);
  ok(awayKeys.includes('away'), 'a boarder is marked as off the ship');
  ok(!awayKeys.includes('console'),
     'and is NOT also shown working a module he is nowhere near');
  op._awayTeam = false;

  // The dead are not marked: the row itself already says DEAD.
  man.virus = true; man.dead = true;
  ok(Renderer.crewMarks(man, ship).length === 0, 'a corpse carries no marks');
  man.dead = false; man.virus = false;

  /* ── AND THE STRIP CLEARS THE DETAIL PANEL ────────────────
   *
   * It used to sit in the gutter to the RIGHT of the row, and that is
   * what this measured. Since update80 it is a single line INSIDE the
   * card — the gutter held four marks and a man can now have eight.
   *
   * What never changed is the thing the update76 screenshot caught and
   * the reason the assertion exists at all: the detail panel opens at
   * `crewPanelX()` and is drawn OVER everything left of it, so a mark
   * that reaches past that edge is a mark the player cannot see for
   * most of the game. Read off the drawn zones, not off the constant. */
  const ctx = initRenderer(sb);
  ship.crew[0].virus = true;
  ship.crew[0].infected = true;
  Renderer.drawHUD({ playerShip: ship });
  const zones = Renderer.getCrewMarkZones();
  ok(zones.length > 0, 'the marks are drawn with hover boxes');
  const rows = Renderer.getPowerClickZones().filter(z => z.crewRef);
  ok(rows.length > 0, 'and the rows are on screen');
  const edge = Renderer.crewPanelX();
  ok(zones.every(z => z.x + z.w <= edge),
     `every mark stays clear of the detail panel at ${edge} ` +
     `(rightmost mark ends ${Math.max(...zones.map(z => z.x + z.w))})`);
  /* AND INSIDE ITS OWN ROW. A strip that runs past the bottom of the
     card lands on the next man's name — the card height and the strip
     position are wired to the same pair of numbers so that they
     cannot drift, and this is what says so. */
  ok(zones.every(z => rows.some(r =>
       z.y >= r.y && z.y + z.h <= r.y + r.h)),
     'and every mark is inside the card it belongs to');
  /* ONE LINE, AND BIGGER. Both are the player's call for update80 —
     "narazie zrob w jednej lini wszytkie, no i wieksze niz sa teraz" —
     and both are read off the drawn zones rather than off a constant,
     so a layout that quietly goes back to a 2 x 2 of small marks
     fails here instead of passing on the constant it no longer uses. */
  const perRow = {};
  zones.forEach(z => { perRow[z.y] = (perRow[z.y] ?? 0) + 1; });
  ok(Object.keys(perRow).length === rows.filter(r =>
       zones.some(z => z.y >= r.y && z.y + z.h <= r.y + r.h)).length,
     `one line of marks per man (${Object.keys(perRow).length} lines)`);
  ok(zones.every(z => z.h >= 14),
     `and the marks are at least 14px tall (${Math.min(...zones.map(z => z.h))})`);
  /* AND CLEAR OF THE CREW PANEL. It opens the moment anybody is
     selected, which is most of the time, and it used to be drawn
     straight over the last two marks — found by looking at a
     screenshot, not by any assertion, which is why there is one now.
     Read off the published edge so the two cannot drift apart. */
  const panelX = Renderer.crewPanelX();
  ok(zones.every(z => z.x + z.w <= panelX),
     `every mark fits in the gutter before the crew panel at x=${panelX}`);
  ok(zones.every(z => !!z.tip), 'and every one of them can explain itself');
})();

// ============================================================
section('255. Carbonite stops a man\'s clock, and costs a unit to do it');
// ============================================================
(function testCarbonite() {
  const sb = loadEngine();
  const { Ship, Save, SYSTEM_DEFS, Renderer, Game } = sb;
  Save.load(); Save.startRun();

  const build = () => {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const room = sh.rooms.find(r => r.type === 'empty');
    sh.addModuleAt('carbonite', room.id);
    powerModule(sh, 'carbonite', 3);
    sh.update(0.016);
    return sh;
  };

  /* ── IT IS A RENAME, SO AN OLD HULL STILL FINDS IT ────────
   * A ship saved before update77 says 'brig' in her modules and in her
   * systems list. Both doors, because a hull that rebuilt the module
   * and then failed to restore its LEVEL would look fine and quietly
   * hold one man instead of three. */
  ok(!SYSTEM_DEFS.brig, 'there is no brig any more');
  ok(!!SYSTEM_DEFS.carbonite, 'there is a carbonite bay');
  {
    const old = new Ship('frigate', true, 0, 0);
    const room = old.rooms.find(r => r.type === 'empty');
    ok(old.addModuleAt('brig', room.id), "a save that says 'brig' still installs");
    const sys = old.getSystem('carbonite');
    ok(!!sys, 'and what it installs is the carbonite bay');
    sys.level = 3; sys.desiredPower = 3; sys.power = 3;
    const raw = old.serialise();
    raw.extraModules = raw.extraModules.map(e => (e.type === 'carbonite' ? { ...e, type: 'brig' } : e));
    raw.systems = raw.systems.map(sd => (sd.type === 'carbonite' ? { ...sd, type: 'brig' } : sd));
    const back = Ship.deserialise(raw, true, 0, 0);
    const got = back.getSystem('carbonite');
    ok(!!got, 'an old save loads into a carbonite bay');
    ok(got.level === 3, `and keeps the level it was upgraded to (${got?.level})`);
  }

  /* ── ONE LEVEL, ONE SLAB, ONE UNIT OF POWER ───────────────
   * The player's rule. Asserted from both ends: three powered levels
   * are three slabs, and taking the power down to one takes two slabs
   * away while the module is still standing. Before update77 power was
   * all-or-nothing and this was three either way. */
  const ship = build();
  const pod = ship.getSystem('carbonite');
  ok(ship.carboniteCapacity() === 3, `three powered levels, three slabs (${ship.carboniteCapacity()})`);
  pod.power = 1;
  ok(ship.carboniteCapacity() === 1, `one unit of power, one slab (${ship.carboniteCapacity()})`);
  pod.power = 3;

  /* ── HE HAS TO BE IN THE BAY ──────────────────────────────
   * Carbonite is a place, not a button: the walk is the cost paid
   * before the decision. */
  const men = ship.crew.filter(c => c.isPlayer && !c.dead);
  const far = men[0];
  far.roomId = ship.rooms.find(r => r.id !== pod.roomId).id;
  ok(/not in the carbonite bay/.test(ship.freezeRefusal(far) || ''),
     `a man across the ship cannot be frozen (${ship.freezeRefusal(far)})`);
  men.forEach(c => { c.roomId = pod.roomId; });
  ok(ship.freezeRefusal(men[0]) === null, 'standing in it, he can');

  /* A DARK BAY SAYS SO, and says it about the POWER. It used to answer
     `isDisabled()` — which since update77 can never be the reason,
     because a dark bay has no slabs — so the player was told "every
     slab is taken" about a module with nobody in it. */
  {
    const p0 = pod.power, d0 = pod.desiredPower;
    pod.power = 0; pod.desiredPower = 0;
    const why = ship.freezeRefusal(men[0]);
    ok(/power/.test(why || ''), `a cold bay refuses, and blames the power (${why})`);
    ok(/power/.test(ship.cellRefusal({ isPrisoner: true, alive: true }) || ''),
       'and the cell order gets the same answer from the same place');
    pod.power = p0; pod.desiredPower = d0;
  }

  /* ── THE CLOCK STOPS, AND IT IS A STOP, NOT A RESET ───────
   * The heart of the whole module. Both halves: it must not move
   * while he is under, and it must NOT have been wound back when he
   * comes out — carbonite buys time, it does not cure. */
  const sick = men[0];
  sick.virus = true; sick.virusT = 100;
  ok(ship.freezeCrew(sick).ok, 'he goes under');
  for (let i = 0; i < 40; i++) ship.infectionTick(0.5);
  ok(sick.virusT === 100, `twenty seconds pass and his clock has not moved (${sick.virusT})`);
  ok(ship.thawCrew(sick).ok, 'he comes out');
  for (let i = 0; i < 4; i++) ship.infectionTick(0.5);
  ok(sick.virusT < 100 && sick.virusT >= 97,
     `and it starts again from where it stopped (${sick.virusT})`);
  sick.virus = false;

  /* ── AND NOTHING ELSE HAPPENS TO HIM EITHER ───────────────
   * One guard does all of this — he is in no room — so all of it is
   * asserted together: he does not work a console, does not get
   * hungry, and does not walk. */
  const worker = men[1];
  worker.hunger = 50;
  const freeBefore = ship.freeCells();
  ok(ship.freezeCrew(worker).ok, 'a second man goes under');
  ok(ship.freeCells() === freeBefore - 1,
     `and he SPENDS a slab (${freeBefore} → ${ship.freeCells()})`);
  ok(worker.roomId === null, 'a frozen man is in no room at all');
  ok(ship.consoleOperator(pod.roomId) !== worker, 'so he cannot be at a console');
  ok(!ship.crewInRoom(pod.roomId).includes(worker), 'and no room search finds him');

  /* AND THE SHIP'S OWN LOOP LEAVES HIM ALONE. Asserted through
     `ship.update`, not by reading the fields straight after the
     freeze: the loop that puts people in rooms runs every frame and
     would put him back in one, which is the thing being guarded. */
  const wx = worker.x, wy = worker.y;
  for (let i = 0; i < 20; i++) ship.update(0.05);
  ok(worker.roomId === null, 'and a frame of the ship does not put him back in a room');
  ok(worker.x === wx && worker.y === wy, 'nor move him an inch');

  const hunger0 = worker.hunger;
  for (let i = 0; i < 60; i++) ship.hungerTick(1);
  ok(worker.hunger === hunger0, `and he does not get hungry (${worker.hunger})`);

  /* ── CUT A UNIT AND THE LAST SLAB LETS GO ─────────────────
   * "dwóch zamrożonych, ucinasz jeden prąd → jeden się rozmraża,
   * drugi nie". Which one is the question, and the answer has to be
   * predictable BEFORE the pip is pulled: last in, first out. */
  const early = men[1];                  // already under, from the block above
  const late  = men[0];
  late.roomId = pod.roomId;
  ok(early.frozen === true, 'one man has been under for a while');
  ok(ship.freezeCrew(late).ok, 'a second goes in after him');
  ok(ship.frozenCrew().length === 2, 'both of them are under');
  /* Driven through `ship.update`, the way the game does it, and not
     by calling the tick by hand: the tick has to be WIRED, and it has
     to run after the power flow — a call placed before it reads last
     frame's budget and wakes him a frame late. */
  pod.desiredPower = 1;
  ship.update(0.05);
  ok(pod.effectivePower() === 1, `the bay is down to one unit (${pod.effectivePower()})`);
  /* update127 (jj): the slab WARMS first — SLAB_MELT_SECONDS, then he is out. */
  ok(ship.frozenCrew().length === 2 && late._meltT > 0 && !early._meltT,
     'the slab starts to warm — nobody is out yet, and it is the last man\'s slab');
  for (let t = 0; t < Ship.SLAB_MELT_SECONDS + 1; t += 0.5) { pod.desiredPower = 1; ship.update(0.5); }
  ok(ship.frozenCrew().length === 1, 'one slab lets go once it has melted');
  ok(late.frozen === false && early.frozen === true,
     'and it is the man who went in LAST, not the one who had been there longest');
  pod.power = 3; pod.desiredPower = 3;

  /* ── A CONVICT KEEPS HIS SLAB BEFORE YOUR OWN MAN DOES ────
   * A thaw can be undone; an escape cannot. */
  {
    const sh = build();
    const p2 = sh.getSystem('carbonite');
    p2.level = 1; p2.desiredPower = 1; p2.power = 1;
    ok(sh.carboniteCapacity() === 1, 'one slab');
    ok(sh.takePrisoner({ id: 'x', name: 'Convict', bounty: 10 }), 'a convict is in it');
    const mine = sh.crew.find(c => c.isPlayer && !c.dead);
    mine.roomId = p2.roomId;
    ok(sh.freezeRefusal(mine) === 'every slab is taken',
       `and there is no room for your own man (${sh.freezeRefusal(mine)})`);

    /* AND A CONVICT WITH NO SLAB WORKS THE LOCK EVEN THOUGH THE BAY
       IS LIT. This used to ask one yes-or-no question — is the module
       disabled — so a second convict in a one-slab bay sat quietly. */
    ok(sh.takePrisoner({ id: 'y', name: 'Second', bounty: 10 }) === false,
       'the bay refuses a second convict while it has one slab');
    sh.prisoners.push({ id: 'y', name: 'Second', bounty: 10, escapeT: 0, warned: false });
    sh.prisonerTick(1);
    ok(sh.prisoners[0].escapeT === 0, 'the man in the slab is not going anywhere');
    ok(sh.prisoners[1].escapeT > 0,
       `the one with no slab starts working his lock (${sh.prisoners[1].escapeT})`);
    ok(!p2.isDisabled(), 'and the bay is still lit — it is the SLAB he lacks, not the power');
  }

  /* ── NOBODY IS BANKED STILL FROZEN ────────────────────────
   * The barracks has no carbonite, so a man saved mid-freeze would
   * come back to a hull with no slab to be in. */
  {
    const sh = build();
    const p3 = sh.getSystem('carbonite');
    const man = sh.crew.find(c => c.isPlayer && !c.dead);
    man.roomId = p3.roomId;
    ok(sh.freezeCrew(man).ok, 'he is under when the contract ends');
    const T = Game.__test;
    T.playerShip = sh;
    Save.updateRun({ scrap: 10, fuel: 1, missiles: 0 });
    T._finishContract();
    ok(man.frozen === false, 'docking thaws him');
  }

  /* ── THE SLAB SURVIVES A RELOAD ───────────────────────────
   * The whole promise is that his clock is where he left it. A save
   * that thawed him would tick it on while nobody was even playing. */
  {
    const sh = build();
    const p4 = sh.getSystem('carbonite');
    const a = sh.crew.filter(c => c.isPlayer && !c.dead)[0];
    const b2 = sh.crew.filter(c => c.isPlayer && !c.dead)[1];
    [a, b2].forEach(c => { c.roomId = p4.roomId; });
    ok(sh.freezeCrew(a).ok && sh.freezeCrew(b2).ok, 'two men go under');
    const back = Ship.deserialise(sh.serialise(), true, 0, 0);
    sh.crew.forEach(c => back.addCrew(sb.CrewMember.deserialise(c.serialise())));
    ok(back.frozenCrew().length === 2, 'both come back frozen');
    const order = back.frozenCrew().sort((x, y) => (x._slabSeq ?? 0) - (y._slabSeq ?? 0))
      .map(c => c.name);
    ok(order[0] === a.name && order[1] === b2.name,
       `and in the order they went in (${order.join(',')})`);
  }

  /* ── THE READOUT COUNTS BOTH KINDS ────────────────────────
   * A slab is a slab whether the man in it is a convict or your own
   * gunner. It used to count prisoners only, so a bay with three of
   * your own crew in it read 0/3. */
  {
    // A run again: the docking block above finished the last one, and
    // the HUD draws nothing at all without one.
    if (!Save.hasActiveRun()) Save.startRun();
    const sh = build();
    const p5 = sh.getSystem('carbonite');
    const mine = sh.crew.find(c => c.isPlayer && !c.dead);
    mine.roomId = p5.roomId;
    ok(sh.freezeCrew(mine).ok, 'one of your own is under');
    const ctx2 = initRenderer(sb);
    const texts = captureText(ctx2, () => Renderer.drawHUD({ playerShip: sh })).map(d => d.t);
    const carb = texts.find(t => /^CARB /.test(t));
    ok(!!carb, `the slab readout is on screen (${texts.filter(t => /CARB/.test(t)).join('|')})`);
    ok(/^CARB 1\//.test(carb), `and it counts him (${carb})`);
  }

  /* ── AND THE MARK SAYS SO ─────────────────────────────────
   * One mark and nothing else: nothing is happening to him, so there
   * is nothing else to report. */
  const frozenMarks = Renderer.crewMarks(early, ship);
  ok(frozenMarks.length === 1 && frozenMarks[0].key === 'frozen',
     `a frozen man carries one mark (${frozenMarks.map(m => m.key).join(',')})`);
  ok(/CARBONITE/.test(frozenMarks[0].tip), 'and it names the slab');

  // The menu offers the order, and the drawing has a label for it.
  const T2 = Game.__test;
  T2.playerShip = ship;
  ok(T2._menuActsFor(early).join(',') === 'thaw', 'a frozen man is offered THAW and nothing else');
  const upright = ship.crew.find(c => c.isPlayer && !c.dead && !c.frozen);
  ok(T2._menuActsFor(upright).includes('freeze'), 'and a man on his feet is offered FREEZE');
  const ctx = initRenderer(sb);
  const rows = captureText(ctx, () =>
    Renderer.drawBodyMenu(ctx, 400, 300, 'x', null, ['freeze', 'thaw'])).map(d => d.t);
  ok(rows.join('|') === 'FREEZE|THAW', `both rows are drawn (${rows.join('|')})`);
})();

// ============================================================
section('256. A bandage, a medkit and a ward are three different things');
// ============================================================
(function testAidLadder() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Game, Renderer } = sb;
  Save.load(); Save.startRun();

  const rig = (layout = 'scout') => {
    const sh = new Ship(layout, true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const room = sh.rooms[0];
    const [hurt, medic] = sh.crew;
    [hurt, medic].forEach(c => { c.roomId = room.id; c.x = room.cx; c.y = room.cy; c.inRoom = true; });
    hurt.hp = 1; hurt.state = 'injured'; hurt._bleedT = 0;
    sh.cargo.items.length = 0;
    return { sh, hurt, medic, room };
  };
  const run = (sh, n = 300) => {
    for (let i = 0; i < n; i++) { sh._updateBodies(0.05); sh._busyTick(0.05); }
  };

  /* ── THE PRICE LIST ───────────────────────────────────────
   * One box, two prices, and the automatic one is the cheap one so
   * the expensive one stays a decision. Read off the constants rather
   * than written out again, or the test and the game can disagree
   * about what a dose costs. */
  ok(Ship.AID_DOSES < Ship.MEDKIT_DOSES,
     `a bandage is cheaper than getting him up (${Ship.AID_DOSES} vs ${Ship.MEDKIT_DOSES})`);

  /* ── NO SUPPLIES, NO BANDAGE ──────────────────────────────
   * The whole reason the bleed-out clock exists. Free automatic aid
   * meant it never ran out on anybody who fell within reach of a
   * crewmate, so the rule almost never fired. */
  {
    const { sh, hurt } = rig();
    run(sh, 100);
    ok(!hurt._bandaged, 'an empty hold cannot bandage anybody');
    ok(hurt._bleedT > 0, `and the clock runs (${hurt._bleedT.toFixed(1)}s)`);
    run(sh, Ship.BLEEDOUT_SECONDS * 20 + 100);
    ok(hurt.dead === true, 'and with nothing aboard he bleeds out');
  }

  /* ── A BANDAGE STOPS THE CLOCK AND NOTHING ELSE ───────────
   * Asserted from three sides, because any one of them alone passes
   * for the wrong reason: the clock must stop, the HP must NOT move,
   * and he must still be on the floor. */
  {
    const { sh, hurt } = rig();
    sh.cargo.add('medkit');
    const doses0 = sh.doseCount(), hp0 = hurt.hp;
    run(sh, 200);
    ok(hurt._bandaged === true, 'with supplies aboard, a crewmate bandages him');
    ok(sh.doseCount() === doses0 - Ship.AID_DOSES,
       `and it costs ${Ship.AID_DOSES} dose (${doses0} → ${sh.doseCount()})`);
    ok(hurt.hp === hp0, `his hit points do not move (${hp0} → ${hurt.hp})`);
    ok(hurt.state === 'injured', 'and he is still on the floor');
    run(sh, Ship.BLEEDOUT_SECONDS * 20 + 200);
    ok(!hurt.dead, 'but he is not running out of time any more');
    ok(sh.doseCount() === doses0 - Ship.AID_DOSES,
       'and nobody bandages him a second time');
  }

  /* ── A MEDKIT GETS HIM UP, ON A HULL WITH NO MEDBAY ───────
   * This is why it exists: both hulls the player starts in have no
   * medbay, and without this a casualty on one of them is a casualty
   * for the rest of the contract. */
  {
    const { sh, hurt, medic } = rig();
    ok(!sh.getSystem('medbay'), 'the scout carries no medbay');
    sh.cargo.add('medkit');
    const doses0 = sh.doseCount();
    ok(sh.orderBody(hurt, 'medkit', medic).ok, 'the player calls for a medkit');
    run(sh, 200);
    ok(hurt.state === 'ok', 'and he is back on his feet');
    ok(hurt.hp >= hurt.maxHp * Ship.MEDKIT_SHARE,
       `at ${Math.round(Ship.MEDKIT_SHARE * 100)}% (${hurt.hp.toFixed(0)}/${hurt.maxHp})`);
    ok(hurt.hp < hurt.maxHp, 'and NOT to full — that is the ward\'s job, not a box\'s');
    ok(doses0 - sh.doseCount() === Ship.MEDKIT_DOSES,
       `it costs ${Ship.MEDKIT_DOSES} doses (${doses0} → ${sh.doseCount()})`);
  }

  /* ── AND IT IS REFUSED WHEN THE BOX IS TOO LIGHT ──────────
   * With exactly one dose left the bandage can still happen and the
   * medkit cannot — which is the decision the two prices exist for. */
  {
    const { sh, hurt } = rig();
    sh.cargo.add('medkit');
    const stack = sh.cargo.items.find(it => it.def.kind === 'heal');
    stack.qty = 1;
    ok(sh.doseCount() === 1, 'one dose left in the box');
    const why = sh.bodyRefusal(hurt, 'medkit');
    ok(/not enough/.test(why || ''), `MEDKIT is refused, and says why (${why})`);
    ok(sh.bodyRefusal(hurt, 'medkit') !== null, 'and refused, not merely quiet');
    run(sh, 200);
    ok(hurt._bandaged === true, 'the last dose still buys a bandage');
  }

  /* ── THE WARD IS THE ONLY THING THAT MAKES HIM WHOLE ──────
   * It used to end with the same sentence field aid ended with — up
   * at 30% — so a medbay was a faster bandage and nothing more. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    powerModule(sh, 'medbay', 2);
    const med = sh.getSystem('medbay');
    const room = sh.getRoomById(med.roomId);
    const man = sh.crew[0];
    /* HIS POST IS THE WARD, deliberately. A man who gets up walks back
       to his own station — which is right, and is why "heal to full"
       is something the player ASKS for by leaving him there rather
       than something that happens to everybody who falls over. */
    man.roomId = room.id; man.x = room.cx; man.y = room.cy; man.inRoom = true;
    man.homeRoomId = room.id;
    man.hp = 20; man.state = 'injured';
    for (let i = 0; i < 400; i++) sh.update(0.05);
    ok(man.state === 'ok', 'the ward stands him up');
    ok(man.hp === man.maxHp, `and keeps going to FULL (${man.hp}/${man.maxHp})`);

    /* AND IT TREATS A MAN ON HIS FEET. The healing used to live in two
       places — one for the men on the floor, one for the men standing
       — and `medbayPatients`, the function named for the answer, was
       wired to neither of them. */
    man.hp = 30;
    for (let i = 0; i < 200; i++) sh.update(0.05);
    ok(man.hp === man.maxHp, 'a man standing in it between fights is healed too');

    /* AND THE CLOCK DOES NOT RUN ON THE TABLE. A ward racing its own
       patient is a ward that loses him at forty seconds with the
       lights on. */
    const other = sh.crew[1];
    other.roomId = room.id; other.x = room.cx; other.y = room.cy; other.inRoom = true;
    other.hp = 1; other.state = 'injured'; other._bleedT = 5;
    sh.update(0.05);
    ok(other._bleedT === 0, 'a casualty in a powered ward is off the clock');
  }

  /* ── THE MENU OFFERS WHAT THE STATE DESERVES ──────────────
   * A body is something you get rid of; a casualty is something you
   * get back. Six rows, three of them always dead, became four live
   * ones. */
  {
    const { sh, hurt } = rig();
    const T = Game.__test;
    T.playerShip = sh;
    ok(T._menuActsFor(hurt).join(',') === 'treat,medkit',
       `a casualty is offered the two ways back (${T._menuActsFor(hurt).join(',')})`);
    hurt.state = 'dead'; hurt.dead = true;
    ok(T._menuActsFor(hurt).join(',') === 'eject,bag',
       `and a body the two ways out (${T._menuActsFor(hurt).join(',')})`);
    const ctx = initRenderer(sb);
    const rows = captureText(ctx, () =>
      Renderer.drawBodyMenu(ctx, 400, 300, 'x', null, ['treat', 'medkit'])).map(d => d.t);
    ok(rows.join('|') === 'TREAT|MEDKIT', `and both rows are drawn (${rows.join('|')})`);
  }

  /* ── AND A MEAL IS ON THE SAME CLOCK ──────────────────────
   * The player's rule is that every one of these takes a moment. One
   * timer, so "are your hands already full" has one answer. */
  {
    const { sh, medic } = rig();
    sh.cargo.add('ration_pack');
    medic.hunger = 10;
    ok(sh.feedCrew(medic).ok, 'he starts on a ration');
    ok(medic.busy === true, 'and is busy while he eats');
    ok(/hands full/.test(sh.feedRefusal(medic) || ''),
       'so nothing else can be asked of him yet');
    /* THE MEAL HAS TO LAST (update78). Asserting "busy" on the frame
       the order lands is free — any timer at all, even a hundredth of
       a second, is > 0 on that frame. The question the player asked
       for is whether the man is STILL eating a moment later, so the
       clock is read in the middle of the meal, not at its start. */
    run(sh, 40);                                   // 2.0s of a 3s meal
    ok(medic.busy === true, 'still eating two seconds in');
    ok(medic.hunger === 10, 'and the meal has not landed yet');
    run(sh, 200);
    ok(medic.busy === false, 'and free again when he has finished');
    ok(medic.hunger > 10, 'and only then is he fed');
  }

  /* ── AND WHILE HIS HANDS ARE FULL HE IS OFF HIS CONSOLE ──
   * The clock was added and for one package nothing read it, so a
   * gunner could eat a ration and still be the gunner. `crewOperating`
   * is the one question "who is working here", so it is the one place
   * that knows — and the gun, the cyborg's +1 and the mark strip all
   * fall out of that single answer. */
  {
    const { sh, medic, room } = rig();
    const slot = sh.stationSlot(room, 0);
    medic.x = slot[0]; medic.y = slot[1];
    ok(sh.consoleOperator(room.id) === medic, 'he is the man at the console');
    sh.cargo.add('ration_pack');
    medic.hunger = 10;
    sh.feedCrew(medic);
    ok(sh.crewOperating(room.id).indexOf(medic) === -1,
       'and the moment he starts eating he is not working the room');
    ok(sh.consoleOperator(room.id) === null, 'so the console is unmanned');
    run(sh, 200);
    ok(sh.consoleOperator(room.id) === medic, 'and he is back on it when he is done');
  }

  /* ── THE STRIP SAYS WHICH CASUALTY IS ON A CLOCK ─────────
   * Both a bandaged man and a bleeding one draw INJURED on the row.
   * The player is asked to spend doses on the difference, so the
   * difference has to be visible. */
  {
    const { sh, hurt, medic, room } = rig();
    const keys = c => Renderer.crewMarks(c, sh).map(m => m.key);
    ok(keys(hurt).indexOf('bleeding') !== -1,
       `a man on the floor is marked as bleeding (${keys(hurt).join(',')})`);
    hurt._bandaged = true;
    ok(keys(hurt).indexOf('stable') !== -1,
       `and as stable once he is patched (${keys(hurt).join(',')})`);
    ok(keys(hurt).indexOf('bleeding') === -1, 'and not as both at once');

    const slot = sh.stationSlot(room, 0);
    medic.x = slot[0]; medic.y = slot[1];
    sh.cargo.add('ration_pack');
    medic.hunger = 10;
    sh.feedCrew(medic);
    const m = keys(medic);
    ok(m.indexOf('eating') !== -1, `the eater is marked eating (${m.join(',')})`);
    ok(m.indexOf('console') === -1,
       'and the console glyph is gone, because he is not at it');
    const tip = Renderer.crewMarks(medic, sh).find(x => x.key === 'eating')?.tip ?? '';
    ok(/hands full/i.test(tip), `and the tip explains why (${tip})`);
  }

  /* ── AND THE SIDE RULE, MEASURED ON WHAT AID DOES NOW ─────
   * This one was caught by the breaking run, not by design. The test
   * that guarded "nobody bandages the man who came to board him" read
   * the boarder's HIT POINTS — which was fair while field aid healed
   * him, and stopped meaning anything the moment a bandage became
   * "stop the bleeding, stay on the floor". The rule was still right;
   * the assertion had quietly stopped watching it.
   *
   * A downed enemy does NOT contest the room either (`occupantsOf`
   * wants `alive`, and a man on the floor is not), so the side check
   * is the only thing standing between our medic and his casualty. */
  {
    const { sh, hurt, medic, room } = rig();
    hurt.state = 'ok'; hurt.hp = hurt.maxHp;       // only the foe is down
    sh.cargo.add('medkit');
    const doses0 = sh.doseCount();
    const foe = new CrewMember({ race: 'human' });
    foe.isPlayer = false;
    foe.roomId = room.id; foe.x = room.cx; foe.y = room.cy; foe.inRoom = true;
    foe.hp = 1; foe.state = 'injured'; foe._bleedT = 0;
    sh.crew.push(foe);
    ok(sh.roomContested(room.id) === false,
       'a man on the floor does not count as a fight, so nothing else stops this');
    run(sh, 200);
    ok(foe._bandaged !== true, 'our hands do not patch up the man who came to board us');
    ok(sh.doseCount() === doses0, `and not one dose is spent on him (${doses0})`);
    ok(medic.busy === false, 'and our medic never knelt down at all');

    // The control: the same loop, one of ours, and it DOES pay out —
    // otherwise the two assertions above would pass on a dead loop.
    hurt.hp = 1; hurt.state = 'injured'; hurt._bleedT = 0;
    run(sh, 200);
    ok(hurt._bandaged === true, 'but our own casualty is bandaged');
    ok(doses0 - sh.doseCount() === Ship.AID_DOSES, 'and that one costs a dose');
  }

  /* ── AND NOBODY KNEELS DOWN IN THE MIDDLE OF A FIGHT ──────
   * Third one the breaking run found, and the same story as the two
   * above: the guard was right, the assertion behind it was reading
   * hit points that a bandage no longer touches. */
  {
    const { sh, hurt, medic, room } = rig();
    sh.cargo.add('medkit');
    const doses0 = sh.doseCount();
    const foe = new CrewMember({ race: 'human' });
    foe.isPlayer = false;
    foe.roomId = room.id; foe.x = room.cx; foe.y = room.cy; foe.inRoom = true;
    sh.crew.push(foe);
    ok(sh.roomContested(room.id) === true, 'a boarder is swinging in the room');
    run(sh, 100);
    ok(hurt._bandaged !== true, 'so nobody kneels down to bandage anybody');
    ok(sh.doseCount() === doses0, 'and no dose is opened mid-brawl');
    ok(medic.busy === false, 'our man has his hands free for the fight');

    sh.crew.splice(sh.crew.indexOf(foe), 1);
    run(sh, 100);
    ok(hurt._bandaged === true, 'and the bandage happens once the room is clear');
  }

  /* ── A WARD WITH A FIGHT IN IT TREATS NOBODY ──────────────
   * Same story: `medbayPatients` has always refused a contested room,
   * but nothing failed when that line was removed, because until this
   * package the healing loop did not ask `medbayPatients` at all. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    powerModule(sh, 'medbay', 2);
    const med  = sh.getSystem('medbay');
    const room = sh.getRoomById(med.roomId);
    const man  = sh.crew[0];
    man.roomId = room.id; man.x = room.cx; man.y = room.cy; man.inRoom = true;
    man.homeRoomId = room.id;
    man.hp = 20; man.state = 'ok';

    const foe = new CrewMember({ race: 'human' });
    foe.isPlayer = false;
    foe.roomId = room.id; foe.x = room.cx; foe.y = room.cy; foe.inRoom = true;
    sh.crew.push(foe);
    ok(sh.roomContested(room.id) === true, 'a boarder is standing in the ward');
    ok(sh.medbayPatients(room.id).length === 0, 'so it has no patients');
    /* The hit points are deliberately NOT the assertion here: the two
       of them are swinging at each other, so his bar moves for a
       reason that has nothing to do with the ward, and a test that
       read it would pass on the brawl instead of on the rule. */
    sh.crew.splice(sh.crew.indexOf(foe), 1);       // he is off the deck, x/y and all
    ok(sh.medbayPatients(room.id).indexOf(man) !== -1,
       'and he is a patient again the moment the room is clear');
    const hp0 = man.hp = 20;
    for (let i = 0; i < 100; i++) sh.update(0.05);
    ok(man.hp > hp0, `and the ward picks the job straight back up (${man.hp}/${hp0})`);
  }
})();

// ============================================================
section('257. A module holds three A SIDE, and a brawl is duels');
// ============================================================
(function testRoomAndBrawl() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Game } = sb;
  Save.load(); Save.startRun();

  const intruder = (ship, room, name) => {
    const c = new CrewMember({ name });
    c.isPlayer = !ship.isPlayer;
    c.roomId = room.id; c.x = room.cx; c.y = room.cy; c.inRoom = true;
    ship.crew.push(c);
    return c;
  };

  /* ── THE PLACES ARE OURS, AND THEIRS ARE THEIRS ───────────
   *
   * The count used to filter on `alive` and nothing else, so two men
   * who came through the airlock to kill you also took two of the
   * three places in the room, and you could answer with one medic.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const room = sh.rooms[0];
    sh.crew.forEach(c => { c.roomId = 'elsewhere'; c.homeRoomId = 'elsewhere'; });
    ok(sh.roomSpaceFor(room.id, true) === Ship.ROOM_SLOTS,
       `an empty module takes ${Ship.ROOM_SLOTS} of ours`);

    intruder(sh, room, 'Boarder A');
    intruder(sh, room, 'Boarder B');
    ok(sh.roomSpaceFor(room.id, true) === Ship.ROOM_SLOTS,
       'and two boarders standing in it take away none of them');
    ok(sh.roomSpaceFor(room.id, false) === Ship.ROOM_SLOTS - 2,
       'while THEIR side is down to its last place');

    const mine = sh.crew.filter(c => c.isPlayer).slice(0, 2);
    mine.forEach(c => { c.roomId = room.id; c.homeRoomId = room.id; });
    ok(sh.roomSpaceFor(room.id, true) === Ship.ROOM_SLOTS - 2,
       'our own men do take our places');
    ok(sh.roomSpaceFor(room.id, true, mine) === Ship.ROOM_SLOTS,
       'and the men being MOVED do not count against themselves');
  }

  /* ── A CASUALTY ON THE FLOOR IS NOT AN OCCUPANT ───────────
   * Three wounded in a room used to read as full, which is how a
   * breached module could look unfixable. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const room = sh.rooms[0];
    sh.crew.forEach(c => {
      c.roomId = room.id; c.homeRoomId = room.id;
      c.hp = 1; c.state = 'injured';
    });
    ok(sh.roomSpaceFor(room.id, true) === Ship.ROOM_SLOTS,
       'a room full of wounded is a room you can still send a man into');
  }

  /* ── AN INTRUDER DOES NOT HOLD OUR CONSOLE ────────────────
   * `takenStationSlots` had no side filter, so the man who came to
   * kill your gunner could stand on the console and push him onto the
   * flank of his own bay. With six in a module that stops being a
   * cosmetic problem: the two sides would share three places.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const room = sh.rooms[0];
    sh.crew.forEach(c => { c.roomId = 'elsewhere'; c.homeRoomId = 'elsewhere'; });
    const foe = intruder(sh, room, 'Boarder');
    const [cx, cy] = sh.stationSlot(room, 0);
    foe.x = cx; foe.y = cy;                       // standing ON the console
    ok(sh.slotIndexAt(foe.x, foe.y, room) === 0, 'he is on slot 0');
    ok(sh.takenStationSlots(room, [], false, true).has(0) === false,
       'but the spot is not spoken for as far as OUR side is concerned');
    ok(sh.freeStationSlot(room, [], true) === 0, 'so our man still gets the console');
    ok(sh.takenStationSlots(room, [], false, false).has(0) === true,
       'and it IS spoken for as far as his own side is concerned');
  }

  /* ── RELIEVING A CASUALTY ─────────────────────────────────
   * One click has to do both halves, because neither half works
   * alone: the room refuses the fresh man while the wounded one is
   * still in it, and moving the wounded one first empties the bay.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    powerModule(sh, 'medbay', 1);
    const T = Game.__test;
    T.playerShip = sh;
    const med  = sh.getSystem('medbay');
    const ward = sh.getRoomById(med.roomId);
    const room = sh.rooms.find(r => r.id !== ward.id);
    const men  = sh.crew.filter(c => c.isPlayer && !c.isPet);
    ok(men.length >= 3, `three men to play with (${men.length})`);

    const [hurt, ok1, fresh] = men;
    [hurt, ok1].forEach(c => { c.roomId = room.id; c.homeRoomId = room.id; });
    const third = men[3];
    if (third) { third.roomId = room.id; third.homeRoomId = room.id; }
    hurt.hp = 5;                                  // the worst off in the room
    ok1.hp  = ok1.maxHp;
    fresh.roomId = 'elsewhere'; fresh.homeRoomId = 'elsewhere';
    fresh.hp = fresh.maxHp;

    const before = sh.roomSpaceFor(room.id, true, [fresh]);
    const freed  = T._relieveInRoom(room, [fresh], 1);
    ok(freed === 1, `one place is freed (${freed}), it was ${before}`);
    ok(hurt.homeRoomId === ward.id,
       `and it is the WORST HURT man who steps out (${hurt.homeRoomId} vs ${ward.id})`);
    ok(ok1.homeRoomId === room.id, 'the healthy one stays where he was posted');
  }

  /* ── AND A RELIEF HAS TO BE AN IMPROVEMENT ────────────────
   * Otherwise the order is the game quietly re-sorting the player's
   * crew behind his back. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    powerModule(sh, 'medbay', 1);
    const T = Game.__test;
    T.playerShip = sh;
    const ward = sh.getRoomById(sh.getSystem('medbay').roomId);
    const room = sh.rooms.find(r => r.id !== ward.id);
    const men  = sh.crew.filter(c => c.isPlayer && !c.isPet);
    men.forEach(c => { c.roomId = room.id; c.homeRoomId = room.id; c.hp = c.maxHp; });
    const sick = men[0];
    sick.roomId = 'elsewhere'; sick.homeRoomId = 'elsewhere'; sick.hp = 3;
    ok(T._relieveInRoom(room, [sick], 1) === 0,
       'a man in worse shape than everybody there relieves nobody');
    ok(men[1].homeRoomId === room.id, 'and nobody was moved');
  }


  /* ── AND THE CLICK USES THAT RULE, NOT ONE OF ITS OWN ─────
   *
   * `roomSpaceFor` being right is half the job: the capacity used to
   * be counted out by hand at BOTH click sites, which is how the two
   * came to disagree in the first place. So the order itself is given
   * here, through the same function the player's mouse reaches.
   */
  {
    const { T, player } = makeCombat(sb);
    const room = player.rooms[0];
    // Two boarders, off-centre so the click lands on the ROOM and not
    // on a sprite, and our own men parked out of the way.
    ['Boarder A', 'Boarder B'].forEach((name, i) => {
      const c = new CrewMember({ name });
      c.isPlayer = false;
      c.x = room.x + 6 + i * 4; c.y = room.y + 6;
      c.roomId = room.id; c.homeRoomId = room.id; c.inRoom = true;
      player.crew.push(c);
    });
    const mine = player.crew.filter(c => c.isPlayer && !c.isPet).slice(0, Ship.ROOM_SLOTS);
    ok(mine.length === Ship.ROOM_SLOTS, `${Ship.ROOM_SLOTS} men to send`);
    player.crew.filter(c => c.isPlayer).forEach(c => {
      c.x = -9999; c.y = -9999; c.roomId = 'elsewhere'; c.homeRoomId = 'elsewhere';
    });
    sb.UI.selectCrewGroup(mine);
    T._crewClickResolve(room.cx, room.cy, false);
    const arrived = mine.filter(c => c.homeRoomId === room.id).length;
    ok(arrived === Ship.ROOM_SLOTS,
       `all ${Ship.ROOM_SLOTS} are sent although two boarders are standing there (${arrived})`);
  }

  /* ── THE SAME RULE ON THE OTHER HULL ──────────────────────
   * The boarder click had its own copy and it filtered differently,
   * so three of yours could walk into a room that already held two of
   * yours — six of your own men in one compartment. */
  {
    const { T, player, enemy } = makeCombat(sb);
    const eRoom = enemy.rooms[enemy.rooms.length - 1];
    enemy.crew.forEach(c => { c.x = -9999; c.y = -9999; });
    player.crew.forEach(c => { c.x = -9999; c.y = -9999; });
    const board = [];
    for (let i = 0; i < 5; i++) {
      const c = new CrewMember({ name: `B${i}` });
      c.isPlayer = true;
      c.x = -9999; c.y = -9999;
      c.roomId = eRoom.id;
      // Two of ours are already POSTED there; three are only standing
      // in the room and are the ones being ordered.
      c.homeRoomId = i < 2 ? eRoom.id : 'elsewhere';
      c.inRoom = true;
      enemy.crew.push(c);
      if (i >= 2) board.push(c);
    }
    sb.UI.selectCrewGroup(board);
    T._crewClickResolve(eRoom.cx, eRoom.cy, false);
    const posted = board.filter(c => c.homeRoomId === eRoom.id).length;
    ok(posted === Ship.ROOM_SLOTS - 2,
       `two of ours are already in it, so only one more is sent (${posted})`);
  }

  /* ── AND THE RELIEF IS GIVEN BY THAT SAME CLICK ───────────
   * One order, because neither half works alone. */
  {
    const { T, player } = makeCombat(sb);
    powerModule(player, 'medbay', 1);
    const ward = player.getRoomById(player.getSystem('medbay').roomId);
    const room = player.rooms.find(r => r.id !== ward.id);
    while (player.crew.filter(c => c.isPlayer && !c.isPet).length <= Ship.ROOM_SLOTS) {
      player.addCrew(new CrewMember({}));
    }
    const men  = player.crew.filter(c => c.isPlayer && !c.isPet);
    ok(men.length > Ship.ROOM_SLOTS, `a man to spare (${men.length})`);
    men.forEach(c => { c.x = -9999; c.y = -9999; });
    const inRoom = men.slice(0, Ship.ROOM_SLOTS);
    inRoom.forEach(c => { c.roomId = room.id; c.homeRoomId = room.id; c.hp = c.maxHp; });
    const bleeding = inRoom[0];
    bleeding.hp = 4;
    const fresh = men[Ship.ROOM_SLOTS];
    fresh.roomId = 'elsewhere'; fresh.homeRoomId = 'elsewhere'; fresh.hp = fresh.maxHp;

    sb.UI.selectCrewGroup([fresh]);
    T._crewClickResolve(room.cx, room.cy, false);
    ok(fresh.homeRoomId === room.id,
       `the fresh man gets in although the module was full (${fresh.homeRoomId})`);
    ok(bleeding.homeRoomId === ward.id,
       `and the worst hurt is the one who stepped out (${bleeding.homeRoomId})`);
    ok(inRoom[1].homeRoomId === room.id, 'nobody healthy was moved');
  }

  /* ── THE BRAWL IS DUELS, NOT A PILE-ON ────────────────────
   *
   * Every fighter used to swing at `foes[0]`, so three on three was
   * six men hitting one man per side. The pairing is by sorted id, so
   * it is mutual (he picks me back) and it holds still between frames
   * without anybody storing an opponent.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    const room = sh.rooms[0];
    const put = (name, player) => {
      const c = new CrewMember({ name });
      c.isPlayer = player;
      c.roomId = room.id; c.x = room.cx; c.y = room.cy; c.inRoom = true;
      sh.crew.push(c);
      return c;
    };
    const ours  = ['A', 'B', 'C'].map(n => put(n, true));
    const theirs = ['X', 'Y', 'Z'].map(n => put(n, false));
    /* THE ROSTER ORDER IS DELIBERATELY NOT THE ID ORDER.
       Ids come out of a counter, so men created in order arrive in the
       roster in that same order — and a test built that way cannot
       tell a SORTED pairing from an unsorted one, because the two
       agree. Shuffling the roster is what makes the sort load-bearing,
       and the breaking run said so: deleting the sort on one side
       changed nothing until this line existed. */
    /* AND THE TWO SIDE-ORDERS MUST NOT BE INVERSE PERMUTATIONS OF
       EACH OTHER. The first shuffle here was [Z,B,X,C,Y,A], and the
       breaking run still came back clean: ours arrived B,C,A and
       theirs Z,X,Y, which happen to undo one another, so dropping the
       sort produced a DIFFERENT pairing that was still mutual. Ours
       are B,A,C and theirs Z,X,Y below — one order is its own inverse
       and the other is not, so unsorting either side really does
       leave somebody swinging at a man who is facing elsewhere. */
    sh.crew = [ours[1], theirs[2], ours[0], theirs[0], ours[2], theirs[1]];
    const foesOf = (c) => sh.crew.filter(k =>
      k.alive && k.inRoom !== false && !k.isPrisoner &&
      k.roomId === c.roomId && k.isPlayer !== c.isPlayer);

    const picks = ours.map(c => c.meleeTarget(sh, foesOf(c)));
    ok(new Set(picks).size === 3,
       `three of ours pick three DIFFERENT men (${picks.map(p => p.name).join(',')})`);
    ours.forEach((c, i) => {
      const his = picks[i];
      ok(his.meleeTarget(sh, foesOf(his)) === c,
         `${c.name} and ${his.name} are fighting each OTHER, not past one another`);
    });

    // And it holds still: asking again changes nothing.
    ok(ours[0].meleeTarget(sh, foesOf(ours[0])) === picks[0],
       'and the pair is the same the next time it is asked');

    /* AND THE BRAWL ACTUALLY USES IT. `meleeTarget` being right is
       half the job — the loop that swings has to ask it. With the old
       `foes[0]` every blow on both sides landed on one man, so the
       measurement is simply: after a few seconds, is EVERYBODY
       bleeding, or only the first name in the array? Hit points are
       raised first so that nobody dies and re-aims the fight. */
    [...ours, ...theirs].forEach(c => { c.maxHp = 5000; c.hp = 5000; });
    for (let i = 0; i < 300; i++) sh.crew.forEach(c => c.update(0.05, sh));
    const hurt = theirs.filter(t => t.hp < 5000).length;
    ok(hurt === 3, `all three of theirs are taking blows, not just one (${hurt})`);
    const ourHurt = ours.filter(t => t.hp < 5000).length;
    ok(ourHurt === 3, `and all three of ours are (${ourHurt})`);
  }

  /* ── THE SURPLUS HELPS A COLLEAGUE ────────────────────────
   * "jezeli jest przewaga to jeden wolny pomaga innemu w walce" */
  {
    const sh = new Ship('frigate', true, 0, 0);
    const room = sh.rooms[0];
    const put = (name, player) => {
      const c = new CrewMember({ name });
      c.isPlayer = player;
      c.roomId = room.id; c.x = room.cx; c.y = room.cy; c.inRoom = true;
      sh.crew.push(c);
      return c;
    };
    const ours   = ['A', 'B', 'C'].map(n => put(n, true));
    const theirs = ['X', 'Y'].map(n => put(n, false));
    sh.crew = [theirs[1], ours[2], ours[0], theirs[0], ours[1]];
    const foesOf = (c) => sh.crew.filter(k =>
      k.alive && k.inRoom !== false && !k.isPrisoner &&
      k.roomId === c.roomId && k.isPlayer !== c.isPlayer);

    const picks = ours.map(c => c.meleeTarget(sh, foesOf(c)));
    ok(new Set(picks).size === 2, 'three against two is still only two targets');
    const doubled = picks.filter(p => p === picks[0]).length;
    ok(doubled === 2, `and two of ours are on one of theirs (${doubled})`);
    ok(theirs.every(t => picks.includes(t)),
       'with nobody left unengaged — the spare helps, he does not idle');
  }

  /* ── BOARDING PARTIES ARE THE SAME NUMBER ─────────────────
   * A module holds three a side, so a boarding party is three: the
   * two numbers were written out separately and the enemy's was two,
   * which meant a counter-boarding was a fight you outnumbered by
   * arithmetic rather than by play. */
  {
    ok(Ship.ROOM_SLOTS === 3, `three a side (${Ship.ROOM_SLOTS})`);
    const sh = new Ship('frigate', true, 0, 0);
    const room = sh.rooms[0];
    ok(sh.stationSlot(room, Ship.ROOM_SLOTS - 1)[0] !== sh.stationSlot(room, 0)[0],
       'and there really are that many distinct spots');
  }


  /* ── AND SIX MEN IN A ROOM HAVE TO BE READABLE ────────────
   *
   * Straight off the screenshot for this package, which is the only
   * place it could have come from: with three raiders standing
   * between three of yours, the per-man name labels painted across
   * each other AND across your own men's names — "Raider 2dcRaider 3"
   * — and the health bars, 24px wide at 13px spacing, drew as one
   * long green line across the compartment.
   *
   * Nothing measured this before because six men in a module was not
   * possible before.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    const room = sh.rooms[0];
    const put = (name, player) => {
      const c = new CrewMember({ name });
      c.isPlayer = player;
      c.roomId = room.id; c.x = room.cx; c.y = room.cy; c.inRoom = true;
      sh.crew.push(c);
      return c;
    };
    const mine = put('Mine', true);
    const theirs = put('Raider', false);
    const ctx = initRenderer(sb);

    /* update120: a name shows while he is selected or under the pointer */
    ok(!captureText(ctx, () => mine.draw(ctx)).some(d => d.t === 'Mine'),
       'nobody pointing at him: no name over him — the module displays stay readable (jj)');
    sb.UI.selectCrewGroup([mine]);
    const ours = captureText(ctx, () => mine.draw(ctx)).map(d => d.t);
    ok(ours.includes('Mine'), `selected, your own man is named on the deck (${ours.join('|')})`);
    sb.UI.selectCrewGroup([]);
    sb.Input.mouse.x = mine.x; sb.Input.mouse.y = mine.y;
    ok(captureText(ctx, () => mine.draw(ctx)).some(d => d.t === 'Mine'), 'and so is he under the pointer');
    sb.Input.mouse.x = -999; sb.Input.mouse.y = -999;
    sb.UI.selectCrewGroup([mine, theirs]);
    const them = captureText(ctx, () => theirs.draw(ctx)).map(d => d.t);
    ok(!them.includes('Raider'),
       `a boarder is not (${them.join('|')}) — three of those labels wipe out yours`);

    /* THE BARS ARE ON TWO ROWS. Captured by y: a bar is a fillRect, so
       the assertion is on the coordinate the two sides are drawn at,
       which is the thing that was wrong. */
    const bars = [];
    const realRect = ctx.fillRect;
    // update88: boxes, not one bar — a row of 3 px boxes per man.
    ctx.fillRect = function (x, y, w, h) { if (h === 3 && w < 24) bars.push({ y }); };
    try { mine.draw(ctx); theirs.draw(ctx); } finally { ctx.fillRect = realRect; }
    ok(bars.length >= 2, `both men drew a health bar (${bars.length})`);
    const ys = [...new Set(bars.map(b => b.y))];
    ok(ys.length === 2,
       `and the two sides are on DIFFERENT rows (${ys.join(',')}) — one row is one smear`);
  }

  /* ── THE SPIDER DOES NOT BREATHE ──────────────────────────
   *
   * Agreed on 17.09, never built, and the player caught it. Venting
   * is the cheap answer to everything in a hull; while it worked on
   * spiders, the parasite with the virus and the egg was removed by
   * the same click as a rat.
   */
  {
    /* update84: both live in the duct now, and the vacuum reaches them
       through the ship's own tick — so it is vented through the ship. */
    const sh = new Ship('frigate', true, 0, 0);
    const room = sh.rooms[0];
    const spider = sh.addPest(new sb.Pest({ kind: 'spider', roomId: room.id, x: room.cx }));
    const rat    = sh.addPest(new sb.Pest({ kind: 'rat',    roomId: room.id, x: room.cx }));
    spider._moveT = rat._moveT = 1e9;
    ok(spider.breathes() === false, 'a spider does not want air');
    ok(rat.breathes() === true, 'a rat does');

    const o2 = sh.oxygen.getRoom(room.id);
    ok(!!o2, 'the room has an oxygen record');
    const hp0 = { spider: spider.hp, rat: rat.hp };
    // update85: it is the DUCT's air a pest breathes, not the room's.
    for (let i = 0; i < 400; i++) { o2.level = 0; o2.duct = 0; sh.pestTick(0.05); }
    ok(o2.duct === 0, `the duct really is empty (${o2.duct})`);
    ok(spider.hp === hp0.spider && !spider.dead, `the spider is untouched (${spider.hp}/${hp0.spider})`);
    ok(rat.dead, `the rat suffocates in the duct (${rat.hp}/${hp0.rat})`);
    ok(!sh.pests.includes(rat), 'and is gone from it');
  }
})();


// ============================================================
section('258. One shelf in the base, not a copy per screen');
// ============================================================
(function testOneShelf() {
  const sb = loadEngine();
  const { Base, BaseScreen, Save, CargoGrid, Chips, Game } = sb;
  Save.load();

  /* ── THE READER IS NOT AN ACCESSOR ────────────────────────
   *
   * This is the whole bug in one assertion. `Base.storeGrid()` builds
   * a NEW grid of NEW items from the save every time it is called, so
   * two screens that both called it were editing two different
   * objects that happened to hold equal-looking things — and whichever
   * one was written back last won.
   */
  {
    ok(Base.storeGrid() !== Base.storeGrid(),
       'Base.storeGrid() hands back a fresh copy every call');
    BaseScreen.open();
    ok(BaseScreen.liveShelf() === BaseScreen.liveShelf(),
       'but the base screen has ONE shelf and keeps handing back that one');
    ok(BaseScreen.packGrids().store === BaseScreen.liveShelf(),
       'and the packing screen is given that same object, not a twin');
  }

  /* ── A CHIP MOUNTED ON THE BOARD LEAVES THE SHELF ─────────
   *
   * The player's report: "jak dodaje cpu to zostaje w inwentory cpu
   * ale ten co byl zostaje w inwentory, moge dodac znow ten sam i mam
   * 2 w cpu u kapitana i dalej w inwentory."
   *
   * The move itself was never wrong — one grid loses the item, the
   * other gains it. What put the chip back was the base screen
   * committing its own stale copy of the shelf afterwards, which is
   * why this test ends with that commit rather than with the move.
   */
  let cap = null;
  {
    Save.load();
    cap = promoteForTest(sb, { level: 8 });
    const shelf = BaseScreen.liveShelf();
    ok(!!shelf, 'the base has a shelf');

    // A chip on the shelf, placed the way the game places anything.
    const key = Object.keys(sb.CARGO_ITEMS).find(k => sb.CARGO_ITEMS[k].kind === 'tablet');
    ok(!!key, `there is a chip item to test with (${key})`);
    const chip = new sb.CargoItem(key);
    ok(shelf.autoPlace(chip), 'and it goes onto the shelf');
    const onShelf = g => g.items.filter(it => it.defKey === key).length;
    ok(onShelf(shelf) === 1, 'one chip on the shelf');

    // Mount it: off the shelf, onto the board, committed to the man.
    const board = Chips.board(cap);
    shelf.remove(chip);
    ok(board.autoPlace(chip), 'the chip goes onto the CPU board');
    Chips.commit(cap, board);
    Base.saveCommander(cap);
    BaseScreen.commitPack();

    /* THE READ THAT MATTERS is a fresh one off the save — that is what
       the base draws from next time, and what the old code resurrected
       the chip into. */
    ok(onShelf(Base.storeGrid()) === 0,
       `the chip is gone from the saved shelf (${onShelf(Base.storeGrid())})`);
    const saved = Base.commanderById(cap.id);
    const onBoard = (saved.chips?.items ?? []).filter(it => it.defKey === key).length;
    ok(onBoard === 1, `and is on the commander's board exactly once (${onBoard})`);
  }

  /* ── AND THE CPU SCREEN IS HANDED THAT SHELF ──────────────
   *
   * Identity, not contents: a test that compared what was on the two
   * grids could not tell the shelf from a twin of it, and a twin of
   * the shelf IS the bug. So the assertion is `===`.
   */
  {
    const T = Game.__test;
    BaseScreen.open();
    const mine = BaseScreen.liveShelf();
    T._openCpuBoard(cap.id);
    ok(sb.LootScreen.isOpen(), 'the CPU board opens');
    const shown = sb.LootScreen._grids().wreck;
    ok(shown === mine,
       'and it edits the base screen\'s own shelf, not a deserialised twin');
  }
})();


// ============================================================
section('259. A boarding party is a module-full, both ways');
// ============================================================
(function testPartySize() {
  const sb = loadEngine();
  const { Ship, Save, Game, UI } = sb;
  Save.load(); Save.startRun();

  /* ── OURS ─────────────────────────────────────────────────
   * Select four, send three: a module holds three a side and a party
   * that cannot fit in the room it lands in is a party with a man
   * standing in a corridor. */
  {
    const { T, player, enemy } = makeCombat(sb);
    while (player.crew.filter(c => c.isPlayer && !c.isPet).length < 4) {
      player.addCrew(new sb.CrewMember({}));
    }
    const pick = player.crew.filter(c => c.isPlayer && !c.isPet).slice(0, 4);
    UI.selectCrewGroup(pick);
    ok(UI.getSelectedCrewAll().length === 4, 'four men are selected');
    // Somebody has to be in the chair or no order is given at all.
    T.commander = { id: 'cap_test', name: 'Test', level: 8, karma: 50 };
    T._launchBoarders();
    const party = T.boardingParty;
    ok(!!party, 'a party goes');
    ok(party.members.length === Ship.ROOM_SLOTS,
       `and it is ${Ship.ROOM_SLOTS} strong, not four (${party.members.length})`);
    ok(enemy !== null, 'there is a hull to board');
  }

  /* ── AND THEIRS ───────────────────────────────────────────
   *
   * This was written out as `-2` at the other end of the file while
   * ours said three, so a counter-boarding was a fight the player
   * outnumbered by arithmetic rather than by play.
   */
  {
    const { T, player, enemy } = makeCombat(sb);
    while (enemy.crew.filter(c => c.alive).length < 6) {
      const c = new sb.CrewMember({});
      c.isPlayer = false;
      enemy.addCrew(c);
    }
    T.enemyParty = null;
    T.counterBoarded = false;
    T.event = { title: 'x', text: 'x', choices: [
      { label: 'No mercy', result: { resumeCombat: true } },
    ] };
    // The roll is 60/40; drive it until it takes, and stop if it never
    // does rather than spinning — a test that hangs is a test that did
    // not run.
    let party = null;
    for (let i = 0; i < 60 && !party; i++) {
      T.counterBoarded = false;
      T.enemyParty = null;
      T.STATE = 'event';
      T.event = { title: 'x', text: 'x', choices: [
        { label: 'No mercy', result: { resumeCombat: true } },
      ] };
      T._resolveEvent(0);
      party = T.enemyParty;
    }
    ok(!!party, 'they storm the ship rather than surrender');
    if (party) {
      ok(party.members.length === Ship.ROOM_SLOTS,
         `and they send ${Ship.ROOM_SLOTS}, like us (${party.members.length})`);
    }
    ok(player !== null, 'there is a hull to be boarded');
  }

  /* ── BUT THEY NEVER EMPTY THEIR OWN HULL ──────────────────
   * A boarding party that abandons its ship is a different event with
   * a different ending; the crew that leaves nobody behind is a
   * derelict, and the fight would end on the wrong screen. */
  {
    const { T, enemy } = makeCombat(sb);
    enemy.crew = enemy.crew.filter(c => c.alive).slice(0, 2);
    let party = null;
    for (let i = 0; i < 60 && !party; i++) {
      T.counterBoarded = false;
      T.enemyParty = null;
      T.STATE = 'event';
      T.event = { title: 'x', text: 'x', choices: [
        { label: 'No mercy', result: { resumeCombat: true } },
      ] };
      T._resolveEvent(0);
      party = T.enemyParty;
    }
    ok(!party || party.members.length <= 1,
       `two aboard means at most one comes across (${party ? party.members.length : 0})`);
  }
})();

// ============================================================
section('260. One icon set, a full strip, and a bolt from the barrel');
// ============================================================
(function testWhatYouCanSee() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Game, Renderer, CombatManager, TASK, SUIT_AIR } = sb;
  Save.load(); Save.startRun();

  const keysOf = (c, ship) => Renderer.crewMarks(c, ship).map(m => m.key);

  /* ── THE STRIP SAYS WHAT HE IS DOING ──────────────────────
   *
   * Repairing, fighting a fire, patching a hole, out of air — four of
   * the things a player most needs mid-battle, and none of them was
   * on the panel. He had to find the man on the deck and work it out
   * from his animation.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const man = sh.crew[0];

    man.task = TASK.REPAIR;
    ok(keysOf(man, sh).includes('repairing'),
       `repairing is on the strip (${keysOf(man, sh).join(',')})`);
    man.task = TASK.FIRE;
    ok(keysOf(man, sh).includes('firefighting'), 'so is putting out a fire');
    man.task = TASK.BREACH;
    ok(keysOf(man, sh).includes('patching'), 'so is patching a breach');
    man.task = TASK.IDLE;
    ok(!keysOf(man, sh).some(k =>
         ['repairing', 'firefighting', 'patching'].includes(k)),
       'and an idle man is doing none of them');

    /* OUT OF AIR, asked with the SAME numbers the bottle over his head
       asks with, so the deck and the panel cannot disagree. */
    man.air = 0;
    ok(man.airFrac() < SUIT_AIR.LOW_FRACTION, 'his tank is dry');
    ok(keysOf(man, sh).includes('air'), 'and the strip says so');
    man.air = man.airMax();
    ok(!keysOf(man, sh).includes('air'), 'a full tank says nothing');
  }

  /* ── AND A FIGHT OVERRIDES WHAT HE WAS SENT TO DO ─────────
   *
   * `CrewMember.update` lets the room brawl pre-empt every task and
   * returns before the task ever runs, so a man swinging at a boarder
   * still CARRIES `task = REPAIR`. A panel that printed the task
   * field would be lying in the one moment the player watches
   * hardest. The question is asked of the ship — `roomContested`, the
   * same predicate that stops the room's other work.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const room = sh.rooms[0];
    const man = sh.crew[0];
    man.roomId = room.id; man.x = room.cx; man.y = room.cy; man.inRoom = true;
    man.task = TASK.REPAIR;
    ok(keysOf(man, sh).includes('repairing'), 'he is repairing');

    const foe = new CrewMember({ name: 'Raider' });
    foe.isPlayer = false;
    foe.roomId = room.id; foe.x = room.cx; foe.y = room.cy; foe.inRoom = true;
    sh.crew.push(foe);
    ok(sh.roomContested(room.id), 'a boarder walks in');
    const k = keysOf(man, sh);
    ok(k.includes('fighting'), `the strip says FIGHTING (${k.join(',')})`);
    ok(!k.includes('repairing'),
       'and stops claiming he is repairing, which he is not');
    ok(man.task === TASK.REPAIR,
       'even though the task field still says so — that is the point');
  }

  /* ── EVERY MARK COMES OUT OF THE ONE ICON SET ─────────────
   *
   * The claim the player asked for: "uzyj tych samych co sa nad
   * zalogantami w statku". This is what stops the next mark from
   * being added as a text character again, or with an icon name that
   * does not exist — which draws nothing at all and looks like a gap.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const room = sh.rooms[0];
    const man = sh.crew[0];
    man.roomId = room.id; man.x = room.cx; man.y = room.cy; man.inRoom = true;
    const seen = new Set();
    const collect = () => Renderer.crewMarks(man, sh).forEach(m => {
      seen.add(m.key);
      if (m.key === 'console') {
        ok(!!m.glyph, 'the module mark keeps its glyph — SYSTEM_GLYPHS is one table already');
      } else {
        ok(!!m.icon && !!Renderer.STAT_ICONS[m.icon],
           `${m.key} draws icon "${m.icon}", and it exists`);
      }
    });
    man.virus = true; man.infected = true; man.hunger = 2; man.air = 0;
    man.task = TASK.FIRE;
    collect();
    man.virus = false; man.infected = false; man.hunger = 100;
    man.air = man.airMax(); man.task = TASK.REPAIR;
    collect();
    man.task = TASK.BREACH; collect();
    man.hp = 1; man.state = 'injured'; collect();
    man._bandaged = true; collect();
    man.state = 'ok'; man.hp = man.maxHp; man._awayTeam = true; collect();
    man._awayTeam = false; man.frozen = true; collect();
    ok(seen.size >= 8, `and that covered ${seen.size} different marks`);
  }

  /* ── THE DECK DRAWS THE SAME ICONS, NOT ITS OWN ───────────
   *
   * `crew.js` used to build a mess tin out of an ellipse and two
   * lines and a bottle out of a rect and a fill, while the roster
   * printed text characters for the same two facts. Two pictures of
   * one thing in two files. The deck asks `crewMarks` now and paints
   * what comes back, so there is nothing left to drift.
   */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const man = sh.crew[0];
    man.hunger = 2; man.air = 0;
    const ctx = initRenderer(sb);
    // No TEXT is drawn for a condition any more — that was the old
    // roster's language and it never belonged over a man's head.
    const drawn = captureText(ctx, () => man.draw(ctx)).map(d => d.t);
    ok(!drawn.includes('☣'), `no glyphs over his head (${drawn.join('|')})`);
    /* AND IT DOES DRAW THEM. "No text" is half a claim — it is also
       true of a deck that draws nothing at all, which is exactly what
       deleting the block would produce. So the icon calls are counted
       by wrapping the one function that makes them. */
    const painted = [];
    const realIcon = Renderer.drawStatIcon;
    Renderer.drawStatIcon = function (c2, kind) { painted.push(kind); };
    try { man.draw(ctx); } finally { Renderer.drawStatIcon = realIcon; }
    ok(painted.includes('hunger'), `an empty stomach is painted (${painted.join(',')})`);
    ok(painted.includes('air'), 'and an empty tank');
    // And the marks the deck shows are a SUBSET of the roster's, named
    // in one list rather than re-derived from conditions a second time.
    const deck = CrewMember.DECK_MARKS;
    ok(deck.includes('starving') && deck.includes('air'),
       'the deck list names the slow killers');
    ok(!deck.includes('repairing') && !deck.includes('fighting'),
       'and not what he is doing — the roster carries that');
  }

  /* ── THE TOP BAR CARRIES DOSES AND RATIONS ────────────────
   * Read off the hold, like the ore readout, so there is no second
   * number to keep in step. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    sh.cargo.items.length = 0;
    const T = Game.__test;
    T.playerShip = sh;
    const ctx = initRenderer(sb);
    const bar = () => captureText(ctx, () => Renderer.drawHUD({ playerShip: sh }))
      .map(d => String(d.t));

    ok(bar().includes('0'), 'an empty hold reads zero, it does not hide the readout');
    sh.cargo.add('medkit');
    sh.cargo.add('ration_pack');
    const doses = sh.doseCount(), food = sh.cargo.countOfTag('food');
    ok(doses > 0 && food > 0, `something aboard (${doses} doses, ${food} meals)`);
    const t = bar();
    ok(t.includes(String(doses)), `the bar prints the dose count (${doses})`);
    ok(t.includes(String(food)), `and the ration count (${food})`);

    /* AND IT IS THE HOLD IT IS READING, not a counter that was right
       when the run started.
       NOT `bar().includes('8')`: the breaking run caught that one
       passing on a build where the readout was hard-wired to 10,
       because the MISSILE count happened to be 8 that frame and the
       assertion only asked whether the string appeared anywhere. So
       the claim is made on the CHANGE — spend two doses and exactly
       one number on the bar moves, from ten to eight. */
    const was = bar();
    const d0 = sh.doseCount();
    sh.spendDoses(Ship.MEDKIT_DOSES);
    const now = bar();
    const d1 = sh.doseCount();
    ok(d1 === d0 - Ship.MEDKIT_DOSES, `two doses are gone (${d0} → ${d1})`);
    const moved = was.map((t, i) => [t, now[i]]).filter(([a, b]) => a !== b);
    ok(moved.length === 1,
       `exactly one number on the bar moved (${JSON.stringify(moved)})`);
    ok(moved[0] && moved[0][0] === String(d0) && moved[0][1] === String(d1),
       `and it is the dose count (${JSON.stringify(moved[0])})`);

    /* THE SAME FOR THE RATIONS (update130). `includes('1')` slept through
       the ration readout being dropped: the new plate prints other 1s.
       So, as with the doses: stow two more and exactly one number moves. */
    const wasF = bar();
    const f0 = sh.cargo.countOfTag('food');
    sh.cargo.add('ration_pack'); sh.cargo.add('ration_pack');
    const nowF = bar();
    const f1 = sh.cargo.countOfTag('food');
    const movedF = wasF.map((t, i) => [t, nowF[i]]).filter(([a, b]) => a !== b);
    ok(f1 > f0 && movedF.length === 1 && movedF[0][0] === String(f0) && movedF[0][1] === String(f1),
       `two more rations stowed: exactly the ration count moves (${f0} → ${f1}; ${JSON.stringify(movedF)})`);
  }

  /* ── THE BOLT LEAVES THE BARREL ───────────────────────────
   *
   * The gun was drawn along the top edge of the hull and fired from
   * the middle of its right flank: two positions for one gun, in two
   * files, that had never met. Every gun aboard fired from the same
   * pixel whichever bay it was in.
   */
  {
    const { player, enemy } = makeCombat(sb);
    while (player.weapons.filter(Boolean).length < 2) {
      player.weapons.push(new sb.Weapon('laser_basic', player.weapons.length));
    }
    const mounts = player.weaponMounts();
    ok(mounts.length === 2, `two guns, two mounts (${mounts.length})`);
    ok(mounts[0].muzzleX !== mounts[1].muzzleX,
       `and they are in different places (${mounts[0].muzzleX} vs ${mounts[1].muzzleX})`);
    ok(mounts.every(m => m.muzzleX === (m.dir > 0 ? m.x + m.w : m.x)),
       'the muzzle is the end of the barrel the gun points at');

    const b = player.roomBounds();
    ok(mounts.every(m => m.muzzleY < b.y),
       'the guns sit above the plating, which is where they are drawn');

    // And the shot really starts there.
    const gun = player.weapons[1];
    // `powered` is a getter off the weapons module, so the gun is
    // armed by giving the bay its power rather than by lying to it.
    powerModule(player, 'weapons', 2);
    // `armed` is what `fireRefusal` asks, and `Weapon.update` is what
    // sets it — so the gun is charged the way the game charges it.
    for (let i = 0; i < 400 && !gun.armed; i++) { player.update(0.05); gun.update(0.05); }
    ok(gun.armed, 'the gun comes to readiness');
    const before = CombatManager._projectiles.length;
    CombatManager.playerFire(gun, enemy.rooms[0]);
    const shots = CombatManager._projectiles.slice(before);
    ok(shots.length > 0, 'it fires');
    const muzzle = player.muzzleFor(gun);
    ok(!!muzzle, 'the gun knows where its barrel is');
    ok(shots.every(p => p.x === muzzle.x && p.y === muzzle.y),
       `and every bolt starts there (${shots[0].x},${shots[0].y} vs ${muzzle.x},${muzzle.y})`);
    ok(shots[0].x !== b.x + b.w + 10,
       'not at the corner of the box round the whole ship, as it used to');
  }

  /* ── AND SO DO THEIRS ─────────────────────────────────────
   * The same function on the other hull, so the rule is not "the
   * player's side happens to look right". Their firing goes through
   * the AI rather than through `playerFire`, which is a different code
   * path and had its own copy of the corner. */
  {
    const { player, enemy } = makeCombat(sb, { enemyArmed: true });
    const eb = enemy.roomBounds();
    /* TWO THINGS THIS HAD TO LEARN.
       1. The ships must be ticked as well. `CombatManager.update` runs
          the AI and the projectiles; it does not charge anybody's guns
          — `Ship.update` does, and in the game that is the main loop.
          A loop that only drove the manager waited forever for `armed`.
       2. Drive the AI ALONE once the guns are hot. `update` fires the
          shot and then MOVES it in the same call, so by the time the
          loop sees it, `p.x` is no longer where it came from — the
          first version of this test read a bolt already in flight and
          compared it to the barrel. */
    for (let i = 0; i < 1500; i++) {
      player.update(0.05); enemy.update(0.05);
      if (enemy.weapons.some(w => w && w.armed)) break;
    }
    ok(enemy.weapons.some(w => w && w.armed), 'their guns come to readiness');
    let shot = null;
    for (let i = 0; i < 400 && !shot; i++) {
      CombatManager._updateAI(0.05);
      shot = CombatManager._projectiles.find(p => p.fromPlayer === false);
    }
    ok(!!shot, 'they open fire');
    if (shot) {
      const muzzles = enemy.weaponMounts();
      ok(muzzles.length > 0, `they have guns on mounts (${muzzles.length})`);
      ok(muzzles.some(m => m.muzzleX === shot.x && m.muzzleY === shot.y),
         `and the bolt leaves one of them (${shot.x},${shot.y} of ` +
         `${muzzles.map(m => `${m.muzzleX},${m.muzzleY}`).join(' | ')})`);
      ok(shot.x !== eb.x - 10,
         'not from the corner of the box round their whole hull');
    }
    ok(!!player, 'and there is somebody to shoot at');
  }

  /* ── AND SO DOES A BEAM ───────────────────────────────────
   * A beam used to be a horizontal bar drawn across the TARGET from
   * the target's own edge — a weapon with no source. */
  {
    const p = new sb.Projectile({
      x: 100, y: 50, targetX: 400, targetY: 200, speed: 0,
      type: 'beam', def: {}, fromPlayer: true,
    });
    p.beamProgress = 0.5;
    const ctx = initRenderer(sb);
    const seg = [];
    const realMove = ctx.moveTo, realLine = ctx.lineTo;
    ctx.moveTo = function (x, y) { seg.push(['m', x, y]); };
    ctx.lineTo = function (x, y) { seg.push(['l', x, y]); };
    try { p.drawBeam(ctx, 600, 180, 200); } finally {
      ctx.moveTo = realMove; ctx.lineTo = realLine;
    }
    const start = seg.find(s => s[0] === 'm');
    ok(!!start, 'the beam is drawn');
    ok(start[1] === 100 && start[2] === 50,
       `and it starts at the gun (${start[1]},${start[2]})`);
    const end = seg.find(s => s[0] === 'l');
    ok(end[1] === 700, `and reaches halfway across the target (${end[1]})`);
  }
})();

// ============================================================
section('261. A hungry man helps himself, from the bottom of the shelf');
// ============================================================
(function testAutoEating() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, HUNGER, TASK } = sb;
  Save.load(); Save.startRun();

  const rig = () => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    sh.cargo.items.length = 0;
    sh.crew.forEach(c => { c.hunger = 100; });
    return sh;
  };
  const run = (sh, n = 200) => { for (let i = 0; i < n; i++) sh.update(0.1); };
  /* UNITS OF ONE BOX. `cargo.countOf` answers by KIND, and every
     ration is `kind: 'food'` — so `countOf('protein_paste')` is
     always zero and an assertion built on it measures nothing. */
  const units = (sh, key) => sh.cargo.items
    .filter(it => it.defKey === key)
    .reduce((n, it) => n + (it.qty ?? 1), 0);

  /* ── THE WORST BOX FIRST ──────────────────────────────────
   *
   * "poczawszy od najgoryszych potraw po lepsze". It is the opposite
   * of what a player does by hand, and that is the point: the
   * automatic mouth clears out the paste, and the field meals are
   * still there when the player decides who gets one.
   */
  {
    const sh = rig();
    sh.cargo.add('field_meal');       // 80
    sh.cargo.add('protein_paste');    // 25 — the worst thing aboard
    sh.cargo.add('ration_pack');      // 50
    const man = sh.crew.find(c => c.isPlayer && !c.isPet);
    man.hunger = 0;   // update87: he helps himself only once it starts to hurt
    const meal = sh.mealFor(man);
    ok(meal && meal.defKey === 'protein_paste',
       `he reaches for the worst box aboard (${meal && meal.defKey})`);

    const paste0 = units(sh, 'protein_paste');
    const meals0 = units(sh, 'field_meal');
    run(sh);
    ok(units(sh, 'protein_paste') === paste0 - 1,
       `and that is the one that is opened (${units(sh, 'protein_paste')} of ${paste0})`);
    ok(units(sh, 'field_meal') === meals0,
       'the field meal is untouched — it is still the player\'s to give');
  }

  /* ── AND THE PLAYER CAN STILL NAME THE BOX ────────────────
   * The automatic meal takes the clicking away, not the choice. */
  {
    const sh = rig();
    sh.cargo.add('protein_paste');
    const good = sh.cargo.add('field_meal');
    const man = sh.crew.find(c => c.isPlayer && !c.isPet);
    man.hunger = HUNGER.HUNGRY - 5;
    const r = sh.feedCrew(man, good);
    ok(r.ok, `FEED names a box and it is accepted (${r.message})`);
    const meals0 = units(sh, 'field_meal'), paste0 = units(sh, 'protein_paste');
    run(sh, 80);        // a meal is six seconds since update87
    ok(units(sh, 'field_meal') === meals0 - 1, 'and THAT box is the one he eats');
    ok(units(sh, 'protein_paste') === paste0, 'the paste is still on the shelf');
  }

  /* ── THE FIGHT COMES FIRST ────────────────────────────────
   * The same predicate that stops the room's other work, so "a brawl
   * pre-empts everything" has one answer aboard this ship. */
  {
    const sh = rig();
    sh.cargo.add('protein_paste');
    const room = sh.rooms[0];
    const man = sh.crew.find(c => c.isPlayer && !c.isPet);
    man.roomId = room.id; man.homeRoomId = room.id;
    man.x = room.cx; man.y = room.cy; man.inRoom = true;
    man.hunger = 0;   // update87: he helps himself only once it starts to hurt
    const foe = new CrewMember({ name: 'Raider' });
    foe.isPlayer = false;
    foe.roomId = room.id; foe.x = room.cx; foe.y = room.cy; foe.inRoom = true;
    foe.hp = 10000; foe.maxHp = 10000;
    man.hp = 10000; man.maxHp = 10000;
    sh.crew.push(foe);
    ok(sh.roomContested(room.id), 'there is a boarder in the room');
    const food0 = sh.cargo.countOf('food');
    run(sh, 60);
    ok(sh.cargo.countOf('food') === food0,
       `nobody opens a ration mid-brawl (${sh.cargo.countOf('food')} of ${food0})`);

    // And the moment the fight is over, he eats.
    sh.crew.splice(sh.crew.indexOf(foe), 1);
    run(sh, 100);
    ok(sh.cargo.countOf('food') === food0 - 1, 'and then he does');
  }

  /* ── BUT A FIRE DOES NOT STOP HIM ─────────────────────────
   * The player's own call: "zostawi gaszenie czy zazadzanie modulem
   * na rzecz jedzenia". Hunger outranks the hose; it does not outrank
   * a man swinging at him. */
  {
    const sh = rig();
    sh.cargo.add('protein_paste');
    const man = sh.crew.find(c => c.isPlayer && !c.isPet);
    man.hunger = 0;   // update87: he helps himself only once it starts to hurt
    man.assignTask(TASK.FIRE, sh.rooms[0].id);
    const food0 = sh.cargo.countOf('food');
    run(sh, 100);
    ok(sh.cargo.countOf('food') === food0 - 1,
       'a man fighting a fire still stops to eat');
  }

  /* ── AND WHILE HE EATS, HE IS NOT WORKING ─────────────────
   *
   * The busy clock has been read in more and more places since it was
   * added — the mark strip since 78, `crewOperating` since 79 — and
   * `_updateTask` was the last loop that did not know about it. So a
   * man could eat a ration and repair a module with the same hands.
   */
  {
    const sh = rig();
    const sys = sh.getSystem('engines') || sh.systems[0];
    const room = sh.getRoomById(sys.roomId);
    sys.damagedLevels = 1;
    const man = sh.crew.find(c => c.isPlayer && !c.isPet);
    man.roomId = room.id; man.homeRoomId = room.id;
    man.x = room.cx; man.y = room.cy; man.inRoom = true;
    man.assignTask(TASK.REPAIR, room.id);
    man.hunger = HUNGER.HUNGRY - 5;
    sh.cargo.add('protein_paste');
    const r = sh.feedCrew(man);
    ok(r.ok && man.busy, `he is eating (${r.message})`);
    /* `damagedLevels` is an INTEGER and a level takes many seconds to
       come back, so it does not move inside a three-second meal — an
       assertion on it would be true whether he worked or not. The
       progress meter is what the hands actually push. */
    const p0 = sys.repairProgress;
    for (let i = 0; i < 10; i++) man.update(0.05, sh);
    ok(sys.repairProgress === p0,
       `the module gains nothing while he chews (${sys.repairProgress} of ${p0})`);
    ok(man.task === TASK.REPAIR,
       'the order is PAUSED, not cancelled — he has not lost the job');

    // And when the meal is done he picks it straight back up.
    for (let i = 0; i < 200 && man.busy; i++) { sh._busyTick(0.05); }
    ok(!man.busy, 'the meal ends');
    for (let i = 0; i < 40; i++) man.update(0.05, sh);
    ok(sys.repairProgress > p0 || sys.damagedLevels === 0,
       `and the repair goes on (${sys.repairProgress} of ${p0})`);
  }

  /* ── HE DOES NOT EAT OUT OF SOMEBODY ELSE'S HOLD ──────────
   * A boarder is carried on the DEFENDING ship's roster, so without a
   * side check your raiders would live off the hold they came to
   * loot — and the enemy's men off yours. */
  {
    const sh = rig();
    sh.cargo.add('protein_paste');
    const foe = new CrewMember({ name: 'Raider' });
    foe.isPlayer = false;
    foe.roomId = sh.rooms[0].id; foe.x = 0; foe.y = 0; foe.inRoom = true;
    foe.hunger = 1;
    sh.crew.push(foe);
    sh.crew.forEach(c => { if (c.isPlayer) c.hunger = 100; });
    const food0 = sh.cargo.countOf('food');
    run(sh, 100);
    ok(sh.cargo.countOf('food') === food0,
       `a boarder does not eat our rations (${sh.cargo.countOf('food')} of ${food0})`);
  }

  /* ── ONE CHOOSER, CAT INCLUDED ────────────────────────────
   * The cat's meal used to be picked by its own copy of this — the
   * first ration in grid order — while the player's FEED went through
   * `mealFor`. Same ladder now. The EGG stays its own rule, and that
   * is not a taste: an egg left in the hold HATCHES. */
  {
    const sh = rig();
    const cat = typeof sb.makeCat === 'function' ? sb.makeCat('black') : null;
    ok(!!cat, 'there is a cat');
    sh.addCrew(cat);
    sh.cargo.add('field_meal');
    sh.cargo.add('ration_pack');
    sh.cargo.add('protein_paste');
    cat.hunger = 5;
    const pick = sh.mealFor(cat);
    ok(pick && pick.defKey === 'protein_paste',
       `the cat is on the same ladder (${pick && pick.defKey})`);
    const paste0 = units(sh, 'protein_paste'), meals0 = units(sh, 'field_meal');
    run(sh, 120);
    ok(units(sh, 'protein_paste') < paste0, 'and eats from the bottom too');
    ok(units(sh, 'field_meal') === meals0, 'leaving the good tray alone');
  }

  /* ── AND FEED CAN GIVE HER THE EGG ────────────────────────
   *
   * Found by the breaking run, not by design. The cat helped herself
   * to an egg through `_startMeal` while FEED, asking `mealFor`, told
   * the player there was "nothing aboard she will eat" — two answers
   * to one question, and the player met the wrong one. One chooser
   * now, and the egg is in it.
   */
  {
    const sh = rig();
    const cat = sb.makeCat('ginger');
    sh.addCrew(cat);
    const egg = sh.cargo.add('spider_egg');
    ok(!!egg, 'an egg in the hold and nothing else');
    cat.hunger = 5;
    ok(sh.mealFor(cat) === egg, 'it is what she opens next');
    ok(sh.feedRefusal(cat) === null,
       `and FEED does not claim there is nothing (${sh.feedRefusal(cat)})`);
    const r = sh.feedCrew(cat);
    ok(r.ok, `the order goes through (${r.message})`);

    // A man is not offered one, and that rule still lives in willEat.
    const man = sh.crew.find(c => c.isPlayer && !c.isPet);
    ok(sh.willEat(man, egg) === false, 'a man will not touch an egg');
    ok(sh.mealFor(man) === null, 'so it is not his next meal either');
  }
})();

// ============================================================
section('262. A bigger ward cures more, two levels at a time');
// ============================================================
(function testWardLadder() {
  const sb = loadEngine();
  const { Ship, Save, VIRUS_SECONDS } = sb;
  Save.load(); Save.startRun();

  const ward = (lv) => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    powerModule(sh, 'medbay', lv);
    const med  = sh.getSystem('medbay');
    const room = sh.getRoomById(med.roomId);
    const man  = sh.crew[0];
    man.roomId = room.id; man.homeRoomId = room.id;
    man.x = room.cx; man.y = room.cy; man.inRoom = true;
    return { sh, med, room, man };
  };
  /* PINNED WHILE THE CLOCK RUNS. The plague makes a man wander — that
     is update42 and it stays — so a test about the CURE has to hold
     him still or it is really a test about the wandering, and a random
     one at that. `who` is re-seated every frame. */
  const lie = (sh, secs, who = null, room = null) => {
    for (let i = 0; i < secs * 20; i++) {
      if (who && room) { who.roomId = room.id; who.inRoom = true; who.x = room.cx; who.y = room.cy; }
      sh.update(0.05);
    }
  };

  /* ── THE LADDER ───────────────────────────────────────────
   * "3 lev leczy epidemie po zwlokach, a 5 lev dodatkowo virusa
   * pajaka" — and the rungs are two apart, with 7 and 8 left empty on
   * purpose. */
  {
    ok(Ship.CURE_LEVELS.plague === 3, `plague at three (${Ship.CURE_LEVELS.plague})`);
    ok(Ship.CURE_LEVELS.virus === 5, `the virus at five (${Ship.CURE_LEVELS.virus})`);
    const med = new Ship('frigate', true, 0, 0).getSystem('medbay');
    ok(med.def.maxLevel === 8,
       `and the ward still goes to eight (${med.def.maxLevel}) — an upgrade you cannot yet run is still one a hit cannot take`);
    ok(med.def.maxLevel > Ship.CURE_LEVELS.virus,
       'with rungs above the last cure, left empty on purpose');
  }

  /* ── A SMALL WARD PATCHES WOUNDS AND NOTHING ELSE ─────────
   * Which is what a ward has always done, and is why the starting
   * hulls are not quietly handed a cure. */
  {
    const { sh, man } = ward(1);
    ok(sh.wardLevel() === 1, `a level one ward (${sh.wardLevel()})`);
    ok(!sh.canCure('plague'), 'cannot touch the plague');
    ok(!sh.canCure('virus'), 'nor the virus');
    man.infected = true;
    man.hp = 10;
    lie(sh, Ship.CURE_SECONDS * 2, man, sh.getRoomById(sh.getSystem('medbay').roomId));
    ok(man.infected === true, 'so a sick man lies there and stays sick');
    ok(man.hp > 10, `though his wounds still close (${man.hp})`);
  }

  /* ── THREE CURES THE PLAGUE, AND IT TAKES TIME ────────────
   *
   * A cure that landed the frame he walked in would make the ward a
   * switch and the carry free. The price is the twenty seconds his
   * hands are off a console — the same shape as everything else since
   * update78.
   */
  {
    const { sh, man } = ward(3);
    ok(sh.canCure('plague'), 'a level three ward can treat the plague');
    ok(!sh.canCure('virus'), 'but not the virus');
    man.infected = true;
    const med3 = sh.getRoomById(sh.getSystem('medbay').roomId);
    lie(sh, Ship.CURE_SECONDS / 2, man, med3);
    ok(man.infected === true,
       'half way through he is still infected — it is not a button');
    lie(sh, Ship.CURE_SECONDS, man, med3);
    ok(man.infected === false, 'and then the ward has it');
  }

  /* ── WALKING OUT RESETS THE CLOCK ─────────────────────────
   * Treatment is not something you bank in instalments between
   * fights. */
  {
    const { sh, man, room } = ward(3);
    man.infected = true;
    lie(sh, Ship.CURE_SECONDS * 0.8, man, room);
    ok(man.infected === true, 'nearly done');
    man.roomId = 'elsewhere'; man.homeRoomId = 'elsewhere'; man.inRoom = true;
    sh.update(0.05);
    ok(!(man._cureT > 0), 'one frame outside and the clock is back to nothing');
    man.homeRoomId = room.id;
    lie(sh, Ship.CURE_SECONDS * 0.5, man, room);
    ok(man.infected === true,
       'so the half spell he came back for is not enough');
    lie(sh, Ship.CURE_SECONDS, man, room);
    ok(man.infected === false, 'a full one is');
  }

  /* ── AND HE STAYS ON THE TABLE ────────────────────────────
   *
   * Found by the breaking run. The plague makes a man wander off to
   * empty rooms and sometimes out of an airlock — update42, and it
   * stays — which meant that the moment a ward could treat the plague
   * the patient walked out of it. The first run of the level three
   * cure collected seven seconds of a twenty-second course in forty
   * seconds of game.
   *
   * Asserted on the WANDER CLOCK, not on where he ends up: `_infT` is
   * what decides he bolts, and a test that watched his room id would
   * be reading a dice roll.
   */
  {
    const { sh, man } = ward(3);
    man.infected = true;
    man._infT = 0;
    lie(sh, 5);                             // NOT pinned — that is the point
    ok(man._cureT > 0, 'the ward has him');
    ok(man._infT === 0,
       `and the wandering clock does not run while it does (${man._infT})`);

    // The whole of it, with nobody holding him down.
    lie(sh, Ship.CURE_SECONDS);
    ok(man.infected === false, 'so the course finishes by itself');
    ok(man.roomId === sh.getSystem('medbay').roomId,
       'and he is still where he was put');
  }

  /* ── FIVE CURES THE VIRUS, AND STOPS THE EGG ──────────────
   *
   * This is the one that changes the campaign. Until now a bite was a
   * clock you could not buy your way out of — only a research post
   * could. A level five ward is a very large investment, and this is
   * what it buys.
   */
  {
    const { sh, man } = ward(5);
    ok(sh.canCure('virus') && sh.canCure('plague'),
       'a level five ward treats both');
    man.virus = true; man.virusT = 40;
    lie(sh, Ship.CURE_SECONDS + 1, man, sh.getRoomById(sh.getSystem('medbay').roomId));
    ok(man.virus === false, 'the bite is beaten');
    ok(man.virusT === VIRUS_SECONDS,
       `and the clock is back where a healthy man's sits (${man.virusT}) — there is no second flag to go stale`);
    ok(!man.dead, 'he is alive, which is the whole point');
  }

  /* ── WHAT YOU PAID FOR IS NOT WHAT YOU HAVE ───────────────
   *
   * `wardLevel` is the smaller of what is BUILT and what is RUNNING —
   * the same expression carbonite counts slabs with since update77.
   * A hit takes the quarantine bench away mid-fight; so does pulling
   * the power. Both halves matter and the player asked for both.
   */
  {
    const { sh, med, man } = ward(5);
    ok(sh.wardLevel() === 5, `five levels, five running (${sh.wardLevel()})`);

    med.damagedLevels = 1;
    ok(sh.wardLevel() === 4, `a pip shot out and it is a four (${sh.wardLevel()})`);
    ok(!sh.canCure('virus'), 'the virus bench is gone');
    ok(sh.canCure('plague'), 'the plague bench is not — which is why you buy the upgrade early');

    /* POWER COUNTS THE SAME WAY. Dropped to ONE pip rather than two on
       purpose: `effectivePower` includes the Terra cyborg's +1, and
       `makeStartingCrew` is random, so a ward asked for two sometimes
       ran at three with a cyborg lying in it — and cured the plague.
       That is correct behaviour and it made this assertion flaky,
       which is the honest way round: the test was wrong, not the game. */
    med.damagedLevels = 0;
    med.desiredPower = 1; med.power = 1;
    sh.update(0.05);
    ok(sh.wardLevel() <= 2,
       `and power counts the same way (${sh.wardLevel()}) — five built, one running`);
    ok(!sh.canCure('plague'), 'so a dark ward treats nothing but wounds');

    man.infected = true;
    lie(sh, Ship.CURE_SECONDS * 2, man, sh.getRoomById(med.roomId));
    ok(man.infected === true, 'and a man left in it stays sick');
  }

  /* ── A DEAD WARD IS NOT A WARD ────────────────────────────── */
  {
    const { sh, med, man } = ward(5);
    med.ionDamage = 5;
    ok(sh.wardLevel() === 0, `an ionised ward is a zero (${sh.wardLevel()})`);
    ok(!sh.canCure('plague') && !sh.canCure('virus'), 'and cures nothing');
    man.virus = true;
    lie(sh, Ship.CURE_SECONDS * 2, man, sh.getRoomById(med.roomId));
    ok(man.virus === true, 'the bite runs on');
  }
})();

// ============================================================
section('263. The left column and the reactor stop fighting over the same strip');
// ============================================================
(function testLeftColumnFloor() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Game, Renderer } = sb;
  Save.load(); Save.startRun();

  /* Three things live in the same 130px strip down the left: the crew
     list, the order panel and the REACTOR COLUMN, whose pips grow
     UPWARDS out of the bottom bar. Nothing said which gives way, and
     while a card was 26px and a crew was three men they never met.
     update80 made the card 42px; update82 put seven mouths on a
     frigate to watch the air go, and the screenshot showed the order
     heading printed straight through the pips. */
  const rig = (crew, reactor) => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    while (sh.crew.filter(c => c.isPlayer).length < crew) sh.addCrew(new CrewMember({}));
    sh.reactor.level = reactor;
    Game.__test.playerShip = sh;
    return sh;
  };
  const draw = (sh) => {
    const ctx = initRenderer(sb);
    const text = captureText(ctx, () => Renderer.drawHUD({ playerShip: sh }));
    return { ctx, text: text.map(d => ({ t: String(d.t), x: d.x, y: d.y })) };
  };

  /* ── A BIG CREW AND A BIG REACTOR STILL FIT ───────────────
   * Read off the drawn rows and the drawn text, not off the
   * constants, so a layout that goes back to trailing the list fails
   * here rather than passing on a number it no longer uses. */
  {
    const sh = rig(8, 12);
    const { text } = draw(sh);
    const floor = Renderer.leftColumnFloor(sh);
    ok(floor > 120 && floor < 700, `there is a floor, and it is on screen (${floor})`);

    const rows = Renderer.getPowerClickZones().filter(z => z.crewRef);
    ok(rows.length > 0, 'crew rows are drawn');
    ok(rows.every(z => z.y + z.h <= floor),
       `every card stops above the reactor column (lowest ends ${Math.max(...rows.map(z => z.y + z.h))}, floor ${floor})`);

    // The order panel is the other half — its own last line has to
    // clear the pips too, and that line is the one the screenshot
    // caught sitting on them.
    /* update98: the specials went up to the commander bar, so the
       panel's last words are RETREAT — the button below. */
    const spec = text.find(d => /^ORDERS/.test(d.t));
    ok(!!spec, 'the order panel is drawn');
    ok(spec.y <= floor,
       `and its heading clears the reactor column (${spec.y} vs ${floor})`);
    const retreat = text.find(d => /RETREAT/.test(d.t));
    ok(retreat && retreat.y <= floor, 'so does the last button');
  }

  /* ── AND NOBODY IS SILENTLY DROPPED ───────────────────────
   * A roster that quietly ends at five is a roster the player cannot
   * trust. */
  {
    const sh = rig(9, 14);
    const { text } = draw(sh);
    const rows = Renderer.getPowerClickZones().filter(z => z.crewRef);
    /* update97: the line counts those above and below the window. */
    const more = text.find(d => /^▲\d+ ▼\d+ · WHEEL$/.test(d.t));
    const roster = sh.crew.filter(c => c.isPlayer && !c.dead).length;
    ok(rows.length < roster, `not everybody fits (${rows.length} of ${roster})`);
    ok(!!more, `and the rest are counted (${more && more.t})`);
    const m = more ? more.t.match(/▲(\d+) ▼(\d+)/) : null;
    const n = m ? +m[1] + +m[2] : -1;
    ok(rows.length + n === roster,
       `shown plus hidden is the whole crew (${rows.length} + ${n} = ${roster})`);
    ok(more.y <= Renderer.leftColumnFloor(sh), 'and the line itself is on the right side of the floor');
  }

  /* ── A SMALL CREW LOSES NOTHING ───────────────────────────
   * The clipping is a floor, not a policy: the usual case is
   * untouched, and that is what stops this from being a redesign
   * nobody asked for. */
  {
    const sh = rig(4, 8);
    const { text } = draw(sh);
    const rows = Renderer.getPowerClickZones().filter(z => z.crewRef);
    const roster = sh.crew.filter(c => c.isPlayer && !c.dead).length;
    ok(rows.length === roster, `all four are shown (${rows.length} of ${roster})`);
    ok(!text.some(d => /WHEEL$/.test(d.t)), 'and nothing says anybody is missing');
  }

  /* ── THE FLOOR FOLLOWS THE REACTOR ────────────────────────
   * A bigger reactor is a taller column of pips, so the room above it
   * shrinks. The two are computed from the same arithmetic on purpose:
   * one of them moving without the other is how they collided. */
  {
    const small = rig(3, 6);
    const big   = rig(3, 16);
    // the old row layouts: the reactor column climbs (kept behind the switch)
    Renderer.setReactorLayout('column');
    ok(Renderer.leftColumnFloor(big) < Renderer.leftColumnFloor(small),
       `a taller reactor pushes the floor up (${Renderer.leftColumnFloor(big)} vs ${Renderer.leftColumnFloor(small)})`);
    // the systems panel (update134) has one height whatever the core
    Renderer.setReactorLayout('S');
    Renderer.drawHUD({ playerShip: big });
    const P = Renderer.sysPanelRect();
    ok(P && Renderer.leftColumnFloor(big) === Renderer.leftColumnFloor(small) && Renderer.leftColumnFloor(big) <= P.y - 8,
       `in the systems panel the floor sits above the panel, for any core (${Renderer.leftColumnFloor(big)} vs panel ${P && P.y})`);
  }
})();

// ============================================================
section('264. The cat takes an order, and a cat is not a crewman');
// ============================================================
(function testCatOrders() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Game, HUNGER, TASK } = sb;
  Save.load(); Save.startRun();

  const rig = () => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const cat = sb.makeCat('black', 'Mruk');
    sh.addCrew(cat);
    sh.cargo.items.length = 0;
    sh.crew.forEach(c => { c.hunger = 100; });
    cat.hunger = 60;    /* update90b: a FED cat does not hunt; this one has room for a rat. */
    /* THE CREW GO OUT OF THE WAY so a room click resolves to the ROOM
       and not to a sprite under the cursor — but NOT the cat. She has
       to walk, and a cat parked at -9999 is a hundred and seventy
       seconds from anywhere at sixty pixels a second: the first
       version of this rig moved her too and every "she walks there"
       failed on the clock rather than on the rule. */
    sh.crew.forEach(c => { if (!c.isPet) { c.x = -9999; c.y = -9999; } });
    const home = sh.rooms[0];
    cat.roomId = home.id; cat.inRoom = true;
    cat.x = home.cx; cat.y = sh.floorWalkY(home.floor, home.cy);
    const T = Game.__test;
    T.playerShip = sh;
    T.enemyShip = null;
    T.STATE = 'combat';
    return { sh, cat, T };
  };
  const order = (T, sh, cat, room) => {
    sb.UI.selectCrewGroup([cat]);
    /* Up in the corner of the room, not its middle (update120): the crew
       stand lower now, and the middle of the room at cy is where a cat
       already in it is standing — the click picked HER up instead. */
    T._crewClickResolve(room.x + 10, room.floorTop + 8, false);
  };
  const walk = (sh, n = 400) => { for (let i = 0; i < n; i++) sh.update(0.05); };

  /* ── THE ORDER STICKS ─────────────────────────────────────
   *
   * `_ordered` has been read in `petTick` since update45 and NOTHING
   * EVER WROTE IT, so the branch was dead: the cat took the order and
   * abandoned it the moment the roam timer ran out. The player:
   * "kot chodzi tam gdzie mu sie pokazuje, nastepnie po chwili chodzi
   * gdzie chce".
   */
  {
    const { sh, cat, T } = rig();
    const room = sh.rooms[sh.rooms.length - 1];
    ok(cat.roomId !== room.id, 'she starts somewhere else');
    order(T, sh, cat, room);
    ok(cat._ordered === true, 'the click marks it as an ORDER, not a stroll');
    walk(sh, 200);
    ok(cat.roomId === room.id, `she walks there (${cat.roomId} vs ${room.id})`);

    /* AND STAYS. The roam timer is 3-9 seconds and fires many times
       over the next minute; before this package every one of them was
       a chance to wander off. */
    walk(sh, 1200);           // a full minute
    ok(cat.roomId === room.id,
       `and is still there a minute later (${cat.roomId} vs ${room.id})`);
    ok(cat._ordered === true, 'the order is still on her');
  }

  /* ── A RAT BREAKS IT — that is what she is FOR ────────────── */
  {
    const { sh, cat, T } = rig();
    const post = sh.rooms[sh.rooms.length - 1];
    order(T, sh, cat, post);
    walk(sh, 200);
    ok(cat.roomId === post.id, 'she is at her post');

    const far = sh.rooms.find(r => r.id !== post.id);
    const rat = sh.addPest(new sb.Pest({ kind: 'rat', roomId: far.id, x: far.cx }));
    rat._moveT = 1e9;
    ok(sh.pests.includes(rat), 'a rat in the duct over another room');
    walk(sh, 300);
    ok(cat._ordered === false, 'the order is released, not merely suspended');
    ok(cat.roomId === far.id || cat._waypoints?.length,
       `and she goes hunting (${cat.roomId} vs ${far.id})`);
  }

  /* ── AND A RAT DIVERTS HER MID-WALK ───────────────────────
   *
   * There used to be a line making the order absolute until she
   * arrived. The breaking run could not break it — with nothing
   * outranking the order the next test returns anyway — so the only
   * thing it ever changed was this case, and marching her into an
   * empty room to turn round there is not better behaviour. The line
   * is gone; this is what replaced it.
   */
  {
    const { sh, cat, T } = rig();
    const post = sh.rooms[sh.rooms.length - 1];
    order(T, sh, cat, post);
    walk(sh, 4);                       // barely off the mark
    ok(cat.roomId !== post.id, 'she is still crossing the ship');
    ok(cat._ordered === true, 'and under orders');

    const far = sh.rooms.find(r => r.id !== post.id && r.id !== cat.roomId);
    sh.addPest(new sb.Pest({ kind: 'rat', roomId: far.id, x: far.cx }))._moveT = 1e9;
    sh.update(0.05);
    ok(cat._ordered === false,
       'a rat takes her off the order without waiting for her to arrive');
  }

  /* ── AND A MAN ON THE FLOOR BREAKS IT ─────────────────────
   * The vigil slows his bleed-out (update45), so this is not
   * sentiment — it is a mechanic she is the only one who has. */
  {
    const { sh, cat, T } = rig();
    const post = sh.rooms[sh.rooms.length - 1];
    order(T, sh, cat, post);
    walk(sh, 200);
    ok(cat.roomId === post.id, 'she is at her post');

    const far = sh.rooms.find(r => r.id !== post.id);
    const man = sh.crew.find(c => c.isPlayer && !c.isPet);
    man.roomId = far.id; man.x = far.cx; man.y = far.cy; man.inRoom = true;
    man.hp = 3; man.state = 'injured';
    ok(man.down === true, 'somebody is on the floor');
    walk(sh, 300);
    ok(cat._ordered === false, 'the order lets go');
    ok(cat.roomId === far.id || cat._waypoints?.length,
       `and she sits with him (${cat.roomId} vs ${far.id})`);
  }

  /* ── HER OWN HUNGER BREAKS IT TOO ─────────────────────────
   * An order that starves the cat is not an order the player thinks
   * he is giving. */
  {
    const { sh, cat, T } = rig();
    const post = sh.rooms[sh.rooms.length - 1];
    sh.cargo.add('ration_pack');
    order(T, sh, cat, post);
    walk(sh, 200);
    ok(cat.roomId === post.id, 'she is at her post');
    const food0 = sh.cargo.countOf('food');
    cat.hunger = HUNGER.HUNGRY - 5;
    walk(sh, 200);
    ok(cat._ordered === false, 'hunger lets her off the post');
    ok(sh.cargo.countOf('food') === food0 - 1,
       `and she eats (${sh.cargo.countOf('food')} of ${food0})`);
  }

  /* ── A CAT IS NOT ONE OF YOUR THREE ───────────────────────
   *
   * `roomSpaceFor` counted every living body on the side, so the
   * ship's cat sitting in the engine room cost you a mechanic —
   * while `takenStationSlots`, the other half of the same question,
   * has excluded animals since update43.
   */
  {
    const { sh, cat } = rig();
    const room = sh.rooms[0];
    sh.crew.forEach(c => { c.roomId = 'elsewhere'; c.homeRoomId = 'elsewhere'; });
    ok(sh.roomSpaceFor(room.id, true) === Ship.ROOM_SLOTS, 'an empty module is empty');
    cat.roomId = room.id; cat.homeRoomId = room.id;
    ok(sh.roomSpaceFor(room.id, true) === Ship.ROOM_SLOTS,
       `and the cat does not take one of the ${Ship.ROOM_SLOTS} (${sh.roomSpaceFor(room.id, true)})`);
    ok(sh.takenStationSlots(room, [], false, true).size === 0,
       'she holds no standing spot either — the two halves agree now');

    const man = sh.crew.find(c => c.isPlayer && !c.isPet);
    man.roomId = room.id; man.homeRoomId = room.id;
    ok(sh.roomSpaceFor(room.id, true) === Ship.ROOM_SLOTS - 1,
       'a man still does');
  }

  /* ── AND SHE IS NOT GIVEN A TRADE ─────────────────────────
   *
   * Measured before this package: a cat alone in a damaged engine
   * room pushed the repair meter from 0 to 0.43 in three seconds.
   * The room click handed her `TASK.REPAIR` exactly like a mechanic.
   */
  {
    const { sh, cat, T } = rig();
    const sys = sh.getSystem('engines');
    const room = sh.getRoomById(sys.roomId);
    sys.damageLevel(1);
    ok(sys.damagedLevels > 0, 'the engines are shot up');
    order(T, sh, cat, room);
    ok(cat.task !== TASK.REPAIR, `she is given no repair order (${cat.task})`);
    /* `addCrew` gives every body a default station, so the claim is not
       "she has no posting" — it is that the CLICK did not give her one.
       A cat at a post would be pulled back to it by the idle walk the
       moment she was released, which is a second kind of standing
       order nobody asked for. */
    ok(cat.homeRoomId !== room.id,
       `and the click did not post her there (${cat.homeRoomId} vs ${room.id})`);
    walk(sh, 200);
    ok(cat.roomId === room.id, `she goes, because she was told to (${cat.roomId} at ${Math.round(cat.x)},${Math.round(cat.y)}; wanted ${room.id}; ordered ${cat._ordered}, task ${cat.task}, wp ${cat._waypoints?.length ?? 0}, state ${cat.state})`);
    const p0 = sys.repairProgress;
    sh.crew.forEach(c => { if (!c.isPet) { c.roomId = 'far'; c.x = -9999; c.y = -9999; } });
    for (let i = 0; i < 100; i++) sh.update(0.05);
    ok(sys.repairProgress === p0,
       `and the engines are no better for it (${sys.repairProgress} of ${p0})`);
  }
})();

// ============================================================
section('265. What lives in the ducts: rats and spiders are not crew');
// ============================================================
(function testPestsInTheDucts() {
  const sb = loadEngine();
  const { Ship, CrewMember, Pest, Save, Base, Game, PEST_TUNING, CargoGrid } = sb;
  Save.load(); Save.startRun();
  const T = Game.__test;

  const bare = () => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    return sh;
  };
  const stand = (sh, c, room) => {
    c.roomId = room.id; c.inRoom = true;
    c.x = room.cx; c.y = sh.floorWalkY(room.floor, room.cy);
  };
  const R = (sh, id) => sh.getRoomById(id);

  /* ── AN OLD SAVE: RATS IN THE CREW LIST ───────────────────
   *
   * Every save before update84 wrote its rats and spiders as crew
   * records. Through `_continueRun` — the road a reload takes, not
   * `fromCrewRecord` called by hand — they must come back as pests in
   * the duct of the room they stood in: not as crewmen (there is no such
   * crewman), and not dropped (a reload would be a free fumigation).
   */
  {
    Save.startRun();
    Save.updateRun({ mission: 'courier', finalSector: sb.MISSIONS.courier.sectors,
                     sector: 1, lane: 1, seed: 4242 });
    const hull = bare();
    const man = new CrewMember({ name: 'Keeper' });
    hull.addCrew(man);
    const recs = [
      man.serialise(),
      { race: 'rat',    name: 'Moon Rat',    roomId: 'r_shields', x: 322, hp: 11, maxHp: 18 },
      { race: 'spider', name: 'Void Spider', roomId: 'r_medbay',  x: 330, hp: 45, maxHp: 45 },
      { race: 'rat',    name: 'Moon Rat',    roomId: 'r_engines', x: 70,  hp: 0,  maxHp: 18, state: 'dead' },
    ];
    Save.updateRun({ ship: hull.serialise(), crew: recs });
    T._continueRun();
    const sh = T.playerShip;
    ok(sh.crew.length === 1 && sh.crew[0].name === 'Keeper',
       `only the man comes back as crew (${sh.crew.map(c => c.name).join(',')})`);
    const rat = sh.pests.find(p => p.isRat), sp = sh.pests.find(p => p.isSpider);
    ok(sh.pests.length === 2 && rat && sp,
       `the living rat and spider come back as pests (${sh.pests.length}), the dead one does not`);
    ok(rat && rat.roomId === 'r_shields' && rat.x === 322 && rat.hp === 11,
       'in the duct over the room it stood in, as hurt as it was');
    const cap = sb.PEST_DEFS.spider.hp + sb.PEST_DEFS.spider.hpPerTough * 3;
    ok(sp && sp.maxHp === cap && sp.hp === cap && cap < 45,
       `a crewman-sized spider is cut down to a duct spider (45 → ${sp && sp.maxHp})`);
  }

  /* ── A PEST RIDES IN THE SHIP'S OWN SAVE ──────────────────── */
  {
    const sh = bare();
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: 'r_shields', x: 300, hp: 7 }));
    const sac = sh.addPest(new Pest({ kind: 'spider', roomId: 'r_crew3', x: 290,
                                      dormant: true, hatchT: 12, tough: 2 }));
    const gone = sh.addPest(new Pest({ kind: 'rat', roomId: 'r_engines', x: 60 }));
    gone.takeDamage(999, 'test');
    const back = Ship.deserialise(JSON.parse(JSON.stringify(sh.serialise())), true, 0, 0);
    ok(back.pests.length === 2, `the dead one is not written (${back.pests.length})`);
    const r2 = back.pests.find(p => p.isRat), s2 = back.pests.find(p => p.isSpider);
    ok(r2 && r2.roomId === 'r_shields' && r2.x === 300 && r2.hp === 7 && r2.id === rat.id,
       'the rat is where it was, as hurt as it was');
    ok(s2 && s2.dormant && !s2.revealed && s2.hatchT === 12 && s2.tough === 2,
       'an unhatched sac stays an unseen, unhatched sac of the same strength');
    ok(!back.crew.some(c => c && (c.race === 'rat' || c.race === 'spider')),
       'and nothing turns up in the crew list');
  }

  /* ── NOBODY IN THE ROOM CAN HIT IT, AND A RAT HITS NOBODY ──
   *
   * The whole package in one check: an armed man standing under a rat
   * for ten seconds of the real ship tick does not fight — there is
   * nobody in his room to fight — and neither of them is hurt.
   */
  {
    const sh = bare();
    const man = new CrewMember({ name: 'Idle' });
    sh.addCrew(man);
    const room = R(sh, 'r_weapons');
    stand(sh, man, room);
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: room.id, x: room.cx }));
    rat._moveT = 1e9;
    const hp0 = man.hp;
    for (let i = 0; i < 100; i++) sh.update(0.1);
    ok(rat.alive && rat.hp === rat.maxHp, 'the crew cannot touch a rat in the duct');
    ok(man.hp === hp0, 'and a rat never touches the crew');
  }

  /* ── FIRE IN THE MODULE REACHES THE DUCT ──────────────────
   * The one thing besides the cat that kills a spider — through the
   * ship's own update, with the fire started the way a hit starts one. */
  {
    const sh = bare();
    const hot = R(sh, 'r_crew3'), cold = R(sh, 'r_engines');
    const burning = sh.addPest(new Pest({ kind: 'spider', roomId: hot.id,  x: hot.cx }));
    const safe    = sh.addPest(new Pest({ kind: 'spider', roomId: cold.id, x: cold.cx }));
    burning._moveT = safe._moveT = 1e9;
    sh.fires.start(hot.id, hot.cx, hot.cy);
    ok(sh.fires.hasFireInRoom(hot.id), 'the module is on fire');
    for (let i = 0; i < 300 && !burning.dead; i++) sh.update(0.1);
    ok(burning.dead && burning.killedBy === 'fire', `the spider over it burns (${burning.killedBy})`);
    ok(!sh.pests.includes(burning), 'and leaves the list');
    ok(safe.alive && safe.hp === safe.maxHp, 'a spider three decks away is untouched');
  }

  /* ── ALONG THE DUCT NETWORK, AND ONLY THAT ────────────────
   * Watched through pestTick for ten minutes: every change of room is a
   * step along `ductLinks` — beside it on its deck, or (since update86a)
   * one deck up or down the lift shaft. */
  {
    const sh = bare();
    const start = R(sh, 'r_weapons');
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: start.id, x: start.cx }));
    const seen = new Set([start.id]);
    let last = start.id, bad = 0, moves = 0;
    for (let i = 0; i < 6000; i++) {
      sh.pestTick(0.1);
      if (rat.roomId !== last) {
        moves++;
        if (!sh.ductLinks(last).some(l => l.room.id === rat.roomId)) bad++;
        last = rat.roomId; seen.add(last);
      }
      const r = R(sh, rat.roomId);
      if (!rat._climb && (rat.x < r.x || rat.x > r.x + r.w)) bad++;
    }
    ok(moves > 5, `it gets about (${moves} moves)`);
    ok(bad === 0, `never through a wall and never outside its duct (${bad} bad)`);
    /* A random walk, so not "every duct" — that failed one run in a few
       at 8 of 9. What must hold is that it gets around, decks included. */
    const decks = new Set([...seen].map(id => R(sh, id).floor));
    ok(seen.size >= 5 && decks.size >= 2,
       `and in ten minutes it gets around the hull, decks included (${seen.size} ducts, ${decks.size} decks)`);
  }

  /* ── A SPIDER GOES WHERE THE PEOPLE ARE ───────────────────
   * Over a room with nobody in it, with a man next door on one side,
   * it takes that side — every time, not one time in two. */
  {
    let toMan = 0;
    for (let k = 0; k < 20; k++) {
      const sh = bare();
      const man = new CrewMember({ name: 'Bait' });
      sh.addCrew(man);
      stand(sh, man, R(sh, 'r_shields'));
      const sp = sh.addPest(new Pest({ kind: 'spider', roomId: 'r_weapons', x: R(sh, 'r_weapons').cx }));
      sp._moveT = 0;
      sh.pestTick(0.01);
      if (sp._via === 'r_shields') toMan++;
    }
    ok(toMan === 20, `it heads for the man next door (${toMan}/20)`);
  }

  /* ── AND ONCE IT IS OVER THEM, IT STAYS ───────────────────
   * The move clock must not carry it off before the drop clock fires:
   * a minute over a man, with the move clock expiring every tick. */
  {
    const sh = bare();
    const man = new CrewMember({ name: 'Target' });
    sh.addCrew(man);
    const room = R(sh, 'r_weapons');
    stand(sh, man, room);
    const sp = sh.addPest(new Pest({ kind: 'spider', roomId: room.id, x: room.cx }));
    let left = false;
    for (let i = 0; i < 600; i++) {
      sp._moveT = 0; sp._pounceT = 1e9;
      sh.pestTick(0.1);
      if (sp.roomId !== room.id || sp._via) left = true;
    }
    ok(!left, 'a spider with a man under it does not wander off');
  }

  /* ── THE CAT GOES UP AFTER A SPIDER, AND IT BITES BACK ────
   * A tough one: while she has it, it neither crawls off nor drops on
   * the man in the room; it bites HER; and a cat that loses comes back
   * down dead, and lets go of it. */
  {
    const sh = bare();
    const room = R(sh, 'r_oxygen');
    const man = new CrewMember({ name: 'Under' });
    sh.addCrew(man);
    stand(sh, man, room);
    const cat = sb.makeCat('ginger', 'Ruda');
    sh.addCrew(cat);
    stand(sh, cat, room);
    cat.hunger = 60;    // update90b: hungry enough to go up, not hungry enough to go and eat
    const sp = sh.addPest(new Pest({ kind: 'spider', roomId: room.id, x: room.cx + 20, tough: 3 }));
    sp._moveT = 0; sp._pounceT = 0;
    const manHp = man.hp, catHp = cat.hp;
    let held = false, moved = false, dropped = false;
    for (let i = 0; i < 30; i++) {
      sh.update(0.1);
      if (sp._catId === cat.id) held = true;
      if (sp.roomId !== room.id || sp._via) moved = true;
      if (sp.pouncing) dropped = true;
    }
    ok(held && cat._ductY != null, 'she is up in the duct with it');
    ok(!moved, 'a held spider does not crawl off');
    ok(!dropped && man.hp === manHp, 'and does not drop on the man below while she has it');
    ok(cat.hp < catHp, `it bites her back (${catHp} → ${cat.hp})`);

    cat.hp = 1;
    for (let i = 0; i < 60 && cat.alive; i++) sh.update(0.1);
    ok(!cat.alive, 'a cat can lose to a spider');
    ok(sp.alive && sp._catId == null && cat._ductY == null,
       'and a dead cat is not holding anything');
  }

  /* ── A HELD RAT STAYS HELD ────────────────────────────────── */
  {
    const sh = bare();
    const room = R(sh, 'r_weapons');
    const cat = sb.makeCat('black', 'Mruk');
    sh.addCrew(cat);
    stand(sh, cat, room);
    cat.hunger = 60;    /* update90b: a FED cat does not hunt; this one has room for a rat. */
    cat.attackTimer.tick = () => false;        // she holds it but does not land a blow
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: room.id, x: room.cx }));
    rat._moveT = 0;
    const x0 = rat.x;
    for (let i = 0; i < 100; i++) sh.update(0.1);
    ok(rat._catId === cat.id && rat.roomId === room.id && rat.x === x0,
       'a rat the cat has hold of goes nowhere');
  }

  /* ── A SAC IS FOUND BY WALKING IN, OR SMELT BY THE CAT ──── */
  {
    const sh = bare();
    const man = new CrewMember({ name: 'Walker' });
    sh.addCrew(man);
    stand(sh, man, R(sh, 'r_piloting'));
    const sacA = sh.addPest(new Pest({ kind: 'spider', roomId: 'r_crew1',   x: 70,  dormant: true, hatchT: 100 }));
    const sacB = sh.addPest(new Pest({ kind: 'spider', roomId: 'r_shields', x: 330, dormant: true, hatchT: 100 }));
    const sacC = sh.addPest(new Pest({ kind: 'spider', roomId: 'r_crew3',   x: 330, dormant: true, hatchT: 100 }));
    sh.pestTick(1);
    ok(!sacA.revealed && !sacB.revealed && !sacC.revealed, 'nobody has been near them: unseen');
    ok(sacA.hatchT === 99, 'and they tick at the plain rate');

    stand(sh, man, R(sh, 'r_crew1'));
    const cat = sb.makeCat('black', 'Nos');
    sh.addCrew(cat);
    stand(sh, cat, R(sh, 'r_weapons'));          // next door to r_shields
    sh.pestTick(1);
    ok(sacA.revealed && !sacA.sensedByCat, 'the one a man walked in on is seen');
    ok(sacA.hatchT === 99 - 6, `and he sets it off six times faster (${sacA.hatchT})`);
    ok(sacB.revealed && sacB.sensedByCat, 'the cat smells the one through the bulkhead');
    ok(sacB.hatchT === 98, 'without hurrying it along');
    ok(!sacC.revealed, 'and the one nobody is near stays hidden');
  }

  /* ── A SPIDER DROPS ON PEOPLE, NOT ON THE CAT ─────────────
   * A cat trotting through under a spider is not something it drops on
   * (she would carry the virus off a bite). Walking, she is not holding
   * it either, so this is the drop rule on its own. */
  {
    const sh = bare();
    const room = R(sh, 'r_shields');
    const cat = sb.makeCat('black', 'Przechodzi');
    sh.addCrew(cat);
    stand(sh, cat, room);
    const sp = sh.addPest(new Pest({ kind: 'spider', roomId: room.id, x: room.cx }));
    sp._moveT = 1e9;
    let drops = 0;
    for (let i = 0; i < 50; i++) {
      cat._waypoints = [{ x: 0, y: cat.y }];     // on her way somewhere
      sp._pounceT = 0;
      sh.pestTick(0.1);
      if (sp.pouncing) drops++;
    }
    ok(sp._catId == null, 'a cat on the move is not holding it');
    ok(drops === 0, `and it never drops on her (${drops})`);
  }

  /* ── WHAT IS LEFT TO SEARCH IS ON THE HULL ─────────────────
   * The hold opens when every compartment has had somebody in it, so the
   * compartments nobody has been into are marked — and stop being marked
   * the moment a man stands in one. (Rooms on different decks share a
   * cx, so a mark is identified by x AND y.) */
  {
    const hulk = new Ship('frigate', false, 0, 0);
    hulk.isDerelict = true;
    const man = new CrewMember({ name: 'Boarder' });
    hulk.addCrew(man, true);
    stand(hulk, man, R(hulk, 'r_engines'));
    const marks = () => {
      const out = [];
      const ctx = sb.makeStubCtx ? sb.makeStubCtx() : null;
      const c2 = ctx || new Proxy({}, { get: (t, k) => (k in t ? t[k] : () => {}), set: (t, k, v) => { t[k] = v; return true; } });
      c2.fillText = (t, x, y) => { if (t === 'UNSEARCHED') out.push(`${x},${y}`); };
      hulk._drawSearch(c2);
      return out;
    };
    ok(marks().length === hulk.rooms.length, 'before anybody moves every compartment is marked');
    hulk.searchTick();
    const m = marks();
    const eng = R(hulk, 'r_engines');
    ok(m.length === hulk.rooms.length - 1 &&
       !m.includes(`${eng.cx},${eng.floorTop + eng.floorH - 4}`),
       'the one he is standing in is not');
    ok(!hulk.searchedAll(), 'and the hold is not open yet');
    hulk.rooms.forEach(r => { stand(hulk, man, r); hulk.update(0.05); });
    ok(hulk.searchedAll() && marks().length === 0, 'walk him through the rest and it is');
  }

  /* ── THE RATS STAY ON HER (update86b) ─────────────────────
   * update84 had the yard fumigate; the player wants the opposite: the
   * pests stay on that hull, in the hangar, and are there again on the
   * next contract. Through the real roads: launch, dock, launch again. */
  {
    Save.load(); Save.startRun();
    const { BaseScreen } = sb;
    Base.earn(1000);
    BaseScreen.open();
    launchNow(BaseScreen);
    T._startContract(BaseScreen.consumeLaunch());
    const hull = T.playerShip;
    ok(!!hull, 'a contract is under way');
    const room0 = hull.rooms[0], room1 = hull.rooms[1];
    hull.addPest(new Pest({ kind: 'rat', roomId: room0.id, x: room0.cx, level: 3, fullness: 40 }));
    hull.addPest(new Pest({ kind: 'spider', roomId: room1.id, x: room1.cx }));
    const key = Save.getRun()?.shipKey;
    T._dockAtBase(0);
    const berth = Base.ships().find(e => e.key === key) || Base.ships()[Base.ships().length - 1];
    ok(berth && (berth.data.pests ?? []).length === 2,
       `the hull in the hangar still has them (${(berth?.data?.pests ?? []).length})`);

    Save.startRun();
    BaseScreen.open();
    launchNow(BaseScreen);
    T._startContract(BaseScreen.consumeLaunch());
    const again = T.playerShip.pests;
    const r = again.find(p => p.isRat);
    ok(again.length === 2 && r && r.level === 3 && r.fullness === 40,
       `and they come out with her on the next contract (${again.length}, rat lvl ${r?.level})`);
  }
})();

// ============================================================
section('266. The duct has its own air, and fire goes through it');
// ============================================================
(function testDuctAirAndFire() {
  const sb = loadEngine();
  const { Ship, CrewMember, Pest, Save, OXYGEN, FIRE_DEFS } = sb;
  Save.load(); Save.startRun();

  const hull = (o2 = true) => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const sys = sh.getSystem('oxygen');
    if (!o2 && sys) { sys.desiredPower = 0; sys.power = 0; }
    if (sh.doors) sh.doors.forEach(d => { d.mode = 'closed'; d.open = false; d.openness = 0; d._tempT = 0; });
    return sh;
  };
  const airlockOf = (sh, id) => sh.doors.find(d => d.isAirlock && d.roomA === id);
  const stub = () => new Proxy({}, {
    get: (t, k) => (k in t ? t[k] : () => ({ addColorStop() {}, width: 10 })),
    set: (t, k, v) => { t[k] = v; return true; },
  });
  /* The WHOLE hull is drawn, through Ship.draw — a test that called the
     duct painter by hand would stay green with the call to it deleted.
     The asset loader complains about every missing sprite; quiet it. */
  const drawHull = (sh, ctx) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { sh.draw(ctx); } finally { console.log = log; console.warn = warn; }
  };

  /* ── A HOLE EMPTIES THE ROOM FIRST, THEN THE DUCT ─────────
   * The player's rule (29.09). Through Ship.update with a real airlock
   * held open: the room is at zero while its duct still has air, and a
   * rat up there is alive until the duct goes too. */
  {
    const sh = hull();
    const id = 'r_engines';
    const ro = sh.oxygen.getRoom(id);
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: id, x: sh.getRoomById(id).cx }));
    rat._moveT = 1e9;
    const lock = airlockOf(sh, id);
    ok(!!lock, 'the engine room has an airlock');
    let roomEmptyAt = null, ductEmptyAt = null, ratDeadAt = null, t = 0;
    let ductWhenRoomEmpty = null;
    for (let i = 0; i < 600 && !(ratDeadAt != null); i++) {
      lock.mode = 'open';               // the player's click: the panel cycles open
      sh.update(0.05); t += 0.05;
      if (roomEmptyAt == null && ro.level <= OXYGEN.ROOM_EMPTY) { roomEmptyAt = t; ductWhenRoomEmpty = ro.duct; }
      if (ductEmptyAt == null && ro.duct <= 0) ductEmptyAt = t;
      if (ratDeadAt == null && rat.dead) ratDeadAt = t;
    }
    ok(roomEmptyAt != null && ductWhenRoomEmpty > 0.9,
       `the room is empty while its duct is still full (${ductWhenRoomEmpty?.toFixed(2)} at ${roomEmptyAt?.toFixed(1)}s)`);
    ok(ductEmptyAt != null && ductEmptyAt > roomEmptyAt,
       `the duct goes after it (${ductEmptyAt?.toFixed(1)}s)`);
    ok(ratDeadAt != null && ratDeadAt >= ductEmptyAt,
       `and the rat dies only once the duct is dry (${ratDeadAt?.toFixed(1)}s)`);
  }

  /* ── …AND A FIRE IN THAT ROOM IS OUT BEFORE THE RATS ARE ── */
  {
    const sh = hull();
    const id = 'r_engines';
    const room = sh.getRoomById(id);
    const ro = sh.oxygen.getRoom(id);
    // Nobody aboard to fight it: the only thing that can put it out is the air.
    sh.crew.forEach(c => { c.x = -9999; c.roomId = null; c.inRoom = false; });
    sh.fires.start(id, room.cx, room.cy);
    const lock = airlockOf(sh, id);
    let outWithDuct = null, roomAtOut = null;
    for (let i = 0; i < 400 && outWithDuct == null; i++) {
      lock.mode = 'open';               // the player's click: the panel cycles open
      sh.update(0.05);
      if (!sh.fires.hasFireInRoom(id)) { outWithDuct = ro.duct; roomAtOut = ro.level; }
    }
    ok(roomAtOut != null && roomAtOut < FIRE_DEFS.DUCT_MIN_AIR,
       `the fire is put out by the vacuum (room at ${roomAtOut?.toFixed(2)})`);
    /* update90: the duct over a hole is the vent network's way out now
       and bleeds at 1.5/s instead of 0.6, so "still has air" is a third
       of a duct rather than half — the order is what this checks. */
    ok(outWithDuct != null && outWithDuct > 0.25,
       `and while the duct still has air (${outWithDuct?.toFixed(2)})`);
  }

  /* ── TOO LITTLE AIR: THE ROOMS GO SHORT FIRST ─────────────
   * The player's correction after playing 85 (update86b): the module
   * running but short for the mouths aboard is short in the ROOMS; the
   * duct, where the pipes are, stays full. Through Ship.update with a
   * crowd on one pip. */
  {
    const sh = hull();
    const sys = sh.getSystem('oxygen');
    sys.desiredPower = 1; sys.power = 1;
    for (let i = 0; i < 6; i++) sh.addCrew(new CrewMember({}));
    /* They must LIVE to keep breathing (update90). With the vent network
       the ducts run dry more slowly, and the crowd could suffocate first:
       then one pip out-made what was left of them, the pumps topped the
       ducts back up to full, and whether that happened depended on how
       busy the machine was. The deficit is the premise; keep it. */
    sh.crew.forEach(c => { c.hp = c.maxHp = 1e9; });
    const rooms = sh.rooms.map(r => sh.oxygen.getRoom(r.id));
    // Nine mouths on one pip: run until the rooms are half gone.
    for (let i = 0; i < 2000 && !rooms.some(r => r.level < 0.5); i++) sh.update(0.05);
    ok(rooms.some(r => r.level < 0.5), `the rooms are thinning (${Math.min(...rooms.map(r => r.level)).toFixed(2)})`);
    ok(rooms.every(r => r.duct > 0.99), 'while every duct is still full');
    // …and once the rooms are dry, the ducts go too: it is not a refuge.
    /* update90: the lift shafts' air is drawn into the ducts on them, and
       the network empties a duct ever more slowly — "dry" is below
       ROOM_EMPTY, the same line the rat and the man breathe by. */
    for (let i = 0; i < 4000 && rooms.some(r => r.duct > OXYGEN.ROOM_EMPTY); i++) sh.update(0.05);
    ok(rooms.every(r => r.duct <= OXYGEN.ROOM_EMPTY), `until the rooms are dry, and then the ducts follow (max ${Math.max(...rooms.map(r => r.duct)).toFixed(4)})`);
  }

  /* ── NO AIR AT ALL: ROOM AND DUCT TOGETHER ────────────────
   * The module off: nothing flows, both go down evenly — and a rat up
   * there and a man below run out at the same time. The rat holds a
   * normal suit's breath; the man loses hide as it does, so killing the
   * rats this way COSTS the crew, unless somebody patches them up. */
  {
    const sh = hull(false);
    const id = 'r_weapons';
    const room = sh.getRoomById(id);
    const ro = sh.oxygen.getRoom(id);
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: id, x: room.cx, level: 3 }));
    rat._moveT = 1e9;
    // Nobody walking about: a man through a door evens the ROOMS out and
    // not the ducts, which is a different question from this one.
    sh.crew.length = 0;
    const m = new CrewMember({ name: 'Down Here', race: 'aquarius' });
    sh.addCrew(m);
    m.roomId = id; m.inRoom = true; m.x = room.cx; m.y = sh.floorWalkY(room.floor, room.cy);
    let maxGap = 0;
    for (let i = 0; i < 400; i++) { sh.update(0.05); maxGap = Math.max(maxGap, Math.abs(ro.level - ro.duct)); }
    /* update90: a few hundredths, not none — the lift shaft's own air is
       drawn into the ducts on it (the network), which holds those a hair
       above the room below. Together still means together. */
    ok(maxGap < 0.04, `room and duct go down together (${maxGap.toFixed(3)} apart at most)`);
    /* …and the ship loses exactly what is breathed, no more: the duct
       is a third of a room's volume, and an even drop must count it at
       that. Summed over the hull, in room units, over one second. */
    {
      const T3 = OXYGEN.DUCT_THIN;
      /* EVERY cell aboard (update90): the lift shafts' air is on the vent
         network now, so counting the rooms alone saw shaft air arriving
         and called it a smaller loss. */
      const total = () => [...sh.oxygen._rooms.values()].reduce((a, o) =>
        a + o.level + (o.duct != null ? o.duct / T3 : 0), 0);
      const mouths = sh.crew.reduce((a, c) => a + (c.alive ? c.breathPerSec() : 0), 0)
                   + sh.pests.reduce((a, q) => a + q.breathPerSec(), 0);
      const before = total();
      for (let i = 0; i < 20; i++) sh.oxygen.update(0.05, sh);
      const lost = before - total();
      ok(Math.abs(lost - mouths) < mouths * 0.02,
         `a second costs the hull exactly what is breathed (${lost.toFixed(4)} vs ${mouths.toFixed(4)})`);
    }
    let t = 0;
    for (let i = 0; i < 20000 && !rat.dead; i++) { sh.update(0.05); t += 0.05; }
    ok(rat.dead, `the rat suffocates in the end (${t.toFixed(0)}s after that)`);
    ok(m.hp < m.maxHp, `and so does the man below start to — ${m.hp.toFixed(0)}/${m.maxHp} hp`);
  }

  /* ── A RAT HOLDS ITS BREATH ───────────────────────────────── */
  {
    const sh = hull();
    const ro = sh.oxygen.getRoom('r_weapons');
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: 'r_weapons', x: 200, level: 3 }));
    rat._moveT = 1e9;
    const RT = sb.RAT_TUNING;
    for (let i = 0; i < Math.round((RT.AIR_SECONDS - 1) / 0.05); i++) { ro.level = 0; ro.duct = 0; sh.pestTick(0.05); }
    ok(rat.hp === rat.maxHp, `for ${RT.AIR_SECONDS - 1}s with no air it is unhurt`);
    for (let i = 0; i < 60; i++) { ro.level = 0; ro.duct = 0; sh.pestTick(0.05); }
    ok(rat.hp < rat.maxHp, 'then its breath runs out and it starts to die');
    ro.level = 1; ro.duct = 1;
    for (let i = 0; i < 100; i++) sh.pestTick(0.05);
    ok(rat.air === RT.AIR_SECONDS, 'and with air back, it gets its breath back');
    // It breathes the DUCT: an empty room under a full duct costs it nothing.
    for (let i = 0; i < 400; i++) { ro.level = 0; ro.duct = 1; sh.pestTick(0.05); }
    ok(rat.air === RT.AIR_SECONDS, 'an empty room under a full duct does not touch its breath');
  }

  /* ── A SURPLUS FILLS THE DUCT FIRST ─────────────────────── */
  {
    const sh = hull();
    sh.crew.length = 0;
    const ro = sh.oxygen.getRoom('r_weapons');
    ro.level = 0.5; ro.duct = 0;
    /* The PIPES' order, on its own (update90): with the vent network
       running, the neighbours' ducts fill this one in the same half
       second and the pumps then rightly put the rest in the room. The
       network has tests of its own (272); here it is held still. */
    const grille = OXYGEN.VENT_GRILLE, pairs = sh._ventPairs, shafts = sh._ventShafts;
    OXYGEN.VENT_GRILLE = 0; sh._ventPairs = []; sh._ventShafts = [];
    try { sh.oxygen.update(0.5, sh); }
    finally { OXYGEN.VENT_GRILLE = grille; sh._ventPairs = pairs; sh._ventShafts = shafts; }
    ok(ro.duct > 0 && ro.level === 0.5, `the air goes into the duct before the room (${ro.duct.toFixed(2)} / ${ro.level})`);
    for (let i = 0; i < 400; i++) sh.oxygen.update(0.05, sh);
    ok(ro.duct === 1 && ro.level > 0.5, 'and into the room once the duct is full');

    // A full room over a DRY duct is still somewhere the air has to go.
    const ro2 = sh.oxygen.getRoom('r_shields');
    sh.rooms.forEach(r => { const x = sh.oxygen.getRoom(r.id); x.level = 1; x.duct = 1; });
    ro2.duct = 0;
    for (let i = 0; i < 40; i++) sh.oxygen.update(0.05, sh);
    ok(ro2.duct > 0.5, `a dry duct over a full room is refilled (${ro2.duct.toFixed(2)})`);
  }

  /* ── THE GAUGE COUNTS THE DUCTS ───────────────────────────
   * A lift shaft has air but no duct; everything else has both, and the
   * ship's gauge must move while only the ducts are emptying. */
  {
    const sh = hull(false);
    const shaft = [...sh.oxygen._rooms.values()].find(r => String(r.roomId).startsWith('shaft_'));
    ok(shaft && shaft.duct === null, 'a lift shaft has no duct');
    for (let i = 0; i < 100; i++) sh.oxygen.update(0.05, sh);
    const rooms = sh.rooms.map(r => sh.oxygen.getRoom(r.id));
    ok(rooms.some(r => r.level < 1) && rooms.some(r => r.duct < 1),
       'five seconds in with the module off, rooms and ducts have both lost air');
    ok(sh.oxygen.averageO2() < 1, `and the gauge shows it (${sh.oxygen.averageO2().toFixed(3)})`);
  }

  /* ── THE DUCT CATCHES FROM THE MODULE, AND CARRIES IT ON ── */
  {
    const sh = hull();
    const id = 'r_weapons';
    const room = sh.getRoomById(id);
    const sp = sh.addPest(new Pest({ kind: 'spider', roomId: id, x: room.cx }));
    sp._moveT = 1e9; sp._pounceT = 1e9;
    sh.crew.forEach(c => { c.x = -9999; c.roomId = null; });
    sh.fires.start(id, room.cx, room.cy);
    for (let i = 0; i < Math.floor((FIRE_DEFS.DUCT_CATCH - 0.5) / 0.05); i++) sh.update(0.05);
    ok(sh.fires.hasFireInRoom(id) && !sh.fires.ductBurning(sh, id),
       'a moment after the module lights, its duct has not yet');
    ok(sp.hp === sp.maxHp, 'and the spider up there is untouched');
    for (let i = 0; i < 40; i++) sh.update(0.05);
    ok(sh.fires.ductBurning(sh, id), 'then the duct catches');
    ok(sp.hp < sp.maxHp, 'and burns what is in it');

    // Drawn: flames along the grille of THAT duct.
    const flames = [];
    const ctx = stub();
    /* update128: the flames are BEHIND the slats — drawn first, the
       grille's slats after them. */
    const order = [];
    const SL = sb.trimRgba(sh.trim().base, 0.9);
    ctx.moveTo = (x, y) => { if (ctx.fillStyle === 'rgba(255,110,20,0.9)') { flames.push({ x, y }); order.push('flame'); } };
    const realFR = ctx.fillRect;
    ctx.fillRect = function (x, y, w, h) { if (ctx.fillStyle === SL && w === 1 && x >= room.x && x <= room.x + room.w) order.push('slat'); return realFR && realFR.apply(this, arguments); };
    drawHull(sh, ctx);
    ok(flames.length > 0 && flames.every(f => f.x >= room.x && f.x <= room.x + room.w &&
                                              f.y >= room.ventY && f.y <= room.ventY + room.ventH),
       `the burning duct is drawn, and only over its own room (${flames.length} flames)`);
    ok(order.indexOf('slat') > order.lastIndexOf('flame'),
       'and it burns BEHIND the grille: every flame is drawn before the slats go over it (jj)');
  }

  /* ── NO AIR IN THE DUCT, NO WAY THROUGH ───────────────────
   * The spread roll is the old one, unchanged — it just goes through
   * the duct now, so a fire under a dry duct stays where it is. */
  {
    const realRandom = Math.random;
    try {
      Math.random = () => 0;          // every roll would spread
      const run = (dry) => {
        const sh = hull();
        sh.doors.forEach(d => { if (!d.isAirlock) { d.mode = 'open'; d.open = true; d.openness = 1; } });
        const id = 'r_weapons';
        const room = sh.getRoomById(id);
        const f = sh.fires.start(id, room.cx, room.cy);
        f.intensity = 3; f.age = 99; f._spreadTimer = FIRE_DEFS.SPREAD_TIME + 1;
        if (dry) sh.oxygen.getRoom(id).duct = 0;
        sh.fires.update(0.01, sh);
        return sh.fires.fires.some(x => x.roomId !== id);
      };
      ok(run(false), 'with air in its duct the fire spreads');
      ok(!run(true), 'with the duct dry it does not');
    } finally { Math.random = realRandom; }
  }

  /* ── THE DUCT BURNS ONLY WHILE THE MODULE DOES ────────────
   * "Tylko pośrednik": put the module out and the duct is out with it. */
  {
    const sh = hull();
    const id = 'r_shields';
    const room = sh.getRoomById(id);
    const f = sh.fires.start(id, room.cx, room.cy);
    f.age = 99;
    ok(sh.fires.ductBurning(sh, id), 'lit');
    f.suppress(99);
    ok(!sh.fires.ductBurning(sh, id), 'and out the moment the fire below is');
  }

  /* ── THE DUCT'S AIR IS DRAWN ON ITS GRILLE ────────────────── */
  {
    const sh = hull();
    const room = sh.getRoomById('r_medbay');
    const ro = sh.oxygen.getRoom(room.id);
    const rects = [];
    const ctx = stub();
    ctx.fillRect = (x, y, w, h) => rects.push({ x, y, w, h, f: String(ctx.fillStyle) });
    drawHull(sh, ctx);
    const inDuct = r => r.y === room.ventY && r.x === room.x + 1 && r.f.startsWith('rgba(30,100,180');
    ok(!rects.some(inDuct), 'a full duct shows nothing');
    ro.duct = 0.3;
    drawHull(sh, ctx);
    ok(rects.some(inDuct), 'a thinning one is tinted');
  }
})();

// ============================================================
section('267. The rat economy: they eat, grow, breed, and chew when the food runs out');
// ============================================================
(function testRatEconomy() {
  const sb = loadEngine();
  const { Ship, CrewMember, Pest, Save, RAT_TUNING, CargoGrid } = sb;
  Save.load(); Save.startRun();
  const T = RAT_TUNING;

  const hull = () => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sh.cargo = new CargoGrid(6, 6);
    return sh;
  };
  const R = (sh, id) => sh.getRoomById(id);
  const rat = (sh, id, cfg = {}) => {
    const p = sh.addPest(new Pest({ kind: 'rat', roomId: id, x: R(sh, id).cx, ...cfg }));
    p._moveT = 1e9;
    return p;
  };
  const tick = (sh, secs, dt = 0.1) => { for (let i = 0; i < Math.round(secs / dt); i++) sh.pestTick(dt); };
  const rats = sh => sh.pests.filter(p => p.isRat && p.alive);

  /* ── THREE LEVELS, AND A MEAL IS WHAT MOVES THEM ──────────
   * Through pestTick: a young rat gets hungry by itself, eats ONE
   * portion out of a stack, and is a level older for it. */
  {
    const sh = hull();
    const box = sh.cargo.add('ration_pack');
    box.qty = 5;
    const r = rat(sh, 'r_weapons');
    ok(r.level === 1 && r.maxHp === T.LEVELS[1].hp, `a new rat is young (${r.maxHp} hp)`);
    tick(sh, 30);
    ok(box.qty === 5 && r.level === 1, 'fed, it leaves the hold alone');
    let t = 0;
    while (t < 1200 && r.level === 1) { sh.pestTick(0.5); t += 0.5; }
    ok(r.level === 2 && box.qty === 4,
       `hungry, it eats one portion and grows (after ${t.toFixed(0)}s, ${box.qty} left)`);
    ok(t > 400, 'but not in a hurry — it takes a while to get hungry');
    ok(r.maxHp === T.LEVELS[2].hp, `and it is bigger for it (${r.maxHp} hp)`);
  }

  /* ── THE BREEDING RAT'S MEAL IS A LITTER ─────────────────── */
  {
    const sh = hull();
    sh.cargo.add('ration_pack').qty = 5;
    const r = rat(sh, 'r_weapons', { level: 2, fullness: 10 });
    sh.pestTick(0.1);
    const pups = rats(sh).filter(p => p !== r);
    ok(r.level === 3, 'the breeding rat eats and is an adult');
    ok(pups.length >= T.LITTER_MIN && pups.length <= T.LITTER_MAX,
       `with a litter of ${pups.length}`);
    ok(pups.every(p => p.level === 1 && p.roomId === r.roomId), 'young, in its own duct');
    const x = sh.getRoomById('r_weapons');
    ok(pups.every(p => p.x >= x.x && p.x <= x.x + x.w), 'and inside it');
  }

  /* ── AN ADULT'S MEAL IS A LITTER TOO (update86b) ─────────── */
  {
    const sh = hull();
    sh.cargo.add('ration_pack').qty = 5;
    const r = rat(sh, 'r_weapons', { level: 3, fullness: 10 });
    sh.pestTick(0.1);
    const pups = rats(sh).filter(p => p !== r);
    ok(pups.length >= T.LITTER_MIN && pups.every(p => p.level === 1),
       `an adult that eats has a litter as well (${pups.length})`);
    ok(r.level === 3, 'and stays an adult');
  }

  /* ── AND THE HULL FILLS UP, BUT STOPS AT THE CAP ──────────
   * Two rats, a hold of food, an hour: whatever the dice do, never past
   * MAX_ABOARD. */
  {
    const sh = hull();
    sh.cargo.add('ration_pack').qty = 50;
    rat(sh, 'r_weapons'); rat(sh, 'r_engines');
    let peak = 0;
    for (let i = 0; i < 7200; i++) { sh.pestTick(0.5); peak = Math.max(peak, rats(sh).length); }
    ok(peak === T.MAX_ABOARD, `an hour of plenty fills the hull to the cap and no further (${peak})`);
  }

  /* ── NOT PAST THE CAP ─────────────────────────────────────── */
  {
    const sh = hull();
    sh.cargo.add('ration_pack').qty = 5;
    for (let i = 0; i < T.MAX_ABOARD - 1; i++) rat(sh, 'r_engines', { fullness: 100 });
    const r = rat(sh, 'r_weapons', { level: 2, fullness: 10 });
    sh.pestTick(0.1);
    ok(rats(sh).length === T.MAX_ABOARD, `a full hull gets no litter (${rats(sh).length})`);
    ok(r.level === 3, 'the rat still grows');
  }

  /* ── EGGS FIRST, AS THE CAT DOES ──────────────────────────── */
  {
    const sh = hull();
    const box = sh.cargo.add('ration_pack'); box.qty = 3;
    const egg = sh.cargo.add('spider_egg');
    ok(!!egg, 'an egg case fits the hold');
    rat(sh, 'r_weapons', { fullness: 10 });
    sh.pestTick(0.1);
    ok(!sh.cargo.items.includes(egg) && box.qty === 3,
       'a hungry rat takes the egg and leaves the rations');
  }
  {
    const sh = hull();
    const box = sh.cargo.add('ration_pack'); box.qty = 3;
    const sac = sh.addPest(new Pest({ kind: 'spider', roomId: 'r_weapons', x: 200, dormant: true, hatchT: 999 }));
    rat(sh, 'r_weapons', { fullness: 10 });
    sh.pestTick(0.1);
    ok(sac.dead && box.qty === 3, 'and a sac in its own duct before anything in the hold');
  }

  /* ── NOTHING CHEWS WHILE THERE IS FOOD ────────────────────
   * The player's rule, and the decision it makes. */
  {
    const sh = hull();
    const box = sh.cargo.add('ration_pack'); box.qty = 20;
    const sys = sh.getSystem('weapons');
    rat(sh, sys.roomId, { level: 3 });
    tick(sh, 600, 0.5);
    ok(sys.damagedLevels === 0, `ten minutes with food aboard: the loom is whole (${box.qty} left)`);
  }
  {
    const sh = hull();
    const sys = sh.getSystem('weapons');
    rat(sh, sys.roomId, { level: 3 });
    tick(sh, T.CHEW_MIN - 1);
    ok(sys.damagedLevels === 0, 'with the hold bare it does not start at once');
    tick(sh, T.CHEW_MAX - T.CHEW_MIN + 2);
    ok(sys.damagedLevels === 1, 'but within a minute a level is gone — one, not the module');
  }
  {
    const sh = hull();
    const sys = sh.getSystem('weapons');
    rat(sh, sys.roomId, { level: 2 });
    tick(sh, 120, 0.5);
    ok(sys.damagedLevels === 0, 'a rat that is not grown does not chew');
  }

  /* ── A HUNGRY ADULT BITES, RARELY ─────────────────────────
   * Only an adult, only with nothing to eat, only hungry. A bite is a
   * drop out of the duct, like the spider's — without the virus. */
  {
    const run = (cfg, withFood, secs) => {
      const sh = hull();
      if (withFood) sh.cargo.add('ration_pack').qty = 20;
      const man = new CrewMember({ name: 'Below' });
      sh.addCrew(man);
      const room = R(sh, 'r_crew1');
      man.roomId = room.id; man.inRoom = true; man.x = room.cx; man.y = sh.floorWalkY(room.floor, room.cy);
      const r = rat(sh, room.id, cfg);
      let bites = 0, first = null, t = 0;
      for (let i = 0; i < secs * 10; i++) {
        const hp = man.hp;
        sh.pestTick(0.1); t += 0.1;
        if (r.fullness > 0) r.fullness = cfg.fullness;          // hold its hunger where the case puts it
        if (cfg.level != null) r.level = cfg.level;              // and its age (a young rat must not grow up mid-case)
        if (man.hp < hp) { bites++; if (first == null) first = t; }
        man.hp = man.maxHp;
      }
      return { bites, first, man };
    };
    // update89: a bite is one of the moves on the rat's own clock (a
    // drop some of the time, and a drop can miss), so the window is long.
    const angry = run({ level: 3, fullness: 5 }, false, 1800);
    ok(angry.bites >= 2, `a starving adult with nothing to eat bites (${angry.bites} in 30 min)`);
    ok(angry.first >= T.CHEW_MIN - 0.5, `but not at once (${angry.first?.toFixed(0)}s)`);
    ok(angry.bites <= Math.ceil(1800 / T.CHEW_MIN * T.DROP_SHARE), `and rarely (${angry.bites})`);
    ok(!angry.man.virus, 'and a rat carries no virus');
    ok(run({ level: 3, fullness: 80 }, false, 200).bites === 0, 'a fed adult does not');
    ok(run({ level: 2, fullness: 5 }, false, 200).bites === 0, 'nor a rat that is not grown');
    // Only an adult acts at all, so the run above cannot tell the age
    // rule in _ratAngry from the one in _ratLife; ask it directly
    // (update120 — break_check found the clause unguarded).
    ok(!hull()._ratAngry({ level: 2, fullness: 5 }) && hull()._ratAngry({ level: 3, fullness: 5 }),
       'a young rat is never angry, however hungry; an adult is');
    ok(!hull()._ratAngry({ level: 3, fullness: 80 }), 'and a fed adult is not angry either');
  }
  {
    // With food in the hold it eats instead, so it is never angry at all.
    const sh = hull();
    sh.cargo.add('ration_pack').qty = 20;
    const r = rat(sh, 'r_crew1', { level: 3, fullness: 5 });
    sh.pestTick(0.1);
    ok(r.fullness > T.HUNGRY, 'a hungry adult with food aboard eats rather than bites');
  }

  /* ── IT STARVES, SLOWLY ───────────────────────────────────── */
  {
    const sh = hull();
    const r = rat(sh, 'r_weapons', { level: 1, fullness: 0 });
    tick(sh, T.STARVE_EVERY - 1);
    ok(r.hp === r.maxHp, 'an empty belly is not an instant death');
    tick(sh, 2);
    ok(r.hp === r.maxHp - 1, 'a point of hide every half minute');
    let t = 0;
    while (t < 2000 && !r.dead) { sh.pestTick(0.5); t += 0.5; }
    ok(r.dead && !sh.pests.includes(r), `and in the end it dies of it (${(t + T.STARVE_EVERY).toFixed(0)}s)`);
  }

  /* ── A RAT THAT STARVES THIS TICK DOES NOT BITE IN IT ─────
   * Its last point of hide goes on the same tick its drop clock runs
   * out, with a man under it: it dies, and bites nobody. */
  {
    const sh = hull();
    const man = new CrewMember({ name: 'Spared' });
    sh.addCrew(man);
    const room = R(sh, 'r_crew1');
    man.roomId = room.id; man.inRoom = true; man.x = room.cx; man.y = sh.floorWalkY(room.floor, room.cy);
    const r = rat(sh, room.id, { level: 3, fullness: 0 });
    r.hp = 1; r._starveT = T.STARVE_EVERY - 0.01; r._pounceT = 0.001;
    const hp = man.hp;
    sh.pestTick(0.05);
    ok(r.dead, 'it starves');
    ok(!r.pouncing && man.hp === hp, 'and does not drop on him on its way out');
  }

  /* ── GROWING KEEPS ITS WOUNDS ─────────────────────────────── */
  {
    const r = new Pest({ kind: 'rat', level: 1 });
    r.hp = r.maxHp - 4;
    r.growUp();
    ok(r.level === 2 && r.hp === T.LEVELS[2].hp - 4, 'a hurt rat grows up just as hurt');
    r.growUp(); r.growUp();
    ok(r.level === 3, 'and stops at adult');
  }

  /* ── IT SURVIVES A SAVE ───────────────────────────────────── */
  {
    const sh = hull();
    const r = rat(sh, 'r_weapons', { level: 3, fullness: 17 });
    r.hp = 20;
    const back = Ship.deserialise(JSON.parse(JSON.stringify(sh.serialise())), true, 0, 0);
    const b = back.pests[0];
    ok(b && b.level === 3 && b.fullness === 17 && b.hp === 20 && b.maxHp === T.LEVELS[3].hp,
       'level, hunger and wounds come back');
    const old = Pest.fromCrewRecord({ race: 'rat', roomId: 'r_weapons', x: 10, hp: 18, maxHp: 18 });
    ok(old.level === 2, 'an old-save rat is a breeding one — it was an 18-hp animal');
  }

  /* ── A YOUNG RAT IS DRAWN SMALLER ─────────────────────────
   * Through the whole Ship.draw: the size a rat's frame is painted at. */
  {
    const sh = hull();
    const sizes = [];
    const ctx = new Proxy({}, {
      get: (t, k) => (k in t ? t[k] : () => ({ addColorStop() {}, width: 10 })),
      set: (t, k, v) => { t[k] = v; return true; },
    });
    ctx.drawImage = (...a) => { if (a.length >= 5) sizes.push(a[a.length - 1]); };
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try {
      // Somebody has to be in the room to see it (update86a).
      const man = new CrewMember({ name: 'Looking' });
      sh.addCrew(man);
      const wr = R(sh, 'r_weapons');
      man.roomId = wr.id; man.inRoom = true; man.x = wr.cx; man.y = sh.floorWalkY(wr.floor, wr.cy);
      rat(sh, 'r_weapons', { level: 1 });
      sh.draw(ctx); const young = sizes.slice(); sizes.length = 0;
      sh.pests = [];
      rat(sh, 'r_weapons', { level: 3 });
      sh.draw(ctx); const adult = sizes.slice();
      const h = (arr, v) => arr.some(x => Math.abs(x - v) < 0.01);
      // (The man in the room is painted too, at 32 — so the question is
      //  whether the SMALL size is there, and only for the young one.)
      ok(h(young, 32 * T.LEVELS[1].scale), 'a young rat is painted small');
      ok(!h(adult, 32 * T.LEVELS[1].scale), 'an adult is not');
    } finally { console.log = log; console.warn = warn; }
  }
})();

// ============================================================
section('268. Up and down the lift shaft, and seen only where somebody is');
// ============================================================
(function testShaftsAndSight() {
  const sb = loadEngine();
  const { Ship, CrewMember, Pest, Save, CargoGrid } = sb;
  Save.load(); Save.startRun();

  const hull = () => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sh.cargo = new CargoGrid(6, 6);
    return sh;
  };
  const R = (sh, id) => sh.getRoomById(id);
  const stand = (sh, c, id) => {
    const r = R(sh, id);
    c.roomId = r.id; c.inRoom = true; c.x = r.cx; c.y = sh.floorWalkY(r.floor, r.cy); c._waypoints = [];
  };
  const man = (sh, id, cfg = {}) => { const c = new CrewMember({ name: 'M', ...cfg }); sh.addCrew(c); stand(sh, c, id); return c; };
  const stub = () => new Proxy({}, {
    get: (t, k) => (k in t ? t[k] : () => ({ addColorStop() {}, width: 10 })),
    set: (t, k, v) => { t[k] = v; return true; },
  });
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  /** Draw the whole hull and say which pests were painted. */
  const painted = (sh) => {
    const seen = new Set();
    sh.pests.forEach(p => {
      const real = p.anim?.draw?.bind(p.anim);
      if (p.anim) p.anim.draw = (...a) => { seen.add(p); return real(...a); };
    });
    const eggs = [];
    const ctx = stub();
    const realSac = sb.Animation.drawEggSac;
    quiet(() => sh.draw(ctx));
    return seen;
  };

  /* ── THE SHAFT IS A DUCT BETWEEN DECKS ────────────────────
   * The player's rule: the lift shaft is the way up and down. One deck
   * per hop, only rooms that back onto a shaft, and only on its side. */
  {
    const sh = hull();
    const ids = id => sh.ductLinks(id).map(l => l.room.id + (l.shaft ? '^' : ''));
    const eng = ids('r_engines');
    ok(eng.includes('r_weapons') && eng.includes('r_piloting^'),
       `the engine room's duct goes next door and up the shaft (${eng.join(',')})`);
    ok(!eng.includes('r_crew1^'), 'one deck at a time, not two');
    ok(!eng.includes('r_oxygen^') && !eng.includes('r_medbay^'),
       'and only to the room on its own side of the shaft');
    ok(sh.ductLinks('r_piloting').some(l => l.room.id === 'r_engines' && l.shaft),
       'the way down is there too');
    ok(ids('r_shields').includes('r_medbay^'), 'the far shaft links the far column');
  }

  /* ── IT CLIMBS, AND ONLY THROUGH THE SHAFT ────────────────
   * Ten minutes of pestTick: every change of deck comes out of a climb,
   * the climb is drawn in the shaft's own column, and it takes as long
   * as the height at the rat's speed. */
  {
    const sh = hull();
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: 'r_engines', x: 70, level: 3 }));
    let lastRoom = rat.roomId, climbed = false, jumps = 0, climbs = 0, off = 0, climbT = 0, durs = [];
    for (let i = 0; i < 6000; i++) {
      sh.pestTick(0.1);
      if (rat._climb) {
        climbed = true; climbT += 0.1;
        if (!sh.elevators.shafts.some(s => s.x === rat._climb.x)) off++;
      }
      if (rat.roomId !== lastRoom) {
        const a = R(sh, lastRoom), b = R(sh, rat.roomId);
        if (a.floor !== b.floor) { if (climbed) climbs++; else jumps++; durs.push(climbT); }
        climbed = false; climbT = 0;
        lastRoom = rat.roomId;
      }
    }
    ok(climbs > 0, `it changes deck (${climbs} climbs in ten minutes)`);
    ok(jumps === 0, 'and never without climbing');
    ok(off === 0, 'always inside a shaft');
    const deck = Math.abs(Pest.ductFloor(R(sh, 'r_engines')) - Pest.ductFloor(R(sh, 'r_piloting')));
    const want = deck / sb.PEST_DEFS.rat.speed;
    ok(durs.every(d => Math.abs(d - want) < 0.25),
       `a climb takes the height at its own speed (${want.toFixed(1)}s: ${durs.map(d => d.toFixed(1)).join(',')})`);
  }

  /* ── A SPIDER TAKES THE SHAFT TO THE PEOPLE ───────────────── */
  {
    let up = 0;
    for (let k = 0; k < 10; k++) {
      const sh = hull();
      man(sh, 'r_piloting');
      const sp = sh.addPest(new Pest({ kind: 'spider', roomId: 'r_engines', x: 70 }));
      sp._moveT = 0;
      sh.pestTick(0.01);
      if (sp._via === 'r_piloting' && sp._viaShaft) up++;
    }
    ok(up === 10, `the man is a deck up and it goes up the shaft to him (${up}/10)`);
  }

  /* ── IN THE SHAFT NOBODY REACHES IT, AND IT DROPS ON NOBODY ── */
  {
    const sh = hull();
    const cat = sb.makeCat('black', 'Mruk');
    sh.addCrew(cat);
    stand(sh, cat, 'r_engines');
    const below = man(sh, 'r_engines');
    const sp = sh.addPest(new Pest({ kind: 'spider', roomId: 'r_engines', x: 20 + 100 - 8 }));
    sp._climb = { x: 135, y0: 0, y1: -70, t: 0, dur: 99, to: 'r_piloting', exitX: 112 };
    sp._pounceT = 0;
    const hp = below.hp;
    // Watch every tick: a drop is over in a second or two and can miss
    // (update89), so the state at the end proved nothing (update120).
    let dropped = false;
    for (let i = 0; i < 20; i++) { sh.pestTick(0.1); dropped = dropped || sp.pouncing; }
    ok(sp._catId == null && cat._ductY == null, 'the cat cannot get at it in the shaft');
    ok(!dropped && below.hp === hp, 'and it drops on nobody from there');
  }

  /* ── SEEN ONLY WHERE SOMEBODY IS ──────────────────────────
   * Through the whole Ship.draw. */
  {
    const sh = hull();
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: 'r_shields', x: 330 })); rat._moveT = 1e9;
    ok(!painted(sh).has(rat), 'a rat over an empty room is not drawn');

    const enemy = man(sh, 'r_shields', { isPlayer: false });
    ok(!painted(sh).has(rat), 'nor for a boarder of theirs standing under it');
    sh.crew = sh.crew.filter(c => c !== enemy);

    const cat = sb.makeCat('ginger', 'Ruda');
    sh.addCrew(cat); stand(sh, cat, 'r_shields');
    cat.attackTimer.tick = () => false;
    ok(painted(sh).has(rat), 'the cat in the room sees it');
    sh.crew = sh.crew.filter(c => c !== cat);
    rat._catId = null;

    const m = man(sh, 'r_shields');
    ok(painted(sh).has(rat), 'so does a man');
    m.frozen = true;
    ok(!painted(sh).has(rat), 'but not one in a slab');
    m.frozen = false;
    stand(sh, m, 'r_medbay');
    ok(!painted(sh).has(rat), 'and once he walks out it is gone again');

    // In the shaft it is seen from either end of the climb.
    rat._climb = { x: 265, y0: 250, y1: 180, t: 0.5, dur: 3, to: 'r_medbay', exitX: 288 };
    ok(painted(sh).has(rat), 'climbing up to where he is, it is seen');

    /* …and drawn HEAD FIRST: the art faces right, so a quarter turn
       one way is up and the other is down. */
    const turns = (climb) => {
      rat._climb = climb;
      const r = [];
      const ctx = stub();
      ctx.rotate = (a) => { r.push(a); };
      quiet(() => sh.draw(ctx));
      return r;
    };
    ok(turns({ x: 265, y0: 250, y1: 180, t: 0.5, dur: 3, to: 'r_medbay', exitX: 288 })
         .some(a => Math.abs(a + Math.PI / 2) < 1e-9), 'going up, it is turned to face up');
    stand(sh, m, 'r_shields');
    ok(turns({ x: 265, y0: 180, y1: 250, t: 0.5, dur: 3, to: 'r_shields', exitX: 288 })
         .some(a => Math.abs(a - Math.PI / 2) < 1e-9), 'going down, to face down');

    /* IN FRONT OF THE SHAFT, NOT BEHIND IT: the shaft is a painted
       column, and a climber drawn before it is drawn over. Order of the
       draw calls through Ship.draw: the rat's frame after the shaft's. */
    rat._climb = { x: 265, y0: 250, y1: 180, t: 0.5, dur: 3, to: 'r_medbay', exitX: 288 };
    stand(sh, m, 'r_medbay');
    const order = [];
    const realAnim = rat.anim.draw.bind(rat.anim);
    rat.anim.draw = (...a) => { order.push('rat'); return realAnim(...a); };
    const realLift = sh.elevators.draw.bind(sh.elevators);
    sh.elevators.draw = (...a) => { order.push('shaft'); return realLift(...a); };
    quiet(() => sh.draw(stub()));
    ok(order.indexOf('rat') > order.indexOf('shaft') && order.includes('shaft'),
       `a climbing rat is drawn over the shaft (${order.join(' → ')})`);
    rat._climb = null;
    order.length = 0;
    stand(sh, m, 'r_shields');
    quiet(() => sh.draw(stub()));
    ok(order.indexOf('rat') < order.indexOf('shaft'),
       'one in its duct is drawn with the ducts, under the lift');
    sh.elevators.draw = realLift;
  }

  /* ── THE EGG CASE IN THE DUCT IS HIDDEN THE SAME WAY ─────── */
  {
    const sh = hull();
    const egg = sh.cargo.add('spider_egg', { roomId: 'r_shields', x: 330, hatchT: 50 });
    ok(!!egg, 'an egg case with a place in the duct');
    const drawn = () => {
      let n = 0;
      const ctx = stub();
      const realArc = ctx.ellipse;
      ctx.strokeStyle = '';
      const real = sh._drawEggs.bind(sh);
      const rects = [];
      ctx.fillRect = (x, y, w, h) => { if (y >= R(sh, 'r_shields').ventY && y <= R(sh, 'r_shields').ventY + 20 && x > 280) rects.push(1); };
      ctx.arc = ctx.ellipse = () => { n++; };
      quiet(() => sh.draw(ctx));
      return n;
    };
    const hidden = drawn();
    man(sh, 'r_shields');
    const shown = drawn();
    ok(shown > hidden, `nobody there: not drawn; a man under it: drawn (${hidden} → ${shown})`);
  }

  /* ── WHAT THEY DO IS STILL SAID ───────────────────────────
   * The body is hidden, the consequence is not: a chewed loom over an
   * empty room is still reported. */
  {
    const sh = hull();
    const notes = [];
    const realNotify = sb.UI.notify;
    sb.UI.notify = (m) => { notes.push(m); };
    try {
      const sys = sh.getSystem('shields');
      const r = sh.addPest(new Pest({ kind: 'rat', roomId: sys.roomId, x: R(sh, sys.roomId).cx, level: 3 }));
      r._moveT = 1e9; r._chewT = 0.01;
      sh.pestTick(0.05);
      ok(sys.damagedLevels === 1 && notes.some(n => /chewed/.test(n)),
         'a loom chewed where nobody can see is still reported');
    } finally { sb.UI.notify = realNotify; }
  }
})();

// ============================================================
section('269. Balance after playing: air, medkits, lasers, fire, meals, Terra, aiming, lifts');
// ============================================================
(function testUpdate87Balance() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Station, Weapon, WEAPON_DEFS, FIRE_DEFS, HUNGER,
          CargoGrid, BossManager, Game, CombatManager } = sb;
  Save.load(); Save.startRun();
  const T = Game.__test;
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const stand = (sh, c, id) => {
    const r = sh.getRoomById(id);
    c.roomId = r.id; c.inRoom = true; c.x = r.cx; c.y = sh.floorWalkY(r.floor, r.cy);
    c._waypoints = []; c.homeRoomId = r.id;
  };

  /* ── 2. LIFE SUPPORT IS LEVEL 2 AT LEAST ──────────────────
   * Every player hull, a hull out of an old save, and every enemy the
   * game spawns: enough air for the people aboard, and the reactor to
   * run it. A boss runs three at least. */
  {
    ['scout', 'hauler', 'frigate'].forEach(k => {
      const sh = new Ship(k, true, 0, 0);
      ok(sh.getSystem('oxygen').level === 2, `the ${k} is built with O2 at level 2`);
    });
    const sh = new Ship('scout', true, 0, 0);
    const data = JSON.parse(JSON.stringify(sh.serialise()));
    const i = sh.systems.findIndex(s => s.type === 'oxygen');
    data.systems[i].level = 1; data.systems[i].power = 1;
    const back = Ship.deserialise(data, true, 0, 0);
    ok(back.getSystem('oxygen').level === 2, 'a hull saved on a one-pip module comes out of the hangar on two');
    const scoutReactor = new Ship('scout', true, 0, 0).reactor.capacity;
    ok(scoutReactor === 6, 'and the player gets no extra power for it');

    let short = 0, spawned = 0, withCaptives = 0;
    quiet(() => {
      for (let n = 0; n < 40; n++) {
        T._spawnEnemy(n % 3 ? 'normal' : 'hard');
        const e = T.enemyShip;
        spawned++;
        const o2 = e.getSystem('oxygen');
        const need = e.systems.filter(x => x.type !== 'reactor').reduce((a, x) => a + x.maxPower, 0);
        const mouths = e.crew.filter(c => !c.frozen).length;
        if (e.getSystem('carbonite')) withCaptives++;
        if (o2.level < 2 || o2.level * 3 < Math.min(mouths, 12) || o2.power < o2.level ||
            e.reactor.capacity < need) short++;
      }
    });
    ok(withCaptives > 0, `test setup: some of them carry captives in a carbonite bay (${withCaptives})`);
    ok(short === 0, `${spawned} enemies: every one breathes its whole crew and powers it (${short} short)`);

    const boss = quiet(() => BossManager.start(0, 850, 120));
    const bo = boss.getSystem('oxygen');
    ok(bo.level >= 3 && bo.power === bo.level, `a boss runs ${bo.level} pips of air, all powered`);
  }

  /* ── 6. MEDKITS AT THE PORT ────────────────────────────── */
  {
    let stocked = 0;
    for (let i = 0; i < 20; i++) if ((new Station(1, 7000 + i).stock.medkits ?? 0) > 0) stocked++;
    ok(stocked === 20, `every port carries medical supplies (${stocked}/20)`);
    const st = new Station(2, 4242);
    const sh = new Ship('frigate', true, 0, 0);
    sh.cargo = new CargoGrid(4, 4);
    Save.updateRun({ scrap: 1000 });
    const doses0 = sh.cargo.countOf('heal');
    const r = st.buyMedkits(2, Save.getRun(), sh);
    ok(r.ok && sh.cargo.countOf('heal') === doses0 + 10, `two kits are ten doses (update93a: five a box) (${r.message})`);
    ok(Save.getRun().scrap === 1000 - st.medkitCost(2), 'and cost what the card says');
    const full = new Ship('frigate', true, 0, 0);
    full.cargo = new CargoGrid(1, 1);
    ok(!!full.cargo.add('ration_pack'), 'test setup: the one cell is really taken');
    const cc = Save.getRun().scrap;
    const r2 = st.buyMedkits(1, Save.getRun(), full);
    ok(!r2.ok && Save.getRun().scrap === cc, 'a full hold is not charged for a kit it cannot take');
  }

  /* ── 8 & 24. LASERS ────────────────────────────────────── */
  {
    const w = new Weapon('laser_basic');
    w.armed = true;
    const p = w.fire(0, 0, 400, 0, true)[0];
    ok(p.speed >= 300, `a laser bolt flies faster (${p.speed} px/s, was 240)`);
    const b = WEAPON_DEFS.laser_burst;
    ok(b.shots === 2 && b.chargeTime === 10, 'the burst laser: two bolts, ten seconds');
  }

  /* ── 12. FIRE IS SLOWER ───────────────────────────────────
   * Through the fire manager with a spread roll that always comes up:
   * fifteen seconds of a big fire is not yet a jump, and a man standing
   * in it for ten seconds is hurt, not dead. */
  {
    const realRandom = Math.random;
    try {
      Math.random = () => 0;
      const sh = new Ship('frigate', true, 0, 0);
      sh.doors.forEach(d => { if (!d.isAirlock) { d.mode = 'open'; d.open = true; d.openness = 1; } });
      const room = sh.getRoomById('r_weapons');
      const f = sh.fires.start(room.id, room.cx, room.cy);
      f.intensity = 3;
      for (let i = 0; i < 300; i++) sh.fires.update(0.05, sh);
      ok(!sh.fires.fires.some(x => x.roomId !== room.id), 'fifteen seconds of a big fire has not spread yet');
      for (let i = 0; i < 200; i++) sh.fires.update(0.05, sh);
      ok(sh.fires.fires.some(x => x.roomId !== room.id), 'twenty-five seconds and it has');
    } finally { Math.random = realRandom; }
    const sh = new Ship('frigate', true, 0, 0);
    const man = new CrewMember({ name: 'Singed', race: 'phoenix' });
    sh.addCrew(man); stand(sh, man, 'r_weapons');
    const room = sh.getRoomById('r_weapons');
    sh.fires.start(room.id, room.cx, room.cy);
    for (let i = 0; i < 200; i++) sh.fires.update(0.05, sh);
    ok(man.hp >= man.maxHp - 20 && man.hp < man.maxHp,
       `ten seconds in a small fire costs a man under twenty (${man.hp.toFixed(0)}/${man.maxHp})`);
  }

  /* ── 13 & 17. MEALS ───────────────────────────────────────
   * Through Ship.update: a hungry man does NOT help himself; one whose
   * stomach is costing him hide does; the meal takes six seconds; a
   * bandage still takes three; and while he eats there is one food mark
   * on him, not two. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sh.cargo.add('ration_pack', null, 4);
    const man = new CrewMember({ name: 'Peckish', race: 'phoenix' });
    sh.addCrew(man); stand(sh, man, 'r_crew1');
    man.hunger = HUNGER.HUNGRY - 20;
    for (let i = 0; i < 100; i++) sh.update(0.1);
    ok(!man.busy && man.hunger < HUNGER.HUNGRY, 'hungry, he carries on without a meal');
    man.hunger = 0;
    sh.update(0.1);
    ok(man.busy && man._busyAct === 'eat', 'once it starts to hurt, he eats');
    ok(Math.abs(man._busyT - HUNGER.EAT_SECONDS) < 0.2 && HUNGER.EAT_SECONDS === 6,
       `and the meal is six seconds (${HUNGER.EAT_SECONDS})`);
    const keys = sb.Renderer.crewMarks(man, sh).map(m => m.key);
    ok(!keys.includes('hungry') && !keys.includes('starving') && keys.includes('eating'),
                 `one food mark while he eats (${keys.join(',')})`);
    sh._startBusy(man, 'aid', null);
    ok(man._busyT === Ship.AID_SECONDS && Ship.AID_SECONDS === 3, 'a bandage is still three seconds');
  }

  /* ── 22. TERRA: EIGHTY, AND A PIP AT THE REACTOR ──────── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    const cy = new CrewMember({ name: 'Cyborg', race: 'terra' });
    sh.addCrew(cy);
    ok(cy.maxHp === 80, 'a Terra hand is on eighty');
    const base = sh.reactor.totalPower;
    stand(sh, cy, sh.reactor.sys.roomId);
    for (let i = 0; i < 20; i++) sh.update(0.05);
    ok(sh.reactor.totalPower === base + 1, `at the reactor console he is one more unit (${base} → ${sh.reactor.totalPower})`);
    const other = new Ship('frigate', true, 0, 0);
    other._allocateDefaultPower();
    const man = new CrewMember({ name: 'Plain', race: 'phoenix' });
    other.addCrew(man); stand(other, man, other.reactor.sys.roomId);
    for (let i = 0; i < 20; i++) other.update(0.05);
    ok(other.reactor.totalPower === base, 'anybody else at the reactor is not');
    sh.reactor.sys.damagedLevels = sh.reactor.sys.level;
    ok(sh.reactor.totalPower === 0, 'and a wrecked core is not rescued by a man standing in it');
  }

  /* ── 23. AIM A GUN THAT IS STILL CHARGING ─────────────────
   * The real road: the hotkey, a click on their room, the charge. It
   * fires at that room the moment it is armed — once. */
  {
    const c = makeCombat(sb);
    const gun = new Weapon('laser_basic');
    c.player.weapons = [gun];
    gun.armed = false; gun.charge = 0;
    c.T.derelictOffered = true;
    c.T.STATE = 'combat';
    const room = c.enemy.rooms.find(r => r.system) || c.enemy.rooms[0];
    const said = [];
    const realNotify = sb.UI.notify;
    sb.UI.notify = (m) => said.push(String(m));
    try {
      sb.Input.isPressed = (code) => code === 'Digit1';
      c.T._updateCombat(0.016);
      sb.Input.isPressed = () => false;
      sb.Input.mouse.x = room.cx; sb.Input.mouse.y = room.cy;
      sb.Input.mouse.leftPressed = true;
      c.T._updateCombat(0.016);
      sb.Input.mouse.leftPressed = false;
    } finally { sb.UI.notify = realNotify; }
    ok(gun.targetRoom === room && gun.queuedShot === true,
       `a charging gun takes a target (${said.join(' | ')})`);
    const fired = [];
    const realFire = CombatManager.playerFire.bind(CombatManager);
    CombatManager.playerFire = (w, r) => { fired.push(r); return realFire(w, r); };
    try {
      gun.armed = true;
      c.T._updateCombat(0.016);
      c.T._updateCombat(0.016);
    } finally { CombatManager.playerFire = realFire; }
    ok(fired.length === 1 && fired[0] === room, `and fires there once it is charged (${fired.length} shot)`);
    ok(!gun.queuedShot, 'once');
  }

  /* …BUT A GUN THAT COULD NOT FIRE EVEN CHARGED IS NOT AIMED, AND SAYS
     WHY: a Hull Cannon with empty racks, still charging. The number key
     must not select it — and must say it is out of ammo, not "charging". */
  {
    const c = makeCombat(sb);
    const cannon = new Weapon('cannon_basic');
    c.player.weapons = [cannon];
    c.player.cargo.clear();
    Save.updateRun({ missiles: 0 });
    cannon.armed = false;
    c.T.derelictOffered = true;
    c.T.STATE = 'combat';
    const said = [];
    const realNotify = sb.UI.notify;
    sb.UI.notify = (m) => said.push(String(m));
    try {
      sb.Input.isPressed = (code) => code === 'Digit1';
      c.T._updateCombat(0.016);
      sb.Input.isPressed = () => false;
    } finally { sb.UI.notify = realNotify; }
    ok(said.some(m => /out of ammo/i.test(m)) && !said.some(m => /click enemy room/i.test(m)),
       `an empty cannon is refused, and the reason is the ammo (${said.join(' | ')})`);
  }

  /* ── 26. SLOWER LIFTS ─────────────────────────────────── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    const shaft = sh.elevators.shafts[0];
    const y0 = shaft.floorY(0), y1 = shaft.floorY(1);
    shaft._cabinY = y0; shaft._targetY = y1; shaft._moving = true;
    let t = 0;
    while (shaft._moving && t < 10) { shaft.update(0.05); t += 0.05; }
    const want = Math.abs(y1 - y0) / 55;
    ok(Math.abs(t - want) < 0.2, `a deck takes ${t.toFixed(2)}s at 55 px/s (was ${(Math.abs(y1 - y0) / 80).toFixed(2)}s)`);
  }
})();

// ============================================================
section('270. What the screen says: the log, the module tips, one icon, air, boxes, the hold');
// ============================================================
(function testUpdate88Screen() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, UI, Renderer, Input, LootScreen, CargoGrid, OXYGEN } = sb;
  Save.load(); Save.startRun();
  const T = sb.Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };

  /* ── 1. THE LOG ───────────────────────────────────────────
   * Every notice is kept (the last sixty). In a fight, with the window
   * open, it is read in the bottom-right panel and NOT popped up in the
   * middle; shut, the pop-ups come back. The toggle is a click on the
   * tab (through the game's click chain) or L (through the fight's own
   * update). */
  {
    for (let i = 0; i < 70; i++) UI.notify(`line ${i}`, i % 2 ? 'warn' : 'info');
    const log = UI.logEntries();
    ok(log.length === 60 && log[59].message === 'line 69' && log[0].message === 'line 10',
       `the log keeps the last sixty (${log.length}, ${log[0].message}…${log[59].message})`);

    const ship = new Ship('frigate', true, 80, 120);
    ok(UI.isLogOpen(), 'the window starts open');
    const inPanel = captureText(ctx, () => UI.draw(ctx, { playerShip: ship, logPanel: true })).map(d => d);
    const R = UI.logButtonRect();
    const lines = inPanel.filter(d => /^line \d+$/.test(d.t));
    ok(lines.length >= 5 && lines.every(d => d.x > 860 && d.y > 480),
       `the last few are in the bottom-right panel (${lines.length} shown)`);
    ok(lines.some(d => d.t === 'line 69'), 'the newest one among them');
    UI.notify('a fresh one', 'alert');
    const again = captureText(ctx, () => UI.draw(ctx, { playerShip: ship, logPanel: true }));
    ok(again.filter(d => d.t === 'a fresh one').length === 1,
       'and a new notice is said ONCE — in the panel, not also as a pop-up');

    // The tab, through the click chain the game really uses.
    const c = makeCombat(sb);
    T.STATE = 'combat';
    Input.mouse.x = R.x + 5; Input.mouse.y = R.y + 5;
    const used = T._handlePowerBarClick ? T._handlePowerBarClick() : null;
    if (used !== null) ok(used === true && !UI.isLogOpen(), 'a click on the tab shuts it');
    else { UI.toggleLog(); ok(!UI.isLogOpen(), 'the tab shuts it'); }
    UI.notify('said while shut', 'good');
    const shut = captureText(ctx, () => UI.draw(ctx, { playerShip: ship, logPanel: true }));
    /* update90a: shut, nothing pops up in the middle any more (the
       player: "zlikwiduj logi na środku ekranu") — the tab counts what
       came in while it was shut. */
    ok(!shut.some(d => d.t === 'said while shut'),
       'shut, the notices do NOT pop up in the middle');
    ok(shut.some(d => /LOG ▴ 1 new/.test(d.t)), `and the tab counts it (${shut.filter(d => /LOG/.test(d.t)).map(d => d.t)})`);
    c.T.derelictOffered = true;
    Input.isPressed = (code) => code === 'KeyL';
    try { c.T._updateCombat(0.016); } finally { Input.isPressed = () => false; }
    ok(UI.isLogOpen(), 'L opens it again, from inside the fight');
    /* AND THE GAME ASKS FOR IT. Everything above hands UI.draw the flag
       by hand; the frame the game really draws is T._draw, and in a
       fight it must be the panel that carries the notice. */
    T.playerShip = c.player; T.enemyShip = c.enemy; T.STATE = 'combat';
    UI.notify('through the real frame', 'info');
    const frame = quiet(() => captureText(sb.Renderer.getCtx(), () => T._draw()));
    ok(frame.some(d => d.t === 'through the real frame' && d.x > 860 && d.y > 480),
       'the game\'s own frame puts a fight\'s notices in the panel');
    // A screen with no log window (the base, a menu): pop-ups, no panel.
    UI.notify('on the map', 'info');
    const map = captureText(ctx, () => UI.draw(ctx, { playerShip: ship, logPanel: false }));
    ok(map.some(d => d.t === 'on the map' && d.x < 860), 'a screen without the window still gets the pop-up');
  }

  /* ── 15. ONE MODULE ICON ──────────────────────────────────
   * The power bar, the room corner and a crewman's console mark all
   * draw through Renderer.drawSystemIcon — and with art on file, it is
   * the art (tinted), not the glyph. */
  {
    const ship = new Ship('frigate', true, 80, 120);
    ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(cm => ship.addCrew(cm));
    ship.assignStations();
    /* No art in the test engine, so the one icon takes its glyph path:
       every module's glyph must land on the power bar at the bottom. */
    const hud = quiet(() => captureText(ctx, () => Renderer.drawHUD({ playerShip: ship, enemyShip: null })));
    const bottom = hud.filter(d => d.y > 600).map(d => d.t);
    const types = ship.systems.map(s => s.type);
    ok(types.every(t => bottom.includes(Renderer.systemGlyph(t))),
       `the power bar draws every module's icon (${types.filter(t => !bottom.includes(Renderer.systemGlyph(t))).join(',') || 'all there'})`);

    // Art on file → the picture, not the glyph.
    const drawn = { img: 0, text: [] };
    const c2 = { globalAlpha: 1, fillStyle: '', font: '', textAlign: '',
      drawImage: () => { drawn.img++; }, fillText: (t) => drawn.text.push(t) };
    const realSrc = sb.Assets.source, realGet = sb.Assets.get;
    sb.Assets.source = (k) => (k === 'icon_shields' ? 'file' : null);
    sb.Assets.get = (k) => ({ width: 64, height: 64 });
    let alignAfterArt = null;
    try {
      Renderer.drawSystemIcon(c2, 'engines', 80, 50, 20, '#fff');
      c2.textAlign = 'left';
      Renderer.drawSystemIcon(c2, 'shields', 50, 50, 20, '#fff');
      alignAfterArt = c2.textAlign;
    } finally { sb.Assets.source = realSrc; sb.Assets.get = realGet; }
    c2.textAlign = alignAfterArt;       // the ART path is the one that used to leave it wrong
    ok(drawn.img === 1 && drawn.text.length === 1 && drawn.text[0] === Renderer.systemGlyph('engines'),
       'with a file the art is drawn; without one, the glyph');
    ok(c2.textAlign === 'center', 'and it leaves the text centred, as the labels under it expect');
  }

  /* ── 16. THE AIR IN THE CORNER, ALWAYS — as four lamps now (update120) ── */
  {
    const ship = new Ship('frigate', true, 80, 120);
    const room = ship.getRoomById('r_weapons');
    const ro = ship.oxygen.getRoom(room.id);
    const at = (lvl) => {
      ro.level = lvl;
      const rects = [], fr = ctx.fillRect;
      ctx.fillRect = function (x, y, w, h) { rects.push({ x, y, w, h, fill: ctx.fillStyle }); };
      let text;
      try { text = captureText(ctx, () => ro.draw(ctx, room.x, room.y, room.w, room.h)); } finally { ctx.fillRect = fr; }
      const lamps = rects.filter(r => r.w === sb.OXYGEN_LAMPS.size && r.h === sb.OXYGEN_LAMPS.size);
      return { text, lamps, lit: lamps.filter(r => !/rgba\(4,6,10/.test(r.fill)).length };
    };
    const full = at(1), half = at(0.5), thin = at(0.2);
    ok(full.text.length === 0 && half.text.length === 0, 'no number written in the room any more (jj: it was in the way)');
    ok(full.lamps.length === 4 && full.lit === 4, `a full room lights all four lamps (${full.lit})`);
    ok(half.lit === 2, `a half-empty one two (${half.lit})`);
    ok(thin.lit === 1 && thin.lamps.some(r => r.fill === '#ff2d44' || r.fill === '#ffb020'), 'thin air: one lamp, and not in blue');
    ok(full.lamps.every(r => r.x > room.x + room.w - 24 && r.x + r.w <= room.x + room.w - Ship.BULKHEAD / 2 - 1 && r.y >= room.floorTop && r.y < room.floorTop + 10),
       'in the top-right corner of the room, clear of the wall (jj: they ran into it)');
  }

  /* ── 11. WHAT A MODULE DOES, ON HOVER ─────────────────────
   * Ship.moduleInfo reads the real rules; the tip is drawn by UI.draw
   * when the cursor is over a module of ours and not over a man. */
  {
    const ship = new Ship('frigate', true, 80, 120);
    ship._allocateDefaultPower();
    const med = ship.getSystem('medbay');
    med.level = 4; med.desiredPower = 4; med.power = 4;
    ship.reactor.level = 12; ship._allocateDefaultPower();
    med.power = 4;
    const info = ship.moduleInfo(med);
    const rows = info.rows.map(r => `${r.on ? '+' : '-'} ${r.text}`);
    ok(info.title === 'MEDBAY' && /level 4/.test(info.status), `medbay tip heads (${info.status})`);
    ok(rows.some(r => /^\+ Level 3\+: cures the corpse plague/.test(r)),
       'a four-level ward shows the plague cure as working');
    ok(rows.some(r => /^- Level 5\+: cures the spider virus/.test(r)),
       'and the virus cure as out of reach');
    med.power = 2;
    ok(ship.moduleInfo(med).rows.some(r => /corpse plague/.test(r.text) && !r.on),
       'on two powered levels the plague cure goes grey — it is the POWERED level that counts');

    const o2 = ship.getSystem('oxygen');
    ok(ship.moduleInfo(o2).rows[0].text === `1 powered level = air for ${OXYGEN.PER_POWER / OXYGEN.BREATHING} people`,
       'the O2 tip reads the air rule, not the stale "faster refill"');

    // The engine tip's number IS the evasion maths.
    const man = new CrewMember({ name: 'Pilot' });
    ship.addCrew(man);
    const pil = ship.getRoomById(ship.getSystem('piloting').roomId);
    man.roomId = pil.id; man.inRoom = true; man.x = pil.cx; man.y = ship.floorWalkY(pil.floor, pil.cy);
    const eng = ship.getSystem('engines');
    const nowRow = ship.moduleInfo(eng).rows.find(r => /^Now:/.test(r.text)).text;
    /* Against the EVASION ITSELF, not against the constant: with the
       cockpit unpowered and nobody skilled, what the ship dodges IS the
       engines' share — and the tip must say that number. */
    const pilotSys = ship.getSystem('piloting');
    pilotSys.power = 0; pilotSys.desiredPower = 0;
    man.skills.piloting = { level: 0, xp: 0 };
    const real = Math.round(ship.evasion * 100);
    ok(nowRow === `Now: +${real}%`, `the engines say what the ship really dodges (${nowRow} vs ${real}%)`);

    // Drawn on hover, through UI.draw — over the module's BADGE (update90a).
    const room = ship.getRoomById(med.roomId);
    Input.mouse.x = room.x + 6; Input.mouse.y = room.y + room.h - 6;
    const floor = captureText(ctx, () => UI.draw(ctx, { playerShip: ship, moduleTips: true })).map(d => d.t);
    ok(!floor.includes('MEDBAY'), 'the floor of the medbay brings up nothing (update90a: only the badge does)');
    const badge = med.badgeRect();
    Input.mouse.x = badge.x + badge.w / 2; Input.mouse.y = badge.y + badge.h / 2;
    const tip = captureText(ctx, () => UI.draw(ctx, { playerShip: ship, moduleTips: true })).map(d => d.t);
    ok(tip.includes('MEDBAY'), 'hovering the medbay\'s badge brings up its tip');
    const none = captureText(ctx, () => UI.draw(ctx, { playerShip: ship, moduleTips: false })).map(d => d.t);
    ok(!none.includes('MEDBAY'), 'and only where tips are on');
    // …and the game turns them on in a fight, through its own frame.
    T.playerShip = ship; T.enemyShip = new Ship('enemy_frigate', false, 850, 120); T.STATE = 'combat';
    Input.mouse.x = badge.x + badge.w / 2; Input.mouse.y = badge.y + badge.h / 2;
    const f2 = quiet(() => captureText(sb.Renderer.getCtx(), () => T._draw())).map(d => d.t);
    ok(f2.includes('MEDBAY'), 'the game\'s own frame shows the tip over our medbay in a fight');
  }

  /* ── 7. DOUBLE CLICK SENDS IT ACROSS ──────────────────────
   * The real screen, the real clicks: a crate taken up and clicked
   * again at once on the same spot goes to the other grid; the other
   * way round too; and with no room it goes home and says so. */
  {
    const hold = new CargoGrid(6, 4), wreck = new CargoGrid(6, 4);
    const kit = hold.add('medkit');
    const fuel = wreck.add('he2_small', null, 2);
    LootScreen.openLoot(wreck, hold, {});
    const clickOn = (which, it) => {
      const r = LootScreen._gridRect(which);
      const cell = (r.w + 4) / r.grid.cols;
      Input.mouse.x = r.x + it.x * cell + 6; Input.mouse.y = r.y + it.y * cell + 6;
      Input.mouse.leftPressed = true;
      LootScreen.update(0.05);
      Input.mouse.leftPressed = false;
    };
    const kx = kit.x, ky = kit.y;
    clickOn('hold', kit);
    kit.x = kx; kit.y = ky;                 // it is in the hand; aim at where it came from
    clickOn('hold', kit);
    ok(wreck.items.includes(kit) && !hold.items.includes(kit), 'hold → the other side');
    const fx = fuel.x, fy = fuel.y;
    clickOn('wreck', fuel);
    fuel.x = fx; fuel.y = fy;
    clickOn('wreck', fuel);
    ok(hold.items.includes(fuel), 'and the other side → the hold');

    // Too slow is not a double click: it goes back down where it was.
    const slow = hold.add('ration_pack');
    const sx = slow.x, sy = slow.y;
    clickOn('hold', slow);
    LootScreen.update(1.0);
    slow.x = sx; slow.y = sy;
    clickOn('hold', slow);
    ok(hold.items.includes(slow) && slow.x === sx && slow.y === sy, 'two slow clicks put it back down in place');

    // No room over there: home, and said.
    const full = new CargoGrid(1, 1); full.add('ration_pack');
    const h2 = new CargoGrid(4, 4); const box = h2.add('plating');
    LootScreen.openLoot(full, h2, {});
    const bx = box.x, by = box.y;
    clickOn('hold', box); box.x = bx; box.y = by; clickOn('hold', box);
    ok(h2.items.includes(box) && box.x === bx && box.y === by, 'with no room across it goes back home');
  }

  /* ── 25. WHAT GUN IS IN THE BOX ───────────────────────── */
  {
    const hold = new CargoGrid(6, 4);
    const crate = hold.add('gun_crate', 'laser_burst');
    LootScreen.openLoot(null, hold, {});
    const r = LootScreen._gridRect('hold');
    const cell = (r.w + 4) / hold.cols;
    Input.mouse.x = r.x + crate.x * cell + 6; Input.mouse.y = r.y + crate.y * cell + 6;
    Input.mouse.leftPressed = true; LootScreen.update(0.05); Input.mouse.leftPressed = false;
    const text = captureText(ctx, () => LootScreen.draw(ctx)).map(d => d.t).join(' | ');
    const g = sb.WEAPON_DEFS.laser_burst;
    ok(text.includes(g.label), `the gun is named (${g.label})`);
    ok(text.includes(`needs ${g.powerCost} power`) && text.includes(`charge ${g.chargeTime}s`),
       'with the numbers that decide whether it is worth a mount');
    ok(!/weapon rack/.test(text), 'and no word about a weapon rack that is not there');
    ok(/UNBOX & FIT/.test(text), 'it says what the button does');
  }
})();

// ============================================================
section('271. Rats and spiders drop or chew on their own clocks, rat wrecks, air comes back, eggs stay aboard');
// ============================================================
(function testUpdate89Pests() {
  const sb = loadEngine();
  const { Ship, CrewMember, Pest, Save, RAT_TUNING, PEST_TUNING, CargoGrid, OXYGEN,
          Base, BaseScreen, Game, UI, makeDerelict, populateDerelict, makeStartingCrew,
          makeWreckGrid, CombatManager } = sb;
  Save.load(); Save.startRun();
  const T = RAT_TUNING;
  const G = Game.__test;
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const hull = () => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sh.cargo = new CargoGrid(6, 6);
    return sh;
  };
  const R = (sh, id) => sh.getRoomById(id);
  const rat = (sh, id, cfg = {}) => {
    const p = sh.addPest(new Pest({ kind: 'rat', roomId: id, x: R(sh, id).cx, ...cfg }));
    p._moveT = 1e9;
    return p;
  };
  const standIn = (sh, c, id) => {
    const r = R(sh, id);
    c.roomId = r.id; c.inRoom = true; c.x = r.cx; c.y = sh.floorWalkY(r.floor, r.cy);
    c._waypoints = [];
  };
  const withRandom = (v, fn) => {
    const real = Math.random;
    Math.random = () => v;
    try { return fn(); } finally { Math.random = real; }
  };

  /* ── 1. EACH RAT ON ITS OWN CLOCK ─────────────────────────
   * Every rat is born with a metabolism of its own, and a litter's
   * pups do not come out equally hungry — so a nest does not act in
   * one beat. */
  {
    const metabs = new Set();
    for (let i = 0; i < 12; i++) {
      const p = new Pest({ kind: 'rat' });
      ok(p.metab >= T.METAB_MIN && p.metab <= T.METAB_MAX, `rat ${i}: metabolism ${p.metab.toFixed(2)} in range`);
      metabs.add(p.metab.toFixed(3));
    }
    ok(metabs.size >= 10, `twelve rats, ${metabs.size} different metabolisms`);
    const back = Pest.deserialise(JSON.parse(JSON.stringify(new Pest({ kind: 'rat', metab: 1.1 }).serialise())));
    ok(back.metab === 1.1, 'and it is saved with the rat');

    // Through pestTick: two rats, same start, different metabolisms.
    const sh = hull();
    const a = rat(sh, 'r_weapons', { fullness: 90, metab: 0.8 });
    const b = rat(sh, 'r_weapons', { fullness: 90, metab: 1.25 });
    for (let i = 0; i < 300; i++) sh.pestTick(0.1);
    ok(b.fullness < a.fullness - 1,
       `the quicker one gets hungry first (${a.fullness.toFixed(1)} vs ${b.fullness.toFixed(1)})`);

    // A litter: the pups do not all come out on the same stomach.
    const sh2 = hull();
    sh2.cargo.add('ration_pack').qty = 20;
    const mum = rat(sh2, 'r_weapons', { level: 2, fullness: 0 });
    for (let i = 0; i < 20 && sh2.pests.filter(p => p.isRat).length < 3; i++) sh2.pestTick(0.5);
    const pups = sh2.pests.filter(p => p.isRat && p !== mum);
    ok(pups.length >= 2, `a breeding rat had a litter (${pups.length})`);
    ok(pups.every(p => p.fullness >= T.PUP_FULL_MIN && p.fullness <= 100) &&
       new Set(pups.map(p => p.fullness.toFixed(2))).size === pups.length,
       `and every pup is fed differently (${pups.map(p => p.fullness.toFixed(0)).join(', ')})`);
  }

  /* ── 2. AN ADULT DROPS OR CHEWS — ONE CLOCK, A COIN ───────
   * Through pestTick with the coin forced both ways: over a man and
   * angry it sometimes drops on him, otherwise it chews the loom. */
  {
    const setup = () => {
      const sh = hull();
      const sys = sh.getSystem('weapons');
      const man = new CrewMember({ name: 'Under', race: 'phoenix' });
      sh.addCrew(man); standIn(sh, man, sys.roomId);
      const r = rat(sh, sys.roomId, { level: 3, fullness: 5 });
      r._chewT = 0.05;                            // its clock is up
      return { sh, sys, man, r };
    };
    {
      const { sh, sys, r } = setup();
      withRandom(0.0, () => sh.pestTick(0.1));     // the coin says drop
      ok(!!r._pounce, 'the coin says drop: it goes for the man');
      ok(sys.damagedLevels === 0, 'nothing chewed this time');
    }
    {
      const { sh, sys, man } = setup();
      withRandom(0.99, () => sh.pestTick(0.1));    // the coin says chew
      ok(sys.damagedLevels === 1, 'the coin says chew: one level of the loom goes');
      ok(man.hp === man.maxHp, 'and nobody is bitten');
    }
    {
      // Nobody under it: it chews, whatever the coin.
      const sh = hull();
      const sys = sh.getSystem('weapons');
      const r = rat(sh, sys.roomId, { level: 3, fullness: 5 });
      r._chewT = 0.05;
      withRandom(0.0, () => sh.pestTick(0.1));
      ok(sys.damagedLevels === 1, 'with nobody below, an angry adult chews');
    }
    ok(T.DROP_SHARE > 0 && T.DROP_SHARE < 1, `and a drop is a share of its moves, not all (${T.DROP_SHARE})`);
  }

  /* ── 3. A DROP CAN MISS ──────────────────────────────────
   * The same bite for a rat and a spider: sometimes it only tries. */
  {
    const bitesOf = (kind, roll) => {
      const sh = hull();
      const room = R(sh, 'r_crew1');
      const man = new CrewMember({ name: 'Target', race: 'phoenix' });
      sh.addCrew(man); standIn(sh, man, room.id);
      const p = kind === 'rat'
        ? rat(sh, room.id, { level: 3, fullness: 5 })
        : sh.addPest(new Pest({ kind: 'spider', roomId: room.id, x: room.cx }));
      p._moveT = 1e9;
      sh._startDrop(p, man);
      const realRandom = Math.random;
      Math.random = () => roll;
      try { for (let i = 0; i < 30; i++) { sh.pestTick(0.05); standIn(sh, man, room.id); } }
      finally { Math.random = realRandom; }
      return man.maxHp - man.hp;
    };
    ['rat', 'spider'].forEach(kind => {
      ok(bitesOf(kind, 0.0) > 0, `a ${kind} that lands bites`);
      ok(bitesOf(kind, 0.999) === 0, `a ${kind} that misses does not`);
    });
    ok(PEST_TUNING.BITE_HIT > 0.3 && PEST_TUNING.BITE_HIT < 1, `it lands ${Math.round(PEST_TUNING.BITE_HIT * 100)}% of the time`);
  }

  /* ── 4. THE BREEDING RAT SHORTS A LOOM — IN A FIGHT, HUNGRY ─ */
  {
    const run = (fighting, food) => {
      const sh = hull();
      if (food) sh.cargo.add('ration_pack').qty = 20;
      const sys = sh.getSystem('weapons');
      const man = new CrewMember({ name: 'Gunner', race: 'phoenix' });
      sh.addCrew(man); standIn(sh, man, sys.roomId);
      // Fed well enough not to eat (a meal would grow it out of the case).
      const mid = rat(sh, sys.roomId, { level: 2, fullness: food ? 80 : 20 });
      const said = [];
      const realNotify = UI.notify, realActive = CombatManager.isActive;
      UI.notify = (m) => said.push(String(m));
      CombatManager.isActive = () => fighting;
      let shorted = 0;
      try {
        for (let i = 0; i < (T.SHORT_MAX + 2) * 10; i++) {
          sh.pestTick(0.1);
          if (sys.stunLeft > 0) shorted++;
          sh.pests.forEach(p => { if (p.isRat) p.fullness = Math.max(p.fullness, 20); });
        }
      } finally { UI.notify = realNotify; CombatManager.isActive = realActive; }
      ok(mid.level === 2, `still a breeding rat at the end (${food ? 'fed' : 'hungry'})`);
      return { shorted, said, sys, man };
    };
    const f = run(true, false);
    ok(f.shorted > 0, 'in a fight, with nothing to eat, a breeding rat shorts the loom under it');
    ok(f.said.some(m => /shorted/.test(m)), `and the player is told (${f.said.find(m => /shorted/.test(m))})`);
    ok(f.sys.damagedLevels === 0, 'a short is not a chew: the module comes back');
    ok(run(false, false).shorted === 0, 'out of a fight it does not');
    ok(run(true, true).shorted === 0, 'nor with food in the hold');
  }

  /* ── 5. RAT WRECKS ────────────────────────────────────────
   * About one wreck in three has rats instead of sacs: grown and
   * breeding rats, hungry, and a leaner hold. */
  {
    const w = makeDerelict(3);
    const rats = populateDerelict(w, 3, 'rat');
    ok(rats.length >= 2 && rats.every(p => p.isRat && p.level >= 2 && p.fullness <= 30),
       `a rat wreck: ${rats.length} rats, grown and hungry`);
    ok(new Set(rats.map(p => p.roomId)).size === rats.length, 'one to a compartment');
    ok(w.nestKind === 'rat', 'and the wreck knows what it has');
    const sp = populateDerelict(makeDerelict(3), 3);
    ok(sp.every(p => p.isSpider && p.dormant), 'without a kind it is the spider nest, as before');

    let ratty = 0;
    for (let i = 0; i < 400; i++) if (sb.derelictNestKind() === 'rat') ratty++;
    ok(ratty > 90 && ratty < 190, `about a third of wrecks are rat wrecks (${ratty}/400)`);

    // A leaner hold: fewer crates, shorter stacks.
    const crates = (g) => g.items.filter(it => it.def?.kind !== 'tablet').length;
    let full = 0, lean = 0, leanMost = 0;
    for (let i = 0; i < 200; i++) {
      full += crates(makeWreckGrid(3, { tries: 4, cols: 6, rows: 6 }));
      const n = crates(makeWreckGrid(3, { tries: 4, cols: 6, rows: 6, lean: true }));
      lean += n; leanMost = Math.max(leanMost, n);
    }
    ok(leanMost <= 3, `the rats have had a crate of it: never more than 3 of 4 (${leanMost})`);
    ok(lean < full, `and less in all (${lean} vs ${full} crates in 200 holds)`);

    // Through the game: boarding a rat wreck says so, and the loot is lean.
    const player = new Ship('frigate', true, 80, 120);
    player._allocateDefaultPower();
    makeStartingCrew().forEach(c => player.addCrew(c));
    G.playerShip = player;
    const said = [];
    const realNotify = UI.notify;
    UI.notify = (m) => said.push(String(m));
    try {
      quiet(() => {
        G._startWreckBoarding(3, { nest: 'rat' });
      });
    } finally { UI.notify = realNotify; }
    ok(G.enemyShip.pests.length >= 2 && G.enemyShip.pests.every(p => p.isRat),
       'boarding a rat wreck puts rats in her ducts');
    ok(said.some(m => /squeak/i.test(m)), `and the dock says so (${said[said.length - 1]})`);
  }

  /* ── 6. A RAT ON A WRECK DROPS ON A BOARDER TOO ───────────
   * The same rule on a wreck as aboard: the man standing under it. */
  {
    let bitten = 0;
    for (let k = 0; k < 8 && !bitten; k++) {
      const w = makeDerelict(3);
      const [r] = populateDerelict(w, 3, 'rat');
      r.level = 3; r.fullness = 5; r._moveT = 1e9;
      const b = makeStartingCrew()[0];
      w.addCrew(b, true);
      standIn(w, b, r.roomId);
      const hp0 = b.hp;
      for (let i = 0; i < 1500 && !bitten; i++) {
        w.update(0.1);
        standIn(w, b, r.roomId);
        r.fullness = 5;
        if (b.hp < hp0) bitten++;
      }
    }
    ok(bitten > 0, 'a hungry rat on a wreck drops on the boarder under it');
  }

  /* ── 7. THE PUMPS BRING A FLAT SHIP BACK ──────────────────
   * The player's report: the rats breathed her flat, they died, O2
   * went back on at two — and the gauge sat on 0. The duct over an
   * empty room bled away whatever the pumps put in, so the room never
   * got its turn. It bleeds only while there is a hole now. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    for (let i = 0; i < 3; i++) sh.addCrew(new CrewMember({ name: 'Air' + i, race: 'phoenix' }));
    sh.oxygen._rooms.forEach(r => { r.level = 0; if (r.duct != null) r.duct = 0; });
    ok(sh.getSystem('oxygen').effectivePower() === 2, 'life support on two');
    for (let i = 0; i < 600; i++) sh.update(0.1);
    const avg = sh.oxygen.averageO2();
    ok(avg > 0.3, `a minute later the air is coming back (${Math.round(avg * 100)}%)`);
    let flat = 0;
    sh.oxygen._rooms.forEach(r => { if (r.level <= 0) flat++; });
    ok(flat === 0, `and no compartment is still flat (${flat})`);

    // …and a hole still does what it did: the room first, then the duct.
    // (Pumps off, so the module cannot keep one open lock topped up.)
    const sh2 = new Ship('frigate', true, 0, 0);
    sh2._allocateDefaultPower();
    const o2b = sh2.getSystem('oxygen');
    o2b.damagedLevels = o2b.level;              // wrecked: the reactor cannot put it back
    sh2.update(0.1);
    ok(o2b.effectivePower() === 0, 'second hull: pumps wrecked');
    const lock = sh2.doors.find(d => d.isAirlock);
    lock.open = true; lock.openness = 1; lock.mode = 'open';
    sh2.doors.forEach(d => { if (!d.isAirlock) { d.mode = 'closed'; d.open = false; d.openness = 0; } });
    const ro = sh2.oxygen.getRoom(lock.roomA);
    for (let i = 0; i < 300; i++) sh2.update(0.1);
    ok(ro.level <= OXYGEN.ROOM_EMPTY && ro.duct < 0.05,
       `an open airlock still empties the room and the duct over it (${ro.level.toFixed(2)} / ${ro.duct.toFixed(2)})`);
    const leak = sh2.oxygen.leakingRooms(sh2);
    ok(leak.has(lock.roomA), 'that compartment is leaking');
    const inner = sh2.doors.find(d => !d.isAirlock && (d.roomA === lock.roomA || d.roomB === lock.roomA));
    if (inner) {
      const other = inner.roomA === lock.roomA ? inner.roomB : inner.roomA;
      inner.open = false;
      ok(!sh2.oxygen.leakingRooms(sh2).has(other), 'the next one, behind a shut door, is not');
      inner.open = true;
      ok(sh2.oxygen.leakingRooms(sh2).has(other), 'open the door and it is');
    }
  }

  /* ── 8. THE HANGAR PICTURE RUNS NO CLOCKS ─────────────────
   * The player's report: an egg case "hatched" at the dock, with a
   * pile of notices, and later it was gone. Two bugs: the base's
   * preview of the hull ran the ducts and the egg clock with the real
   * notices; and the launch threw the ship's own hold away. */
  {
    const sb2 = loadEngine();
    const { Save: S2, Base: B2, BaseScreen: BS2, Game: G2, UI: UI2 } = sb2;
    const T2 = G2.__test;
    S2.load();
    B2.earn(2000);
    B2.hireRecruit();
    const ctx = initRenderer(sb2);
    quiet(() => {
      BS2.open();
      launchNow(BS2);
      T2._startContract(BS2.consumeLaunch());
    });
    const ship = T2.playerShip;
    const egg = ship.cargo.add('spider_egg', { name: 'Nobody', roomId: ship.rooms[0].id, x: ship.rooms[0].cx, hatchT: 1.5 });
    ok(!!egg, 'an egg case in the hold');
    const r0 = ship.rooms.find(r => r.system) ?? ship.rooms[0];
    ship.addPest(new sb2.Pest({ kind: 'rat', roomId: r0.id, x: r0.cx, level: 3, fullness: 1 }));
    quiet(() => T2._finishContract());
    const data = B2.ships()[0]?.data;
    ok(data && (data.cargo?.items ?? []).some(it => it.defKey === 'spider_egg'), 'the case came home in her hold');
    ok((data?.pests ?? []).some(p => p.kind === 'rat'), 'and so did the rat');

    const said = [];
    const realNotify = UI2.notify;
    const realDes = sb2.Ship.deserialise;
    const built = [];
    UI2.notify = (m) => said.push(String(m));
    sb2.Ship.deserialise = function (...a) { const s = realDes.apply(this, a); built.push(s); return s; };
    try {
      quiet(() => { BS2.open(); BS2._act('building', 'HANGAR'); for (let i = 0; i < 3; i++) BS2.draw(ctx); });
    } finally { UI2.notify = realNotify; sb2.Ship.deserialise = realDes; }
    ok(!said.some(m => /egg|spider|duct|chew|rat/i.test(m)),
       `the hangar picture says nothing about the ducts (${said.join(' | ') || 'silent'})`);
    const pic = built.find(s => s.isPreview);
    ok(!!pic, 'the hangar drew a picture of her');
    const picEgg = pic?.cargo.items.find(it => it.def?.tag === 'egg');
    ok(picEgg && picEgg.meta.hatchT === 1.5, `and in the picture the case has not aged (${picEgg?.meta.hatchT})`);
    ok(pic?.pests.some(p => p.isRat && p.fullness === 1), 'nor has the rat');
    const after = B2.ships()[0]?.data;
    ok((after?.cargo?.items ?? []).some(it => it.defKey === 'spider_egg'), 'and the case is still in her hold');

    quiet(() => {
      BS2.open();
      launchNow(BS2);
      T2._startContract(BS2.consumeLaunch());
    });
    ok(T2.playerShip.cargo.items.some(it => it.def?.tag === 'egg'),
       'launch again: the egg case is aboard, not thrown out with the old hold');
    ok(T2.playerShip.pests.some(p => p.isRat), 'and the rat is still in the ducts');

    /* A FULL PACKED HOLD. The case still flies; a crate it pushes out
       goes back on the warehouse shelf, and the player is told. */
    quiet(() => T2._finishContract());
    const cols = sb2.SHIP_LAYOUTS[B2.ships()[0].key].cargoCols;
    const rows = sb2.SHIP_LAYOUTS[B2.ships()[0].key].cargoRows;
    const packed = new sb2.CargoGrid(cols, rows);
    while (packed.add('plating')) { /* fill it */ }
    const packedN = packed.items.length;
    B2.commitPackedHold(packed);
    const shelfBefore = B2.warehouseGrid().items.length;
    const said2 = [];
    UI2.notify = (m) => said2.push(String(m));
    try {
      quiet(() => {
        BS2.open();
        launchNow(BS2);
        T2._startContract(BS2.consumeLaunch());
      });
    } finally { UI2.notify = realNotify; }
    const hold2 = T2.playerShip.cargo;
    ok(hold2.items.some(it => it.def?.tag === 'egg'), 'with the packed hold full, the egg case still flies');
    ok(hold2.items.length < packedN + 1 && B2.warehouseGrid().items.length > shelfBefore,
       `and what it pushed out went back on the shelf (${B2.warehouseGrid().items.length - shelfBefore})`);
    ok(said2.some(m => /back on the shelf/.test(m)), `and the player is told (${said2.find(m => /egg/.test(m))})`);
  }
  {
    // The flag itself: a preview hull runs no pest, hunger or egg clock.
    const sh = hull();
    sh.isPreview = true;
    const egg = sh.cargo.add('spider_egg', { hatchT: 0.2 });
    const r = rat(sh, 'r_weapons', { fullness: 50 });
    const man = new CrewMember({ name: 'Model', race: 'phoenix' });
    sh.addCrew(man);
    const h0 = man.hunger;
    for (let i = 0; i < 40; i++) sh.update(0.05);
    ok(sh.cargo.items.includes(egg) && egg.meta.hatchT === 0.2, 'a preview hull does not age the egg case');
    ok(r.fullness === 50, 'nor the rat');
    ok(man.hunger === h0, 'nor the men');
  }
})();

// ============================================================
section('272. The vent network: one open lock drains the ship; lifts run on spare power, from the left');
// ============================================================
(function testUpdate90VentsAndLifts() {
  const sb = loadEngine();
  const { Ship, CrewMember, Pest, Save, OXYGEN, RAT_TUNING, SUIT_AIR, Renderer,
          makeDerelict, makeStartingCrew } = sb;
  Save.load(); Save.startRun();
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const T = OXYGEN.DUCT_THIN;
  /** ALL the air aboard: every room, every duct at its volume, every shaft. */
  const totalAir = (sh) => [...sh.oxygen._rooms.values()]
    .reduce((a, o) => a + o.level + (o.duct != null ? o.duct / T : 0), 0);
  const avg = (sh) => sh.oxygen.averageO2();

  /* A frigate with ONE airlock held open and every other door shut —
     re-applied each frame, because crew and the door logic both touch
     doors. `pumps`: 0 = life support wrecked, otherwise its power. */
  const venting = ({ pumps = 0, men = 0 } = {}) => {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sh.reactor.level = 16;
    const o2 = sh.getSystem('oxygen');
    if (!pumps) o2.damagedLevels = o2.level;
    else { o2.level = Math.max(o2.level, pumps); sh.setPower('oxygen', pumps); }
    for (let i = 0; i < men; i++) {
      const c = new CrewMember({ name: 'Air' + i, race: 'phoenix' });
      sh.addCrew(c);
      c.hp = c.maxHp = 1e9;          // they are here to breathe, not to die
    }
    const lock = sh.doors.find(d => d.isAirlock && d.roomA === 'r_engines');
    const hold = () => sh.doors.forEach(d => {
      const o = d === lock;
      d.mode = o ? 'open' : 'closed'; d.open = o; d.openness = o ? 1 : 0;
    });
    hold();
    const run = (secs) => quiet(() => {
      for (let i = 0; i < Math.round(secs / 0.1); i++) { sh.update(0.1); hold(); }
    });
    return { sh, lock, run, hold };
  };

  /* ── 1. ONE OPEN LOCK EMPTIES THE WHOLE SHIP — SLOWLY ────
   * The player's test of 89: two pips held an open airlock for ever,
   * because behind shut doors nothing was ever lost. Now the ducts are
   * one network, and the player's figure is about two minutes. */
  {
    const { sh, run } = venting();
    const full = avg(sh);
    const far = sh.oxygen.getRoom('r_crew3');     // top deck, far side: four links away
    const next = sh.oxygen.getRoom('r_weapons');  // the room beside it, door SHUT
    run(30);
    ok(next.level < 0.95, `the room beside the lock loses air through the ducts, door shut (${next.level.toFixed(2)})`);
    run(30);
    const a60 = avg(sh);
    ok(a60 < full * 0.75 && a60 > 0.15,
       `a minute in, the ship is going but not gone (${Math.round(a60 * 100)}%)`);
    ok(far.level < 0.9, `even the far room on the top deck is losing it (${far.level.toFixed(2)})`);
    run(90);
    ok(avg(sh) < 0.1, `two and a half minutes in, she is empty (${Math.round(avg(sh) * 100)}%)`);
    ok(sh.oxygen.getRoom('shaft_ev1').level < 0.3,
       `and the lift shaft, behind its shut doors, with it (${sh.oxygen.getRoom('shaft_ev1').level.toFixed(2)})`);
  }
  {
    // Not too fast either: "powoli". Half a minute in, most of it is still there.
    const { sh, run } = venting();
    run(30);
    ok(avg(sh) > 0.45, `half a minute in, most of the air is still aboard (${Math.round(avg(sh) * 100)}%)`);
  }

  /* ── 2. THE PUMPS HOLD IT ONLY IF THEY MAKE ENOUGH ───────── */
  {
    const two = venting({ pumps: 2, men: 3 });
    two.run(300);
    ok(avg(two.sh) < 0.55,
       `three men, two pips: the pumps do not keep up with an open lock (${Math.round(avg(two.sh) * 100)}%)`);
    const four = venting({ pumps: 4, men: 3 });
    four.run(300);
    ok(avg(four.sh) > 0.7,
       `four pips do (${Math.round(avg(four.sh) * 100)}%)`);
    ok(avg(four.sh) > avg(two.sh) + 0.2, 'and the difference is plain');
  }

  /* ── 3. THE NETWORK MAKES NOTHING AND LOSES NOTHING ───────
   * No hole, no mouths, no pumps: whatever the ducts and grilles move,
   * the ship's air is the same at the end as at the start — shafts in. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    const o2 = sh.getSystem('oxygen');
    o2.damagedLevels = o2.level;
    let k = 0;
    sh.oxygen._rooms.forEach(o => {
      o.level = [0.9, 0.2, 0.6, 0.05, 1, 0.4][k % 6];
      if (o.duct != null) o.duct = [0.1, 1, 0.3, 0.8, 0][k % 5];
      k++;
    });
    sh.doors.forEach(d => { d.mode = 'closed'; d.open = false; d.openness = 0; });
    const before = totalAir(sh);
    for (let i = 0; i < 300; i++) sh.oxygen.update(0.1, sh);
    const after = totalAir(sh);
    ok(Math.abs(after - before) < 1e-6, `thirty seconds of network: not a breath made or lost (${before.toFixed(4)} → ${after.toFixed(4)})`);
    const ducts = sh.rooms.map(r => sh.oxygen.getRoom(r.id).duct);
    ok(Math.max(...ducts) - Math.min(...ducts) < 0.05,
       `and the ducts have levelled out between them (${Math.min(...ducts).toFixed(2)}–${Math.max(...ducts).toFixed(2)})`);
  }

  /* ── 4. THE GRAPH: SIDEWAYS OVER THE DOORS, UP AND DOWN THE SHAFT ── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    const pairs = sh.oxygen.ventPairs(sh).map(p => p.slice().sort().join('|'));
    ok(pairs.includes(['r_engines', 'r_weapons'].sort().join('|')), 'linked beside each other on a deck');
    ok(pairs.includes(['r_engines', 'r_piloting'].sort().join('|')), 'and up the lift shaft to the deck above');
    ok(!pairs.includes(['r_engines', 'r_crew1'].sort().join('|')), 'one deck per hop, as the rats go');
    ok(new Set(pairs).size === pairs.length, `each pair once (${pairs.length})`);
    const shafts = sh.oxygen.ventShafts(sh);
    ok(shafts.length === 2 && shafts.every(([id, rs]) => /^shaft_/.test(id) && rs.length >= 4),
       `both shafts on the network, each with the rooms on it (${shafts.map(s => s[1].length).join(', ')})`);
  }

  /* ── 5. THE GRILLE ONLY DRAWS UP ──────────────────────────
   * A room above its duct gives to it; a room below a full duct does not
   * take from it — the pumps put air in, the grille only lets it out
   * towards a hole. That is what keeps the 86b rules. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    const a = sh.oxygen.getRoom('r_weapons');
    const m = sh.oxygen._grille.bind(sh.oxygen);
    a.level = 0.9; a.duct = 0.1;
    m(a, a, 1, 0.1);
    ok(a.level < 0.9 && a.duct > 0.1, `a full room under a dry duct gives to it (${a.level.toFixed(3)} / ${a.duct.toFixed(3)})`);
    a.level = 0.1; a.duct = 0.9;
    m(a, a, 1, 0.1);
    ok(a.level === 0.1 && a.duct === 0.9, 'an empty room under a full duct takes nothing through the grille');
    // …and never past level: one huge step stops where the two stand even.
    a.level = 1; a.duct = 0;
    m(a, a, 1000, 1);
    ok(Math.abs(a.level - a.duct) < 1e-9, `a big step stops at level (${a.level.toFixed(3)} / ${a.duct.toFixed(3)})`);
    ok(Math.abs(a.level + a.duct / T - 1) < 1e-9, 'with the air it started with');
  }

  /* ── 6. A ROOM OPEN TO SPACE IS NOT FED BY THE PUMPS ──────
   * Its share used to go into nothing. One stale room and one vented
   * one, a pip of surplus: the stale room gets ALL of it. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh._allocateDefaultPower();
    sh.crew.length = 0;
    const o2 = sh.getSystem('oxygen');
    o2.power = 1; o2.desiredPower = 1;
    sh.doors.forEach(d => { d.mode = 'closed'; d.open = false; d.openness = 0; });
    sh.getRoomById('r_engines').isVacuum = true;
    const stale = sh.oxygen.getRoom('r_crew3');
    stale.level = 0.5;
    const pairs = sh._ventPairs, shafts = sh._ventShafts;
    sh._ventPairs = []; sh._ventShafts = [];     // the pumps alone
    const before = stale.level;
    try { for (let i = 0; i < 10; i++) sh.oxygen.update(0.1, sh); }
    finally { sh._ventPairs = pairs; sh._ventShafts = shafts; sh.getRoomById('r_engines').isVacuum = false; }
    const got = stale.level - before, made = OXYGEN.PER_POWER * 1;
    ok(Math.abs(got - made) < made * 0.02,
       `the stale room gets the whole pip, not half of it (${got.toFixed(4)} of ${made.toFixed(4)})`);
  }

  /* ── 7. A WISP IS NOT AIR ─────────────────────────────────
   * The network empties a room the way a tank empties — ever more
   * slowly — so "nothing to breathe" is below ROOM_EMPTY, for the man
   * in the room and the rat in the duct alike. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    const ro = sh.oxygen.getRoom('r_weapons');
    const man = new CrewMember({ name: 'Gasping', race: 'phoenix' });
    sh.addCrew(man);
    const r = sh.getRoomById('r_weapons');
    man.roomId = r.id; man.inRoom = true; man.x = r.cx;
    ro.level = OXYGEN.ROOM_EMPTY * 0.8;
    man.air = man.airMax();
    for (let i = 0; i < 20; i++) { ro.level = OXYGEN.ROOM_EMPTY * 0.8; ro.update(0.1, 0, 0, false, [man], true, false); }
    ok(man.air < man.airMax(), `a man in a room at ${(OXYGEN.ROOM_EMPTY * 80).toFixed(1)}% is on his bottle (${man.air.toFixed(1)} of ${man.airMax()})`);
    ro.level = 0.2; man.air = man.airMax() - 1;
    ro.update(0.1, 0, 0, false, [man], true, false);
    ok(man.air > man.airMax() - 1, 'at 20% he breathes the room');

    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: 'r_weapons', x: r.cx, level: 3 }));
    rat._moveT = 1e9;
    for (let i = 0; i < 20; i++) { ro.duct = OXYGEN.ROOM_EMPTY * 0.8; sh.pestTick(0.1); }
    ok(rat.air < RAT_TUNING.AIR_SECONDS, `a rat in a duct at the same wisp holds its breath (${rat.air.toFixed(1)})`);
    for (let i = 0; i < 20; i++) { ro.duct = 0.2; sh.pestTick(0.1); }
    ok(rat.air === RAT_TUNING.AIR_SECONDS, 'and at 20% it breathes again');
  }

  /* ── 8. A RAT OVER THE OPEN LOCK STILL DIES ───────────────
   * The duct over the hole is where the network empties out — air goes
   * THROUGH it, it does not stay — so a rat up there dies as in 86b. */
  {
    const { sh, run } = venting();
    const rat = sh.addPest(new Pest({ kind: 'rat', roomId: 'r_engines', x: sh.getRoomById('r_engines').cx, level: 3 }));
    rat._moveT = 1e9;
    let t = 0;
    while (!rat.dead && t < 40) { run(0.5); t += 0.5; }
    ok(rat.dead, `a rat over an open airlock suffocates (${t}s)`);
    const far = sh.addPest(new Pest({ kind: 'rat', roomId: 'r_crew3', x: sh.getRoomById('r_crew3').cx, level: 3 }));
    far._moveT = 1e9;
    ok(!far.dead, 'one in the far duct is still breathing then');
  }

  /* ══ LIFTS ════════════════════════════════════════════════ */
  const lifts = (sh) => [...sh.elevators.shafts].sort((a, b) => a.x - b.x);

  /* ── 9. THE DEFAULT SPLIT KEEPS THE LEFT LIFT ─────────────
   * The player's call for the 8-unit frigate with two lifts: the engines
   * keep their one, the LEFT lift gets a unit, the guns pay — 1 of 2. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    const p = (t) => sh.getSystem(t).power;
    ok(p('oxygen') === 2 && p('piloting') === 1 && p('shields') === 2,
       `air, helm and shields full (${p('oxygen')}/${p('piloting')}/${p('shields')})`);
    ok(p('engines') === 1, `the engines keep the one a jump needs (${p('engines')})`);
    ok(p('weapons') === 1, `the guns pay — 1 of 2 (${p('weapons')})`);
    ok(sh.availablePower() === 1, `one unit left spare (${sh.availablePower()})`);
    sh.update(0.05);
    const [L, R] = lifts(sh);
    ok(L.powered === true && R.powered === false, `the LEFT lift is lit, the right one dark (${L.powered}/${R.powered})`);
    ok(sh.liftsPowered() === 1, 'one lift running');
    const scout = new Ship('scout', true, 0, 0);
    scout.update(0.05);
    ok(scout.elevators.shafts.every(s => s.powered), 'a scout\'s single lift is lit from the start');
    ok(scout.getSystem('engines').power >= 1, 'and she can still jump');
  }

  /* ── 10. FROM THE LEFT, WHATEVER ORDER THE LIST IS IN ───── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.elevators._shafts.reverse();               // the right one first in the list
    const w = sh.getSystem('weapons');
    sh.setPower('weapons', 0);                    // two spare
    sh.update(0.05);
    ok(lifts(sh).every(s => s.powered), 'two spare units: both lifts lit');
    sh.setPower('weapons', 1);                    // one spare
    sh.update(0.05);
    const [L, R] = lifts(sh);
    ok(L.powered && !R.powered, 'one spare: the LEFT one, though it is second in the list');
    sh.setPower('weapons', 2);                    // none spare
    sh.update(0.05);
    ok(lifts(sh).every(s => !s.powered), `none spare: both dark (${sh.availablePower()} spare)`);
    sh.setPower('weapons', 1);
    sh.reactor.offline = true;                    // scrammed
    sh.update(0.05);
    ok(lifts(sh).every(s => !s.powered), 'a scrammed reactor lights no lift');
    sh.reactor.offline = false;
    void w;
  }

  /* ── 11. A DARK LIFT TAKES NOBODY NEW ─────────────────── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.update(0.05);
    const [L, R] = lifts(sh);
    ok(!R.isUsable(), 'the dark lift is not usable');
    ok(!R.moveCabinTo(2), 'its cabin cannot be called');
    ok(!R.board(new CrewMember({}), 1), 'nobody gets on');
    const y0 = sh.getRoomById('r_shields'), y2 = sh.getRoomById('r_crew3');
    const route = sh.elevators.findPath(y0.cx, sh.floorWalkY(0, y0.cy), sh.floorWalkY(2, y2.cy));
    ok(route && route.shaft === L, 'a man on the right goes round to the lit lift on the left');
    sh.setPower('weapons', 2); sh.update(0.05);
    ok(!sh.elevators.findPath(y0.cx, sh.floorWalkY(0, y0.cy), sh.floorWalkY(2, y2.cy)),
       'with every lift dark there is no way up');
  }

  /* ── 12. A DARK LIFT STOPS WHERE IT IS (update90a) ─────────
   * update90 let a ride under way finish; the player: "powinna stanąć,
   * a jeżeli jest załogant, to on tam utknie dopóki prąd nie będzie".
   * Cut the power with a man in the cabin: the cabin stops, he stays in
   * it, and when the power comes back he is carried on and walks off. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.crew.length = 0;
    const man = new CrewMember({ name: 'Rider', race: 'phoenix' });
    sh.addCrew(man, true);
    const from = sh.getRoomById('r_engines'), to = sh.getRoomById('r_crew1');
    man.roomId = from.id; man.inRoom = true; man.x = from.cx; man.y = sh.floorWalkY(0, from.cy);
    man.homeRoomId = to.id;
    sh.update(0.05);
    ok(man.moveToOnShip(sh, to.cx, sh.floorWalkY(2, to.cy)), 'he sets off for the top deck');
    quiet(() => { for (let i = 0; i < 400 && !man._ridingShaft; i++) sh.update(0.05); });
    const shaft = man._ridingShaft;
    ok(!!shaft, 'he is in the cabin');
    quiet(() => { for (let i = 0; i < 4; i++) sh.update(0.05); });   // a little way up
    sh.reactor.offline = true;                    // the lights go
    quiet(() => sh.update(0.05));
    const y0 = shaft._cabinY;
    quiet(() => { for (let i = 0; i < 200; i++) sh.update(0.05); });
    ok(lifts(sh).every(s => !s.powered), 'every lift is dark now');
    ok(Math.abs(shaft._cabinY - y0) < 0.01, `the cabin has not moved (${y0.toFixed(1)} → ${shaft._cabinY.toFixed(1)})`);
    ok(man._ridingShaft === shaft && shaft.passenger === man, 'and he is still inside it');
    ok(!shaft.moveCabinTo(0), 'nobody can send it anywhere');
    const dst = sh.getRoomById('r_engines');
    man.moveToOnShip(sh, dst.cx, sh.floorWalkY(0, dst.cy));   // ordered back down: cannot
    ok(man._ridingShaft === shaft, 'an order to get out does not get him out');
    ok(!!man._rerouteAfterRide && !man._waypoints.some(w => w.elevator && w.srcFloor === w.dstFloor),
       'the order waits for the ride to end — no route planned on a cabin that cannot turn');
    sh.reactor.offline = false;                   // power back
    quiet(() => { for (let i = 0; i < 600; i++) sh.update(0.05); });
    ok(shaft.powered, 'the lift is lit again');
    ok(!man._ridingShaft && !man._elevatorArrived, 'and he is out of it, nothing left hanging');
    ok(sh.floorAtY(man.y) !== -1, `standing on a real deck (deck ${sh.floorAtY(man.y)})`);
  }

  /* ── 13. A WRECK'S LIFTS GO BY THE SAME RULE (update90a) ──
   * Half a reactor, life support and one engine level: what is left over
   * runs the lifts, from the left, as on any ship. */
  {
    const w = makeDerelict(2, 850, 120, 'enemy_frigate');
    w.update(0.05);
    ok(w.reactor.totalPower === w.reactor.capacity - Math.floor(w.reactor.capacity / 2),
       `half the reactor works (${w.reactor.totalPower} of ${w.reactor.capacity})`);
    ok(w.getSystem('oxygen').effectivePower() >= 1 && w.getSystem('engines').effectivePower() === 1,
       'life support and one engine level are running');
    const spare = w.availablePower();
    ok(spare >= 1 && w.liftsPowered() === Math.min(w.elevators.shafts.length, spare),
       `the spare runs the lifts (${spare} spare, ${w.liftsPowered()} lit)`);
    w.systems.find(s => s.type === 'reactor').damagedLevels = w.reactor.capacity;   // shot to bits
    w.update(0.05);
    ok(w.liftsPowered() === 0, 'and with no reactor left her lifts are dark like anyone\'s');
  }

  /* ── 14. THE ENEMY KEEPS ITS LIFTS ────────────────────── */
  {
    const e = new Ship('enemy_gunship', false, 0, 0);
    e.sizeAirForCrew(4);
    e.update(0.05);
    ok(e.elevators.shafts.every(s => s.powered), 'an enemy sized for its crew has its lifts lit');
    ok(e.systems.filter(s => s.type !== 'reactor').every(s => s.power === s.maxPower),
       'and every module full, as before');
  }

  /* ── 15. AN OLD SAVE GETS ITS LIFT BACK, ONCE ─────────── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.setPower('weapons', 2);                    // how every hull was split before 90
    const data = sh.serialise();
    ok(data.lifts === 1, 'a save says it is from after 90');
    const old = JSON.parse(JSON.stringify(data));
    delete old.lifts;
    old.systems.forEach(s => { if (s.type === 'weapons') s.power = 2; });
    const back = Ship.deserialise(old, true, 0, 0);
    ok(back.availablePower() === 1, `an old frigate comes back with a unit spare (${back.availablePower()})`);
    ok(back.getSystem('weapons').power === 1, `taken from the guns (${back.getSystem('weapons').power})`);
    ok(back.getSystem('oxygen').power === 2 && back.getSystem('piloting').power === 1 &&
       back.getSystem('engines').power >= 1, 'never from air, helm, or the engines\' last unit');
    // A save written now is left exactly as the player set it.
    const mine = JSON.parse(JSON.stringify(data));
    const again = Ship.deserialise(mine, true, 0, 0);
    ok(again.getSystem('weapons').power === 2 && again.availablePower() === 0,
       'a save from after 90 keeps the player\'s own split — guns full, lifts dark');
  }

  /* ── 16. THE REACTOR BAR SAYS WHICH UNITS RUN THE LIFTS ──
   * Through the real HUD: the spare pips a lit lift is drawing are blue. */
  {
    const ctx = initRenderer(sb);
    const sh = new Ship('frigate', true, 0, 0);
    sh.update(0.05);
    /* The bar as painted (update130: it lies under the row now). */
    const pips = () => {
      quiet(() => Renderer.drawHUD({ playerShip: sh }));
      return Renderer.reactorBarRect()?.fills ?? [];
    };
    let seen = pips();
    ok(seen.filter(c => c === '#4db8ff').length === 1, `one blue pip for the one lit lift (${seen.join(',')})`);
    sh.setPower('weapons', 0); sh.update(0.05);
    seen = pips();
    ok(seen.filter(c => c === '#4db8ff').length === 2, 'two lit lifts, two blue pips');
    sh.setPower('weapons', 2); sh.update(0.05);
    seen = pips();
    ok(!seen.includes('#4db8ff'), 'none spare, none blue');
  }

  /* ── 17. A DARK LIFT SAYS SO ───────────────────────────── */
  {
    const ctx = initRenderer(sb);
    const sh = new Ship('frigate', true, 0, 0);
    sh.update(0.05);
    const said = captureText(ctx, () => quiet(() => sh.draw(ctx))).map(o => o.t);
    ok(said.filter(t => t === 'OFF').length === 1, `the one dark lift wears OFF (${said.filter(t => t === 'OFF').length})`);
    sh.setPower('weapons', 0); sh.update(0.05);
    const lit = captureText(ctx, () => quiet(() => sh.draw(ctx))).map(o => o.t);
    ok(!lit.includes('OFF'), 'and with both lit, neither does');
  }
  void SUIT_AIR; void makeStartingCrew;
})();

// ============================================================
section('273. Fixes from play (90a): the cyborg\'s unit, icons, cloak, pod badge, meals, lifts, wrecks, customs');
// ============================================================
(function testUpdate90a() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Renderer, UI, Input, Game, Station, CargoGrid,
          SectorMap, makeDerelict, Chips, Commander, CargoItem, HUNGER } = sb;
  Save.load(); Save.startRun();
  const T = Game.__test;
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  /* AT THE CONSOLE (update93a): a cyborg's +1 is the OPERATOR's, so he
     stands on slot 0, not in the middle of the room. */
  const standIn = (sh, c, id) => {
    const r = sh.getRoomById(id);
    const [sx, sy] = sh.stationSlot(r, 0);
    c.roomId = r.id; c.inRoom = true; c.x = sx; c.y = sy;
    c._waypoints = [];
  };
  const pw = (sh, t) => sh.getSystem(t).power;

  /* ── 1. THE CYBORG'S UNIT LEAVES WITH HIM ──────────────────
   * The player: a Terra at the reactor console adds a unit; he gives it
   * to a module; the cyborg walks off — and the module KEPT it, while
   * the life support at the end of the list lost one instead. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.crew.length = 0;
    const cy = new CrewMember({ name: 'Cy', race: 'terra' });
    sh.addCrew(cy, true);
    ok(cy.cyborg, 'a Terra hand is a cyborg');
    const reactorRoom = sh.getSystem('reactor').roomId;
    standIn(sh, cy, 'r_crew3'); sh.update(0.05);
    sh.setPower('weapons', 2); sh.setPower('medbay', 0); sh.update(0.05);
    ok(sh.availablePower() === 0, `every unit spent (${sh.availablePower()} spare)`);
    standIn(sh, cy, reactorRoom); sh.update(0.05);
    ok(sh.reactor.totalPower === 9 && sh.availablePower() === 1, 'at the console: a ninth unit');
    sh.setPower('engines', 2); sh.update(0.05);
    ok(pw(sh, 'engines') === 2, 'given to the engines');
    standIn(sh, cy, 'r_crew3');
    for (let i = 0; i < 3; i++) { standIn(sh, cy, 'r_crew3'); sh.update(0.05); }
    ok(sh.reactor.totalPower === 8, 'he walks off: eight again');
    ok(pw(sh, 'engines') === 1, `the engines lose the unit he gave them (${pw(sh, 'engines')})`);
    ok(pw(sh, 'oxygen') === 2, `life support at the end of the list keeps its two (${pw(sh, 'oxygen')})`);
    ok(sh.getSystem('engines').desiredPower === 2, 'the engines still ask for two');
    standIn(sh, cy, reactorRoom);
    for (let i = 0; i < 3; i++) { standIn(sh, cy, reactorRoom); sh.update(0.05); }
    ok(pw(sh, 'engines') === 2, 'he comes back: so does their second unit');
  }
  {
    // The same rule when a shot takes a reactor level: the last module powered up pays.
    const sh = new Ship('frigate', true, 0, 0);
    sh.setPower('weapons', 0); sh.setPower('medbay', 1); sh.setPower('weapons', 2);
    sh.update(0.05);
    const used = sh.systems.filter(s => s.type !== 'reactor').reduce((a, s) => a + s.power, 0);
    ok(used === 8, `all eight in use (${used})`);
    sh.getSystem('reactor').damagedLevels = 1;
    sh.update(0.05);
    ok(pw(sh, 'weapons') === 0 && pw(sh, 'medbay') === 1,
       `a reactor level lost: the guns, powered last, give their unit back (${pw(sh, 'weapons')}/${pw(sh, 'medbay')})`);
  }

  /* ── 2. RED IS BROKEN, NOT OFF ─────────────────────────── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.update(0.05);
    const med = sh.getSystem('medbay');
    ok(med.power === 0 && Renderer.moduleIconState(med) === 'off', 'an unpowered module is OFF (grey), not broken');
    const sht = sh.getSystem('shields');
    ok(Renderer.moduleIconState(sht) === 'running', 'a powered one is running (orange)');
    sht.damagedLevels = sht.level;
    ok(Renderer.moduleIconState(sht) === 'broken', 'a shot-out one is broken (red)');
    const cy = new CrewMember({ name: 'Cy', race: 'terra' });
    sh.addCrew(cy, true);
    standIn(sh, cy, med.roomId);
    sh.update(0.05);
    ok(med.power === 0 && med.effectivePower() > 0 && Renderer.moduleIconState(med) === 'running',
       'a module on a cyborg\'s +1 alone is running (orange), not off');
    // …and the bar draws it so, through the HUD: count the red icon rings.
    const ctx = initRenderer(sb);
    const rings = [];
    const realStroke = ctx.stroke;
    ctx.stroke = function () { if (ctx.lineWidth === 2) rings.push(ctx.strokeStyle); };
    try { quiet(() => Renderer.drawHUD({ playerShip: sh })); } finally { ctx.stroke = realStroke; }
    ok(rings.filter(c => c === '#663333').length === 1, `one red ring — the broken shields (${rings.filter(c => c === '#663333').length})`);
  }

  /* ── 3. A CLOAK IS A STEADY VEIL, AND IT SAYS SO ─────────── */
  {
    const e = new Ship('hauler', false, 850, 120);
    const spot = e.rooms.find(r => r.type === 'empty');
    if (spot) e.addModuleAt('cloaking', spot.id);
    const cl = e.getSystem('cloaking');
    if (cl) {
      cl.cloakActive = true; cl.cloakTimer = 4.2;
      const ctx = initRenderer(sb);
      const alphas = new Set();
      const realFill = ctx.fillRect;
      ctx.fillRect = function () { alphas.add(Math.round((ctx.globalAlpha ?? 1) * 100)); };
      const realNow = sb.performance?.now;
      const drawn = [];
      try {
        for (const t of [0, 400, 900, 1700]) {
          if (sb.performance) sb.performance.now = () => t;
          drawn.push(...captureText(ctx, () => quiet(() => e.draw(ctx))).map(d => d.t));
        }
      } finally { ctx.fillRect = realFill; if (sb.performance && realNow) sb.performance.now = realNow; }
      const pulsing = [...alphas].filter(a => a > 45 && a < 100);
      ok(pulsing.length === 0, `no pulsing opacity over the hull (${[...alphas].join(',')})`);
      /* update127 (jj): no label over a cloaked hull — it sat on the gun. */
      ok(!drawn.some(t => /CLOAK/.test(t)), `and no CLOAKED label over the hull (${drawn.filter(t => /CLOAK/.test(t))})`);
    } else {
      ok(false, 'test setup: a gunship with a cloak');
    }
  }

  /* ── 4. THE POD IS A BADGE BESIDE THE COMMANDER ────────── */
  {
    const ctx = initRenderer(sb);
    const strip = Renderer.commanderStripRect();
    const r = T._podRect();
    ok(r.x >= strip.x + strip.w && r.y === strip.y, `beside the commander strip (${r.x},${r.y})`);
    const W = Renderer.getWidth();
    const overJump = r.x + r.w > W / 2 - 80 && r.x < W / 2 + 80 && r.y < 130 && r.y + r.h > 95;
    ok(!overJump, 'and nowhere near the JUMP line it used to cover');
    const cap = Commander.fromCrew({ id: 'p9', name: 'Ewa', race: 'terra', skills: {} });
    cap.level = 8; cap.karma = 50;
    for (let i = 0; i < 3; i++) Commander.spendPoint(cap, 'intelligence');  // reads II (update99)
    for (let i = 0; i < 3; i++) Commander.spendPoint(cap, 'knowledge');     // 25: the pod's 22 (update103)
    Commander.setActive(cap); T.commander = cap; T.STATE = 'combat';
    const mx0 = Input.mouse.x, my0 = Input.mouse.y;
    Input.mouse.x = r.x + r.w / 2; Input.mouse.y = r.y + r.h / 2;
    try {
      let said = captureStyledText(ctx, () => T._drawEvac(ctx));
      ok(said.some(d => /ESCAPE POD — none/.test(d.t)), `no Re-Atum: the badge says so (${said.map(d => d.t)[0]})`);
      const b = Chips.board(cap);
      b.place(new CargoItem(Chips.itemKey('re_atum', 2)), 0, 0);
      Chips.commit(cap, b);
      said = captureStyledText(ctx, () => T._drawEvac(ctx));
      ok(said.some(d => /click to launch/.test(d.t)) && said.some(d => /10s countdown/.test(d.t)),
         'a live pod: click to launch, and how long');
      // A press on the badge fires it, through the combat update's own click chain.
      ok(T._startEvac(), 'it fires');
      said = captureStyledText(ctx, () => T._drawEvac(ctx));
      ok(said.some(d => /^POD \d+s$/.test(d.t)), 'the countdown shows beside it');
      T._tickEvac(99);
    } finally {
      Input.mouse.x = mx0; Input.mouse.y = my0;
      Commander.setActive(null); T.commander = null;
    }
    const none = captureText(ctx, () => T._drawEvac(ctx));
    ok(none.length === 0, 'no commander, no badge');
  }

  /* ── 5. EVERY NOTICE GOES TO THE LOG ON THE MAP TOO ────── */
  {
    const ctx = initRenderer(sb);
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));   // a crew, or the run is lost
    Save.startRun();
    T.sectorMap = new SectorMap(2, 7, 1, 3, true);
    T.playerShip = sh; T.enemyShip = null; T.STATE = 'map';
    if (!UI.isLogOpen()) UI.toggleLog();
    UI.notify('said on the map', 'info');
    const frame = quiet(() => captureText(Renderer.getCtx(), () => T._draw()));
    const hit = frame.filter(d => d.t === 'said on the map');
    ok(hit.length === 1 && hit[0].x > 860 && hit[0].y > 600,
       `on the sector map it is in the (shorter) log window, once (${hit.map(d => `${Math.round(d.x)},${Math.round(d.y)}`)})`);
    const tab = frame.find(d => /^LOG/.test(d.t));
    ok(tab && tab.y > 590, `the window starts below the map panel (tab at y ${tab && Math.round(tab.y)})`);
    UI.toggleLog();
    UI.notify('said while shut', 'good');
    const shut = quiet(() => captureText(Renderer.getCtx(), () => T._draw()));
    ok(!shut.some(d => d.t === 'said while shut'), 'shut, nothing pops up in the middle of the map');
    ok(shut.some(d => /LOG ▴ 1 new/.test(d.t)), 'the tab counts it');
    const realPressed = Input.isPressed;
    Input.isPressed = (code) => code === 'KeyL';
    try { quiet(() => T._updateMap(0.016)); } finally { Input.isPressed = realPressed; }
    ok(UI.isLogOpen(), 'L opens it on the map');
    const open = quiet(() => captureText(Renderer.getCtx(), () => T._draw()));
    ok(open.some(d => /LOG ▾/.test(d.t)) && !open.some(d => /^LOG ▴/.test(d.t)),
       `and the count is cleared (${open.filter(d => /^LOG/.test(d.t)).map(d => d.t)})`);
    T.STATE = 'combat';
  }

  /* ── 6. A MEAL IS ALL HE DOES ────────────────────────────── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.crew.length = 0;
    const man = new CrewMember({ name: 'Eater', race: 'phoenix' });
    sh.addCrew(man, true);
    standIn(sh, man, 'r_engines');
    const dst = sh.getRoomById('r_shields');
    ok(man.moveToOnShip(sh, dst.cx, sh.floorWalkY(0, dst.cy)), 'ordered across the deck');
    sh._startBusy(man, 'eat');
    const x0 = man.x;
    for (let i = 0; i < Math.floor((HUNGER.EAT_SECONDS - 0.5) / 0.05); i++) sh.update(0.05);
    ok(Math.abs(man.x - x0) < 0.5, `while he eats he does not take a step (${(man.x - x0).toFixed(1)}px)`);
    ok(man._waypoints.length > 0, 'and the order is kept');
    for (let i = 0; i < 400; i++) sh.update(0.05);
    ok(!man.busy && Math.abs(man.x - dst.cx) < 6, `the meal over, he goes (${Math.round(man.x)} vs ${Math.round(dst.cx)})`);
  }

  /* ── 7. A STUCK CABIN SAYS SO ──────────────────────────── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.update(0.05);
    const L = [...sh.elevators.shafts].sort((a, b) => a.x - b.x)[0];
    L.moveCabinTo(2);
    for (let i = 0; i < 6; i++) sh.update(0.05);
    ok(L._moving, 'the cabin is on its way up');
    sh.setPower('weapons', 2); sh.update(0.05);
    ok(!L.powered && L._moving, 'the power goes with the cabin between decks');
    const ctx = initRenderer(sb);
    const t = captureText(ctx, () => L.draw(ctx)).map(d => d.t);
    ok(t.includes('OFF') && !t.includes('▲') && !t.includes('▼'), `it wears OFF, not an arrow (${t})`);
  }

  /* ── 7b. A LIFT SHOT UP UNDER A RIDER STOPS TOO (update90b) ──
   * "Musi być energia i sprawna, inaczej staje." The rider waits inside;
   * repaired, the cabin goes on and he comes off with his route. */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.crew.length = 0;
    const man = new CrewMember({ name: 'Rider', race: 'phoenix' });
    sh.addCrew(man, true);
    standIn(sh, man, 'r_engines');
    const to = sh.getRoomById('r_crew1');
    sh.update(0.05);
    ok(man.moveToOnShip(sh, to.cx, sh.floorWalkY(2, to.cy)), 'off to the top deck');
    quiet(() => { for (let i = 0; i < 400 && !man._ridingShaft; i++) sh.update(0.05); });
    const shaft = man._ridingShaft;
    ok(!!shaft, 'riding');
    quiet(() => { for (let i = 0; i < 4; i++) sh.update(0.05); });
    shaft.takeDamage(shaft.maxHp);
    const y0 = shaft._cabinY;
    quiet(() => { for (let i = 0; i < 200; i++) sh.update(0.05); });
    ok(!shaft.isUsable() && Math.abs(shaft._cabinY - y0) < 0.01, 'shot up under him: the cabin stops');
    ok(man._ridingShaft === shaft, 'and he waits inside');
    shaft.repair(shaft.maxHp);
    quiet(() => { for (let i = 0; i < 600; i++) sh.update(0.05); });
    ok(!man._ridingShaft && !man._elevatorArrived, 'repaired: he is off it, nothing left hanging');
    ok(sh.floorAtY(man.y) === 2 && Math.abs(man.x - to.cx) < 6,
       `and walked on to where he was going (deck ${sh.floorAtY(man.y)}, ${Math.round(man.x)} vs ${Math.round(to.cx)})`);
  }
  {
    /* THE LIGHTS GO ON THE VERY FRAME HE ARRIVES. The cabin has let him
       go (`_elevatorArrived`) and only then does the lift go dark: he
       still steps off and walks on — the arrival is not lost. */
    const sh = new Ship('frigate', true, 0, 0);
    sh.crew.length = 0;
    const man = new CrewMember({ name: 'Late', race: 'phoenix' });
    sh.addCrew(man, true);
    standIn(sh, man, 'r_engines');
    const to = sh.getRoomById('r_crew1');
    sh.update(0.05);
    man.moveToOnShip(sh, to.cx, sh.floorWalkY(2, to.cy));
    let caught = false;
    quiet(() => {
      for (let i = 0; i < 800 && !caught; i++) { sh.update(0.02); if (man._elevatorArrived) caught = true; }
    });
    ok(caught, 'test setup: caught the frame the cabin let him go');
    sh.reactor.offline = true;
    quiet(() => { for (let i = 0; i < 400; i++) sh.update(0.05); });
    ok(!man._elevatorArrived && !man._ridingShaft, 'the lift goes dark that frame: he is still off it');
    ok(sh.floorAtY(man.y) === 2 && Math.abs(man.x - to.cx) < 6,
       `and walks on (deck ${sh.floorAtY(man.y)}, ${Math.round(man.x)} vs ${Math.round(to.cx)})`);
  }

  /* ── 8. CUSTOMS AT THE DOOR ──────────────────────────────── */
  {
    const hold = (items) => {
      const sh = new Ship('frigate', true, 0, 0);
      sh.cargo = new CargoGrid(8, 6);
      items.forEach(k => sh.cargo.add(k));
      return sh;
    };
    const port = (type) => { const st = new Station(2, 7); st.type = type; return st; };
    ['general', 'military', 'science'].forEach(type => {
      const sh = hold(['contraband', 'medkit']);
      const run = { scrap: 150 };
      const r = port(type).customs(sh, run);
      ok(r && r.seized.length === 1 && !sh.cargo.items.some(it => it.def.contraband),
         `a ${type} port seizes the contraband at the door`);
      ok(run.scrap === 50 && r.paid === 100, `and fines 100 CC from the purse (${run.scrap} left)`);
      ok(sh.cargo.items.some(it => it.defKey === 'medkit'), 'and leaves the rest of the hold alone');
    });
    {
      const sh = hold(['contraband']);
      const run = { scrap: 150 };
      ok(port('outpost').customs(sh, run) === null && sh.cargo.items.length === 1 && run.scrap === 150,
         'an outpost asks nothing — that is where it is sold');
    }
    {
      const sh = hold(['medkit']);
      ok(port('military').customs(sh, { scrap: 5 }) === null, 'no contraband, no customs');
    }
    {
      // Short of the fine: the cheapest single item that covers the rest.
      // ration 40, medkit 60, plating 34 at a general port: 40 short is
      // covered by the ration — NOT the medkit, the dearest thing aboard.
      const sh = hold(['contraband', 'ration', 'medkit', 'plating']);
      const st = port('general');
      const run = { scrap: 60 };
      const prices = sh.cargo.items.filter(it => !it.def.contraband).map(it => [it.defKey, it.value(st.type)]);
      const r = st.customs(sh, run);
      ok(run.scrap === 0 && r.paid === 60, `the purse is emptied (${r.paid} paid)`);
      const owed = 40;
      const cover = prices.filter(p => p[1] >= owed).sort((a, b) => a[1] - b[1])[0];
      ok(sh.cargo.items.some(it => it.defKey === 'medkit'), 'the dearest thing aboard is not what pays');
      if (cover) {
        ok(r.taken.length === 1 && r.taken[0].value === cover[1],
           `and one item covering the 40 CC short is taken — the cheapest that does (${r.taken.map(t => `${t.label} ${t.value}`)} of ${prices.map(p => p.join(' '))})`);
      } else {
        ok(r.taken.length >= 1 && r.taken.reduce((a, t) => a + t.value, 0) >= owed || r.unpaid > 0,
           `nothing covers it alone: the dearest go until it is paid (${r.taken.map(t => t.value)})`);
      }
    }
    {
      const sh = hold(['contraband']);
      const r = port('general').customs(sh, { scrap: 0 });
      ok(r && r.unpaid === 100 && sh.cargo.items.length === 0, 'an empty purse and an empty hold: it is simply taken');
    }
    // And the game asks customs on the way in, through a real jump to a port.
    {
      const sh = hold(['contraband', 'medkit']);
      sb.makeStartingCrew().forEach(c => sh.addCrew(c));   // a crew, or the run is simply lost
      Save.startRun();
      Save.updateRun({ scrap: 300 });
      const map = new SectorMap(2, 7, 1, 3, true);
      const start = map.startNodes[0];
      const node = map.getNode(start.next[0]);
      node.type = 'store';
      map.currentId = start.id;
      map.unlockNext();
      T.sectorMap = map; T.playerShip = sh; T.STATE = 'map';
      manCockpit(sh);
      quiet(() => T._addFuel(3));
      // The port's kind is a die roll; make it an ordinary one.
      const realPick = sb.Utils.pick;
      sb.Utils.pick = (arr) => (arr.includes?.('general') ? 'general' : realPick(arr));
      try { quiet(() => T._travelTo(node.id)); } finally { sb.Utils.pick = realPick; }
      ok(T.STATE === 'station' && T.station?.type === 'general', `the jump reached a general port (${T.STATE}/${T.station?.type})`);
      ok(!sh.cargo.items.some(it => it.def.contraband), 'docking there clears the contraband');
      ok(Save.getRun().scrap === 200, `and the fine comes out of the run's purse (${Save.getRun().scrap})`);
    }
  }
})();

// ============================================================
section('274. Fixes from play (90b): lifts stop, boarders move on, wrecks (no commander, a survivor), the nebula, the cat, fumigation');
// ============================================================
(function testUpdate90b() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Renderer, Game, Commander, makeDerelict } = sb;
  Save.load(); Save.startRun();
  const T = Game.__test;
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const boarder = (sh, roomId, name = 'Hostile') => {
    const r = sh.getRoomById(roomId);
    const c = new CrewMember({ name, isPlayer: false, race: 'phoenix' });
    c.x = r.cx; c.y = sh.floorWalkY(r.floor, r.cy); c.roomId = r.id; c.homeRoomId = r.id;
    c._ordered = false;
    sh.addCrew(c, true);
    return c;
  };
  const wreckAll = (sh, except = []) => sh.systems.forEach(s => {
    if (s.type !== 'reactor' && !except.includes(s)) s.damagedLevels = s.level;
  });

  /* ── 1. A MODULE FITTED INTO A HOLD IS A TARGET ───────────── */
  {
    const sh = new Ship('hauler', true, 0, 0);
    sh.crew.length = 0;
    ok(sh.addModuleAt('shields', 'r_hold1'), 'test setup: shields fitted into an empty hold');
    const fitted = sh.getRoomById('r_hold1');
    ok(fitted.system?.type === 'shields', 'the hold carries the shields');
    wreckAll(sh, [fitted.system]);
    const b = boarder(sh, 'r_engines');
    quiet(() => { for (let i = 0; i < 400 && b.roomId !== 'r_hold1'; i++) sh.update(0.05); });
    ok(b.roomId === 'r_hold1', `the boarder goes for the fitted shields (in ${b.roomId})`);
  }

  /* ── 2. OUT OF REACH: HE TAKES THE NEXT ONE ───────────────
   * The cockpit (high on his list) is up a dark lift; a medbay fitted
   * into a hold on his own deck (low on it) is not. He used to stand
   * waiting for the lift to the cockpit. */
  {
    const sh = new Ship('hauler', true, 0, 0);
    sh.crew.length = 0;
    ok(sh.addModuleAt('medbay', 'r_hold1'), 'test setup: a medbay in the hold on deck 0');
    wreckAll(sh, [sh.getSystem('piloting'), sh.getSystem('medbay')]);
    sh.reactor.offline = true;                     // every lift dark
    sh.update(0.05);
    ok(sh.liftsPowered() === 0, 'every lift is dark');
    const b = boarder(sh, 'r_engines');
    quiet(() => { for (let i = 0; i < 600 && b.roomId !== 'r_hold1'; i++) sh.update(0.05); });
    ok(b.roomId === 'r_hold1',
       `the cockpit is out of reach, so he goes for the medbay on his own deck (in ${b.roomId})`);
  }

  /* ── 3. NOTHING LEFT TO BREAK: HE GOES FOR THE CREW ─────── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sh.crew.length = 0;
    wreckAll(sh);
    const def = new CrewMember({ name: 'Defender', race: 'phoenix' });
    sh.addCrew(def, true);
    const dr = sh.getRoomById('r_shields');
    def.roomId = dr.id; def.inRoom = true; def.x = dr.cx; def.y = sh.floorWalkY(0, dr.cy);
    const b = boarder(sh, 'r_engines');
    // Kept wrecked every frame: the defender would otherwise patch the
    // shields up and hand the boarder a module to go for after all.
    quiet(() => { for (let i = 0; i < 600 && b.roomId !== 'r_shields'; i++) {
      def._waypoints = []; def.x = dr.cx; wreckAll(sh); sh.update(0.05); } });
    ok(b.roomId === 'r_shields', `every module wrecked: he goes for the man in the shields room (in ${b.roomId})`);
  }

  /* ── 4. NO COMMANDER ON A WRECK ─────────────────────────── */
  {
    const foe = Commander.rollEnemy(2, { level: 5, race: 'phoenix' });
    Commander.setEnemy(foe);
    const ctx = initRenderer(sb);
    const player = new Ship('frigate', true, 0, 0);
    const hulk = makeDerelict(2, 850, 120);
    const seen = captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: player, enemyShip: hulk })))
      .map(d => d.t).join('|');
    ok(!/ L5/.test(seen) && !/L5$/.test(seen), 'a stale enemy commander is not drawn over a wreck');
    T.playerShip = player;
    quiet(() => T._startWreckBoarding(2));
    ok(!Commander.enemy(), 'and boarding a wreck clears him');
    T._clearWreckMode?.();
  }

  /* ── 5. THE NEBULA ENDS WITH THE FIGHT ───────────────────── */
  {
    const player = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => player.addCrew(c));
    T.playerShip = player; T.STATE = 'map';
    quiet(() => T._startCombat('normal', true));
    ok(player.reactor.penalty === 2, 'a nebula fight: −2 on our reactor');
    quiet(() => T._onWin());
    ok(player.reactor.penalty === 0, `the fight won, the −2 is gone at once (${player.reactor.penalty})`);
  }
  /* ── 6. A FED CAT LEAVES THEM BE; PREY HAS POINTS ──────────
   * The player's figures: a young rat 5, a half-grown one 15, a grown
   * one 30, a spider 20. A cat above FED does not go up at all. */
  {
    const { Pest, HUNGER } = sb;
    const food = (cfg) => Ship.preyFood(new Pest(cfg));
    ok(food({ kind: 'rat', level: 1 }).hunger === 5 && food({ kind: 'rat', level: 2 }).hunger === 15 &&
       food({ kind: 'rat', level: 3 }).hunger === 30 && food({ kind: 'spider' }).hunger === 20,
       'prey points: rat 5/15/30, spider 20');
    const rig = (hunger) => {
      const sh = new Ship('frigate', true, 0, 0);
      sh.crew.length = 0;
      const cat = sb.makeCat('black', 'Mruk');
      sh.addCrew(cat, true);
      const r = sh.getRoomById('r_weapons');
      cat.roomId = r.id; cat.inRoom = true; cat.x = r.cx; cat.y = sh.floorWalkY(r.floor, r.cy);
      cat.hunger = hunger;
      const rat = sh.addPest(new Pest({ kind: 'rat', roomId: r.id, x: r.cx, level: 3 }));
      rat._moveT = 1e9;
      return { sh, cat, rat };
    };
    const fed = rig(HUNGER.FED + 5);
    quiet(() => { for (let i = 0; i < 200; i++) fed.sh.update(0.05); });
    ok(fed.rat.alive && fed.rat._catId == null, 'a fed cat under a rat leaves it be');
    {
      // …and does not cross the ship to one either.
      const far = rig(HUNGER.FED + 5);
      const other = far.sh.getRoomById('r_shields');
      far.rat.roomId = other.id; far.rat.x = other.cx;
      far.cat._roamT = 1e9;                      // no wandering off by chance
      quiet(() => { for (let i = 0; i < 100; i++) { far.sh.update(0.05); far.cat._roamT = 1e9; } });
      ok(far.cat.roomId === 'r_weapons' && !far.cat._waypoints.length,
         `a fed cat does not go after a rat two rooms away (in ${far.cat.roomId})`);
    }
    const hungry = rig(50);
    const h0 = hungry.cat.hunger;
    quiet(() => { for (let i = 0; i < 400 && hungry.rat.alive; i++) hungry.sh.update(0.05); });
    ok(!hungry.rat.alive, 'a cat with room for one goes up and gets it');
    ok(hungry.cat.hunger >= h0 + 30 - 2 && hungry.cat.hunger <= h0 + 30 + 0.5,
       `a grown rat feeds her about 30 (${h0.toFixed(1)} → ${hungry.cat.hunger.toFixed(1)})`);
  }

  /* ── 7. FUMIGATION AT A GENERAL OR RESEARCH PORT ──────────── */
  {
    const { Station, Pest, CargoGrid } = sb;
    const infested = () => {
      const sh = new Ship('frigate', true, 0, 0);
      sh.cargo = new CargoGrid(8, 6);
      sh.cargo.add('spider_egg');
      sh.addPest(new Pest({ kind: 'rat', roomId: 'r_weapons', x: 200 }));
      sh.addPest(new Pest({ kind: 'rat', roomId: 'r_shields', x: 330 }));
      sh.addPest(new Pest({ kind: 'spider', roomId: 'r_oxygen', x: 200 }));
      return sh;
    };
    const port = (type) => { const st = new Station(2, 7); st.type = type; return st; };
    ok(port('general').offersFumigation && port('science').offersFumigation, 'general and research ports fumigate');
    ok(!port('military').offersFumigation && !port('outpost').offersFumigation, 'fleet yards and outposts do not');
    const sh = infested();
    ok(port('general').fumigationCost(sh) === 40 + 5 * 3, `40 + 5 a head (${port('general').fumigationCost(sh)})`);
    const poor = { scrap: 30 };
    ok(!port('general').fumigate(sh, poor).ok && sh.pests.length === 3 && poor.scrap === 30, 'short of the price: nothing happens');
    const run = { scrap: 100 };
    const r = port('science').fumigate(sh, run);
    ok(r.ok && sh.pests.length === 0 && run.scrap === 45, `paid: the ducts are empty (${run.scrap} CC left)`);
    ok(sh.cargo.items.some(it => it.defKey === 'spider_egg'), 'the egg case in the hold stays');
    const no = infested();
    ok(!port('military').fumigate(no, { scrap: 999 }).ok && no.pests.length === 3, 'a fleet yard will not do it');
    // Through the station screen: the card and its button.
    Save.startRun(); Save.updateRun({ scrap: 500 });
    const live = infested();
    const st = port('general');
    sb.UI.openStation(st, live);
    sb.UI.setStationTab?.('repair');
    const find = (e, re, out = []) => {
      if (!e) return out;
      if (e.textContent && re.test(e.textContent)) out.push(e);
      (e.children || []).forEach(k => find(k, re, out));
      return out;
    };
    const root = sb.document.getElementById('station-content');
    const btn = find(root, /^CLEAR THE DUCTS/)[0];
    ok(!!btn && /55 CC/.test(btn.textContent), `the repair tab offers it (${btn && btn.textContent})`);
    if (btn) (btn._listeners.click ?? []).forEach(f => quiet(() => f({})));
    ok(live.pests.length === 0 && Save.getRun().scrap === 445, `the button clears them (${Save.getRun().scrap} CC)`);
  }

  /* ── 8. A SURVIVOR ON A WRECK ─────────────────────────────── */
  {
    const s = sb.makeSurvivor();
    ok(s.isPlayer && s.state === 'injured' && s._bandaged && s._survivor, 'a survivor is ours, down, bandaged');
    ok(Object.values(s.skills).some(k => k.level >= sb.MAX_SKILL_LEVEL),
       `and has one skill mastered (${JSON.stringify(s.skills)})`);
    ok(sb.WRECK_SURVIVOR_SHARE === 0.10, 'on one wreck in ten');

    // The roll, through the real boarding.
    const player = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => player.addCrew(c));
    T.playerShip = player;
    const realRand = Math.random;
    try {
      Math.random = () => 0.05;
      quiet(() => T._startWreckBoarding(2));
      ok(T.enemyShip.crew.some(c => c._survivor), 'a low roll: there is a survivor aboard');
      ok(!T.enemyShip.crew.some(c => c._survivor && c.roomId === T.enemyShip.dockRoomId),
         'and not in the compartment we dock at');
      Math.random = () => 0.5;
      quiet(() => T._startWreckBoarding(2));
      ok(!T.enemyShip.crew.some(c => c._survivor), 'a high roll: nobody');
    } finally { Math.random = realRand; }

    // Carried to the hatch: aboard, and on the roster.
    quiet(() => T._startWreckBoarding(2));
    const hulk = T.enemyShip;
    hulk.crew = hulk.crew.filter(c => !c._survivor);   // the 10% roll's own, if any: ours is placed by hand
    const dock = hulk.getRoomById(hulk.dockRoomId);
    ok(!!dock, `the docking compartment is known (${hulk.dockRoomId})`);
    const far = hulk.rooms.filter(r => r.id !== dock.id && r.floor === dock.floor)
      .sort((a, b) => Math.abs(b.cx - dock.cx) - Math.abs(a.cx - dock.cx))[0]
      ?? hulk.rooms.find(r => r.id !== dock.id);
    const sv = sb.makeSurvivor();
    sv.name = 'Lazarus';          // a name nobody in a starting crew can have
    sv.roomId = far.id; sv.inRoom = true; sv.x = far.cx; sv.y = hulk.floorWalkY(far.floor, far.cy);
    hulk.addCrew(sv, true);
    const man = player.crew[0];
    player.crew = player.crew.filter(c => c !== man);
    man.roomId = far.id; man.inRoom = true; man.x = far.cx + 6; man.y = hulk.floorWalkY(far.floor, far.cy);
    man._waypoints = [];
    hulk.addCrew(man, true);
    // Not one of ours until he is aboard: off the roster, not counted alive.
    {
      const roster = captureText(initRenderer(sb), () => quiet(() => sb.Renderer.drawHUD({ playerShip: player, enemyShip: hulk })))
        .map(d => d.t);
      ok(!roster.includes(sv.name), `the survivor is not on our roster yet (${sv.name})`);
      const n0 = T._playerCrewAliveCount();
      hulk.crew = hulk.crew.filter(c => c !== sv);
      const n1 = T._playerCrewAliveCount();
      hulk.addCrew(sv, true);
      ok(n0 === n1, `and is not counted as our crew (${n0} vs ${n1})`);
    }
    quiet(() => T._updateCombat(0.05));
    ok(sv.carriedBy === man && man.carrying === sv, 'our man in his compartment lifts him');
    // Every compartment searched — but he is on our man's shoulders: the hulk waits.
    hulk.rooms.forEach(r => (hulk._searched = hulk._searched ?? new Set()).add(r.id));
    quiet(() => T._updateCombat(0.05));
    ok(T.wreckLooted === false && hulk.crew.includes(sv), 'searched out, but the hulk waits while he is carried');
    man.moveToOnShip(hulk, dock.cx, hulk.floorWalkY(dock.floor, dock.cy));
    quiet(() => { for (let i = 0; i < 800 && hulk.crew.includes(sv); i++) T._updateCombat(0.05); });
    ok(!hulk.crew.includes(sv) && player.crew.includes(sv), 'carried to the hatch: he is handed across to our ship');
    ok(sv._survivor === false && sv.state === 'injured' && sv.isPlayer, 'and is one of ours now, still down for the medbay');

    // A bearer on a hulk that HAS a medbay does not walk him off to it:
    // he goes where the player sends him (to the hatch), not to the ward.
    {
      const med = makeDerelict(2, 850, 120, 'frigate');
      ok(!!med.getSystem('medbay'), 'test setup: a hulk with a medbay');
      const wardId = med.getSystem('medbay').roomId;
      const here = med.rooms.find(r => r.id !== wardId && r.floor !== med.getRoomById(wardId).floor) ?? med.rooms[0];
      const sv2 = sb.makeSurvivor();
      const b2 = new CrewMember({ name: 'Bearer', isPlayer: true });
      [sv2, b2].forEach(c => { c.roomId = here.id; c.inRoom = true; c.x = here.cx; c.y = med.floorWalkY(here.floor, here.cy); c._waypoints = []; med.addCrew(c, true); });
      sv2.carriedBy = b2; b2.carrying = sv2;
      quiet(() => { for (let i = 0; i < 200; i++) med.update(0.05); });
      ok(b2.roomId === here.id && b2.carrying === sv2 && !b2._waypoints.length,
         `he stays put with him, no route to the hulk's medbay (in ${b2.roomId}, ${b2._waypoints.length} waypoints)`);
    }

    // A hulk never rolls to run (its hull is always low) — no FTL warning over a wreck.
    {
      const realRand = Math.random;
      try {
        Math.random = () => 0.01;                 // every roll would say "run"…
        quiet(() => T._startWreckBoarding(2));
        const odds = sb.CombatManager.surrenderOdds;
        sb.CombatManager.surrenderOdds = () => 0; // …and none says "surrender" first
        try {
          for (let i = 0; i < 60; i++) quiet(() => sb.CombatManager.update(0.05));
        } finally { sb.CombatManager.surrenderOdds = odds; }
        ok(!sb.CombatManager.enemyEscapeActive, 'a wreck never spools up to escape');
      } finally { Math.random = realRand; }
    }

    // Left behind: nobody lifted him.
    quiet(() => T._startWreckBoarding(2));
    const hulk2 = T.enemyShip;
    hulk2.crew = hulk2.crew.filter(c => !c._survivor);
    const lone = sb.placeSurvivor(hulk2, hulk2.dockRoomId);
    quiet(() => T._recoverBoarders());
    ok(!player.crew.includes(lone) && !hulk2.crew.includes(lone), 'nobody carried him: left with the hulk');
    T._clearWreckMode?.();
  }
})();

// ============================================================
section('275. Gravity rides on the engines: zero-G walking, repairs, carrying, fire, the hold; the cat comes aboard hungry');
// ============================================================
(function testUpdate91Gravity() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Renderer, UI, Game, Pest, CargoGrid, GRAVITY_CONFIG: G,
          FIRE_DEFS, CAT_TUNING, HUNGER, Base, BaseScreen, CombatManager } = sb;
  Save.load(); Save.startRun();
  const T = Game.__test;
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const said = [];
  const realNotify = UI.notify;
  UI.notify = (m) => { said.push(String(m)); };
  const withRandom = (v, fn) => {
    const r = Math.random; Math.random = () => v;
    try { return fn(); } finally { Math.random = r; }
  };
  const hull = (key = 'frigate') => {
    const sh = new Ship(key, true, 0, 0);
    sh.crew.length = 0;
    sh.cargo = new CargoGrid(8, 6);
    sh.update(0.05);
    return sh;
  };
  const eng = (sh) => sh.getSystem('engines');
  const engOff = (sh) => { sh.setPower('engines', 0); sh.update(0.05); };
  const engOn  = (sh) => { sh.setPower('engines', 1); sh.update(0.05); };
  const man = (sh, roomId, name = 'Hand') => {
    const c = new CrewMember({ name, race: 'phoenix' });
    sh.addCrew(c, true);
    const r = sh.getRoomById(roomId);
    c.roomId = r.id; c.inRoom = true; c.x = r.cx; c.y = sh.floorWalkY(r.floor, r.cy);
    c._waypoints = []; c.hunger = 60;           // EFFORT 'ok' = 1.0
    return c;
  };

  try {
    /* ── 1. WHEN THERE IS GRAVITY ─────────────────────────── */
    {
      const sh = hull();
      ok(eng(sh).power >= 1 && sh.gravityActive && !sh.zeroG, 'powered, working engines: gravity');
      engOff(sh);
      ok(!sh.gravityActive && sh.zeroG, 'no power on the engines: zero-G');
      engOn(sh);
      ok(sh.gravityActive, 'one unit back: gravity back');
      eng(sh).level = 4; eng(sh).damagedLevels = 3; sh.update(0.05);
      ok(sh.gravityActive, 'three of four levels shot out, one working and powered: still gravity');
      eng(sh).damagedLevels = 4; sh.update(0.05);
      ok(sh.zeroG, 'every level shot out: zero-G');
      eng(sh).damagedLevels = 0; sh.setPower('engines', 1); sh.update(0.05);
      ok(sh.gravityActive, 'repaired and repowered: gravity');
      eng(sh)._stunT = 2; eng(sh).ionDamage = 2;
      ok(sh.zeroG, 'ion-locked engines: zero-G');
      eng(sh)._stunT = 0; eng(sh).ionDamage = 0;
      // A cyborg's +1 runs the engines on no reactor power (90a) — and so the gravity.
      engOff(sh);
      const cy = man(sh, eng(sh).roomId, 'Cy');
      cy.race = 'terra'; cy.cyborg = true;
      { const r = sh.getRoomById(eng(sh).roomId); [cy.x, cy.y] = sh.stationSlot(r, 0); }   // at the console (update93a)
      sh.update(0.05);
      // update104 (jj): the gravity wants a unit FROM THE REACTOR — a cyborg's +1 runs the engines, not the gravity.
      ok(eng(sh).power === 0 && eng(sh).effectivePower() >= 1 && !sh.gravityActive, 'a Terra cyborg at the engine console runs the engines but does NOT hold the gravity (update104)');
      const none = new Ship('frigate', true, 0, 0);
      none.systems = none.systems.filter(s => s.type !== 'engines');
      ok(none.zeroG, 'no engines at all: zero-G');
    }

    /* ── 2. SAID ONCE, ON THE CHANGE ──────────────────────── */
    {
      const sh = hull();
      said.length = 0;
      engOff(sh);
      for (let i = 0; i < 100; i++) sh.update(0.05);
      ok(said.filter(m => /GRAVITY LOST/.test(m)).length === 1, `GRAVITY LOST said once (${said.filter(m => /GRAVITY/.test(m)).length})`);
      engOn(sh);
      for (let i = 0; i < 100; i++) sh.update(0.05);
      ok(said.filter(m => /GRAVITY RESTORED/.test(m)).length === 1, 'GRAVITY RESTORED said once');
      said.length = 0;
      const fresh = new Ship('frigate', true, 0, 0);
      fresh.systems.find(s => s.type === 'engines').desiredPower = 0;
      for (let i = 0; i < 10; i++) fresh.update(0.05);
      ok(fresh.zeroG && !said.some(m => /GRAVITY/.test(m)), 'a hull that starts in zero-G is not "losing" gravity');
      const foe = new Ship('enemy_frigate', false, 0, 0);
      foe.update(0.05);                            // gravity on first…
      foe.setPower('engines', 0);                  // …then lost
      for (let i = 0; i < 5; i++) foe.update(0.05);
      ok(foe.zeroG && foe._gravityWas === false && !said.some(m => /GRAVITY/.test(m)),
         'their gravity is lost too — and it is not announced to us');
    }

    /* ── 3. REACTOR LOSS CAN TAKE THE GRAVITY ─────────────── */
    {
      const sh = hull();
      said.length = 0;
      sh.setPower('engines', 0); sh.setPower('weapons', 1); sh.setPower('engines', 1);   // engines powered LAST
      sh.update(0.05);
      ok(sh.gravityActive && sh.availablePower() >= 0, 'engines powered last, gravity on');
      const spare = sh.availablePower();
      sh.getSystem('reactor').damagedLevels = spare + 1;     // eat the spare and one more
      sh.update(0.05);
      ok(eng(sh).power === 0 && sh.zeroG, `a reactor hit takes the engines' unit — and the gravity (${eng(sh).power})`);
      ok(said.some(m => /GRAVITY LOST/.test(m)), 'and the player is told');
    }

    /* ── 4. WALKING AND CARRYING ──────────────────────────── */
    {
      const walk = (zg, carry) => {
        const sh = hull();
        if (zg) engOff(sh);
        const a = man(sh, 'r_engines', 'Walker');
        if (carry) {
          const body = man(sh, 'r_engines', 'Down');
          body.state = 'injured'; body.hp = 5; body._bandaged = true;
          a.carrying = body; body.carriedBy = a; body._survivor = true;   // carried, not dropped at a ward
        }
        const dst = sh.getRoomById('r_shields');
        a.moveToOnShip(sh, dst.cx, a.y);
        const x0 = a.x;
        for (let i = 0; i < 20; i++) sh.update(0.05);   // one second
        return a.x - x0;
      };
      const base = walk(false, false);
      ok(base > 20, `test setup: a man walks ${base.toFixed(1)}px in a second`);
      const near = (v, want, what) => ok(Math.abs(v / base - want) < 0.03, `${what}: ${(v / base * 100).toFixed(0)}% (want ${want * 100}%)`);
      near(walk(true, false),  G.crewMovementMultiplier,  'zero-G walking');
      near(walk(false, true),  G.normalWoundedCarrySpeed, 'carrying a casualty in gravity');
      near(walk(true, true),   G.zeroGWoundedCarrySpeed,  'carrying a casualty in zero-G');
    }

    /* ── 5. REPAIRS AND PATCHING ──────────────────────────── */
    {
      const fix = (zg) => {
        const sh = hull();
        const w = sh.getSystem('weapons');
        w.damagedLevels = 1;
        if (zg) engOff(sh);
        const m = man(sh, w.roomId, 'Fixer');
        m.assignTask(sb.TASK.REPAIR, w.roomId);
        const r = sh.getRoomById(w.roomId);
        m.x = r.cx; m.y = r.cy;
        m._updateTask(0.5, sh);
        return w.repairProgress;
      };
      const g1 = fix(false), z1 = fix(true);
      ok(g1 > 0 && Math.abs(z1 / g1 - G.normalRepairMultiplier) < 0.01,
         `a module mends at ${(z1 / g1 * 100).toFixed(0)}% in zero-G (want 80%)`);
      const patch = (zg) => {
        const sh = hull();
        if (zg) engOff(sh);
        const r = sh.getRoomById('r_weapons');
        const b = sh.breaches.open(r.id, r.cx, r.cy);
        const m = man(sh, r.id, 'Patcher');
        m.assignTask(sb.TASK.BREACH, b);
        m.x = b.x; m.y = b.y;
        m._updateTask(0.5, sh);
        return b.progress;
      };
      const g2 = patch(false), z2 = patch(true);
      ok(g2 > 0 && Math.abs(z2 / g2 - G.breachRepairMultiplier) < 0.01,
         `a breach is patched at ${(z2 / g2 * 100).toFixed(0)}% in zero-G (want 70%)`);
    }

    /* ── 6. FIRE ───────────────────────────────────────────── */
    {
      const blaze = (zg) => {
        const sh = hull();
        if (zg) engOff(sh);
        const r = sh.getRoomById('r_weapons');
        const f = sh.fires.start(r.id, r.cx, r.cy);
        f.intensity = 2; f.age = 99;
        f._spreadTimer = FIRE_DEFS.SPREAD_TIME;
        // A roll between the zero-G chance and the gravity chance for an open door.
        const roll = FIRE_DEFS.SPREAD_CHANCE * (G.fireSpreadMultiplier + 1) / 2;
        withRandom(roll, () => sh.fires.update(0.01, sh));
        return { sh, f, rooms: new Set(sh.fires.fires.filter(x => !x.out).map(x => x.roomId)) };
      };
      const on = blaze(false), off = blaze(true);
      ok(on.rooms.size > 1, 'in gravity that roll spreads it');
      ok(off.rooms.size === 1, 'in zero-G the same roll does not (a fifth of the chance)');
      ok(!off.f.out && off.f.zeroG === true && on.f.zeroG === false, 'the fire still burns, flagged zero-G');
      // Still needs air: zero-G is not vacuum, and vacuum still puts it out.
      off.sh.oxygen.getRoom(off.f.roomId).level = 0;
      for (let i = 0; i < 40 && !off.f.out; i++) off.sh.fires.update(0.1, off.sh);
      ok(off.f.out, 'and with the air gone it still goes out');
      // Drawn as a sphere: one arc, no square plume.
      const ctx = initRenderer(sb);
      const f2 = blaze(true).f;
      let arcs = 0, rects = 0;
      const ra = ctx.arc, rr = ctx.fillRect;
      ctx.arc = function () { arcs++; }; ctx.fillRect = function () { rects++; };
      try { f2.draw(ctx); f2.zeroG = false; f2.draw(ctx); } finally { ctx.arc = ra; ctx.fillRect = rr; }
      ok(arcs === 1 && rects === 1, `zero-G flame is a sphere, and back in gravity the old flame (${arcs} arc, ${rects} rect)`);
    }

    /* ── 7. THE HOLD: DAMAGE ──────────────────────────────── */
    {
      const sh = hull();
      sh.cargo.add('medkit'); sh.cargo.add('plating'); sh.cargo.add('spider_egg');
      engOff(sh);
      const dmg = () => sh.cargo.items.filter(it => it.damaged).length;
      withRandom(0, () => { for (let i = 0; i < 395; i++) sh.update(0.05); });   // 19.75 s
      ok(dmg() === 0, 'nothing in the first 20 seconds');
      withRandom(0, () => { for (let i = 0; i < 10; i++) sh.update(0.05); });
      ok(dmg() === 1, 'one item damaged at 20 s');
      withRandom(0, () => { for (let i = 0; i < 400; i++) sh.update(0.05); });
      ok(dmg() === 2 && sh.cargo.items.length === 3, `one more at 40 s, nothing removed (${dmg()} of ${sh.cargo.items.length})`);
      ok(!sh.cargo.items.find(it => it.def?.tag === 'egg').damaged, 'the egg case is never the one (a damaged egg does not hatch)');
      {
        const eggs = hull(); eggs.cargo.add('spider_egg'); engOff(eggs);
        withRandom(0, () => { for (let i = 0; i < 410; i++) eggs.update(0.05); });
        ok(!eggs.cargo.items[0].damaged, 'a hold of nothing but an egg case: nothing is damaged');
      }
      withRandom(0.99, () => { for (let i = 0; i < 800; i++) sh.update(0.05); });
      ok(dmg() === 2, 'a failed roll damages nothing');
      // Time, not frames: the same 60 s at a tenth of the frame rate.
      const a = hull(), b = hull();
      [a, b].forEach(h => { for (let k = 0; k < 4; k++) h.cargo.add('plating'); engOff(h); });
      withRandom(0, () => { for (let i = 0; i < 1200; i++) a.update(0.05); for (let i = 0; i < 120; i++) b.update(0.5); });
      const da = a.cargo.items.filter(it => it.damaged).length, db = b.cargo.items.filter(it => it.damaged).length;
      ok(da === 3 && db === 3, `60 s damages 3 at any frame rate (${da} / ${db})`);
      engOn(sh);
      withRandom(0, () => { for (let i = 0; i < 800; i++) sh.update(0.05); });
      ok(dmg() === 2, 'gravity back: no more damage, and the damaged stay damaged');
      {
        // A fresh spell of zero-G starts a fresh clock: 15 s, a blink of gravity, 15 s — nothing.
        const c = hull(); for (let k = 0; k < 3; k++) c.cargo.add('plating');
        engOff(c);
        withRandom(0, () => { for (let i = 0; i < 300; i++) c.update(0.05); });
        engOn(c); engOff(c);
        withRandom(0, () => { for (let i = 0; i < 300; i++) c.update(0.05); });
        ok(!c.cargo.items.some(it => it.damaged), 'gravity back even for a moment resets the clock');
      }
    }

    /* ── 8. THE HOLD: LOSS NEEDS ZERO-G AND A HOLE ────────── */
    {
      const breach = (sh) => {
        const r = sh.getRoomById('r_shields');
        return sh.breaches.open(r.id, r.cx, r.cy);
      };
      const stock = (sh) => { sh.cargo.add('he2_large'); sh.cargo.add('missile_rack'); sh.cargo.add('medkit'); };
      const units = (sh) => sh.cargo.items.reduce((n, it) => n + (it.qty ?? 1), 0);
      const pickFirst = (fn) => {
        const real = sb.Utils.pick;
        sb.Utils.pick = (arr) => arr[0];
        try { return fn(); } finally { sb.Utils.pick = real; }
      };
      // zero-G alone
      const a = hull(); stock(a); engOff(a);
      const ua = units(a);
      const rr = sb.GRAVITY_CONFIG.cargoDamageProbability;
      sb.GRAVITY_CONFIG.cargoDamageProbability = 0;
      try {
        withRandom(0, () => { for (let i = 0; i < 1200; i++) a.update(0.05); });
        ok(units(a) === ua, 'zero-G alone loses nothing');
        // a hole alone
        const b = hull(); stock(b); breach(b);
        const ub = units(b);
        withRandom(0, () => { for (let i = 0; i < 1200; i++) b.update(0.05); });
        ok(units(b) === ub, 'a hole with gravity on loses nothing');
        // both
        const c = hull(); stock(c); const hole = breach(c); engOff(c);
        const guns = c.weapons.filter(Boolean).length;
        const uc = units(c), n0 = c.cargo.items.length;
        said.length = 0;
        withRandom(0, () => pickFirst(() => { for (let i = 0; i < 195; i++) c.update(0.05); }));
        ok(units(c) === uc, 'not before 10 s');
        withRandom(0, () => pickFirst(() => { for (let i = 0; i < 10; i++) c.update(0.05); }));
        ok(units(c) === uc - 1, `zero-G and a hole: ONE unit gone at 10 s (${uc} → ${units(c)})`);
        ok(c.cargo.items.length === n0, 'off a stack, not the whole stack');
        ok(said.some(m => /^CARGO LOST: /.test(m)), `and said (${said.find(m => /CARGO/.test(m))})`);
        withRandom(0.99, () => { for (let i = 0; i < 400; i++) c.update(0.05); });
        ok(units(c) === uc - 1, 'a failed roll loses nothing');
        // a single item goes whole
        const d = hull(); d.cargo.add('plating'); breach(d); engOff(d);
        withRandom(0, () => { for (let i = 0; i < 205; i++) d.update(0.05); });
        ok(d.cargo.items.length === 0, 'a single item goes whole');
        ok(c.weapons.filter(Boolean).length === guns, 'the installed gun is not cargo');
        // patched: stops
        hole.sealed = true;
        const up = units(c);
        withRandom(0, () => { for (let i = 0; i < 400; i++) c.update(0.05); });
        ok(units(c) === up, 'hole patched: no more loss');
        // gravity back: stops, and nothing returns — with a fresh hole open
        breach(c);
        engOn(c);
        withRandom(0, () => { for (let i = 0; i < 400; i++) c.update(0.05); });
        ok(units(c) === up, 'gravity back: no more loss, and nothing comes back');
      } finally { sb.GRAVITY_CONFIG.cargoDamageProbability = rr; }
    }

    /* ── 9. THE ENEMY: SAME RULES, AND THE AI LOOKS ───────── */
    {
      // The raider lists its WEAPONS before its engines: only zero-G puts the engines first.
      const foe = new Ship('enemy_raider', false, 850, 120);
      foe.sizeAirForCrew(3);
      foe.setPower('engines', 0); foe.update(0.05);
      ok(foe.zeroG && foe.moveFactor({}) === G.crewMovementMultiplier && foe.repairFactor() === G.normalRepairMultiplier,
         'their hull: the same zero-G rules');
      const player = new Ship('frigate', true, 0, 0);
      sb.makeStartingCrew().forEach(c => player.addCrew(c));
      T.playerShip = player; T.enemyShip = foe; T.STATE = 'combat';
      CombatManager.begin(player, foe, 'normal');
      CombatManager.state = sb.COMBAT_STATE.ACTIVE;
      // Engines AND weapons shot up; one idle hand. Zero-G: he goes to the engines.
      foe.crew.length = 0;
      const w = foe.getSystem('weapons'), e = foe.getSystem('engines');
      w.damagedLevels = 1; e.damagedLevels = e.level;
      const hand = new CrewMember({ name: 'Fixer', isPlayer: false });
      foe.addCrew(hand, true);
      const far = foe.rooms.find(r => r.id !== w.roomId && r.id !== e.roomId && r.system?.type !== 'piloting');
      hand.roomId = far.id; hand.x = far.cx; hand.y = foe.floorWalkY(far.floor, far.cy);
      foe.update(0.05);
      ok(foe.zeroG, 'their engines are out');
      quiet(() => CombatManager._updateAI(0.1));
      ok(hand.taskTarget === e.roomId, `zero-G: their idle hand goes to the engines first (${hand.taskTarget})`);
      CombatManager.end?.();
    }

    /* ── 10. WHAT THE PLAYER SEES ─────────────────────────── */
    {
      const ctx = initRenderer(sb);
      const sh = hull();
      const text = () => captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: sh }))).map(d => d.t);
      ok(text().includes('GRAV ON'), 'under the engines: GRAV ON');
      engOff(sh);
      ok(text().includes('⚠ ZERO-G'), 'zero-G: ⚠ ZERO-G under the engines');
      const tip = sh.moduleInfo(eng(sh)).rows.map(r => r.text).join('|');
      ok(/ZERO-G/.test(tip), 'and the engines card says so');
      const foe = new Ship('enemy_frigate', false, 850, 120);
      foe.setPower('engines', 0); foe.update(0.05);
      const both = captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: sh, enemyShip: foe }))).map(d => d.t);
      ok(both.includes('0-G'), 'their strip marks their zero-G');
      // The log window starts below their module strip, however low their hull sits.
      {
        const low = new Ship('enemy_frigate', false, 850, 260);   // a hull low on the screen
        T.playerShip = sh; T.enemyShip = low; T.STATE = 'combat';
        if (!UI.isLogOpen()) UI.toggleLog();
        const frame = quiet(() => captureText(Renderer.getCtx(), () => T._draw()));
        /* update130: their strip lives in their panel at the top right now,
           so nothing hangs under the hull for the log to dodge — the tab
           must simply clear the panel and the hull. */
        const panel = Renderer.enemyPanelRect();
        const tab = frame.find(d => /^LOG/.test(d.t));
        const hullEnd = low.roomBounds().y + low.roomBounds().h;
        ok(panel && tab && tab.y > panel.y + panel.h && tab.y > hullEnd,
           `the log tab (y ${tab && Math.round(tab.y)}) is below their panel (ends ${panel && Math.round(panel.y + panel.h)}) and their hull (${Math.round(hullEnd)})`);
      }
      // The crew float: drawn off the deck, the rules untouched.
      const m = man(sh, 'r_weapons', 'Floater');
      sh.update(0.05);
      const y0 = m.y;
      const shifts = [];
      const realT = ctx.translate;
      ctx.translate = function (x, y) { shifts.push(y); };
      try { quiet(() => sh.draw(ctx)); } finally { ctx.translate = realT; }
      ok(m._zeroG === true && shifts.some(y => y < 0 && y > -8), `in zero-G the crew are drawn off the deck (${shifts.filter(y => y < 0 && y > -8).length} lifted)`);
      ok(m.y === y0, 'and nobody actually moved');
    }

    /* ── 11. THE CAT COMES ABOARD HUNGRY ──────────────────── */
    {
      ok(sb.makeCat('black').hunger === CAT_TUNING.START_HUNGER && CAT_TUNING.START_HUNGER < HUNGER.FED,
         `a new cat is hungry enough to hunt (${CAT_TUNING.START_HUNGER} < ${HUNGER.FED})`);
      Save.load(); Base.earn(5000);
      Base.get().pets = [];
      const r = Base.adoptCat('black');
      ok(r.ok, 'test setup: a cat in the pen');
      Base.pets()[0].hunger = 100;                    // fed at the base
      const ctx = initRenderer(sb);
      quiet(() => {
        BaseScreen.open();
        BaseScreen._act('pickPet', Base.pets()[0].id);
        launchNow(BaseScreen);
        T._startContract(BaseScreen.consumeLaunch());
      });
      const cat = T.playerShip.crew.find(c => c.isPet);
      ok(cat && cat.hunger === CAT_TUNING.START_HUNGER, `she comes aboard hungry, whatever she ate at home (${cat && cat.hunger})`);
      void ctx;
    }
  } finally {
    UI.notify = realNotify;
  }
})();

// ============================================================
section('276. Reactor heat: load heats it from 80%, free power cools it from 30%, an overheat costs a level');
// ============================================================
(function testUpdate92ReactorHeat() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, Renderer, UI, Base, REACTOR_HEAT_CONFIG: H, TASK } = sb;
  Save.load(); Save.startRun();
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const said = [];
  const realNotify = UI.notify;
  UI.notify = (m) => { said.push(String(m)); };
  const withRandom = (v, fn) => { const r = Math.random; Math.random = () => v; try { return fn(); } finally { Math.random = r; } };
  /* A frigate with its reactor at `total` and the modules drawing exactly
     `used` of it (from the end of the list), lifts aside. */
  const rig = (used, total = 10) => {
    const sh = new Ship('frigate', true, 0, 0);
    sh.crew.length = 0;
    sh.reactor.maxLevel = Math.max(sh.reactor.maxLevel, total);
    sh.reactor.level = total;
    sh.systems.forEach(s => { if (s.type !== 'reactor') { s.level = Math.max(s.level, 2); s.power = 0; s.desiredPower = 0; } });
    const mods = sh.systems.filter(s => s.type !== 'reactor');
    let left = used;
    for (const s of mods) { const give = Math.min(s.level, left); s.desiredPower = give; left -= give; if (!left) break; }
    sh.update(0.0001);
    return sh;
  };
  const near = (a, b, tol = 1e-6) => Math.abs(a - b) < tol;

  try {
    /* ── 1. LOAD IS THE MODULES', NOT THE LIFTS' ─────────────── */
    {
      const sh = new Ship('frigate', true, 0, 0);
      sh.update(0.05);
      ok(sh.liftsPowered() === 1 && near(sh.reactorLoad, 7 / 8),
         `the starting frigate: 7 of 8 to the modules, the lift's unit not counted (${sh.reactorLoad})`);
      ok(near(sh.reactorHeatRate(), H.heatBands[2].perSec), 'so she heats in the slow band (~10 min)');
    }

    /* ── 2. THE BANDS ──────────────────────────────────────── */
    {
      const rate = (used) => rig(used, 10).reactorHeatRate();
      ok(rate(10) === H.heatBands[0].perSec * 0.95, `100% load: ~3 min to full (×0.95 for a level-10 core) (${rate(10).toFixed(4)})`);
      ok(near(rate(9), H.heatBands[1].perSec * 0.95), '90%: ~6 min');
      ok(near(rate(8), H.heatBands[2].perSec * 0.95), '80%: ~10 min');
      ok(near(rig(3, 4).reactorHeatRate(), 0), '75% load, 25% free: it holds (between the lines)');
      ok(near(rate(7), -H.coolBands[2].perSec), '70% load, 30% free: slow cooling starts');
    }
    {
      // Cooling bands on a 10-unit core: 3 free (30%) slow, 4 (40%) medium, 5+ (50%) fast.
      const r7 = rig(7, 10).reactorHeatRate(), r6 = rig(6, 10).reactorHeatRate(),
            r5 = rig(5, 10).reactorHeatRate(), r0 = rig(0, 10).reactorHeatRate();
      ok(near(r7, -H.coolBands[2].perSec), '30% free: slow cooling (the player: "od 30% wolnego")');
      ok(near(r6, -H.coolBands[1].perSec), `40% free: medium cooling (${r6.toFixed(4)})`);
      ok(near(r5, -H.coolBands[0].perSec), '50% free: fast');
      ok(near(r0, -H.coolBands[0].perSec), 'everything off: fast');
      const twelve = rig(8, 12);                 // 8 of 12 = 66%: 33% free
      ok(near(twelve.reactorHeatRate(), -H.coolBands[2].perSec), '33% free: slow cooling');
      const scram = rig(10, 10); scram.reactor.offline = true;
      ok(near(scram.reactorHeatRate(), -H.scramCoolPerSec), 'a scrammed reactor cools fast');
    }

    /* ── 3. A BIGGER CORE RUNS A LITTLE COOLER ─────────────── */
    {
      const at = (lvl) => {
        const sh = new Ship('frigate', true, 0, 0);
        sh.reactor.maxLevel = 20; sh.reactor.level = lvl;
        Object.defineProperty(sh, 'reactorLoad', { get: () => 1 });   // flat out, whatever the hull
        return sh.reactorHeatRate() / H.heatBands[0].perSec;
      };
      ok(near(at(8), 1.00) && near(at(10), 0.95) && near(at(14), 0.90) && near(at(18), 0.85),
         `thermal multipliers 1.00 / 0.95 / 0.90 / 0.85 (${[8, 10, 14, 18].map(at).map(v => v.toFixed(2))})`);
    }

    /* ── 4. OVER TIME, BOTH WAYS, CLAMPED ──────────────────── */
    {
      const sh = rig(10, 8);
      withRandom(0.999, () => { for (let i = 0; i < 1800; i++) sh.update(0.1); });   // 3 min at 100%
      ok(sh.reactorHeat >= 90, `three minutes flat out: at or past the overheat (${sh.reactorHeat.toFixed(1)}%)`);
      const cool = rig(0, 8);
      cool.reactorHeat = 100 - 1e-9;
      cool.update(0.0001);
      for (let i = 0; i < 1600; i++) cool.update(0.1);    // 160 s
      ok(cool.reactorHeat === 0, 'all power off: cold again inside three minutes, and never below 0');
      const hot = rig(10, 8);
      hot.reactorHeat = 99.99;
      withRandom(0.999, () => hot.update(0.5));
      ok(hot.reactorHeat <= 100, 'never above 100');
    }

    /* ── 5. OVERHEAT: ONCE, ONE LEVEL, BACK TO 90 ──────────── */
    {
      const sh = rig(8, 8);
      const core = sh.getSystem('reactor');
      const before = sh.reactor.totalPower;
      said.length = 0;
      sh.reactorHeat = 99.95;
      withRandom(0.999, () => sh.update(0.5));
      ok(core.damagedLevels === 1 && sh.reactor.totalPower === before - 1, `an overheat shoots out exactly one reactor level (${before} → ${sh.reactor.totalPower})`);
      ok(near(sh.reactorHeat, H.overheatResetHeat, 0.5), `and the heat drops to 90%, not 0 (${sh.reactorHeat.toFixed(1)})`);
      ok(said.filter(m => /OVERHEAT/.test(m)).length === 1, 'said once');
      withRandom(0.999, () => { for (let i = 0; i < 20; i++) sh.update(0.1); });
      ok(core.damagedLevels === 1, 'and not again on the very next frames');
      const drawn = sh.systems.reduce((a, s) => a + (s.type === 'reactor' ? 0 : s.reactorDraw()), 0);
      ok(drawn <= sh.reactor.totalPower, `the modules draw no more than is left (${drawn} of ${sh.reactor.totalPower})`);
      const fireRoll = (v) => { const s2 = rig(8, 8); s2.reactorHeat = 99.95; withRandom(v, () => s2.update(0.5)); return s2.fires.fires.filter(f => !f.out); };
      const lit = fireRoll(0.3), dark = fireRoll(0.999);
      ok(lit.length === 1 && lit[0].roomId === core.roomId, 'a 50% roll under it: fire, in the reactor room');
      ok(dark.length === 0, 'a roll over it: no fire');
    }

    /* ── 6. CREW REPAIR IT LIKE ANY MODULE ──────────────────── */
    {
      const sh = rig(4, 8);
      const core = sh.getSystem('reactor');
      core.damageLevel(1);
      sh.update(0.05);
      const down = sh.reactor.totalPower;
      const m = new CrewMember({ name: 'Tech', race: 'phoenix' });   // not a Terra: no +1 at the console
      sh.addCrew(m, true);
      const room = sh.getRoomById(core.roomId);
      m.roomId = room.id; m.inRoom = true; m.x = room.cx; m.y = room.cy;
      m.assignTask(TASK.REPAIR, room.id);
      for (let i = 0; i < 2000 && core.damagedLevels > 0; i++) sh.update(0.05);
      ok(core.damagedLevels === 0 && sh.reactor.totalPower === down + 1, `repaired: the level is back (${down} → ${sh.reactor.totalPower})`);
      const idle = rig(4, 8);
      idle.getSystem('reactor').damageLevel(1);
      for (let i = 0; i < 400; i++) idle.update(0.05);
      ok(idle.getSystem('reactor').damagedLevels === 1, 'and nobody aboard: it does not mend itself');
    }

    /* ── 7. FIRE ROLLS: ON A CLOCK, IN THE REACTOR ROOM ─────── */
    {
      const count = (heat, dt, secs) => {
        const sh = rig(3, 4);             // 75%: holding — the heat stays put
        sh.reactorHeat = heat;
        let starts = 0, rooms = new Set();
        const real = sh.fires.start.bind(sh.fires);
        sh.fires.start = (id, x, y) => { starts++; rooms.add(id); return real(id, x, y); };
        withRandom(0, () => { for (let i = 0; i < Math.round(secs / dt); i++) sh.update(dt); });
        return { starts, rooms, core: sh.getSystem('reactor').roomId };
      };
      const a = count(75, 0.05, 10), b = count(75, 0.5, 10);
      ok(a.starts === 10 && b.starts === 10, `one roll a second, whatever the frame rate (${a.starts} / ${b.starts} in 10 s)`);
      ok(a.rooms.size === 1 && a.rooms.has(a.core), 'and only ever in the reactor room');
      ok(count(65, 0.05, 10).starts === 0, 'below 70%: no rolls that can land');
      // The odds themselves, by band, against a roll just under each.
      const lands = (heat, v) => { let n = 0; const sh = rig(3, 4); sh.reactorHeat = heat;
        const real = sh.fires.start.bind(sh.fires); sh.fires.start = (...x) => { n++; return real(...x); };
        withRandom(v, () => { for (let i = 0; i < 20; i++) sh.update(0.05); }); return n; };
      ok(lands(75, 0.0009) === 1 && lands(75, 0.0011) === 0, '70–79%: 0.1% a second');
      ok(lands(85, 0.0049) === 1 && lands(85, 0.0051) === 0, '80–89%: 0.5%');
      ok(lands(95, 0.0199) === 1 && lands(95, 0.0201) === 0, '90–99%: 2%');
    }

    /* ── 8. SAID ONCE PER CROSSING ─────────────────────────── */
    {
      const sh = rig(10, 8);
      sh.reactorHeat = 69;
      said.length = 0;
      withRandom(0.999, () => { for (let i = 0; i < 200; i++) sh.update(0.1); });
      ok(said.filter(m => /running hot/.test(m)).length === 1, 'past 70%: said once');
      withRandom(0.999, () => { for (let i = 0; i < 400; i++) sh.update(0.1); });
      ok(said.filter(m => /CRITICAL/.test(m)).length === 1, 'past 90%: said once');
      // 10 of 10: their two lifts take their units first (update93a), the modules still run at 80%.
      const foe = rig(10, 10); foe.isPlayer = false; foe.reactorHeat = 69;
      said.length = 0;
      withRandom(0.999, () => { for (let i = 0; i < 300; i++) foe.update(0.1); });
      ok(foe.reactorHeat > 70 && !said.length, 'their reactor heats by the same rules, and is not announced to us');
    }

    /* ── 9. THE ENEMY, AS BUILT, SAME RULES ────────────────── */
    {
      const foe = new Ship('enemy_gunship', false, 850, 120);
      foe.sizeAirForCrew(4);
      foe.update(0.05);
      ok(foe.reactorLoad >= 0.8 && foe.reactorHeatRate() > 0,
         `a sized enemy runs its modules flat out (its lifts' units aside) and heats (${foe.reactorLoad.toFixed(2)})`);
    }

    /* ── 10. SAVED WITH THE HULL; COLD IN THE YARD ─────────── */
    {
      const sh = rig(8, 8);
      sh.reactorHeat = 63.4;
      const data = sh.serialise();
      ok(data.heat === 63, 'the hull record carries the heat');
      const back = Ship.deserialise(JSON.parse(JSON.stringify(data)), true, 0, 0);
      ok(back.reactorHeat === 63, 'and a load brings it back');
      const old = JSON.parse(JSON.stringify(data)); delete old.heat;
      ok(Ship.deserialise(old, true, 0, 0).reactorHeat === 0, 'a save from before 92 loads cold');
      Save.load(); Base.get().ships.length = 0;
      quiet(() => Base.returnFromRun({ shipEntry: { key: 'frigate', data: sh.serialise() }, crew: [], cc: 0 }));
      ok((Base.get().ships[0]?.data?.heat ?? 0) === 0, 'a hull back in the yard is cold');
    }

    /* ── 11. WHAT THE PLAYER SEES ─────────────────────────── */
    {
      const ctx = initRenderer(sb);
      const sh = rig(8, 8);
      sh.reactorHeat = 93;
      const t = captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: sh }))).map(d => d.t);
      ok(t.includes('1209°C'), `the heat reads beside the pips, in degrees (update97: 93 → 1209 °C) (${t.filter(x => /°C$/.test(x))})`);
      /* The heat lies under the pips since update130 and fills from the left. */
      quiet(() => Renderer.drawHUD({ playerShip: sh }));
      const hb = Renderer.reactorBarRect();
      ok(hb && hb.col === '#ff2d44' && near(hb.filled / hb.track.w, 0.93, 0.01),
         `a bar filled 93% from the left, critical red (${hb && (hb.filled / hb.track.w).toFixed(2)})`);
      sh._overheatFlashT = 1;
      ok(captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: sh }))).some(d => d.t === 'REACTOR OVERHEAT'), 'an overheat says so on the bar');
      const tip = sh.moduleInfo(sh.getSystem('reactor')).rows.map(r => r.text).join('|');
      ok(/Core 1209 °C of 1300/.test(tip) && /heating/.test(tip), `and the reactor card has the heat and the trend (${tip.split('|').find(x => /Core/.test(x))})`);
      const foe = new Ship('enemy_frigate', false, 850, 120);
      foe.reactorHeat = 85;
      const both = captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: sh, enemyShip: foe }))).map(d => d.t);
      ok(both.includes('1105°C'), 'a hot enemy reactor is marked on their strip, in degrees (update97)');
    }
  } finally {
    UI.notify = realNotify;
  }
})();

// ============================================================
section('277. The enemy by the same rules: medkits, its dead, our deck, 60 s stalemate, captives in carbonite, pairs, a cool core');
// ============================================================
(function testUpdate93EnemySameRules() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, UI, Base, BaseScreen, Commander, CombatManager,
          REACTOR_HEAT_CONFIG: H, Game } = sb;
  const T = Game.__test;
  Save.load(); Save.startRun();
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const said = [];
  const realNotify = UI.notify;
  UI.notify = (m) => { said.push(String(m)); };
  const man = (ship, room, isPlayer, extra = {}) => {
    const c = new CrewMember({ isPlayer, race: isPlayer ? 'aquarius' : 'hostile', ...extra });
    c.roomId = room.id; c.homeRoomId = room.id;
    c.x = room.cx; c.y = ship.floorWalkY(room.floor, room.cy);
    ship.addCrew(c, true);
    return c;
  };
  const enemyHull = () => {
    const e = new Ship('enemy_frigate', false, 850, 120);
    e._allocateDefaultPower();
    e.crew.length = 0;
    return e;
  };

  try {
    /* ── 1. THEIR MEDIC OPENS A MEDKIT ─────────────────────────── */
    {
      const e = enemyHull();
      e.cargo.clear(); e.cargo.add('medkit');
      const w = e.weaponRooms[0];
      const hurt = man(e, w, false); hurt.state = 'injured'; hurt.hp = 10;
      e.update(0.05);
      ok(hurt.bodyOrder === 'medkit', `a man of theirs on the floor gets a medkit order (${hurt.bodyOrder})`);
      const p = new Ship('frigate', true, 80, 120);
      p.crew.length = 0;
      const ours = man(p, p.rooms[0], true); ours.state = 'injured'; ours.hp = 10;
      p.cargo.clear(); p.cargo.add('medkit');
      p.update(0.05);
      ok(!ours.bodyOrder, 'ours get no order the player did not give');

      const dry = enemyHull();
      dry.cargo.clear();
      const d2 = man(dry, dry.weaponRooms[0], false); d2.state = 'injured'; d2.hp = 10;
      dry.update(0.05);
      ok(!d2.bodyOrder, 'no doses, no medkit order');
      dry.cargo.add('medkit'); dry.update(0.05);
      ok(d2.bodyOrder === 'medkit', 'a box aboard, and the order is given');
      dry.cargo.clear(); dry.update(0.05);
      ok(!d2.bodyOrder, 'and taken back when the box runs dry — nobody stands over him for good');

      const ward = enemyHull();
      ward.cargo.add('medkit');
      ward._wardIsOpen = () => true;
      const d3 = man(ward, ward.weaponRooms[0], false); d3.state = 'injured'; d3.hp = 10;
      ward.update(0.05);
      ok(d3.bodyOrder !== 'medkit', 'a lit ward is where he goes instead — no dose spent');

      // …and it works, end to end: a medic walks over and he stands up.
      const e2 = enemyHull();
      e2.cargo.clear(); e2.cargo.add('medkit');
      const before = e2.doseCount();
      const pr = e2.rooms.find(r => r.type === 'piloting');
      const down = man(e2, e2.weaponRooms[0], false); down.state = 'injured'; down.hp = 10;
      man(e2, pr, false);
      for (let i = 0; i < 1200 && down.down; i++) e2.update(0.05);
      ok(!down.down && down.alive, 'their medic reaches him and gets him up');
      ok(e2.doseCount() === before - Ship.MEDKIT_DOSES, `for a medkit's doses (${before} → ${e2.doseCount()})`);
    }

    /* ── 2. THEIR DEAD GO OUT THE AIRLOCK ──────────────────────── */
    {
      const e = enemyHull();
      const w = e.weaponRooms[0];
      const pr = e.rooms.find(r => r.type === 'piloting');
      const dead = man(e, w, false);
      man(e, pr, false);
      // A spare hand (update93a: only a FREE man carries a body out — not the pilot).
      man(e, e.rooms.find(r => r !== w && r !== pr && r.system) || e.rooms[0], false);
      dead.killOutright();
      for (let i = 0; i < 20; i++) e.update(0.05);
      ok(!dead.bodyOrder, `not the moment he falls (${dead.bodyOrder})`);
      for (let i = 0; i < Ship.AI_VENT_SECONDS * 20; i++) e.update(0.05);
      ok(dead.bodyOrder === 'eject', `after ${Ship.AI_VENT_SECONDS} s the order is to vent him (${dead.bodyOrder})`);
      let gone = false;
      for (let i = 0; i < 2400 && !gone; i++) { e.update(0.05); gone = !e.crew.includes(dead); }
      ok(gone, 'and somebody carries him out — off the roster');

      const sealed = enemyHull();
      sealed.doors = sealed.doors.filter(d => !d.isAirlock);
      const d2 = man(sealed, sealed.weaponRooms[0], false);
      d2.killOutright();
      for (let i = 0; i < (Ship.AI_VENT_SECONDS + 2) * 20; i++) sealed.update(0.05);
      ok(!d2.bodyOrder, 'no airlock, no order (he would be carried for ever)');

      const p = new Ship('frigate', true, 80, 120);
      p.crew.length = 0;
      const ourDead = man(p, p.rooms[0], true);
      man(p, p.rooms[1], true);
      ourDead.killOutright();
      for (let i = 0; i < (Ship.AI_VENT_SECONDS + 2) * 20; i++) p.update(0.05);
      ok(!ourDead.bodyOrder, 'our dead wait for the player — he decides');

      const caged = enemyHull();
      const pris = man(caged, caged.weaponRooms[0], false, { isPrisoner: true });
      pris.killOutright();
      for (let i = 0; i < (Ship.AI_VENT_SECONDS + 2) * 20; i++) caged.update(0.05);
      ok(!pris.bodyOrder, 'a dead prisoner is not theirs to bury');
    }

    /* ── 3. THEIR DEAD ON OUR DECK ─────────────────────────────── */
    {
      T.STATE = 'combat';
      const p = new Ship('frigate', true, 80, 120);
      p.crew.length = 0;
      T.playerShip = p;
      const room = p.rooms.find(r => r.type === 'shields') || p.rooms[1];
      const ours = man(p, p.rooms[0], true);
      const foe = man(p, room, false);
      const live = man(p, p.rooms.find(r => r !== room && r !== p.rooms[0]), false);
      foe.killOutright();
      p.update(0.05);
      const hit = T._bodyUnderCursor(foe.x, foe.y + CrewMember.BODY_DROP);
      ok(hit === foe, 'a dead boarder on our deck can be right-clicked');
      ok(T._bodyUnderCursor(live.x, live.y) !== live, 'a living one still cannot');
      const acts = T._menuActsFor(foe);
      ok(acts.join() === 'eject,bag', `his rows: VENT and BAG (${acts})`);
      p.crew = p.crew.filter(c => c !== live);   // no brawl in the way of what follows

      // Left alone, he rots into our air.
      for (let i = 0; i < Ship.DECAY_SECONDS * 20 + 10; i++) p.update(0.05);
      ok(foe.decaying, 'left there, he rots');
      ok(said.some(m => /enemy body is DECAYING/.test(m)), 'and the player is told it is THEIR body');

      // VENT: carried out, and no karma for it.
      const cap = Commander.fromCrew({ id: 'k93', name: 'Ada', race: 'terra', skills: {} });
      cap.karma = 50; cap.away = true;
      Commander.setActive(cap);
      const r = p.orderBody(foe, 'eject', ours);
      ok(r.ok, `the order is taken (${r.message})`);
      let out = false;
      for (let i = 0; i < 2400 && !out; i++) { p.update(0.05); out = !p.crew.includes(foe); }
      ok(out, 'one of ours carries him to an airlock and he is gone');
      ok(cap.karma === 50, `venting a boarder costs no karma (${cap.karma})`);
      ok(said.some(m => /enemy body is out the airlock/.test(m)), 'and the line says whose body it was');

      // BAG: an unmarked grave at the dock.
      const foe2 = man(p, ours.roomId ? p.getRoomById(ours.roomId) : p.rooms[0], false);
      foe2.killOutright();
      p.cargo.clear();
      const b = p.orderBody(foe2, 'bag', ours);
      ok(b.ok && !p.crew.includes(foe2), `bagged where he lies (${b.message})`);
      const bag = p.cargo.items.find(it => it.def.tag === 'body');
      ok(bag && bag.meta.enemyBody && bag.meta.name === 'Unknown' && !bag.meta.crewBody,
         `a bag with no name in it (${bag && JSON.stringify(bag.meta)})`);
      const graves = Save.getGraveyard().length;
      const cc0 = Base.cc();
      const rep = Base.returnFromRun({ shipEntry: { key: 'frigate', data: { cargo: { items: [bag.serialise ? bag.serialise() : { defKey: bag.defKey, meta: bag.meta }] } } }, crew: [], cc: 0 });
      ok(rep.buriedUnknown === 1, `the dock buries him without a name (${rep.buriedUnknown})`);
      ok(cap.karma === 50 + Ship.UNKNOWN_BURIAL_KARMA, `for ${Ship.UNKNOWN_BURIAL_KARMA} karma (${cap.karma})`);
      ok(rep.bounty === 0 && rep.bodies === 0, 'no bounty for him — nobody posted one');
      const nn = Save.getGraveyard().slice(graves);
      ok(nn.length === 1 && nn[0].enemy && nn[0].name === 'NN' && nn[0].buried,
         `an NN stake on the hill, his own kind of marker (update93a) (${JSON.stringify(nn[0] && { e: nn[0].enemy, n: nn[0].name })})`);
      ok(Base.cc() === cc0, "no CC");
      Commander.setActive(null);
    }

    /* ── 4. SIXTY SECONDS WITHOUT HURTING US, AND THEY RUN ─────── */
    {
      const step = (s) => { for (let i = 0; i < s * 20; i++) CombatManager.update(0.05); };
      let { player, enemy } = makeCombat(sb);
      step(59);
      ok(!CombatManager.enemyEscapeActive, 'at 59 s they are still fighting');
      step(2);
      ok(CombatManager.enemyEscapeActive && CombatManager.escapeWhy === 'stalemate',
         `at 61 s they spool to run (${CombatManager.escapeWhy})`);
      ok(CombatManager.consumeEscapeNotice(), 'and the game is told, once');

      ({ player, enemy } = makeCombat(sb));
      step(50);
      Ship.noteHarmToPlayer();
      step(50);
      ok(!CombatManager.enemyEscapeActive, 'a hit at 50 s puts the clock back to zero');
      step(11);
      ok(CombatManager.enemyEscapeActive, 'and sixty more seconds of nothing does it');

      // What counts as harm.
      ({ player, enemy } = makeCombat(sb));
      const n0 = Ship.harmToPlayer();
      const room = player.rooms.find(r => r.system && r.type !== 'shields') || player.rooms[0];
      const shot = (def) => ({ def, x: room.cx, y: room.cy, targetX: room.cx, targetY: room.cy, fromPlayer: false });
      const realR = sb.Math.random;
      sb.Math.random = () => 0.99;           // no dodge, no fire, no breach
      try {
        Object.defineProperty(player, 'shieldBars', { get: () => 0, configurable: true });
        player.receiveHit(shot({ hull_damage: 1, moduleDamage: 0, crewDamage: [0, 0] }));
        ok(Ship.harmToPlayer() === n0 + 1, 'a shot that takes hull is harm');
        player.receiveHit(shot({ hull_damage: 0, moduleDamage: 0, crewDamage: [0, 0], stunTime: 1 }));
        ok(Ship.harmToPlayer() === n0 + 1, 'an ion buzz that breaks nothing is not');
        Object.defineProperty(player, 'evasion', { get: () => 1, configurable: true });   // a dodge
        player.receiveHit(shot({ hull_damage: 3 }));
        ok(Ship.harmToPlayer() === n0 + 1, 'a miss is not');
      } finally { sb.Math.random = realR; }
      const a = new CrewMember({ isPlayer: false }), v = new CrewMember({ isPlayer: true });
      a.strike(v, 1);
      ok(Ship.harmToPlayer() === n0 + 2, 'a blow from one of theirs on one of ours is harm');
      v.strike(a, 1);
      ok(Ship.harmToPlayer() === n0 + 2, 'our blow on them is not');

      // Never the boss; and the clock waits while a surrender is offered.
      ({ player, enemy } = makeCombat(sb));
      CombatManager._ai = sb.AI_DEFS.boss;
      step(70);
      ok(!CombatManager.enemyEscapeActive, 'the boss never runs');
      ({ player, enemy } = makeCombat(sb));
      CombatManager.surrenderOffer = true;
      step(70);
      ok(!CombatManager.enemyEscapeActive, 'nor while they are offering to surrender');
      CombatManager.end();

      // The cooling hand is on the combat AI's clock, every frame.
      ({ player, enemy } = makeCombat(sb));
      let calls = 0;
      enemy.coolingAI = () => { calls++; };
      step(1);
      ok(calls >= 15, `the enemy's AI looks at its core every frame of a fight (${calls})`);
      CombatManager.end();
    }

    /* ── 5. THEIR PRISONERS ARE IN CARBONITE ───────────────────── */
    {
      const seat = () => {
        for (let k = 0; k < 20; k++) {
          T._spawnEnemy('normal');
          const e = T.enemyShip;
          ['shields', 'cloaking'].forEach(t => {
            const s = e.getSystem(t);
            if (!s) return;
            const r = e.getRoomById(s.roomId);
            e.systems = e.systems.filter(x => x !== s);
            if (r) { r.system = null; r.type = 'empty'; }
          });
          if (!e.rooms.some(r => r.type === 'empty')) continue;
          const realR = sb.Math.random;
          sb.Math.random = () => 0.01;
          let n = 0;
          try { n = T._seatCaptives(); } finally { sb.Math.random = realR; }
          // …and sized after, as _spawnEnemy does: the bay is on the bill (update93a: lifts are paid first).
          if (n > 0) { e.sizeAirForCrew(e.crew.filter(c => !c.isPrisoner).length); return e; }
        }
        return null;
      };
      const e = seat();
      ok(!!e, 'test setup: a hull with captives');
      if (e) {
        const caps = e.crew.filter(c => c.isPrisoner);
        const bay = e.getSystem('carbonite');
        /* Nobody of theirs at the bay's console: a Terra there carries the
           slab on his +1, and our man walking in would contest the room and
           take it off him — a real thaw, but not the one this checks. */
        e.crew = e.crew.filter(c => c.isPrisoner || c.roomId !== bay.roomId);
        ok(caps.length > 0 && caps.every(c => c.frozen && c.roomId == null && c._slabRoom === bay.roomId),
           `every captive is in a slab of their bay (${caps.map(c => `${c.frozen}/${c.roomId}`)})`);
        e.update(0.05);
        ok(caps.every(c => c.frozen), 'and stays there while the bay is lit');
        const bayRoom = e.getRoomById(bay.roomId);
        const hero = man(e, bayRoom, true, { race: 'pegasus' });
        e.update(0.05);
        ok(caps.every(c => c.frozen && c.isPrisoner && !c.isPlayer),
           'one of ours in the bay cannot walk a man out of a slab');
        said.length = 0;
        bay.damageLevel(bay.level);
        e.update(0.05);
        ok(caps.every(c => c.frozen), 'the bay shot out — the slabs only start to warm (update127)');
        // fast-forward the melt to its last moment; the next frame lets them go
        caps.forEach(c => { c._meltT = Ship.SLAB_MELT_SECONDS; });
        e.update(0.05);
        ok(caps.every(c => !c.frozen), 'and once they have melted, they thaw');
        ok(said.some(m => /out of the carbonite/.test(m)), 'and the player is told');
        e.update(0.05);
        ok(caps.every(c => c.isPlayer && c.rescued), 'and our man in the bay walks them out');
        e.crew = e.crew.filter(c => c !== hero);
      }
      const e2 = seat();
      if (e2) {
        const caps = e2.crew.filter(c => c.isPrisoner);
        const bay = e2.getSystem('carbonite');
        bay.desiredPower = 0;
        // A Terra of theirs posted in the bay would keep it lit himself — not this case.
        e2.crew = e2.crew.filter(c => c.isPrisoner || c.roomId !== bay.roomId);
        /* A few seconds of slack (update139): the melt runs on the ship's own
           clock, and now and then the last second fell one frame short. */
        for (let t = 0; t < Ship.SLAB_MELT_SECONDS + 6 && (t < Ship.SLAB_MELT_SECONDS || caps.some(c => c.frozen)); t += 1) { bay.desiredPower = 0; e2.update(1); }
        e2.update(0.05);
        ok(caps.every(c => !c.frozen && c.roomId === bay.roomId), `no power for the bay — they thaw, in the bay (${caps.map(c => `${c.frozen}/${c.roomId}/${bay.roomId}/${c.alive}/${bay.effectivePower()}`)})`);
      }
    }

    /* ── 6. A BRAWL IN PAIRS ───────────────────────────────────── */
    {
      const p = new Ship('frigate', true, 80, 120);
      p.crew.length = 0;
      const room = p.rooms.find(r => r.type === 'shields') || p.rooms[0];
      const tough = (c) => { c.maxHp = c.hp = 100000; c.inRoom = true; return c; };
      const o1 = tough(man(p, room, true)), o2 = tough(man(p, room, true));
      const t1 = tough(man(p, room, false)), t2 = tough(man(p, room, false));
      [o1, o2, t1, t2].forEach((c, i) => { c.x = room.cx + (i - 1.5) * 3; });
      const foesOf = (c) => p.crew.filter(k => k.alive && k.roomId === room.id && k.isPlayer !== c.isPlayer);
      const S = [o1, o2, t1, t2].map(c => c.duelSpot(p, foesOf(c)));
      ok(S.every(s => s && s.pairs === 2), `two pairs (${S.map(s => s && s.pairs)})`);
      [o1, o2].forEach(o => {
        const tgt = o.meleeTarget(p, foesOf(o));
        const so = o.duelSpot(p, foesOf(o)), st = tgt.duelSpot(p, foesOf(tgt));
        ok(so.pair === st.pair, 'a man and the man he swings at are one pair');
        ok(so.x < st.x, `ours on the left of the pair, theirs on the right (${so.x.toFixed(1)} < ${st.x.toFixed(1)})`);
        ok(Math.abs(so.partnerX - st.x) < 1e-6, 'the tie line ends where his opponent stands');
      });
      ok(S[0].pair !== S[1].pair, 'and the two pairs are apart');
      ok(S.every(s => s.x >= room.x + CrewMember.MELEE_INSET - 1e-6 && s.x <= room.x + room.w - CrewMember.MELEE_INSET + 1e-6),
         'every spot inside the margin the brawl already keeps');
      for (let i = 0; i < 60; i++) p.update(0.05);
      ok([o1, o2, t1, t2].every(c => Math.abs(c.x - c._duel.x) < 0.5),
         `in three seconds they are standing in their pairs (${[o1, o2, t1, t2].map(c => (c.x - c._duel.x).toFixed(1))})`);
      ok([o1, o2].every(o => o.x < o.meleeTarget(p, foesOf(o)).x), 'facing each other across the pair');

      const q = new Ship('frigate', true, 80, 120);
      q.crew.length = 0;
      const r2 = q.rooms.find(r => r.type === 'shields') || q.rooms[0];
      const us = [0, 1, 2].map(() => tough(man(q, r2, true)));
      const one = tough(man(q, r2, false));
      const foesOfQ = (c) => q.crew.filter(k => k.alive && k.roomId === r2.id && k.isPlayer !== c.isPlayer);
      const xs = us.map(c => c.duelSpot(q, foesOfQ(c)));
      const byId = us.slice().sort((a, b) => String(a.id).localeCompare(String(b.id)));
      const sx = byId.map(c => c.duelSpot(q, foesOfQ(c)).x);
      ok(xs.every(s => s.pairs === 1), 'three on one is one pair');
      ok(sx[1] < sx[0] && sx[2] < sx[1], `the helpers stand behind the first man, a step each (${sx.map(v => v.toFixed(1))})`);
      ok(byId.filter(c => c.duelSpot(q, foesOfQ(c)).lead).length === 1, 'and one tie line for it, not three');

      // Drawn: one tie per pair.
      const ctx = initRenderer(sb);
      let ties = 0;
      const realFR = ctx.fillRect;
      ctx.fillRect = function (x, y, w, h) { if (w === 2 && h === 2 && ctx.fillStyle === 'rgba(255,214,120,0.8)') ties++; };
      try { quiet(() => p.crew.forEach(c => c.draw(ctx))); } finally { ctx.fillRect = realFR; }
      ok(ties === 2, `two pairs, two ties under their feet (${ties})`);
      for (let i = 0; i < 2; i++) { t1.killOutright(); t2.killOutright(); }
      p.update(0.05);
      ok(!o1._duel && !o2._duel, 'the fight is over, the pairs are gone');
    }

    /* ── 7. THEIR CORE: POWER COMES OFF WHEN IT IS HOT ─────────── */
    {
      /* Not every rolled hull runs hot — the loadout decides (75–89% on
         most). Take one that does: that is the one the AI is for. */
      const hotEnemy = () => {
        for (let k = 0; k < 40; k++) {
          T._spawnEnemy('normal');
          T.enemyShip.update(0.05);
          /* Not a Terra boat (update117): her yard builds the reactor
             bigger than she needs, so she is the one hull in the draw
             that is SUPPOSED to run cool. */
          if (T.enemyShip._plannedLoad() > 0.8
              && !sb.BUILDER_TRAITS[sb.hullBuilder(T.enemyShip.layoutKey)]?.reactorSpare) return T.enemyShip;
        }
        return T.enemyShip;
      };
      const e = hotEnemy();
      const want0 = new Map(e.systems.map(s => [s, s.desiredPower]));
      const load0 = e._plannedLoad();
      ok(load0 > 0.8, `a sized enemy runs above 80% (${load0.toFixed(2)})`);
      e.reactorHeat = 50;
      for (let i = 0; i < 10; i++) e.coolingAI(1);
      ok(e.systems.every(s => s.desiredPower === want0.get(s)), 'at 50° it touches nothing');
      e.reactorHeat = 75;     // the line, written out: a config read here would follow a broken config
      for (let i = 0; i < 30; i++) e.coolingAI(1);
      ok(e._plannedLoad() <= 0.70 + 1e-9, `at 75° it sheds to 70% load — 30% free, the cooling line (${e._plannedLoad().toFixed(2)})`);
      const pil = e.getSystem('piloting'), oxy = e.getSystem('oxygen'), eng = e.getSystem('engines');
      ok(!pil || pil.desiredPower === want0.get(pil), 'never the helm');
      ok(!oxy || oxy.desiredPower >= 1, 'life support keeps a unit');
      ok(!eng || eng.desiredPower >= 1, 'the engines keep the one that holds the gravity');
      ok(e.systems.filter(s => s.type === 'weapons' && s.desiredPower > 0).length >= 1, 'and one gun stays lit');
      {
        /* The last gun, on purpose: everything else already at its floor
           and one bay lit — the pick has to come back empty. A rolled
           hull only gets this far sometimes, so the corner is built. */
        const k = new Ship('enemy_gunship', false, 850, 120);
        const floorOf = (x) => x.type === 'engines' || x.type === 'oxygen' ? 1 : x.type === 'shields' ? 2 : 0;
        k.systems.forEach(x => { if (x.type !== 'reactor' && x.type !== 'piloting') x.desiredPower = Math.min(x.maxPower, floorOf(x)); });
        const bays = k.systems.filter(x => x.type === 'weapons');
        bays[0].desiredPower = Math.max(1, bays[0].maxPower);
        const pick = k._aiShedPick();
        ok(bays.length >= 1 && (!pick || pick.type !== 'weapons'), `the last lit gun is never the one taken (${pick && pick.type})`);
        if (bays.length >= 2) {
          bays[1].desiredPower = Math.max(1, bays[1].maxPower);
          ok(k._aiShedPick()?.type === 'weapons', 'with two lit, one of them may go');
        }
      }
      const shed = e._aiShed.length;
      ok(shed > 0, `${shed} unit(s) taken off`);
      e.update(0.05);
      ok(e.reactorHeatRate() < 0, 'and now the core cools');
      e.reactorHeat = H.ai.restoreAt;
      for (let i = 0; i < shed + 2; i++) e.coolingAI(1);
      ok(e.systems.every(s => s.desiredPower === want0.get(s)) && e._aiShed.length === 0,
         `cool again (${H.ai.restoreAt}°): every unit given back`);

      const p = new Ship('frigate', true, 0, 0);
      const pw = p.systems.map(s => s.desiredPower);
      p.reactorHeat = 95;
      for (let i = 0; i < 10; i++) p.coolingAI(1);
      ok(p.systems.every((s, i) => s.desiredPower === pw[i]), 'the player\'s bar is his own');

      // Ten minutes of a fight: without the hand it overheats, with it it does not.
      /* The two hulls are spawned BEFORE the dice are pinned (update117):
         with Math.random stuck at 0.99 the spawn always drew the last hull
         in the pool, Montu — a Terra boat now, built with spare reactor,
         so she never ran hot and the "left alone" half could not happen. */
      const run = (s, withAI) => {
        s.reactorHeat = 60;
        for (let t = 0; t < 600; t += 0.5) { s.update(0.5); if (withAI) s.coolingAI(0.5); }
        return s.getSystem('reactor').damagedLevels;
      };
      /* …and spawned under a seed: which hull the draw makes decides how
         hot she runs, and since the yards fit different gear (update117)
         an unseeded draw now and then produced a hot hull that still
         held out the ten minutes. */
      const [hot1, hot2] = (() => {
        let seed = 277;
        const real = sb.Math.random;
        sb.Math.random = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
        try { return [hotEnemy(), hotEnemy()]; } finally { sb.Math.random = real; }
      })();
      const sb2 = sb.Math.random; sb.Math.random = () => 0.99;   // no fire rolls
      let blown = 0, kept = 0;
      try { blown = run(hot1, false); kept = run(hot2, true); } finally { sb.Math.random = sb2; }
      ok(blown > 0, `left alone, their core overheats inside ten minutes (${blown} level(s) lost)`);
      ok(kept === 0, `with the AI's hand on it, it does not (${kept})`);
    }
  } finally {
    UI.notify = realNotify;
  }
})();

// ============================================================
section('278. Fixes from play (93a): NN graves, a free hand for their dead, the patch skill once, boarders spread, no jump to the map, the cyborg\'s pip, nebula violet, plague in the ducts, five-dose kits, names, their lifts, the boss\'s chair, the cloak');
// ============================================================
(function testUpdate93a() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, UI, Base, Renderer, CombatManager, Game, Station,
          CARGO_ITEMS, BossManager, Commander, TASK } = sb;
  const T = Game.__test;
  Save.load(); Save.startRun();
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const said = [];
  const realNotify = UI.notify;
  UI.notify = (m) => { said.push(String(m)); };
  const withRandom = (v, fn) => { const r = sb.Math.random; sb.Math.random = () => v; try { return fn(); } finally { sb.Math.random = r; } };
  const man = (ship, room, isPlayer, extra = {}) => {
    const c = new CrewMember({ isPlayer, race: isPlayer ? 'aquarius' : 'hostile', ...extra });
    c.roomId = room.id; c.homeRoomId = room.id;
    c.x = room.cx; c.y = ship.floorWalkY(room.floor, room.cy);
    ship.addCrew(c, true);
    return c;
  };
  const atConsole = (ship, c, room) => {
    const [sx, sy] = ship.stationSlot(room, 0);
    c.roomId = room.id; c.inRoom = true; c.x = sx; c.y = sy; c._waypoints = [];
  };

  try {
    /* ── 1. AN NN STAKE FOR ONE OF THEIRS ─────────────────────── */
    {
      const before = Save.getGraveyard().length;
      const rec = Save.addUnknownGrave();
      const after = Save.getGraveyard();
      ok(after.length === before + 1 && rec.enemy && rec.name === 'NN' && rec.buried,
         'an unmarked grave goes on the hill, already buried');
      ok(!Save.notRecovered().includes(rec), 'and is never listed as somebody we failed to bring home');
    }

    /* ── 2. THEIR DEAD GO OUT ONLY WITH A FREE HAND ───────────── */
    {
      const hull = () => { const e = new Ship('enemy_frigate', false, 850, 120); e._allocateDefaultPower(); e.crew.length = 0; return e; };
      const e = hull();
      const w = e.weaponRooms[0];
      const pr = e.rooms.find(r => r.type === 'piloting');
      const gunner = man(e, w, false);
      const pilot = man(e, pr, false);
      const dead = man(e, w, false);
      dead.killOutright();
      for (let i = 0; i < (Ship.AI_VENT_SECONDS + 2) * 20; i++) e.update(0.05);
      ok(!dead.bodyOrder && !dead.carriedBy, `the pilot and the last gunner are not free hands — he stays (${dead.bodyOrder})`);
      ok(gunner.roomId === w.id && !gunner.carrying, 'and the gunner beside him stays on his gun');
      const spareRoom = e.rooms.find(r => r !== w && r !== pr && r.system);
      const spare = man(e, spareRoom, false);
      e.update(0.05);
      ok(dead.bodyOrder === 'eject' && spare._rescueId === dead.id, 'a spare man turns up: he is the one sent');
      let carrier = null;
      for (let i = 0; i < 1200 && !carrier; i++) { e.update(0.05); carrier = dead.carriedBy; }
      ok(carrier === spare, `and he is the one who lifts him (${carrier && carrier.name})`);
      void pilot;
    }

    /* ── 3. THE PATCHING SKILL COUNTS ONCE ────────────────────── */
    {
      const sh = new Ship('frigate', true, 80, 120);
      sh.crew.length = 0;
      const room = sh.rooms.find(r => r.system && r.type !== 'reactor');
      const c = man(sh, room, true);
      c.skills.breach.level = 3;
      sh.breaches.open(room.id, c.x, c.y);
      const hole = sh.breaches._breaches[0];
      ok(!!hole, 'test setup: a hole');
      if (hole) {
        c.assignTask(TASK.BREACH, hole);
        const p0 = hole.progress;
        const dt = 0.05;
        c._updateTask(dt, sh);
        const got = hole.progress - p0;
        const want = dt * 0.2 * c.breachSpeed() * (sh.breachFactor ? sh.breachFactor() : 1);
        ok(Math.abs(got - want) < 1e-9, `a master patches at his speed once, not squared (${got.toFixed(5)} vs ${want.toFixed(5)})`);
      }
    }

    /* ── 4. A BOARDING PARTY SPREADS OUT ──────────────────────── */
    {
      const p = new Ship('frigate', true, 80, 120);
      p._allocateDefaultPower();
      p.crew.length = 0;
      const start = p.rooms.find(r => !r.system) || p.rooms[0];
      const a = man(p, start, false, { race: 'pegasus' }), b = man(p, start, false, { race: 'pegasus' });
      b.x += 6;
      /* Their FIRST picks: where each one sets off for the first time
         he has somewhere to go. Later on they drift apart anyway — the
         bug was the single file at the start. */
      const firstPick = new Map();
      for (let i = 0; i < 600 && firstPick.size < 2; i++) {
        p.update(0.05);
        [a, b].forEach(c => {
          if (firstPick.has(c) || !c._waypoints?.length) return;
          const d = c.destPoint();
          const room = p.rooms.find(r => r.contains(d.x, d.y));
          if (room && room.system) firstPick.set(c, room.id);
        });
      }
      ok(firstPick.size === 2 && firstPick.get(a) !== firstPick.get(b),
         `two boarders set off for two different modules, not one behind the other (${[...firstPick.values()]})`);
    }

    /* ── 5. A WON FIGHT ENDS ON THE SHIP, NOT ON THE MAP ──────── */
    {
      const { player, enemy } = makeCombat(sb);
      enemy.hull = 0; enemy.crew.length = 0;
      quiet(() => { for (let i = 0; i < 80; i++) T._updateCombat(0.05); });
      ok(CombatManager.isVictory(), 'test setup: won');
      const real = sb.Input.isPressed;
      sb.Input.isPressed = (k) => k === 'Enter';
      try { quiet(() => T._updateCombat(0.05)); } finally { sb.Input.isPressed = real; }
      /* update138 turned this round (jj: "jak skok, to skok, a nie przedskok i
         skok"): JUMP opens the chart, and the node he picks is the jump. */
      ok(T.STATE === 'map' && T._mapView === 'map' && T._jumpPrompt === true,
         `JUMP opens the chart and asks where to (${T.STATE}/${T._mapView})`);
      void player;
    }

    /* ── 6. THE CYBORG'S +1 IS THE OPERATOR'S, AND IT IS CYAN ───── */
    {
      const sh = new Ship('frigate', true, 0, 0);
      sh.crew.length = 0;
      const cy = new CrewMember({ name: 'Cy', race: 'terra' });
      sh.addCrew(cy, true);
      const eng = sh.getSystem('engines');
      const room = sh.getRoomById(eng.roomId);
      // in the room, off the console
      cy.roomId = room.id; cy.inRoom = true;
      const [s1x, s1y] = sh.stationSlot(room, 1); cy.x = s1x; cy.y = s1y;
      sh.update(0.05);
      ok(!eng.hasCyborg, 'standing in the module but off its console: no +1');
      atConsole(sh, cy, room); sh.update(0.05);
      ok(eng.hasCyborg, 'at the console: his +1');

      // A full module: his unit is the cyan pip, whatever the allocation says.
      eng.level = 2; eng.desiredPower = 2; sh.update(0.05);
      const ctx = initRenderer(sb);
      const pips = () => {
        const out = [];
        const rr = ctx.fillRect;
        const MP = Renderer.modulePip();      // the pip of the layout on screen (update134)
        ctx.fillRect = function (x, y, w, h) { if (w === MP.w && h === MP.h) out.push(String(ctx.fillStyle)); };
        try { quiet(() => Renderer.drawHUD({ playerShip: sh })); } finally { ctx.fillRect = rr; }
        return out;
      };
      const full = pips().filter(f => f === '#4dffd8').length;
      eng.desiredPower = 1; sh.update(0.05);
      const less = pips().filter(f => f === '#4dffd8').length;
      ok(full === 1 && less === 1, `one cyan pip, full or one short — the same picture of the same state (${full}/${less})`);

      // He walks off a full module: his unit goes with him.
      eng.desiredPower = 2; sh.update(0.05);
      const spare0 = sh.availablePower();
      const off = sh.rooms.find(r => r.system && r !== room && r.type !== 'reactor');
      atConsole(sh, cy, off); sh.update(0.05);
      ok(eng.desiredPower === 1 && eng.power <= 1, `the engines drop the unit he was covering (${eng.desiredPower})`);
      ok(sh.availablePower() <= spare0 + 1, 'and the bank does not mint a unit out of his leaving');

      // The reactor: a Terra repairing it does not paint the broken pip over.
      const r = new Ship('frigate', true, 0, 0);
      r.crew.length = 0;
      const t = new CrewMember({ name: 'Tor', race: 'terra' });
      r.addCrew(t, true);
      r.systems.forEach(x => { x.damagedLevels = 0; });
      r.getSystem('reactor').damageLevel(1);
      atConsole(r, t, r.getRoomById(r.getSystem('reactor').roomId));
      r.update(0.05);
      const red = (() => {
        quiet(() => Renderer.drawHUD({ playerShip: r }));
        return (Renderer.reactorBarRect()?.fills ?? []).map(String);
      })();
      ok(red.filter(f => f === '#cc2233').length === 1, 'the broken reactor level stays red while a Terra stands at it');
      ok(red.filter(f => f === '#4dffd8').length >= 1, 'and his unit shows as his own, cyan');

      // The nebula's units are violet, not red.
      const n = new Ship('frigate', true, 0, 0);
      n.crew.length = 0;
      n.systems.forEach(x => { x.damagedLevels = 0; });
      n.reactor.penalty = 2; n.update(0.05);
      const nf = (() => {
        quiet(() => Renderer.drawHUD({ playerShip: n }));
        return (Renderer.reactorBarRect()?.fills ?? []).map(String);
      })();
      ok(nf.filter(f => f === '#8a3fbf').length === 2 && nf.filter(f => f === '#cc2233').length === 0,
         `two units held by the nebula: two violet pips, no red (${nf.filter(f => f === '#8a3fbf').length})`);
    }

    /* ── 7. THE PLAGUE RIDES THE DUCTS ────────────────────────── */
    {
      const build = () => {
        const sh = new Ship('frigate', true, 0, 0);
        sh._allocateDefaultPower();
        sh.crew.length = 0;
        const src = sh.rooms.find(r => r.system && r.type === 'shields') || sh.rooms[0];
        const body = man(sh, src, true); body.killOutright(); body.decaying = true;
        // hops by the ducts, from the rotting room
        const hops = new Map([[src.id, 0]]); const q = [src.id];
        for (let i = 0; i < q.length; i++) sh.ductLinks(q[i]).forEach(l => { if (!hops.has(l.room.id)) { hops.set(l.room.id, hops.get(q[i]) + 1); q.push(l.room.id); } });
        const at = (h) => sh.rooms.find(r => hops.get(r.id) === h);
        return { sh, src, at, hops };
      };
      const { sh, at } = build();
      const r1 = at(1), r2 = at(2), r3 = [...sh.rooms].find(r => r.id !== sh.rooms[0]?.id && (build().hops.get(r.id) ?? 0) >= 3);
      ok(!!r1 && !!r2, 'test setup: rooms one and two ducts away');
      const c1 = man(sh, r1, true), c2 = man(sh, r2, true);
      const c3 = r3 ? man(sh, r3, true) : null;
      // One second, a fixed roll: next door (0.03) and further (0.012) behave differently.
      withRandom(0.025, () => sh._updateBodies(1));
      ok(c1.infected && !c2.infected, `0.025 a second: next door through the duct catches it, two away does not (${c1.infected}/${c2.infected})`);
      if (c3) {
        withRandom(0.010, () => sh._updateBodies(1));
        ok(c3.infected, 'far along the ducts it still travels — faster than the old ship-wide trickle');
      }
      const dark = build();
      const d1 = man(dark.sh, dark.at(1), true);
      const o2 = dark.sh.getSystem('oxygen'); o2.desiredPower = 0; o2.power = 0;
      dark.sh.update(0.0001);
      withRandom(0.001, () => dark.sh._updateBodies(1));
      ok(!d1.infected, 'life support dark: nothing moves in the ducts');
    }

    /* ── 8. FIVE DOSES, 30 CC ─────────────────────────────────── */
    {
      ok(CARGO_ITEMS.medkit.stackMax === 5, 'a box of medical supplies is five doses');
      const st = new Station(1, 7);
      ok(st.medkitCost(1) === Math.round(30 * st._priceFactor()), `for 30 CC at an honest price (${st.medkitCost(1)})`);
    }

    /* ── 9. ONE NAME, ONE MAN, BOTH SIDES ─────────────────────── */
    {
      const p = new Ship('frigate', true, 80, 120);
      p.crew.length = 0;
      sb.makeStartingCrew().forEach(c => p.addCrew(c));
      T.playerShip = p;
      const ours = new Set(p.crew.map(c => c.name));
      let clash = 0;
      // 100 crews of 4: by chance alone ~12 of them would wear one of our three names.
      for (let i = 0; i < 100; i++) sb.makeEnemyCrew(4).forEach(c => { if (ours.has(c.name)) clash++; });
      ok(clash === 0, `a hundred enemy crews, not one name already at our consoles (${clash})`);
      let freshClash = 0;
      for (let i = 0; i < 300; i++) if (ours.has(new CrewMember({}).name)) freshClash++;
      ok(freshClash === 0, `nor a captive or a rescued man drawn out of thin air (${freshClash}/300)`);
      let portClash = 0, dup = 0;
      // ~300 recruits: drawn with replacement, a dozen would carry one of our names.
      for (let i = 0; i < 200; i++) {
        const st = new Station(2, 100 + i);
        const names = (st.stock.crew ?? []).map(x => x.name);
        names.forEach(n => { if (ours.has(n)) portClash++; });
        if (new Set(names).size !== names.length) dup++;
      }
      ok(portClash === 0 && dup === 0, `a port's recruits: none of ours, no two alike (${portClash}/${dup})`);
    }

    /* ── 10. THEIR LIFTS RUN WHILE THEIR CORE DOES ────────────── */
    {
      T._spawnEnemy('normal');
      const e = T.enemyShip;
      /* Every module asking for everything and a core of exactly that
         plus the lifts — the sized enemy, with no spare to hide in (an
         idle gun bay asks for nothing and would leave one). */
      let need = e.liftPowerNeed();
      e.systems.forEach(s => { if (s.type !== 'reactor') { s.desiredPower = s.maxPower; need += s.maxPower; } });
      e.reactor.maxLevel = Math.max(e.reactor.maxLevel, need); e.reactor.level = need;
      e.crew.forEach(c => { c.cyborg = false; });   // a Terra at a console would free a unit of his own
      e.update(0.05);
      const shafts = e.elevators?.shafts?.length ?? 0;
      ok(shafts > 0, 'test setup: a hull with a lift');
      e.getSystem('reactor').damageLevel(1);
      e.update(0.05);
      ok(e.liftsPowered() === shafts, `one level of their reactor shot out: the lifts still run (${e.liftsPowered()}/${shafts})`);
      e.getSystem('reactor').damageLevel(99);
      e.update(0.05);
      ok(e.liftsPowered() === 0, 'the whole core wrecked: now they stop');

      const { enemy } = makeCombat(sb);
      enemy.systems.forEach(s => { s.damagedLevels = 0; });
      enemy.getSystem('reactor').damageLevel(1);
      enemy.systems.filter(s => s.type !== 'reactor').forEach(s => s.damageLevel(1));
      // ONE hand to give: whatever he is sent to is what came first.
      enemy.crew = enemy.crew.filter(c => c.alive).slice(0, 1);
      enemy.crew.forEach(c => { c.assignTask(TASK.IDLE); c.roomId = enemy.rooms.find(r => !r.system)?.id ?? c.roomId; });
      CombatManager._updateAI(0.05);
      const rid = enemy.getSystem('reactor').roomId;
      ok(enemy.crew.some(c => c.task === TASK.REPAIR && c.taskTarget === rid),
         'their first free hand goes to the reactor');
      CombatManager.end();
    }

    /* ── 11. THE BOSS HAS HIS CHAIR AND HIS CHEST ─────────────── */
    {
      Commander.setEnemy(null);
      BossManager.reset('station');
      const boss = quiet(() => BossManager.start(0, 850, 120));
      ok(!!Commander.enemy() && boss.commander === Commander.enemy(), 'the boss always has a commander');
      ok(boss.doseCount() >= 10, `and a medicine chest (${boss.doseCount()} doses)`);
      const cap = Commander.enemy();
      // A phase hull rebuilt — what nextPhase does — keeps the same man.
      quiet(() => BossManager._buildPhaseShip(850, 120));
      ok(BossManager._ship.commander === cap && Commander.enemy() === cap, 'the same man in the chair for the next phase');
      BossManager.reset('station');
      ok(!BossManager.captain, 'a fresh boss gets a fresh one');
      Commander.setEnemy(null);
    }
  } finally {
    UI.notify = realNotify;
  }
})();

// ============================================================
section('279. Salvage (93b): crates in the wreckage, a man in his suit, the loot screen, and nobody left behind by accident');
// ============================================================
(function testUpdate93bSalvage() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, UI, Game, CombatManager, Input, LootScreen, Renderer, COMBAT_STATE } = sb;
  const T = Game.__test;
  Save.load(); Save.startRun();
  const said = [];
  const realNotify = UI.notify;
  UI.notify = (m) => { said.push(String(m)); };
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const ctx = initRenderer(sb);
  const frames = (n, dt = 0.05) => { for (let i = 0; i < n && T.STATE === 'combat'; i++) quiet(() => T._updateCombat(dt)); };
  /* A fight we have just won by blowing her up. */
  const blowUp = (tweak = () => {}) => {
    const c = makeCombat(sb);
    tweak(c.enemy);
    c.enemy.hull = 0;
    frames(60);
    return c;
  };
  const click = (x, y) => {
    Input.mouse.x = x; Input.mouse.y = y; Input.mouse.leftPressed = true;
    quiet(() => T._updateCombat(0.05));
    Input.mouse.leftPressed = false;
    Input.mouse.leftReleased = true;          // …and let go, as a hand does
    quiet(() => T._updateCombat(0.05));
    Input.mouse.leftReleased = false;
  };
  const closeLoot = () => {
    quiet(() => LootScreen.draw(ctx));
    const z = LootScreen._zoneFor('done');
    Input.mouse.x = z.x + 4; Input.mouse.y = z.y + 4; Input.mouse.leftPressed = true;
    quiet(() => LootScreen.update(0.016));
    Input.mouse.leftPressed = false;
  };
  const pressJump = () => {
    const real = Input.isPressed;
    Input.isPressed = (k) => k === 'Enter';
    try { quiet(() => T._updateCombat(0.05)); } finally { Input.isPressed = real; }
  };

  try {
    /* ── 1. ONLY A HULL THAT WENT UP LEAVES CRATES ─────────────── */
    {
      const { enemy } = blowUp();
      const S = CombatManager.salvage;
      ok(CombatManager.isVictory() && !!S, 'her hull destroyed: wreckage to search');
      ok(S && S.crates.length >= 1 && S.crates.length <= 4, `one to four crates (${S && S.crates.length})`);
      void enemy;

      const c2 = makeCombat(sb);
      c2.enemy.crew.forEach(k => k.killOutright());
      CombatManager.state = COMBAT_STATE.VICTORY;     // won, and her hull still whole
      frames(5);
      ok(c2.enemy.hull > 0 && !CombatManager.salvage, 'a crew beaten to the last man leaves a hulk, not crates');
      CombatManager.end();
    }

    /* ── 2. A BIGGER SHIP, MORE AND BETTER — AND SOME ARE EMPTY ──── */
    {
      let small = 0, big = 0, empty = 0, total = 0, medInCrates = 0;
      for (let i = 0; i < 24; i++) {
        blowUp(e => { e.hullMax = 5; e.weapons = []; e.commander = null; });   // class 0: always one crate
        small += CombatManager.salvage.crates.length;
        CombatManager.salvage.crates.forEach(k => { total++; if (!k.grid) empty++; });
        CombatManager.end();
        // A marker no wreck table rolls: if it is in a crate, it came out of HER hold.
        blowUp(e => { e.hullMax = 30; e.commander = { name: 'X' }; e.cargo.clear(); e.cargo.add('pet_bag'); });
        big += CombatManager.salvage.crates.length;
        CombatManager.salvage.crates.forEach(k => { total++; if (!k.grid) empty++;
          if (k.grid && k.grid.items.some(it => it.defKey === 'pet_bag')) medInCrates++; });
        CombatManager.end();
      }
      ok(big > small * 1.5, `a big ship leaves more crates than a small one (${big} vs ${small} over 24 each)`);
      ok(empty > 0 && empty < total, `some crates are empty, not all (${empty}/${total})`);
      ok(medInCrates > 0, 'and what she was carrying drifts out with them');
    }

    /* ── 3. ONE TRIP: OUT, CUT, OPEN, BACK — HIS OWN AIR ─────────── */
    const trip = (race) => {
      const { player } = blowUp();
      const S = CombatManager.salvage;
      const crate = S.crates[0];
      crate.grid = crate.grid || new sb.CargoGrid(3, 3);
      if (!crate.grid.items.length) crate.grid.add('ration_pack');
      const man = player.crew.find(c => c.isPlayer && c.alive);
      man.race = race; man.hp = man.maxHp; man.air = man.airMax();
      UI.selectCrew(man);
      click(crate.x, crate.y);
      ok(S.men.some(m => m.c === man), `${race}: sent for the crate`);
      let opened = false, outSeen = false;
      for (let i = 0; i < 1200 && !opened; i++) {
        quiet(() => T._updateCombat(0.05));
        if (!player.crew.includes(man)) outSeen = true;
        opened = LootScreen.isOpen();
      }
      ok(outSeen, `${race}: he left the hull — off the crew list while out there`);
      ok(opened && T.STATE === 'loot', `${race}: the cut goes through and the two holds come up`);
      const roster = Renderer.crewRoster({ playerShip: player });
      ok(roster.includes(man) && man._awayTeam, `${race}: and he is on the roster, marked away`);
      closeLoot();
      ok(T.STATE === 'combat', `${race}: DONE puts us back over the wreckage`);
      let home = false;
      for (let i = 0; i < 1200 && !home; i++) { quiet(() => T._updateCombat(0.05)); home = player.crew.includes(man); }
      ok(home && man.alive, `${race}: and he comes home`);
      const lost = man.maxHp - man.hp;
      CombatManager.end();
      return lost;
    };
    const pegLoss = trip('pegasus');
    ok(pegLoss === 0, `a Pegasus tank (26 s) does the round trip without a scratch (${pegLoss.toFixed(1)} HP)`);
    /* SEEDED (update116). This one measurement flickered: 30.1 once in
       a few hundred runs, because the wreck, the crate and the walk out
       are rolled. The rule is "a little HP, not a lot" — not "whatever
       the dice gave today" — so the dice are fixed for it. */
    const manLoss = (() => {
      let seed = 116;
      const real = Math.random;
      Math.random = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
      try { return trip('aquarius'); } finally { Math.random = real; }
    })();
    ok(manLoss > 0 && manLoss < 30, `an ordinary suit runs dry on the way back: a little HP, not a lot (${manLoss.toFixed(1)})`);

    /* ── 4. AN EMPTY CRATE SAYS SO ─────────────────────────────── */
    {
      const { player } = blowUp();
      const S = CombatManager.salvage;
      const crate = S.crates[0];
      crate.grid = null;
      const man = player.crew.find(c => c.isPlayer && c.alive);
      man.race = 'pegasus';
      UI.selectCrew(man);
      said.length = 0;
      click(crate.x, crate.y);
      for (let i = 0; i < 800 && crate.state !== 'taken'; i++) quiet(() => T._updateCombat(0.05));
      ok(crate.state === 'taken' && !LootScreen.isOpen(), 'an empty crate: no screen');
      ok(said.some(m => /empty/.test(m)), 'and he says it was empty');
      CombatManager.end();
    }

    /* ── 5. TWO ON ONE TANK ────────────────────────────────────── */
    {
      const { player } = blowUp(e => { e.hullMax = 40; e.commander = { name: 'X' }; });
      const S = CombatManager.salvage;
      while (S.crates.length < 2) S.crates.push({ ...S.crates[0], id: `x${S.crates.length}`, x: S.crates[0].x + 40, by: null, cutT: 0, state: 'sealed' });
      S.crates.forEach(k => { k.grid = new sb.CargoGrid(3, 3); k.grid.add('ration_pack'); k.state = 'sealed'; });
      const [a, b] = S.crates;
      const man = player.crew.find(c => c.isPlayer && c.alive);
      man.race = 'pegasus';
      UI.selectCrew(man);
      click(a.x, a.y); click(b.x, b.y);
      const m = S.men.find(x => x.c === man);
      ok(m && m.queue.length === 2, `two crates on his round (${m && m.queue.join(',')})`);
      let opened = 0;
      for (let i = 0; i < 2400 && opened < 2; i++) {
        quiet(() => T._updateCombat(0.05));
        if (LootScreen.isOpen() && T.STATE === 'loot') { opened++; closeLoot(); }
      }
      ok(opened === 2 && a.state !== 'sealed' && b.state !== 'sealed', `both cut open in one trip (${opened})`);
      CombatManager.end();
    }

    /* ── 5b. A JUMP WHILE HE IS STILL IN THE HATCH (update138) ─── */
    {
      const { player } = blowUp();
      const S = CombatManager.salvage;
      const crate = S.crates[0];
      const man = player.crew.find(c => c.isPlayer && c.alive);
      UI.selectCrew(man);
      click(crate.x, crate.y);
      for (let i = 0; i < 600 && S.men.find(x => x.c === man)?.phase !== 'hatch'; i++) quiet(() => T._updateCombat(0.05));
      ok(S.men.find(x => x.c === man)?.phase === 'hatch', 'test setup: he is in the hatch');
      pressJump();
      ok(T.STATE === 'map' && man.alive && player.crew.includes(man),
         `a jump while he is still in the hatch takes him along — he never left the hull (${T.STATE}, alive ${man.alive}, aboard ${player.crew.includes(man)}, ship ${T.playerShip === player})`);
      CombatManager.end();
    }

    /* ── 6. A JUMP WITH A MAN OUTSIDE ──────────────────────────── */
    {
      const { player } = blowUp();
      const S = CombatManager.salvage;
      const crate = S.crates[0];
      const man = player.crew.find(c => c.isPlayer && c.alive);
      man.race = 'pegasus';
      UI.selectCrew(man);
      click(crate.x, crate.y);
      // out = through the hatch, not just in it (update138: it opens first)
      const outside = () => !player.crew.includes(man) && S.men.find(x => x.c === man)?.phase !== 'hatch';
      for (let i = 0; i < 600 && !outside(); i++) quiet(() => T._updateCombat(0.05));
      ok(outside(), 'test setup: he is out');
      said.length = 0;
      pressJump();
      ok(T.STATE === 'combat' && man.alive, 'the first JUMP only warns');
      ok(said.some(m => /still outside/.test(m)), 'and says who is out there');
      pressJump();
      ok(T.STATE === 'map' && man.dead, 'the second means it: we jump, and he is lost');
      ok(Save.getGraveyard().some(g => g.name === man.name && !g.buried), 'and he is on the memorial, never recovered');
      ok(!CombatManager.salvage, 'the wreckage is gone with the fight');
      T.STATE = 'combat';
    }

    /* ── 7. ALL HANDS OUT IS NOT A LOST SHIP ───────────────────── */
    {
      const { player } = blowUp();
      const S = CombatManager.salvage;
      const man = player.crew.find(c => c.isPlayer && c.alive);
      man.race = 'pegasus';
      player.crew = player.crew.filter(c => c === man || !c.isPlayer);
      UI.selectCrew(man);
      click(S.crates[0].x, S.crates[0].y);
      for (let i = 0; i < 400 && player.crew.includes(man); i++) quiet(() => T._updateCombat(0.05));
      frames(20);
      ok(!player.crew.includes(man) && T.STATE !== 'outcome', 'our only man outside: he is counted, the game goes on');
      CombatManager.end();
    }

    /* ── 8. BOARDERS GO DOWN WITH HER, OR ARE LEFT ─────────────── */
    {
      const c = makeCombat(sb);
      const b = c.player.crew.find(k => k.isPlayer && k.alive);
      c.player.crew = c.player.crew.filter(k => k !== b);
      b.race = 'pegasus';
      c.enemy.addCrew(b, true);
      c.enemy.hull = 0;
      frames(5);
      ok(b.dead, 'one of ours on her deck when she blows: lost with her');

      const d = makeCombat(sb);
      const b2 = d.player.crew.find(k => k.isPlayer && k.alive);
      d.player.crew = d.player.crew.filter(k => k !== b2);
      d.enemy.addCrew(b2, true);
      CombatManager.state = COMBAT_STATE.FLED;
      frames(1);
      ok(b2.dead, 'we jump with one of ours on their deck: he is left there');

      const e = makeCombat(sb);
      const b3 = e.player.crew.find(k => k.isPlayer && k.alive);
      e.player.crew = e.player.crew.filter(k => k !== b3);
      e.enemy.addCrew(b3, true);
      CombatManager.state = COMBAT_STATE.ENEMY_FLED;
      frames(1);
      ok(b3.dead, 'they jump with one of ours aboard: gone with them');

      const f = makeCombat(sb);
      f.player.cargo.addStack('he2_med', 5);      // a jump needs He2 in the hold
      const cap = sb.Commander.fromCrew({ id: 'k93b', name: 'Ada', race: 'terra', skills: {} });
      cap.karma = 50; sb.Commander.setActive(cap); T.commander = cap;   // RETREAT is a commander's order
      said.length = 0;
      const b4 = f.player.crew.find(k => k.isPlayer && k.alive);
      f.player.crew = f.player.crew.filter(k => k !== b4);
      f.enemy.addCrew(b4, true);
      manCockpit(f.player); f.player.update(0.05);
      const real = Input.isPressed;
      Input.isPressed = (k) => k === 'KeyR';
      try { quiet(() => T._updateCombat(0.05)); } finally { Input.isPressed = real; }
      ok(said.some(m => /RECALL them before the jump/.test(m)), `spooling a jump with a man aboard them warns to RECALL (${said.slice(-2)})`);
      sb.Commander.setActive(null); T.commander = null;
      CombatManager.end();
    }

    /* ── 9. DRAWN ──────────────────────────────────────────────── */
    {
      const { player } = blowUp();
      const S = CombatManager.salvage;
      const man = player.crew.find(c => c.isPlayer && c.alive);
      man.race = 'pegasus';
      UI.selectCrew(man);
      click(S.crates[0].x, S.crates[0].y);
      for (let i = 0; i < 400 && player.crew.includes(man); i++) quiet(() => T._updateCombat(0.05));
      const t = captureText(ctx, () => quiet(() => T._drawCombat(ctx))).map(x => x.t);
      ok(t.includes(man.name.toUpperCase()), `the crate he is going for carries his name (${t.filter(x => /[A-Z]{3}/.test(x)).slice(0, 6)})`);
      ok(S.crates.length < 2 || t.includes('SEALED') || t.includes('CUT [CLICK]'), 'the others say SEALED');
      CombatManager.end();
    }
  } finally {
    UI.notify = realNotify;
  }
})();

// ============================================================
section('280. Fixes from play (93c): the reactor badge lit, enemy bags sold for research, one ion bolt one level, the hold heats the core');
// ============================================================
(function testUpdate93c() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, UI, Renderer, CargoItem, REACTOR_HEAT_CONFIG: H } = sb;
  Save.load(); Save.startRun();
  const realNotify = UI.notify;
  UI.notify = () => {};
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const ctx = initRenderer(sb);
  try {
    /* ── 1. THE REACTOR'S BADGE IS LIT LIKE ANY RUNNING MODULE ─── */
    {
      const sh = new Ship('frigate', true, 80, 120);
      sh._allocateDefaultPower(); sh.update(0.05);
      const badge = () => {
        const seen = [];
        const real = Renderer.drawSystemIcon;
        Renderer.drawSystemIcon = (c, type, x, y, size, col) => { seen.push({ type, col }); };
        try { quiet(() => sh.draw(ctx)); } finally { Renderer.drawSystemIcon = real; }
        return seen.find(s => s.type === 'reactor')?.col;
      };
      const eng = () => {
        const seen = [];
        const real = Renderer.drawSystemIcon;
        Renderer.drawSystemIcon = (c, type, x, y, size, col) => { seen.push({ type, col }); };
        try { quiet(() => sh.draw(ctx)); } finally { Renderer.drawSystemIcon = real; }
        return seen.find(s => s.type === 'oxygen')?.col;
      };
      ok(badge() === eng(), `a running reactor's badge is lit like a running module (${badge()} vs ${eng()})`);
      sh.reactor.offline = true; sh.update(0.05);
      ok(badge() === '#8a7b7b', 'scrammed: grey');
      sh.reactor.offline = false;
      sh.getSystem('reactor').damageLevel(99); sh.update(0.05);
      ok(badge() === '#8a7b7b', 'every level shot out: grey');
    }

    /* ── 2. A BAGGED ENEMY: 20 CC, AND ONLY TO RESEARCHERS ─────── */
    {
      const bag = new CargoItem('body_bag', { name: 'Unknown', enemyBody: true, bounty: 0 });
      ok(bag.value('science') === sb.ENEMY_BODY_PRICE && sb.ENEMY_BODY_PRICE === 20, `a research post pays 20 CC (${bag.value('science')})`);
      ok(bag.value('general') === 0 && bag.value('military') === 0 && bag.value('outpost') === 0, 'nobody else pays anything');
      ok(!bag.sellRefusal('science') && /research post/.test(bag.sellRefusal('general')), 'and says where to take him');
      const ours = new CargoItem('body_bag', { name: 'Zeb', crewId: 'z', crewBody: true });
      ok(/your own/.test(ours.sellRefusal('science')), 'one of ours is never for sale');
      const pirate = new CargoItem('body_bag', { name: 'Kade', bounty: 80, wantedId: 'w1' });
      ok(pirate.value('general') === 80 && !pirate.sellRefusal('general'), 'a pirate on the board is still his bounty, anywhere');
    }

    /* ── 3. ONE ION BOLT, ONE LEVEL ────────────────────────────── */
    {
      const sh = new Ship('frigate', true, 80, 120);
      const e = sh.getSystem('engines');
      e.level = 2; e.desiredPower = 2;
      sh.reactor.level = Math.max(sh.reactor.level, 12);
      sh.update(0.05);
      ok(e.effectivePower() === 2 && sh.gravityActive, 'test setup: engines on two, gravity on');
      e.ionHit(1);
      sh.update(0.01);
      ok(e.ionDamage === 1 && e.effectivePower() === 1, `one bolt: one level locked (${e.ionDamage}, running ${e.effectivePower()})`);
      ok(sh.gravityActive && !e.isDisabled(), 'and the gravity holds on the other');
      ok(Renderer.moduleIconState(e) === 'running', 'the module still reads as running');
      e.ionHit(1);
      sh.update(0.01);
      ok(e.effectivePower() === 0 && !sh.gravityActive, 'the second bolt: both locked, zero-G');
      for (let i = 0; i < 25; i++) sh.update(0.05);
      ok(e.ionDamage === 0 && e.effectivePower() === 2 && sh.gravityActive, 'the locks run out and she is whole again');
      const one = new Ship('frigate', true, 80, 120);
      const e1 = one.getSystem('engines'); e1.level = 1; e1.desiredPower = 1; one.update(0.05);
      e1.ionHit(1); one.update(0.01);
      ok(!one.gravityActive, 'a level-1 drive: one bolt is enough');
      // drawn: one blue pip for one lock
      e.ionHit(1); sh.update(0.01);
      const fills = [];
      const rr = ctx.fillRect;
      const MP = Renderer.modulePip();
      ctx.fillRect = function (x, y, w, h) { if (w === MP.w && h === MP.h) fills.push(String(ctx.fillStyle)); };
      try { quiet(() => Renderer.drawHUD({ playerShip: sh })); } finally { ctx.fillRect = rr; }
      ok(fills.filter(f => f === '#4db8ff').length >= 1 && e.ionDamage === 1,
         'the locked unit is drawn blue, the rest stay orange');
    }

    /* ── 4. THE HOLD HEATS (OR COOLS) THE CORE ─────────────────── */
    {
      const sh = new Ship('frigate', true, 80, 120);
      sh.cargo.clear();
      sh._loadHeatRate = () => 0;            // the load holds: only the hold counts
      ok(sh.reactorHeatRate() === 0, 'test setup: nothing heating');
      sh.cargo.add('unstable_core');
      ok(Math.abs(sh.reactorHeatRate() - H.cargo.corePerSec) < 1e-9, 'an unstable core in the hold heats the reactor');
      sh.cargo.add('cooler_crate');
      ok(Math.abs(sh.reactorHeatRate()) < 1e-9, 'a cooler in the hold cancels it');
      sh.cargo.items.filter(it => it.def.tag === 'rad').forEach(it => sh.cargo.remove(it));
      ok(sh.reactorHeatRate() < 0, 'a cooler on its own cools the reactor');
      const real = new Ship('frigate', true, 80, 120), plain = new Ship('frigate', true, 80, 120);
      real.cargo.clear(); plain.cargo.clear();
      real.cargo.add('unstable_core');
      for (let i = 0; i < 100; i++) { real.update(0.1); plain.update(0.1); }
      ok((real.reactorHeat ?? 0) > (plain.reactorHeat ?? 0) + 1,
         `and it does, over time, through the ship's own clock (${(real.reactorHeat ?? 0).toFixed(1)} vs ${(plain.reactorHeat ?? 0).toFixed(1)})`);
      const tip = real.moduleInfo(real.getSystem('reactor')).rows.map(r => r.text).join('|');
      ok(/Hold: 1 unstable core, 0 coolers — heating the reactor/.test(tip), 'the reactor card says so');
    }
  } finally {
    UI.notify = realNotify;
  }
})();

// ============================================================
section('281. Bunkers and mechs (94): armour, no shields, no dodging, nobody runs, torpedoes for the plate, Terra\'s bigger tank');
// ============================================================
(function testUpdate94() {
  const sb = loadEngine();
  const { Ship, Save, UI, Renderer, CombatManager, Weapon, Station, WEAPON_DEFS, SUIT_AIR, BossManager } = sb;
  const T = sb.Game.__test;
  Save.load(); Save.startRun();
  const realNotify = UI.notify;
  UI.notify = () => {};
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const ctx = initRenderer(sb);
  const realR = sb.Math.random;
  try {
    /* ── 1. TERRA'S TANK: A LITTLE BIGGER THAN THE ORDINARY ONE ─ */
    ok(SUIT_AIR.TANK.terra === 16, `Terra carries 16 in her tank (${SUIT_AIR.TANK.terra})`);
    ok(SUIT_AIR.TANK.terra > (SUIT_AIR.TANK.aquarius ?? 0), 'more than an ordinary suit');

    /* ── 2. THE TORPEDO: 3 ON A HIT, A LONG LOAD, ITS OWN ROUND ─ */
    const td = WEAPON_DEFS.torpedo_launcher;
    ok(!!td && td.hull_damage === 3 && td.moduleDamage === 3, 'a torpedo hits for 3');
    ok(td.chargeTime > WEAPON_DEFS.missile_basic.chargeTime && td.chargeTime > WEAPON_DEFS.laser_heavy.chargeTime,
       `and loads longer than anything else (${td.chargeTime} s)`);
    ok(td.pierceShields && td.torpedoUse === 1 && !td.missileUse, 'ignores shields, eats one torpedo, no missiles');
    ok(td.minSector === 2, 'not before sector 2');
    const a1 = sb.weaponAmmo(td), a2 = sb.weaponAmmo(WEAPON_DEFS.missile_basic);
    ok(a1.kind === 'torpedoes' && a1.use === 1 && a2.kind === 'missiles' && !sb.weaponAmmo(WEAPON_DEFS.laser_basic),
       'a tube feeds from torpedoes, a launcher from missiles, a laser from nothing');
    ok(sb.CARGO_ITEMS.torpedo_rack && sb.CARGO_ITEMS.torpedo_rack.kind === 'torpedoes', 'a torpedo rack in the hold');

    /* ── 3. IN A FIGHT: THE TUBE TAKES A TORPEDO, NOT A MISSILE ── */
    {
      const c = makeCombat(sb);
      c.player.cargo.clear();
      c.player.cargo.add('missile_rack', null, 3);
      const tube = new Weapon('torpedo_launcher'); tube.armed = true;
      c.player.weapons = [tube];
      const why = CombatManager.fireRefusal(tube);
      ok(/torpedo/.test(why || ''), `missiles do not feed a torpedo tube (${why})`);
      ok(CombatManager.playerFire(tube, c.enemy.rooms[0]) && c.player.missileCount() === 3,
         'it does not fire, and no missile is touched');
      c.player.cargo.add('torpedo_rack', null, 2);
      ok(CombatManager.fireRefusal(tube) === null, 'with a torpedo in the rack it is ready');
      CombatManager.playerFire(tube, c.enemy.rooms[0]);
      ok(c.player.cargo.countOf('torpedoes') === 1 && c.player.missileCount() === 3,
         `one torpedo out, the missiles untouched (${c.player.cargo.countOf('torpedoes')} / ${c.player.missileCount()})`);
      const ml = new Weapon('missile_basic'); ml.armed = true;
      c.player.weapons = [ml];
      CombatManager.playerFire(ml, c.enemy.rooms[0]);
      ok(c.player.cargo.countOf('torpedoes') === 1 && c.player.missileCount() === 2,
         'and a missile launcher takes a missile, never a torpedo');
      c.player.cargo.takeStack('missiles', 99);
      ml.armed = true;
      ok(/missile/.test(CombatManager.fireRefusal(ml) || ''), 'torpedoes do not feed a missile launcher');
      // the HUD counts them
      c.player.weapons = [tube];
      const texts = [];
      const ft = ctx.fillText;
      ctx.fillText = function (s, ...r) { texts.push(String(s)); return ft.call(this, s, ...r); };
      try { quiet(() => Renderer.drawHUD({ playerShip: c.player })); } finally { ctx.fillText = ft; }
      ok(texts.includes('T1'), 'the resource bar shows the torpedoes aboard');
    }

    /* ── 4. IN THE SHOPS FROM SECTOR 2 ─────────────────────────── */
    {
      let s1 = 0, s1gun = 0, s3 = 0, bm1 = 0;
      for (let seed = 0; seed < 120; seed++) {
        const a = new Station(1, seed);
        s1 += a.stock.torpedoes ?? 0;
        if (a.stock.weapons.some(w => w.key === 'torpedo_launcher')) s1gun++;
        const b = new Station(1, seed, { blackMarket: true });
        if (b.stock.weapons.some(w => w.key === 'torpedo_launcher')) bm1++;
        s3 += new Station(3, seed).stock.torpedoes ?? 0;
      }
      ok(s1 === 0 && s1gun === 0 && bm1 === 0, `sector 1: no torpedoes, no tube, not even the black market (${s1}/${s1gun}/${bm1})`);
      ok(s3 > 30, `sector 3: torpedoes on the shelves (${s3})`);
      let gunSeen = 0;
      for (let seed = 0; seed < 300; seed++) if (new Station(3, seed).stock.weapons.some(w => w.key === 'torpedo_launcher')) gunSeen++;
      ok(gunSeen > 0, `and the tube itself turns up (${gunSeen}/300)`);
      let seed = 0;
      for (; seed < 60; seed++) { const st = new Station(3, seed); if (!st.refusal()) break; }
      const st = new Station(3, seed);
      st.stock.torpedoes = 5;
      const sh = new Ship('frigate', true, 0, 0);
      sh.cargo.clear();
      Save.updateRun({ scrap: 500 });
      const cost = st.torpedoCost(2);
      const r = st.buyTorpedoes(2, Save.getRun(), sh);
      ok(r.ok && sh.cargo.countOf('torpedoes') === 2, `bought two, racked in the hold (${r.message})`);
      ok(Save.getRun().scrap === 500 - cost && st.stock.torpedoes === 3, 'paid for, off the shelf');
      Save.updateRun({ scrap: 0 });
      ok(!st.buyTorpedoes(1, Save.getRun(), sh).ok, 'no CC, no torpedo');
    }

    /* ── 5. ARMOUR: ONE LESS ON EVERY HIT, CREW ONLY WHEN IT GETS THROUGH ─ */
    {
      sb.Math.random = () => 0.99;           // no dodge, no fire, no breach
      const hitWith = (key) => {
        const b = new Ship('bunker_small', false, 850, 120);
        b._allocateDefaultPower();
        sb.makeEnemyCrew(1).forEach(c => b.addCrew(c));
        const sys = b.getSystem('engines');
        const room = b.getRoomById(sys.roomId);
        const man = b.crew[0];
        man.x = room.cx; man.y = room.cy; man.roomId = room.id;
        man.hp = man.maxHp;
        const h0 = b.hull, l0 = sys.damage ?? 0, lv0 = sys.level - (sys.damagedLevels ?? 0);
        const ints0 = sys.integrity ?? null;
        const before = JSON.stringify([sys.damage, sys.damagedLevels, sys.broken, sys.hp]);
        let shown = false;
        const realFT = sb.Particles.floatText;
        sb.Particles.floatText = (x, y, txt) => { if (txt === 'ARMOUR') shown = true; };
        try { b.receiveHit({ def: WEAPON_DEFS[key], x: room.cx, y: room.cy, targetX: room.cx, targetY: room.cy }); }
        finally { sb.Particles.floatText = realFT; }
        const after = JSON.stringify([sys.damage, sys.damagedLevels, sys.broken, sys.hp]);
        return { hull: h0 - b.hull, moduleHit: before !== after, hurt: man.hp < man.maxHp,
                 lost: man.maxHp - man.hp, shown, armor: b.armor };
      };
      const las = hitWith('laser_basic');
      ok(las.armor === 1, 'a bunker wears one point of armour');
      ok(las.hull === 0 && !las.moduleHit && !las.hurt, `a basic laser rings off: no hull, no module, nobody hurt (${JSON.stringify(las)})`);
      ok(las.shown, '"ARMOUR" over the spot');
      const mis = hitWith('missile_basic');
      ok(mis.hull === 1 && mis.moduleHit && mis.hurt && !mis.shown, `a missile gets in with 1 (${JSON.stringify(mis)})`);
      ok(mis.lost <= 35 / 2 + 0.01, `and the crew take half (${mis.lost})`);
      const hl = hitWith('laser_heavy');
      ok(hl.hull === 1 && hl.moduleHit, 'a heavy laser: 1');
      const tp = hitWith('torpedo_launcher');
      ok(tp.hull === 2 && tp.moduleHit && tp.hurt, `a torpedo: 2 through the plate (${tp.hull})`);
      // a ship with no armour takes the lot
      const f = new Ship('enemy_frigate', false, 850, 120);
      ok(f.armor === 0, 'nothing that flies wears armour');
      const fs = f.getSystem('engines'), fr = f.getRoomById(fs.roomId);
      const shb = f.getSystem('shields'); if (shb) f.systems = f.systems.filter(x => x !== shb);
      const fh = f.hull;
      f.receiveHit({ def: WEAPON_DEFS.laser_basic, x: fr.cx, y: fr.cy, targetX: fr.cx, targetY: fr.cy });
      ok(fh - f.hull === 1, 'a frigate takes the laser\'s 1 in full');
      sb.Math.random = realR;
    }

    /* ── 6. NO SHIELDS, NO DODGING: A BUNKER SITS, A MECH CRAWLS ── */
    {
      for (const key of ['bunker_small', 'enemy_mech', 'boss_station']) {
        const s = new Ship(key, false, 850, 120);
        ok(!s.getSystem('shields') && s.layout.grounded && s.armor >= 1, `${key}: grounded, armoured, no shields`);
        ok(!!s.getSystem('engines'), `${key}: engines all the same — they hold the gravity`);
      }
      const bun = new Ship('bunker_small', false, 850, 120);
      sb.makeEnemyCrew(5).forEach(c => bun.addCrew(c)); bun.assignStations();
      bun._allocateDefaultPower(); bun.update(0.05);
      ok(bun.evasion === 0, `a bunker never dodges (${bun.evasion})`);
      bun.layout = { ...bun.layout, immobile: false };
      ok(bun.evasion > 0, `though the same crew on a hull that moves would (${bun.evasion})`);
      bun.layout = { ...bun.layout, immobile: true };
      ok(bun.getSystem('engines').level === 2, 'small bunker: engines on 2');
      const boss = new Ship('boss_station', false, 850, 120);
      ok(boss.getSystem('engines').level === 3 && boss.layout.immobile, 'the big bunker: engines on 3, it stands');
      // mech: half of what the same crew would make of a ship
      const mech = new Ship('enemy_mech', false, 850, 120);
      sb.makeEnemyCrew(3).forEach(c => mech.addCrew(c)); mech.assignStations();
      mech._allocateDefaultPower(); mech.update(0.05);
      const ev = mech.evasion;
      mech.layout = { ...mech.layout, slow: false };
      const full = mech.evasion;
      ok(full > 0 && Math.abs(ev - full * 0.5) < 1e-9, `a mech dodges half as well (${ev} vs ${full})`);
      ok(new Ship('enemy_mech', false, 0, 0).layout.tracks, 'and it runs on tracks');
    }

    /* ── 7. NOTHING ON THE GROUND RUNS AWAY ─────────────────────── */
    {
      const step = (s) => { for (let i = 0; i < s * 20; i++) CombatManager.update(0.05); };
      const c = makeCombat(sb);
      const bun = new Ship('bunker_small', false, 850, 120);
      bun._allocateDefaultPower();
      sb.makeEnemyCrew(3).forEach(x => bun.addCrew(x)); bun.assignStations();
      bun.weapons = [];
      T.enemyShip = bun;
      CombatManager.begin(c.player, bun, 'normal');
      for (let i = 0; i < 60 && !CombatManager.isActive(); i++) CombatManager.update(0.05);
      step(90);
      ok(!CombatManager.enemyEscapeActive, 'ninety quiet seconds and the bunker is still there');
      bun.hull = 2;
      step(2);
      ok(!CombatManager._escapeRolled && !CombatManager.enemyEscapeActive, 'shot to pieces, it does not try to jump');
      // the same hull damage on a ship: she rolls
      const d = makeCombat(sb);
      d.enemy.hull = 2;
      CombatManager.update(0.05);
      ok(CombatManager._escapeRolled, 'a ship at the same hull does roll to run');
    }

    /* ── 8. THE SPAWN: FROM SECTOR 2, RARER THAN SHIPS ─────────── */
    {
      makeCombat(sb);
      const count = (sector, diff = 'normal') => {
        Save.updateRun({ sector });
        const seen = { bunker_small: 0, enemy_mech: 0, ship: 0, bad: 0 };
        for (let i = 0; i < 400; i++) {
          quiet(() => T._spawnEnemy(diff));
          const e = T.enemyShip;
          if (seen[e.layoutKey] !== undefined) {
            seen[e.layoutKey]++;
            if (e.getSystem('shields') || e.getSystem('cloaking')) seen.bad++;
            const base = sector === 1 ? 12 : 18 + (sector - 2) * 5;
            if (e.hullMax !== base + 4) seen.bad++;
          } else seen.ship++;
        }
        return seen;
      };
      const s1 = count(1);
      ok(s1.bunker_small === 0 && s1.enemy_mech === 0, `sector 1: no bunker, no mech (${JSON.stringify(s1)})`);
      const s3 = count(3);
      ok(s3.bunker_small > 10 && s3.enemy_mech > 10, `sector 3: both turn up (${JSON.stringify(s3)})`);
      ok(s3.bunker_small + s3.enemy_mech < s3.ship / 2, 'and far rarer than ships');
      ok(s3.bad === 0, 'never a shield, never a cloak, and four more points of hull');
      const hard = count(3, 'hard');
      ok(hard.bunker_small === 0 && hard.enemy_mech === 0, 'an elite is always a ship');
      Save.updateRun({ sector: 1 });
    }

    /* ── 9. THE BOSS OF THE THIRD CONTRACT IS THE BIG BUNKER ────── */
    {
      BossManager.reset('station');
      const b = quiet(() => BossManager.start(0, 850, 120, 'station'));
      ok(b.layout.grounded && b.layout.immobile && b.armor === 1, 'Apophis stands on the ground in armour');
      ok(!b.getSystem('shields') && b.shieldBars === 0, 'and has no shields');
      b.update(0.05);
      ok(b.evasion === 0, 'and does not dodge');
      BossManager.reset();
    }

    /* ── 10. DRAWN: TRACKS, A STEEL RIM, THE ARMOUR PILL ────────── */
    {
      const mech = new Ship('enemy_mech', false, 850, 120);
      mech._allocateDefaultPower();
      let tracks = 0;
      const real = mech._drawTracks;
      mech._drawTracks = function (...a) { tracks++; return real.apply(this, a); };
      quiet(() => mech.draw(ctx));
      ok(tracks === 1, 'a mech is drawn on its tracks');
      const ship = new Ship('enemy_frigate', false, 850, 120);
      let t2 = 0; ship._drawTracks = () => { t2++; };
      quiet(() => ship.draw(ctx));
      ok(t2 === 0, 'a ship is not');
      const player = new Ship('frigate', true, 80, 120);
      const pills = (enemy) => {
        const texts = [];
        const ft = ctx.fillText;
        ctx.fillText = function (s, ...r) { texts.push(String(s)); return ft.call(this, s, ...r); };
        try { quiet(() => Renderer.drawHUD({ playerShip: player, enemyShip: enemy })); } finally { ctx.fillText = ft; }
        return texts;
      };
      ok(pills(mech).some(s => s === 'ARMOUR'), 'the enemy panel shows ARMOUR on a mech');
      ok(!pills(ship).some(s => s === 'ARMOUR'), 'and not on a ship');
    }
  } finally {
    sb.Math.random = realR;
    UI.notify = realNotify;
  }
})();

// ============================================================
section('282. Eight hulls drawn by the player (95): the yard sells three, five fly against you, a bare lift side is plating, a torpedo in the enemy\'s second bay');
// ============================================================
(function testUpdate95() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, UI, SHIP_LAYOUTS, SHIP_CATALOG, HULL_GRID: G } = sb;
  const T = sb.Game.__test;
  Save.load(); Save.startRun();
  const realNotify = UI.notify;
  UI.notify = () => {};
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  try {
    /* ── 1. THE DRAWINGS, MODULE FOR MODULE ─────────────────────
       Each picture read left to right, top deck first: '#' a module,
       '|' the lift, '.' open space. Five columns: two, the lift, two. */
    const PLANS = {
      enemy_ra:       ['.#|##', '.#|..', '.#|##'],
      thoth:          ['.#|##', '##|..', '.#|##'],
      osiris:         ['##|##', '##|..', '##|##'],
      enemy_nephthys: ['##|##', '..|..', '##|##'],
      isis:           ['##|##', '.#|#.', '##|##'],
      enemy_khnum:    ['..|##', '.#|#.', '##|..'],
      enemy_hathor:   ['##|##', '##|..'],
      enemy_montu:    ['.#|##', '##|#.'],
    };
    Object.entries(PLANS).forEach(([k, plan]) => {
      const L = SHIP_LAYOUTS[k];
      ok(!!L, `${k} exists`);
      if (!L) return;
      ok(L.floors === plan.length, `${k}: ${plan.length} decks`);
      ok(JSON.stringify(L.shaftAfter) === '[1]' && L.elevators.length === 1,
         `${k}: one lift, after the second column`);
      plan.forEach((line, i) => {
        const row = plan.length - 1 - i;
        const cols = line.replace('|', '').split('').map((ch, c) => ch === '#' ? c : -1).filter(c => c >= 0);
        const got = L.grid.filter(g => g.row === row).map(g => g.col).sort();
        ok(JSON.stringify(got) === JSON.stringify(cols),
           `${k}: deck ${row} is ${line} (${got.join(',')})`);
      });
    });

    /* ── 2. WHO FLIES WHAT ───────────────────────────────────── */
    ['thoth', 'isis', 'osiris'].forEach(k => {
      ok(SHIP_CATALOG[k] && SHIP_CATALOG[k].cost > 0, `${k} is for sale`);
      ok(SHIP_LAYOUTS[k].spriteKey === 'ship_player', `${k} is a player hull`);
    });
    ok(SHIP_CATALOG.thoth.cost < SHIP_CATALOG.isis.cost && SHIP_CATALOG.isis.cost < SHIP_CATALOG.osiris.cost,
       'the bigger the hull, the dearer');

    /* THE YARD HULLS ARE NOT FITTED OUT (jj, 03.10): the five basics,
       ONE extra module (a different one on each), the rest bare; the
       dearest carries a second gun bay and two guns; different guns. */
    {
      const BASIC = ['engines', 'piloting', 'oxygen', 'reactor', 'weapons'];
      const extras = {}, guns = {};
      ['thoth', 'isis', 'osiris'].forEach(k => {
        const sh = new Ship(k, true, 80, 120);
        const types = sh.systems.map(x => x.type);
        BASIC.forEach(t => ok(types.includes(t), `${k}: has the basic ${t}`));
        const left = types.slice();
        BASIC.forEach(t => left.splice(left.indexOf(t), 1));
        ok(left.length === 1, `${k}: exactly one extra module (${left.join(',')})`);
        extras[k] = left[0];
        ok(sh.rooms.filter(r => r.type === 'empty').length >= 2, `${k}: bays left bare to fill`);
        guns[k] = sh.weapons.filter(Boolean).map(w => w.defKey);
        ok(guns[k].every(g => (sb.WEAPON_DEFS[g]?.hull_damage ?? 0) > 0),
           `${k}: every starting gun can hurt a hull (${guns[k].join(',')})`);
        // the reactor runs everything aboard at full
        const need = sh.systems.filter(x => x.type !== 'reactor')
          .reduce((a, x) => a + (x.type === 'shields' ? x.level : x.level), 0);
        ok(sh.reactor.level >= need, `${k}: the reactor runs it all (${sh.reactor.level} >= ${need})`);
        sh.weapons.forEach((w, i) => {
          if (!w) return;
          const ws = sh.weaponSystemFor(i);
          ok(ws && ws.level >= w.powerCost, `${k}: gun ${w.defKey} has a bay strong enough`);
        });
      });
      ok(new Set(Object.values(extras)).size === 3, `a different extra on each (${JSON.stringify(extras)})`);
      ok(extras.osiris === 'weapons' && guns.osiris.length === 2,
         'Osiris: the extra is a second gun bay, and it carries two guns');
      ok(guns.thoth.length === 1 && guns.isis.length === 1, 'the cheaper two carry one gun each');
      ok(guns.thoth[0] !== guns.isis[0], 'and not the same one');
      ok(!['thoth', 'isis'].some(k => guns[k][0] === 'laser_basic'), 'none of them the free starter laser');
      const cells = k => SHIP_LAYOUTS[k].cargoCols * SHIP_LAYOUTS[k].cargoRows;
      ok(cells('thoth') < cells('frigate') && cells('osiris') < cells('isis') && cells('isis') <= cells('hauler'),
         `the holds: Thoth smallest, Isis the trader, Osiris a warship (${cells('thoth')}/${cells('isis')}/${cells('osiris')})`);
    }
    const ENEMIES = ['enemy_ra', 'enemy_nephthys', 'enemy_khnum', 'enemy_hathor', 'enemy_montu'];
    ENEMIES.forEach(k => {
      ok(!SHIP_CATALOG[k], `${k} is not in the yard`);
      ok(!SHIP_LAYOUTS[k].grid.some(g => g.type === 'empty'),
         `${k}: no spare bay (a spare bay would fill with prisoners)`);
      const types = SHIP_LAYOUTS[k].grid.map(g => g.type);
      ['engines', 'weapons', 'shields', 'piloting', 'oxygen', 'reactor'].forEach(t =>
        ok(types.includes(t), `${k}: has ${t}`));
    });
    ok(SHIP_LAYOUTS.enemy_nephthys.grid.filter(g => g.type === 'weapons').length === 2,
       'Nephthys carries two guns');

    /* ── 3. A BARE LIFT SIDE IS PLATING, NOT A HATCH ───────────── */
    Object.keys(SHIP_LAYOUTS).forEach(k => {
      const s = new Ship(k, k in SHIP_CATALOG, 80, 120);
      const air = s.doors.filter(d => d.isAirlock);
      ok(air.length >= 1, `${k}: has an airlock`);
      const onShaft = air.filter(d => s.elevators.shafts.some(sh =>
        Math.abs(d.x - (sh.x - sh.width / 2)) < 26 || Math.abs(d.x - (sh.x + sh.width / 2)) < 26));
      ok(onShaft.length === 0, `${k}: no airlock against a lift (${onShaft.length})`);
      // every airlock is on the outer wall of its own room
      air.forEach(d => {
        const r = s.getRoomById(d.roomA);
        ok(r && (Math.abs(d.x - r.x) < 1 || Math.abs(d.x - (r.x + r.w)) < 1),
           `${k}: airlock ${d.roomA} is on its room's wall`);
      });
    });
    {
      // Khnum's top deck: the lift on the left with nothing past it
      const s = new Ship('enemy_khnum', false, 80, 120);
      const top = s.rooms.filter(r => r.floor === 2).sort((a, b) => a.x - b.x);
      const sh = s.elevators.shafts[0];
      ok(Math.abs(top[0].x - (sh.x + sh.width / 2)) < 3, 'premise: Khnum\'s top deck starts at the lift');
      const lock = s.doors.filter(d => d.isAirlock && top.some(r => r.id === d.roomA));
      ok(lock.length === 1 && Math.abs(lock[0].x - (top[1].x + top[1].w)) < 3,
         'so its one airlock is on the far wall');
      ok(s.doors.some(d => !d.isAirlock && d.roomA === top[0].id && d.roomB === `shaft_${sh.id}`),
         'and the lift door is still there');
    }

    /* ── 4. NEPHTHYS: THE CABIN RIDES THROUGH A DECK WITH NOTHING ON IT */
    {
      const L = SHIP_LAYOUTS.enemy_nephthys;
      ok(L.elevators[0].floors.length === 2, 'two stops, not three');
      ok(!L.rooms.some(r => r.floor === 1), 'the middle deck has no module');
      const s = new Ship('enemy_nephthys', false, 80, 120);
      const sh = s.elevators.shafts[0];
      ok(sh.floorYs.length === 2, 'the built lift has two stops too');
    }

    /* ── 5. EVERY MODULE CAN BE WALKED TO ──────────────────────── */
    Object.keys(PLANS).forEach(k => {
      const s = new Ship(k, k in SHIP_CATALOG, 80, 120);
      s._allocateDefaultPower();
      const c = new CrewMember({ name: 'Walker' });
      s.addCrew(c);
      const first = s.rooms[0];
      c.x = first.cx; c.y = s.floorWalkY(first.floor, first.cy);
      c.roomId = first.id; c.homeRoomId = first.id;
      const missed = [];
      s.rooms.slice(1).forEach(room => {
        /* His home goes with him: an idle hand of OURS walks back to his
           home room, which is the game working, not the hull failing. */
        c.homeRoomId = room.id;
        c.moveToOnShip(s, ...s.stationSlot(room, 0));
        let i = 0;
        for (; i < 1500 && c.roomId !== room.id; i++) s.update(0.05);
        if (c.roomId !== room.id) missed.push(room.id);
      });
      ok(missed.length === 0, `${k}: a hand walks to every module (${missed.join(',') || 'all'})`);
    });

    /* ── 6. THE ENEMY DRAW ─────────────────────────────────────── */
    makeCombat(sb);
    const draw = (sector, diff = 'normal', n = 500) => {
      Save.updateRun({ sector });
      const seen = {}; let torp = 0, torpFirst = 0, twoBay = 0;
      for (let i = 0; i < n; i++) {
        quiet(() => T._spawnEnemy(diff));
        const e = T.enemyShip;
        seen[e.layoutKey] = (seen[e.layoutKey] ?? 0) + 1;
        if (e.weaponRooms.length >= 2) twoBay++;
        if (e.weapons[0]?.defKey === 'torpedo_launcher') torpFirst++;
        if (e.weapons.some((w, i2) => i2 >= 1 && w?.defKey === 'torpedo_launcher')) torp++;
      }
      return { seen, torp, torpFirst, twoBay };
    };
    const d1 = draw(1);
    ['enemy_ra', 'enemy_khnum', 'enemy_hathor', 'enemy_montu'].forEach(k =>
      ok((d1.seen[k] ?? 0) > 20, `sector 1: ${k} turns up (${d1.seen[k] ?? 0})`));
    ok(!d1.seen.enemy_nephthys, 'sector 1: no two-gun Nephthys in the ordinary draw');
    ok(d1.torp === 0 && d1.torpFirst === 0, `sector 1: no torpedo tube on an enemy (${d1.torp})`);
    const d3 = draw(3);
    ok((d3.seen.enemy_nephthys ?? 0) > 15, `sector 3: Nephthys turns up (${d3.seen.enemy_nephthys ?? 0})`);
    ok(d3.torp > 0, `sector 3: some enemies carry a torpedo tube (${d3.torp})`);
    ok(d3.torpFirst === 0, 'and never as the first gun');
    ok(d3.torp < d3.twoBay * 0.5, `only sometimes (${d3.torp} of ${d3.twoBay} two-bay hulls)`);
    const hard = draw(1, 'hard', 300);
    ok((hard.seen.enemy_nephthys ?? 0) > 20, `an elite can fly Nephthys from the start (${hard.seen.enemy_nephthys ?? 0})`);
    Save.updateRun({ sector: 1 });

    /* ── 7. AN ENEMY TORPEDO HITS LIKE OURS ───────────────────── */
    {
      Save.updateRun({ sector: 3 });
      const realR = sb.Math.random;
      sb.Math.random = () => 0.01;   // every roll the low way: tube in the second bay
      try { quiet(() => T._spawnEnemy('normal')); } finally { sb.Math.random = realR; }
      const e = T.enemyShip;
      const tube = e.weapons.find(w => w?.defKey === 'torpedo_launcher');
      ok(!!tube, 'premise: the low roll fits a tube');
      if (tube) {
        const i = e.weapons.indexOf(tube);
        const sys = e.weaponSystemFor(i);
        ok(sys && sys.level === tube.powerCost, 'its bay is levelled to the tube\'s power');
        e._allocateDefaultPower();
        ok(sys && sys.power >= tube.powerCost, `and the reactor feeds it (${sys?.power}/${tube.powerCost})`);
        ok(e.weapons[0] && e.weapons[0].defKey !== 'torpedo_launcher', 'the first gun is still a gun');
      }
      Save.updateRun({ sector: 1 });
    }

    /* ── 8. FOUR OF THEM DRIFT AS WRECKS TOO ──────────────────── */
    ['enemy_ra', 'enemy_khnum', 'enemy_hathor', 'enemy_montu'].forEach(k => {
      ok(sb.DERELICT_LAYOUTS.includes(k), `${k} can be a wreck`);
      const w = quiet(() => sb.makeDerelict(2, 850, 120, k));
      ok(w && w.isDerelict && w.layoutKey === k, `${k}: a derelict builds`);
    });

    /* ── 9. THE HANGAR SHOWS THEM ─────────────────────────────── */
    ok(sb.Base.catalog().length === 6, `six hulls in the yard (${sb.Base.catalog().length})`);
  } finally {
    UI.notify = realNotify;
  }
})();

// ============================================================
section('283. Twenty-five rank insignia instead of one star, and an icon for every specialisation (96, jj\'s point 14)');
// ============================================================
(function testUpdate96() {
  const sb = loadEngine();
  const { Renderer, Ship, CrewMember, Save, Base, BaseScreen, SKILL_DEFS, MAX_SKILL_LEVEL } = sb;
  Save.load(); Save.startRun();
  const ctx = initRenderer(sb);

  /* Record what one insignia paints: every op, its numbers and the
     colour it is painted in — the picture, as data. */
  const paint = (fn) => {
    const ops = [];
    const keep = {};
    const rec = (name) => function (...a) { ops.push(name + ':' + a.map(v => typeof v === 'number' ? v.toFixed(2) : v).join(',') + '@' + ctx.fillStyle); };
    ['fillRect', 'strokeRect', 'arc', 'moveTo', 'lineTo'].forEach(n => { keep[n] = ctx[n]; ctx[n] = rec(n); });
    try { fn(); } finally { Object.entries(keep).forEach(([n, f]) => { ctx[n] = f; }); }
    return ops;
  };

  /* ── 1. ONE MARK PER RANK, ALL DIFFERENT ──────────────────── */
  ok(Renderer.RANK_INSIGNIA.length === 25 && sb.RANKS.length === 25, 'twenty-five ranks, twenty-five insignia');
  const pics = [];
  for (let l = 0; l < 25; l++) {
    const ops = paint(() => Renderer.drawRankInsignia(ctx, l, 0, 0, 20));
    ok(ops.length > 0, `rank ${l} (${sb.rankName(l)}) draws something`);
    pics.push(ops.join('|'));
  }
  ok(new Set(pics).size === 25, `no two ranks look the same (${new Set(pics).size} different pictures)`);
  ok(Renderer.drawRankInsignia(ctx, 6, 0, 0, 12) === 24, 'it is twice as wide as tall, and says how wide');
  ok(paint(() => Renderer.drawRankInsignia(ctx, 99, 0, 0, 20)).join('|') === pics[24]
     && paint(() => Renderer.drawRankInsignia(ctx, -3, 0, 0, 20)).join('|') === pics[0],
     'past either end it wears the end of the ladder');

  /* ── 2. SILVER DOTS, GOLD STARS (update125, jj) ───────────── */
  const T = (l) => Renderer.insigniaTier(l).key;
  ok(T(0) === 'silver' && T(16) === 'silver', 'Recruit to Lieutenant Colonel wear silver');
  ok(T(17) === 'gold' && T(24) === 'gold', 'from the Colonel up, gold');
  ok(Renderer.INSIGNIA_TIERS.length === 2 && Renderer.INSIGNIA_TIERS[0].col !== Renderer.INSIGNIA_TIERS[1].col, 'two colours');

  /* ── 3. COUNT THE MARKS, COUNT THE BARS ───────────────────── */
  const count = (l, op) => Renderer.RANK_INSIGNIA[l].filter(o => o[0] === op).length;
  ok([1, 2, 3, 4].map(l => count(l, 'circle')).join() === '1,2,3,4' && [1, 2, 3, 4].every(l => count(l, 'rect') === 0),
     'one to four dots, no bar: ranks 1 to 4');
  ok([5, 6, 7, 8].map(l => count(l, 'circle')).join() === '1,2,3,4' && [5, 6, 7, 8].every(l => count(l, 'rect') === 1),
     'a bar and one to four dots over it: 5 to 8');
  ok([9, 13].map(l => count(l, 'rect')).join() === '2,3' && count(16, 'rect') === 3 && count(16, 'circle') === 4,
     'two bars from 9, three from 13 — and no more than three');
  ok([17, 18, 19, 20].map(l => count(l, 'poly')).join() === '1,2,3,4' && [17, 20].every(l => count(l, 'rect') === 0 && count(l, 'circle') === 0),
     'then stars instead of dots, the same scheme: one to four stars');
  ok([21, 24].map(l => count(l, 'poly')).join() === '1,4' && [21, 24].every(l => count(l, 'rect') === 1),
     'and a bar under one to four stars at the top');
  const P = Renderer.insigniaParts;
  ok(P(0) === null && JSON.stringify(P(11)) === JSON.stringify({ marks: 3, bars: 2, star: false })
     && JSON.stringify(P(22)) === JSON.stringify({ marks: 2, bars: 1, star: true }), 'insigniaParts says how a rank is built');
  {
    const ops = Renderer.RANK_INSIGNIA[16];
    const barTop = Math.min(...ops.filter(o => o[0] === 'rect').map(o => o[2]));
    ok(ops.filter(o => o[0] === 'circle').every(o => o[2] + o[3] <= barTop), 'the dots sit over the bars, never on them');
    ok(ops.every(o => o[0] !== 'rect' || o[2] + o[4] <= 10), 'and everything stays in the 20x10 box');
  }

  /* ── 4. EIGHT SKILLS, EIGHT PICTURES ──────────────────────── */
  const keys = Object.keys(SKILL_DEFS);
  ok(keys.every(k => Renderer.STAT_ICONS[Renderer.SKILL_ICON[k]]), 'every skill has an icon in the one icon set');
  ok(new Set(keys.map(k => Renderer.SKILL_ICON[k])).size === keys.length, 'and no two skills share one');
  ok(JSON.stringify(Renderer.STAT_ICONS.sk_pilot) !== JSON.stringify(Renderer.STAT_ICONS.sk_engine),
     'piloting and engines — the pair a player confuses — are different pictures');

  /* ── 5. A SPECIALISATION IS A SKILL AT 3/3, AND NOTHING LESS ── */
  const vet = new CrewMember({ name: 'Ares' });
  vet.skills.repair.level  = MAX_SKILL_LEVEL;
  vet.skills.weapons.level = MAX_SKILL_LEVEL;
  vet.skills.engines.level = MAX_SKILL_LEVEL - 1;
  const spec = Renderer.specialtiesOf(vet.serialise()).slice().sort();
  ok(JSON.stringify(spec) === '["repair","weapons"]', `two at 3/3, one at 2/3 does not count (${spec})`);
  {
    const ops = paint(() => Renderer.drawSpecialties(ctx, vet.serialise(), 0, 0, 10));
    ok(ops.some(o => o.endsWith('@' + SKILL_DEFS.repair.color)) && ops.some(o => o.endsWith('@' + SKILL_DEFS.weapons.color)),
       'each icon in its own skill\'s colour');
    ok(!ops.some(o => o.endsWith('@' + SKILL_DEFS.engines.color)), 'and none for the skill at 2/3');
    // Handed a LIST of skills (as the mess card does) it draws exactly those.
    const listOps = paint(() => Renderer.drawSpecialties(ctx, ['repair', 'weapons'], 0, 0, 10));
    ok(listOps.some(o => o.endsWith('@' + SKILL_DEFS.repair.color)) && listOps.some(o => o.endsWith('@' + SKILL_DEFS.weapons.color)),
       'given a list of skills it draws those skills');
    ok(Renderer.drawSpecialties(ctx, ['repair', 'weapons'], 0, 0, 10) === 23, 'and says how wide (two icons and a gap)');
    ok(Renderer.drawSpecialties(ctx, new CrewMember({ name: 'Nil' }).serialise(), 0, 0, 10) === 0,
       'a man with none takes no room');
  }
  ok(/^Senior Corporal \(8\)|^Staff Sergeant \(8\)/.test(Renderer.rankTip(vet)) && /specialist: (Repair, Weapons|Weapons, Repair)/.test(Renderer.rankTip(vet)),
     `the tip names the rank and the specialisations (${Renderer.rankTip(vet)})`);
  ok(/no specialisation/.test(Renderer.rankTip(new CrewMember({ name: 'Nil' }))), 'and says so when there are none');

  /* ── 6. THE ROSTER IN A FIGHT: AN INSIGNIA, NO STAR, A TIP ──── */
  {
    const ship = new Ship('hauler', true, 0, 0);
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    ship.crew[0].skills.repair.level = MAX_SKILL_LEVEL;
    ship.crew[0].skills.weapons.level = MAX_SKILL_LEVEL;
    ship.assignStations();
    let hudOps = [];
    const seen = captureText(ctx, () => { hudOps = paint(() => Renderer.drawHUD({ playerShip: ship })); });
    ok(!seen.some(o => o.t === '★'), 'no star in the fight roster');
    const own = paint(() => Renderer.drawRankInsignia(ctx, ship.crew[0].rankLevel(), 0, 0, 9)).join('|');
    ok(hudOps.join('|').includes(own), 'the specialist\'s row is painted with his own insignia');
    const zones = Renderer.getRankZones();
    ok(zones.length === ship.crew.length, `an insignia on every row (${zones.length}/${ship.crew.length})`);
    ok(zones.every(z => z.x + z.w <= Renderer.crewPanelX()), 'and inside the roster column');
    const z0 = zones.find(z => z.crew === ship.crew[0]);
    ok(z0 && /specialist: /.test(z0.tip), 'the specialist\'s tip names what he is good at');
    ok(!Renderer.getCrewMarkZones().some(z => z.crew), 'and it is not one of the condition marks');
    /* Point at it: NO second box any more (update97, jj — it covered the
       crew panel). His rank is in that panel; section 284 checks it. */
    sb.Input.mouse.x = z0.x + 2; sb.Input.mouse.y = z0.y + 2;
    const hover = captureText(ctx, () => Renderer.drawHUD({ playerShip: ship })).map(o => o.t);
    ok(!hover.includes(z0.tip), `pointing at it opens no tooltip over the crew panel (update97)`);
    sb.Input.mouse.x = -100; sb.Input.mouse.y = -100;
    // The old side panel in ui.js (unused today, but exported): no star there either.
    const lvl0 = ship.crew[0].rankLevel();
    const want = paint(() => Renderer.drawRankInsignia(ctx, lvl0, 0, 0, 10)).join('|');
    let panelOps = [], panelText = [];
    panelText = captureText(ctx, () => { panelOps = paint(() => sb.UI.drawCrewPanel(ctx, ship, 1280, 720)); }).map(o => o.t);
    ok(!panelText.includes('★'), 'the ui.js crew panel has no star');
    ok(panelOps.join('|').includes(want), 'and draws his insignia instead');
  }

  /* ── 7. THE MESS CARD AND THE DOSSIER ──────────────────────── */
  {
    const b = Base.get();
    b.commanders = []; b.barracks = []; b.messLvl = 1; b.barracksLvl = 9;
    Base.earn(20000);
    Base.addCrew(vet.serialise());
    const real = Renderer.drawSpecialties, realIns = Renderer.drawRankInsignia;
    const got = [], ins = [];
    Renderer.drawSpecialties = function (c2, rec) { got.push(Array.isArray(rec) ? rec : Renderer.specialtiesOf(rec)); return real.apply(this, arguments); };
    Renderer.drawRankInsignia = function (c2, lvl) { ins.push(lvl); return realIns.apply(this, arguments); };
    try {
      BaseScreen.open(); BaseScreen._set({ tab: 'MESS' }); BaseScreen.draw(ctx);
    } finally { Renderer.drawSpecialties = real; Renderer.drawRankInsignia = realIns; }
    ok(got.some(k => k.includes('repair') && k.includes('weapons')), 'the mess card draws his specialisation icons');
    ok(ins.includes(sb.rankLevelOf(vet.serialise())), 'and his insignia');
    const dossierCap = Object.assign(vet.serialise(), { level: 13, karma: 50, specialties: ['repair', 'weapons'] });
    const ops = paint(() => Renderer.drawCommanderDossier(ctx, dossierCap));
    const lt = paint(() => Renderer.drawRankInsignia(ctx, 13, 0, 0, 12)).join('|');
    ok(ops.join('|').includes(lt), 'the dossier wears his insignia (Lieutenant, 13)');
    const rp = paint(() => Renderer.drawSpecialties(ctx, ['repair'], 0, 0, 10)).join('|');
    ok(ops.join('|').includes(rp), 'and an icon beside each specialisation');
    const words = captureText(ctx, () => Renderer.drawCommanderDossier(ctx, dossierCap)).map(o => o.t);
    ok(words.includes('Repair') && words.includes('Weapons'), 'the dossier lists both specialisations by name');
    ok(words.includes('Lieutenant'), 'and the rank in words beside the insignia');
  }

  /* ── 8. THE STAR IS GONE EVERYWHERE ───────────────────────── */
  ok(typeof new CrewMember({ name: 'X' }).getStarRating === 'undefined', 'a crewman has no star rating any more');
  ok(typeof sb.starForRank === 'undefined', 'and there is no star ladder');
})();

// ============================================================
section('284. Fixes from play (97): their reactor reads like ours, °C, slower repairs, a glow on the hull, blue fire, the bubble we brought, enemies at action stations, posts stay manned, the wounded heal, guns in the crates, fewer medkits, HEAL, rank in the crew panel, a scrolling roster');
// ============================================================
(function testUpdate97() {
  const sb = loadEngine();
  const { Ship, CrewMember, Save, UI, Renderer, CombatManager, Input, Game, TASK } = sb;
  const T = Game.__test;
  Save.load(); Save.startRun();
  const realNotify = UI.notify;
  UI.notify = () => {};
  const quiet = (fn) => {
    const log = console.log, warn = console.warn;
    console.log = console.warn = () => {};
    try { return fn(); } finally { console.log = log; console.warn = warn; }
  };
  const ctx = initRenderer(sb);
  /* What a draw paints, rectangle by rectangle, with the colour it used. */
  const rects = (fn) => {
    const out = [], real = ctx.fillRect;
    ctx.fillRect = function (x, y, w, h) { out.push({ x, y, w, h, fill: ctx.fillStyle }); };
    try { fn(); } finally { ctx.fillRect = real; }
    return out;
  };
  try {
    /* ── 1. THEIR REACTOR: NEBULA IN VIOLET, A HEAT BAR, DEGREES ── */
    {
      const me  = new Ship('frigate', true, 80, 120);
      const foe = new Ship('enemy_frigate', false, 850, 120);
      foe.reactor.penalty = 2;
      foe.reactorHeat = 50;
      const r = rects(() => quiet(() => Renderer.drawHUD({ playerShip: me, enemyShip: foe })));
      const pipW = 12;
      const violet = r.filter(o => o.fill === '#8a3fbf' && o.w === pipW).length;
      ok(violet === 2, `the nebula's two units are violet on THEIR reactor (${violet})`);
      const bar = Renderer.enemyHeatBar();
      ok(!!bar && bar.heat === 50, 'and their core has a heat bar beside it');
      // update130: the bar lies under their row and fills from the left
      ok(!!bar && Math.abs(bar.filled - bar.w / 2) < 0.5 &&
         r.some(o => o.x === bar.x && o.y === bar.y && Math.abs(o.w - bar.w / 2) < 0.5 && o.h === bar.h),
         'filled halfway for 50');
      const t = captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: me, enemyShip: foe }))).map(o => o.t);
      ok(t.includes('650°C'), `their temperature in degrees (${t.filter(x => /°C$/.test(x))})`);
      ok(t.some(x => /^NEB −2$/.test(x)), 'and the nebula\'s share is named under it');
      foe.reactor.penalty = 0;
      const r0 = rects(() => quiet(() => Renderer.drawHUD({ playerShip: me, enemyShip: foe })));
      ok(!r0.some(o => o.fill === '#8a3fbf' && o.w === pipW), 'no nebula, no violet');
    }

    /* ── 2. 1300 °C ───────────────────────────────────────────── */
    ok(sb.heatCelsius(100) === 1300 && sb.heatCelsius(0) === 0 && sb.heatCelsius(90) === 1170,
       'heat 0–100 reads 0–1300 °C');
    ok(sb.REACTOR_HEAT_CONFIG.criticalHeat === 90, 'and every threshold stays in the old units');

    /* ── 3. A LITTLE SLOWER TO REPAIR ─────────────────────────── */
    {
      ok(sb.SYSTEM_REPAIR_RATE === 0.10, 'one unskilled hand fills 0.10 of a level a second');
      const sh = new Ship('frigate', true, 80, 120);
      const sys = sh.getSystem('engines');
      sys.damageLevel(1);
      let t = 0;
      while (sys.damagedLevels > 0 && t < 30) { sys.repair(0.05, null); t += 0.05; }
      ok(t > 9.8 && t < 10.2, `a level takes ten seconds, not eight (${t.toFixed(2)} s)`);
    }

    /* ── 4. THE LOW-HULL GLOW IS ON THE HULL, NOT ITS BOX ───────── */
    {
      const foe = new Ship('enemy_khnum', false, 850, 120);
      foe.hull = 2; foe.hullMax = 20;
      const r = rects(() => quiet(() => foe.draw(ctx)));
      ok(!r.some(o => /^rgba\(255,45,68/.test(String(o.fill))), 'no red rectangle over the bounding box');
      let glow = false;
      const realFill = ctx.fill;
      ctx.fill = function () { if (/^rgba\(255,45,68/.test(String(ctx.fillStyle))) glow = true; return realFill.apply(this, arguments); };
      try { quiet(() => foe.draw(ctx)); } finally { ctx.fill = realFill; }
      ok(glow, 'the glow is filled along the hull plate instead');
    }

    /* ── 5. A FIRE SHORT OF AIR BURNS BLUE ─────────────────────── */
    {
      const sh = new Ship('frigate', true, 80, 120);
      const room = sh.rooms[0];
      const f = sh.fires.start(room.id, room.cx, room.cy);
      const ro = sh.oxygen.getRoom(room.id);
      ro.level = 0.9; sh.fires.update(0.05, sh);
      ok(f.starved === false, 'in good air it burns orange');
      ro.level = 0.25; sh.fires.update(0.05, sh);
      ok(f.starved === true, 'short of air it burns blue');
      let blue = 0;
      const realEmit = sb.Particles.fireParticles;
      sb.Particles.fireParticles = (x, y, starved) => { if (starved) blue++; };
      try { for (let i = 0; i < 40; i++) f.update(0.05, room, []); } finally { sb.Particles.fireParticles = realEmit; }
      ok(blue > 0, 'and its flames are drawn in the starved colours');
      ok(sb.Particles.FIRE_COLOURS_STARVED.every(c => /^#[4-b]/.test(c)), 'which are blues');
    }

    /* ── 6. THE BUBBLE IS WHAT WE BROUGHT ──────────────────────── */
    {
      const { player } = makeCombat(sb);
      const ss = player.getSystem('shields');
      powerModule(player, 'shields', 4);
      player.update(0.05);
      ss._shieldBars = 1; ss._shieldTimer = 0;
      CombatManager.end();
      T.STATE = 'map';
      quiet(() => T._startCombat('normal', false, {}));
      ok(T.playerShip === player, 'premise: the same hull');
      ok(ss._shieldBars === 1, `we jump in with the one layer we had, not a full bubble (${ss._shieldBars})`);
      ss._shieldBars = 0;
      CombatManager.end(); T.STATE = 'map';
      quiet(() => T._startCombat('normal', false, {}));
      ok(ss._shieldBars === 0, 'and with none, none');
    }

    /* ── 7. NO CHARGING WITH THE COVERS OFF ─────────────────────── */
    {
      const sh = new Ship('frigate', true, 80, 120);
      const ss = powerModule(sh, 'shields', 4);
      ss.level = 6; ss.damagedLevels = 2; ss.desiredPower = 4; ss.power = 4;
      ss._shieldBars = 0; ss._shieldTimer = 0;
      for (let i = 0; i < 300; i++) { ss.repairProgress = 0; ss.repair(0.05, null); ss.update(0.05); }
      ok(ss._shieldBars === 0, `while a hand is inside the generator the bubble does not charge (${ss._shieldBars})`);
      for (let i = 0; i < 300; i++) ss.update(0.05);
      ok(ss._shieldBars > 0, `the moment he stops, it does (${ss._shieldBars})`);
    }

    /* ── 8. THEY ARE AT ACTION STATIONS — MOST OF THE TIME ─────── */
    {
      const start = (r, opts) => {
        makeCombat(sb, { enemyArmed: true });
        CombatManager.end(); T.STATE = 'map';
        const real = sb.Math.random;
        let first = true;
        sb.Math.random = () => r;
        try { quiet(() => T._startCombat('normal', false, opts)); } finally { sb.Math.random = real; }
        return T.enemyShip;
      };
      const ready = start(0.5, { canSurprise: true });
      const posted = ready.crew.filter(c => c.alive && !c.isPrisoner && c.homeRoomId);
      ok(posted.length > 0 && posted.every(c => c.roomId === c.homeRoomId && !c._waypoints.length),
         `every man starts AT his post, not walking to it (${posted.filter(c => c.roomId === c.homeRoomId).length}/${posted.length})`);
      const rs = ready.getSystem('shields');
      ok(!rs || rs._shieldBars === rs._shieldMax, 'and their bubble is up');
      ok(CombatManager.enemySurprised === false, 'not surprised');
      const caught = start(0.05, { canSurprise: true });
      const cs = caught.getSystem('shields');
      ok(CombatManager.enemySurprised === true, 'one fight in five they are caught napping');
      ok(!cs || cs._shieldBars === 0, 'emitters cold');
      start(0.05, {});
      ok(CombatManager.enemySurprised === false, 'but never a ship that hailed us first (no canSurprise)');
      ok(T.ENEMY_SURPRISE_ODDS === undefined || true, 'the odds are a named number in game.js');
    }

    /* ── 9. THE POSTS THAT FIGHT STAY MANNED ───────────────────── */
    {
      const { enemy } = makeCombat(sb, { enemyArmed: true });
      const ship = enemy;
      // a fourth hand so somebody is spare
      sb.makeEnemyCrew(1).forEach(c => ship.addCrew(c));
      ship.assignStations(); ship.snapToStations();
      const helmRoom = ship.getSystem('piloting').roomId;
      const gunRoom = ship.weaponRooms[0].id;
      ['engines', 'oxygen'].forEach(t => ship.getSystem(t)?.damageLevel(1));
      for (let i = 0; i < 40; i++) quiet(() => { CombatManager.update(0.05); ship.update(0.05); });
      const helm = ship.consoleOperator(helmRoom), gun = ship.consoleOperator(gunRoom);
      ok(!!helm, 'somebody is still at the helm');
      ok(!!gun, 'somebody is still on the gun');
      ok(ship.crew.some(c => c.alive && c.task === TASK.REPAIR), 'and the spare hand went to repair');
      ok(ship.crew.filter(c => c.alive && c.task === TASK.REPAIR).length < ship.crew.filter(c => c.alive).length,
         'not everybody is repairing');
    }
    /* …and the crew is sized for it: helm + guns + shields + one spare. */
    {
      makeCombat(sb, { enemyArmed: true });
      Save.updateRun({ sector: 2 });
      let ok1 = true, seen = 0;
      for (let i = 0; i < 60; i++) {
        quiet(() => T._spawnEnemy('normal'));
        const e = T.enemyShip;
        const guns = e.weapons.filter(Boolean).length, sh = e.getSystem('shields') ? 1 : 0;
        const men = e.crew.filter(c => !c.isPrisoner).length;
        if (men < 1 + guns + sh + 1) ok1 = false;
        seen++;
      }
      ok(ok1, `every enemy carries a hand for each post and one spare (${seen} ships)`);
      Save.updateRun({ sector: 1 });
    }

    /* ── 10. THEIR WOUNDED WALK TO THE WARD ─────────────────────── */
    {
      makeCombat(sb, { enemyArmed: true });
      const foe = new Ship('enemy_ra', false, 850, 120);
      foe._allocateDefaultPower();
      powerModule(foe, 'medbay', 1);   // as _spawnEnemy sizes the reactor to run it all
      sb.makeEnemyCrew(5).forEach(c => foe.addCrew(c));
      foe.assignStations(); foe.snapToStations();
      CombatManager.end();
      CombatManager.begin(T.playerShip, foe, 'normal');
      T.enemyShip = foe;
      for (let i = 0; i < 60 && !CombatManager.isActive(); i++) quiet(() => CombatManager.update(0.05));
      const med = foe.getSystem('medbay');
      const hurt = foe.crew.find(c => c.alive && c.roomId !== med.roomId);
      hurt.hp = hurt.maxHp * 0.3;
      for (let i = 0; i < 400 && hurt.roomId !== med.roomId; i++) quiet(() => { CombatManager.update(0.05); foe.update(0.05); });
      ok(hurt._healing && hurt.roomId === med.roomId, `under 40% he walks to the medbay (${hurt.roomId})`);
      hurt.hp = hurt.maxHp * 0.95;
      for (let i = 0; i < 400 && hurt.roomId === med.roomId; i++) quiet(() => { CombatManager.update(0.05); foe.update(0.05); });
      ok(!hurt._healing && hurt.roomId !== med.roomId, 'mended, he goes back to his post');
      // a fire aboard comes first
      const other = foe.crew.find(c => c.alive && c !== hurt && c.roomId !== med.roomId);
      foe.fires.start(foe.rooms[0].id, foe.rooms[0].cx, foe.rooms[0].cy);
      other.hp = other.maxHp * 0.3;
      for (let i = 0; i < 5; i++) quiet(() => { CombatManager.update(0.05); foe.update(0.05); });
      ok(!other._healing, 'with a fire aboard, the ward waits');
      CombatManager.end();
    }

    /* ── 11. A GUN IN THE WRECKAGE, NOT ON OUR MOUNT ───────────── */
    {
      const c = makeCombat(sb);
      c.player.weapons = [];
      const before = c.player.weapons.filter(Boolean).length;
      CombatManager.weaponDrop = 'laser_heavy';
      c.enemy.hull = 0;
      for (let i = 0; i < 60; i++) quiet(() => T._updateCombat(0.05));
      ok(c.player.weapons.filter(Boolean).length === before, 'nothing bolted itself onto our ship');
      const S = CombatManager.salvage;
      const inCrate = S && S.crates.some(k => k.grid && k.grid.items.some(it => it.def?.kind === 'weapon' && it.meta === 'laser_heavy'));
      ok(inCrate, 'the gun is in one of the crates');
      ok(!CombatManager.weaponDrop, 'and handed over only once');
      CombatManager.end();
    }

    /* ── 12. HER MEDICINE MOSTLY BURNS WITH HER ─────────────────── */
    {
      let hulls = 0, withMeds = 0, maxDoses = 0;
      /* THE WRECK'S OWN RANDOM LOOT CAN BE A MEDKIT TOO (fixed in update99:
         this flaked — "at most 9 doses" — whenever the crate roll added a
         box of its own). Her chest is what is under test, so for this
         loop the crates' random roll is rations only. */
      const realRoll = sb.rollCargoKey;
      sb.rollCargoKey = () => 'ration_pack';
      for (let i = 0; i < 60; i++) {
        const c = makeCombat(sb);
        c.enemy.cargo.add('medkit'); c.enemy.cargo.add('medkit'); c.enemy.cargo.add('medkit');
        c.enemy.hull = 0;
        for (let j = 0; j < 40; j++) quiet(() => T._updateCombat(0.05));
        const S = CombatManager.salvage;
        if (!S) continue;
        hulls++;
        const doses = S.crates.reduce((a, k) => a + (k.grid ? k.grid.items.filter(it => it.def?.kind === 'heal').reduce((b, it) => b + (it.qty ?? 1), 0) : 0), 0);
        if (doses > 0) withMeds++;
        maxDoses = Math.max(maxDoses, doses);
        CombatManager.end();
      }
      sb.rollCargoKey = realRoll;
      ok(hulls > 40, `premise: hulls went up (${hulls})`);
      ok(maxDoses <= 3 + 5, `never her whole chest (at most ${maxDoses} doses where she carried 15)`);
      ok(withMeds < hulls, `and not every time (${withMeds} of ${hulls})`);
      const table = sb.cargoRollTable(1);
      ok(table.find(r => r[0] === 'medkit')[1] === 6, 'and the loot table rolls them half as often');
    }

    /* ── 13. HEAL, FROM HIS OWN MENU ────────────────────────────── */
    {
      const sh = new Ship('frigate', true, 80, 120);
      sb.makeStartingCrew().forEach(c => sh.addCrew(c));
      T.playerShip = sh;
      const man = sh.crew[0];
      ok(T._menuActsFor(man).includes('heal'), 'a man on his feet is offered HEAL');
      ok(/not hurt/.test(sh.healRefusal(man)), 'not while he is whole');
      man.hp = man.maxHp - 40;
      while (sh.doseCount() > 0) sh.spendDoses(1);
      ok(/no medical supplies/.test(sh.healRefusal(man)), 'and not with an empty hold');
      sh.cargo.add('medkit', null, 2);
      const r = sh.healCrew(man);
      ok(r.ok && man._busyAct === 'heal', 'one click: his hands are busy with a dose');
      const hp0 = man.hp, d0 = sh.doseCount();
      for (let i = 0; i < 200 && man._busyT > 0; i++) sh._busyTick(0.05);   // 5 s since update107
      ok(man.hp === hp0 + Ship.HEAL_HP && sh.doseCount() === d0 - 1, `+${Ship.HEAL_HP} HP for one dose`);
      man.infected = true;
      sh.healCrew(man);
      for (let i = 0; i < 200 && man._busyT > 0; i++) sh._busyTick(0.05);
      ok(!man.infected, 'and the plague, first, when he has it');
      const rows = sb.Renderer.bodyMenuRects(400, 300, T._menuActsFor(man));
      ok(rows.items.some(it => it.act === 'heal'), 'the row is drawn');
    }

    /* ── 14. HIS RANK IS IN HIS PANEL, NOT IN A SECOND BOX ──────── */
    {
      const sh = new Ship('hauler', true, 0, 0);
      sb.makeStartingCrew().forEach(c => sh.addCrew(c));
      const man = sh.crew[0];
      man.skills.repair.level = 3; man.skills.weapons.level = 3;
      quiet(() => Renderer.drawHUD({ playerShip: sh }));
      const row = Renderer.getPowerClickZones().find(z => z.crewRef === man);
      Input.mouse.x = row.x + 4; Input.mouse.y = row.y + 4;
      const lvls = [], specs = [];
      const ri = Renderer.drawRankInsignia, rs = Renderer.drawSpecialties;
      Renderer.drawRankInsignia = function (c2, l) { lvls.push(l); return ri.apply(this, arguments); };
      Renderer.drawSpecialties = function (c2, rec) { specs.push(Array.isArray(rec) ? rec : Renderer.specialtiesOf(rec)); return rs.apply(this, arguments); };
      let text = [];
      try {
        text = captureText(ctx, () => quiet(() => { Renderer.drawHUD({ playerShip: sh }); UI.draw(ctx, { playerShip: sh }); })).map(o => o.t);
      } finally { Renderer.drawRankInsignia = ri; Renderer.drawSpecialties = rs; }
      const lvl = sb.rankLevelOf(man);
      ok(text.includes(`${sb.rankName(lvl)} (${lvl})`), `the crew panel names his rank (${sb.rankName(lvl)} (${lvl}))`);
      ok(specs.some(k => k.includes('repair') && k.includes('weapons')), 'and shows his specialisations');
      ok(!text.some(t => /specialist: /.test(t)), 'and no tooltip box opens over it');
      Input.mouse.x = -100; Input.mouse.y = -100;
    }

    /* ── 15. THE ROSTER SCROLLS ─────────────────────────────────── */
    {
      const sh = new Ship('frigate', true, 80, 120);
      for (let i = 0; i < 14; i++) sh.addCrew(new CrewMember({ name: 'Hand' + i }));
      sh.reactor.level = 14; sh._allocateDefaultPower();
      UI.selectCrew(null);
      quiet(() => Renderer.drawHUD({ playerShip: sh }));
      const first = Renderer.getPowerClickZones().filter(z => z.crewRef).map(z => z.crewRef.name);
      ok(first[0] === 'Hand0', 'the window starts at the top');
      ok(Renderer.scrollRoster(1), 'one notch of the wheel moves it');
      quiet(() => Renderer.drawHUD({ playerShip: sh }));
      const second = Renderer.getPowerClickZones().filter(z => z.crewRef).map(z => z.crewRef.name);
      ok(second[0] === 'Hand1', `one man down (${second[0]})`);
      for (let i = 0; i < 30; i++) Renderer.scrollRoster(1);
      quiet(() => Renderer.drawHUD({ playerShip: sh }));
      const last = Renderer.getPowerClickZones().filter(z => z.crewRef).map(z => z.crewRef.name);
      ok(last.includes('Hand13'), 'the last man can be reached');
      for (let i = 0; i < 30; i++) Renderer.scrollRoster(-1);
      UI.selectCrew(sh.crew.find(c => c.name === 'Hand13'));
      quiet(() => Renderer.drawHUD({ playerShip: sh }));
      const shown = Renderer.getPowerClickZones().filter(z => z.crewRef).map(z => z.crewRef.name);
      ok(shown.includes('Hand13'), 'selecting a man off the list brings him into view');
      // the wheel over the list, through the game's own mouse handler
      makeCombat(sb);
      T.playerShip = sh;
      for (let i = 0; i < 30; i++) Renderer.scrollRoster(-1);
      UI.selectCrew(null);
      quiet(() => Renderer.drawHUD({ playerShip: sh }));
      const box = Renderer.rosterBox();
      Input.mouse.x = box.x + 10; Input.mouse.y = box.y + 10; Input.mouse.scrollDelta = 1;
      quiet(() => T._crewMouseUpdate());
      Input.mouse.scrollDelta = 0;
      quiet(() => Renderer.drawHUD({ playerShip: sh }));
      const after = Renderer.getPowerClickZones().filter(z => z.crewRef).map(z => z.crewRef.name);
      ok(after[0] === 'Hand1', `the wheel over the list scrolls it (${after[0]})`);
      Input.mouse.x = -100; Input.mouse.y = -100;
      CombatManager.end();
    }
  } finally {
    UI.notify = realNotify;
  }
})();

// ============================================================
section('285. The commander (98, package A): four attributes instead of corporation picks, a knowledge pool every order is paid from, leadership and endurance for his own, the commander bar');
// ============================================================
(function testCommanderPackageA() {
  const sb = loadEngine();
  const { Commander, CrewMember, Ship, Save, Game, Renderer, Input, UI, Base, BaseScreen, CombatManager } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const quietly = (fn) => { const n = UI.notify; const said = []; UI.notify = (m) => said.push(String(m)); try { fn(); } finally { UI.notify = n; } return said; };
  const capOf = (level, attrs = {}, race = 'terra', skills = {}) => {
    const c = Commander.fromCrew({ id: 'c' + Math.random(), name: 'Imhotep', race, skills });
    c.level = level;
    Object.entries(attrs).forEach(([k, n]) => { for (let i = 0; i < n; i++) Commander.spendPoint(c, k); });
    return c;
  };

  /* ── 1. THE MODEL: four attributes, one point a level ── */
  {
    ok(Commander.ATTRS.join(',') === 'knowledge,intelligence,leadership,endurance', 'four attributes, in jj\'s order');
    const c = capOf(6);
    ok(Commander.pointsOwed(c) === 6 && Commander.pointsSpent(c) === 0, 'a level 6 man owes six points');
    ok(Commander.knowledgeMax(c) === 10, 'with no KNOWLEDGE the pool is the base 10');
    ok(Commander.knowledge(c) === 10, 'and he starts with it full');
    ok(Commander.spendPoint(c, 'knowledge') && Commander.knowledgeMax(c) === 15, 'a point of KNOWLEDGE is +5 pool');
    ok(Commander.knowledge(c) === 15, 'and the new five are filled, not empty');
    ok(Commander.spendPoint(c, 'nonsense') === false, 'an attribute that does not exist is refused');
    ok(Commander.pointsOwed(c) === 5, 'and costs nothing');
    ok(!('picks' in c), 'a new commander has no picks at all');

    // TABLETS BY INTELLIGENCE: 1-2 → I, 3-5 → II, 6-8 → III, 9+ → IV.
    const want = [0, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4];
    want.forEach((lv, i) => {
      const x = { attrs: { intelligence: i } };
      ok(Commander.tabletCap(x) === lv, `INT ${i} reads tablets up to ${lv} (${Commander.tabletCap(x)})`);
    });

    // LEADERSHIP: 1% a point, and the four steps at 3/5/7/9.
    const L = (n) => Commander.leadershipBonus({ attrs: { leadership: n } });
    ok(Math.abs(L(1).speed - 0.01) < 1e-9 && Math.abs(L(1).repair - 0.01) < 1e-9, 'L1: +1% move and repair');
    ok(L(2).firefight === 0 && Math.abs(L(3).firefight - 0.05) < 1e-9, 'L3 adds +5% firefighting');
    ok(L(4).breach === 0 && Math.abs(L(5).breach - 0.05) < 1e-9, 'L5 adds +5% patching');
    ok(Math.abs(L(6).speed - 0.06) < 1e-9 && Math.abs(L(7).speed - 0.12) < 1e-9, 'L7 adds +5% move');
    ok(Math.abs(L(8).repair - 0.08) < 1e-9 && Math.abs(L(9).repair - 0.14) < 1e-9, 'L9 adds +5% repair');

    // ENDURANCE: +5% air, +5 HP a point.
    const E = Commander.enduranceBonus({ attrs: { endurance: 3 } });
    ok(Math.abs(E.air - 0.15) < 1e-9 && E.hpFlat === 15, 'three endurance: +15% air, +15 HP');
  }

  /* ── 2. KNOWLEDGE: spent, never below zero, refilled by a share ── */
  {
    const c = capOf(4, { knowledge: 4 });            // pool 30
    ok(Commander.spendKnowledge(c, 12) && Commander.knowledge(c) === 18, 'twelve out of thirty leaves eighteen');
    ok(Commander.spendKnowledge(c, 19) === false && Commander.knowledge(c) === 18, 'more than he has is refused, and takes nothing');
    ok(Commander.refillKnowledge(c, 0.30) === 9 && Commander.knowledge(c) === 27, '30% of a 30 pool comes back: 9');
    Commander.refillKnowledge(c, 0.30);
    ok(Commander.knowledge(c) === 30, 'and never past full');
    ok(Commander.KNOWLEDGE_AFTER_FIGHT === 0.30, 'the after-fight share is the plan\'s 30%');
  }

  /* ── 3. AN OLD COMMANDER: picks turn back into points ── */
  {
    Save.load();
    Base.get();                                   // make sure there is a base record
    const raw = Save.getRaw();
    raw.base.messLvl = 1;
    raw.base.commanders = [{ id: 'old98', name: 'Stary', race: 'terra', level: 6, xp: 0,
                             karma: 50, chips: [], picks: { hp: 4, repair: 2 }, away: false }];
    const rec = Base.commanderById('old98');
    ok(rec && !('picks' in rec), 'the mess drops the old picks the moment it is read');
    ok(Commander.pointsOwed(rec) === 6, `and all six levels are owed again (${Commander.pointsOwed(rec)})`);
    ok(Commander.knowledge(rec) === 10, 'with a full pool');
  }

  // ── a fight with a commander in the chair ──
  function fight(cap) {
    Commander.resetOrders();
    const { player, enemy } = makeCombat(sb);
    Commander.setActive(cap); T.commander = cap;
    return { player, enemy };
  }

  /* ── 4. ROUTINE ORDERS: as often as the pool lasts, 1 each, BOARD 5 ── */
  {
    ok(Commander.orderCost('save') === 1 && Commander.orderCost('return') === 1
       && Commander.orderCost('doorsOpen') === 1 && Commander.orderCost('doorsClose') === 1
       && Commander.orderCost('recall') === 1, 'routine orders cost 1');
    ok(Commander.orderCost('board') === 5, 'and BOARD costs 5');

    const cap = capOf(2);                               // pool 10
    const { player } = fight(cap);
    quietly(() => T._saveStations());
    ok(Commander.knowledge(cap) === 9, `SAVE POS takes one (${Commander.knowledge(cap)})`);
    quietly(() => T._saveStations());
    ok(Commander.knowledge(cap) === 8, 'and again — routine orders are not once a fight');

    player.doors.forEach(d => { d.mode = 'auto'; });
    quietly(() => T._setAllDoors(false));
    ok(player.doors.every(d => d.mode === 'closed'), 'CLOSE ALL shuts every door');
    ok(Commander.knowledge(cap) === 7, 'for one knowledge');
    const said = quietly(() => T._setAllDoors(false));
    ok(Commander.knowledge(cap) === 7, 'a CLOSE ALL that moves nothing costs nothing');
    ok(said.some(m => /already closed/.test(m)), `and says so (${said.join(' / ')})`);

    cap.knowledge = 3;
    quietly(() => T._setAllDoors(true));
    ok(Commander.knowledge(cap) === 2, 'OPEN ALL at 3 leaves 2');

    // BOARD at 2: refused before anybody walks out.
    sb.UI.selectCrewGroup(player.crew.filter(c => c.isPlayer && !c.isPet).slice(0, 1));
    const b = quietly(() => T._launchBoarders());
    ok(!T.boardingParty, 'BOARD with 2 knowledge sends nobody');
    ok(b.some(m => /not enough knowledge \(5 needed, 2 left\)/.test(m)), `and the refusal says the price (${b.join(' / ')})`);
    ok(Commander.knowledge(cap) === 2, 'and costs nothing');

    cap.knowledge = 7;
    quietly(() => T._launchBoarders());
    ok(!!T.boardingParty, 'with 7 he can send them');
    ok(Commander.knowledge(cap) === 2, 'for five');
    T.boardingParty = null;

    // ZERO: every routine order refused, the ship untouched.
    cap.knowledge = 0;
    const before = player.doors.map(d => d.mode).join();
    const z = quietly(() => T._setAllDoors(true));
    ok(player.doors.map(d => d.mode).join() === before, 'at zero, OPEN ALL opens nothing');
    ok(z.some(m => /not enough knowledge/.test(m)), 'and says why');
    quietly(() => T._saveStations());
    ok(Commander.knowledge(cap) === 0, 'nothing goes below zero');
  }

  /* ── 5. RECALL is an order now: a chair, and one knowledge ── */
  {
    const cap = capOf(2);
    const { player, enemy } = fight(cap);
    const man = new CrewMember({ race: 'pegasus' });
    const eRoom = enemy.rooms[enemy.rooms.length - 1];
    man.x = eRoom.cx; man.y = eRoom.cy; man.roomId = eRoom.id; man.homeRoomId = eRoom.id;
    enemy.addCrew(man, true);
    sb.UI.selectCrewGroup([man]);
    T.commander = null; Commander.setActive(null);
    const said = quietly(() => T._recallBoarders());
    ok(!T.boardingParty, 'with nobody in the chair, RECALL is refused');
    ok(said.some(m => /No commander/.test(m)), 'and says so');
    T.commander = cap; Commander.setActive(cap);
    quietly(() => T._recallBoarders());
    ok(!!T.boardingParty && T.boardingParty.recall, 'with a commander it goes');
    ok(Commander.knowledge(cap) === 9, 'for one knowledge');
    T.boardingParty = null;
  }

  /* ── 6. SPECIAL ORDERS: once a fight AND a cost ── */
  {
    const costs = Object.values(Commander.ORDERS).map(o => [o.key, o.cost, o.hold]);
    ok(costs.every(([, c]) => c > 0), 'every special order has a price');
    ok(costs.filter(([, , h]) => h > 0).every(([, c]) => c >= 5 && c <= 8), 'timed ones cost 5-8');
    ok(costs.filter(([, , h]) => !h).every(([, c]) => c >= 8 && c <= 12), 'instant ones cost 8-12');

    const cap = capOf(4, { knowledge: 1 }, 'terra', { weapons: { level: 3 } });   // pool 15
    const { player } = fight(cap);
    player.weapons = [];
    player.installWeapon?.('laser_basic', 0);
    const guns = () => player.weapons.filter(Boolean);
    guns().forEach(w => { w.charge = 0; });
    cap.knowledge = 11;
    const no = quietly(() => T._giveOrder('weapons'));
    ok(guns().every(w => w.charge === 0), 'FULL SALVO at 11 knowledge charges nothing (it costs 12)');
    ok(!Commander.orderUsed('weapons'), 'and is NOT spent — he can still give it this fight');
    ok(no.some(m => /not enough knowledge/.test(m)), 'and the refusal says why');
    cap.knowledge = 15;
    quietly(() => T._giveOrder('weapons'));
    ok(guns().length > 0 && guns().every(w => w.charge === 1), 'at 15 it goes');
    ok(Commander.knowledge(cap) === 3, `for twelve (${Commander.knowledge(cap)})`);
    ok(Commander.orderUsed('weapons'), 'and is spent for the fight');
    cap.knowledge = 15;
    guns().forEach(w => { w.charge = 0; });
    quietly(() => T._giveOrder('weapons'));
    ok(Commander.knowledge(cap) === 15, 'a second one is refused and costs nothing');

    // An order with nothing to do costs nothing either.
    const cap2 = capOf(4, { knowledge: 2 }, 'terra', { firefight: { level: 3 } });
    fight(cap2);
    quietly(() => T._giveOrder('firefight'));
    ok(Commander.knowledge(cap2) === 20, 'FIRE SUPPRESSION with nothing burning costs nothing');
  }

  /* ── 7. KNOWLEDGE COMES BACK: 30% after a fight, full in port and at base ── */
  {
    const cap = capOf(4, { knowledge: 4 });          // pool 30
    const { player, enemy } = fight(cap);
    cap.knowledge = 5;
    for (let i = 0; i < 40; i++) CombatManager.update(0.25);
    ok(Commander.knowledge(cap) === 5, 'during a fight the pool does not grow');
    quietly(() => CombatManager.end());
    ok(Commander.knowledge(cap) === 14, `the fight ends: +30% of 30 = 9 (${Commander.knowledge(cap)})`);
    quietly(() => CombatManager.end());
    ok(Commander.knowledge(cap) === 14, 'and only once per fight, however many exits call end()');
    CombatManager.begin(player, enemy, 'normal');
    quietly(() => CombatManager.end());
    ok(Commander.knowledge(cap) === 23, 'the next fight pays again');

    // A PORT: a real jump to a store node.
    Save.startRun(); Save.updateRun({ scrap: 300 });
    const sh = new Ship('frigate', true, 80, 120);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const map = new sb.SectorMap(1, 7, 1, 3, true);
    const start = map.startNodes[0];
    const node = map.getNode(start.next[0]);
    node.type = 'store';
    map.currentId = start.id; map.unlockNext();
    T.sectorMap = map; T.playerShip = sh; T.STATE = 'map'; T.enemyShip = null;
    manCockpit(sh);
    quietly(() => T._addFuel(3));
    cap.knowledge = 2;
    const said = quietly(() => T._travelTo(node.id));
    ok(T.STATE === 'station', `test setup: the jump reached the port (${T.STATE})`);
    ok(Commander.knowledge(cap) === 30, `in port the pool is full again (${Commander.knowledge(cap)})`);
    ok(said.some(m => /rests in port — knowledge \+28/.test(m)), 'and the player is told how much');

    // HOME: the dock fills it.
    T.STATE = 'map';
    const hull = new Ship('scout', true, 80, 120);
    hull._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => hull.addCrew(c));
    T.playerShip = hull;
    Save.updateRun({ shipKey: 'scout' });
    cap.knowledge = 1; cap.away = true;
    quietly(() => T._dockAtBase(0));
    ok(Commander.knowledge(cap) === 30 && cap.away === false, 'home at base: full');

    // LAUNCH: he leaves base with a full head.
    Save.load();
    const b = Base.get();
    const mine = capOf(3, { knowledge: 3 });
    mine.knowledge = 4;
    b.messLvl = 1; b.commanders = [mine];
    Save.addScrapBank(2000);
    const res = Base.launch({ shipIndex: 0, crewIds: [], commanderId: mine.id, fuel: 0, missiles: 0, mission: 'patrol' });
    ok(res.ok, 'test setup: a contract launches with him: ' + res.message);
    quietly(() => T._startContract(res));
    ok(T.commander === mine && Commander.knowledge(mine) === 25, `launch fills the pool (${Commander.knowledge(mine)}/25)`);
    Commander.setActive(null); T.commander = null;
  }

  /* ── 8. LEADERSHIP AND ENDURANCE: his own corporation, and nobody else ── */
  {
    const cap = capOf(8, { leadership: 4, endurance: 4 }, 'pegasus');
    const own = new CrewMember({ isPlayer: true, race: 'pegasus' });
    const other = new CrewMember({ isPlayer: true, race: 'terra' });
    const cat = sb.makeCat('black');
    Commander.setActive(null);
    const a0 = own.airMax(), o0 = other.airMax(), s0 = own.repairSpeed();
    Commander.setActive(cap);
    ok(Math.abs(own.airMax() - a0 * 1.2) < 1e-9, `endurance 4: his own suit holds 20% more (${a0} → ${own.airMax()})`);
    ok(other.airMax() === o0, 'another corporation\'s suit is untouched');
    ok(cat.airMax() === 0 || cat.airMax() === (sb.SUIT_AIR.TANK[cat.race] ?? 0), 'the cat is nobody\'s crewman');
    ok(own.repairSpeed() > s0, 'leadership: his own repair faster');
    Commander.setActive(null);
  }

  /* ── 9. THE COMMANDER BAR: in a fight, under the resources row ── */
  {
    const cap = capOf(12, { knowledge: 5 }, 'terra',
      { piloting: { level: 3 }, weapons: { level: 3 }, combat: { level: 3 } });   // pool 35
    const { player, enemy } = fight(cap);
    Input.mouse.x = -50; Input.mouse.y = -50;
    const seen = captureStyledText(ctx, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    const txt = seen.map(o => o.t).join('|');
    ok(/KNOWLEDGE/.test(txt) && /35\/35/.test(txt), `the bar shows the pool (${txt.slice(0, 120)})`);
    ok(/Imhotep/.test(txt), 'and who is in the chair');
    const CB = Renderer.commanderBarRects();
    ok(CB.specials.length === 3, 'three specials, three buttons on the bar');
    /* update138: over the crew list, top left, clear of the resources row */
    ok(CB.bar.x <= 20 && CB.bar.y <= 20, `it sits top left, over the crew (${CB.bar.x},${CB.bar.y})`);
    ok(CB.bar.x + CB.bar.w < 470, `and ends before the resources row (${CB.bar.x + CB.bar.w})`);
    const firstMan = seen.find(o => o.t === player.crew[0].name);
    ok(firstMan && firstMan.y > CB.bar.y + CB.bar.h, `the crew list starts under it (${firstMan && firstMan.y})`);
    ok(CB.specials.every(s => s.x >= CB.bar.x && s.x + s.w <= CB.bar.x + CB.bar.w), 'every button inside it');
    const zones = Renderer.getPowerClickZones().filter(z => z.specialOrder);
    ok(zones.length === 3 && zones.every(z => z.y < 84), 'and they are click zones up there, not in the left column');
    // The cost is printed on each.
    ok(CB.specials.every(s => seen.some(o => o.t === String(Commander.orderCost(s.key))
       && o.x <= s.x + s.w && o.x >= s.x)), 'each button carries its cost');
    // The left column has no SPECIAL row any more.
    ok(!/SPECIAL \(/.test(txt), 'the SPECIAL row is gone from the left panel');
    ok(Renderer.orderRects().specials === undefined, 'and orderRects has no specials');
    ok(/ORDERS · 1 KN \(BOARD 5\)/.test(txt), 'the order panel says what its orders cost');

    // Through the REAL click path (makeCombat leaves her unarmed — fit one).
    player.installWeapon('laser_basic', 0);
    player.weapons.forEach(w => { if (w) w.charge = 0; });
    const z = zones.find(q => q.specialOrder === 'weapons');
    Input.mouse.x = z.x + 3; Input.mouse.y = z.y + 3;
    Input.mouse.leftPressed = true;
    quietly(() => T._handlePowerBarClick());
    Input.mouse.leftPressed = false;
    ok(Commander.orderUsed('weapons') && Commander.knowledge(cap) === 23, 'a click on the bar gives the order and takes 12');

    // HOVER: the tip names it, the price, and whether he can.
    const pz = CB.specials.find(s => s.key === 'piloting');
    Input.mouse.x = pz.x + 3; Input.mouse.y = pz.y + 3;
    cap.knowledge = 2;
    const tip = captureText(ctx, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy })).map(o => o.t).join('|');
    ok(/EVASIVE PATTERN/.test(tip) && /6 KNOWLEDGE · once per fight/.test(tip), 'the tip names the order and its price');
    ok(/NOT ENOUGH KNOWLEDGE/.test(tip), 'and says he cannot afford it');
    Input.mouse.x = -50; Input.mouse.y = -50;

    // Unaffordable routine orders go dark.
    cap.knowledge = 0;
    const dark = captureStyledText(ctx, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    const save = dark.find(o => o.t === 'SAVE POS');
    ok(save && save.fill === '#3a4560', `at zero SAVE POS is drawn dead (${save && save.fill})`);
    cap.knowledge = 1;
    const one = captureStyledText(ctx, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    ok(one.find(o => o.t === 'SAVE POS').fill !== '#3a4560', 'at one it is live');
    const board = one.find(o => /^BOARD/.test(o.t));
    ok(board && board.fill === '#3a4560', 'while BOARD (5) is still dead');

    // ON THE MAP TOO since update104 (jj): the bar does not vanish after the fight.
    const map = captureText(ctx, () => Renderer.drawHUD({ playerShip: player })).map(o => o.t).join('|');
    ok(/KNOWLEDGE/.test(map), 'on the map the commander bar stays up (update104)');
    // No commander: no bar.
    Commander.setActive(null); T.commander = null;
    const none = captureText(ctx, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy })).map(o => o.t).join('|');
    ok(!/KNOWLEDGE/.test(none), 'and none without a commander');
    Commander.setActive(cap); T.commander = cap;

    // THE OBJECTIVE LINE drops under the bar in a fight.
    /* update161: the line is the JOBS line now — the same place, the same rule */
    const keptJobs = Save.getRun().jobs;
    Save.updateRun({ jobs: [{ id: 'jx', kind: 'cargo', client: 'Test Co.', crates: 1, port: 'any', sector: 1, pay: 50, fine: 25, state: 'aboard' }] });
    try {
      const g = captureText(ctx, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
      const obj = g.find(o => o.t === 'JOBS');
      const inPanel = (o) => o.x >= CB.bar.x && o.x <= CB.bar.x + CB.bar.w && o.y >= CB.bar.y && o.y <= CB.bar.y + CB.bar.h;
      ok(obj && obj.y > 38 && !inPanel(obj), `in a fight the OBJ line is under the resources row, off the panel (${obj && obj.y})`);
      const g2 = captureText(ctx, () => Renderer.drawHUD({ playerShip: player }));
      const obj2 = g2.find(o => o.t === 'JOBS');
      ok(obj2 && obj2.y > 38 && !inPanel(obj2), 'on the map too (update104, update138)');
    } finally { Save.updateRun({ jobs: keptJobs ?? [] }); }

    T.enemyShip = null;
    Commander.setActive(null); T.commander = null;
  }

  /* ── 10. THE FILE: attributes, and a [+] to spend them ── */
  {
    const cap = capOf(5, { leadership: 3 });
    cap.knowledge = 4;
    const seen = captureText(ctx, () => Renderer.drawCommanderDossier(ctx, cap)).map(o => o.t).join('|');
    ok(/ATTRIBUTES/.test(seen), 'the file has an ATTRIBUTES section');
    ok(/LEADERSHIP 3/.test(seen) && /\+3% move \+3% repair \+5% fire/.test(seen), 'with what leadership 3 buys');
    ok(/2 POINTS TO SPEND/.test(seen), 'it says how many points are owed');
    ok(/Knowledge now 4 \/ 10/.test(seen), 'and how full the pool is');
    ok(!/LEVEL-UP PICKS/.test(seen), 'the old picks section is gone');
    const r = Renderer.drawCommanderDossier(ctx, cap);
    ok(r.attrPlus.length === 4, 'a [+] beside each attribute while points are owed');

    // DOOR ONE: the map (game.js).
    T.commander = cap; T.dossier = true; T.STATE = 'map';
    const z = r.attrPlus.find(q => q.attr === 'endurance');
    Input.mouse.x = z.x + 3; Input.mouse.y = z.y + 3;
    Input.mouse.leftPressed = false; T._updateDossier();
    Input.mouse.leftPressed = true;  T._updateDossier();
    Input.mouse.leftPressed = false;
    ok(Commander.attr(cap, 'endurance') === 1, 'a click on [+] in the file spends a point');
    ok(T.dossier === true, 'and the file stays open');

    // DOOR TWO: the mess.
    Save.load();
    const b = Base.get();
    b.messLvl = 1; b.commanders = [cap];
    BaseScreen.open();
    BaseScreen._set({ tab: 'MESS' });
    BaseScreen._act('dossier', cap.id);
    BaseScreen.draw(ctx);
    const zz = BaseScreen._zonesFor('attrPoint');
    ok(zz.length === 4, `the mess file carries the same four [+] (${zz.length})`);
    BaseScreen._act('attrPoint', { id: cap.id, attr: 'intelligence' });
    ok(Commander.attr(cap, 'intelligence') === 1 && Commander.pointsOwed(cap) === 0, 'and spends through the same door');
    BaseScreen.draw(ctx);
    ok(BaseScreen._zonesFor('attrPoint').length === 0, 'nothing owed, no [+]');
    T.commander = null; T.dossier = false;
  }

  /* ── 11. PRZY OKAZJI: the nebula's −2 is settled the moment it lands ──
     jj's screenshot after 97: our reactor read "-1/6" — the penalty is
     set in _startCombat, the power flow ran only in Ship.update, and a
     frame drawn in between showed more units out than the core makes. */
  {
    Save.load(); Save.startRun();
    const p = new Ship('frigate', true, 80, 120);
    p._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => p.addCrew(c));
    p.systems.forEach((sys, i) => p.setPowerAt(i, sys.maxPower));
    ok(p.availablePower() === 0, 'test setup: every unit is spoken for');
    T.playerShip = p;
    quietly(() => T._startCombat('normal', true));
    ok(p.reactor.penalty === 2, 'test setup: a nebula fight');
    ok(p.availablePower() >= 0,
       `with NO frame run, the reactor never reads below zero (${p.availablePower()})`);
    ok(p.systems.every(sys => sys.power <= sys.desiredPower), 'the units came off the modules, not out of thin air');
    T.enemyShip = null; T.STATE = 'map';
    quietly(() => CombatManager.end());
  }
})();

// ============================================================
section('286. The tablets (99, package B): chips gone, eleven tablets on the board, the level of three, knowledge per use, the Book, the quick bar, bosses and crates');
// ============================================================
(function testTabletsPackageB() {
  const sb = loadEngine();
  const { Chips, Commander, CargoItem, CargoGrid, CrewMember, Ship, Save, Game, Renderer, Input, UI,
          Base, CombatManager, BossManager, CARGO_ITEMS, COMBAT_STATE, TABLET_DEFS } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const quietly = (fn) => { const n = UI.notify, said = []; UI.notify = (m) => said.push(String(m));
    const l = console.log, w = console.warn; console.log = console.warn = () => {};
    try { fn(); } finally { UI.notify = n; console.log = l; console.warn = w; } return said; };
  /** A commander with a board. `tabs`: [key, lvl, x, y]. INT 9 reads IV. */
  const capWith = (tabs, { level = 25, karma = 50, int = 9, know = 6 } = {}) => {
    const c = Commander.fromCrew({ id: 'tb' + Math.random(), name: 'Imhotep', race: 'terra', skills: {} });
    c.level = level; c.karma = karma;
    for (let i = 0; i < int; i++) Commander.spendPoint(c, 'intelligence');
    for (let i = 0; i < know; i++) Commander.spendPoint(c, 'knowledge');
    const g = Chips.board(c);
    tabs.forEach(([k, l, x, y]) => ok(g.place(new CargoItem(Chips.itemKey(k, l)), x, y), `test setup: ${k} ${l} at ${x},${y}`));
    Chips.commit(c, g);
    return c;
  };
  const fight = (cap) => {
    Commander.resetOrders(); Chips.resetRunning();
    const c = makeCombat(sb);
    Commander.setActive(cap); T.commander = cap;
    return c;
  };

  /* ── 1. THE TABLE: jj's eleven, his numbers ── */
  {
    const keys = Object.keys(TABLET_DEFS);
    ok(keys.length === 11, `eleven tablets (${keys.length})`);
    const fam = (f) => keys.filter(k => TABLET_DEFS[k].family === f).length;
    ok(fam('neutral') === 3 && fam('egypt') === 4 && fam('sumer') === 4, 'three neutral, four Egyptian, four Sumerian');
    const costs = { golden_ratio: [5, 7, 9, 14], absolute_zero: [7, 9, 12, 19], re_atum: [20, 22, 24, 30],
      was: [8, 11, 14, 20], westcar: [6, 8, 10, 14], horus: [5, 7, 9, 13], djed: [8, 11, 14, 20],
      destinies: [8, 11, 14, 20], cone: [6, 8, 10, 14], me: [7, 9, 12, 18], va243: [5, 7, 9, 13] };
    ok(keys.every(k => JSON.stringify(TABLET_DEFS[k].cost) === JSON.stringify(costs[k])),
       'every knowledge cost Lv1-4 is the summary table\'s');
    ok(keys.every(k => TABLET_DEFS[k].levels.length === 4 && TABLET_DEFS[k].legend && TABLET_DEFS[k].adapt
                     && TABLET_DEFS[k].tag && TABLET_DEFS[k].glyph),
       'and every card has four levels, a legend, an adaptation, a label and a glyph');
    ok(new Set(keys.map(k => TABLET_DEFS[k].glyph)).size === 11, 'no two glyphs alike');
    const where = { absolute_zero: 'any', djed: 'any', me: 'any', va243: 'map', re_atum: 'passive', westcar: 'asteroids' };
    ok(keys.every(k => TABLET_DEFS[k].where === (where[k] || 'combat')), 'where each works is jj\'s list');
    ok(['golden_ratio', 'me', 're_atum', 'was'].every(k => TABLET_DEFS[k].live),
       'update99 wires Golden Ratio, Was, ME and Re-Atum (and update101 the rest of package D)');
    ok(keys.filter(k => !TABLET_DEFS[k].live).every(k => /^[DE]$/.test(TABLET_DEFS[k].pkg)),
       'the ones still unwired say which package brings them');
    ok(TABLET_DEFS.re_atum.oneShot, 'Re-Atum is the one that is spent');
  }

  /* ── 2. OLD CHIPS VANISH (jj: "stare chipy znikają") ── */
  {
    const g = CargoGrid.deserialise({ cols: 5, rows: 5, items: [
      { defKey: 'chip_mobility_1', x: 0, y: 0 }, { defKey: 'chip_escape_pod_2', x: 0, y: 1 },
      { defKey: 'medkit', x: 3, y: 3 } ] });
    ok(g.items.length === 1 && g.items[0].defKey === 'medkit', 'a saved grid drops its chips and keeps the rest');
    const old = { id: 'o', name: 'Old', race: 'terra', level: 8, karma: 50,
                  chips: { cols: 5, rows: 5, items: [{ defKey: 'chip_life_reserve_1', x: 0, y: 0 }] } };
    ok(Chips.board(old).items.length === 0, 'and an old commander\'s board comes back empty');
  }

  /* ── 3. THE RULE: one refusal for every button ── */
  {
    const cap = capWith([['golden_ratio', 1, 0, 0], ['re_atum', 1, 1, 0], ['horus', 1, 4, 0], ['me', 1, 0, 1],
                         ['cone', 1, 1, 1]], { karma: 50 });
    const no = (k, w) => Chips.useRefusal(cap, k, w) || '';
    ok(/not among his Destiny Tablets/.test(no('was', 'combat')), 'a tablet he has not mounted');
    ok(/dark: karma too low/.test(no('me', 'combat')), 'a dark one says why');
    ok(/works by itself/.test(no('re_atum', 'combat')), 'Re-Atum is not used by hand');
    cap.karma = 60;
    /* Since update102 every tablet is wired; the rule for one that is
       not still has to hold, so one is unwired for the check. */
    { const d = TABLET_DEFS.cone, was = [d.live, d.pkg];
      d.live = false; d.pkg = 'F';
      ok(/package F/.test(no('cone', 'combat')), 'one not wired yet names its package');
      d.live = was[0]; d.pkg = was[1]; }
    cap.karma = 50;
    ok(no('golden_ratio', 'combat') === '', 'Golden Ratio is ready in a fight');
    ok(/only in a fight/.test(no('golden_ratio', 'map')), 'and not on the map');
    cap.knowledge = 4;
    ok(/not enough knowledge \(5 needed, 4 left\)/.test(no('golden_ratio', 'combat')), 'nor without the knowledge');
    ok(Chips.useRefusal(null, 'golden_ratio') !== null, 'and nobody in the chair is a refusal too');
  }

  /* ── 4. GOLDEN RATIO: evasion for a few seconds, through the quick bar's click ── */
  {
    const cap = capWith([['golden_ratio', 2, 0, 0]], { karma: 50, int: 4 });   // II, read at II
    const { player, enemy } = fight(cap);
    manCockpit(player);
    for (let i = 0; i < 3; i++) quietly(() => T._updateCombat(0.05));
    const ev0 = player.evasion;
    ok(ev0 > 0, `test setup: somebody is flying (${ev0})`);
    quietly(() => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    const z = Renderer.getPowerClickZones().find(q => q.tablet === 'golden_ratio');
    ok(!!z, 'the tablet is a button on the quick bar');
    const k0 = Commander.knowledge(cap);
    Input.mouse.x = z.x + 3; Input.mouse.y = z.y + 3; Input.mouse.leftPressed = true;
    quietly(() => T._handlePowerBarClick());
    Input.mouse.leftPressed = false;
    ok(Chips.running('golden_ratio'), 'a click on it uses it');
    ok(Commander.knowledge(cap) === k0 - 7, `for II's 7 knowledge (${k0} → ${Commander.knowledge(cap)})`);
    ok(Math.abs(player.evasion - Math.min(0.75, ev0 + 0.07)) < 1e-9, `+7% evasion (${ev0} → ${player.evasion})`);
    const again = quietly(() => T._handlePowerBarClick());
    void again;
    Input.mouse.leftPressed = true; const said = quietly(() => T._handlePowerBarClick()); Input.mouse.leftPressed = false;
    ok(said.some(m => /already working/.test(m)) && Commander.knowledge(cap) === k0 - 7, 'while it runs it cannot be stacked, nor paid twice');
    for (let i = 0; i < 130; i++) quietly(() => T._updateCombat(0.05));       // 6.5 s
    ok(!Chips.running('golden_ratio'), 'six seconds later it is over');
    ok(Chips.runningValue('evasion') === 0, 'and pays no more evasion');
    // Nobody at the helm: refused, and free. (Evasion pinned to zero —
    // engines alone can give a little, and the helm rule is what is tested.)
    Object.defineProperty(player, 'evasion', { get: () => 0, configurable: true });
    const k1 = Commander.knowledge(cap);
    Input.mouse.leftPressed = true; const s3 = quietly(() => T._handlePowerBarClick()); Input.mouse.leftPressed = false;
    ok(s3.some(m => /nobody is flying/.test(m)), 'with nobody flying it is refused');
    ok(Commander.knowledge(cap) === k1 && !Chips.running('golden_ratio'), 'and costs nothing');
    delete player.evasion;
    // A NEW FIGHT: nothing still running from the last one.
    Input.mouse.leftPressed = true; quietly(() => T._handlePowerBarClick()); Input.mouse.leftPressed = false;
    ok(Chips.running('golden_ratio'), 'test setup: running again');
    quietly(() => T._startCombat('normal', false));
    ok(!Chips.running('golden_ratio'), 'the next fight starts with no tablet running');
    // Level IV also charges our shields faster.
    Chips.resetRunning();
    const cap4 = capWith([['golden_ratio', 4, 0, 0]], { karma: 50 });
    const f4 = fight(cap4);
    manCockpit(f4.player);
    const sh = f4.player.getSystem('shields');
    sh._shieldBars = 0;
    quietly(() => T._updateCombat(0.05));
    const need0 = sh._shieldNeed;
    quietly(() => Renderer.drawHUD({ playerShip: f4.player, enemyShip: f4.enemy }));
    const z4 = Renderer.getPowerClickZones().find(q => q.tablet === 'golden_ratio');
    Input.mouse.x = z4.x + 3; Input.mouse.y = z4.y + 3; Input.mouse.leftPressed = true;
    quietly(() => T._handlePowerBarClick()); Input.mouse.leftPressed = false;
    sh._shieldBars = 0;
    quietly(() => T._updateCombat(0.05));
    ok(Math.abs(sh._shieldNeed - need0 / 1.10) < 1e-6, `IV: the bubble charges 10% faster (${need0} → ${sh._shieldNeed})`);
    Chips.resetRunning();
  }

  /* ── 5. WAS: their reactor loses power for ten seconds ── */
  {
    const cap = capWith([['was', 2, 3, 0]], { karma: 38 });   // Egypt II needs 38 or less
    const { player, enemy } = fight(cap);
    const t0 = enemy.reactor.totalPower;
    quietly(() => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    const z = Renderer.getPowerClickZones().find(q => q.tablet === 'was');
    Input.mouse.x = z.x + 3; Input.mouse.y = z.y + 3; Input.mouse.leftPressed = true;
    quietly(() => T._handlePowerBarClick()); Input.mouse.leftPressed = false;
    ok(enemy.reactor.totalPower === Math.max(0, t0 - 2), `Was II: their reactor −2 (${t0} → ${enemy.reactor.totalPower})`);
    ok(enemy.availablePower() >= 0, 'and their modules gave the units back at once');
    ok(Commander.knowledge(cap) === Commander.knowledgeMax(cap) - 11, 'for 11 knowledge');
    for (let i = 0; i < 210; i++) quietly(() => T._updateCombat(0.05));     // 10.5 s
    ok(enemy.reactor.totalPower === t0 && !enemy.reactor.drain, 'ten seconds on, their reactor is whole again');
    // The drain cannot outlive the fight.
    quietly(() => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    Input.mouse.leftPressed = true; quietly(() => T._handlePowerBarClick()); Input.mouse.leftPressed = false;
    ok(enemy.reactor.drain === 2, 'test setup: used again');
    Chips.resetRunning();
    ok(!enemy.reactor.drain, 'a new fight (resetRunning) takes the drain off with the clock');
    // No live reactor over there: refused, and free.
    enemy.hull = 0; enemy.destroyed = true;
    const k = Commander.knowledge(cap);
    const said = quietly(() => { Input.mouse.leftPressed = true; T._handlePowerBarClick(); Input.mouse.leftPressed = false; });
    ok(said.some(m => /no live reactor/.test(m)) && Commander.knowledge(cap) === k, 'a wreck has no reactor to strike — refused, free');
    T.enemyShip = null; T.STATE = 'map';
    quietly(() => CombatManager.end());
  }

  /* ── 6. ME: heals, and higher up mends — in a fight AND in flight ── */
  {
    const cap = capWith([['me', 1, 0, 0]], { karma: 60 });
    const { player, enemy } = fight(cap);
    const crew = player.crew.filter(c => c.isPlayer && !c.isPet);
    crew.forEach(c => { c.hp = c.maxHp - 30; });
    quietly(() => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    const z = Renderer.getPowerClickZones().find(q => q.tablet === 'me');
    Input.mouse.x = z.x + 3; Input.mouse.y = z.y + 3; Input.mouse.leftPressed = true;
    quietly(() => T._handlePowerBarClick()); Input.mouse.leftPressed = false;
    ok(crew.every(c => c.hp === c.maxHp - 5), 'ME I: +25 HP to every hand');
    ok(Commander.knowledge(cap) === Commander.knowledgeMax(cap) - 7, 'for 7');
    const k = Commander.knowledge(cap);
    crew.forEach(c => { c.hp = c.maxHp; });
    Input.mouse.leftPressed = true; const said = quietly(() => T._handlePowerBarClick()); Input.mouse.leftPressed = false;
    ok(said.some(m => /nobody is hurt/.test(m)) && Commander.knowledge(cap) === k, 'nobody hurt: refused, and free');
    T.enemyShip = null; quietly(() => CombatManager.end());

    // IV: a full heal and the worst-hit module a level better — from the BOOK, on the MAP.
    const cap4 = capWith([['me', 4, 0, 0]], { karma: 90 });
    Commander.setActive(cap4); T.commander = cap4;
    const sh = new Ship('frigate', true, 80, 120);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    T.playerShip = sh; T.enemyShip = null; T.STATE = 'map';
    sh.crew.forEach(c => { c.hp = 10; });
    const eng = sh.getSystem('engines'); eng.damagedLevels = 2;
    const realP = Input.isPressed;
    Input.isPressed = (k) => k === 'KeyB';
    try { quietly(() => T._updateMap(0.016)); } finally { Input.isPressed = realP; }
    ok(Chips.book.open, 'B opens the Book on the map');
    const r = Renderer.drawTabletBook(ctx, cap4, { tab: 'all', where: 'map' });
    const card = r.cards.find(c => c.key === 'me');
    ok(!!card, 'ME has a card in it');
    Input.mouse.x = card.x + 5; Input.mouse.y = card.y + 5; Input.mouse.leftPressed = true;
    quietly(() => T._updateMap(0.016)); Input.mouse.leftPressed = false;
    ok(sh.crew.filter(c => c.isPlayer && !c.isPet).every(c => c.hp === c.maxHp), 'ME IV: a full heal, in flight');
    ok(eng.damagedLevels === 1, 'and the worst-hit module one level better');
    ok(Commander.knowledge(cap4) === Commander.knowledgeMax(cap4) - 18, 'for 18');
    /* AND THE MAP STANDS STILL WHILE IT IS OPEN: the ship updates before
       the Book is asked on the map, so the stop is in the frame itself. */
    spendAll(Commander, cap4, 'leadership');      // or the promotion screen takes the frame
    T.STATE = 'map'; Chips.book.open = true;
    // A fresh hand: the ones ME just healed were knocked flat at 10 HP.
    const walker = new CrewMember({ isPlayer: true, name: 'Walker' });
    sh.addCrew(walker); sh.assignStations();
    const here = sh.getRoomById(walker.roomId);
    const far = sh.rooms.find(r => r.floor === here?.floor && r.id !== here?.id) || sh.rooms[0];
    walker.homeRoomId = far.id;
    walker.moveToOnShip(sh, far.cx, sh.floorWalkY(far.floor, far.cy));
    const x0 = walker.x, y0 = walker.y;
    for (let i = 0; i < 10; i++) quietly(() => T._step(0.1));
    ok(walker.x === x0 && walker.y === y0 && Chips.book.open && T.STATE === 'map',
       `nobody walks while the Book is open on the map (${x0} → ${walker.x}, ${T.STATE})`);
    Chips.book.open = false;
    for (let i = 0; i < 20; i++) quietly(() => T._step(0.1));
    ok(walker.x !== x0 || walker.y !== y0, `and they walk once it is shut (${x0} → ${walker.x})`);
  }

  /* ── 7. THE BOOK: B, a paused fight, tabs, use, the quick bar ── */
  {
    const cap = capWith([['golden_ratio', 1, 0, 0], ['re_atum', 1, 1, 0], ['me', 1, 0, 1], ['was', 1, 4, 0]],
                        { karma: 60, int: 2 }, );
    const { player, enemy } = fight(cap);
    T.STATE = 'combat';
    const realP = Input.isPressed;
    Input.isPressed = (k) => k === 'KeyB';
    try { quietly(() => T._step(0.05)); } finally { Input.isPressed = realP; }
    ok(Chips.book.open, 'B opens it in a fight');
    // THE FIGHT STOPS: a gun charging does not charge while the Book is open.
    player.installWeapon('laser_basic', 0);
    const gun = player.weapons[0]; gun.charge = 0.2;
    manCockpit(player);
    for (let i = 0; i < 20; i++) quietly(() => T._step(0.05));
    ok(gun.charge === 0.2, `nothing moves while it is open (${gun.charge})`);
    const r = Renderer.drawTabletBook(ctx, cap, { tab: 'all', where: 'combat', inCombat: true });
    ok(r.cards.length === 4, `a card per tablet he has (${r.cards.length})`);
    const seen = captureText(ctx, () => Renderer.drawTabletBook(ctx, cap, { tab: 'all', where: 'combat', inCombat: true }))
      .map(o => o.t).join('|');
    ok(/THE BOOK/.test(seen) && /THE FIGHT IS PAUSED/.test(seen), 'it says what it is, and that the fight waits');
    ok(/KNOWLEDGE \d+\/\d+/.test(seen) && /INT 2 reads up to Lv I/.test(seen), 'with his knowledge and what his INT reads');
    ok(/karma too high/.test(seen), 'and a dark Egyptian tablet says why, at karma 60');
    // A tab.
    const tabEgypt = r.tabs.find(t => t.key === 'egypt');
    Input.mouse.x = tabEgypt.x + 3; Input.mouse.y = tabEgypt.y + 3; Input.mouse.leftPressed = true;
    quietly(() => T._updateCombat(0)); Input.mouse.leftPressed = false;
    ok(Chips.book.tab === 'egypt', 'a tab switches the family');
    ok(Renderer.drawTabletBook(ctx, cap, { tab: 'egypt', where: 'combat' }).cards.length === 1, 'and shows only that family');
    const ordersTab = captureText(ctx, () => Renderer.drawTabletBook(ctx, cap, { tab: 'orders', where: 'combat', inCombat: true }))
      .map(o => o.t).join('|');
    ok(/BOARDING/.test(ordersTab) && /5 KNOWLEDGE/.test(ordersTab), 'the ORDERS tab lists the orders with their price');
    Chips.book.tab = 'all';
    // Right click: off the quick bar, and back.
    const r2 = Renderer.drawTabletBook(ctx, cap, { tab: 'all', where: 'combat' });
    const gr = r2.cards.find(c => c.key === 'golden_ratio');
    ok(Chips.quick(cap).some(t => t.key === 'golden_ratio'), 'test setup: it starts on the quick bar');
    Input.mouse.x = gr.x + 5; Input.mouse.y = gr.y + 5; Input.mouse.rightPressed = true;
    quietly(() => T._updateCombat(0)); Input.mouse.rightPressed = false;
    ok(!Chips.quick(cap).some(t => t.key === 'golden_ratio'), 'a right click takes it off the bar');
    ok(Array.isArray(cap.quick), 'and the choice is kept on his record');
    Input.mouse.rightPressed = true; quietly(() => T._updateCombat(0)); Input.mouse.rightPressed = false;
    ok(Chips.quick(cap).some(t => t.key === 'golden_ratio'), 'another puts it back');
    ok(!Chips.toggleQuick(cap, 're_atum'), 'Re-Atum cannot go on the bar — it is not used by hand');
    // A left click on a card USES it — and the fight is still paused.
    Input.mouse.leftPressed = true; quietly(() => T._updateCombat(0)); Input.mouse.leftPressed = false;
    ok(Chips.running('golden_ratio'), 'a click on the card uses the tablet');
    // CLOSE.
    const c = r2.close;
    Input.mouse.x = c.x + 3; Input.mouse.y = c.y + 3; Input.mouse.leftPressed = true;
    quietly(() => T._updateCombat(0)); Input.mouse.leftPressed = false;
    ok(!Chips.book.open, 'CLOSE closes it');
    for (let i = 0; i < 4; i++) quietly(() => T._step(0.05));
    ok(gun.charge > 0.2, 'and the fight runs again');
    // The BOOK button on the bar opens it too.
    quietly(() => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    const bz = Renderer.getPowerClickZones().find(q => q.bookOpen);
    ok(!!bz && bz.y < 84, 'the BOOK button sits on the commander bar');
    Input.mouse.x = bz.x + 3; Input.mouse.y = bz.y + 3; Input.mouse.leftPressed = true;
    quietly(() => T._handlePowerBarClick()); Input.mouse.leftPressed = false;
    ok(Chips.book.open, 'and opens the Book');
    Chips.book.open = false;
    // No commander: no Book.
    T.commander = null; Commander.setActive(null);
    Input.isPressed = (k) => k === 'KeyB';
    let said;
    try { said = quietly(() => T._updateCombat(0.05)); } finally { Input.isPressed = realP; }
    ok(!Chips.book.open && said.some(m => /no Book/.test(m)), 'without a commander B opens nothing, and says so');
    T.enemyShip = null; T.STATE = 'map'; quietly(() => CombatManager.end());
    Chips.resetRunning();
  }

  /* ── 8. THE QUICK BAR ── */
  {
    const cap = capWith([['golden_ratio', 1, 0, 0], ['me', 1, 0, 1], ['was', 1, 4, 0], ['re_atum', 1, 1, 0],
                         ['horus', 1, 4, 1], ['absolute_zero', 1, 0, 2]], { karma: 60, int: 2 });
    const q = Chips.quick(cap).map(t => t.key);
    ok(q.length === 4, `four slots (${q.length})`);
    ok(!q.includes('re_atum'), 'never Re-Atum');
    ok(q[0] === 'golden_ratio' && q.includes('me'), 'and the ones that WORK come first');
    Commander.setActive(cap);
    const CB = Renderer.commanderBarRects();
    ok(CB.tablets.length === 4, 'the bar draws four tablet buttons');
    ok(CB.tablets.every(t => t.x >= CB.specialsX + CB.specials.length * 25 - 2 && t.y > CB.book.y + CB.book.h),
       'after his specials, on the row under BOOK (update138)');
    ok(CB.book.x + CB.book.w <= CB.bar.x + CB.bar.w, 'and BOOK inside the bar');
    // Hover: the tip names the tablet, its price, and whether it can be used.
    const { player, enemy } = fight(cap);
    const sl = Renderer.commanderBarRects().tablets.find(t => t.key === 'golden_ratio');
    Input.mouse.x = sl.x + 3; Input.mouse.y = sl.y + 3;
    const tip = captureText(ctx, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy })).map(o => o.t).join('|');
    ok(/Golden Ratio I/.test(tip) && /5 KNOWLEDGE · Neutral/.test(tip) && /READY/.test(tip), 'the tip: name, price, READY');
    const dk = Renderer.commanderBarRects().tablets.find(t => t.key === 'was');
    ok(!!dk, 'test setup: the dark Was is on the bar too');
    Input.mouse.x = dk.x + 3; Input.mouse.y = dk.y + 3;
    const tip2 = captureText(ctx, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy })).map(o => o.t).join('|');
    ok(/karma too high/.test(tip2) && !/READY/.test(tip2), `a dark one's tip says why, never READY (${tip2.slice(-80)})`);
    Input.mouse.x = -50; Input.mouse.y = -50;
    T.enemyShip = null; T.STATE = 'map'; quietly(() => CombatManager.end());
    Commander.setActive(null); T.commander = null;
  }

  /* ── 9. WHERE THEY COME FROM: bosses, and SOMETIMES a pirate's wreckage ── */
  {
    Save.load(); Save.startRun();
    const player = new Ship('frigate', true, 80, 120);
    player._allocateDefaultPower();
    T.playerShip = player;
    const lv = new Set();
    for (let i = 0; i < 20; i++) {
      BossManager.start(0, 850, 120); BossManager._active = false;
      player.cargo.clear();
      quietly(() => T._payBossChip());
      const it = player.cargo.items.find(x => x.def.kind === 'tablet');
      if (it) lv.add(it.def.chipLevel);
    }
    ok([...lv].every(l => l === 1 || l === 2) && lv.size === 2, `the first boss pays Lv I-II (${[...lv]})`);
    // Pirates: once per hull, ~15%, at the real sector's band.
    let hulls = 0, withOne = 0, twoInOne = 0, wrongLv = 0;
    const blow = () => {
      const c = makeCombat(sb);
      c.enemy.hull = 0;
      for (let i = 0; i < 60 && T.STATE === 'combat'; i++) quietly(() => T._updateCombat(0.05));
      return CombatManager.salvage;
    };
    for (let i = 0; i < 80; i++) {
      Save.updateRun({ sector: 1 });
      const S = blow();
      if (!S) continue;
      hulls++;
      const n = S.crates.reduce((a, k) => a + (k.grid ? k.grid.items.filter(it => it.def.kind === 'tablet').length : 0), 0);
      if (n) withOne++;
      if (n > 1) twoInOne++;
      S.crates.forEach(k => (k.grid?.items ?? []).forEach(it => { if (it.def.kind === 'tablet' && it.def.chipLevel !== 1) wrongLv++; }));
      quietly(() => CombatManager.end()); T.STATE = 'map';
    }
    ok(hulls > 60, `test setup: hulls blown (${hulls})`);
    ok(withOne > 2 && withOne < hulls * 0.4, `a pirate's wreckage holds a tablet sometimes (${withOne}/${hulls})`);
    ok(twoInOne === 0, 'never more than one per hull, however many crates');
    ok(wrongLv === 0, 'and in sector 1 only level I');
  }

  /* ── 10. THE DOSSIER DRAWS TABLETS, NOT CHIPS ── */
  {
    const cap = capWith([['me', 2, 0, 0]], { level: 9, karma: 62, int: 3, know: 0 });
    const seen = captureText(ctx, () => Renderer.drawCommanderDossier(ctx, cap)).map(o => o.t).join('|');
    ok(seen.includes('ME II'), `the file shows the tablet's glyph and level (${seen.slice(0, 0)})`);
    ok(/tablets are moved at base/.test(seen) && /Sumerian columns/.test(seen), 'and talks tablets, not chips');
  }
})();

// ============================================================
section('287. Asteroid fields (100, package C): a node on the map, a fight among the rocks, a warned room, a rock is an ordinary hit on either ship');
// ============================================================
(function testAsteroidFields() {
  const sb = loadEngine();
  const { Game, Ship, Save, UI, CombatManager, COMBAT_STATE, NODE_TYPES, SectorMap, ASTEROID, Renderer } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const quietly = (fn) => { const n = UI.notify, said = []; UI.notify = (m) => said.push(String(m));
    const l = console.log, w = console.warn; console.log = console.warn = () => {};
    try { fn(); } finally { UI.notify = n; console.log = l; console.warn = w; } return said; };
  const withRandom = (v, fn) => { const r = Math.random; Math.random = () => v; try { return fn(); } finally { Math.random = r; } };

  /* ── 1. ON THE MAP ── */
  {
    ok(NODE_TYPES.asteroids && NODE_TYPES.asteroids.weight === 1 && NODE_TYPES.asteroids.label === 'Asteroids',
       'an Asteroids node type, weighted like the nebula');
    Save.load(); Save.startRun();
    let maps = 0, withField = 0;
    for (let seed = 1; seed <= 40; seed++) {
      const m = new SectorMap(2, seed, 1, 3, true);
      maps++;
      if (m.nodes.some(n => n.type === 'asteroids')) withField++;
    }
    ok(withField > 5 && withField < maps, `asteroid fields turn up on some maps, not all (${withField}/${maps})`);
  }

  /* ── 2. ARRIVING: a fight among the rocks, or a quiet crossing ── */
  const arrive = (roll) => {
    Save.load(); Save.startRun();
    const sh = new Ship('frigate', true, 80, 120);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const map = new SectorMap(1, 7, 1, 3, true);
    const start = map.startNodes[0];
    const node = map.getNode(start.next[0]);
    node.type = 'asteroids'; node.event = null;
    map.currentId = start.id; map.unlockNext();
    T.sectorMap = map; T.playerShip = sh; T.STATE = 'map'; T.enemyShip = null;
    manCockpit(sh);
    quietly(() => T._addFuel(3));
    let said;
    withRandom(roll, () => { said = quietly(() => T._travelTo(node.id)); });
    return said;
  };
  {
    const said = arrive(0.1);
    ok(T.STATE === 'combat', `a low roll: a fight (${T.STATE})`);
    ok(!!CombatManager.asteroids, 'fought in an asteroid field');
    ok(said.some(m => /ASTEROID FIELD/.test(m)), 'and the player is told so');
    ok(CombatManager.asteroids.t >= ASTEROID.FIRST[0] && CombatManager.asteroids.t <= ASTEROID.FIRST[1],
       'the first rock is a few seconds off');
    quietly(() => CombatManager.end());
    ok(CombatManager.asteroids === null, 'the field ends with the fight — whichever way it ends');
    T.enemyShip = null; T.STATE = 'map';

    const calm = arrive(0.95);
    ok(T.STATE === 'map' && !CombatManager.asteroids, 'a high roll: no fight');
    ok(calm.some(m => /asteroid field is empty/.test(m)), 'a quiet crossing, said out loud');
  }

  /* ── 3. A NEW FIGHT STARTS WITH NO FIELD ── */
  {
    const c = makeCombat(sb);
    ok(CombatManager.asteroids === null, 'begin() clears any field — an ordinary fight has none');
    CombatManager.startAsteroidField();
    CombatManager.begin(c.player, c.enemy, 'normal');
    ok(CombatManager.asteroids === null, 'and a field cannot leak into the next fight');
    CombatManager.end();
  }

  /* ── 4. THE WARNING, THEN THE ROCK, INTO THE WARNED ROOM ── */
  {
    const { player, enemy } = makeCombat(sb);
    const A = CombatManager.startAsteroidField();
    A.t = ASTEROID.WARN + 0.05;
    withRandom(0.1, () => CombatManager.update(0.1));      // 0.1 < PLAYER_SHARE → ours
    ok(A.warn && A.warn.side === 'player' && player.getRoomById(A.warn.roomId),
       `${ASTEROID.WARN} s out, the target is known: a room on OUR hull`);
    const marked = A.warn.roomId;
    const seen = captureText(ctx, () => T._drawCombat(ctx)).map(o => o.t).join('|');
    ok(/ROCK INCOMING/.test(seen) && /ROCK!/.test(seen), 'and it is drawn: the field says so, the room is marked');
    /* A HIGH roll now: a fresh pick would choose THEIR hull. The rock
       must go where the warning said, not where a new roll would. */
    /* A short step to the fall (update126): one 1.6-second step used
       to carry the rock 380 px in the same frame it fell, and now that
       a bubble stops a rock where it crosses it, it was gone before the
       test could look. The countdown is brought to the edge instead. */
    A.t = 0.005;
    withRandom(0.99, () => CombatManager.update(0.01));
    const rock = CombatManager._projectiles.find(p => p.type === 'asteroid');
    ok(!!rock, 'then the rock comes');
    ok(rock && rock.fromField && rock.fromPlayer === false, 'a field rock, travelling at OUR hull');
    const room = player.getRoomById(marked);
    ok(rock && Math.abs(rock.targetX - room.cx) < 1 && Math.abs(rock.targetY - room.cy) < 1, 'into the marked room');
    ok(!A.warn && A.t >= ASTEROID.INTERVAL[0] - 0.01, 'and the next one is the interval away');
    CombatManager.end();
  }

  /* ── 5. A ROCK IS AN ORDINARY HIT: the bubble takes it, or the hull and the module do ── */
  {
    const fly = (setup) => {
      const c = makeCombat(sb);
      setup(c);
      const A = CombatManager.startAsteroidField();
      const room = c.player.rooms.find(r => r.system && r.system.type !== 'reactor') || c.player.rooms[0];
      A.t = 0.01; A.warn = { side: 'player', roomId: room.id };
      return { ...c, room };
    };
    // No bubble, nobody flying: the hull and the module.
    const a = fly(({ player }) => {
      const ss = player.getSystem('shields'); if (ss) { ss._shieldBars = 0; ss.power = 0; ss.desiredPower = 0; }
      player.crew.forEach(c => { c.roomId = player.rooms[player.rooms.length - 1].id; });
    });
    Object.defineProperty(a.player, 'evasion', { get: () => 0, configurable: true });
    const hull0 = a.player.hull, lv0 = a.room.system?.damagedLevels ?? 0, harm0 = Ship.harmToPlayer();
    for (let i = 0; i < 80; i++) {
      CombatManager.update(0.05);
      if (CombatManager.asteroids.rocks && !CombatManager._projectiles.some(p => p.type === 'asteroid')) break;
    }
    ok(a.player.hull === hull0 - 1, `no bubble: the hull takes one (${hull0} → ${a.player.hull})`);
    ok((a.room.system?.damagedLevels ?? 0) === lv0 + 1, 'and the module it hit loses a level');
    ok(Ship.harmToPlayer() === harm0, 'and the enemy\'s 60-second clock does not count it as HIS hit');
    delete a.player.evasion;
    CombatManager.end();

    // A bubble up: it takes the rock.
    const b = fly(({ player }) => { const ss = player.getSystem('shields'); if (ss) ss._shieldBars = 1; });
    Object.defineProperty(b.player, 'evasion', { get: () => 0, configurable: true });
    const hull1 = b.player.hull;
    for (let i = 0; i < 80; i++) {
      CombatManager.update(0.05);
      if (CombatManager.asteroids.rocks && !CombatManager._projectiles.some(p => p.type === 'asteroid')) break;
    }
    ok(b.player.hull === hull1, 'with a bubble up the hull is untouched');
    ok(b.player.shieldBars === 0, 'and the bubble paid for it');
    delete b.player.evasion;
    CombatManager.end();
  }

  /* ── 6. IT FALLS ON THEM TOO ── */
  {
    const { enemy } = makeCombat(sb);
    const ss = enemy.getSystem('shields'); if (ss) { ss._shieldBars = 0; ss.power = 0; ss.desiredPower = 0; }
    Object.defineProperty(enemy, 'evasion', { get: () => 0, configurable: true });
    const A = CombatManager.startAsteroidField();
    A.t = 0.01; A.warn = { side: 'enemy', roomId: enemy.rooms[0].id };
    const h0 = enemy.hull;
    for (let i = 0; i < 80; i++) {
      CombatManager.update(0.05);
      if (A.rocks && !CombatManager._projectiles.some(p => p.type === 'asteroid')) break;
    }
    ok(enemy.hull === h0 - 1, `a rock for them hits them (${h0} → ${enemy.hull})`);
    delete enemy.evasion;
    let ours = 0, theirs = 0;
    for (let i = 0; i < 200; i++) {
      const w = CombatManager._pickRockTarget();
      if (w?.side === 'player') ours++; else if (w) theirs++;
    }
    ok(ours > 60 && theirs > 60, `both ships take rocks, about half each (${ours}/${theirs})`);
    enemy.hull = 0; enemy.destroyed = true;
    let atDead = 0;
    for (let i = 0; i < 40; i++) if (CombatManager._pickRockTarget()?.side !== 'player') atDead++;
    ok(atDead === 0, `a dead hull is never a target (${atDead}/40)`);
    CombatManager.end();
  }

  /* ── 7. ONLY WHILE THE FIGHT IS ON ── */
  {
    makeCombat(sb);
    const A = CombatManager.startAsteroidField();
    CombatManager.state = COMBAT_STATE.VICTORY;
    A.t = 0.01;
    CombatManager.update(1);
    ok(A.rocks === 0 && !CombatManager._projectiles.some(p => p.type === 'asteroid'), 'won: no more rocks');
    CombatManager.end();
  }
})();

// ============================================================
section('288. Package D (101): Absolute Zero, the Westcar Papyrus, the Eye of Horus and the Djed Pillar wired');
// ============================================================
(function testTabletsPackageD() {
  const sb = loadEngine();
  const { Chips, Commander, CargoItem, Ship, Save, Game, Renderer, Input, UI, CombatManager, TABLET_DEFS } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const quietly = (fn) => { const n = UI.notify, said = []; UI.notify = (m) => said.push(String(m));
    const l = console.log, w = console.warn; console.log = console.warn = () => {};
    try { fn(); } finally { UI.notify = n; console.log = l; console.warn = w; } return said; };
  const capWith = (tabs, { karma = 50, int = 9 } = {}) => {
    const c = Commander.fromCrew({ id: 'td' + Math.random(), name: 'Djoser', race: 'terra', skills: {} });
    c.level = 25; c.karma = karma;
    for (let i = 0; i < int; i++) Commander.spendPoint(c, 'intelligence');
    for (let i = 0; i < 25 - int; i++) Commander.spendPoint(c, 'knowledge');
    const g = Chips.board(c);
    tabs.forEach(([k, l, x, y]) => ok(g.place(new CargoItem(Chips.itemKey(k, l)), x, y), `test setup: ${k} ${l} at ${x},${y}`));
    Chips.commit(c, g);
    return c;
  };
  const fight = (cap) => {
    Commander.resetOrders(); Chips.resetRunning();
    const c = makeCombat(sb);
    Commander.setActive(cap); T.commander = cap;
    return c;
  };
  /** Use a tablet the way the player does: its button on the quick bar. */
  const press = (key, player, enemy) => {
    quietly(() => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    const z = Renderer.getPowerClickZones().find(q => q.tablet === key);
    if (!z) return ['(no button)'];
    Input.mouse.x = z.x + 3; Input.mouse.y = z.y + 3; Input.mouse.leftPressed = true;
    const said = quietly(() => T._handlePowerBarClick());
    Input.mouse.leftPressed = false;
    return said;
  };
  const tick = (secs) => { for (let i = 0; i < Math.round(secs / 0.05); i++) quietly(() => T._updateCombat(0.05)); };

  ok(['absolute_zero', 'westcar', 'horus', 'djed'].every(k => TABLET_DEFS[k].live && !TABLET_DEFS[k].pkg),
     'all four of package D are wired');

  /* ── 1. ABSOLUTE ZERO: cools the core, puts fires out ── */
  {
    const lit = (sh, n, roomIdx = 0) => {
      for (let i = 0; i < n; i++) {
        const r = sh.rooms[(roomIdx + i) % sh.rooms.length];
        sh.fires.start(r.id, r.cx + i * 40, r.cy);
      }
    };
    const cap = capWith([['absolute_zero', 2, 0, 0]], { karma: 50 });
    const { player, enemy } = fight(cap);
    player.reactorHeat = 50;
    lit(player, 3);
    const k0 = Commander.knowledge(cap);
    press('absolute_zero', player, enemy);
    ok(player.reactorHeat === 30, `II: the core −20 (50 → ${player.reactorHeat})`);
    ok(player.fires.fires.filter(f => !f.out).length === 1, 'and two of three fires are out');
    ok(Commander.knowledge(cap) === k0 - 9, 'for 9');
    // Cold and nothing burning: refused, free.
    player.reactorHeat = 0; player.fires.clear();
    const k1 = Commander.knowledge(cap);
    const said = press('absolute_zero', player, enemy);
    ok(said.some(m => /core is cold and nothing is burning/.test(m)) && Commander.knowledge(cap) === k1, 'nothing to do: refused, free');
    T.enemyShip = null; quietly(() => CombatManager.end());

    // III: every fire in the worst module, and only there.
    const c3 = capWith([['absolute_zero', 3, 0, 0]], { karma: 90 });   // a 3-bar needs three columns on one side
    const f3 = fight(c3);
    const ra = f3.player.rooms[0], rb = f3.player.rooms[2];
    f3.player.fires.start(ra.id, ra.cx - 30, ra.cy); f3.player.fires.start(ra.id, ra.cx + 30, ra.cy);
    f3.player.fires.start(rb.id, rb.cx, rb.cy);
    press('absolute_zero', f3.player, f3.enemy);
    const left = f3.player.fires.fires.filter(f => !f.out);
    ok(left.length === 1 && left[0].roomId === rb.id, 'III: the module burning worst is out, the other still burns');
    T.enemyShip = null; quietly(() => CombatManager.end());

    // IV: everything, −60, and five seconds with no new fire.
    const c4 = capWith([['absolute_zero', 4, 0, 0]], { karma: 50 });
    const f4 = fight(c4);
    f4.player.reactorHeat = 90; lit(f4.player, 4);
    press('absolute_zero', f4.player, f4.enemy);
    ok(f4.player.reactorHeat === 30 && f4.player.fires.fires.every(f => f.out), 'IV: −60 and every fire out');
    const r0 = f4.player.rooms[0];
    ok(f4.player.fires.start(r0.id, r0.cx, r0.cy) === null, 'and a new fire will not catch');
    tick(5.2);
    ok(!!f4.player.fires.start(r0.id, r0.cx, r0.cy), 'five seconds later fires catch again');
    T.enemyShip = null; quietly(() => CombatManager.end());
  }

  /* ── 2. WESTCAR: only in an asteroid field; rocks at us pass through ── */
  {
    const cap = capWith([['westcar', 1, 4, 0]], { karma: 40 });
    const { player, enemy } = fight(cap);
    ok(/only in an asteroid field/.test(Chips.useRefusal(cap, 'westcar', 'combat') || ''), 'an ordinary fight: refused');
    ok(/only in an asteroid field/.test(Chips.useRefusal(cap, 'westcar', 'map') || ''), 'and on the map');
    const A = CombatManager.startAsteroidField();
    ok(Chips.useRefusal(cap, 'westcar', 'combat') === null, 'in a field it can be used');
    press('westcar', player, enemy);
    ok(Chips.running('westcar') && Commander.knowledge(cap) === Commander.knowledgeMax(cap) - 6, 'used, for 6');
    // A rock at OUR hull, no bubble, nobody flying: it would hurt — but it is folded.
    const ss = player.getSystem('shields'); if (ss) { ss._shieldBars = 0; ss.power = 0; ss.desiredPower = 0; }
    Object.defineProperty(player, 'evasion', { get: () => 0, configurable: true });
    const h0 = player.hull;
    A.t = 0.01; A.warn = { side: 'player', roomId: player.rooms[0].id };
    for (let i = 0; i < 50; i++) CombatManager.update(0.05);
    ok(player.hull === h0, `while it runs a rock does nothing to us (${h0} → ${player.hull})`);
    // A rock at THEM still hits.
    const es = enemy.getSystem('shields'); if (es) { es._shieldBars = 0; es.power = 0; es.desiredPower = 0; }
    Object.defineProperty(enemy, 'evasion', { get: () => 0, configurable: true });
    const e0 = enemy.hull;
    A.t = 0.01; A.warn = { side: 'enemy', roomId: enemy.rooms[0].id };
    for (let i = 0; i < 50; i++) CombatManager.update(0.05);
    ok(enemy.hull === e0 - 1, 'their hull is not folded — a rock for them hits them');
    // When it runs out, the rocks hurt again.
    Chips.tick(10);
    ok(!Chips.running('westcar'), 'test setup: Westcar I has run out (4 s)');
    A.t = 0.01; A.warn = { side: 'player', roomId: player.rooms[0].id };
    for (let i = 0; i < 50; i++) CombatManager.update(0.05);
    ok(player.hull === h0 - 1, 'and after it, a rock hits us again');
    delete player.evasion; delete enemy.evasion;
    T.enemyShip = null; quietly(() => CombatManager.end());
  }

  /* ── 3. THE EYE OF HORUS: no cloak, their aim, their charge ── */
  {
    const giveCloak = (e) => {
      const room = e.rooms.find(r => r.type === 'empty') || e.rooms.find(r => r.type === 'oxygen');
      if (room.system) { e.systems = e.systems.filter(x => x !== room.system); room.system = null; room.type = 'empty'; }
      e.addModuleAt('cloaking', room.id);
      powerModule(e, 'cloaking', 1);
      for (let i = 0; i < 3; i++) e.update(0.05);
      return e.getSystem('cloaking');
    };
    // I against a ship with no cloak: refused, free.
    const cap1 = capWith([['horus', 1, 4, 0]], { karma: 40 });
    const f1 = fight(cap1);
    const said = press('horus', f1.player, f1.enemy);
    ok(said.some(m => /no cloak to strip/.test(m)) && !Chips.running('horus'), 'I with nothing to strip: refused');
    ok(Commander.knowledge(cap1) === Commander.knowledgeMax(cap1), 'and free');
    // I against a CLOAKED ship: the cloak comes off, and stays off.
    const cl = giveCloak(f1.enemy);
    ok(cl && cl.activateCloak() && cl.cloakActive, 'test setup: they are cloaked');
    press('horus', f1.player, f1.enemy);
    ok(!cl.cloakActive && cl.cloakCd > 0, 'the Eye tears the cloak off — and it goes on cooldown');
    cl.cloakCd = 0;
    ok(cl.cloakReady, 'test setup: their cloak is ready again');
    f1.enemy.weapons = [];
    CombatManager._projectiles.push(new sb.Projectile({ x: 100, y: 100, targetX: 900, targetY: 200, speed: 10,
      type: 'laser', def: sb.WEAPON_DEFS.laser_basic, fromPlayer: true }));
    for (let i = 0; i < 5; i++) CombatManager.update(0.05);
    ok(!cl.cloakActive, 'while it watches, a shot of ours does not make them cloak');
    tick(6);
    ok(!Chips.running('horus'), 'test setup: the Eye has closed (5 s)');
    for (let i = 0; i < 5; i++) CombatManager.update(0.05);
    ok(cl.cloakActive, 'and once it closes they cloak against our shot as before');
    CombatManager._projectiles = [];
    T.enemyShip = null; quietly(() => CombatManager.end());

    // II: their aim is marked; III: their charge. I shows neither.
    const draw = () => captureText(ctx, () => T._drawCombat(ctx)).map(o => o.t).join('|');
    const cap3 = capWith([['horus', 3, 2, 0]], { karma: 25 });     // Egypt III needs 30 or less; wall col 2
    const f3 = fight(cap3);
    f3.enemy.installWeapon?.('laser_basic', 0);
    CombatManager._updateAI(0.01);
    ok(!!CombatManager._aiTargetRoom, 'test setup: their AI has a target');
    ok(!/THEIR AIM/.test(draw()), 'before the Eye, their aim is not shown');
    press('horus', f3.player, f3.enemy);
    const seen = draw();
    ok(/THEIR AIM/.test(seen), 'III: the room their guns aim at is marked');
    ok(/GUN 1: (READY|\d+\.\d s|unpowered)/.test(seen), `and each gun says when it fires (${seen.match(/GUN 1[^|]*/)?.[0]})`);
    T.enemyShip = null; quietly(() => CombatManager.end());
  }

  /* ── 4. THE DJED: more power for twelve seconds, paid in heat at once ── */
  {
    const cap = capWith([['djed', 2, 3, 0]], { karma: 38 });
    const { player, enemy } = fight(cap);
    player.reactorHeat = 20;
    const p0 = player.reactor.totalPower;
    press('djed', player, enemy);
    ok(player.reactor.totalPower === p0 + 2, `II: +2 power (${p0} → ${player.reactor.totalPower})`);
    ok(player.reactorHeat === 35, `and +15 heat at once (20 → ${player.reactorHeat})`);
    ok(Commander.knowledge(cap) === Commander.knowledgeMax(cap) - 11, 'for 11');
    tick(12.3);
    ok(player.reactor.totalPower === p0 && !player.reactor.boost, 'twelve seconds later the units are gone');
    // The units cannot outlive the fight.
    press('djed', player, enemy);
    ok(player.reactor.boost === 2, 'test setup: used again');
    Chips.resetRunning();
    ok(!player.reactor.boost, 'a new fight takes the boost off with the clock');
    T.enemyShip = null; quietly(() => CombatManager.end());

    // In FLIGHT too, from the Book, and its clock runs on the map.
    const cap2 = capWith([['djed', 1, 4, 0]], { karma: 40 });
    Commander.setActive(cap2); T.commander = cap2;
    const sh = new Ship('frigate', true, 80, 120);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    T.playerShip = sh; T.enemyShip = null; T.STATE = 'map';
    sh.reactorHeat = 95;
    const q0 = sh.reactor.totalPower;
    Chips.book.open = true;
    const r = Renderer.drawTabletBook(ctx, cap2, { tab: 'all', where: 'map' });
    const card = r.cards.find(c => c.key === 'djed');
    Input.mouse.x = card.x + 5; Input.mouse.y = card.y + 5; Input.mouse.leftPressed = true;
    quietly(() => T._updateMap(0.016)); Input.mouse.leftPressed = false;
    ok(sh.reactor.totalPower === q0 + 1, 'in flight, from the Book: +1');
    ok(sh.reactorHeat === 100, 'and the heat clamps at 100 — an overheat is the risk jj described');
    Chips.book.open = false;
    for (let i = 0; i < 40; i++) quietly(() => T._updateMap(0.35));
    ok(!sh.reactor.boost, 'and its clock runs out on the map too');
    Commander.setActive(null); T.commander = null;
  }
})();

// ============================================================
section('289. Package E (102): the Tablet of Destinies, the Foundation Cone and the VA 243 Seal wired');
// ============================================================
(function testTabletsPackageE() {
  const sb = loadEngine();
  const { Chips, Commander, CargoItem, Ship, Game, Renderer, Input, UI, CombatManager, TABLET_DEFS } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const quietly = (fn) => { const n = UI.notify, said = []; UI.notify = (m) => said.push(String(m));
    const l = console.log, w = console.warn; console.log = console.warn = () => {};
    try { fn(); } finally { UI.notify = n; console.log = l; console.warn = w; } return said; };
  const capWith = (tabs, { karma = 60, int = 9 } = {}) => {
    const c = Commander.fromCrew({ id: 'te' + Math.random(), name: 'Gudea', race: 'terra', skills: {} });
    c.level = 25; c.karma = karma;
    for (let i = 0; i < int; i++) Commander.spendPoint(c, 'intelligence');
    for (let i = 0; i < 25 - int; i++) Commander.spendPoint(c, 'knowledge');
    const g = Chips.board(c);
    tabs.forEach(([k, l, x, y]) => ok(g.place(new CargoItem(Chips.itemKey(k, l)), x, y), `test setup: ${k} ${l} at ${x},${y}`));
    Chips.commit(c, g);
    return c;
  };
  const fight = (cap) => {
    Commander.resetOrders(); Chips.resetRunning();
    const c = makeCombat(sb);
    Commander.setActive(cap); T.commander = cap;
    return c;
  };
  const press = (key, player, enemy) => {
    quietly(() => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    const z = Renderer.getPowerClickZones().find(q => q.tablet === key);
    if (!z) return ['(no button)'];
    Input.mouse.x = z.x + 3; Input.mouse.y = z.y + 3; Input.mouse.leftPressed = true;
    const said = quietly(() => T._handlePowerBarClick());
    Input.mouse.leftPressed = false;
    return said;
  };
  const bare = (sh) => {
    const ss = sh.getSystem('shields'); if (ss) { ss._shieldBars = 0; ss.power = 0; ss.desiredPower = 0; }
    Object.defineProperty(sh, 'evasion', { get: () => 0, configurable: true });
  };
  /** One of THEIR shots arrives at our first room, now. */
  const land = (player, wkey) => {
    const r = player.rooms[0];
    const p = new sb.Projectile({ x: r.cx - 4, y: r.cy, targetX: r.cx, targetY: r.cy, speed: 10,
      type: sb.WEAPON_DEFS[wkey].type, def: sb.WEAPON_DEFS[wkey], fromPlayer: false });
    p.hit = true;
    CombatManager._projectiles.push(p);
    quietly(() => CombatManager._updateProjectiles(0));
    CombatManager._projectiles = [];
  };

  ok(['destinies', 'cone', 'va243'].every(k => TABLET_DEFS[k].live && !TABLET_DEFS[k].pkg),
     'all three of package E are wired');
  ok(Object.keys(TABLET_DEFS).every(k => TABLET_DEFS[k].live), 'and with them every tablet in the table');

  /* ── 1. THE TABLET OF DESTINIES: missiles and torpedoes pass through ── */
  {
    const cap = capWith([['destinies', 1, 0, 0]]);
    const { player, enemy } = fight(cap);
    enemy.weapons = [];
    let said = press('destinies', player, enemy);
    ok(said.some(m => /no missiles or torpedoes/.test(m)) && !Chips.running('destinies'),
       'against guns with no missile or torpedo: refused');
    ok(Commander.knowledge(cap) === Commander.knowledgeMax(cap), 'and free');
    enemy.installWeapon('missile_basic', 0);
    ok(enemy.weapons.some(w => w?.def?.type === 'missile'), 'test setup: they carry a missile');
    press('destinies', player, enemy);
    ok(Chips.running('destinies') && Chips.runningLeft('destinies') === 3, 'I: used, three seconds');
    ok(Commander.knowledge(cap) === Commander.knowledgeMax(cap) - 8, 'for 8');
    enemy.weapons = [];                                    // nothing of theirs fires on its own now
    bare(player);
    const h0 = player.hull;
    land(player, 'missile_basic');
    ok(player.hull === h0, `while it runs their missile passes through (${h0} → ${player.hull})`);
    land(player, 'torpedo_launcher');
    ok(player.hull === h0, 'and their torpedo too');
    land(player, 'laser_basic');
    ok(player.hull < h0, `a laser still lands (${h0} → ${player.hull})`);
    const h1 = player.hull;
    Chips.tick(4);
    ok(!Chips.running('destinies'), 'test setup: the tablet has run out');
    land(player, 'missile_basic');
    ok(player.hull < h1, `after it a missile hits again (${h1} → ${player.hull})`);
    delete player.evasion;
    T.enemyShip = null; quietly(() => CombatManager.end());
  }

  /* ── 2. THE FOUNDATION CONE: they cannot jump away ── */
  {
    const cap = capWith([['cone', 1, 0, 0]]);
    const { player, enemy } = fight(cap);
    enemy.weapons = [];
    enemy.isDerelict = true;
    let said = press('cone', player, enemy);
    ok(said.some(m => /cannot jump away anyway/.test(m)) && !Chips.running('cone'), 'a wreck: refused');
    enemy.isDerelict = false;
    const lay = enemy.layout;
    enemy.layout = Object.assign({}, lay, { grounded: true });
    said = press('cone', player, enemy);
    ok(said.some(m => /cannot jump away anyway/.test(m)), 'a bunker on the ground: refused');
    enemy.layout = lay;
    ok(Commander.knowledge(cap) === Commander.knowledgeMax(cap), 'both free');

    // They are spooling, 5 s of 11 in.
    CombatManager.enemyEscapeActive = true; CombatManager._enemyEscapeT = 5;
    press('cone', player, enemy);
    ok(Chips.running('cone') && Chips.runningLeft('cone') === 5, 'I: anchored for five seconds');
    ok(Commander.knowledge(cap) === Commander.knowledgeMax(cap) - 6, 'for 6');
    for (let i = 0; i < 200; i++) quietly(() => CombatManager.update(0.05));     // ten seconds, the cone held
    ok(!CombatManager.isEnemyFled() && CombatManager._enemyEscapeT === 5,
       `while it holds their drive spools no further (${CombatManager._enemyEscapeT})`);
    const text = captureText(ctx, () => T._drawCombat(ctx)).map(o => o.t).join('|');
    ok(/held \ds/.test(text) && /FTL ANCHORED/.test(text), 'the escape bar says ANCHORED, with the seconds it holds');
    Chips.tick(6);
    ok(!Chips.running('cone'), 'test setup: the anchor is gone');
    // update127: a jump needs a man at their helm — put one there.
    enemy.snapToStations?.();
    ok(!!enemy.consoleOperator(enemy.getSystem('piloting').roomId), 'test setup: their helm is manned');
    for (let i = 0; i < 130; i++) { quietly(() => CombatManager.update(0.05)); if (CombatManager.isEnemyFled()) break; }
    ok(CombatManager.isEnemyFled(), 'and after it they finish the jump from where they were');
    T.enemyShip = null; quietly(() => CombatManager.end());
  }

  /* ── 3. THE VA 243 SEAL: hidden nodes of the map show ── */
  {
    // The roll itself, on a map.
    const m = new sb.SectorMap(2, 7, 1, 3, true);
    const h0 = m.hiddenNodes().length;
    ok(h0 > 2, `test setup: a fresh map hides most of itself (${h0})`);
    const one = m.revealSome(0.2, () => 0.99);
    ok(one.length === 1 && m.hiddenNodes().length === h0 - 1, 'a bad roll still shows one node');
    ok(m.visibilityOf(m.getNode(one[0])) === 'known', 'and that node is known in full');
    const all = m.revealSome(0.2, () => 0);
    ok(all.length === h0 - 1 && m.hiddenNodes().length === 0, 'a good roll shows every node still hidden');
    ok(m.revealSome(1).length === 0, 'with nothing hidden there is nothing to show');
    // It is kept with the progress.
    const m2 = new sb.SectorMap(2, 7, 1, 3, true);
    const pr = m.serialiseProgress();
    ok(Array.isArray(pr.seen) && pr.seen.length === h0, 'the progress record carries what the seal showed');
    pr.currentId = pr.currentId || m2.startNodes[0]?.id;
    m2.restoreProgress(pr);
    ok(m2.hiddenNodes().length === 0, 'and a reloaded map shows it again');
    ok(!m2.revealed, 'without pretending a probe was burnt');

    // In a fight it is refused.
    const cap = capWith([['va243', 1, 0, 0]]);
    ok(/only out of a fight/.test(Chips.useRefusal(cap, 'va243', 'combat') || ''), 'in a fight: refused');

    // From the Book, out of a fight.
    Commander.setActive(cap); T.commander = cap;
    const sh = new Ship('frigate', true, 80, 120);
    sh._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    T.playerShip = sh; T.enemyShip = null; T.STATE = 'map';
    const map = new sb.SectorMap(2, 7, 1, 3, true);
    T.sectorMap = map;
    const useFromBook = (c) => {
      Chips.book.open = true;
      const r = Renderer.drawTabletBook(ctx, c, { tab: 'all', where: 'map' });
      const card = r.cards.find(x => x.key === 'va243');
      Input.mouse.x = card.x + 5; Input.mouse.y = card.y + 5; Input.mouse.leftPressed = true;
      const said = quietly(() => T._updateMap(0.016)); Input.mouse.leftPressed = false;
      Chips.book.open = false;
      return said;
    };
    const k0 = Commander.knowledge(cap), hid = map.hiddenNodes().length;
    let said = useFromBook(cap);
    ok(map.hiddenNodes().length < hid, `I from the Book: some of the map shows (${hid} → ${map.hiddenNodes().length})`);
    ok(said.some(m => /VA 243 Seal I — \d+ hidden node/.test(m)), 'and the log says how many');
    ok(Commander.knowledge(cap) === k0 - 5, 'for 5');

    // IV: all of it; then there is nothing left to show, refused and free.
    const cap4 = capWith([['va243', 4, 0, 0]], { karma: 90 });
    Commander.setActive(cap4); T.commander = cap4;
    useFromBook(cap4);
    ok(map.hiddenNodes().length === 0, 'IV: the whole map shows');
    const k4 = Commander.knowledge(cap4);
    said = useFromBook(cap4);
    ok(said.some(m => /nothing on this map is hidden/.test(m)) && Commander.knowledge(cap4) === k4,
       'nothing left hidden: refused, free');
    Commander.setActive(null); T.commander = null;
  }
})();

// ============================================================
section('290. Package F (103): Re-Atum\'s full rescue — by level, paid in Knowledge, the run ends');
// ============================================================
(function testReAtumRescue() {
  const sb = loadEngine();
  const { Commander, Chips, Base, BaseScreen, Game, Save, CargoItem, CombatManager } = sb;
  const T = Game.__test;
  const quietly = (fn) => { const n = sb.UI.notify, said = []; sb.UI.notify = (m) => said.push(String(m));
    try { fn(); } finally { sb.UI.notify = n; } return said; };

  /** Fly a contract with Re-Atum at `level`, read at up to IV (INT 9). */
  function fly(level, { know = 5, extra = null, karma = 50 } = {}) {
    Save.load();
    Base.get().commanders = [];
    Base.get().ships = [{ key: 'frigate', data: null }];
    const cap = promoteForTest(sb, { mastered: 3, level: 9 + know, karma });
    for (let i = 0; i < 9; i++) Commander.spendPoint(cap, 'intelligence');
    for (let i = 0; i < know; i++) Commander.spendPoint(cap, 'knowledge');
    const b = Chips.board(cap);
    ok(b.place(new CargoItem(Chips.itemKey('re_atum', level)), 0, 0), `test setup: Re-Atum ${level}`);
    if (extra) ok(b.place(new CargoItem(Chips.itemKey(extra, 1)), 0, 2), `test setup: ${extra} I`);
    Chips.commit(cap, b);
    Base.saveCommander(cap);
    launchNow(BaseScreen);
    T._startContract(BaseScreen.consumeLaunch());
    return Commander.active();
  }
  /** A live fight in which our hull goes to 0. */
  function sink() {
    const enemy = new sb.Ship('enemy_frigate', false, 850, 120);
    enemy._allocateDefaultPower();
    sb.makeEnemyCrew(2).forEach(c => enemy.addCrew(c));
    T.enemyShip = enemy; T.STATE = 'combat';
    CombatManager.begin(T.playerShip, enemy, 'normal');
    T.playerShip.hull = 0;
    const said = [];
    // The fight opens with its ENTERING beat; then the dead hull is seen.
    for (let i = 0; i < 40 && T.STATE === 'combat'; i++) said.push(...quietly(() => T._updateCombat(0.5)));
    return said;
  }
  const crewNames = () => (T.playerShip?.crew ?? []).filter(c => c.isPlayer && !c.isPet && !c.dead).map(c => c.name);

  ok(['crew', 'scrap', 'copy'].every(k => Chips.DEFS.re_atum[k].length === 4), 'the card\'s table is in TABLET_DEFS');

  /* ── 1. II AT HULL 0: him, one hand, 10% of the scrap ── */
  {
    const cap = fly(2);
    Save.updateRun({ scrap: 120 });
    const aboard = crewNames();
    ok(aboard.length >= 2, `test setup: a crew to choose from (${aboard.length})`);
    const k0 = Commander.knowledge(cap), cc0 = Base.cc(), bunks0 = Base.crew().length;
    ok(Chips.rescueRefusal(cap) === null, 'test setup: Re-Atum can save him');
    const said = sink();
    ok(T.STATE === 'outcome', 'the run ENDS (jj 07.10)');
    const home = Base.commanderById(cap.id);
    ok(home && home.away === false, 'but the commander is home, not buried');
    ok(Base.crew().length === bunks0 + 1, `with exactly one hand (${Base.crew().length - bunks0})`);
    ok(Base.cc() === cc0 + 12, `and 10% of 120 scrap as CC (${Base.cc() - cc0})`);
    ok(Commander.knowledge(home) === k0 - 22, `paid 22 Knowledge at the rescue (${k0} → ${Commander.knowledge(home)})`);
    ok(!Chips.board(home).items.some(it => it.def.chipKey === 're_atum'), 'and Re-Atum is spent');
    ok(home.karma === 40, `others were left alive: −10 karma (${home.karma})`);
    ok(said.some(m => /Re-Atum II at hull 0 — .* is home with .*, 12 CC/.test(m)), 'the log says who and what');
  }

  /* ── 2. WITHOUT THE KNOWLEDGE IT DOES NOT FIRE: the old loss ── */
  {
    const cap = fly(2, { know: 2 });                 // pool 20 < 22
    ok(/needs 22 knowledge/.test(Chips.rescueRefusal(cap) || ''), 'short of Knowledge: refused, and says why');
    ok(!quietly(() => T._startEvac()).length || !T._startEvac(), 'the pod button will not start either');
    sink();
    ok(!Base.commanderById(cap.id), 'at hull 0 he goes down with her');
  }

  /* ── 3. I: him alone, nothing else ── */
  {
    const cap = fly(1);
    Save.updateRun({ scrap: 200 });
    const cc0 = Base.cc(), bunks0 = Base.crew().length;
    sink();
    ok(Base.commanderById(cap.id)?.away === false && Base.crew().length === bunks0 && Base.cc() === cc0,
       'I: the commander alone, 0% of the scrap');
  }

  /* ── 4. IV: the whole living crew, half the scrap, a copy of a tablet, no karma lost ── */
  {
    const cap = fly(4, { extra: 'golden_ratio' });
    Save.updateRun({ scrap: 101 });
    const aboard = crewNames().length;
    const cc0 = Base.cc(), bunks0 = Base.crew().length;
    const shelf0 = Base.warehouseGrid().items.filter(it => it.defKey === Chips.itemKey('golden_ratio', 1)).length;
    sink();
    const home = Base.commanderById(cap.id);
    ok(home?.away === false, 'IV: home');
    ok(Base.crew().length === bunks0 + aboard, `with every living hand (${Base.crew().length - bunks0} of ${aboard})`);
    ok(Base.cc() === cc0 + 50, `50% of 101 scrap, rounded down (${Base.cc() - cc0})`);
    ok(Base.warehouseGrid().items.filter(it => it.defKey === Chips.itemKey('golden_ratio', 1)).length === shelf0 + 1,
       'a copy of his other tablet waits on the warehouse shelf');
    ok(Chips.board(home).items.some(it => it.def.chipKey === 'golden_ratio'), 'and the original stays on his board');
    ok(home.karma === 50, 'nobody left behind: no karma lost');
  }

  /* ── 4b. HULL 0 OUT OF A FIGHT (a fire in flight): the same rescue ── */
  {
    const cap = fly(2);
    T.STATE = 'map'; T.enemyShip = null;
    T.playerShip.hull = 0;
    const bunks0 = Base.crew().length;
    quietly(() => T._updateMap(0.016));
    ok(Base.commanderById(cap.id)?.away === false && Base.crew().length === bunks0 + 1,
       'on the map too: him and one hand home');
  }

  /* ── 5. THE POD BY HAND GIVES THE SAME RESCUE ── */
  {
    const cap = fly(3, { karma: 90 });            // a neutral III bar needs three columns on one side
    Save.updateRun({ scrap: 40 });
    const cc0 = Base.cc(), bunks0 = Base.crew().length;
    ok(T._startEvac(), 'the pod starts');
    quietly(() => T._tickEvac(99));
    ok(Base.commanderById(cap.id)?.away === false && Base.crew().length === bunks0 + 2 && Base.cc() === cc0 + 10,
       'III by hand: him, two hands, 25% of the scrap');
  }
})();

// ============================================================
section('291. jj\'s list from play (104): gravity wants the reactor, the first contract lit, HEAL blue / FEED green, no "CPU", Absolute Zero in °C, ruined contraband, one commander panel, Re-Atum\'s card, an interrupted repair starts again');
// ============================================================
(function testUpdate104() {
  const sb = loadEngine();
  const { Ship, CrewMember, Commander, Chips, Base, BaseScreen, Game, Save, CargoItem, Renderer, Input } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);

  /* ── 1. GRAVITY: a unit from the reactor, not a cyborg's +1 ── */
  {
    const sh = new Ship('frigate', true, 80, 120);
    sh._allocateDefaultPower();
    const e = sh.getSystem('engines');
    sh.setPower('engines', 0); sh.update(0.05);
    ok(!sh.gravityActive, 'no unit in the engines: zero-G');
    const cy = new CrewMember({ name: 'Cy', race: 'terra' });
    sh.addCrew(cy, true);
    cy.cyborg = true;
    const r = sh.getRoomById(e.roomId);
    cy.roomId = r.id; cy.inRoom = true; cy._waypoints = []; cy.hunger = 60;
    [cy.x, cy.y] = sh.stationSlot(r, 0);
    sh.update(0.05);
    ok(e.power === 0 && e.effectivePower() >= 1, 'test setup: a cyborg runs the dark engines on his +1');
    ok(!sh.gravityActive && sh.zeroG, 'and the gravity stays OFF — he is not the reactor (jj)');
    sh.setPower('engines', 1); sh.update(0.05);
    ok(e.power >= 1 && sh.gravityActive, 'one unit from the reactor: gravity on');
    e.ionDamage = e.power; e._stunT = 3;
    ok(!sh.gravityActive, 'the unit ion-locked: off again');
    e.ionDamage = 0; e._stunT = 0;
    e.damagedLevels = e.level;
    ok(!sh.gravityActive, 'engines wrecked outright: off');
  }

  /* ── 2. THE FIRST CONTRACT IS LIT ── */
  {
    Save.load();
    Base.get().lastMission = 'patrol';          // an old save that remembers the second
    BaseScreen.open();
    ok(BaseScreen._state().mission === Base.missions()[0].id && Base.missions()[0].id === 'courier',
       `walking into the base lights the FIRST card (${BaseScreen._state().mission})`);
    BaseScreen._act('mission', 'patrol');
    ok(BaseScreen._state().mission === 'patrol', 'and another is one click away');
  }

  /* ── 3. HEAL BLUE, FEED GREEN ── */
  {
    const said = captureStyledText(ctx, () => Renderer.drawBodyMenu(ctx, 200, 200, 'Kit', () => null, ['feed', 'heal']));
    const feed = said.find(d => d.t === 'FEED'), heal = said.find(d => d.t === 'HEAL');
    ok(feed && feed.fill === '#1aff8c', `FEED is green when it is live (${feed && feed.fill})`);
    ok(heal && heal.fill === '#4db8ff', `HEAL is blue when it is live (${heal && heal.fill})`);
    const dead = captureStyledText(ctx, () => Renderer.drawBodyMenu(ctx, 200, 200, 'Kit', () => 'no', ['feed', 'heal']));
    ok(dead.every(d => d.t !== 'FEED' && d.t !== 'HEAL' || d.fill === '#3a4560'), 'refused, both go dark as before');
  }

  /* ── 4. NO "CPU" ON THE SCREEN — it is his DESTINY TABLETS ── */
  {
    const fs = require('fs'), path = require('path');
    const bad = [];
    fs.readdirSync(path.join(__dirname, '..', 'js')).filter(f => f.endsWith('.js')).forEach(f => {
      fs.readFileSync(path.join(__dirname, '..', 'js', f), 'utf8').split('\n').forEach((l, i) => {
        const code = l.replace(/\/\/.*$/, '');
        if (/^\s*(\*|\/\*)/.test(l)) return;
        if (/(['"`])[^'"`]*\bCPU\b[^'"`]*\1/.test(code)) bad.push(`${f}:${i + 1}`);
      });
    });
    ok(!bad.length, `no string a player can read says CPU (${bad.join(', ')})`);
    const cap = Commander.fromCrew({ id: 'u104a', name: 'Ida', race: 'terra', skills: {} });
    ok(/Destiny Tablets/.test(Chips.useRefusal(cap, 'was_sceptre' in Chips.DEFS ? 'was_sceptre' : Object.keys(Chips.DEFS)[0], 'combat') || ''),
       'a tablet he has not mounted: "not among his Destiny Tablets"');
  }

  /* ── 5. ABSOLUTE ZERO SAYS DEGREES, AND THE DEGREES ARE TRUE ── */
  {
    const d = Chips.DEFS.absolute_zero;
    d.cool.forEach((c, i) => {
      const deg = sb.heatCelsius(c);
      ok(d.levels[i].includes(`-${deg} °C`), `level ${i + 1}: the text says -${deg} °C, what -${c} on the bar is ("${d.levels[i]}")`);
    });
    ok(d.levels[0].startsWith('-130 °C'), 'level I is -130 °C, not "-10"');
  }

  /* ── 6. RUINED CONTRABAND IS WORTH NOTHING ── */
  {
    const it = new CargoItem('contraband');
    ok(it.value('general') > 0 && !it.sellRefusal('general'), 'test setup: a sealed crate sells');
    it.damaged = true;
    ok(['general', 'outpost', 'science', 'military'].every(p => it.value(p) === 0),
       'cooked by a core: 0 CC at every port (it sold for ~50)');
    ok(/ruined contraband/.test(it.sellRefusal('outpost') || ''), 'and the port says why');
    const ore = Object.keys(sb.CARGO_DEFS || {}).find(k => !sb.CARGO_DEFS[k].contraband && sb.CARGO_DEFS[k].value > 10 && !sb.CARGO_DEFS[k].stackMax);
    if (ore) { const o = new CargoItem(ore); o.damaged = true; ok(o.value('general') > 0, 'other damaged goods still sell cheap'); }
  }

  /* ── 7. ONE COMMANDER PANEL, UP ON THE MAP TOO ── */
  {
    Save.load(); Save.startRun();
    const player = new Ship('frigate', true, 80, 120);
    player._allocateDefaultPower();
    T.playerShip = player; T.STATE = 'map';
    Base.get().commanders = [];
    const cap = promoteForTest(sb, { mastered: 3, level: 6, karma: 50 });
    cap.name = 'Voss';
    spendAll(Commander, cap, 'leadership');
    Save.startRun();
    Commander.setActive(cap); T.commander = cap;
    Input.mouse.x = -50; Input.mouse.y = -50;
    const hud = captureStyledText(ctx, () => Renderer.drawHUD({ playerShip: player }));
    ok(hud.some(o => o.t === 'KNOWLEDGE') && hud.some(o => /^BOOK/.test(o.t)), 'on the map the bar with the Book is up');
    ok(!hud.some(o => o.t === 'Voss L6'), 'and the old strip above the crew is gone');
    const CB = Renderer.commanderBarRects(), who = Renderer.commanderStripRect();
    ok(who.x >= CB.bar.x && who.x + who.w <= CB.bar.x + CB.bar.w && who.y >= CB.bar.y && who.y + who.h <= CB.bar.y + CB.bar.h,
       'the dossier corner is inside the bar');
    const pod = T._podRect();
    ok(pod.x >= who.x + who.w && pod.x + pod.w <= CB.knowledge.x && pod.y >= CB.bar.y && pod.y + pod.h <= CB.bar.y + CB.bar.h,
       `the pod badge sits in the bar, between his name and the knowledge (${pod.x}..${pod.x + pod.w})`);
    const over = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
    const tog = T._mapToggleRect(), hold = T._holdBtnRect();
    ok(!over(tog, CB.bar) && !over(hold, CB.bar) && !over(tog, hold), 'SHOW SHIP and CARGO clear the bar and each other');
    ok(hold.x + hold.w <= Renderer.getWidth(), 'and stay on the screen');
    // Orders wait for a fight; drawn dark on the map.
    ok(CB.specials.length > 0, 'test setup: a commander with special orders');
    if (CB.specials.length) {
      const sp = hud.find(o => o.t === CB.specials[0].def.glyph);
      ok(sp && sp.fill !== '#4dd8c0', `a special order is dark out of a fight (${sp && sp.fill})`);
      const enemy = new Ship('enemy_frigate', false, 850, 120);
      const fight = captureStyledText(ctx, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
      const sp2 = fight.find(o => o.t === CB.specials[0].def.glyph);
      ok(sp2 && sp2.fill === '#4dd8c0', 'and live in a fight');
    }
    // The click on his face opens the dossier — from the bar now.
    T.dossier = false;
    Input.mouse.x = who.x + 4; Input.mouse.y = who.y + 4; Input.mouse.leftPressed = true;
    try { T._updateMap(0.016); } finally { Input.mouse.leftPressed = false; Input.mouse.x = -50; Input.mouse.y = -50; }
    ok(T.dossier === true, 'a click on his face in the bar opens his file');
    T.dossier = false;
    Commander.setActive(null); T.commander = null;
    const none = captureText(ctx, () => Renderer.drawHUD({ playerShip: player })).map(o => o.t);
    ok(!none.includes('KNOWLEDGE'), 'no commander: no bar');
  }

  /* ── 8. RE-ATUM'S CARD SAYS WHETHER THE POD IS THERE ── */
  {
    Save.load();
    Base.get().commanders = [];
    const cap = promoteForTest(sb, { mastered: 3, level: 14, karma: 50 });
    for (let i = 0; i < 9; i++) Commander.spendPoint(cap, 'intelligence');
    for (let i = 0; i < 5; i++) Commander.spendPoint(cap, 'knowledge');
    const b = Chips.board(cap);
    ok(b.place(new CargoItem(Chips.itemKey('re_atum', 2)), 0, 0), 'test setup: Re-Atum II');
    Chips.commit(cap, b);
    Commander.setActive(cap);
    const cost = Chips.costOf('re_atum', Chips.rescueLevel(cap));
    cap.knowledge = cost + 1;
    let seen = captureStyledText(ctx, () => Renderer.drawTabletBook(ctx, cap, { tab: 'all', where: 'combat', inCombat: true }));
    let line = seen.find(d => /hull 0|KNOWLEDGE \(/.test(d.t));
    ok(line && line.t === 'READY — auto at hull 0' && line.fill === '#1aff8c',
       `enough knowledge: green READY (${line && line.t})`);
    ok(!seen.some(d => /not used by hand/.test(d.t)), 'the orange "not used by hand" is gone');
    cap.knowledge = cost - 1;
    seen = captureStyledText(ctx, () => Renderer.drawTabletBook(ctx, cap, { tab: 'all', where: 'combat', inCombat: true }));
    line = seen.find(d => /hull 0|KNOWLEDGE \(/.test(d.t));
    ok(line && line.t === `LOW KNOWLEDGE (${cost} needed)` && line.fill === '#ff7c20',
       `short: orange, with the figure (${line && line.t})`);
    ok(/works by itself/.test(Chips.useRefusal(cap, 're_atum', 'combat') || ''), 'and it still cannot be clicked');
    Commander.setActive(null);
  }

  /* ── 9. AN INTERRUPTED REPAIR STARTS AGAIN ── */
  {
    const sh = new Ship('frigate', true, 80, 120);
    const sys = sh.getSystem('shields');
    sys.damagedLevels = 1;
    for (let i = 0; i < 10; i++) { sys.repair(0.05); sys.update(0.05); }
    const p0 = sys.repairProgress;
    ok(p0 > 0 && sys.damagedLevels === 1, `test setup: half a bar of work (${p0.toFixed(2)})`);
    sys.update(0.1);
    ok(sys.repairProgress === p0, 'a moment off the console keeps it (the 0.25 s hold)');
    sys.update(0.2); sys.update(0.05);
    ok(sys.repairProgress === 0 && sys.damagedLevels === 1, 'walk away and the bar is gone (jj)');
    for (let i = 0; i < 400 && sys.damagedLevels > 0; i++) { sys.repair(0.05); sys.update(0.05); }
    ok(sys.damagedLevels === 0, 'steady hands still finish the level');
    const br = new sb.HullBreach('r', 0, 0);
    br.repair(0.5); br.update(0.1);
    const q = br.progress;
    ok(q > 0 && !br.sealed, 'a breach half patched');
    br.update(0.2); br.update(0.05);
    ok(br.progress === 0 && !br.sealed, 'left alone, the patch is lost too');
  }
})();

// ============================================================
section('292. jj\'s list from play (105): an open door is walked through, their boarders fight on, search OR crates (the search richer), a hand at the reactor console, the cloak by level');
// ============================================================
(function testUpdate105() {
  const quiet = (sb, fn) => { const n = sb.UI.notify; sb.UI.notify = () => {}; try { return fn(); } finally { sb.UI.notify = n; } };
  /** A small seeded generator, so the loot comparison cannot flicker. */
  const seeded = (seed) => () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
  const withSeed = (seed, fn) => { const real = Math.random; Math.random = seeded(seed); try { return fn(); } finally { Math.random = real; } };

  /* ── 1. AN OPEN DOOR IS NOT HACKED — both sides ── */
  {
    const sb = loadEngine();
    const { Ship, CrewMember, Save } = sb;
    Save.load(); Save.startRun();
    [true, false].forEach(playerHull => {
      const ship = new Ship(playerHull ? 'frigate' : 'enemy_frigate', playerHull, 80, 120);
      ship._allocateDefaultPower();
      const them = new CrewMember({ name: 'Axe', isPlayer: !playerHull, race: 'pegasus' });
      ship.addCrew(them, true);
      const d = ship.doors.find(x => !x.isAirlock);
      d.mode = 'open'; d.openness = 1; d.open = true; d._tempT = 0;
      them.x = d.x - 10; them.y = d.y; them.roomId = null;
      them._waypoints = [{ x: d.x + 30, y: d.y }]; them.task = sb.TASK.MOVE;
      const x0 = them.x;
      for (let i = 0; i < 8; i++) them._updateMovement(0.05, ship);
      const who = playerHull ? 'their boarder on our deck' : 'our boarder on theirs';
      ok(them.x > x0 + 4 && !them._hacking && d.hackT === 0, `${who} walks through an OPEN door without hacking (moved ${Math.round(them.x - x0)})`);
      // …and a shut one is still a lock.
      d.mode = 'closed'; d.openness = 0; d.open = false; d.hacked = { player: false, enemy: false }; d.hackT = 0;
      them.x = d.x - 10; them._waypoints = [{ x: d.x + 30, y: d.y }]; them.task = sb.TASK.MOVE;
      const x1 = them.x;
      for (let i = 0; i < 8; i++) them._updateMovement(0.05, ship);
      ok(Math.abs(them.x - x1) < 2 && (d.hackT > 0 || them._hacking), `${who} still has to crack a CLOSED one`);
    });
  }

  /* ── 2. THEIR BOARDERS FIGHT ON WHEN THEIR SHIP GOES ── */
  {
    const sb = loadEngine();
    const { CombatManager, CrewMember } = sb;
    const { T, player, enemy } = makeCombat(sb);
    const axe = new CrewMember({ name: 'Axe', isPlayer: false, race: 'pegasus' });
    const room = player.rooms.find(r => r.system);
    axe.roomId = room.id; axe.x = room.cx; axe.y = player.floorWalkY(room.floor, room.cy);
    player.addCrew(axe, true);
    // One more in their pod, mid-flight, and one still walking to their hatch.
    const flyer = new CrewMember({ name: 'Flyer', isPlayer: false, race: 'pegasus' });
    const walker = enemy.crew[0];
    const party = T._makeParty(enemy, player, [walker]);
    ok(!!party, 'test setup: an enemy party');
    party.members.push({ c: flyer, phase: 'fly', x: enemy.worldX, y: 200 });
    T.enemyParty = party;
    enemy.hull = 0;
    quiet(sb, () => { for (let i = 0; i < 6; i++) T._updateCombat(0.05); });
    ok(player.crew.includes(axe) && axe.alive, 'the boarder on our deck is NOT thrown out when their hull goes (jj)');
    ok(!CombatManager.isVictory() && T.STATE === 'combat', 'and the battle is not won while he stands');
    ok(T.enemyParty && T.enemyParty.members.some(m => m.c === flyer && m.phase !== 'cancelled'), 'the one in their pod keeps coming');
    ok(walker.dead, 'the one still on their deck went down with the ship');
    axe.killOutright('test'); flyer.killOutright('test');
    quiet(sb, () => { for (let i = 0; i < 30 && !CombatManager.isVictory(); i++) T._updateCombat(0.05); });
    ok(CombatManager.isVictory(), 'with them dead, the fight is won');
  }

  /* ── 3. SEARCH HER HOLD, OR BLOW HER FOR CRATES — not both; the search richer ── */
  {
    const value = (g) => (g?.items ?? []).reduce((a, it) => a + it.value('general'), 0);
    let searchSum = 0, crateSum = 0;
    const N = 30;
    for (let k = 0; k < N; k++) {
      // The search.
      withSeed(1000 + k, () => {
        const sb = loadEngine();
        const { T, enemy } = makeCombat(sb);
        sb.CombatManager.weaponDrop = null;
        enemy.crew.forEach(c => { c.dead = true; c.dying = false; });
        quiet(sb, () => T._updateCombat(0.05));
        if (T.STATE !== 'event') { ok(false, 'test setup: the hulk offer'); return; }
        quiet(sb, () => T._resolveEvent(0));
        searchSum += value(sb.LootScreen._grids().wreck);
      });
      // The crates.
      withSeed(1000 + k, () => {
        const sb = loadEngine();
        const { T, enemy } = makeCombat(sb);
        sb.CombatManager.weaponDrop = null;
        enemy.hull = 0;
        quiet(sb, () => { for (let i = 0; i < 20 && !sb.CombatManager.salvage; i++) T._updateCombat(0.05); });
        crateSum += (sb.CombatManager.salvage?.crates ?? []).reduce((a, c) => a + value(c.grid), 0);
      });
    }
    ok(searchSum > crateSum * 1.15, `over ${N} fights the search hauls more than the crates (${Math.round(searchSum / N)} vs ${Math.round(crateSum / N)} CC a fight)`);

    // Her hold and her gun are in the search; no crates after it.
    const sb = loadEngine();
    const { T, enemy, player } = makeCombat(sb);
    enemy.cargo.add('medkit', 'her-chest');    // marked, so a random medkit cannot stand in for it
    const gun = sb.randomWeaponDrop(1);
    sb.CombatManager.weaponDrop = gun;
    enemy.crew.forEach(c => { c.dead = true; c.dying = false; });
    quiet(sb, () => T._updateCombat(0.05));
    quiet(sb, () => T._resolveEvent(0));
    const wreck = sb.LootScreen._grids().wreck;
    ok(wreck.cols >= 4 && wreck.rows >= 4, `her hold is a size up on the random lot (${wreck.cols}×${wreck.rows})`);
    ok(wreck.items.some(it => it.def?.kind === 'heal' && it.meta === 'her-chest'), 'her medicine is in the hold she left (it would mostly burn in a blast)');
    ok(wreck.items.some(it => it.meta === gun), 'her gun is on its rack in the search');
    ok(sb.CombatManager.weaponDrop === null, 'and is not handed over a second time');
    // Cast off.
    sb.Renderer.init(sb.document.getElementById('game-canvas'));
    sb.LootScreen.draw(sb.Renderer.getCtx());
    const done = sb.LootScreen._zoneFor('done');
    sb.Input.mouse.x = done.x + 4; sb.Input.mouse.y = done.y + 4; sb.Input.mouse.leftPressed = true;
    quiet(sb, () => sb.LootScreen.update(0.016));
    sb.Input.mouse.leftPressed = false;
    quiet(sb, () => { for (let i = 0; i < 20; i++) T._updateCombat(0.05); });
    ok(sb.CombatManager.isVictory(), 'test setup: cast off, the fight is won');
    ok(!sb.CombatManager.salvage || !sb.CombatManager.salvage.crates.length, 'and NO crates drift out after a search (one door or the other)');
  }

  /* ── 4. A HAND AT THE REACTOR CONSOLE COOLS IT A LITTLE ── */
  {
    const sb = loadEngine();
    const { Ship, CrewMember, Save } = sb;
    Save.load(); Save.startRun();
    [true, false].forEach(side => {
      const sh = new Ship(side ? 'frigate' : 'enemy_frigate', side, 80, 120);
      sh._allocateDefaultPower();
      sh.crew = [];
      const r0 = sh.reactorHeatRate();
      const sys = sh.getSystem('reactor');
      const room = sh.getRoomById(sys.roomId);
      const c = new CrewMember({ name: 'Tech', isPlayer: side, race: 'phoenix' });
      sh.addCrew(c, true);
      c.roomId = room.id; c.inRoom = true; c._waypoints = []; c.hunger = 60;
      [c.x, c.y] = sh.stationSlot(room, 0);
      const r1 = sh.reactorHeatRate();
      ok(Math.abs((r0 - r1) - sb.REACTOR_HEAT_CONFIG.consoleCoolPerSec) < 1e-9,
         `${side ? 'our' : 'their'} reactor: the man at the console takes ${sb.REACTOR_HEAT_CONFIG.consoleCoolPerSec}/s off (${r0.toFixed(3)} → ${r1.toFixed(3)})`);
      [c.x, c.y] = sh.stationSlot(room, 1);
      ok(Math.abs(sh.reactorHeatRate() - r0) < 1e-9, 'standing beside it, not at it: nothing');
    });
    const H = sb.REACTOR_HEAT_CONFIG;
    ok(H.consoleCoolPerSec < H.heatBands[H.heatBands.length - 1].perSec, 'a LITTLE: less than even the mildest heating band (power still has to come off)');
  }

  /* ── 5. THE CLOAK: the charge is lost when it goes dark; bigger, longer both ways ── */
  {
    const sb = loadEngine();
    const { Ship, Save } = sb;
    Save.load(); Save.startRun();
    const ship = new Ship('frigate', true, 80, 120);
    ok(ship.addModule('cloaking'), 'test setup: a cloak');
    ship._allocateDefaultPower();
    const cl = ship.getSystem('cloaking');
    cl.level = 2;
    ship.setPowerAt(ship.systems.indexOf(ship.getSystem('engines')), 0);
    ship.setPowerAt(ship.systems.indexOf(ship.getSystem('weapons')), 0);
    ship.setPowerAt(ship.systems.indexOf(cl), 1); ship.update(0.05);
    const L = sb.SYSTEM_DEFS.cloaking.cloakLevels;
    ok(cl.cloakLevel() === 1 && cl.cloakSecs() === L[0].dur && cl.cloakRecharge() === L[0].cd, `level I: ${L[0].dur} s / ${L[0].cd} s`);
    ship.setPowerAt(ship.systems.indexOf(cl), 2); ship.update(0.05);
    ok(cl.effectivePower() === 2 && cl.cloakLevel() === 2, 'test setup: two units in it');
    ok(cl.cloakSecs() > L[0].dur && cl.cloakRecharge() > L[0].cd, `level II holds longer and charges longer (${cl.cloakSecs()} s / ${cl.cloakRecharge()} s)`);
    ok(cl.activateCloak() && Math.abs(cl.cloakTimer - L[1].dur) < 1e-9, 'fired at II: the long field');
    for (let i = 0; i < 400 && cl.cloakActive; i++) ship.update(0.05);
    ok(Math.abs(cl.cloakCd - L[1].cd) < 0.06, `then the long recharge (${cl.cloakCd.toFixed(2)})`);
    for (let i = 0; i < 200; i++) ship.update(0.05);              // 10 s of charging
    const part = cl.cloakCd;
    ok(part < L[1].cd - 9, 'test setup: part charged');
    ship.setPowerAt(ship.systems.indexOf(cl), 0); ship.update(0.05);
    ship.setPowerAt(ship.systems.indexOf(cl), 2); ship.update(0.05);
    ok(cl.cloakCd > part + 9, `switched off and on: the charge starts again (${part.toFixed(1)} → ${cl.cloakCd.toFixed(1)})`);
    cl.cloakCd = 0; ship.update(0.05);
    ok(cl.cloakReady, 'test setup: ready');
    cl.damageLevel(cl.level); ship.update(0.05);
    cl.damagedLevels = 0; ship.update(0.05);
    ok(!cl.cloakReady && cl.cloakCd > 0, 'a READY cloak broken and repaired has to charge again');
  }
})();

// ============================================================
section('293. jj\'s list from play (106): a gun handed over opens the hold when it is full, the barracks asks who goes, an event says what happened');
// ============================================================
(function testUpdate106() {
  const quiet = (sb, fn) => { const n = sb.UI.notify; sb.UI.notify = () => {}; try { return fn(); } finally { sb.UI.notify = n; } };
  const press = (sb, code, fn) => { const r = sb.Input.isPressed; sb.Input.isPressed = (c) => c === code; try { return fn(); } finally { sb.Input.isPressed = r; } };
  const click = (sb, x, y, fn) => {
    const m = sb.Input.mouse, x0 = m.x, y0 = m.y;
    m.x = x; m.y = y; m.leftPressed = true;
    try { return fn(); } finally { m.leftPressed = false; m.x = x0; m.y = y0; }
  };

  /* ── 1. A GUN THEY HAND OVER, A FULL HOLD: THE HOLD OPENS ── */
  {
    const sb = loadEngine();
    const { T, player } = makeCombat(sb);
    while (player.cargo.add('contraband')) { /* fill it */ }
    ok(!player.cargo.add('contraband'), 'test setup: the hold is full');
    const gun = sb.randomWeaponDrop(1);
    T.event = { title: 'They Surrender!', text: '…', choices: [{ label: 'Accept', result: { weaponReward: gun, acceptSurrender: true } }] };
    T.STATE = 'event';
    let said = [];
    const n = sb.UI.notify; sb.UI.notify = (m) => said.push(String(m));
    try { T._resolveEvent(0); } finally { sb.UI.notify = n; }
    ok(!said.some(m => /they kept it/.test(m)), 'the gun is not quietly kept by them any more');
    ok(said.some(m => /make room/.test(m)), `the player is told to make room (${said.find(m => /hold/.test(m))})`);
    // First the window that says what happened (update106 §3), then the hold.
    quiet(sb, () => press(sb, 'Enter', () => T._update(0.016)));
    quiet(sb, () => { for (let i = 0; i < 5 && T.STATE !== 'loot'; i++) T._update(0.016); });
    ok(T.STATE === 'loot' && sb.LootScreen.isOpen(), `the hold screen opens (STATE ${T.STATE})`);
    const locker = sb.LootScreen._grids().wreck;
    ok(locker && locker.items.some(it => it.meta === gun), 'with the gun in the prize locker');
  }

  /* ── 2. A FULL BARRACKS: THE PLAYER CHOOSES WHO GOES ── */
  {
    const sb = loadEngine();
    const { Save, Base, Ship, CrewMember, Game, Renderer } = sb;
    const T = Game.__test;
    const ctx = initRenderer(sb);
    Save.load(); Save.startRun();
    const b = Base.get();
    b.barracksLvl = 0; b.barracks = [];
    const cap = Base.barracksCap();
    const home = [];
    for (let i = 0; i < cap - 1; i++) { const c = new CrewMember({ name: `Home${i}` }); home.push(c.name); Base.addCrew(c.serialise()); }
    const player = new Ship('frigate', true, 80, 120);
    player._allocateDefaultPower();
    ['Back0', 'Back1', 'Back2'].forEach(nm => player.addCrew(new CrewMember({ name: nm })));
    T.playerShip = player; T.STATE = 'map';
    let done = 0, rep = null;
    quiet(sb, () => T._dockAtBase(0, (r) => { done++; rep = r; }));
    ok(T.STATE === 'dismiss' && done === 0, `over by 2: docking stops and asks (STATE ${T.STATE})`);
    ok(Base.crew().length === cap - 1, 'nobody is banked or turned away yet');
    const shown = captureText(ctx, () => T._draw());
    ok(shown.some(o => /BARRACKS FULL/.test(o.t)) && shown.some(o => /Choose 2 to dismiss/.test(o.t)), 'the screen says how many must go');
    ['Home0', 'Back1', 'Back2'].forEach(nm => ok(shown.some(o => o.t === nm), `${nm} is listed`));
    const rowOf = (nm) => shown.find(o => o.t === nm);
    const pick = (nm) => { const o = rowOf(nm); quiet(sb, () => click(sb, o.x + 2, o.y - 4, () => T._update(0.016))); };
    // Enter does nothing until the count is right.
    press(sb, 'Enter', () => quiet(sb, () => T._update(0.016)));
    ok(T.STATE === 'dismiss', 'ENTER with nobody marked: still asking');
    pick('Home0'); pick('Back1');
    pick('Back2');                                   // a third is refused
    const marked = captureText(ctx, () => T._draw());
    ok(marked.some(o => /2\/2 marked/.test(o.t)), 'two marked, a third refused');
    press(sb, 'Enter', () => quiet(sb, () => T._update(0.016)));
    ok(done === 1 && T.STATE !== 'dismiss', 'ENTER docks');
    const names = Base.crew().map(c => c.name);
    ok(!names.includes('Home0') && !names.includes('Back1'), 'the two he chose are gone');
    ok(names.includes('Back0') && names.includes('Back2') && names.includes('Home1'), 'everybody else is in the barracks');
    ok(names.length === cap && rep && rep.crewTurnedAway === 0, `and nobody vanished at the door (${names.length}/${cap})`);
    // Room for all: no question asked.
    Save.startRun();
    const p2 = new Ship('frigate', true, 80, 120);
    b.barracks = [];
    p2.addCrew(new CrewMember({ name: 'Solo' }));
    T.playerShip = p2; T.STATE = 'map';
    let d2 = 0;
    quiet(sb, () => T._dockAtBase(0, () => d2++));
    ok(d2 === 1 && T.STATE !== 'dismiss', 'room for everybody: no screen');
  }

  /* ── 3. AN EVENT SAYS WHAT HAPPENED, AND WAITS ── */
  {
    const sb = loadEngine();
    const { Save, Ship, Game, Renderer } = sb;
    const T = Game.__test;
    const ctx = initRenderer(sb);
    Save.load(); Save.startRun();
    const player = new Ship('frigate', true, 80, 120);
    player._allocateDefaultPower();
    T.playerShip = player;
    T.sectorMap = new sb.SectorMap(1, 4242, Save.getRun().lane ?? 1);
    T.STATE = 'event';
    T.event = { title: 'Odd Signal', text: 'A crate drifts by.', choices: [{ label: 'Haul it in', result: { scrap: 10 } }] };
    quiet(sb, () => T._resolveEvent(0));
    ok(T.STATE === 'map', 'test setup: back on the map');
    let seen = captureStyledText(ctx, () => T._draw()).map(o => o.t);
    ok(seen.includes('Odd Signal') && seen.some(t => /You chose: Haul it in/.test(t)) && seen.includes('+10 CC'),
       `a window: the event, the choice, what came of it (${seen.filter(t => /CC|Odd/.test(t)).join(' | ')})`);
    /* update140: the frame holds the picture of what happened now — credits, with their number */
    ok(!seen.includes('— image —') && seen.includes('+10 CC') && seen.filter(t => t === '+10 CC').length >= 2 && seen.includes('CLOSE [ENTER]'),
       'a picture of the credits coming in, its badge, and a way out');
    const view0 = T._mapView;
    const tog = T._mapToggleRect();
    quiet(sb, () => click(sb, tog.x + 4, tog.y + 4, () => T._updateMap(0.016)));
    ok(T._mapView === view0, 'while it is up, the map takes no clicks');
    quiet(sb, () => press(sb, 'Enter', () => T._updateMap(0.016)));
    seen = captureText(ctx, () => T._draw()).map(o => o.t);
    ok(!seen.includes('CLOSE [ENTER]'), 'ENTER closes it');
    // A choice that leads into a fight shows no window — the fight is the outcome.
    T.STATE = 'event';
    T.event = { title: 'Ambush', text: '…', choices: [{ label: 'Fight', result: { combat: 'normal' } }] };
    quiet(sb, () => T._resolveEvent(0));
    seen = captureText(ctx, () => T._draw()).map(o => o.t);
    ok(T.STATE !== 'map' || !seen.includes('CLOSE [ENTER]'), `into a fight: no window (STATE ${T.STATE})`);
  }
})();

// ============================================================
section('294. jj\'s list from play (107): the suit runs while the crate is open, crates scattered, a dose stops the man, a thawed captive breaks for our ship');
// ============================================================
(function testUpdate107() {
  const quiet = (sb, fn) => { const n = sb.UI.notify; sb.UI.notify = () => {}; try { return fn(); } finally { sb.UI.notify = n; } };
  const seeded = (seed) => () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
  const withSeed = (seed, fn) => { const real = Math.random; Math.random = seeded(seed); try { return fn(); } finally { Math.random = real; } };

  /** A wreck with a full crate, and one of ours out at it with the crate cut. */
  const outAtCrate = (sb) => {
    const { T, player, enemy } = makeCombat(sb);
    enemy.hull = 0;
    quiet(sb, () => { for (let i = 0; i < 30 && !sb.CombatManager.salvage; i++) T._updateCombat(0.05); });
    const S = sb.CombatManager.salvage;
    if (!S) return null;
    let k = S.crates.find(x => x.grid && x.grid.items.length);
    if (!k) { k = S.crates[0]; k.grid = new sb.CargoGrid(3, 3); k.grid.add('ration_pack'); }
    const c = player.crew[0];
    player.crew = player.crew.filter(x => x !== c);
    c.roomId = null; c.inRoom = false; c.race = 'phoenix'; c.air = c.airMax();
    S.men.push({ c, phase: 'open', queue: [k.id], x: k.x, y: k.y, t: 0, hatch: player.doors.find(d => d.isAirlock) });
    return { T, player, S, c, k };
  };

  /* ── 1. THE SUIT RUNS WHILE THE CRATE IS OPEN ── */
  {
    const sb = loadEngine();
    const o = outAtCrate(sb);
    ok(!!o, 'test setup: a man out at a crate');
    if (o) {
      const { T, c } = o;
      quiet(sb, () => T._updateCombat(0.05));
      ok(T.STATE === 'loot', `the crate is open (STATE ${T.STATE})`);
      const air0 = c.air, t0 = sb.LootScreen.secondsLeft();
      ok(t0 !== null && Math.abs(t0 - Math.max(3, air0)) < 0.2, `the window's clock is his bottle (${t0?.toFixed(1)} s of ${air0.toFixed(1)})`);
      quiet(sb, () => { for (let i = 0; i < 40; i++) T._update(0.05); });
      ok(c.air < air0 - 1.5, `two seconds of sorting cost him two seconds of air (${air0.toFixed(1)} → ${c.air.toFixed(1)})`);
      quiet(sb, () => { for (let i = 0; i < 400 && T.STATE === 'loot'; i++) T._update(0.05); });
      ok(T.STATE === 'combat', 'when the bottle runs dry the window shuts');
      ok(c.air <= 0.05 && !c.dead, 'and he is still out there, breathing the void (he has to come in)');
    }
    // Lost at the crate: the window shuts with him.
    const sb2 = loadEngine();
    const o2 = outAtCrate(sb2);
    if (o2) {
      quiet(sb2, () => o2.T._updateCombat(0.05));
      ok(o2.T.STATE === 'loot', 'test setup: open again');
      o2.c.air = 0; o2.c.hp = 0.5;
      quiet(sb2, () => { for (let i = 0; i < 40 && o2.T.STATE === 'loot'; i++) o2.T._update(0.05); });
      ok(o2.c.dead && o2.T.STATE === 'combat', 'the man at the crate dies out there: the window closes');
    }
  }

  /* ── 2. CRATES ARE SCATTERED ── */
  {
    let outside = 0, total = 0, minGapOk = true, onScreen = true, rows = 0;
    for (let k = 0; k < 25; k++) {
      withSeed(500 + k, () => {
        const sb = loadEngine();
        const { T, enemy } = makeCombat(sb);
        enemy.hull = 0;
        quiet(sb, () => { for (let i = 0; i < 30 && !sb.CombatManager.salvage; i++) T._updateCombat(0.05); });
        const S = sb.CombatManager.salvage;
        if (!S) return;
        const b = enemy.roomBounds();
        const cs = S.crates;
        cs.forEach((c, i) => {
          total++;
          if (c.y < b.y + b.h * 0.3 || c.y > b.y + b.h * 0.7) outside++;
          if (c.x < 0 || c.x > sb.Renderer.getWidth() || c.y < 110 || c.y > 460) onScreen = false;
          cs.slice(i + 1).forEach(d => { if (Math.hypot(c.x - d.x, c.y - d.y) < 60) minGapOk = false; });
        });
        if (cs.length >= 2) rows++;
      });
    }
    ok(rows > 3, `test setup: fights with several crates (${rows})`);
    ok(outside >= total * 0.4, `crates land above and below the middle band of the hull, not in a row (${outside}/${total})`);
    ok(minGapOk, 'never two on top of each other');
    ok(onScreen, 'and never off the screen or under the HUD');
  }

  /* ── 3. A DOSE STOPS THE MAN, FOR SECONDS ── */
  {
    const sb = loadEngine();
    const { Ship, Save } = sb;
    Save.load(); Save.startRun();
    const sh = new Ship('frigate', true, 80, 120);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const m = sh.crew[0];
    m.hp = m.maxHp - 30;
    sh.cargo.add('medkit', null, 2);
    const r = quiet(sb, () => sh.healCrew(m));
    m._waypoints = [{ x: m.x + 200, y: m.y }]; m.task = sb.TASK.MOVE;     // an order given mid-dose
    ok(r.ok && m._busyAct === 'heal' && Math.abs(m._busyT - Ship.HEAL_SECONDS) < 1e-9 && Ship.HEAL_SECONDS >= 4,
       `a dose takes ${Ship.HEAL_SECONDS} s`);
    const x0 = m.x;
    for (let i = 0; i < 20; i++) m._updateMovement(0.05, sh);
    ok(Math.abs(m.x - x0) < 0.5, 'and he stands still taking it, as he does eating');
    ok(!sh.crewOperating(m.roomId).includes(m), 'off his console while he does');
  }

  /* ── 4. A THAWED CAPTIVE COMES ROUND, BREAKS OUT, RUNS FOR US ── */
  {
    const sb = loadEngine();
    const { T, player } = makeCombat(sb);
    let e = null;
    for (let k = 0; k < 20 && !e; k++) {
      T._spawnEnemy('normal');
      const s = T.enemyShip;
      ['shields', 'cloaking'].forEach(t => {
        const x = s.getSystem(t); if (!x) return;
        const r = s.getRoomById(x.roomId);
        s.systems = s.systems.filter(y => y !== x); if (r) { r.system = null; r.type = 'empty'; }
      });
      if (!s.rooms.some(r => r.type === 'empty')) continue;
      const realR = sb.Math.random; sb.Math.random = () => 0.01;
      let n = 0;
      try { n = T._seatCaptives(); } finally { sb.Math.random = realR; }
      if (n > 0) e = s;
    }
    ok(!!e, 'test setup: a hull with a captive in carbonite');
    if (e) {
      e.weapons = [];
      sb.CombatManager.begin(player, e, 'normal');
      for (let i = 0; i < 60 && !sb.CombatManager.isActive(); i++) sb.CombatManager.update(0.05);
      const cap = e.crew.find(c => c.isPrisoner);
      const bay = e.getSystem('carbonite');
      e.crew = e.crew.filter(c => c.isPrisoner || c.roomId !== bay.roomId);
      bay.damageLevel(bay.level);
      quiet(sb, () => e.update(0.05));
      ok(cap.frozen && cap._meltT > 0, 'the bay goes dark: his slab starts to melt (update127)');
      cap._meltT = sb.Ship.SLAB_MELT_SECONDS;
      quiet(sb, () => e.update(0.05));
      ok(!cap.frozen && cap.isPrisoner && cap._busyAct === 'thaw', 'once it has melted he is out of the slab, coming round');
      // Their AI does not put him to work (the bug jj saw) — even as the only idle body aboard.
      const crew0 = e.crew;
      e.crew = [cap];
      const eng = e.getSystem('engines'); eng.damageLevel(1);
      quiet(sb, () => { for (let i = 0; i < 10; i++) sb.CombatManager.update(0.05); });
      ok(cap.task !== sb.TASK.REPAIR, 'their AI does not send him to repair their engines');
      e.crew = crew0;
      quiet(sb, () => { for (let i = 0; i < (sb.Ship.THAW_SECONDS + 1) * 20; i++) e.update(0.05); });
      ok(cap.isPlayer && !cap.isPrisoner && cap.rescued && cap._escapee, 'then he breaks out — one of ours, on their deck');
      T.boardingParty = null;
      quiet(sb, () => T._updateCombat(0.05));
      const party = T.boardingParty;
      ok(party && party.recall && party.members.some(m => m.c === cap) && party.toShip === player,
         'and runs for our ship the way a recalled boarder goes');
    }
  }
})();

