section('297. 1920×1080, part 2 (110): pixel art drawn crisp (the enemy window was taken out in 111)');
// ============================================================
(function testUpdate110() {
  const sb = loadEngine();
  const { Ship, Renderer, Assets, Save, Commander } = sb;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();

  /* ── 1. PIXEL ART BY NEAREST NEIGHBOUR ── */
  {
    const seen = [];
    const realDraw = ctx.drawImage;
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage = function () { seen.push(ctx.imageSmoothingEnabled); };
    try {
      const anim = new sb.Animation.AnimationInstance([sb.document.createElement('canvas')], 8, true);
      anim.draw(ctx, 10, 10, 24, 24);
      const tile = sb.document.createElement('canvas');
      Assets.tileRect(ctx, tile, 0, 0, 60, 60, 48);
    } finally { ctx.drawImage = realDraw; }
    ok(seen.length >= 2 && seen.every(v => v === false), `every pixel-art blit is nearest-neighbour (${seen.join(',')})`);
    ok(ctx.imageSmoothingEnabled === true, 'and the setting is put back for everything else (icons, text)');
  }
  // A generated sprite through Assets.draw — the sprites exist once Assets.init has run.
  asyncSection('297 Assets.draw', async () => {
    await Assets.init();
    const name = ['ship_player', 'proj_missile'].find(n => Assets.has(n));
    ok(!!name, 'test setup: a generated sprite');
    const seen = [];
    const realDraw = ctx.drawImage;
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage = function () { seen.push(ctx.imageSmoothingEnabled); };
    try { Assets.draw(ctx, name, 0, 0, 30, 30); } finally { ctx.drawImage = realDraw; }
    ok(seen.length === 1 && seen[0] === false && ctx.imageSmoothingEnabled === true,
       `a generated sprite is drawn nearest-neighbour, the setting put back (${seen})`);
  });

})();

// ============================================================
section('298. The bar under the tabs (111, its window replaced by the loadout in 113); the enemy window is gone');
// ============================================================
(function testUpdate111() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, Ship } = sb;
  const ctx = initRenderer(sb);
  Save.reset(); Save.load(); Save.startRun();
  Base.earn(9000);
  for (let i = 0; i < 2; i++) Base.hireRecruit();
  BaseScreen.open();
  BaseScreen._set({ tab: 'HANGAR' });
  const text = captureText(ctx, () => BaseScreen.draw(ctx)).map(o => o.t);
  ok(BaseScreen._zonesFor('loadout').length === 1, 'the bar under the tabs has the LOADOUT button');
  ok(BaseScreen._zonesFor('launch').length === 0, 'and no LAUNCH of its own — the contract starts on the destination screen');
  ok(BaseScreen._zonesFor('mission').length === 0, 'the contract cards are not on the base');
  ok(text.some(t => /^NEXT CONTRACT$/.test(t)) && text.some(t => /Courier Run/.test(t)), 'the bar says what would fly');

  /* ── THE ENEMY WINDOW FROM 110 IS GONE ── */
  ok(typeof Renderer.enemyWindowRect !== 'function' && typeof Renderer.drawEnemyWindow !== 'function',
     'no enemy window in the renderer');
  const e = new Ship('enemy_frigate', false, Ship.ENEMY_STATION.x, Ship.ENEMY_STATION.y);
  e._allocateDefaultPower();
  const p0 = new Ship('frigate', true, 80, 120); p0._allocateDefaultPower();
  const hud = captureText(ctx, () => Renderer.drawHUD({ playerShip: p0, enemyShip: e }));
  const ev = hud.filter(o => o.t === 'EVADE' || o.t === 'EVD');   // EVD in the systems panel (update135)
  ok(ev.some(o => o.x > Renderer.getWidth() * 0.6 && o.y < 80),
     `their readout is back in the top right corner (${ev.map(o => `${Math.round(o.x)},${Math.round(o.y)}`).join(' ')})`);
})();

// ============================================================
section('299. One crew card, one weapon card, one cargo cell (112): the same man, the same gun and the same crate on every screen; a grown warehouse scrolls');
// ============================================================
(function testUpdate112() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, LootScreen, CargoGrid, CargoItem, CrewMember, Ship } = sb;
  const ctx = initRenderer(sb);
  Save.reset(); Save.load(); Save.startRun();
  Base.earn(9000);
  for (let i = 0; i < 4; i++) Base.hireRecruit();
  const crew = Base.crew();
  crew[1].hp = 10; crew[2].virus = true;
  const capRes = Base.promote(crew[0].id);
  ok(capRes.ok && Base.crew().length >= 3, 'test setup: a barracks and a commander');
  ['laser_burst', 'ion_basic'].forEach(k => Base.storeWeapon(k));

  const spy = (name) => {
    const calls = [], real = Renderer[name];
    Renderer[name] = function (...a) { calls.push(a); return real.apply(this, a); };
    return { calls, done: () => { Renderer[name] = real; } };
  };

  /* ── 1. EVERY BASE SCREEN DRAWS THE MAN WITH THE ONE CARD ── */
  {
    const cc = spy('drawCrewCard');
    try {
      BaseScreen.open();
      BaseScreen._set({ tab: 'CREW' }); BaseScreen.draw(ctx);
      const barracks = cc.calls.length;
      /* update155: every man sleeps in his pod; the one card is his file, for whoever is picked */
      ok(barracks === 1 && cc.calls[0][1].id === BaseScreen.bunkSel(), `the barracks: the picked man's file is the one card (${barracks})`);
      ok(cc.calls.every(a => a[4] === 'M'), 'size M');
      cc.calls.length = 0;
      BaseScreen._set({ tab: 'MESS' }); BaseScreen.draw(ctx);
      /* update156: the commander sits at his desk in the office; his card is his file (the dossier, one click) */
      ok(BaseScreen._zonesFor('dossier').some(z => z.arg === capRes.commander.id), 'the mess: the commander at his desk, his file one click away');
      ok(cc.calls.some(a => !a[5]?.commander), 'and the candidates for the chair: the same card');
    } finally { cc.done(); }
  }

  /* ── 2. THE CARD SAYS THE SAME THINGS WHEREVER IT IS ── */
  {
    const vet = new CrewMember({ name: 'Vega' });
    vet.skills.weapons.level = 3; vet.skills.repair.level = 3; vet.skills.engines.level = 2;
    vet.hp = 20; vet.virus = true;
    const drawn = captureText(ctx, () => Renderer.drawCrewCard(ctx, vet.serialise(), 10, 10, 'M', { w: 364, h: 66, skills: true })).map(o => o.t);
    ok(drawn.includes('Vega'), 'his name');
    ok(drawn.some(t => /Staff Sergeant · 8/.test(t)), 'his rank by name and number');
    ok(drawn.includes('WOUNDED') && drawn.includes('VIRUS') && drawn.includes('☣'), 'and what is wrong with him, both things');
    ok(drawn.includes('HP') && drawn.some(t => /^20\/\d+$/.test(t)), 'his HP in figures');
    const cmd = captureText(ctx, () => Renderer.drawCrewCard(ctx, capRes.commander, 10, 10, 'M', { commander: true })).map(o => o.t);
    ok(cmd.some(t => /^CMDR \d+$/.test(t)), 'a commander carries CMDR and his level');
  }

  /* ── 3. THE ROSTER IN A FIGHT AND THE COMMANDER BAR SHOW HIS FACE ── */
  {
    const ship = new Ship('frigate', true, 80, 120); ship._allocateDefaultPower();
    Base.crew().slice(0, 3).forEach(r => ship.addCrew(CrewMember.deserialise(r)));
    /* count portraits: since update124 a man's is his FACE (CrewArt's
       portrait canvas) drawn into the 20 px box */
    let anims = 0;
    const realPC = sb.CrewArt.portraitCanvas;
    sb.CrewArt.portraitCanvas = function (rec) { anims++; return realPC.call(this, rec); };
    try { Renderer.drawHUD({ playerShip: ship }); }
    finally { sb.CrewArt.portraitCanvas = realPC; }
    ok(anims >= 3, `every man on the roster is drawn by his own sprite (${anims} portraits)`);
  }

  /* ── 4. THE ARMOURY: MOUNTS AND RACK ARE THE ONE WEAPON CARD ── */
  {
    const wc = spy('drawWeaponCard');
    try {
      BaseScreen.open(); BaseScreen._set({ tab: 'ARMOURY' }); BaseScreen.draw(ctx);
      const keys = wc.calls.map(a => a[1]);
      /* update157: the gun picked from its crate is the one weapon card; the crates and the
         mounts show each gun by its own icon */
      ok(keys.length === 1 && keys[0] === Base.armoury()[BaseScreen.crateSel()], 'the gun picked from its crate is the weapon card');
      const ic = spy('drawWeaponIcon');
      try { BaseScreen.draw(ctx); } finally { ic.done(); }
      const icons = ic.calls.map(a => a[1]);
      ok(Base.shipWeapons(0).every(g => icons.includes(g.defKey)) && Base.armoury().every(k => icons.includes(k)), 'every fitted gun and every crate shows its gun');
      ok(wc.calls.every(a => a[4] === 'M'), 'all size M');
    } finally { wc.done(); }
    const t = captureText(ctx, () => Renderer.drawWeaponCard(ctx, 'laser_burst', 0, 0, 'M', { w: 400 })).map(o => o.t);
    ok(t.includes(sb.WEAPON_DEFS.laser_burst.label), 'the card names the gun');
    ok(t.some(x => /^LASER/.test(x)), 'and its type');
    ok(t.includes('DMG') && t.includes('CHARGE'), 'and the stat chips the armoury always showed');
  }

  /* ── 5. ONE CELL, WHATEVER THE GRIDS ── */
  {
    const pitch = (which) => {
      const r = LootScreen._gridRect(which);
      // the cell under the window's first pixel, and the first pixel of the next one
      // from the window's left edge to the first pixel of the second column
      let x = r.x; const c0 = LootScreen._cellAt(which, x, r.y + 1);
      while (LootScreen._cellAt(which, x, r.y + 1)?.cx !== c0.cx + 1) x++;
      return x - r.x;
    };
    const sizes = [];
    [[new CargoGrid(8, 6), new CargoGrid(5, 3)], [new CargoGrid(6, 4), new CargoGrid(7, 5)], [new CargoGrid(10, 2), new CargoGrid(4, 4)]]
      .forEach(([a, b]) => { LootScreen.openLoot(a, b, {}); sizes.push(pitch('wreck'), pitch('hold')); });
    LootScreen.openHold(new CargoGrid(5, 3), {}); sizes.push(pitch('hold'));
    ok(new Set(sizes).size === 1, `the cell is the same size on every grid, big or small (${[...new Set(sizes)].join(', ')})`);
    ok(sizes[0] === LootScreen.CELL + LootScreen.GAP, `and it is the one constant (${sizes[0]} = ${LootScreen.CELL}+${LootScreen.GAP})`);
  }

  /* ── 6. A GROWN WAREHOUSE SCROLLS — and clicks land where they look ── */
  {
    const store = new CargoGrid(20, 6), hold = new CargoGrid(5, 3);
    const far = new CargoItem('ration_pack'); store.place(far, 17, 0);
    LootScreen.openLoot(store, hold, {});
    let r = LootScreen._gridRect('wreck');
    ok(r.scrolls && r.vc < 20 && r.vc === LootScreen.VIEW_COLS, `20 columns are seen through a ${r.vc}-column window`);
    ok(r.x >= 0 && r.x + r.w <= 1280 && LootScreen._gridRect('hold').x + LootScreen._gridRect('hold').w <= 1280,
       'both windows fit the screen');
    LootScreen.draw(ctx);
    ok(!!LootScreen._zoneFor('scroll'), 'there is a scroll arrow');
    // The wheel over the window moves it along.
    const P = LootScreen.CELL + LootScreen.GAP;
    sb.Input.mouse.x = r.x + P / 2; sb.Input.mouse.y = r.y + P / 2;
    sb.Input.mouse.scrollDelta = 1;
    for (let i = 0; i < 10; i++) LootScreen.update(0.016);
    sb.Input.mouse.scrollDelta = 0;
    r = LootScreen._gridRect('wreck');
    ok(r.sx === 20 - r.vc, `the wheel scrolls to the far end and stops there (${r.sx})`);
    const c = LootScreen._cellAt('wreck', r.x + P / 2, r.y + P / 2);
    ok(c && c.cx === r.sx && c.cy === 0, `the cell under the cursor is the scrolled one (${c?.cx})`);
    // Pick up the far crate through the scrolled window and put it down one cell left.
    const at = (cx, cy) => ({ x: r.x + (cx - r.sx) * P + P / 2, y: r.y + (cy - r.sy) * P + P / 2 });
    const click = (pt) => {
      sb.Input.mouse.x = pt.x; sb.Input.mouse.y = pt.y; sb.Input.mouse.leftPressed = true;
      LootScreen.update(0.5); sb.Input.mouse.leftPressed = false; LootScreen.update(0.5);
    };
    click(at(17, 0));
    ok(!store.items.includes(far), 'the crate far out on the shelf can be picked up');
    click(at(16, 2));
    ok(store.items.includes(far) && far.x === 16 && far.y === 2, `and it lands on the cell it was put on (${far.x},${far.y})`);
    // a carried crate survives a scroll
    click(at(16, 2));
    sb.Input.mouse.x = r.x + P / 2; sb.Input.mouse.y = r.y + P / 2; sb.Input.mouse.scrollDelta = -1;
    LootScreen.update(0.016); sb.Input.mouse.scrollDelta = 0;
    LootScreen.draw(ctx);
    const z = LootScreen._zoneFor('scroll');
    if (z) { sb.Input.mouse.x = z.x + 2; sb.Input.mouse.y = z.y + 2; sb.Input.mouse.leftPressed = true; LootScreen.update(0.016); sb.Input.mouse.leftPressed = false; }
    ok(!store.items.includes(far) && !hold.items.includes(far), 'scrolling with a crate in hand keeps it in the hand');
    LootScreen.forceClose();
    ok(store.items.includes(far) || hold.items.includes(far), 'and closing puts it down — nothing lost');
  }

  /* ── 7. A CRATE SHOWS WHAT IS IN IT; THE DETAIL SHOWS THE GUN'S CARD ── */
  {
    const store = new CargoGrid(8, 6), hold = new CargoGrid(5, 3);
    const gun = new CargoItem('gun_crate', 'ion_basic'); store.place(gun, 0, 0);
    store.add('medkit');
    LootScreen.openLoot(store, hold, {});
    const icons = spy('drawWeaponIcon'), picts = spy('drawCargoPict');
    try { LootScreen.draw(ctx); }
    finally { icons.done(); picts.done(); }
    ok(icons.calls.some(a => a[1] === 'ion_basic'), 'the gun crate draws the ion cannon inside it');
    ok(picts.calls.some(a => a[1] === 'heal'), 'the medkit draws its cross');
    // pick the gun up — the detail panel shows its weapon card
    const r = LootScreen._gridRect('wreck'), P = LootScreen.CELL + LootScreen.GAP;
    sb.Input.mouse.x = r.x + P / 2; sb.Input.mouse.y = r.y + P / 2; sb.Input.mouse.leftPressed = true;
    LootScreen.update(0.5); sb.Input.mouse.leftPressed = false;
    const wc = spy('drawWeaponCard');
    try { LootScreen.draw(ctx); } finally { wc.done(); }
    ok(wc.calls.some(a => a[1] === 'ion_basic'), 'and the detail panel draws the gun\'s weapon card');
    LootScreen.forceClose();
  }
})();

// ============================================================
section('300. The loadout and the destination (113): shelf, ship and hold side by side, everything dragged; a man posted on a room; the moon, then the contract');
// ============================================================
(function testUpdate113() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, LootScreen, CargoItem, Ship, CrewMember } = sb;
  const ctx = initRenderer(sb);
  const T = sb.Game.__test;
  Save.reset(); Save.load(); Save.startRun();
  Base.earn(9000);
  for (let i = 0; i < 4; i++) Base.hireRecruit();
  const capRes = Base.promote(Base.crew()[0].id);
  Base.adoptCat();
  Base.buySupply('fuel', 10); Base.buySupply('missiles', 8);
  ['laser_burst', 'ion_basic'].forEach(k => Base.storeWeapon(k));
  ok(capRes.ok && Base.crew().length >= 3 && Base.armoury().length >= 2, 'test setup: crew, a commander, guns on the shelf');

  const M = sb.Input.mouse;
  const frame = () => { BaseScreen.draw(ctx); };
  const press = (x, y) => { M.x = x; M.y = y; M.leftPressed = true; const r = BaseScreen.update(0.05); M.leftPressed = false; frame(); return r; };
  const release = (x, y) => { M.x = x; M.y = y; M.leftReleased = true; const r = BaseScreen.update(0.05); M.leftReleased = false; frame(); return r; };
  const click = (x, y) => { const r = press(x, y); release(x, y); return r; };
  const wait = () => { BaseScreen.update(0.5); };                   // let a double-click window pass
  const key = (code) => { const real = sb.Input.isPressed; sb.Input.isPressed = (c) => c === code;
    try { return BaseScreen.update(0.05); } finally { sb.Input.isPressed = real; frame(); } };
  const P = LootScreen.CELL + LootScreen.GAP;

  BaseScreen.open();
  frame();
  /* ── 1. OPENED FROM THE BAR, OR WITH ENTER ── */
  key('Enter');
  ok(BaseScreen._state().loadout, 'ENTER on the base opens the loadout');
  key('Escape');
  ok(!BaseScreen._state().loadout, 'ESCAPE closes it');
  const z0 = BaseScreen._zonesFor('loadout')[0];
  click(z0.x + 5, z0.y + 5);
  ok(BaseScreen._state().loadout, 'the bar\'s LOADOUT button opens it');
  ok(BaseScreen._zonesFor('tab').length === 0 && BaseScreen._zonesFor('town').length === 0, 'nothing of the base can be pressed under it');
  ok(BaseScreen._zonesFor('loFilter').length === 7, 'the shelf has its seven filters');
  const R = BaseScreen.loadoutRects();

  const shelf = () => BaseScreen.liveShelf(), hold = () => BaseScreen._state().hold;
  const cellXY = (r, view, cx, cy) => ({ x: r.x + (cx - view.sx) * P + P / 2, y: r.y + (cy - view.sy) * P + P / 2 });
  const sv = () => ({ sx: BaseScreen._state().shelfView.x, sy: BaseScreen._state().shelfView.y });
  const hv = { sx: 0, sy: 0 };
  const total = (k) => shelf().countOf(k) + hold().countOf(k);

  /* ── 2. A CRATE: CLICK TO TAKE, CLICK TO PUT ── */
  {
    const fuel0 = total('fuel');
    const tank = shelf().items.find(it => it.def.kind === 'fuel');
    ok(!!tank, 'test setup: He2 on the shelf');
    const a = cellXY(R.shelf, sv(), tank.x, tank.y);
    click(a.x, a.y);
    ok(BaseScreen._state().hand?.kind === 'cargo' && BaseScreen._state().hand.item === tank, 'a click takes the crate into the hand');
    ok(!shelf().items.includes(tank), 'and it has left the shelf');
    wait();
    const b = cellXY(R.hold, hv, 0, 0);
    click(b.x, b.y);
    ok(hold().items.includes(tank) && tank.x === 0 && tank.y === 0, 'a second click puts it on the cell under the cursor');
    ok(total('fuel') === fuel0, 'nothing made, nothing lost');
    ok(Base.packedHold().countOf('fuel') === hold().countOf('fuel'), 'and the packed hold is saved on the spot');
    // a HELD drag does the same — onto a free spot of the shelf
    const spot = (() => { const g = shelf(); for (let y = g.rows - 1; y >= 0; y--) for (let x = g.cols - 1; x >= 0; x--)
      if (g.fits(tank, x, y)) return { x, y }; return null; })();
    wait();
    const c = cellXY(R.hold, hv, 0, 0);
    press(c.x, c.y);
    const d = cellXY(R.shelf, sv(), spot.x, spot.y);
    release(d.x, d.y);
    ok(shelf().items.includes(tank) && tank.x === spot.x && tank.y === spot.y, `a held drag drops it where the button came up (${tank.x},${tank.y})`);
    // double-click sends it across
    wait();
    const e = cellXY(R.shelf, sv(), spot.x, spot.y);
    click(e.x, e.y); click(e.x, e.y);
    ok(hold().items.includes(tank) && !BaseScreen._state().hand, 'a double-click sends it to the other side');
    // right-click puts it back
    wait();
    const f = cellXY(R.hold, hv, tank.x, tank.y);
    click(f.x, f.y);
    M.rightPressed = true; BaseScreen.update(0.05); M.rightPressed = false;
    ok(hold().items.includes(tank) && !BaseScreen._state().hand, 'a right-click puts it back where it was');
    // a full hold refuses, and the crate stays in the hand — never dropped
    const filler = [];
    for (let k = 0; k < 99; k++) { const it = hold().add('ration_pack'); if (!it) break; filler.push(it); }
    const msl = shelf().items.find(it => it.def.kind === 'missiles');
    wait();
    const g = cellXY(R.shelf, sv(), msl.x, msl.y);
    click(g.x, g.y);
    wait();
    click(R.hold.x + 4, R.hold.y + 4);
    ok(BaseScreen._state().hand?.item === msl, 'a crate that fits nowhere stays in the hand');
    key('Escape');
    ok(shelf().items.includes(msl) && BaseScreen._state().loadout, 'ESCAPE with something in the hand puts it back — and keeps the screen open');
    filler.forEach(it => hold().remove(it)); BaseScreen.commitPack();
  }

  /* ── 3. THE FILTER GREYS, IT NEVER MOVES ── */
  {
    const before = shelf().items.map(it => `${it.id}@${it.x},${it.y}`).join('|');
    const zf = BaseScreen._zonesFor('loFilter').find(z => z.arg === 'GUNS');
    click(zf.x + 2, zf.y + 2);
    ok(BaseScreen._state().filter === 'GUNS', 'GUNS filter on');
    ok(shelf().items.map(it => `${it.id}@${it.x},${it.y}`).join('|') === before, 'nothing on the shelf moved');
    const zA = BaseScreen._zonesFor('loFilter').find(z => z.arg === 'ALL'); click(zA.x + 2, zA.y + 2);
  }

  /* ── 4. GUNS: RACK → MOUNT, MOUNT → RACK, A SWAP ── */
  {
    const slots = Base.shipSlotCount(0);
    ok(slots >= 1 && R.mounts.length === slots, `a mount box per mount (${R.mounts.length})`);
    const m0 = R.mounts[0];
    const was = Base.shipWeapons(0).find(f => f.slot === 0)?.defKey;
    const rack0 = Base.armoury().length;
    const want = Base.armoury()[0];
    wait();
    click(R.rack.x + 100, R.rack.y + 30);
    ok(BaseScreen._state().hand?.kind === 'gun' && BaseScreen._state().hand.key === want, 'a click on a rack card takes the gun');
    wait();
    click(m0.x + 10, m0.y + 10);
    ok(Base.shipWeapons(0).find(f => f.slot === 0)?.defKey === want, 'dropped on mount 1 it is fitted to mount 1');
    ok(!was || Base.armoury().includes(was), 'the gun that was there went onto the shelf, not into the void');
    ok(Base.armoury().length === rack0 - (was ? 0 : 1), `the rack count adds up (${rack0} → ${Base.armoury().length})`);
    wait();
    click(m0.x + 10, m0.y + 10);
    ok(BaseScreen._state().hand?.from === 'mount', 'a fitted gun can be taken off its mount');
    wait();
    click(R.rackPanel.x + 40, R.rackPanel.y + 40);
    ok(!Base.shipWeapons(0).some(f => f.slot === 0) && Base.armoury().includes(want), 'dropped on the rack it comes off onto the shelf');
    // double-click on the rack fits it to the first free mount
    wait();
    const vi = Base.armoury().indexOf(want);
    click(R.rack.x + 100, R.rack.y + vi * R.rack.pitch + 30); click(R.rack.x + 100, R.rack.y + vi * R.rack.pitch + 30);
    ok(Base.shipWeapons(0).some(f => f.defKey === want), 'a double-click on a rack card fits it');

    /* update128 (jj): "przenieś broń na slot na statku, na dachu" — the roof
       of the ship in the picture takes a gun too. Off it first, then onto
       the roof (not on a gun: the first free mount), then picked back up
       off the roof. */
    const slotOf = () => Base.shipWeapons(0).find(f => f.defKey === want)?.slot;
    const s0 = slotOf();
    const mz = R.mounts.find(z => z.slot === s0);
    wait(); click(mz.x + 10, mz.y + 10); wait(); click(R.rackPanel.x + 40, R.rackPanel.y + 40);
    ok(!Base.shipWeapons(0).some(f => f.defKey === want && f.slot === s0), 'test setup: the gun is back on the rack');
    frame();
    const roof = BaseScreen.loadoutRoof();
    ok(!!roof?.band, 'the picture has a roof to drop on');
    const freeBefore = R.mounts.filter(z => !Base.shipWeapons(0).some(f => f.slot === z.slot)).map(z => z.slot);
    const vi2 = Base.armoury().indexOf(want);
    wait(); click(R.rack.x + 100, R.rack.y + vi2 * R.rack.pitch + 30);
    // a spot on the roof clear of every fitted gun
    const guns = roof.ship.weaponMounts();
    let px = roof.band.x + 4;
    while (px < roof.band.x + roof.band.w && guns.some(m => px >= m.x - 4 && px <= m.x + m.w + 4)) px += 6;
    wait(); click(px, roof.band.y + 6);
    ok(Base.shipWeapons(0).some(f => f.defKey === want && f.slot === freeBefore[0]),
       `dropped on the ship's roof, the gun is fitted to the first free mount (${freeBefore[0]} → ${slotOf()})`);
    frame();
    const onRoof = BaseScreen.loadoutRoof().ship.weaponMounts().find(m => m.weapon.defKey === want);
    ok(!!onRoof, 'and it stands on her roof in the picture');
    wait(); click(onRoof.x + onRoof.w / 2, onRoof.y + onRoof.h / 2);
    ok(BaseScreen._state().hand?.from === 'mount' && BaseScreen._state().hand.key === want,
       'a gun on the roof can be picked up off it');
    wait(); click(R.rackPanel.x + 40, R.rackPanel.y + 40);
  }

  /* ── 5. PEOPLE: BARRACKS ⇄ DECK, AND A MAN POSTED ON A ROOM ── */
  {
    BaseScreen._set({ picked: [] });
    frame();
    const man = Base.crew()[0];
    // he is the first card in STAYING HOME
    wait();
    click(R.barr.x + 30, R.barr.y + 20);
    ok(BaseScreen._state().hand?.kind === 'crew' && BaseScreen._state().hand.id === man.id, 'a click on a man staying home takes him');
    wait();
    click(R.deckPanel.x + 300, R.deckPanel.y + 150);
    ok(BaseScreen._state().picked.includes(man.id), 'dropped on the deck he is aboard');
    // onto a room of the hull: aboard AND posted there
    const other = Base.crew()[1];
    wait();
    click(R.barr.x + 30, R.barr.y + 20);
    ok(BaseScreen._state().hand?.id === other.id, 'the next man staying home');
    const sh = BaseScreen.loadoutShip();
    ok(!!sh, 'the stage has the hull');
    const room = sh.rooms.find(r => sh.systems.some(s2 => s2.roomId === r.id && s2.type === 'engines')) || sh.rooms[0];
    wait();
    click(room.x + room.w / 2, room.y + room.h / 2);
    ok(BaseScreen._state().picked.includes(other.id) && BaseScreen._state().posts[other.id] === room.id,
       'dropped on a room he is aboard and POSTED there');
    frame();
    const sh2 = BaseScreen.loadoutShip();
    const him = sh2.crew.find(c => c.id === other.id);
    ok(him && him.homeRoomId === room.id, 'the hull on the stage shows him at that post');
    // the deck card says so
    const deckText = captureText(ctx, () => BaseScreen.draw(ctx)).map(o => o.t);
    ok(deckText.some(t => /^◆ /.test(t)), 'his card on the deck is marked as posted by the player');
    // commander: seat from STAYING HOME, unseat by clicking the slot
    BaseScreen._set({ commanderId: null });
    frame();
    const list = captureText(ctx, () => BaseScreen.draw(ctx)).filter(o => o.t === capRes.commander.name);
    ok(list.length > 0, 'the commander at home is listed under STAYING HOME');
    // find his card in STAYING HOME: scroll is 0; cards after the hands
    let seated = false;
    for (let i = 0; i < R.barr.vis && !seated; i++) {
      wait();
      M.x = R.barr.x + 30; M.y = R.barr.y + i * R.barr.pitch + 20;
      M.leftPressed = true; BaseScreen.update(0.05); M.leftPressed = false; frame();
      if (BaseScreen._state().commanderId === capRes.commander.id) seated = true;
      else if (BaseScreen._state().hand) key('Escape');
    }
    ok(seated, 'a click on a commander staying home puts him in the chair');
    wait();
    click(R.cmdSlot.x + 20, R.cmdSlot.y + 20);
    ok(BaseScreen._state().commanderId === null, 'a click on the chair sends him back to the mess');
    BaseScreen._set({ commanderId: capRes.commander.id });
    // animal: the slot cycles
    wait();
    click(R.petSlot.x + 20, R.petSlot.y + 20);
    ok(BaseScreen._state().petId === Base.pets()[0].id, 'a click on the animal slot takes the cat');
    wait();
    click(R.petSlot.x + 20, R.petSlot.y + 20);
    ok(BaseScreen._state().petId === null, 'another click leaves her home');
    // a posted man flies to his post — and RETURN knows it
    const posts = BaseScreen._state().posts;
    ok(Object.keys(posts).length === 1, 'test setup: one man posted');
  }

  /* ── 6. START CONTRACT → THE DESTINATION ── */
  {
    key('Enter');
    ok(BaseScreen._state().dest, 'ENTER (START CONTRACT) opens the destination');
    const D = BaseScreen.destRects();
    const open = Base.missions().filter(m => !sb.missionRefusal(m));
    ok(BaseScreen._zonesFor('mission').length === open.length, `every open contract of Luna is a card (${open.length})`);
    ok(BaseScreen._zonesFor('launch').length === 1, 'LAUNCH is live on Luna');
    // a locked moon: no contracts, no launch
    const eu = D.moons.find(m => m.key === 'europa');
    click(eu.x + eu.w / 2, eu.y + eu.h / 2);
    ok(BaseScreen._state().destMoon === 'europa', 'Europa can be looked at');
    ok(BaseScreen._zonesFor('mission').length === 0 && BaseScreen._zonesFor('launch').length === 0,
       'but it is locked: no contracts, no LAUNCH');
    const lu = D.moons.find(m => m.key === 'luna');
    click(lu.x + lu.w / 2, lu.y + lu.h / 2);
    const pz = BaseScreen._zonesFor('mission').find(z => z.arg === 'patrol');
    click(pz.x + 10, pz.y + 10);
    ok(BaseScreen._state().mission === 'patrol', 'a card picks the contract');
    key('Escape');
    ok(BaseScreen._state().loadout, 'ESCAPE goes back to the loadout, not to the base');
    key('Enter');
    const picked = BaseScreen._state().picked.slice(), posts = BaseScreen._state().posts;
    const postedId = Object.keys(posts)[0], postedRoom = posts[postedId];
    const r = key('Enter');
    ok(r === 'launch', 'ENTER on the destination launches');
    const L = BaseScreen.consumeLaunch();
    ok(!!L && L.mission.id === 'patrol', 'the contract picked under the moon flies');
    ok(L.crew.length === picked.length, 'the people put aboard fly');
    ok(L.posts && L.posts[postedId] === postedRoom, 'and the post goes with the loadout');
    T._startContract(L);
    const ship = T.playerShip;
    const man = ship.crew.find(c => String(c.id) === String(postedId));
    ok(man && man.homeRoomId === postedRoom, 'aboard, he is at the post he was given');
    // RETURN sends him back there: the posts are the saved stations from the start
    const elsewhere = ship.rooms.find(rm => rm.id !== postedRoom);
    man.homeRoomId = elsewhere.id;
    T._returnToStations();
    ok(man.homeRoomId === postedRoom, 'RETURN sends him back to it — the posts are the saved stations');
  }

  /* ── 8. A LONG BLURB AND A LONG REASON STILL FIT THE CARD ──
     The destination cards are wide, so today's words fit in a line or
     two — the caps on the wrap only show with longer ones. Lengthen
     both and measure: the blurb stops two lines down, a clear line above
     the bonus, and the whole refusal is there, word for word. */
  {
    const m = sb.MISSIONS.courier, blurb0 = m.blurb;
    const refuse0 = sb.missionRefusal;
    m.blurb = 'One sector, no boss, and a very long account of it that goes on and on about the route, '
            + 'the cargo, the weather in the lanes and the people who will be waiting at the far end of it all.';
    const why = 'They will not hand their people to a commander with your name, not this month, not after what '
              + 'happened at the relief station, and not while the board is still counting the dead.';
    sb.missionRefusal = (mm, k) => (mm.id === 'patrol' ? why : refuse0(mm, k));
    try {
      BaseScreen.open(); BaseScreen._set({ screen: 'dest' });
      const marks = captureText(ctx, () => BaseScreen.draw(ctx));
      const card = BaseScreen.destRects().cards.find(c => c.id === 'courier');
      const bonus = marks.find(d => /bonus \d+ CC/.test(d.t) && d.y > card.y && d.y < card.y + card.h);
      const blurb = marks.filter(d => d.x === card.x + 14 && d.y > card.y + 22 && bonus && d.y < bonus.y);
      ok(blurb.length > 0 && blurb.length <= 2, `a long blurb is capped at two lines (${blurb.length})`);
      ok(bonus && blurb.every(d => bonus.y - d.y >= 13), 'and stops a clear line above the bonus');
      const joined = marks.map(d => d.t).join(' ');
      const missing = why.replace(/[.,]/g, '').split(/\s+/).filter(w => w.length > 2 && !joined.includes(w));
      ok(missing.length === 0, `a long refusal is on the card word for word (missing: ${missing.join(' ') || 'nothing'})`);
    } finally { m.blurb = blurb0; sb.missionRefusal = refuse0; }
  }

  /* ── 7. Ship.applyPosts: a full room takes what fits, nobody is left nowhere ── */
  {
    const sh = new Ship('frigate', true, 80, 120); sh._allocateDefaultPower();
    const men = [0, 1, 2, 3, 4].map(i => new CrewMember({ name: 'P' + i }));
    men.forEach(c => sh.addCrew(c));
    sh.assignStations();
    const room = sh.rooms[0];
    const posts = Object.fromEntries(men.map(c => [c.id, room.id]));
    const n = sh.applyPosts(posts);
    ok(n <= Ship.ROOM_SLOTS, `no more than ${Ship.ROOM_SLOTS} are posted into one room (${n})`);
    ok(men.every(c => c.homeRoomId), 'and everyone still has a post');
  }
})();

// ============================================================
section('301. The solar system as it really stands (114): every planet and Pluto, the Martian moons, positions for today');
// ============================================================
(function testUpdate114() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen } = sb;
  const ctx = initRenderer(sb);
  Save.reset(); Save.load(); Save.startRun();
  const O = (d) => BaseScreen.orreryLayout(new Date(d));
  const sep = (a, b) => { const x = Math.abs(((a - b) % 360 + 360) % 360); return Math.min(x, 360 - x); };

  /* ── 1. THE NUMBERS ARE THE SKY ── */
  ok(BaseScreen.ORRERY_PLANETS.map(p => p.key).join(',') === 'mercury,venus,earth,mars,jupiter,saturn,uranus,neptune,pluto',
     'all eight planets and Pluto, in order from the Sun');
  {
    const L = O(Date.UTC(2000, 0, 1, 12));
    ok(sep(L.planets.earth.lon, 100.4) < 1.5, `Earth at J2000 (${L.planets.earth.lon.toFixed(1)}°)`);
    const T = O(Date.UTC(2026, 9, 11, 12));
    const sun = (T.planets.earth.lon + 180) % 360;
    ok(sep(sun, 198.2) < 1.5, `the Sun seen from Earth on 11 Oct 2026 (${sun.toFixed(1)}°, almanac 198°)`);
    // oppositions: Earth between the Sun and the planet, same heliocentric longitude
    [['jupiter', Date.UTC(2026, 0, 10)], ['saturn', Date.UTC(2026, 9, 4)], ['mars', Date.UTC(2027, 1, 19)]].forEach(([k, d]) => {
      const A = O(d);
      ok(sep(A.planets.earth.lon, A.planets[k].lon) < 3,
         `${k} is at opposition when the almanac says (${sep(A.planets.earth.lon, A.planets[k].lon).toFixed(1)}° apart)`);
    });
    // new moon on 10 Oct 2026, 15:50 UTC: the Moon in front of the Sun
    const N = O(Date.UTC(2026, 9, 10, 15, 50));
    const sunN = (N.planets.earth.lon + 180) % 360;
    ok(sep(N.moons.luna.ang, sunN) < 8, `at new moon Luna sits on the Sun's line (${sep(N.moons.luna.ang, sunN).toFixed(1)}°)`);
    /* THE SEASONS, to the hour — the Sun crosses 0°, 90°, 180°, 270° at
       the 2026 equinoxes and solstices. Earth's orbit is nearly round, so
       only a real Kepler solution lands every one of them inside 0.6°;
       taking the mean anomaly for the eccentric one misses March by 1.3°. */
    [[Date.UTC(2026, 2, 20, 14, 46), 0], [Date.UTC(2026, 5, 21, 8, 24), 90],
     [Date.UTC(2026, 8, 23, 0, 5), 180], [Date.UTC(2026, 11, 21, 20, 50), 270]].forEach(([d, want]) => {
      const sunAt = (O(d).planets.earth.lon + 180) % 360;
      ok(sep(sunAt, want) < 0.6, `the Sun at ${want}° on ${new Date(d).toISOString().slice(0, 10)} (${sunAt.toFixed(2)}°)`);
    });
    // things move, the near ones fastest
    const A = O(Date.UTC(2026, 0, 1)), B = O(Date.UTC(2026, 1, 1));
    ok(sep(A.planets.mercury.lon, B.planets.mercury.lon) > sep(A.planets.pluto.lon, B.planets.pluto.lon) * 20,
       'a month moves Mercury far, Pluto hardly at all');
    ok(sep(A.moons.io.ang, B.moons.io.ang) > 0, 'the moons go round too');
  }

  /* ── 2. THE MARTIAN MOONS ARE PLACES — shut, like every moon past Luna ── */
  {
    const R = Save.regions();
    ['phobos', 'deimos'].forEach(k => {
      ok(R[k] && R[k].body === 'Mars' && R[k].locked && !Save.regionUnlocked(k), `${k.toUpperCase()} is on the list, at Mars, locked`);
      ok(BaseScreen.ORRERY_MOONS.some(m => m.key === k && m.planet === 'mars'), `and on the map, round Mars`);
    });
    ok(BaseScreen.ORRERY_MOONS.every(m => R[m.key]), 'every moon on the map is a place the save knows');
  }

  /* ── 3. THE SCREEN: today's positions, a click on a moon, the distance ── */
  {
    const d = Date.UTC(2026, 9, 11, 12);
    BaseScreen.open();
    BaseScreen._set({ screen: 'dest', orreryDate: d });
    const text = captureText(ctx, () => BaseScreen.draw(ctx)).map(o => o.t);
    ok(text.some(t => /11 OCT 2026/.test(t)), 'the map says which day it shows');
    const L = O(d), D = BaseScreen.destRects();
    const ph = D.moons.find(m => m.key === 'phobos');
    ok(Math.abs(ph.x + ph.w / 2 - L.moons.phobos.sx) < 1 && Math.abs(ph.y + ph.h / 2 - L.moons.phobos.sy) < 1,
       'the place to click Phobos is where Phobos is drawn today');
    BaseScreen._act('destMoon', 'phobos');
    const t2 = captureText(ctx, () => BaseScreen.draw(ctx)).map(o => o.t).join('|');
    const au = Math.hypot(L.planets.mars.x - L.planets.earth.x, L.planets.mars.y - L.planets.earth.y);
    ok(t2.includes(`${au.toFixed(2)} AU`), `its panel gives today's distance from Earth (${au.toFixed(2)} AU)`);
    ok(BaseScreen._zonesFor('launch').length === 0, 'and it cannot be launched to');
    BaseScreen._act('destMoon', 'luna');
    const t3 = captureText(ctx, () => BaseScreen.draw(ctx)).map(o => o.t).join('|');
    ok(/384 400 km/.test(t3) && BaseScreen._zonesFor('launch').length === 1, 'Luna: 384 400 km, and LAUNCH');
  }

  /* ── 4. THE LABELS NEVER LAND ON EACH OTHER, WHATEVER THE DAY ──
     The planets move, so a fixed layout cannot be trusted: two years of
     dates, every body labelled exactly once, no two labels overlapping. */
  {
    const names = new Set([...BaseScreen.ORRERY_PLANETS.map(p => p.label),
                           ...BaseScreen.ORRERY_MOONS.map(m => Save.regions()[m.key].label)]);
    const bad = [];
    /* 24 months from 2026 — and two crowded days found by sweeping fifteen
       years, where a label only fits further out on its hair-line. */
    const days = Array.from({ length: 24 }, (_, k) => Date.UTC(2026, 0, 1) + k * 31 * 86400000)
      .concat([Date.UTC(2031, 5, 24), Date.UTC(2039, 4, 26)]);
    for (const d of days) {
      BaseScreen._set({ screen: 'dest', orreryDate: d });
      const runs = [];
      const real = ctx.fillText;
      ctx.fillText = function (t, x, y) {
        const s = String(t);
        if (!names.has(s) || x > 800) return;          // the map's labels only
        const w = (ctx.measureText && ctx.measureText(s).width) || s.length * 6;
        const x0 = ctx.textAlign === 'center' ? x - w / 2 : ctx.textAlign === 'right' ? x - w : x;
        runs.push({ t: s, x0, y, w });
      };
      try { BaseScreen.draw(ctx); } finally { ctx.fillText = real; }
      const seen = new Set(runs.map(r => r.t));
      if (seen.size !== names.size) bad.push(`${new Date(d).toISOString().slice(0, 10)}: ${names.size - seen.size} unlabelled`);
      for (let i = 0; i < runs.length; i++) for (let j = i + 1; j < runs.length; j++) {
        const a = runs[i], c = runs[j];
        if (Math.abs(a.y - c.y) > 9) continue;
        if (Math.min(a.x0 + a.w, c.x0 + c.w) - Math.max(a.x0, c.x0) > 1) bad.push(`${new Date(d).toISOString().slice(0, 10)}: ${a.t}×${c.t}`);
      }
    }
    ok(!bad.length, `every body labelled once and no labels overlap, on ${days.length} dates (${bad.slice(0, 4).join('; ')})`);
    BaseScreen._set({ orreryDate: null });
  }
})();

// ============================================================
section('302. Five tabs, not nine (115): SHIP, CREW, STORES, BASE, ARCHIVE — every screen still one click away, each group remembers its screen');
// ============================================================
(function testUpdate115() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen } = sb;
  const ctx = initRenderer(sb);
  Save.reset(); Save.load();
  Base.earn(2000); Base.hireRecruit(); Base.adoptCat();
  BaseScreen.open();
  BaseScreen.draw(ctx);
  /* update149: the base opens on the TOWN; the tabs are behind its doors */
  ok(BaseScreen._state().town && BaseScreen._zonesFor('tabGroup').length === 0, 'the base opens on the town, no tab bar');
  BaseScreen._act('building', 'HANGAR');
  BaseScreen.draw(ctx);

  /* update152: no tab bar at all — each building is its own room */
  ok(BaseScreen._zonesFor('tabGroup').length === 0 && BaseScreen._zonesFor('tab').length === 0, 'inside a building: no tab bar');
  ok(BaseScreen._state().tab === 'HANGAR', 'and the hangar\'s door opens the hangar');

  /* EVERY SCREEN: BY ITS DOOR IN THE TOWN, AND BY ITS NUMBER FROM INSIDE ANY OTHER */
  /* update154: the WORKSHOP is closed — eight doors, eight numbers */
  const all = ['HANGAR', 'ARMOURY', 'CREW', 'MESS', 'SUPPLY', 'MEMORIAL', 'WANTED', 'GATE'];
  const byDoor = [], byKey = [];
  const keyN = (n) => { const real = sb.Input.isPressed; sb.Input.isPressed = (c) => c === `Digit${n}`; try { BaseScreen.update(0.016); } finally { sb.Input.isPressed = real; } };
  all.forEach(t => {
    BaseScreen._act('town'); BaseScreen.draw(ctx);
    const z = BaseScreen._zonesFor('building').find(q => q.arg === t);
    if (z) BaseScreen._act('building', z.arg);
    if (BaseScreen._state().tab === t && !BaseScreen._state().town) byDoor.push(t);
  });
  ok(byDoor.length === all.length, `all eight open buildings through their doors (${byDoor.join(',')})`);
  const B = sb.TownView.BUILDINGS;
  all.forEach((t, i) => {
    BaseScreen._set({ tab: all[(i + 1) % all.length] }); BaseScreen.draw(ctx);
    keyN(B.find(q => q.tab === t).n);
    if (BaseScreen._state().tab === t && !BaseScreen._state().town) byKey.push(t);
  });
  ok(byKey.length === all.length, `and from inside any other, by its number (${byKey.join(',')})`);
  BaseScreen.open();
  const text = captureText(ctx, () => { BaseScreen._act('building', 'CREW'); BaseScreen.draw(ctx); }).map(o => o.t);
  ok(text.includes('BARRACKS') && BaseScreen._state().tab === 'CREW', 'CREW is the barracks, and the room calls itself BARRACKS');
  BaseScreen.open();
  ok(BaseScreen._state().tab === 'HANGAR', 'a new visit to the base starts on the hangar again');

  /* THE PEN'S SENTENCE STAYS IN ITS COLUMN (found looking at the mess) */
  BaseScreen._set({ tab: 'MESS' });
  const runs = [];
  const real = ctx.fillText;
  ctx.fillText = function (t, x, y) {
    const s = String(t);
    if (/animal per hull|hunts vermin|with the wounded/.test(s)) runs.push({ x, w: ctx.measureText(s).width });
  };
  try { BaseScreen.draw(ctx); } finally { ctx.fillText = real; }
  /* update156: the pen is a room of its own; its sentence stays inside it, right-aligned in its title row */
  const PEN = BaseScreen.messRects().pen;
  ok(runs.length > 0 && runs.every(r => r.x <= PEN.x + PEN.w && r.x - r.w >= PEN.x), `the pen's sentence stays inside the pen (${runs.map(r => Math.round(r.x)).join(',')})`);
})();

// ============================================================
section('303. The hull as a picture (116): every hull painted to its own geometry, drawn when it fits, the plate in code when it does not');
// ============================================================
(function testUpdate116() {
  const fs = require('fs'), path = require('path');
  const ROOT = path.join(__dirname, '..');
  const sb = loadEngine();
  const { Ship, SHIP_LAYOUTS, HULL_GRID, HULL_ART, hullArtGeometry, Assets, Renderer } = sb;
  const ctx = initRenderer(sb);
  const T = HULL_GRID.TILE, M = HULL_GRID.MARGIN;
  const inside = (r, box) => r.x >= box.x && r.y >= box.y && r.x + r.w <= box.x + box.w && r.y + r.h <= box.y + box.h;
  const geomOf = (key, isPlayer) => {
    const L = SHIP_LAYOUTS[key];
    return hullArtGeometry(L.rooms, (L.elevators ?? []).map(e => e.x), isPlayer, !!L.isStation);
  };
  const keys = Object.keys(SHIP_LAYOUTS);
  ok(typeof hullArtGeometry === 'function' && HULL_ART && HULL_ART.PAD_BOW === HULL_GRID.PROW_W + T
     && HULL_ART.PAD_STERN < HULL_ART.PAD_BOW,
     'the geometry is the game\'s own: room for a nose at the bow, only the nozzles\' overhang at the stern (update121)');
  ok(HULL_ART.name('scout', true) === 'hull_scout' && HULL_ART.name('scout', false) === 'hull_scout_enemy',
     'yours is hull_<key>, theirs hull_<key>_enemy');

  /* ── THE GEOMETRY ──────────────────────────────────────── */
  const bad = [];
  keys.forEach(key => [true, false].forEach(isPlayer => {
    const L = SHIP_LAYOUTS[key], g = geomOf(key, isPlayer), b = g.bounds, tag = `${key}/${isPlayer ? 'you' : 'them'}`;
    const padL = L.isStation ? HULL_ART.PAD_STERN : isPlayer ? HULL_ART.PAD_STERN : HULL_ART.PAD_BOW;
    const padR = L.isStation ? HULL_ART.PAD_STERN : isPlayer ? HULL_ART.PAD_BOW : HULL_ART.PAD_STERN;
    if (g.box.x !== b.x - padL || g.box.w !== b.w + padL + padR
        || g.box.y !== b.y - HULL_ART.PAD_Y || g.box.h !== b.h + 2 * HULL_ART.PAD_Y) bad.push(tag + ' box');
    if (g.box.w % T || g.box.h % T) bad.push(tag + ' box off the tile grid');
    [...g.plate, ...g.engines, ...g.prows].forEach(r => { if (!inside(r, g.box)) bad.push(tag + ' piece outside the box'); });
    if (g.plate.length !== L.rooms.length + (L.elevators ?? []).length) bad.push(tag + ' plate pieces');
    if (L.isStation) { if (g.engines.length || g.prows.length) bad.push(tag + ' a station with engines'); return; }
    if (g.engines.length !== 2 || !g.prows.length) bad.push(tag + ' not two nacelles, or no bow');
    /* update121: one nacelle ON TOP of the top deck and one UNDER the
       bottom deck, each at that deck's stern end, bolted into the plate.
       update128: bigger than the first ones (jj: "za płaskie"). */
    if (HULL_ART.NACELLE.h < 20) bad.push('nacelles still flat (' + HULL_ART.NACELLE.h + ' px)');
    const top = g.engines.find(e => e.side === 'top'), bot = g.engines.find(e => e.side === 'bottom');
    const d0 = g.decks[0], dn = g.decks[g.decks.length - 1];
    if (!top || top.y + top.h <= d0.y - M || top.y >= d0.y - M) bad.push(tag + ' top nacelle not on the top of the hull');
    if (!bot || bot.y >= dn.y + dn.h + M || bot.y + bot.h <= dn.y + dn.h + M) bad.push(tag + ' bottom nacelle not under the hull');
    [[top, d0], [bot, dn]].forEach(([e, d]) => {
      if (!e) return;
      const sternEdge = isPlayer ? d.x0 - M : d.x1 + M;
      const nozzle = isPlayer ? e.x : e.x + e.w;
      /* update128 (jj): the nozzle ends FLUSH with the stern — a nacelle
         sticking out cost room between the two ships. */
      if (nozzle !== sternEdge) bad.push(tag + ' nozzle not flush with the stern');
      if (e.exhaustX !== nozzle) bad.push(tag + ' exhaust not at the nozzle');
    });
    g.prows.forEach(p => { if (isPlayer ? p.x !== b.x + b.w + M : p.x + p.w !== b.x - M) bad.push(tag + ' bow not on the bow'); });
  }));
  ok(bad.length === 0, `every hull, both ways round: box, nacelles on the stern, bow on the bow, stations bare (${bad.slice(0, 4).join('; ') || 'all good'})`);
  ok(geomOf('scout', true).engines.length === 2 && geomOf('scout', true).prows.length === 1,
     'Bastet: two nacelles, top and bottom, and one bow (only the upper deck reaches it)');
  ok(geomOf('frigate', true).engines.length === 2, 'Horus too: two nacelles whatever the number of decks (update121)');
  ok(geomOf('frigate', true).prows.length === 1 && geomOf('frigate', true).prows[0].h === 3 * HULL_GRID.MODULE_H,
     'Horus: three decks to the bow make ONE nose, three decks tall');

  const live = new Ship('scout', true, 170, 180);
  const lg = live.hullArtGeometry(), dg = geomOf('scout', true);
  ok(lg.box.w === dg.box.w && lg.box.h === dg.box.h && lg.box.x - dg.box.x === 170 && lg.box.y - dg.box.y === 180,
     'a ship in the world asks the same question of its live rooms: the same box, moved to where she is');

  /* ── THE FILES ─────────────────────────────────────────── */
  const man = JSON.parse(fs.readFileSync(path.join(ROOT, 'art/manifest.json'), 'utf8'));
  const pngSize = f => { const b = fs.readFileSync(f); return { w: b.readUInt32BE(16), h: b.readUInt32BE(20), sig: b.readUInt32BE(0) === 0x89504e47 }; };
  const fileBad = [];
  keys.forEach(key => [true, false].forEach(isPlayer => {
    const name = HULL_ART.name(key, isPlayer), f = path.join(ROOT, 'art', name + '.png');
    if (!fs.existsSync(f)) { fileBad.push(name + ' missing'); return; }
    if (!man.sprites.includes(name)) fileBad.push(name + ' not in the manifest');
    const s = pngSize(f), g = geomOf(key, isPlayer);
    if (!s.sig) fileBad.push(name + ' not a PNG');
    if (s.w !== g.box.w || s.h !== g.box.h) fileBad.push(`${name} ${s.w}x${s.h}, the hull wants ${g.box.w}x${g.box.h}`);
  }));
  ok(fileBad.length === 0, `every hull has both pictures, listed, and each is exactly its box — a layout that changed without re-running tools/gen_hull_art.js fails here (${fileBad.slice(0, 3).join('; ') || 'all good'})`);
  // the roofs (update118) are the hull's pictures too
  const known = new Set(keys.flatMap(k => [true, false].flatMap(p =>
    [HULL_ART.name(k, p), ...(HULL_ART.roofName ? [HULL_ART.roofName(k, p)] : [])])));
  const stale = man.sprites.filter(n => n.startsWith('hull_') && !known.has(n));
  ok(stale.length === 0, `no picture listed for a hull that is gone (${stale.join(',') || 'none'})`);

  /* ── THE DRAW ──────────────────────────────────────────── */
  const realSource = Assets.source, realGet = Assets.get;
  const fakes = new Map();
  Assets.source = n => fakes.has(n) ? 'file' : realSource(n);
  Assets.get = n => fakes.has(n) ? fakes.get(n) : realGet(n);
  const spy = (ship, fn) => {
    const calls = { images: [], plate: [], glows: [] };
    const di = ctx.drawImage, rg = ctx.createRadialGradient, hp = ship._hullPlatePath;
    ctx.drawImage = function (img, x, y, w, h) { calls.images.push({ img, x, y, w, h }); };
    ctx.createRadialGradient = function (x0, y0) { calls.glows.push({ x: x0, y: y0 }); return { addColorStop() {} }; };
    ship._hullPlatePath = function (c, inset) { calls.plate.push(inset); return hp.call(this, c, inset); };
    try { fn(); } finally { ctx.drawImage = di; ctx.createRadialGradient = rg; delete ship._hullPlatePath; }
    return calls;
  };
  try {
    const you = new Ship('scout', true, 170, 180), g = you.hullArtGeometry();
    const none = spy(you, () => you.draw(ctx));
    ok(none.plate.includes(0) && none.plate.includes(3), 'no picture: the plate is drawn in code, rim and fill, as before');

    const pic = { width: g.box.w, height: g.box.h, tag: 'scout' };
    fakes.set('hull_scout', pic);
    const drawn = spy(you, () => you.draw(ctx));
    const hit = drawn.images.find(c => c.img === pic);
    ok(hit && hit.x === g.box.x && hit.y === g.box.y, `the picture goes exactly on its box (${hit ? hit.x + ',' + hit.y : 'not drawn'} vs ${g.box.x},${g.box.y})`);
    ok(!drawn.plate.includes(0) && !drawn.plate.includes(3), 'and the code plate is not drawn under it');
    const glowXs = g.engines.map(e => e.exhaustX - 4);
    ok(glowXs.every(x => drawn.glows.some(q => q.x === x)) && g.engines.every(e => drawn.glows.some(q => q.y === e.y + e.h / 2)),
       `a glow at every nozzle (${drawn.glows.map(q => q.x + ':' + q.y).join(' ')})`);

    fakes.set('hull_scout', { width: g.box.w + 10, height: g.box.h });
    const wrong = spy(you, () => you.draw(ctx));
    ok(!wrong.images.some(c => c.img === fakes.get('hull_scout')) && wrong.plate.includes(0),
       'a picture the wrong size for the hull is refused — the plate in code, not a rim through the rooms');
    fakes.delete('hull_scout');

    const them = new Ship('scout', false, 750, 200), tg = them.hullArtGeometry();
    fakes.set('hull_scout', { width: tg.box.w, height: tg.box.h });          // YOUR picture only
    ok(them.hullArt() === null, 'the same hull flown at you does not borrow your picture (its stern is on the other side)');
    const theirs = { width: tg.box.w, height: tg.box.h };
    fakes.set('hull_scout_enemy', theirs);
    ok(them.hullArt()?.img === theirs, 'it takes its own');
    ok(tg.engines.every(e => e.exhaustX === e.x + e.w && e.x + e.w > tg.bounds.x + tg.bounds.w / 2), 'and its nozzles are at the right-hand end, at its stern');
    fakes.clear();

    const bunker = new Ship('bunker_small', false, 750, 200), bg = bunker.hullArtGeometry();
    fakes.set('hull_bunker_small_enemy', { width: bg.box.w, height: bg.box.h });
    const bd = spy(bunker, () => bunker.draw(ctx));
    ok(bd.images.length > 0 && bd.glows.length === 0, 'a bunker is drawn from its picture and burns nothing at the stern');
    fakes.clear();

    /* ── THE THUMBNAIL ────────────────────────────────────── */
    const tgeo = geomOf('hauler', true);
    const thumbPic = { width: tgeo.box.w, height: tgeo.box.h };
    const thumbCalls = (fnc) => { const di = ctx.drawImage, out = []; ctx.drawImage = function (img, x, y, w, h) { out.push({ img, x, y, w, h }); }; try { fnc(); } finally { ctx.drawImage = di; } return out; };
    ok(thumbCalls(() => Renderer.drawShipThumb(ctx, 'hauler', 100, 100, 200, 80)).length === 0, 'no picture: the thumbnail is the room plan alone');
    fakes.set('hull_hauler', thumbPic);
    const tc = thumbCalls(() => Renderer.drawShipThumb(ctx, 'hauler', 100, 100, 200, 80)).find(c => c.img === thumbPic);
    ok(tc && tc.x >= 100 - 0.01 && tc.y >= 100 - 0.01 && tc.x + tc.w <= 300.01 && tc.y + tc.h <= 180.01
       && Math.abs(tc.w / tc.h - tgeo.box.w / tgeo.box.h) < 0.01,
       `with one the picture goes under the plan, fitted inside the card at its own proportions (${tc ? [tc.x, tc.y, tc.w, tc.h].map(v => v.toFixed(0)).join(',') : 'not drawn'})`);
    fakes.set('hull_hauler', { width: 1, height: 1 });
    ok(!thumbCalls(() => Renderer.drawShipThumb(ctx, 'hauler', 100, 100, 200, 80)).some(c => c.img === fakes.get('hull_hauler')),
       'and a thumbnail refuses a picture that does not fit its hull too');
  } finally {
    Assets.source = realSource; Assets.get = realGet;
  }
})();

// ============================================================
section('304. Whose yard (117): every hull painted in the colours of the corporation that built it, and the yard\'s habits fitted to the enemy');
// ============================================================
(function testUpdate117() {
  const fs = require('fs'), path = require('path'), zlib = require('zlib');
  const ROOT = path.join(__dirname, '..');
  const sb = loadEngine();
  const { Save, Game, SHIP_LAYOUTS, CORP_DEFS, CORP_KEYS, BUILDER_TRAITS, hullBuilder, HULL_ART, BaseScreen, Base } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const seeded = (seed) => () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
  const withSeed = (seed, fn) => { const real = Math.random; Math.random = seeded(seed); try { return fn(); } finally { Math.random = real; } };

  /* ── EVERY HULL HAS A YARD ─────────────────────────────── */
  const keys = Object.keys(SHIP_LAYOUTS);
  const noYard = keys.filter(k => !CORP_KEYS.includes(SHIP_LAYOUTS[k].builder));
  ok(noYard.length === 0, `every hull names the corporation that built it (${noYard.join(',') || 'all do'})`);
  ok(CORP_KEYS.every(c => BUILDER_TRAITS[c]), 'and every corporation has a yard with habits');
  ok(hullBuilder('frigate') === 'aquarius' && hullBuilder('thoth') === 'aquarius' && hullBuilder('enemy_ra') === 'aquarius',
     'the hulls with a medbay are Aquarius hospital ships');
  ok(hullBuilder('osiris') === 'phoenix' && hullBuilder('enemy_gunship') === 'phoenix', 'the two-gun hulls are Phoenix');
  ok(hullBuilder('isis') === 'pegasus' && hullBuilder('enemy_frigate') === 'pegasus', 'Isis and Set: Pegasus, shielded');
  ok(hullBuilder('hauler') === 'terra' && hullBuilder('bunker_small') === 'terra', 'Hapi and the bunker: Terra, big reactors');
  const pool = ['enemy_frigate', 'enemy_gunship', 'enemy_raider', 'enemy_ra', 'enemy_khnum', 'enemy_hathor', 'enemy_montu'];
  ok(CORP_KEYS.every(c => pool.some(k => hullBuilder(k) === c)), 'all four yards fly in the ordinary enemy draw');

  /* ── THE PICTURE IS IN THE YARD'S COLOURS ─────────────────
     A small PNG reader (8-bit RGBA, what a canvas writes) — enough to
     look at the plate itself rather than trust the generator. */
  const readPng = (file) => {
    const b = fs.readFileSync(file);
    const w = b.readUInt32BE(16), h = b.readUInt32BE(20), depth = b[24], type = b[25];
    if (depth !== 8 || type !== 6) return null;
    const idat = []; let o = 8;
    while (o < b.length) { const len = b.readUInt32BE(o), t = b.toString('ascii', o + 4, o + 8); if (t === 'IDAT') idat.push(b.slice(o + 8, o + 8 + len)); o += 12 + len; }
    const raw = zlib.inflateSync(Buffer.concat(idat)), px = Buffer.alloc(w * h * 4), st = w * 4;
    for (let y = 0; y < h; y++) {
      const f = raw[y * (st + 1)];
      for (let x = 0; x < st; x++) {
        const v = raw[y * (st + 1) + 1 + x], a = x >= 4 ? px[y * st + x - 4] : 0, up = y ? px[(y - 1) * st + x] : 0, ul = (y && x >= 4) ? px[(y - 1) * st + x - 4] : 0;
        let r = v;
        if (f === 1) r = v + a; else if (f === 2) r = v + up; else if (f === 3) r = v + ((a + up) >> 1);
        else if (f === 4) { const p0 = a + up - ul, pa = Math.abs(p0 - a), pb = Math.abs(p0 - up), pc = Math.abs(p0 - ul); r = v + (pa <= pb && pa <= pc ? a : pb <= pc ? up : ul); }
        px[y * st + x] = r & 255;
      }
    }
    return { w, h, px };
  };
  /** The average colour of the plate band along the top of the hull. */
  const plateColour = (name) => {
    const img = readPng(path.join(ROOT, 'art', name + '.png'));
    if (!img) return null;
    const y = HULL_ART.PAD_Y - 6;                        // inside the band above the top deck
    let r = 0, g = 0, bl = 0, n = 0;
    for (let x = HULL_ART.PAD_BOW + HULL_ART.NACELLE.len; x < img.w - HULL_ART.PAD_BOW - HULL_ART.NACELLE.len; x++) {   // clear of the nose and the top nacelle (update121)
      const i = (y * img.w + x) * 4;
      if (img.px[i + 3] < 200) continue;
      r += img.px[i]; g += img.px[i + 1]; bl += img.px[i + 2]; n++;
    }
    return n ? { r: r / n, g: g / n, b: bl / n } : null;
  };
  const isYard = {
    phoenix:  c => c.r > c.g * 1.8 && c.r > c.b * 1.8,
    terra:    c => c.r > c.g * 1.3 && c.g > c.b * 1.3,
    aquarius: c => c.b > c.r * 1.6 && c.r + c.g + c.b < 330,
    pegasus:  c => c.b > c.r * 1.15 && c.r + c.g + c.b >= 330,
  };
  const wrongPaint = [];
  keys.forEach(k => [true, false].forEach(you => {
    const name = HULL_ART.name(k, you), c = plateColour(name), y = SHIP_LAYOUTS[k].builder;
    if (!c || !isYard[y](c)) wrongPaint.push(`${name} (${y}: ${c ? [c.r, c.g, c.b].map(Math.round).join('/') : 'unreadable'})`);
  }));
  ok(wrongPaint.length === 0, `every picture is painted in its yard's colours — red Phoenix, orange Terra, deep blue Aquarius, pale Pegasus (${wrongPaint.slice(0, 3).join('; ') || 'all'})`);
  const aq = plateColour('hull_frigate'), pg = plateColour('hull_isis');
  ok(aq && pg && (pg.r + pg.g + pg.b) - (aq.r + aq.g + aq.b) > 80, 'the two blue yards cannot be mistaken: Pegasus is much the paler');

  /* ── THE YARD'S HABITS ON AN ENEMY ──────────────────────── */
  const census = (sector, seed) => withSeed(seed, () => {
    Save.load(); Save.startRun(); Save.updateRun({ mission: 'patrol', sector });
    const by = {};
    for (let i = 0; i < 400; i++) {
      T._spawnEnemy('normal');
      const e = T.enemyShip, y = hullBuilder(e.layoutKey) ?? 'none';
      const a = by[y] = by[y] || { n: 0, shields: 0, layers: 0, medbay: 0, mbLevel: 0, gun0: {}, spare: 0, eng: 0, medkits: 0 };
      a.n++;
      const sh = e.getSystem('shields'); if (sh) { a.shields++; a.layers += sh.level; }
      const mb = e.getSystem('medbay'); if (mb) { a.medbay++; a.mbLevel += mb.level; }
      const g = e.weapons[0]?.defKey; a.gun0[g] = (a.gun0[g] || 0) + 1;
      const need = e.systems.filter(s => s.type !== 'reactor').reduce((x, s) => x + s.maxPower, 0);
      a.spare += e.reactor.level - need;
      a.eng += e.getSystem('engines')?.level ?? 0;
      a.medkits += (e.cargo?.items ?? []).filter(it => it.defKey === 'medkit').reduce((x, it) => x + (it.isStack ? it.qty : 1), 0);
    }
    return by;
  });
  const s1 = census(1, 1171), s3 = census(3, 1173);
  const avg = (a, f) => a[f] / a.n;
  const others = (by, y, f) => { const o = Object.entries(by).filter(([k]) => k !== y && k !== 'none'); return o.reduce((x, [, a]) => x + a[f], 0) / o.reduce((x, [, a]) => x + a.n, 0); };

  // Phoenix: a better first gun, about half the time; nobody else's changes.
  const ph1 = s1.phoenix, ph3 = s3.phoenix;
  const burst1 = (ph1.gun0.laser_burst ?? 0) / ph1.n, heavy3 = (ph3.gun0.laser_heavy ?? 0) / ph3.n;
  ok(burst1 > 0.3 && burst1 < 0.7, `Phoenix, sector 1: a burst laser up front on ${(burst1 * 100).toFixed(0)}% of hulls`);
  ok(heavy3 > 0.3 && heavy3 < 0.7, `Phoenix, sector 3: a heavy laser up front on ${(heavy3 * 100).toFixed(0)}%`);
  const othersUpgraded = ['terra', 'pegasus', 'aquarius'].some(y => (s1[y]?.gun0.laser_burst ?? 0) + (s3[y]?.gun0.laser_heavy ?? 0) > 0);
  ok(!othersUpgraded, 'and no other yard\'s first gun is touched');

  // Pegasus: shields always from sector 2, a second layer from sector 3; sector 1 keeps its rule.
  ok(s1.pegasus.shields === 0, 'Pegasus, sector 1: still nobody\'s shields — the opening sector\'s rule holds');
  ok(s3.pegasus.shields === s3.pegasus.n, `Pegasus, sector 3: every hull has her bubble (${s3.pegasus.shields}/${s3.pegasus.n})`);
  ok(avg(s3.pegasus, 'layers') >= 4 && others(s3, 'pegasus', 'shields') < 0.8,
     `two layers on a Pegasus hull (${avg(s3.pegasus, 'layers').toFixed(1)} pips), while the others roll for theirs`);

  // Aquarius: a medbay, always, and a better one; more medicine.
  const aqNoMed = keys.filter(k => SHIP_LAYOUTS[k].builder === 'aquarius' && !SHIP_LAYOUTS[k].rooms.some(r => r.type === 'medbay'));
  ok(aqNoMed.length === 0, `every Aquarius hull is DRAWN with a medbay (${aqNoMed.join(',') || 'all are'})`);
  ok(s1.aquarius.medbay === s1.aquarius.n && s3.aquarius.medbay === s3.aquarius.n, 'and flies with it: every Aquarius enemy is a hospital ship');
  ok(avg(s3.aquarius, 'mbLevel') >= 2, `with a level-2 medbay (${avg(s3.aquarius, 'mbLevel').toFixed(1)})`);
  ok(avg(s3.aquarius, 'medkits') > others(s3, 'aquarius', 'medkits') + 1,
     `and more medicine aboard (${avg(s3.aquarius, 'medkits').toFixed(1)} against ${others(s3, 'aquarius', 'medkits').toFixed(1)})`);

  // Terra: spare reactor and a hotter drive.
  ok(avg(s1.terra, 'spare') > others(s1, 'terra', 'spare') + 0.5 && avg(s3.terra, 'spare') > others(s3, 'terra', 'spare') + 0.5,
     `Terra flies with power to spare (${avg(s3.terra, 'spare').toFixed(1)} against ${others(s3, 'terra', 'spare').toFixed(1)})`);
  ok(avg(s1.terra, 'eng') >= others(s1, 'terra', 'eng') + 0.9, `and a hotter drive (${avg(s1.terra, 'eng').toFixed(1)} against ${others(s1, 'terra', 'eng').toFixed(1)})`);

  /* ── THE BASE SAYS WHOSE YARD ──────────────────────────── */
  Save.reset(); Save.load(); Base.earn(2000);
  BaseScreen.open();
  BaseScreen._act('building', 'HANGAR');         // the hangar is behind its door in the town (update149)
  const drawn = captureStyledText(ctx, () => BaseScreen.draw(ctx));
  const tag = drawn.find(o => o.t === 'TERRA');
  ok(tag && String(tag.fill).toLowerCase() === CORP_DEFS.terra.color, `the shipyard card names the yard, in its colour (${tag ? tag.fill : 'not drawn'})`);
  ok(drawn.some(o => o.t === BUILDER_TRAITS.terra.blurb), 'and the hangar preview says what that yard is known for');
})();

// ============================================================
section('305. A closed hull (118): a roof over every hull, closed in the yard and in the jump, filmed jumps, and the roofs come off when a fight opens');
// ============================================================
(function testUpdate118() {
  const fs = require('fs'), path = require('path'), zlib = require('zlib');
  const ROOT = path.join(__dirname, '..');
  const sb = loadEngine();
  const { Ship, Save, Game, SectorMap, SHIP_LAYOUTS, HULL_ART, HULL_GRID, hullArtGeometry, Assets, Renderer,
          BaseScreen, Base, JumpScene, Input, CombatManager } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const keys = Object.keys(SHIP_LAYOUTS);
  const geomOf = (key, isPlayer) => {
    const L = SHIP_LAYOUTS[key];
    return hullArtGeometry(L.rooms, (L.elevators ?? []).map(e => e.x), isPlayer, !!L.isStation);
  };

  /* ── THE ROOF PICTURES ─────────────────────────────────── */
  ok(typeof HULL_ART.roofName === 'function' && HULL_ART.roofName('scout', true) === 'hull_scout_roof'
     && HULL_ART.roofName('scout', false) === 'hull_scout_enemy_roof', 'the roof is hull_<key>_roof, and hull_<key>_enemy_roof for theirs');
  const readPng = (file) => {
    const b = fs.readFileSync(file);
    const w = b.readUInt32BE(16), h = b.readUInt32BE(20), depth = b[24], type = b[25];
    if (depth !== 8 || type !== 6) return null;
    const idat = []; let o = 8;
    while (o < b.length) { const len = b.readUInt32BE(o), t = b.toString('ascii', o + 4, o + 8); if (t === 'IDAT') idat.push(b.slice(o + 8, o + 8 + len)); o += 12 + len; }
    const raw = zlib.inflateSync(Buffer.concat(idat)), px = Buffer.alloc(w * h * 4), st = w * 4;
    for (let y = 0; y < h; y++) {
      const f = raw[y * (st + 1)];
      for (let x = 0; x < st; x++) {
        const v = raw[y * (st + 1) + 1 + x], a = x >= 4 ? px[y * st + x - 4] : 0, up = y ? px[(y - 1) * st + x] : 0, ul = (y && x >= 4) ? px[(y - 1) * st + x - 4] : 0;
        let r = v;
        if (f === 1) r = v + a; else if (f === 2) r = v + up; else if (f === 3) r = v + ((a + up) >> 1);
        else if (f === 4) { const p0 = a + up - ul, pa = Math.abs(p0 - a), pb = Math.abs(p0 - up), pc = Math.abs(p0 - ul); r = v + (pa <= pb && pa <= pc ? a : pb <= pc ? up : ul); }
        px[y * st + x] = r & 255;
      }
    }
    return { w, h, px };
  };
  const man = JSON.parse(fs.readFileSync(path.join(ROOT, 'art/manifest.json'), 'utf8'));
  const roofBad = [], coverBad = [], colours = {};
  keys.forEach(key => [true, false].forEach(isPlayer => {
    const name = HULL_ART.roofName(key, isPlayer), f = path.join(ROOT, 'art', name + '.png');
    if (!fs.existsSync(f)) { roofBad.push(name + ' missing'); return; }
    if (!man.sprites.includes(name)) roofBad.push(name + ' not in the manifest');
    const img = readPng(f), g = geomOf(key, isPlayer), L = SHIP_LAYOUTS[key];
    if (!img) { roofBad.push(name + ' unreadable'); return; }
    if (img.w !== g.box.w || img.h !== g.box.h) { roofBad.push(`${name} ${img.w}x${img.h}, wants ${g.box.w}x${g.box.h}`); return; }
    // opaque over every compartment and lift trunk, clear everywhere else
    const inRoom = (x, y) => L.rooms.some(r => x >= r.x && x < r.x + r.w && y >= r.y && y < r.y + r.h)
      || (L.elevators ?? []).some(e => x >= e.x - HULL_GRID.SHAFT_W / 2 && x < e.x + HULL_GRID.SHAFT_W / 2
                                       && y >= g.bounds.y && y < g.bounds.y + g.bounds.h);
    let holes = 0, spill = 0, r = 0, gg = 0, bl = 0, n = 0;
    for (let y = 0; y < img.h; y += 2) for (let x = 0; x < img.w; x += 2) {
      const a = img.px[(y * img.w + x) * 4 + 3], inside = inRoom(x + g.box.x, y + g.box.y);
      if (inside && a !== 255) holes++;
      if (!inside && a !== 0) spill++;
      if (inside) { const i = (y * img.w + x) * 4; r += img.px[i]; gg += img.px[i + 1]; bl += img.px[i + 2]; n++; }
    }
    if (holes || spill) coverBad.push(`${name}: ${holes} open, ${spill} outside`);
    colours[name] = { r: r / n, g: gg / n, b: bl / n };
  }));
  ok(roofBad.length === 0, `every hull has both roofs, listed, each exactly its box (${roofBad.slice(0, 3).join('; ') || 'all good'})`);
  ok(coverBad.length === 0, `each roof covers every compartment and lift trunk and nothing else (${coverBad.slice(0, 3).join('; ') || 'all exact'})`);
  const isYard = {
    phoenix:  c => c.r > c.g * 1.6 && c.r > c.b * 1.6,
    terra:    c => c.r > c.g * 1.25 && c.g > c.b * 1.25,
    aquarius: c => c.b > c.r * 1.4 && c.r + c.g + c.b < 360,
    pegasus:  c => c.b > c.r * 1.1 && c.r + c.g + c.b >= 360,
  };
  const wrongRoof = Object.entries(colours).filter(([name, c]) => {
    const key = name.replace(/^hull_/, '').replace(/(_enemy)?_roof$/, '');
    return !isYard[SHIP_LAYOUTS[key].builder](c);
  }).map(([n, c]) => `${n} ${[c.r, c.g, c.b].map(Math.round).join('/')}`);
  ok(wrongRoof.length === 0, `a roof is the yard's colour, like its plate (${wrongRoof.slice(0, 3).join('; ') || 'all'})`);
  const peg = colours.hull_isis_roof, aqu = colours.hull_frigate_roof;
  ok(peg && aqu && (peg.r + peg.g + peg.b) - (aqu.r + aqu.g + aqu.b) > 80, 'and the two blue yards are still told apart closed');

  /* ── THE SHIP DRAWS ITS ROOF ───────────────────────────── */
  const realSource = Assets.source, realGet = Assets.get;
  const fakes = new Map();
  Assets.source = n => fakes.has(n) ? 'file' : realSource(n);
  Assets.get = n => fakes.has(n) ? fakes.get(n) : realGet(n);
  const order = (ship, fn) => {
    const log = [];
    const di = ctx.drawImage, fr = ctx.fillRect, wm = ship._drawWeaponMounts, rs = ship.rooms[0].system?.draw;
    ctx.drawImage = function (img, x, y) { log.push({ k: 'img', img, x, y, alpha: ctx.globalAlpha }); };
    ctx.fillRect = function (x, y, w, h) { log.push({ k: 'rect', x, y, w, h, fill: ctx.fillStyle }); };
    ship._drawWeaponMounts = function (c) { log.push({ k: 'guns' }); };
    try { fn(); } finally { ctx.drawImage = di; ctx.fillRect = fr; delete ship._drawWeaponMounts; }
    return log;
  };
  try {
    const you = new Ship('scout', true, 170, 180), g = you.hullArtGeometry();
    ok(you.roofAlpha === 0, 'a ship is built OPEN — the cutaway the fight is played on');
    ok(you.roofArt() === null, 'no file, no roof picture');
    const roof = { width: g.box.w, height: g.box.h, tag: 'roof' };
    fakes.set('hull_scout_roof', roof);
    ok(you.roofArt()?.img === roof, 'with the file, the roof picture');
    let log = order(you, () => you.draw(ctx));
    ok(!log.some(e => e.img === roof), 'open (roofAlpha 0): the roof is not drawn at all');
    you.roofAlpha = 0.5;
    ctx.globalAlpha = 1;
    log = order(you, () => you.draw(ctx));
    const at = log.findIndex(e => e.img === roof), guns = log.findIndex(e => e.k === 'guns');
    ok(at >= 0 && log[at].x === g.box.x && log[at].y === g.box.y && Math.abs(log[at].alpha - 0.5) < 1e-9,
       `half closed: the roof goes on its box at half strength (${at >= 0 ? log[at].x + ',' + log[at].y + ' a=' + log[at].alpha : 'not drawn'})`);
    ok(at >= 0 && guns > at, 'over the compartments, UNDER the guns — the barrels stay on top of a closed hull');
    ok(ctx.globalAlpha === 1, 'and the alpha is given back');
    fakes.set('hull_scout_roof', { width: g.box.w + 10, height: g.box.h });
    you.roofAlpha = 1;
    log = order(you, () => you.draw(ctx));
    const covered = you.rooms.every(r => log.some(e => e.k === 'rect' && e.x === r.x && e.y === r.y && e.w === r.w && e.h === r.h));
    ok(!log.some(e => e.img === fakes.get('hull_scout_roof')) && covered,
       'a roof the wrong size is refused, and the code skin closes every compartment instead');
    fakes.clear();
    const them = new Ship('scout', false, 750, 200), tg = them.hullArtGeometry();
    fakes.set('hull_scout_roof', { width: tg.box.w, height: tg.box.h });
    ok(them.roofArt() === null, 'theirs does not borrow your roof');
    fakes.set('hull_scout_enemy_roof', { width: tg.box.w, height: tg.box.h });
    ok(them.roofArt()?.img === fakes.get('hull_scout_enemy_roof'), 'it takes its own');
    fakes.clear();
    ok(!JSON.stringify(you.serialise?.() ?? {}).includes('roofAlpha'), 'how closed she is is never saved');

    /* ── THE THUMBNAIL ────────────────────────────────────── */
    const hg = geomOf('hauler', true);
    const hullPic = { width: hg.box.w, height: hg.box.h }, roofPic = { width: hg.box.w, height: hg.box.h };
    const thumb = (o) => { const out = [], di = ctx.drawImage; ctx.drawImage = function (img, x, y, w, h) { out.push({ img, x, y, w, h, a: ctx.globalAlpha }); }; try { Renderer.drawShipThumb(ctx, 'hauler', 100, 100, 200, 80, o); } finally { ctx.drawImage = di; } return out; };
    fakes.set('hull_hauler_roof', roofPic);
    ok(!thumb({ roof: 1 }).some(c => c.img === roofPic), 'no hull picture: no roof on the card either (it is cut to the picture)');
    fakes.set('hull_hauler', hullPic);
    const closed = thumb({ roof: 1 }), h = closed.find(c => c.img === hullPic), rf = closed.find(c => c.img === roofPic);
    ok(h && rf && rf.x === h.x && rf.y === h.y && rf.w === h.w && rf.h === h.h && closed.indexOf(rf) > closed.indexOf(h),
       'closed card: the roof goes on top of the hull, on exactly the same rectangle');
    ok(!thumb({ roof: 0 }).some(c => c.img === roofPic) && !thumb({}).some(c => c.img === roofPic), 'open card: no roof');
    ok(Math.abs((thumb({ roof: 0.4 }).find(c => c.img === roofPic)?.a ?? 0) - 0.4) < 1e-9, 'half way: the roof at that strength');
    fakes.set('hull_hauler_roof', { width: 3, height: 3 });
    ok(!thumb({ roof: 1 }).some(c => c.img === fakes.get('hull_hauler_roof')), 'a card refuses a roof that does not fit');
    fakes.clear();

    /* ── THE YARD SHOWS HER CLOSED ────────────────────────── */
    fakes.set('hull_scout', { width: geomOf('scout', true).box.w, height: geomOf('scout', true).box.h });
    fakes.set('hull_scout_roof', { width: geomOf('scout', true).box.w, height: geomOf('scout', true).box.h });
    Save.reset(); Save.load(); Base.earn(2000);
    BaseScreen.open();
    BaseScreen._set({ tab: 'HANGAR', screen: null, interior: false, roofs: {}, roofStep: 0 });
    Input.mouse.x = 2; Input.mouse.y = 2;
    let words = captureText(ctx, () => BaseScreen.draw(ctx));
    let st = BaseScreen._state();
    const cardIds = Object.keys(st.roofs).filter(k => k.startsWith('row:'));
    ok(cardIds.length >= 2 && cardIds.every(k => st.roofs[k] === 1), `every card in the hangar starts closed (${cardIds.length} cards)`);
    ok(st.roofs.hangar === 1, 'and so does the big hull in the middle');
    const btn = words.find(w => /INTERIOR\s+\[I\]/.test(w.t));
    ok(!!btn, 'INTERIOR [I] is offered over the hull');
    // the preview ship the hangar draws carries what the yard set
    let shipDrawn = null;
    const realDraw = Ship.prototype.draw;
    Ship.prototype.draw = function (c) { shipDrawn = { ship: this, roof: this.roofAlpha }; return realDraw.call(this, c); };
    try {
      BaseScreen.draw(ctx);
      ok(shipDrawn && shipDrawn.roof === 1, `the hangar hull is drawn closed (roof ${shipDrawn?.roof})`);
      // The pointer on the hull takes the roof off, over ROOF_FADE seconds.
      const stage = BaseScreen._state().hangarStage;
      Input.mouse.x = stage.x + stage.w / 2; Input.mouse.y = stage.y + stage.h / 2;
      BaseScreen._set({ roofStep: 0.15 });
      BaseScreen.draw(ctx);
      ok(Math.abs(shipDrawn.roof - 0.5) < 1e-9, `half a fade later she is half open (${shipDrawn.roof})`);
      BaseScreen.draw(ctx);
      ok(shipDrawn.roof === 0, 'and then open — the cutaway, to see what is inside');
      Input.mouse.x = 2; Input.mouse.y = 2;
      BaseScreen._set({ roofStep: 1 });
      BaseScreen.draw(ctx);
      ok(shipDrawn.roof === 1, 'the pointer gone, she closes again');
      // INTERIOR [I] holds her open.
      const realPressed = Input.isPressed;
      Input.isPressed = k => k === 'KeyI';
      try { BaseScreen.update(0); } finally { Input.isPressed = realPressed; }
      ok(BaseScreen._state().interior === true, '[I] holds the hull open');
      BaseScreen._set({ roofStep: 1 });
      BaseScreen.draw(ctx);
      ok(shipDrawn.roof === 0, 'and she stays open with the pointer away');
      words = captureText(ctx, () => BaseScreen.draw(ctx));
      ok(words.some(w => /EXTERIOR\s+\[I\]/.test(w.t)), 'the button now offers the outside back');
      Input.isPressed = k => k === 'KeyI';
      try { BaseScreen.update(0); } finally { Input.isPressed = realPressed; }
      BaseScreen._set({ roofStep: 1 });
      BaseScreen.draw(ctx);
      ok(BaseScreen._state().interior === false && shipDrawn.roof === 1, 'and [I] again closes her');
      // A card under the pointer opens.
      st = BaseScreen._state();
      const anyCard = Object.keys(st.roofs).find(k => k.startsWith('row:'));
      const [cx, cy] = anyCard.split(':')[2].split(',').map(Number);
      Input.mouse.x = cx + 20; Input.mouse.y = cy + 20;
      BaseScreen.draw(ctx);
      st = BaseScreen._state();
      ok(st.roofs[anyCard] === 0 && Object.keys(st.roofs).filter(k => k.startsWith('row:') && k !== anyCard).every(k => st.roofs[k] === 1),
         'the card under the pointer opens, and only that one');
      // The loadout: men are posted on rooms, so it is always the cutaway.
      Input.mouse.x = 2; Input.mouse.y = 2;
      BaseScreen._set({ screen: 'loadout' });
      shipDrawn = null;
      BaseScreen.draw(ctx);
      ok(shipDrawn && shipDrawn.roof === 0, 'the LOADOUT shows the hull open — you post your crew on its rooms');
      BaseScreen._set({ screen: null });
    } finally { Ship.prototype.draw = realDraw; }
  } finally {
    Assets.source = realSource; Assets.get = realGet;
  }

  /* ── THE FILMS ─────────────────────────────────────────── */
  ok(JumpScene && JumpScene.enabled === false, 'the suites run without films unless they ask (the game turns them on at boot)');
  ok(Math.abs(JumpScene.OUT_T - 1.5) < 1e-9, `the jump is a second and a half (${JumpScene.OUT_T})`);
  const setUp = () => {
    JumpScene.reset();
    Save.reset(); Save.load(); Save.startRun();
    const ship = new Ship('scout', true, Ship.PLAYER_STATION?.x ?? 80, Ship.PLAYER_STATION?.y ?? 120);
    ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    T.playerShip = ship; T.STATE = 'map'; T.paused = false;
    T.sectorMap = new SectorMap(1, 4242, Save.getRun().lane ?? 1);
    if (T.sectorMap.awaitingStartPick && T.sectorMap.startNodes.length) T._travelTo(T.sectorMap.startNodes[0].id);
    T._addFuel(5);
    return ship;
  };
  const fight = (ship) => {
    const node = T.sectorMap.nodes.find(n => !n.locked && !n.visited && n.id !== T.sectorMap.currentId);
    node.type = 'combat'; node.wantedId = null;
    const real = Math.random; Math.random = () => 0.9;
    try { T._travelTo(node.id); } finally { Math.random = real; }
    return node;
  };

  // Off: the old game exactly — no film, the fight opens open.
  let ship = setUp();
  ok(!JumpScene.active(), 'picking the starting lane is not a jump — no film');
  fight(ship);
  ok(T.STATE === 'combat' && !JumpScene.active(), 'films off: straight into the fight');
  ok(ship.roofAlpha === 0 && T.enemyShip.roofAlpha === 0, 'and both hulls open');

  JumpScene.enabled = true;
  try {
    ship = setUp();
    ok(!JumpScene.active(), 'films on: still no film for picking a lane');
    fight(ship);
    ok(T.STATE === 'combat', 'the jump does what it always did, at once: the fight is already set up behind the film');
    ok(JumpScene.current()?.kind === 'jump' && JumpScene.queued() === 1, 'and the jump film plays, with the arrival queued behind it');
    ok(ship.roofAlpha === 1 && T.enemyShip.roofAlpha === 1, 'both hulls are closed from the moment the fight is set');
    ok(JumpScene.covers(), 'the jump fills the screen');
    let hud = 0;
    const realHud = Renderer.drawHUD;
    Renderer.drawHUD = function () { hud++; };
    let words;
    try { words = captureText(ctx, () => T._draw()); } finally { Renderer.drawHUD = realHud; }
    ok(words.some(w => w.t === JumpScene.SKIP_HINT) && hud === 0,
       'what is drawn is the film and nothing of the fight behind it');
    // The clock is held: neither ship gets a single tick while you watch.
    const ticks = { you: 0, him: 0 };
    const realYou = ship.update, realHim = T.enemyShip.update;
    ship.update = function (dt) { if (dt > 0) ticks.you++; return realYou.call(this, dt); };
    T.enemyShip.update = function (dt) { if (dt > 0) ticks.him++; return realHim.call(this, dt); };
    for (let i = 0; i < 20; i++) T._step(0.05);
    ok(JumpScene.current()?.kind === 'jump' && ticks.you === 0 && ticks.him === 0,
       'a second into the film nothing in the fight has moved — neither hull has had a tick');
    for (let i = 0; i < 12; i++) T._step(0.05);
    ok(JumpScene.current()?.kind === 'jump' && !JumpScene.covers() && JumpScene.placement(ship).dx < 0,
       'while the flash fades off the fight, you are already where the arrival starts — not parked in place');
    for (let i = 0; i < 5; i++) T._step(0.05);
    ok(JumpScene.current()?.kind === 'arrive', 'after the jump and its flash, the arrival');
    // the fight screen draws the hulls where the film has them
    const drawn = [];
    const realP = ship.draw, realE = T.enemyShip.draw;
    ship.draw = function (c) { drawn.push('you'); };
    T.enemyShip.draw = function (c) { drawn.push('him'); };
    try { T._drawCombat(ctx); } finally { ship.draw = realP; T.enemyShip.draw = realE; delete ship.draw; delete T.enemyShip.draw; }
    ok(drawn.includes('you') && (!JumpScene.flies(T.enemyShip) || !drawn.includes('him')),
       `the fight screen draws you coming in and not him yet (${drawn.join(',')})`);
    ok(!JumpScene.covers(), 'which is played ON the fight screen');
    const p0 = JumpScene.placement(ship), e0 = JumpScene.placement(T.enemyShip);
    ok(p0.dx < 0 && p0.sx > 1 && p0.visible, 'you come in from the left, still stretched from the jump');
    ok(JumpScene.flies(T.enemyShip) ? !e0.visible : e0.visible, 'he is not there yet (a flying hull drops out a moment later)');
    for (let i = 0; i < 18; i++) T._step(0.05);
    const p1 = JumpScene.placement(ship), e1 = JumpScene.placement(T.enemyShip);
    ok(p1.dx === 0 && p1.sx === 1 && e1.visible && Math.abs(e1.dx) < 1 && e1.sx < 1.01, 'both in place, at rest');
    ok(ship.roofAlpha === 1, 'and still closed until he has braked');
    for (let i = 0; i < 3; i++) T._step(0.05);
    ok(ship.roofAlpha > 0 && ship.roofAlpha < 1 && T.enemyShip.roofAlpha === ship.roofAlpha, 'then both roofs come off together');
    for (let i = 0; i < 40 && JumpScene.active(); i++) T._step(0.05);
    ok(!JumpScene.active() && ship.roofAlpha === 0 && T.enemyShip.roofAlpha === 0, 'the film over: the cutaway, and the fight is on');
    ok(ticks.you === 0 && ticks.him === 0, 'not one tick of the fight through the whole film');
    T._step(0.05);
    ok(ticks.you === 1 && ticks.him === 1, `and only now does the fight run (${ticks.you}/${ticks.him})`);
    delete ship.update; delete T.enemyShip.update;

    // Skipping: one key does the lot, and SPACE does not also pause.
    ship = setUp();
    fight(ship);
    const realPressed = Input.isPressed;
    Input.isPressed = k => k === 'Space';
    try { T._step(0.05); } finally { Input.isPressed = realPressed; }
    ok(!JumpScene.active() && JumpScene.queued() === 0, 'SPACE skips the jump AND the arrival');
    ok(ship.roofAlpha === 0 && T.enemyShip.roofAlpha === 0, 'leaving the hulls open, as if the film had played');
    ok(T.paused === false, 'and the key that skipped did not pause the fight as well');
    ship = setUp();
    fight(ship);
    Input.mouse.leftPressed = true;
    try { T._step(0.05); } finally { Input.mouse.leftPressed = false; }
    ok(!JumpScene.active(), 'a click skips too');

    // A hull that does not fly is there all along, and opens sooner.
    JumpScene.reset();
    const bunker = new Ship('bunker_small', false, 750, 200);
    JumpScene.arrive(ship, bunker);
    ok(!JumpScene.flies(bunker) && JumpScene.placement(bunker).visible && JumpScene.placement(bunker).dx === 0,
       'a bunker does not drop out of a jump — it is already there');
    ok(JumpScene.current().dur < JumpScene.ARR_T, 'and the roofs come off sooner');
    JumpScene.skip();

    // The boss: his station is there already; the roofs still come off.
    ship = setUp();
    const bossNode = T.sectorMap.nodes.find(n => !n.locked && !n.visited && n.id !== T.sectorMap.currentId);
    bossNode.type = 'boss';
    T._travelTo(bossNode.id);
    ok(T.STATE === 'combat' && JumpScene.queued() === 1 && T.enemyShip.roofAlpha === 1,
       'the boss: a jump in, and his station closed behind it');
    JumpScene.skip();
    ok(T.enemyShip.roofAlpha === 0 && ship.roofAlpha === 0, 'and open for the fight');
    sb.BossManager?.reset?.();

    // Running away opens the chart; the node he picks is the jump that is
    // filmed (update138 — one jump, not a film and then the same place).
    ship = setUp();
    fight(ship);
    JumpScene.skip();
    const realFled = CombatManager.isFled;
    CombatManager.isFled = () => true;
    try { T._updateCombat(0.02); } finally { CombatManager.isFled = realFled; }
    ok(T.STATE === 'map' && T._mapView === 'map' && T._jumpPrompt && !JumpScene.active(),
       'an escape opens the chart and asks where to — no film yet');
    JumpScene.skip();
  } finally {
    JumpScene.enabled = false; JumpScene.reset();
  }
})();

// ============================================================
section('306. The inside of every module (119): a picture per module, a console where the operator stands, a healing pod and three slabs, the lights down without power');
// ============================================================
(function testUpdate119() {
  const fs = require('fs'), path = require('path'), zlib = require('zlib');
  const ROOT = path.join(__dirname, '..');
  const sb = loadEngine();
  const { Ship, HULL_GRID, Assets, SYSTEM_DEFS, SYSTEM_ALIASES, moduleArt, MODULE_DARK, ROOM_DISPLAY } = sb;
  const ctx = initRenderer(sb);
  const W = HULL_GRID.MODULE_W, H = HULL_GRID.MODULE_H - HULL_GRID.VENT_H;
  const TYPES = ['empty', ...Object.keys(SYSTEM_DEFS)];
  const nameOf = t => t === 'empty' ? 'room_default' : 'room_' + t;
  const readPng = (file) => {
    const b = fs.readFileSync(file);
    const w = b.readUInt32BE(16), h = b.readUInt32BE(20), depth = b[24], type = b[25];
    if (depth !== 8 || type !== 6) return null;
    const idat = []; let o = 8;
    while (o < b.length) { const len = b.readUInt32BE(o), t = b.toString('ascii', o + 4, o + 8); if (t === 'IDAT') idat.push(b.slice(o + 8, o + 8 + len)); o += 12 + len; }
    const raw = zlib.inflateSync(Buffer.concat(idat)), px = Buffer.alloc(w * h * 4), st = w * 4;
    for (let y = 0; y < h; y++) {
      const f = raw[y * (st + 1)];
      for (let x = 0; x < st; x++) {
        const v = raw[y * (st + 1) + 1 + x], a = x >= 4 ? px[y * st + x - 4] : 0, up = y ? px[(y - 1) * st + x] : 0, ul = (y && x >= 4) ? px[(y - 1) * st + x - 4] : 0;
        let r = v;
        if (f === 1) r = v + a; else if (f === 2) r = v + up; else if (f === 3) r = v + ((a + up) >> 1);
        else if (f === 4) { const p0 = a + up - ul, pa = Math.abs(p0 - a), pb = Math.abs(p0 - up), pc = Math.abs(p0 - ul); r = v + (pa <= pb && pa <= pc ? a : pb <= pc ? up : ul); }
        px[y * st + x] = r & 255;
      }
    }
    return { w, h, px, at: (x, y) => [px[(y * w + x) * 4], px[(y * w + x) * 4 + 1], px[(y * w + x) * 4 + 2], px[(y * w + x) * 4 + 3]] };
  };
  const hex = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
  const same = (a, b) => a[0] === b[0] && a[1] === b[1] && a[2] === b[2];
  const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);

  /* ── THE FILES ─────────────────────────────────────────── */
  const man = JSON.parse(fs.readFileSync(path.join(ROOT, 'art/manifest.json'), 'utf8'));
  const imgs = {}, fileBad = [];
  TYPES.forEach(t => {
    const f = path.join(ROOT, 'art', nameOf(t) + '.png');
    if (!fs.existsSync(f)) { fileBad.push(nameOf(t) + ' missing'); return; }
    if (!man.sprites.includes(nameOf(t))) fileBad.push(nameOf(t) + ' not in the manifest');
    const img = readPng(f);
    if (!img || img.w !== W || img.h !== H) { fileBad.push(`${nameOf(t)} ${img ? img.w + 'x' + img.h : '?'}, a room is ${W}x${H}`); return; }
    let clear = 0;
    for (let i = 3; i < img.px.length; i += 4) if (img.px[i] !== 255) clear++;
    if (clear) fileBad.push(`${nameOf(t)} has ${clear} see-through pixels`);
    imgs[t] = img;
  });
  ok(fileBad.length === 0, `every module, the empty bay included, has its picture: listed, ${W}x${H} (the room under its duct), solid (${fileBad.slice(0, 3).join('; ') || 'all good'})`);

  /* ── WHAT IS IN THEM (redrawn in update120) ──────────────
     A big display on the wall instead of a desk and a monitor; the deck
     thin, its back edge at 40 where the operator's boots are; the four
     air-lamp sockets in the top-right corner where the game lights them. */
  const TINT = { empty: '#5a6a86', engines: '#1aff8c', weapons: '#ff5566', shields: '#4db8ff', piloting: '#9fdcff',
                 oxygen: '#4dd8ff', medbay: '#3aff6a', reactor: '#ffb020', cloaking: '#cc44ff',
                 autorepair: '#ffd700', artillery: '#ff7c20', carbonite: '#9fe8ff',
                 tractor: '#5fe8ff' };                                   // update171
  const DECK_BACK = 45;
  const ship = new Ship('frigate', true, 170, 180), room = ship.rooms[0];
  const [ox, oy] = ship.stationSlot(room, 0), [, sy] = ship.stationSlot(room, 1);
  const opX = ox - room.x, opFeet = oy - room.floorTop + HULL_GRID.FEET, sideFeet = sy - room.floorTop + HULL_GRID.FEET;
  ok(opX === W / 2 && opFeet === DECK_BACK,
     `the operator stands in the middle (${opX}) with his boots on the back edge of the deck (${opFeet} against ${DECK_BACK})`);
  ok(sideFeet === H, `the two either side stand on the front of the deck — the lid of the duct (${sideFeet})`);
  ok(H - DECK_BACK <= 10, `and the deck is thin: ${H - DECK_BACK} px of the room, not a band of tiles (jj)`);
  const screenOf = (t, d) => imgs[t] && same(imgs[t].at(d.x + 1, d.y + d.h - 2), hex(TINT[t]).map((v, k) => Math.round([6, 9, 14][k] + (v - [6, 9, 14][k]) * 0.32)));
  const DISPLAYS = { piloting: [{ x: 25, y: 4, w: 50, h: 15 }],
                     reactor: [{ x: 26, y: 6, w: 14, h: 12 }, { x: 60, y: 6, w: 14, h: 12 }] };
  const NO_CONSOLE = ['empty', 'medbay', 'carbonite'];
  const consoleBad = TYPES.filter(t => imgs[t]).filter(t => {
    const has = (DISPLAYS[t] ?? [ROOM_DISPLAY]).every(d => screenOf(t, d));
    return NO_CONSOLE.includes(t) ? has : !has;
  });
  ok(consoleBad.length === 0, `a big display on the wall over the operator in every module somebody works in, none in the empty bay, the medbay or carbonite (${consoleBad.join(',') || 'all right'})`);
  ok(ROOM_DISPLAY.x + ROOM_DISPLAY.w / 2 === W / 2 && ROOM_DISPLAY.y + ROOM_DISPLAY.h < opFeet - 15,
     'centred over him, and high enough to read over the crew\'s heads');
  const stripBad = TYPES.filter(t => imgs[t] && t !== 'empty').filter(t => {
    const T = hex(TINT[t]);
    for (let y = 0; y < 2; y++) for (let x = 0; x < W; x++) if (dist(imgs[t].at(x, y), T) < 60) return true;
    return false;
  });
  ok(stripBad.length === 0, `no coloured strip between the duct and the module (${stripBad.join(',') || 'none'})`);
  const slabs = [0, 1, 2].map(i => ship.stationSlot(room, i)[0] - room.x).sort((a, b) => a - b);
  ok(JSON.stringify(slabs) === '[24,50,76]', `the three places in a module are at ${slabs.join(', ')}`);
  ok(imgs.carbonite && slabs.every(x => same(imgs.carbonite.at(x, 42), hex(TINT.carbonite))),
     'and the carbonite bay has a slab on each of them — a man frozen where he stood is frozen in one');
  ok(imgs.medbay && same(imgs.medbay.at(W / 2, 42), hex(TINT.medbay)) && !screenOf('medbay', ROOM_DISPLAY),
     'the medbay has its healing pod in the middle, not a console');
  const L = sb.OXYGEN_LAMPS;
  const socketsBad = TYPES.filter(t => imgs[t]).filter(t =>
    ![0, 1, 2, 3].every(i => same(imgs[t].at(W - L.right + i * (L.size + L.gap) + 1, L.y + 1), [4, 6, 10])));
  ok(socketsBad.length === 0, `every picture has the four air-lamp sockets exactly where the game lights them (${socketsBad.join(',') || 'all'})`);

  /* ── DRAWN IN THE ROOM ─────────────────────────────────── */
  const realSource = Assets.source, realGet = Assets.get, realTile = Assets.tileRect;
  const fakes = new Map();
  Assets.source = n => fakes.has(n) ? 'file' : realSource(n);
  Assets.get = n => fakes.has(n) ? fakes.get(n) : realGet(n);
  try {
    ok(moduleArt('engines') === null, 'no file: no picture');
    const pic = { width: W, height: H, tag: 'eng' };
    fakes.set('room_engines', pic);
    ok(moduleArt('engines') === pic, 'with the file, the picture');
    fakes.set('room_carbonite', { width: W, height: H });
    ok(SYSTEM_ALIASES.brig === 'carbonite' && moduleArt('brig') === fakes.get('room_carbonite'), 'an old save\'s brig shows the carbonite bay');
    fakes.set('room_default', { width: W, height: H });
    ok(moduleArt('empty') === fakes.get('room_default'), 'an empty bay is room_default');
    fakes.set('room_weapons', { width: 48, height: 48 });
    ok(moduleArt('weapons') === null, 'a picture the wrong size (an old 48px tile) is refused');

    const sys = ship.getSystem('engines'), sysRoom = ship.getRoomById(sys.roomId);
    const spy = (fn) => {
      const log = [], di = ctx.drawImage, fr = ctx.fillRect;
      ctx.drawImage = function (img, x, y, w, h) { log.push({ k: 'img', img, x, y, w, h }); };
      ctx.fillRect = function (x, y, w, h) { log.push({ k: 'rect', x, y, w, h, fill: ctx.fillStyle }); };
      Assets.tileRect = function () { log.push({ k: 'tile' }); };
      try { fn(); } finally { ctx.drawImage = di; ctx.fillRect = fr; Assets.tileRect = realTile; }
      return log;
    };
    sys.isDisabled = () => false;
    let log = spy(() => sys.draw(ctx));
    const d = log.find(e => e.img === pic);
    ok(d && d.x === sysRoom.x && d.y === sysRoom.floorTop && d.w === sysRoom.w && d.h === sysRoom.floorH,
       `the picture fills the room under its duct, unsquashed (${d ? [d.x - sysRoom.x, d.y - sysRoom.y, d.w, d.h].join(',') : 'not drawn'} vs 0,${HULL_GRID.VENT_H},${W},${H})`);
    ok(!log.some(e => e.k === 'tile'), 'and the old tiles are not drawn under it');
    ok(!log.some(e => e.k === 'rect' && e.fill === MODULE_DARK), 'powered: the lights are on');
    sys.isDisabled = () => true;
    log = spy(() => sys.draw(ctx));
    const dark = log.find(e => e.k === 'rect' && e.fill === MODULE_DARK);
    ok(dark && dark.x === sysRoom.x && dark.y === sysRoom.floorTop && dark.w === sysRoom.w && dark.h === sysRoom.floorH,
       'no power: the same room with the lights down');
    delete sys.isDisabled;
    fakes.delete('room_engines');
    log = spy(() => sys.draw(ctx));
    ok(log.some(e => e.k === 'tile') && !log.some(e => e.img === pic), 'no picture: the tiles drawn in code, as before');

    const bare = new Ship('scout', true, 170, 180);
    const empty = bare.rooms.find(r => !r.system);
    if (empty) {
      log = spy(() => bare._drawEmptyRoom(ctx, empty));
      const e = log.find(x => x.img === fakes.get('room_default'));
      ok(e && e.x === empty.x && e.y === empty.floorTop && e.w === empty.w && e.h === empty.floorH,
         'an empty bay is drawn from its picture, under the duct');
    } else ok(false, 'Bastet has an empty bay to look at');
  } finally {
    Assets.source = realSource; Assets.get = realGet; Assets.tileRect = realTile;
  }
})();

// ============================================================
section('307. The inside in the ship\'s colours (120): ducts, lifts and doors in the yard\'s trim, no frames, the emblem painted in, four air lamps, the repair in its pip, a lower crew on a thin deck');
// ============================================================
(function testUpdate120() {
  const fs = require('fs'), path = require('path');
  const ROOT = path.join(__dirname, '..');
  const sb = loadEngine();
  const { Ship, Save, Game, HULL_GRID, Assets, Renderer, YARD_TRIM, trimRgba, hullBuilder, moduleArt,
          OXYGEN_LAMPS, ROOM_DISPLAY, SYSTEM_DEFS, walkOffset } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const W = HULL_GRID.MODULE_W, H = HULL_GRID.MODULE_H - HULL_GRID.VENT_H;
  const spy = (fn) => {
    const log = [];
    const keep = { fillRect: ctx.fillRect, strokeRect: ctx.strokeRect, drawImage: ctx.drawImage, arc: ctx.arc, fillText: ctx.fillText };
    ctx.fillRect = function (x, y, w, h) { log.push({ k: 'fill', x, y, w, h, c: String(ctx.fillStyle) }); };
    ctx.strokeRect = function (x, y, w, h) { log.push({ k: 'stroke', x, y, w, h, c: String(ctx.strokeStyle) }); };
    ctx.drawImage = function (img, x, y, w, h) { log.push({ k: 'img', img, x, y, w, h }); };
    ctx.arc = function () { log.push({ k: 'arc' }); };
    ctx.fillText = function (t, x, y) { log.push({ k: 'text', t: String(t), x, y, c: String(ctx.fillStyle) }); };
    try { fn(); } finally { Object.assign(ctx, keep); }
    return log;
  };

  /* ── THE YARD'S TRIM ───────────────────────────────────── */
  const terra = new Ship('hauler', true, 170, 180), aqua = new Ship('frigate', true, 170, 180);
  ok(hullBuilder('hauler') === 'terra' && terra.trim() === YARD_TRIM.terra && aqua.trim() === YARD_TRIM.aquarius,
     'every hull is trimmed inside in the palette of the yard that built it');
  const vents = spy(() => terra._drawVents(ctx));
  const blue = vents.filter(e => /77,184,255|255,90,90|30,58,92/.test(e.c));
  const own = vents.filter(e => [YARD_TRIM.terra.base, YARD_TRIM.terra.seam, YARD_TRIM.terra.light].some(c => e.c.startsWith(`rgba(${c[0]},${c[1]},${c[2]}`)));
  ok(blue.length === 0 && own.length > 20, `the ducts of a Terra hull are drawn in Terra's trim, nothing blue (${own.length} own, ${blue.length} blue)`);
  const louvres = vents.filter(e => e.w === 1 && e.h === HULL_GRID.VENT_H - 3 - 6).length;   // thinner slats, update128
  ok(louvres >= terra.rooms.length * 20, `the duct under the deck is louvred all along, as it was on the ceiling (${louvres} slats)`);
  const walk = vents.filter(e => e.h === 3 && e.w === terra.rooms[0].w);
  ok(walk.length === terra.rooms.length && walk.every(e => terra.rooms.some(r => r.ventY === e.y)),
     'and a walkway plate on top of each duct — the deck the crew stand on');
  const grates = vents.filter(e => e.w === 7 && e.h === 2).length;
  ok(grates >= terra.rooms.length * 3, `with a small grate in it every so often (${grates})`);
  const lift = spy(() => { terra.elevators.trim = terra.trim(); terra.elevators.draw(ctx); });
  ok(!lift.some(e => /#2b4463|#24365a|#2a5f8a|#31597f|#16293f|43,68,99|77,140,200|36,54,90/.test(e.c)), 'and the lift trunks: no old blue in them');

  /* ── BULKHEADS: TWO ROOMS, ONE WALL, A DOOR IN IT ────────── */
  const walls = spy(() => terra._drawBulkheads(ctx)).filter(e => e.w === Ship.BULKHEAD && e.c === trimRgba(YARD_TRIM.terra.base, 1));
  const edges = new Set(terra.rooms.flatMap(r => [r.floor + '|' + r.x, r.floor + '|' + (r.x + r.w)]));
  ok(walls.length === edges.size, `a wall at every end of every compartment, once — shared ends drawn once (${walls.length} of ${edges.size})`);
  ok(walls.every(e => terra.rooms.some(r => r.floorTop === e.y && r.floorH === e.h)), 'from the ceiling down to the deck, never into the duct');
  const order = [];
  const realBH = terra._drawBulkheads, realEl = terra.elevators.draw;
  terra._drawBulkheads = function () { order.push('walls'); };
  const realDD = sb.Door.prototype.draw;
  sb.Door.prototype.draw = function () { order.push('door'); };
  try { terra.draw(ctx); } finally { delete terra._drawBulkheads; sb.Door.prototype.draw = realDD; }
  ok(order[0] === 'walls' && order.includes('door') && order.indexOf('door') > 0, 'the ship draws its walls, then the doors set into them');

  /* ── DOORS: AN OPENING, OR LEAVES WITH A LAMP — NEVER GREEN ── */
  const door = terra.doors.find(d => !d.isAirlock);
  door.openness = 1; door.open = true;
  let d = spy(() => door.draw(ctx, terra.trim()));
  const lampR = door.lampRect();
  ok(!d.some(e => /1aff8c|26,255,140|2a5a3a/i.test(e.c) && !(e.x === lampR.x && e.y === lampR.y)),
     'an open door is not lit green — only the lamp over it is (update122)');
  ok(!d.some(e => e.k === 'stroke') && !d.some(e => /ff5566|ffb020/.test(e.c)), 'nor framed — an opening, a header and a sill');
  ok(d.some(e => e.w === sb.Door.DRAWN_W && e.h === sb.Door.H && e.x === door.x - sb.Door.DRAWN_W / 2), 'the doorway is cut through the wall: a dark opening the height of the door');
  /* update128 (jj: "zrób cieńsze… próg na dole i na górze"): the LEAF is
     thinner than the old 4 px; only the header and the sill reach the
     frame's width, and nothing goes past the frame. */
  const F = sb.Door.FRAME, top = door.y - sb.Door.H / 2, bot = door.y + sb.Door.H / 2;
  ok(sb.Door.DRAWN_W < 4, `the leaf is thinner than it was (${sb.Door.DRAWN_W} px, was 4)`);
  ok(d.filter(e => e.k === 'fill' && !(e.x === lampR.x && e.y === lampR.y))
      .every(e => e.x >= door.x - F.w / 2 && e.x + e.w <= door.x + F.w / 2),
     `and nothing of it is wider than its frame (${F.w} px)`);
  ok(d.some(e => e.w === F.w && e.h === F.header && e.y + e.h === top) && d.some(e => e.w === F.w && e.h === F.sill && e.y === bot),
     'a header over it and a sill under it');
  ok(d.filter(e => e.k === 'fill' && e.c === trimRgba(sb.Door.STEEL.base, 1) && e.w === sb.Door.DRAWN_W && e.h >= sb.Door.POCKET).length >= 2,
     'open, the ends of both leaves still show in their pockets — it is a door, standing open');
  ok(lampR.y + lampR.h === top - F.header, 'the lamp sits ON the header — the door\'s own button');
  door.openness = 0; door.open = false;
  d = spy(() => door.draw(ctx, terra.trim()));
  ok(d.some(e => e.c === sb.Door.LAMP.shut && e.w === sb.Door.LAMP.w && e.h === sb.Door.LAMP.h), 'a shut one has the orange lamp over it (update122)');
  ok(d.some(e => e.c === trimRgba(sb.Door.STEEL.base, 1)) && !d.some(e => e.c === trimRgba(YARD_TRIM.terra.base, 1)),
     'and its leaves are plain grey steel — one colour for every door, so it stands out against any yard (jj)');
  const handed = [];
  const realDoor = sb.Door.prototype.draw;
  sb.Door.prototype.draw = function (c, trim) { handed.push(trim); };
  try { terra.draw(ctx); } finally { sb.Door.prototype.draw = realDoor; }
  ok(handed.length === terra.doors.length && handed.every(t => t === YARD_TRIM.terra), 'the ship hands every door its own trim');

  /* ── NO FRAMES, THE EMBLEM PAINTED IN ───────────────────── */
  const realSource = Assets.source, realGet = Assets.get;
  const fakes = new Map();
  Assets.source = n => fakes.has(n) ? 'file' : realSource(n);
  Assets.get = n => fakes.has(n) ? fakes.get(n) : realGet(n);
  try {
    const plain = { width: W, height: H, tag: 'plain' }, yard = { width: W, height: H, tag: 'terra' };
    fakes.set('room_engines', plain);
    ok(moduleArt('engines', 'terra') === plain, 'a yard with no picture of its own takes the plain one');
    fakes.set('room_engines_terra', yard);
    ok(moduleArt('engines', 'terra') === yard && moduleArt('engines') === plain, 'and its own when it has one');
    const sys = terra.getSystem('engines');
    ok(sys.yard === 'terra', 'a module knows whose yard its room is in');
    const icons = [];
    const realIcon = Renderer.drawSystemIcon;
    Renderer.drawSystemIcon = (c, type) => icons.push(type);
    let log;
    try { log = spy(() => sys.draw(ctx)); } finally { Renderer.drawSystemIcon = realIcon; }
    ok(log.some(e => e.img === yard), 'the module is drawn from its yard\'s picture');
    ok(!log.some(e => e.k === 'stroke'), 'with no frame round it (jj: a door or an opening between rooms, nothing else)');
    ok(icons.length === 0, 'and no badge stuck on it — its emblem is painted on the wall plate');
    fakes.clear();
    Renderer.drawSystemIcon = (c, type) => icons.push(type);
    try { spy(() => sys.draw(ctx)); } finally { Renderer.drawSystemIcon = realIcon; }
    ok(icons.includes('engines'), 'with no picture the old badge is still there, so the room says what it is');

    /* ── THE REPAIR, IN THE PIP ───────────────────────────── */
    sys.damagedLevels = 1; sys.repairProgress = 0.5;
    log = spy(() => sys.draw(ctx));
    ok(!log.some(e => e.k === 'arc'), 'no repair ring in the room any more');
    Save.load(); Save.startRun();
    terra._allocateDefaultPower?.();
    log = spy(() => Renderer.drawHUD({ playerShip: terra }));
    const MP = Renderer.modulePip();
    const fills = log.filter(e => e.c === '#1aff8c' && e.h === MP.h);
    ok(fills.some(e => e.w === MP.w / 2), `the broken pip being repaired fills from the left, half way at half done (${fills.map(e => e.w).join(',') || 'none'})`);
    sys.repairProgress = 0;
    log = spy(() => Renderer.drawHUD({ playerShip: terra }));
    ok(!log.some(e => e.c === '#1aff8c' && e.h === 9 && e.w < 22), 'and nothing fills before anybody starts on it');
    sys.damagedLevels = 0;

    /* ── EVERY MODULE'S DISPLAY SAYS WHAT IT IS DOING ──────── */
    const o2 = terra.getSystem('oxygen');
    ['oxygen', 'piloting', 'engines', 'weapons', 'shields', 'reactor', 'medbay'].forEach(t => fakes.set('room_' + t + '_terra', { width: W, height: H }));
    terra._allocateDefaultPower();
    const texts = () => spy(() => terra._drawModuleScreens(ctx)).filter(e => e.k === 'text');
    let tx = texts();
    const at = (re) => tx.find(e => re.test(e.t));
    const air = at(/^O₂ \d+%$/);
    ok(air && air.x === o2.roomX + ROOM_DISPLAY.x + ROOM_DISPLAY.w / 2 && air.y < o2.roomY + ROOM_DISPLAY.y + ROOM_DISPLAY.h,
       `the ship's air is written on the oxygen bay's display (${air ? air.t : 'nothing'})`);
    ok(spy(() => terra.draw(ctx)).some(e => e.k === 'text' && /^O₂ \d+%$/.test(e.t)), 'every time the ship is drawn');
    // nobody at the helm: the cockpit says so, and neither adds anything
    ok(at(/^NO PILOT$/) && at(/^EVD \+0%$/), `no pilot: NO PILOT on the helm, +0% on the drive (${tx.map(e => e.t).join(' | ')})`);
    // a pilot and an engineer at their consoles: each says its own share
    const pilotSys = terra.getSystem('piloting'), engSys = terra.getSystem('engines');
    const crew = sb.makeStartingCrew();
    crew.forEach(c => terra.addCrew(c));
    const put = (c, sys) => { const r = terra.getRoomById(sys.roomId); [c.x, c.y] = terra.stationSlot(r, 0); c.roomId = r.id; c.homeRoomId = r.id; };
    put(crew[0], pilotSys); put(crew[1], engSys);
    terra.update(0.01);
    const sh = terra.evasionShares();
    ok(sh.hasPilot && sh.cockpit > 0 && sh.engines > 0, `with a pilot, the helm and the drive each add their share (${sh.cockpit.toFixed(2)} + ${sh.engines.toFixed(2)})`);
    tx = texts();
    const shown = tx.filter(e => /^EVD \+\d+%$/.test(e.t)).map(e => e.t).sort();
    const want = [`EVD +${Math.round(sh.cockpit * 100)}%`, `EVD +${Math.round(sh.engines * 100)}%`].sort();
    ok(JSON.stringify(shown) === JSON.stringify(want), `and the two displays say exactly that (${shown.join(', ')})`);
    // gravity down: the drive's display says so
    const realG = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(terra), 'zeroG');
    Object.defineProperty(terra, 'zeroG', { get: () => true, configurable: true });
    try { ok(spy(() => terra._drawModuleScreens(ctx)).some(e => e.k === 'text' && e.t === 'GRAV OFF'), 'gravity down: GRAV OFF on the engines'); }
    finally { delete terra.zeroG; }
    // the guns: the chance to hit the ship we are fighting
    terra.foe = null;
    ok(texts().some(e => e.t === 'NO TARGET'), 'no fight: the guns say NO TARGET');
    const foe = new Ship('enemy_raider', false, 850, 120);
    Object.defineProperty(foe, 'evasion', { get: () => 0.3, configurable: true });
    terra.foe = foe;
    ok(texts().some(e => e.t === 'HIT 70%'), `in a fight: HIT 70% against a ship that dodges 30% (${texts().filter(e => /^HIT/.test(e.t)).map(e => e.t)})`);
    // the reactor: its core temperature
    terra.reactorHeat = 50;
    tx = texts();
    ok(tx.some(e => e.t === `${sb.heatCelsius(50)}°`) && tx.some(e => e.t === '50%'), `the reactor shows its core temperature (${sb.heatCelsius(50)}°) and its heat`);
    // no power: nothing on the screen
    engSys.isDisabled = () => true;
    const inEng = e => e.x === engSys.roomX + ROOM_DISPLAY.x + ROOM_DISPLAY.w / 2 && e.y > engSys.roomY && e.y < engSys.roomY + H;
    engSys.isDisabled = () => false;
    ok(texts().some(inEng), 'powered, the drive\'s display has its line');
    engSys.isDisabled = () => true;
    try { ok(!texts().some(inEng), 'a module with no power shows nothing — its lights are down'); }
    finally { delete engSys.isDisabled; }
    const med = new Ship('frigate', true, 170, 180), mb = med.getSystem('medbay');
    med._allocateDefaultPower();
    ok(!spy(() => med._drawModuleScreens(ctx)).some(e => e.k === 'text' && e.x > mb.roomX && e.x < mb.roomX + W && e.y > mb.roomY && e.y < mb.roomY + H),
       'and the medbay has no display to write on');
    fakes.clear();
    ok(spy(() => terra._drawModuleScreens(ctx)).length === 0, 'nothing anywhere when there are no pictures with displays to write on');
  } finally { Assets.source = realSource; Assets.get = realGet; }

  /* ── A LOWER CREW ON A THIN DECK ───────────────────────── */
  ok(HULL_GRID.WALK_FRAC === 0.9 && Ship.OPERATOR_LIFT === 5, 'the walk line is lower and the operator stands only a step behind');
  const room = terra.rooms[0];
  const [, wy] = terra.stationSlot(room, 1);
  ok(wy + HULL_GRID.FEET === room.ventY, `a man's boots are on the deck — the lid of the duct (${wy + HULL_GRID.FEET - room.y} vs ${room.ventY - room.y})`);
  const dy = terra.floorDoorY(room.floor);
  ok(dy + sb.ElevatorShaft.DOOR_H / 2 === wy + HULL_GRID.FEET, 'and every doorway and lift landing stands on that deck — its sill at their boots');

  /* ── THE FILES IN EVERY YARD'S COLOURS ─────────────────── */
  const man = JSON.parse(fs.readFileSync(path.join(ROOT, 'art/manifest.json'), 'utf8'));
  const yards = Object.keys(YARD_TRIM).filter(k => !k.startsWith('_'));
  const types = ['empty', ...Object.keys(SYSTEM_DEFS)];
  const missing = [];
  yards.forEach(y => types.forEach(t => {
    const n = (t === 'empty' ? 'room_default' : 'room_' + t) + '_' + y;
    if (!fs.existsSync(path.join(ROOT, 'art', n + '.png')) || !man.sprites.includes(n)) missing.push(n);
  }));
  ok(missing.length === 0, `every module in every yard's colours, on disk and listed (${missing.slice(0, 3).join(',') || 'all ' + yards.length * types.length}`);
})();

// ============================================================
section('308. Engines on top and underneath, guns on the plate (121): nacelles bolted to the hull at the stern, turrets on mounts, the two hulls further apart');
// ============================================================
(function testUpdate121() {
  const sb = loadEngine();
  const { Ship, HULL_GRID, HULL_ART, SHIP_LAYOUTS, Renderer, YARD_TRIM, trimRgba } = sb;
  const ctx = initRenderer(sb);
  const G = HULL_GRID, M = G.MARGIN;

  /* ── THE NACELLES ──────────────────────────────────────── */
  const bad = [];
  Object.keys(SHIP_LAYOUTS).forEach(k => [true, false].forEach(you => {
    const sh = new Ship(k, you, 300, 200), g = sh.hullArtGeometry();
    if (SHIP_LAYOUTS[k].isStation) return;
    const b = g.bounds;
    // nothing sticks out of the stern more than the nozzles' overhang
    const stern = you ? Math.min(...g.engines.map(e => e.x)) : Math.max(...g.engines.map(e => e.x + e.w));
    const reach = you ? (b.x - M) - stern : stern - (b.x + b.w + M);
    if (reach > HULL_ART.NACELLE.overhang) bad.push(`${k}/${you ? 'you' : 'them'} ${reach}px past the stern`);
    // and every nacelle overlaps the plate — it is bolted on, not floating
    g.engines.forEach(e => {
      const touches = g.plate.some(p => e.x < p.x + p.w && e.x + e.w > p.x && e.y < p.y + p.h && e.y + e.h > p.y);
      if (!touches) bad.push(`${k} ${e.side} nacelle floats`);
    });
  }));
  ok(bad.length === 0, `two nacelles bolted to the top and the underside, only their nozzles past the stern (${bad.slice(0, 3).join('; ') || 'all'})`);

  /* ── MORE ROOM BETWEEN THE TWO HULLS ───────────────────── */
  const span = (k, you, wx) => {
    const g = new Ship(k, you, wx, 0).hullArtGeometry(), b = g.bounds;
    const xs = [b.x - M, b.x + b.w + M, ...g.engines.flatMap(e => [e.x, e.x + e.w]), ...g.prows.flatMap(p => [p.x, p.x + p.w])];
    return [Math.min(...xs), Math.max(...xs)];
  };
  const p = span('hauler', true, Ship.PLAYER_STATION.x), e = span('enemy_khnum', false, Ship.ENEMY_STATION.x);
  ok(e[0] - p[1] >= 120, `the gap the shells cross grew — Hapi to a Terra hull: ${(e[0] - p[1]).toFixed(0)} px (was about 70)`);
  ok(p[0] >= 125 && e[1] <= 1280, `and both still fit: player from ${p[0]}, enemy to ${e[1]}`);

  /* ── THE GUNS SIT ON THE PLATE ─────────────────────────── */
  const sh = new Ship('hauler', true, Ship.PLAYER_STATION.x, Ship.PLAYER_STATION.y);
  sh._allocateDefaultPower();
  const mounts = sh.weaponMounts(), b = sh.roomBounds();
  ok(mounts.length > 0 && mounts.every(m => m.y + m.h >= b.y - M && m.y + m.h <= b.y - M + 4),
     `every gun's underside is on the plate (${mounts.map(m => m.y + m.h - (b.y - M)).join(',')} px into it)`);
  const top = sh.hullArtGeometry().engines.find(e => e.side === 'top');
  ok(mounts.every(m => m.x >= top.x + top.w || m.x + m.w <= top.x), 'and none sits on the top nacelle');
  // every hull, both sides, every slot filled — a short hull (Khnum flown
  // by you) centres its gun right over the nacelle unless the row steps aside
  const onNacelle = [];
  Object.keys(SHIP_LAYOUTS).forEach(k => { if (SHIP_LAYOUTS[k].isStation) return; [true, false].forEach(you => {
    const s2 = new Ship(k, you, you ? Ship.PLAYER_STATION.x : Ship.ENEMY_STATION.x, 200);
    for (let i = 0; i < (SHIP_LAYOUTS[k].weaponSlots || 1); i++) { try { s2.installWeapon('laser_basic', i); } catch (e) { /* full */ } }
    const t2 = s2.hullArtGeometry().engines.find(e => e.side === 'top');
    s2.weaponMounts().forEach(q => { if (!(q.x >= t2.x + t2.w || q.x + q.w <= t2.x)) onNacelle.push(k + (you ? '/you' : '/them')); });
  }); });
  ok(onNacelle.length === 0, `on no hull does a gun stand on the top nacelle (${onNacelle.join(', ') || 'none'})`);
  const log = [];
  const keep = { fillRect: ctx.fillRect, fill: ctx.fill };
  ctx.fillRect = function (x, y, w, h) { log.push({ x, y, w, h, c: String(ctx.fillStyle) }); };
  ctx.fill = function () { log.push({ k: 'fill', c: String(ctx.fillStyle) }); };
  try { sh._drawWeaponMounts(ctx); } finally { Object.assign(ctx, keep); }
  ok(log.some(r => r.k === 'fill' && r.c === trimRgba(sh.trim().base, 1)), 'each stands on a mount in the ship\'s own colours');
  const m = mounts[0];
  const boxes = log.filter(r => r.h === 5 && r.w === 8 || (r.h === 5 && r.y < m.y));
  ok(boxes.length > 0 && boxes.every(r => r.y < m.y), `its charge boxes are above the gun now, the gun itself down on the hull (${boxes.length})`);
  // the housing on the hull is steel, not the dark UI badge
  /* update126: the guns are painted pixel by pixel now (WeaponArt), so
     the housing is a fillRect, not a path fill — the question is the
     same: steel on the hull, the UI's blue on a card. */
  const fills = [];
  ctx.fillRect = function () { fills.push(String(ctx.fillStyle)); };
  try { Renderer.drawWeaponIcon(ctx, 'laser_basic', 0, 0, 44, 18, { onHull: true }); } finally { ctx.fillRect = keep.fillRect; }
  ok(fills.includes('#6c7586'), `a gun on the hull has a steel housing (${fills.slice(0, 3)})`);
  fills.length = 0;
  ctx.fillRect = function () { fills.push(String(ctx.fillStyle)); };
  try { Renderer.drawWeaponIcon(ctx, 'laser_basic', 0, 0, 44, 18, {}); } finally { ctx.fillRect = keep.fillRect; }
  ok(fills.length > 0 && !fills.includes('#6c7586'), 'while the same gun on a card in the shop keeps its badge look');
  // and a mounted gun really asks for the hull look on its way through Weapon#draw
  const asked = [], keepIcon = Renderer.drawWeaponIcon;
  Renderer.drawWeaponIcon = function (c, key, x, y, w, h, o) { asked.push(!!(o && o.onHull)); };
  try { sh._drawWeaponMounts(ctx); } finally { Renderer.drawWeaponIcon = keepIcon; }
  ok(asked.length > 0 && asked.every(Boolean), `a gun on the ship is drawn with its steel housing (${asked.join(',')})`);
})();

// ============================================================
section('309. The reactor on its core, door lamps, films in OPTIONS (122): the power bar\'s reactor pips up its core, a lamp over every door — green, orange, red — and ENTER to skip');
// ============================================================
(function testUpdate122() {
  const sb = loadEngine();
  const { Ship, ShipSystem, HULL_GRID, Door, Save, Game, JumpScene, Input, Renderer, CrewMember } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const fs = require('fs'), path = require('path');
  const hit = (a, b) => a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  const spyFills = fn => {
    const log = [], keep = ctx.fillRect;
    ctx.fillRect = function (x, y, ww, hh) { log.push({ x, y, w: ww, h: hh, c: String(ctx.fillStyle) }); };
    try { fn(); } finally { ctx.fillRect = keep; }
    return log;
  };

  /* ── NO LEVEL LAMPS IN THE MODULES (jj: "rezygnujemy") ─── */
  ok(typeof ShipSystem.prototype.levelLamps === 'undefined' && typeof sb.LEVEL_LAMPS === 'undefined',
     'no lamps for the level in every module — tried and dropped (jj: "źle to wygląda i jest niepotrzebne")');

  /* ── ONE LIST OF PIPS FOR THE BAR AND THE CORE ─────────── */
  Save.load(); Save.startRun();
  const ps = new Ship('frigate', true, 145, 180);
  ps._allocateDefaultPower();
  ok(typeof Renderer.reactorPips === 'function', 'Renderer.reactorPips: the reactor column\'s pips, as a list');
  let pips = Renderer.reactorPips(ps);
  const R = ps.reactor;
  ok(pips.length === (R.capacity ?? R.ratedPower) + (R.cyborgBonus ?? 0), `one per unit of the core (${pips.length})`);
  ok(pips.filter(p => p.kind === 'free' || p.kind === 'lift').length === ps.availablePower(), `lit for what is left to spend (${ps.availablePower()})`);
  R.sys.damagedLevels = 2; R.sys.repairProgress = 0.4;
  pips = Renderer.reactorPips(ps);
  ok(pips.slice(-2).every(p => p.kind === 'broken' && p.fill === '#cc2233'), 'the top two broken: red');
  ok(pips.filter(p => p.repairing).length === 1 && pips[pips.length - 2].repairing, 'the lowest broken one is the one being repaired');
  // the bar draws exactly that list
  const barFills = spyFills(() => Renderer.drawHUD({ playerShip: ps, enemyShip: null, inCombat: true }));
  const want = pips.map(p => p.fill);
  // update130: the bar lies under the row, first pip on the left
  const got = (Renderer.reactorBarRect()?.fills ?? []).map(String);
  ok(barFills.length > 0 && got.length === want.length && want.every((c, i) => got[i] === c), `the power bar is drawn from it, left to right (${got.join(' ')})`);

  /* ── ON THE CORE, OVER HIS HEAD ────────────────────────── */
  const sys = R.sys;
  const { panel, pips: rects } = ps.reactorCoreRects();
  ok(rects.length === pips.length, `a place on the core for every pip (${rects.length})`);
  const inner = { x: sys.roomX, y: sys.roomY, w: HULL_GRID.MODULE_W, h: HULL_GRID.MODULE_H - HULL_GRID.VENT_H };
  ok(panel.x >= inner.x && panel.x + panel.w <= inner.x + inner.w && panel.y >= inner.y, 'inside the reactor room');
  const mid = inner.x + inner.w / 2;
  ok(Math.abs(panel.x + panel.w / 2 - mid) <= 1, 'in the middle of the module');
  sb.moduleScreens('reactor').forEach(d => ok(!hit(panel, { x: inner.x + d.x, y: inner.y + d.y, w: d.w, h: d.h }), 'between the two little displays, not over them'));
  ok(panel.h >= 30, `up the whole core — the operator may stand in front of it (jj) (${panel.h} px)`);
  ok(rects.every(r => r.x >= panel.x && r.x + r.w <= panel.x + panel.w && r.y >= panel.y && r.y + r.h <= panel.y + panel.h), 'every pip on the panel');
  ok(rects.every((r, i) => i === 0 || (r.y < rects[i - 1].y && r.x === rects[0].x)), 'one column, the bottom pip first — the bar\'s order');
  ok(rects.every(r => r.w >= 2 && r.h >= 2), 'big enough to read at a sixteen-unit core too, if it gets one');
  // the core is part of the picture: the suites have no PNGs, so lend it one
  const realArt = sb.moduleArt;
  sb.moduleArt = () => ({ width: 100, height: 50 });
  let log;
  try { log = spyFills(() => ps._drawReactorCore(ctx)); } finally { sb.moduleArt = realArt; }
  ok(spyFills(() => ps._drawReactorCore(ctx)).length === 0 || realArt('reactor', null), 'no picture, no core: nothing drawn on the code tile');
  ok(pips.every((p, i) => log.some(e => e.x === rects[i].x && e.y === rects[i].y && e.c === p.fill)), 'drawn in the bar\'s colours');
  ok(log.some(e => e.c === '#1aff8c' && e.x === rects[pips.length - 2].x), 'the repair fills its pip in green, as on the bar');
  const order = [];
  const realCore = Ship.prototype._drawReactorCore, realScreens = Ship.prototype._drawModuleScreens;
  ps._drawReactorCore = function () { order.push('core'); };
  ps._drawModuleScreens = function () { order.push('screens'); };
  try { ps.draw(ctx); } finally { delete ps._drawReactorCore; delete ps._drawModuleScreens; }
  ok(order.join() === 'screens,core', 'Ship#draw puts it in, with the module screens');
  const big = new Ship('frigate', true, 145, 180);
  big.reactor.level = 16; big._allocateDefaultPower();
  const bigR = big.reactorCoreRects();
  ok(bigR.pips.length === Renderer.reactorPips(big).length && bigR.pips.every(r => r.y >= bigR.panel.y && r.h >= 2)
     && bigR.pips[1].x > bigR.pips[0].x && bigR.pips[1].y === bigR.pips[0].y, 'past eight, two to a row, and it still fits');
  const enemy = new Ship('frigate', false, 780, 200);
  sb.moduleArt = () => ({ width: 100, height: 50 });
  try { log = spyFills(() => enemy._drawReactorCore(ctx)); } finally { sb.moduleArt = realArt; }
  ok(log.length === Renderer.reactorPips(enemy).length + 1, 'his reactor shows his');
  const g = fs.readFileSync(path.join(__dirname, '..', 'js', 'renderer.js'), 'utf8');
  ok(/const pips = reactorPips\(ship\);/.test(g) && g.split('const capBase = r.capacity ?? rated;').length === 2,
     'the bar has no copy of the logic left — it walks the list');

  /* ── THE LAMP OVER EVERY DOOR ──────────────────────────── */
  const L = Door.LAMP;
  ok(L.w * L.h > 4 && L.w >= 4, `a bigger lamp than the 2x2 it was (${L.w}x${L.h}, jj: "troszkę większa")`);
  const door = new Door(null, null, 300, 200, false);
  door.mode = 'open'; door.openness = 1; door.open = true;
  ok(door.lampState() === 'open', 'open: green');
  door.openness = 0.5; door.open = false;
  ok(door.lampState() === 'shut', 'still sliding: not open yet, orange');
  door.openness = 0;
  ok(door.lampState() === 'shut', 'shut: orange');
  door.hacked.enemy = true;
  ok(door.lampState() === 'damaged' && door.damaged, 'a lock a boarding party cracked: red');
  door.hacked.enemy = false; door.hacked.player = true; door.openness = 1;
  ok(door.lampState() === 'damaged', 'cracked by either side, open or shut: red');
  const air = new Door(null, null, 300, 200, true);
  ok(air.lampState() === 'shut', 'an airlock shut: orange');
  air.openness = 1; air.open = true;
  ok(air.lampState() === 'damaged', 'an airlock standing open is a hole to space: red, never green');
  air.breached = true;
  ok(air.lampState() === 'damaged', 'a smashed hatch: red');
  ok(L.open === '#1aff8c' && /^#ff9a20$/i.test(L.shut) && L.damaged === '#ff2d44', 'green, orange, red');
  const lr = door.lampRect();
  ok(lr.y + lr.h < door.y - Door.H / 2 && Math.abs(lr.x + lr.w / 2 - door.x) <= 1, 'over the door, centred, clear of its header');
  door.hacked.player = false; door.openness = 1; door.open = true;
  log = spyFills(() => door.draw(ctx));
  ok(log.some(e => e.c === L.open && e.x === lr.x && e.y === lr.y && e.w === L.w && e.h === L.h), 'an open door is drawn with its green lamp now (it had none)');
  door.openness = 0; door.open = false; door.hackT = 0.1;
  log = spyFills(() => door.draw(ctx));
  ok(log.some(e => e.c === L.damaged && e.x === lr.x), 'a lock being worked blinks red');
  door.hackT = 0.3;
  log = spyFills(() => door.draw(ctx));
  ok(log.some(e => e.c === L.shut && e.x === lr.x), '…and orange by turns');
  door.hackT = 0;
  log = spyFills(() => air.draw(ctx));
  ok(log.some(e => e.c === L.damaged && e.w === L.w), 'the airlock wears the same lamp');

  /* ── THE FILMS IN OPTIONS ─────────────────────────────── */
  Save.load();
  ok(Save.getSetting('jumpFilms') === true, 'films are on by default');
  const gsrc = fs.readFileSync(path.join(__dirname, '..', 'js', 'game.js'), 'utf8');
  ok(/JumpScene\.enabled = _filmsOn\(\)/.test(gsrc), 'Game.init asks the setting instead of always turning them on');
  T.STATE = 'options';
  const M = Input.mouse;
  const clickAt = (x, y) => {
    M.x = x; M.y = y; M.leftPressed = true;
    try { T._updateOptions(0); } finally { M.leftPressed = false; }
  };
  // find the switch on the drawn screen
  const words = captureText(ctx, () => T._drawOptions(ctx));
  const label = words.find(w2 => w2.t === 'JUMP FILMS');
  const state = words.find(w2 => w2.t === 'ON');
  ok(label && state, 'OPTIONS shows JUMP FILMS with its state');
  JumpScene.enabled = true;
  clickAt(state.x, state.y - 6);
  ok(Save.getSetting('jumpFilms') === false && JumpScene.enabled === false, 'a click turns them off — the setting and the films at once, no restart');
  const after = captureText(ctx, () => T._drawOptions(ctx));
  ok(after.some(w2 => w2.t === 'OFF'), 'and it says OFF');
  const stored = JSON.parse(sb.localStorage.getItem('moonwars_settings_v1') || '{}');
  ok(stored.jumpFilms === false, 'written to the settings, so it survives F5');
  clickAt(state.x, state.y - 6);
  ok(Save.getSetting('jumpFilms') === true && JumpScene.enabled === true, 'a second click turns them back on');
  const btns = after.filter(w2 => w2.t === 'BACK' || w2.t === 'MUTE');
  // the switch's box is state.y - 22 .. state.y + 12 with its hint line under it; a button's box starts 26 over its label
  ok(btns.length === 2 && btns.every(b => b.y - 26 >= state.y + 12 + 20), `BACK and MUTE moved down, clear of the new row and its hint (${btns.map(b => b.t + '@' + b.y).join(', ')})`);
  sb.localStorage.setItem('moonwars_settings_v1', JSON.stringify({ masterVolume: 0.5 }));
  Save.load();
  ok(Save.getSetting('jumpFilms') === true, 'settings saved before the switch existed: films on');

  /* ── ENTER SKIPS ──────────────────────────────────────── */
  ok(/ENTER/.test(JumpScene.SKIP_HINT), `the hint says ENTER (${JumpScene.SKIP_HINT})`);
  JumpScene.enabled = true; JumpScene.reset();
  const sh = new Ship('frigate', true, 145, 180);
  JumpScene.jump(sh);
  JumpScene.update(0.1);
  T.STATE = 'map'; T.paused = false;
  const realP = Input.isPressed;
  Input.isPressed = c => c === 'Enter';
  try { T._step(0.016); } finally { Input.isPressed = realP; }
  ok(!JumpScene.active() && T.paused === false, 'ENTER ends the film, and does not pause the game');
  JumpScene.arrive(sh, new Ship('frigate', false, 780, 200));
  const hintArr = captureText(ctx, () => JumpScene.drawOverlay(ctx, 1280, 720));
  ok(hintArr.some(w2 => w2.t === JumpScene.SKIP_HINT), 'the arrival says it can be skipped too');
  Input.isPressed = c => c === 'NumpadEnter';
  try { T._step(0.016); } finally { Input.isPressed = realP; }
  ok(!JumpScene.active(), 'the keypad ENTER as well');
  JumpScene.reset(); JumpScene.enabled = false;
})();

// ============================================================
section('310. The title screen (123): your hull drifting past the Moon, a line under ENTER BASE, NEW GAME behind a question');
// ============================================================
(function testUpdate123() {
  const sb = loadEngine();
  const { Save, Base, Game, Input, Renderer, Ship } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const W = Renderer.getWidth(), H = Renderer.getHeight();
  Save.load();
  T.STATE = 'menu';

  /* ── THE BUTTONS ──────────────────────────────────────── */
  const r = [0, 1, 2].map(i => T._menuRect(i));
  ok(r[0].x <= 640 && r[0].x + r[0].w >= 640 && r[0].y <= 360 && r[0].y + r[0].h >= 360, 'ENTER BASE is where it always was (the browser test clicks 640,360)');
  ok(r[1].y - (r[0].y + r[0].h) >= 24, 'room under ENTER BASE for its line');
  ok(r[2].y + r[2].h < H * 0.75, 'the three buttons end well above the flyby');
  const words = captureText(ctx, () => T._drawMenu(ctx));
  const st = words.find(w => /CC .* hull.* in the hangar .* in the barracks/.test(w.t));
  ok(!!st && st.y > r[0].y + r[0].h && st.y < r[1].y, `under ENTER BASE: what the base holds (${st && st.t})`);
  ok(words.some(w => w.t === 'NEW GAME'), 'NEW GAME is on the title screen');

  /* ── THE LINE UNDER ENTER BASE ────────────────────────── */
  ok(T._menuStatus().text === `${Base.cc()} CC  ·  ${Base.ships().length} hull${Base.ships().length === 1 ? '' : 's'} in the hangar  ·  ${Base.crew().length} in the barracks`,
     'no contract out: money, hulls, men');
  Save.startRun();
  ok(!/CONTRACT/.test(T._menuStatus().text), 'a blank run record is not a contract in the air (shipKey says so)');
  Save.updateRun({ mission: 'patrol', finalSector: 3, shipKey: 'frigate', sector: 2 });
  ok(/^CONTRACT IN THE AIR — Border Patrol, sector 2\/3$/.test(T._menuStatus().text), `a contract out says which and how far (${T._menuStatus().text})`);

  /* ── THE HULL THAT FLIES PAST ─────────────────────────── */
  ok(T._menuHullKey() === 'frigate', 'the hull out on the contract is the one that flies past');
  const ship = T._menuShipFor();
  ok(ship && ship.layoutKey === 'frigate' && ship.roofAlpha === 1 && ship.crew.length === (Save.getRun()?.crew?.length ?? 0),
     'closed, manned by the contract\'s own crew (none on this record) — update131');
  ok(T._menuShipFor() === ship, 'built once and kept, not every frame');
  Save.updateRun({ shipKey: null });
  ok(T._menuHullKey() === (Base.ships()[0]?.key ?? 'scout'), 'no contract: the first hull in the hangar');
  const f0 = T._menuFlyby(0, ship), f1 = T._menuFlyby(10, ship);
  ok(f0.x + f0.b.w * f0.s < 0, 'it comes in from off the left edge');
  ok(f1.x > f0.x, 'and moves right');
  ok(f0.s < 1, `smaller than in a fight (${f0.s})`);
  const top = f1.y - f1.b.h * f1.s / 2;
  ok(top > r[2].y + r[2].h, `it flies under the buttons, never across them (${Math.round(top)} vs ${r[2].y + r[2].h})`);
  let drew = 0;
  const realDraw = Ship.prototype.draw;
  Ship.prototype.draw = function () { drew++; };
  try { T._drawMenu(ctx); } finally { Ship.prototype.draw = realDraw; }
  ok(drew === 2, 'the title screen draws it — and, since update125, the raider on its tail');

  /* ── NEW GAME ASKS FIRST ──────────────────────────────── */
  const M = Input.mouse;
  const click = (x, y) => { M.x = x; M.y = y; M.leftPressed = true; try { T._updateMenu(0); } finally { M.leftPressed = false; } };
  Base.earn(500);
  const cc = Base.cc();
  click(r[2].x + 20, r[2].y + 20);
  ok(T.menuConfirm === true && Base.cc() === cc, 'NEW GAME only asks — nothing is wiped yet');
  const conf = captureText(ctx, () => T._drawMenu(ctx));
  ok(conf.some(w => /START A NEW GAME/.test(w.t)) && conf.some(w => /cannot be undone/.test(w.t)), 'and says what it would wipe');
  const R = T._menuConfirmRects();
  click(r[0].x + 20, r[0].y + 20);
  ok(T.STATE === 'menu' && T.menuConfirm === false, 'a click outside the question closes it and does nothing else (no ENTER BASE through it)');
  click(r[2].x + 20, r[2].y + 20);
  click(R.keep.x + 10, R.keep.y + 10);
  ok(T.menuConfirm === false && Base.cc() === cc, 'KEEP MY GAME keeps it');
  click(r[2].x + 20, r[2].y + 20);
  const realP = Input.isPressed;
  Input.isPressed = c => c === 'Escape';
  try { T._updateMenu(0); } finally { Input.isPressed = realP; }
  ok(T.menuConfirm === false && Base.cc() === cc, 'ESC keeps it too');
  Save.updateRun({ shipKey: null });
  const before = T._menuShipFor();
  Save.updateRun({ shipKey: 'frigate' });
  click(r[2].x + 20, r[2].y + 20);
  click(R.wipe.x + 10, R.wipe.y + 10);
  ok(T._menuShipFor() !== before, 'the hull that flies past is built again after a wipe — not the old one, even of the same kind');
  ok(T.menuConfirm === false && Base.cc() !== cc && !Save.getRun(), 'WIPE AND START: the money and the contract are gone');
  ok(T.STATE === 'menu' && /CC/.test(T._menuStatus().text), 'and you are back on the title screen with a fresh base');
  ok(T._menuHullKey() === (Base.ships()[0]?.key ?? 'scout'), 'flying the hull a new game starts with');
})();

// ============================================================
section('311. The crew (124): bigger men with two bottles on their backs, their backs to us at a console, faces when they eat or heal, and a face of their own on every card');
// ============================================================
(function testUpdate124() {
  const fs = require('fs'), path = require('path');
  const sb = loadEngine();
  const { CrewArt, CrewMember, Animation, Renderer, Save, Base, Commander, Game } = sb;
  const ctx = initRenderer(sb);
  Save.load();

  /* ── LOADED, AND KNOWN TO THE LOADER ──────────────────── */
  const html = fs.readFileSync(path.join(__dirname, '..', 'index.html'), 'utf8');
  ok(html.indexOf('js/crewart.js') > html.indexOf('js/animation.js') && html.indexOf('js/crewart.js') < html.indexOf('js/crew.js'),
     'index.html loads crewart.js after animation.js and before crew.js');
  const gsrc = fs.readFileSync(path.join(__dirname, '..', 'js', 'game.js'), 'utf8');
  ok(/name: 'CrewArt',\s*src: 'js\/crewart\.js'/.test(gsrc), 'and a stale index.html gets it loaded at runtime (LATE_MODULES)');
  ok(/window\.CrewArt = CrewArt/.test(fs.readFileSync(path.join(__dirname, '..', 'js', 'crewart.js'), 'utf8')), 'it publishes itself on window, so that check can see it');

  /* ── A FACE PER SEED ──────────────────────────────────── */
  const a = CrewArt.faceOf(12345, 'aquarius'), b = CrewArt.faceOf(12345, 'aquarius');
  ok(JSON.stringify(a) === JSON.stringify(b), 'the same seed is the same face, every time');
  const faces = Array.from({ length: 400 }, (_, i) => CrewArt.faceOf(1000 + i * 7919, 'pegasus'));
  const kinds = k => new Set(faces.map(f => f[k])).size;
  ok(kinds('hairdo') >= 7 && kinds('hair') >= 8 && kinds('skin') >= 5 && kinds('nose') >= 4 && kinds('mouth') >= 5,
     `hair, skin, nose and mouth all vary (${kinds('hairdo')} hairdos, ${kinds('hair')} hair colours, ${kinds('skin')} skins)`);
  ok(kinds('eye') >= 8, `jj: "różne kolory oczu" — ${kinds('eye')} eye colours turn up`);
  const glasses = faces.filter(f => f.glasses !== 'none').length / faces.length;
  ok(glasses > 0.3 && glasses < 0.7 && kinds('glasses') === 5, `jj: "okulary" — about one in two wears a pair, four kinds (${Math.round(glasses * 100)}%)`);
  const violet = faces.filter(f => f.eye === 'violet').length / faces.length;
  const odd = faces.filter(f => f.eyes2).length / faces.length;
  ok(violet > 0 && violet < 0.15 && odd > 0 && odd < 0.12, `violet eyes and two colours are the rare ones (${Math.round(violet * 100)}%, ${Math.round(odd * 100)}%)`);
  ok(CrewArt.faceOf(7, 'terra').cyborg && !CrewArt.faceOf(7, 'phoenix').cyborg, 'a Terra man has the implant, nobody else');

  /* ── HIS FACE IS SAVED WITH HIM ───────────────────────── */
  const m1 = new CrewMember({ name: 'Alba', race: 'aquarius' }), m2 = new CrewMember({ name: 'Alba', race: 'aquarius' });
  ok(Number.isFinite(m1.faceSeed) && m1.faceSeed !== m2.faceSeed, 'a new man rolls a face of his own — two men of one name are two faces');
  const back = CrewMember.deserialise(m1.serialise());
  ok(back.faceSeed === m1.faceSeed && m1.serialise().faceSeed === m1.faceSeed, 'serialised and read back: the same face');
  const old = { id: 77, name: 'Orrin', race: 'terra', hp: 80, maxHp: 80 };
  const o1 = new CrewMember({ ...old }), o2 = new CrewMember({ ...old });
  ok(o1.faceSeed === o2.faceSeed && o1.faceSeed === CrewArt.seedOf(old), 'a save from before 124 (no seed): one made from his name and corporation, the same on every load');
  ok(o1.serialise().faceSeed === o1.faceSeed, 'and written back the next time he is saved');
  if (Commander?.fromCrew) {
    const cap = Commander.fromCrew(m1.serialise());
    ok(cap.faceSeed === m1.faceSeed, 'promoted to the chair, he keeps his face');
  }

  /* ── WHICH WAY HE FACES (jj) ──────────────────────────── */
  const V = CrewArt.STATES;
  ok(V.operate.view === 'back', 'at a console: his back to us');
  ok(V.idle.view === 'front' && V.eat.view === 'front', 'standing about and eating: facing us');
  ok(V.walk.view === 'side' && V.fight.view === 'side' && V.repair.view === 'side', 'walking, fighting, mending: side on');
  ok(V.die.view === 'lying' && !V.die.loop, 'and dead on his back, still');
  const man = new CrewMember({ name: 'Kael', race: 'phoenix', isPlayer: true });
  man._setAnim('operate');
  ok(man.anim.view === 'back' && man.anim.native, 'CrewMember: at the console the frames are his back, at their own size');
  man._setAnim('idle');
  ok(man.anim.view === 'front' && man._animKey === 'idle', 'idle: his face');
  man._meal = { def: { label: 'ration' } };
  man.update(0.016, null);
  ok(man._animKey === 'eat' && man._animState === 'idle', 'a meal in his hands: the eating frames — still "idle" to everything that asks');
  man._meal = null;
  man.update(0.016, null);
  ok(man._animKey === 'idle', 'meal done: back to standing');

  /* ── THE FRAMES ───────────────────────────────────────── */
  const F = CrewArt.FRAME;
  ok(F.w === 24 && F.h === 32, `a 24 x 32 frame (${F.w}x${F.h})`);
  const fr = CrewArt.frames(42, 'pegasus', '#9fdcff', 'walk');
  ok(fr.length === 4 && CrewArt.frames(42, 'pegasus', '#9fdcff', 'walk') === fr, 'four walking frames, painted once and kept');
  ok(CrewArt.frames(42, 'pegasus', '#ff2d44', 'walk') !== fr, 'another suit, other frames');
  const draws = [];
  const realDI = ctx.drawImage;
  ctx.drawImage = function (...args) { draws.push(args); };
  try { man._setAnim('walk'); man.anim.draw(ctx, 300, 200, 32, 32); } finally { ctx.drawImage = realDI; }
  const d0 = draws[0];
  ok(d0 && d0[1] === 300 - F.ax && d0[2] === 200 - F.ay && d0[3] === F.w && d0[4] === F.h,
     `drawn at its own size round his point, not squeezed into the old 32 (${d0 && d0.slice(1).join(',')})`);
  ok(F.h - F.oy - (F.ay) === 5 && F.oy + 28 === 30, 'his boots on the same line as before (5 px under his y)');

  /* ── TWO BOTTLES, FLAT ON HIS BACK (jj) ───────────────── */
  const paintSpy = (view) => {
    const rects = [];
    const g = { fillRect(x, y, w, h) { rects.push({ x, y, w, h, c: this.fillStyle }); }, save() {}, restore() {},
                beginPath() {}, arc() {}, fill() {}, stroke() {}, set fillStyle(v) { this._f = v; }, get fillStyle() { return this._f; } };
    CrewArt.paint(g, 0, 0, '#4db8ff', CrewArt.faceOf(5, 'aquarius'), view, 0);
    return rects;
  };
  const TANK = 'rgb(182,192,208)';
  const backTanks = paintSpy('operate').filter(r => r.c === TANK && r.h >= 6);
  ok(backTanks.length === 2 && backTanks[0].x !== backTanks[1].x, `from behind: two bottles side by side (${backTanks.length})`);
  const sideTanks = paintSpy('walk').filter(r => r.c === TANK && r.h >= 6);
  ok(sideTanks.length === 1 && sideTanks[0].w <= 2, `side on: one bottle in profile, flat — no wider than 2 px (${sideTanks.map(r => r.w)})`);
  const frontTanks = paintSpy('idle').filter(r => r.c === TANK);
  ok(frontTanks.length === 2 && frontTanks.every(r => r.h <= 2), 'from the front: just the two caps over his shoulders');

  /* ── THE STACK OVER HIS HEAD RIDES HIGHER ─────────────── */
  ok(CrewMember.LIFT === CrewArt.LIFT && CrewArt.LIFT > 0, `the health boxes and the name ride ${CrewArt.LIFT} px higher`);
  const ours = new CrewMember({ name: 'Tess', race: 'terra', isPlayer: true });
  ours.x = 400; ours.y = 300; ours._setAnim('idle');
  let pips = null;
  const realPips = Renderer.drawPips;
  Renderer.drawPips = (c, x, y) => { pips = y; };
  try { ours.draw(ctx); } finally { Renderer.drawPips = realPips; }
  ok(pips === 300 - 19 - CrewArt.LIFT, `his health over the taller head (${pips})`);
  const headTop = 300 - F.ay + F.oy + 1;
  ok(pips + 3 <= headTop, 'clear of the glass');
  const H = CrewMember.HIT, HL = CrewMember.HIT_LYING;
  ok(H.cy < -1 && H.ry > H.rx && H.ry >= 14, `a click finds the taller man (centre ${H.cy}, ${H.rx}x${H.ry})`);
  ok(HL.rx > HL.ry, 'and a body lies flat — its click box is wide');
  const T = Game.__test;
  ok(T._hitsCrew(ours.x, ours.y - 20, ours) && T._hitsCrew(ours.x, ours.y + 4, ours), 'a click on his helmet finds him, and one on his boots');
  ok(!T._hitsCrew(ours.x, ours.y + 14, ours), 'a click on the deck under him does not');
  const kitty = new CrewMember({ name: 'Tom', race: 'cat_black', isPlayer: true });
  kitty.x = ours.x; kitty.y = ours.y;
  ok(!T._hitsCrew(kitty.x, kitty.y - 20, kitty), 'a cat is still cat-sized');
  ok(T._crewMid(ours) === ours.y + H.cy, 'the drag box picks him by the middle of the man as drawn');

  /* ── ON THE DECK: HIS OWN LYING FRAME ─────────────────── */
  const body = new CrewMember({ name: 'Rook', race: 'aquarius', isPlayer: true });
  body.x = 200; body.y = 200; body.hp = 0; body.dead = true; body.state = 'dead'; body._setAnim('idle');
  let rotated = 0, lyingDrawn = null;
  const realRot = ctx.rotate;
  ctx.rotate = function () { rotated++; };
  ctx.drawImage = function (...args) { if (args[3] === F.w) lyingDrawn = args; };
  try { body.draw(ctx); } finally { ctx.rotate = realRot; ctx.drawImage = realDI; }
  ok(rotated === 0 && lyingDrawn && lyingDrawn[2] === 200 + CrewMember.BODY_DROP - F.ay,
     'a body is his lying frame, low by the drop — not the standing man turned on his side');

  /* ── THE ENEMY RING GOES ROUND THE TALLER MAN ─────────── */
  const foe = new CrewMember({ name: 'Raid', race: 'phoenix', isPlayer: false });
  foe.x = 100; foe.y = 100; foe._setAnim('idle');
  let ell = null;
  const realEll = ctx.ellipse;
  ctx.ellipse = (x, y, rx, ry) => { ell = { x, y, rx, ry }; };
  try { foe.drawSideRing(ctx); } finally { ctx.ellipse = realEll; }
  ok(ell && ell.y === 100 + H.cy && ell.ry > ell.rx, 'the red ring is an oval round all of him');

  /* ── PORTRAITS: HIS FACE ON EVERY CARD ────────────────── */
  const rec = m1.serialise();
  const pc = CrewArt.portraitCanvas(rec);
  ok(pc && CrewArt.portraitCanvas(rec) === pc, 'his portrait is painted once and kept');
  ok(CrewArt.portraitCanvas(CrewMember.deserialise(rec)) === pc, 'the live man and his record share it');
  const got = [];
  ctx.drawImage = function (...args) { got.push(args); };
  try {
    Renderer.drawCrewPortrait(ctx, rec, 10, 10, 64);
    Renderer.drawCrewPortrait(ctx, rec, 10, 10, 20);
  } finally { ctx.drawImage = realDI; }
  ok(got[0] && got[0][0] === pc && got[0].length === 5, 'a card portrait is his face, whole');
  ok(got[1] && got[1][0] === pc && got[1].length === 9 && got[1][3] < 48, 'the fight\'s 20 px list crops to the face so it still reads as somebody');
  ok(!CrewArt.isPerson({ race: 'cat_black', isPet: true }) && CrewArt.isPerson(rec), 'a cat keeps her own sprite');
  const caps = [];
  ctx.drawImage = function (...args) { caps.push(args[0]); };
  try { Renderer.drawCrewPortrait(ctx, { name: 'Kit', race: 'cat_ginger', isPet: true }, 0, 0, 48); } finally { ctx.drawImage = realDI; }
  ok(!caps.some(c => c && c.width === 48 && c.height === 48 && c === CrewArt.portraitCanvas({ name: 'Kit', race: 'cat_ginger' })), 'and is not given a face');
})();

// ============================================================
section('312. The chase on the title screen and the new rank marks (125): the best hull in the yard on your tail, same size, both firing; dots, bars, stars');
// ============================================================
(function testUpdate125() {
  const sb = loadEngine();
  const { Save, Game, Renderer, Ship } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const W = Renderer.getWidth();
  Save.load();
  T.STATE = 'menu';

  /* ── THE CHASE (jj: the best hull in the yard chases yours, same size) ── */
  const you = T._menuShipFor(), foe = T._menuFoeShip();
  const best = Object.values(sb.SHIP_CATALOG).filter(d => d.key !== you.layoutKey).sort((a, b) => b.cost - a.cost)[0].key;
  ok(foe && foe.layoutKey === best && T._menuChaserKey() === best, `the dearest hull the shipyard sells gives chase (${foe && foe.layoutKey})`);
  ok(foe.roofAlpha === 1 && foe.isPlayer === true && T._menuFoeShip() === foe, 'closed, facing the way it flies, built once');
  const f = T._menuFlyby(30, you, foe);
  ok(f.foe.s === f.s, `both at the same size (${f.s}) — not shrunk`);
  const yw = f.b.w * f.s, fw = f.foe.b.w * f.foe.s, fh = f.foe.b.h * f.foe.s, yh = f.b.h * f.s;
  ok(f.foe.x + fw < f.x && f.x - (f.foe.x + fw) === T._menuChaseCfg().gap, 'on your tail, a set gap behind');
  const r2 = T._menuRect(2);
  ok(f.foe.y - fh / 2 > r2.y + r2.h && f.y - yh / 2 > r2.y + r2.h, 'both under the buttons');
  const f2 = T._menuFlyby(31, you, foe);
  ok(f2.x > f.x && f2.foe.x - f.foe.x === f2.x - f.x, 'and they move together');
  const fStart = T._menuFlyby(0, you, foe);
  ok(fStart.foe.x + fw < 0 && fStart.x + yw < 0, 'a pass begins with both off the left edge');
  {
    const run0 = Save.getRun();
    if (!run0) Save.startRun();
    Save.updateRun({ shipKey: best });
    ok(T._menuHullKey() === best && T._menuChaserKey() !== best, 'flying the best hull yourself, the next best chases you');
    Save.updateRun({ shipKey: null });
  }

  /* ── THE SHOTS (since update131 a real exchange — section 317) ── */
  {
    // the engine has its own Date (vm) — stop the clock THERE
    const SDate = require('vm').runInContext('Date', sb);
    const realNow = SDate.now;
    let clock = 48000 * 1000 + 26000;
    SDate.now = () => clock;
    try {
      for (let i = 0; i < 160; i++) { clock += 50; T._menuFightTick(0.05, clock / 1000); }
    } finally { SDate.now = realNow; }
    ok(T._menuFight().fired > 0, `both hulls fire as they cross the screen (${T._menuFight().fired} shots)`);
    let strokes = 0;
    const realStroke = ctx.stroke;
    ctx.stroke = function () { strokes++; };
    try { SDate.now = () => clock; T._drawMenu(ctx); } finally { ctx.stroke = realStroke; SDate.now = realNow; }
    ok(strokes > 0, 'the title screen draws the exchange');
  }

  /* ── THE MARKS ON THE CARDS USE THEM ──────────────────── */
  const ops = [];
  const keep = ctx.arc;
  ctx.arc = function () { ops.push(ctx.fillStyle); };
  try { Renderer.drawRankInsignia(ctx, 7, 0, 0, 12); } finally { ctx.arc = keep; }
  ok(ops.length === 3 && ops.every(c => c === '#c8d0dc'), 'rank 7: three silver dots (over one bar)');
})();

// ============================================================
section('313. Guns, shots and hits (126): every gun a machine of its own, every shot its own body, every hit its own blast; the bubble stops a shot where it crosses it, and a dodged one flies on');
// ============================================================
(function testUpdate126() {
  const sb = loadEngine();
  const { WeaponArt, Weapon, Projectile, WEAPON_DEFS, Ship, CombatManager, Renderer, Game, Camera } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const fs = require('fs'), path = require('path');
  const src = f => fs.readFileSync(path.join(__dirname, '..', f), 'utf8');

  /* ── THE MODULE IS LOADED EVERYWHERE ─────────────────── */
  ok(!!WeaponArt && typeof WeaponArt.turret === 'function', 'WeaponArt is there');
  ok(/<script src="js\/weaponart\.js"><\/script>/.test(src('index.html')), 'index.html loads it');
  ok(/name: 'WeaponArt',\s*src: 'js\/weaponart\.js'/.test(src('js/game.js')), 'and a stale index.html gets it from the late loader');

  /* ── THE GUNS ─────────────────────────────────────────── */
  const paint = (key, o = {}) => {
    const log = [], keep = { fillRect: ctx.fillRect, translate: ctx.translate };
    ctx.fillRect = function (x, y, w, h) { log.push(`${x},${y},${w},${h},${ctx.fillStyle}`); };
    ctx.translate = function (x, y) { log.push(`T${x},${y}`); };
    try { WeaponArt.turret(ctx, key, 0, 0, 44, 18, o); } finally { Object.assign(ctx, keep); }
    return log;
  };
  const keys = Object.keys(WEAPON_DEFS);
  const sigs = keys.map(k => paint(k, { charge: 0.5 }).join('|'));
  ok(new Set(sigs).size === keys.length, `all ${keys.length} guns are painted differently (${new Set(sigs).size})`);
  // and not by colour alone: the SHAPES differ (a burst laser is not a red Mk I)
  const shapes = keys.map(k => paint(k, { charge: 0.5 }).map(l => l.split(',').slice(0, 4).join(',')).join('|'));
  ok(new Set(shapes).size === keys.length, `every gun has its own silhouette, colour aside (${new Set(shapes).size})`);
  ok(paint('ion_basic', { charge: 0.9, t: 1.234 }).join('|') === paint('ion_basic', { charge: 0.9, t: 1.234 }).join('|'),
     'a gun is painted from its inputs alone — the same moment paints the same gun');
  const cold = paint('laser_basic', { charge: 0 }), hot = paint('laser_basic', { charge: 1, armed: true });
  ok(cold.join('|') !== hot.join('|') && hot.some(l => l.endsWith('#ffffff')), 'a charged gun shows it: the lens comes up white');
  const off = paint('laser_basic', { powered: false });
  ok(off[off.length - 1].endsWith('#0b0f18'), 'an unpowered gun is drawn dark');
  ok(paint('cannon_basic', { recoil: 1 }).includes('T-3,0') && !paint('cannon_basic', { recoil: 0 }).includes('T-3,0'),
     'a gun that has just fired has its barrel kicked back');
  const hullP = paint('laser_basic', { charge: 0.5 }), cardP = paint('laser_basic', { charge: 0.5, card: true });
  ok(hullP.some(l => l.endsWith(WeaponArt.STEEL.body)) && cardP.some(l => l.endsWith(WeaponArt.CARD.body)) &&
     !cardP.some(l => l.endsWith(WeaponArt.STEEL.body)), 'steel on the hull, the UI blue on a card');
  // the card in the shop asks for the card look; the hull for steel
  {
    const asked = [], keepT = WeaponArt.turret;
    WeaponArt.turret = function (c, k, x, y, w, h, o) { asked.push(!!o.card); };
    try {
      Renderer.drawWeaponIcon(ctx, 'laser_basic', 0, 0, 44, 18, { onHull: true });
      Renderer.drawWeaponIcon(ctx, 'laser_basic', 0, 0, 44, 18, {});
    } finally { WeaponArt.turret = keepT; }
    ok(asked.join() === 'false,true', `drawWeaponIcon hands every gun to WeaponArt (${asked.join()})`);
  }

  /* ── THE GUN KICKS AND TELLS THE PAINTER ─────────────── */
  {
    const w = new Weapon('laser_heavy');
    w.armed = true; w.charge = 1;
    WeaponArt.clear();
    const ps = w.fire(0, 0, 100, 0, true);
    ok(w.recoil === 1, 'firing kicks the barrel');
    ok(ps[0].defKey === 'laser_heavy' && ps[0].gun === w, 'the shot knows which gun fired it');
    ok(WeaponArt.active().some(f => f.kind === 'muzzle' && f.col === WeaponArt.STYLE.laser_heavy.col),
       'and the muzzle flashes in that gun\'s colour');
    w.update(0.3);
    ok(w.recoil === 0, 'the barrel runs back out in a quarter of a second');
    let opts = null;
    const keepI = Renderer.drawWeaponIcon;
    Renderer.drawWeaponIcon = function (c, k, x, y, ww, hh, o) { opts = o; };
    w.charge = 0.4; w.recoil = 0.5;
    try { w.draw(ctx, 0, 0, false, 1, { onHull: true }); } finally { Renderer.drawWeaponIcon = keepI; }
    ok(opts && opts.charge === 0.4 && opts.recoil === 0.5 && 'armed' in opts, 'Weapon#draw passes its charge and its kick to the painter');

    // the second bolt of a burst kicks the gun again when it leaves
    const b = new Weapon('laser_burst');
    b.armed = true;
    const two = b.fire(0, 0, 400, 0, true);
    b.recoil = 0; WeaponArt.clear();
    two[1].update(0.5);
    ok(b.recoil === 1 && WeaponArt.active().some(f => f.kind === 'muzzle'), 'the second bolt of a burst kicks and flashes too');

    // the bolt is drawn by WeaponArt, as its own kind
    const kinds = [], keepS = WeaponArt.shot;
    WeaponArt.shot = function (c, kind) { kinds.push(kind); };
    try { ps[0].draw(ctx); two[0].draw(ctx); } finally { WeaponArt.shot = keepS; }
    ok(kinds.join() === 'heavy,laser', `a heavy laser's bolt is its own (${kinds.join()})`);
  }

  /* ── THE BUBBLE STOPS IT WHERE IT IS ─────────────────── */
  const flyAt = (player, defKey, startOut = 60) => {
    const room = player.rooms.find(r => r.system) || player.rooms[0];
    const e = player.shieldEllipse();
    const def = WEAPON_DEFS[defKey];
    const p = new Projectile({ x: e.cx + e.rx + startOut, y: e.cy, targetX: room.cx, targetY: room.cy,
                               speed: 300, type: def.type, def, defKey, fromPlayer: false });
    CombatManager._projectiles = [p];
    for (let i = 0; i < 400 && !p._resolved; i++) CombatManager._updateProjectiles(1 / 60);
    return { p, room, e };
  };
  {
    const { player } = makeCombat(sb);
    Object.defineProperty(player, 'evasion', { get: () => 0, configurable: true });
    const bars = player.shieldBars;
    ok(bars > 0, `your bubble is up (${bars})`);
    WeaponArt.clear();
    const { p, room, e } = flyAt(player, 'laser_basic');
    /* update142: the bubble follows the hull — it is stopped on its OUTERMOST layer */
    const off = player.shieldDist(p.x, p.y) - Ship.shieldRadius(bars - 1);
    ok(p._resolved && p.atShield, 'a laser is stopped by the shield');
    ok(off <= Ship.SHIELD_HEX * 0.75 && off > -8, `where it crosses the bubble's outer layer, not in the room (${off.toFixed(1)} px off it)`);
    ok(Math.hypot(p.x - room.cx, p.y - room.cy) > 40, 'it never reached the room');
    ok(player.shieldBars === bars - 1, 'and it took a bar, the same as before');
    const fx = WeaponArt.active().find(f => f.kind === 'shield');
    ok(fx && (player._shieldWaves ?? []).length === 1, 'the bubble lights up where it was struck — a wave on its own cells');
    ok(!WeaponArt.active().some(f => f.kind === 'scorch'), 'and leaves no scorch on a hull it never touched');
    // the bubble is still up for the missile (the laser may have taken the last bar)
    Object.defineProperty(player, 'shieldBars', { get: () => 2, set() {}, configurable: true });
    const m = flyAt(player, 'missile_basic');
    ok(m.p._resolved && !m.p.atShield && Math.hypot(m.p.x - m.room.cx, m.p.y - m.room.cy) < 20,
       'a missile goes through the bubble to its room');
    CombatManager.end();
  }

  /* ── A DODGED SHOT FLIES ON ──────────────────────────── */
  {
    const { player } = makeCombat(sb);
    Object.defineProperty(player, 'evasion', { get: () => 1, configurable: true });
    let calls = 0;
    const keepR = player.receiveHit;
    player.receiveHit = function (pp) { calls++; return keepR.call(this, pp); };
    WeaponArt.clear();
    const { p, room } = flyAt(player, 'missile_basic');
    ok(p._resolved && p.flyOn && !p.done, 'a shot that missed keeps flying');
    ok(WeaponArt.active().some(f => f.kind === 'miss'), 'with a faint ring where it slipped by');
    const x0 = p.x;
    for (let i = 0; i < 30; i++) CombatManager._updateProjectiles(1 / 60);
    ok(p.x < x0 - 20 && calls === 1, `on past the hull, and it hits nothing on the way (${calls})`);
    let minX = p.x;
    for (let i = 0; i < 400 && CombatManager._projectiles.length; i++) {
      CombatManager._updateProjectiles(1 / 60); minX = Math.min(minX, p.x);
    }
    ok(minX < room.cx - 100, `right past the room it was aimed at (${Math.round(minX)} vs ${Math.round(room.cx)})`);
    ok(p.done && CombatManager._projectiles.length === 0, 'until it is off the screen, and then it is gone');
    CombatManager.end();
  }

  /* ── EVERY HIT ITS OWN BLAST ─────────────────────────── */
  {
    const sh = new Ship('enemy_frigate', false, 850, 120);
    sh._allocateDefaultPower();
    Object.defineProperty(sh, 'evasion', { get: () => 0, configurable: true });
    Object.defineProperty(sh, 'shieldBars', { get: () => 0, set() {}, configurable: true });
    const room = sh.rooms[0];
    const shakes = [], keepShake = Camera.shake;
    Camera.shake = function (a) { shakes.push(a); };
    const hit = key => {
      WeaponArt.clear();
      const def = WEAPON_DEFS[key];
      const p = new Projectile({ x: room.cx, y: room.cy, targetX: room.cx, targetY: room.cy,
                                 speed: 1, type: def.type, def, defKey: key, fromPlayer: true });
      sh.receiveHit(p);
      return WeaponArt.active().map(f => f.kind);
    };
    try {
      const torp = hit('torpedo_launcher');
      ok(torp.includes('torpedo') && torp.includes('scorch'), `a torpedo makes a torpedo's blast and burns the plate (${torp})`);
      const ion = hit('ion_basic');
      ok(ion.includes('ion') && !ion.includes('scorch'), `an ion bolt crackles and burns nothing (${ion})`);
      const heavy = hit('laser_heavy');
      ok(heavy.includes('heavy'), `a heavy laser has its own (${heavy})`);
      sh.armor = 2;
      const ring = hit('laser_basic');
      ok(ring.includes('armour') && !ring.includes('scorch'), `armour rings a laser off (${ring})`);
      sh.armor = 0;
      shakes.length = 0; hit('torpedo_launcher'); const big = Math.max(...shakes);
      shakes.length = 0; hit('laser_basic'); const small = Math.max(...shakes);
      ok(big > small, `a torpedo shakes the screen harder than a laser (${big} > ${small})`);
    } finally { Camera.shake = keepShake; }
  }

  /* ── THE EFFECTS PLAY OUT AND GO ─────────────────────── */
  {
    WeaponArt.clear();
    ok(WeaponArt.add({ kind: 'nothing' }) === null, 'an unknown effect is refused');
    WeaponArt.add({ kind: 'laser', x: 10, y: 10 });
    WeaponArt.update(0.2);
    ok(WeaponArt.active().length === 1, 'a blast is still playing a moment later');
    WeaponArt.update(0.2);
    ok(WeaponArt.active().length === 0, 'and gone when its time is up');
    for (let i = 0; i < 300; i++) WeaponArt.add({ kind: 'scorch', x: i, y: 0 });
    ok(WeaponArt.active().length === WeaponArt.MAX_FX, `there is a cap on them (${WeaponArt.active().length})`);
    const count = (layer) => {
      let n = 0; const ka = ctx.arc, ke = ctx.ellipse;
      ctx.arc = function () { n++; }; ctx.ellipse = function () { n++; };
      try { WeaponArt.draw(ctx, layer); } finally { ctx.arc = ka; ctx.ellipse = ke; }
      return n;
    };
    ok(count('under') > 0 && count('over') === 0, 'a scorch is burnt into the plate: the under layer');
    WeaponArt.clear(); WeaponArt.add({ kind: 'missile', x: 10, y: 10 });
    ok(count('under') === 0 && count('over') > 0, 'a blast goes over the shots');
    const draws = [], keepD = WeaponArt.draw;
    WeaponArt.draw = function (c, layer) { draws.push(layer); };
    const { player } = makeCombat(sb);
    try { CombatManager.draw(ctx); } finally { WeaponArt.draw = keepD; }
    ok(draws.join() === 'under,over', `the fight draws them either side of the shots (${draws})`);
    ok(WeaponArt.active().length === 0, 'and a new fight starts with no scorch from the last');
    const t0 = WeaponArt.now();
    T._update(0.1);
    ok(WeaponArt.now() > t0, 'the game clock drives them');
    void player;
    CombatManager.end();
  }

  /* ── THE BEAM ─────────────────────────────────────────── */
  {
    const p = new Projectile({ x: 100, y: 50, targetX: 400, targetY: 200, speed: 0,
                               type: 'beam', def: WEAPON_DEFS.beam_basic, defKey: 'beam_basic', fromPlayer: true });
    p.beamProgress = 0.5;
    const got = [], kb = WeaponArt.beam, ks = WeaponArt.beamScar;
    WeaponArt.beam = function (c, x0, y0, x1, y1) { got.push(['beam', x0, y0, x1, y1]); };
    WeaponArt.beamScar = function (c, x0, y, x1) { got.push(['scar', x0, y, x1]); };
    try { p.drawBeam(ctx, 600, 180, 200); } finally { WeaponArt.beam = kb; WeaponArt.beamScar = ks; }
    ok(got.length === 2 && got[0][0] === 'scar' && got[0][1] === 600 && got[0][3] === 700,
       'a beam leaves a burnt line along the plate behind its cut');
    ok(got[1] && got[1][1] === 100 && got[1][3] === 700, 'and is drawn from the gun to the cut');
  }

  /* ── THE TITLE SCREEN STILL FIRES (holes found in 125) ── */
  {
    const S = sb.Save; S.load(); T.STATE = 'menu';
    const you = T._menuShipFor(), foe = T._menuFoeShip();
    /* update131: the chase is a real exchange now — the shots are
       Projectiles painted by WeaponArt, so ask WeaponArt what it drew. */
    const SDate = require('vm').runInContext('Date', sb);
    const realNow = SDate.now, keepShot = sb.WeaponArt.shot;
    let heads = 0, ms = 48000 * 2000 + 26000;
    sb.WeaponArt.shot = function () { heads++; return keepShot.apply(this, arguments); };
    try {
      for (let i = 0; i < 120; i++) {
        ms += 50; SDate.now = () => ms;
        T._menuFightTick(0.05, ms / 1000); T._drawMenu(ctx);
      }
    } finally { sb.WeaponArt.shot = keepShot; SDate.now = realNow; }
    ok(heads > 0, `the chase really fires: the bolts are drawn (${heads})`);
  }
})();

// ============================================================
section('314. Fixes after jj played 124–126 (127): a slab melts, their guns get power back, their last man repairs and runs, a suit flies home facing home, a port opens after the film, the escape bar, no cloak label, their reactor reads true, the loadout picture has nobody in a lift');
// ============================================================
(function testUpdate127() {
  const sb = loadEngine();
  const { Ship, Save, Game, CombatManager, TASK, JumpScene, SectorMap, Renderer } = sb;
  const T = Game.__test;
  Renderer.init(sb.document.getElementById('game-canvas'));
  const ctx = Renderer.getCtx();
  const said = [];
  sb.UI.notify = (m) => { said.push(String(m)); };
  const quiet = (sb2, fn) => fn();               // notify already captured above
  const quietly = (fn) => { const n = said.length; fn(); return said.slice(n); };
  Save.load(); Save.startRun();

  /* ── A. A SLAB MELTS, IT DOES NOT POP ─────────────────────── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const room = sh.rooms.find(r => r.type === 'empty');
    sh.addModuleAt('carbonite', room.id);
    powerModule(sh, 'carbonite', 1);
    sh.update(0.016);
    const pod = sh.getSystem('carbonite');
    const man = sh.crew.find(c => c.isPlayer && !c.isPet);
    man.roomId = pod.roomId;
    ok(sh.freezeCrew(man).ok, 'test setup: one man in a one-slab bay');
    ok(Ship.SLAB_MELT_SECONDS >= 20 && Ship.SLAB_MELT_SECONDS <= 30,
       `a slab takes 20–30 s to melt (${Ship.SLAB_MELT_SECONDS})`);
    said.length = 0;
    pod.desiredPower = 0;
    for (let t = 0; t < Ship.SLAB_MELT_SECONDS - 2; t += 0.5) { pod.desiredPower = 0; sh.update(0.5); }
    ok(man.frozen && man._meltT > Ship.SLAB_MELT_SECONDS - 4,
       `the bay dark for ${Ship.SLAB_MELT_SECONDS - 2} s — he is still under, melting (${man._meltT?.toFixed(1)})`);
    ok(said.filter(m => /slab has lost power/.test(m)).length === 1, 'and the player is warned once, with the time');
    pod.desiredPower = 1;
    sh.update(0.05);
    ok(man.frozen && !man._meltT, 'the power back in time: the clock goes back to zero and he stays under');
    pod.damageLevel(1);
    for (let t = 0; t < Ship.SLAB_MELT_SECONDS + 1; t += 0.5) { pod.damagedLevels = 1; sh.update(0.5); }
    ok(!man.frozen, 'shot out and left so: once it has melted he is out');
    ok(!man._meltT && !man._meltWarned, 'and nothing of the melt is left on him');
    // THAWED BY HAND while his slab was melting: the clock goes with him.
    pod.damagedLevels = 0; pod.desiredPower = 1; pod.power = 1; sh.update(0.05);
    man.roomId = pod.roomId;
    ok(sh.freezeCrew(man).ok, 'test setup: back under');
    pod.desiredPower = 0;
    for (let t = 0; t < 5; t += 0.5) { pod.desiredPower = 0; sh.update(0.5); }
    ok(man._meltT > 0, 'test setup: his slab is melting');
    sh.thawCrew(man);
    ok(!man._meltT && !man._meltWarned, 'a THAW by hand mid-melt leaves no clock on him for next time');
    pod.desiredPower = 1;
    // The melt is drawn: the amber line under the slab.
    const m2 = sh.crew.find(c => c.isPlayer && !c.isPet && c !== man);
    m2.frozen = true; m2._meltT = Ship.SLAB_MELT_SECONDS / 2; m2.x = 100; m2.y = 100;
    const fills = [];
    const real = ctx.fillRect;
    ctx.fillRect = function (x, y, w, h) { fills.push([String(ctx.fillStyle), w]); return real.apply(this, arguments); };
    try { m2.draw(ctx); } finally { ctx.fillRect = real; }
    ok(fills.some(([c, w]) => c === '#ffb020' && w > 0), 'a melting slab draws the time it has left');
    m2.frozen = false; m2._meltT = 0;
  }

  /* ── B. THEIR GUNS GET THEIR POWER BACK ───────────────────── */
  {
    const e = new Ship('enemy_frigate', false, 850, 120);
    e._allocateDefaultPower();
    const gun = e.systems.find(x => x.type === 'weapons');
    ok(!!gun && gun.desiredPower > 0, 'test setup: their gun is powered at the start');
    gun.desiredPower = 0; gun.power = 0;          // a Terra walked off a full console
    e.rePowerAI(1.1);
    ok(gun.desiredPower > 0, 'within a second their AI puts the unit back on the gun');
    // …and it is the FIGHT that runs it, not only a direct call.
    {
      const { player, enemy } = makeCombat(sb, { enemyArmed: true });
      const g = enemy.systems.find(x => x.type === 'weapons');
      g.desiredPower = 0; g.power = 0;
      quiet(sb, () => { for (let i = 0; i < 30; i++) CombatManager.update(0.05); });
      ok(g.desiredPower > 0, 'in a fight their gun gets its unit back by itself');
      quietly(() => CombatManager.end());
    }
    // A full core: the gun takes a unit from a luxury.
    const e2 = new Ship('enemy_frigate', false, 850, 120);
    e2._allocateDefaultPower();
    const g2 = e2.systems.find(x => x.type === 'weapons');
    const spare = e2.reactor.totalPower - e2.liftPowerNeed()
      - e2.systems.reduce((a, x) => a + (x.type === 'reactor' ? 0 : x.reactorDraw(Math.min(x.desiredPower, x.workingLevels))), 0);
    const eng = e2.getSystem('engines');
    eng.desiredPower += Math.max(0, spare) + (g2.desiredPower ?? 0);
    eng.desiredPower = Math.min(eng.desiredPower, eng.maxPower);
    g2.desiredPower = 0;
    const engBefore = eng.desiredPower;
    e2.rePowerAI(1.1);
    ok(g2.desiredPower > 0 && (eng.desiredPower < engBefore || spare > 0),
       `a dark gun on a full core gets a unit, from the engines above one (${engBefore} → ${eng.desiredPower})`);
    // Not while the core is being cooled.
    const e3 = new Ship('enemy_frigate', false, 850, 120);
    e3._allocateDefaultPower();
    const g3 = e3.systems.find(x => x.type === 'weapons');
    g3.desiredPower = 0; e3._aiShed = [g3];
    e3.rePowerAI(1.1);
    ok(g3.desiredPower === 0, 'while the cooling AI holds units back, it leaves them be');
    // The flow cuts their luxuries before their guns.
    const e4 = new Ship('enemy_frigate', false, 850, 120);
    e4._allocateDefaultPower();
    const g4 = e4.systems.find(x => x.type === 'weapons');
    // the gun LAST in the list, where the old flow cut first (the case jj hit)
    e4.systems = [...e4.systems.filter(x => x !== g4), g4];
    const want4 = g4.power;
    e4.reactor.sys.damageLevel(2);
    e4.update(0.05);
    ok(g4.power === want4, `their core loses two units — the gun keeps its own (${want4} → ${g4.power})`);
  }

  /* ── C. THE LAST MAN REPAIRS, GOES BACK, AND RUNS ─────────── */
  {
    const { player, enemy } = makeCombat(sb);
    enemy.snapToStations?.();
    const pil = enemy.getSystem('piloting');
    const pilot = enemy.consoleOperator(pil.roomId);
    ok(!!pilot, 'test setup: a man at their helm');
    enemy.crew.filter(c => c !== pilot && !c.isPlayer).forEach(c => c.killOutright('test'));
    const eng = enemy.getSystem('engines');
    eng.damageLevel(eng.level);            // dead engines: no running until they are fixed
    let left = false, back = false, fixedAt = null, backAt = null;
    for (let i = 0; i < 600; i++) {
      quiet(sb, () => { enemy.update(0.05); CombatManager.update(0.05); });
      if (pilot.roomId !== pil.roomId) left = true;
      if (fixedAt == null && eng.damagedLevels === 0) fixedAt = i * 0.05;
      if (left && eng.damagedLevels === 0 && pilot.roomId === pil.roomId && pilot.task === TASK.IDLE && !back) { back = true; backAt = i * 0.05; }
      if (back && CombatManager.enemyEscapeActive) break;
      if (CombatManager.state !== 'active') break;
    }
    ok(left, 'alone at the helm with the engines shot, he leaves the helm to fix them');
    ok(eng.damagedLevels === 0, `and fixes them (${eng.damagedLevels} left, ${CombatManager.state}, task ${pilot.task}, room ${pilot.roomId}, alive ${enemy.crew.filter(c => c.alive).length})`);
    ok(back && backAt - fixedAt < 8, `then walks straight back to his own console (${fixedAt?.toFixed(1)} → ${backAt?.toFixed(1)} s)`);
    ok(back, `and is there at the end (${CombatManager.state}, task ${pilot.task}, room ${pilot.roomId}/${pil.roomId}, off ${pilot._offPost}, home ${pilot.homeRoomId}, wp ${pilot._waypoints?.length})`);
    ok(CombatManager.enemyEscapeActive && CombatManager.escapeWhy === 'alone', 'and, the last of them, he spools the drive');
    quietly(() => CombatManager.end());
  }
  {
    const { player, enemy } = makeCombat(sb);
    const away = enemy.crew.find(c => !c.isPlayer);
    enemy.crew.filter(c => c !== away && !c.isPlayer).forEach(c => c.killOutright('test'));
    // He is on OUR deck: their ship does not leave him.
    enemy.crew = enemy.crew.filter(c => c !== away);
    player.crew.push(away);
    enemy.crew.push(sb.makeEnemyCrew(1)[0]);
    quiet(sb, () => { for (let i = 0; i < 4; i++) CombatManager.update(0.05); });
    ok(!(CombatManager.escapeWhy === 'alone'), 'with one of theirs still on our deck, the last man aboard does not run');
    player.crew = player.crew.filter(c => c !== away);
    quietly(() => CombatManager.end());
  }

  /* ── D. A SUIT FLIES HOME FACING HOME ─────────────────────── */
  {
    const { player, enemy } = makeCombat(sb);
    const c = player.crew.find(k => k.isPlayer && !k.isPet);
    player.crew = player.crew.filter(k => k !== c);
    c.roomId = null; c.inRoom = false; c._facing = 1;
    const hatch = { x: 300, y: 200, roomA: player.rooms[0].id };
    CombatManager.salvage = { crates: [], men: [{ c, phase: 'home', x: 600, y: 200, t: 0, queue: [], hatch }] };
    T._updateSalvage(0.05);
    ok(c._facing === -1, 'flying back to a hatch on his left, he faces left');
    CombatManager.salvage.men[0].x = 100;
    T._updateSalvage(0.05);
    ok(c._facing === 1, 'and the other way round');
    CombatManager.salvage = null;
    player.addCrew(c, true);
    // A recall: from their hull (on the right) back to ours — facing left.
    const rider = sb.makeStartingCrew()[0];
    enemy.addCrew(rider); rider.isPlayer = true; rider._facing = 1;
    const party = T._makeParty(enemy, player, [rider], { recall: true });
    party.members[0].phase = 'fly';
    party.members[0].x = party.entryDoor.x + 200; party.members[0].y = party.entryDoor.y;
    T._updateParty(party, 0.05);
    ok(rider._facing === -1, 'a man recalled from their hull flies home facing home');
    quietly(() => CombatManager.end());
  }

  /* ── E. A PORT OPENS WHEN THE FILM IS OVER ────────────────── */
  {
    JumpScene.reset();
    JumpScene.enabled = true;
    const opened = [];
    const realOpen = sb.UI.openStation;
    sb.UI.openStation = function () { opened.push(1); };
    /* update143: a port opens on the promenade, not straight into the panel */
    const realPort = sb.PortView.open;
    sb.PortView.open = function () { opened.push('port'); return realPort.apply(this, arguments); };
    try {
      Save.startRun(); Save.updateRun({ scrap: 100 });
      const sh = new Ship('frigate', true, 80, 120);
      sh._allocateDefaultPower();
      sb.makeStartingCrew().forEach(c => sh.addCrew(c));
      const map = new SectorMap(1, 7, 1, 3, true);
      const start = map.startNodes[0];
      const node = map.getNode(start.next[0]);
      node.type = 'store';
      map.currentId = start.id; map.unlockNext();
      T.sectorMap = map; T.playerShip = sh; T.STATE = 'map'; T.enemyShip = null;
      manCockpit(sh);
      quietly(() => T._addFuel(3));
      quietly(() => T._travelTo(node.id));
      ok(T.STATE === 'station' && JumpScene.active(), 'test setup: a jump to a port, with its film');
      ok(opened.length === 0, 'the port does not open over the film');
      for (let i = 0; i < 200 && JumpScene.active(); i++) quietly(() => T._step(0.05));
      quietly(() => T._step(0.05));
      ok(opened.length === 1 && opened[0] === 'port' && T.portMode, `it opens once the film is over — on the promenade (${opened.join()})`);
      ok(T.STATE === 'station', 'and you are in port, not bounced back to the map');
    } finally {
      sb.UI.openStation = realOpen;
      sb.PortView.open = realPort;
      JumpScene.enabled = false; JumpScene.reset();
    }
  }

  /* ── F. THE ESCAPE BAR, AND NOTHING OVER THEIR GUN ────────── */
  {
    const { player, enemy } = makeCombat(sb);
    CombatManager.enemyEscapeActive = true; CombatManager._enemyEscapeT = 5;
    const strokes = [];
    const realSR = ctx.strokeRect;
    ctx.strokeRect = function (x, y, w, h) { strokes.push({ x, y, w, h, c: String(ctx.strokeStyle) }); return realSR.apply(this, arguments); };
    let text;
    try { text = captureText(ctx, () => T._drawCombat(ctx)).map(o => o.t); }
    finally { ctx.strokeRect = realSR; }
    ok(text.includes('ENEMY FTL') && text.includes('6s'), `the bar names the drive and counts the seconds (${text.filter(t => /FTL|\ds$/.test(t))})`);
    ok(text.includes('hit HELM / ENGINES'), 'and says where to shoot');
    ok(!text.some(t => /FTL SPOOLING/.test(t)), 'no marker hung over their hull any more');
    const pr = enemy.getRoomById(enemy.getSystem('piloting').roomId);
    ok(strokes.some(s => s.c === '#ff2d44' && Math.abs(s.x - (pr.x + 2)) < 1 && Math.abs(s.y - (pr.y + 2)) < 1),
       'their helm is framed red — the room to shoot');
    CombatManager.enemyEscapeActive = false; CombatManager._enemyEscapeT = 0;
    quietly(() => CombatManager.end());
  }

  /* ── H. (127b) THE LOADOUT PICTURE: EVERYBODY AT HIS POST, NOBODY IN THE LIFT ──
   * jj: "przy załadowaniu załogantów przed startem (dwuklik) raz są
   * normalnie, raz przeskakują do windy". The picture walked them for
   * three seconds and froze; a man posted a deck away was in the lift. */
  {
    const { Base, BaseScreen, SHIP_LAYOUTS } = sb;
    const hulls = ['hauler', 'isis', 'osiris', 'thoth', 'frigate'].filter(k => SHIP_LAYOUTS[k]);
    const stray = [];
    hulls.forEach(key => {
      Save.load();
      const b = Base.get(); b.ships.length = 0;
      b.ships.push({ key, data: new Ship(key, true, 0, 0).serialise() });
      b.barracks.length = 0;
      sb.makeStartingCrew().concat(sb.makeStartingCrew()).slice(0, 5).forEach(c => Base.addCrew(c.serialise()));
      BaseScreen.open();
      BaseScreen._set({ tab: 'HANGAR', shipIdx: 0, screen: 'loadout', picked: Base.crew().map(c => c.id), posts: {} });
      let seen = null; const real = Ship.prototype.draw;
      Ship.prototype.draw = function (c, ...a) { if (this.isPreview) seen = this; return real.call(this, c, ...a); };
      try { quiet(sb, () => BaseScreen.draw(ctx)); } finally { Ship.prototype.draw = real; }
      if (!seen) { stray.push(`${key}: no picture`); return; }
      seen.crew.filter(c => !c.isPet).forEach(c => {
        if (c._ridingShaft || c._waypoints?.length || c.roomId !== c.homeRoomId)
          stray.push(`${key}:${c.name} ${c.roomId}→${c.homeRoomId}${c._ridingShaft ? ' LIFT' : ''}`);
      });
    });
    ok(hulls.length >= 3 && stray.length === 0,
       `the loadout picture shows every man at his post, none in a lift (${hulls.length} hulls; ${stray.join(', ') || 'all in place'})`);
  }

  /* ── G. THEIR REACTOR COLUMN READS TRUE ───────────────────── */
  {
    const { player, enemy } = makeCombat(sb, { enemyArmed: true });
    quiet(sb, () => Renderer.drawHUD({ playerShip: player, enemyShip: enemy }));
    const fills = (Renderer.enemyReactorBar()?.fills ?? []).map(String);   // lying since update130
    const spent = enemy.reactor.totalPower - enemy.availablePower();
    ok(spent > 0, `test setup: their modules draw power (${spent})`);
    ok(fills.filter(f => f === 'rgba(40,44,60,0.9)').length >= Math.min(spent, enemy.reactor.capacity),
       `the units their modules spend are dark in their column, not orange (${fills.join(',').slice(0, 120)})`);
    const rs = enemy.getSystem('reactor');
    ok(Renderer.moduleIconState(rs) === 'running', 'their running core has a lit icon, not a grey one');
    quietly(() => CombatManager.end());
  }
})();

// ============================================================
section('315. On the ship (128): their side read off red-framed health boxes, keys at the hands, the frozen in the painted slabs, ship doors, everything in a duct behind its grille, bigger flush nacelles, a honeycomb shield, a meal and a dose you can see, a gun dropped on the roof');
// ============================================================
(function testUpdate128() {
  const fs = require('fs'), path = require('path'), zlib = require('zlib');
  const ROOT = path.join(__dirname, '..');
  const sb = loadEngine();
  const { Ship, Door, CrewMember, CrewArt, Renderer, HULL_GRID, HULL_ART, Save } = sb;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();
  const readPng = (file) => {
    const b = fs.readFileSync(file);
    const w = b.readUInt32BE(16), h = b.readUInt32BE(20);
    const idat = []; let o = 8;
    while (o < b.length) { const len = b.readUInt32BE(o), t = b.toString('ascii', o + 4, o + 8); if (t === 'IDAT') idat.push(b.slice(o + 8, o + 8 + len)); o += 12 + len; }
    const raw = zlib.inflateSync(Buffer.concat(idat)), px = Buffer.alloc(w * h * 4), st = w * 4;
    for (let y = 0; y < h; y++) {
      const f = raw[y * (st + 1)];
      for (let x = 0; x < st; x++) {
        const v = raw[y * (st + 1) + 1 + x], a = x >= 4 ? px[y * st + x - 4] : 0, up = y ? px[(y - 1) * st + x] : 0, ul = (y && x >= 4) ? px[(y - 1) * st + x - 4] : 0;
        let r = v;
        if (f === 1) r = v + a; else if (f === 2) r = v + up; else if (f === 3) r = v + ((a + up) >> 1);
        else if (f === 4) { const p0 = a + up - ul, pa = Math.abs(p0 - a), pb = Math.abs(p0 - up), pc = Math.abs(p0 - ul); r = v + (pa <= pb && pa <= pc ? a : pb <= pc ? up : ul); }
        px[y * st + x] = r & 255;
      }
    }
    return { w, h, at: (x, y) => [px[(y * w + x) * 4], px[(y * w + x) * 4 + 1], px[(y * w + x) * 4 + 2]] };
  };
  const hex = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));

  /* ── 1. THE KEYS ARE AT HIS HANDS ─────────────────────────── */
  {
    const T = { weapons: '#ff5566', engines: '#1aff8c', piloting: '#9fdcff', shields: '#4db8ff' };
    const bad = [];
    Object.entries(T).forEach(([t, c]) => {
      const img = readPng(path.join(ROOT, 'art', 'room_' + t + '.png'));
      const col = hex(c);
      const rows = new Set();
      for (let y = 20; y < 37; y++) for (let x = 32; x < 68; x++) { const p = img.at(x, y); if (p[0] === col[0] && p[1] === col[1] && p[2] === col[2]) rows.add(y); }
      const keyRows = [...rows];
      if (!keyRows.length || Math.min(...keyRows) < 29 || Math.max(...keyRows) > 33) bad.push(`${t}: ${keyRows.join(',') || 'no keys'}`);
    });
    ok(bad.length === 0, `every console's keys sit at the operator's hands, not his helmet — one row for all (${bad.join('; ') || 'rows 29–33'})`);
    // the operator: his hands are about there — the walk line minus his lift, a third of the way down his body
    const sh = new Ship('frigate', true, 170, 180), room = sh.rooms[0];
    const [, oy] = sh.stationSlot(room, 0);
    const handY = (oy - room.floorTop) * (50 / room.floorH);
    ok(handY > 28 && handY < 46, `the keys are below his visor and above his boots (${handY.toFixed(1)} of 50)`);
  }

  /* ── 2. THE FROZEN, IN THE SLABS THE BAY IS PAINTED WITH ──── */
  {
    const sh = new Ship('frigate', true, 0, 0);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const r = sh.rooms.find(q => q.type === 'empty');
    sh.addModuleAt('carbonite', r.id);
    powerModule(sh, 'carbonite', 3);
    sh.update(0.016);
    const pod = sh.getSystem('carbonite'), bay = sh.getRoomById(pod.roomId);
    const men = sh.crew.filter(c => c.isPlayer && !c.isPet).slice(0, 3);
    men.forEach(c => { c.roomId = bay.id; ok(sh.freezeCrew(c).ok, `test setup: ${c.name} under`); });
    const A = Ship.SLAB_ART;
    ok(A.xs.join() === '24,50,76', 'the slabs are where the bay\'s picture paints them');
    const idx = men.map(c => c._slabIdx);
    ok(new Set(idx).size === 3 && idx.every(i => i >= 0 && i <= 2), `each man has a slab of his own (${idx.join(',')})`);
    const off = men.map(c => {
      const want = bay.x + A.xs[c._slabIdx] * bay.w / A.W;
      return Math.abs(c.x - want);
    });
    ok(off.every(d => d < 0.5), `and stands in its window, on the picture (${off.map(d => d.toFixed(1)).join(',')})`);
    ok(men.every(c => c._slab && c._slab.w < 20 && c._slab.h < bay.floorH), 'the ice is the window: smaller than the old box, inside the room');
    // knocked off his window (a reload, a ship that moved): the ship puts him back
    men.forEach(c => { c.x += 37; c.y -= 11; });
    for (let i = 0; i < 2; i++) sh.update(0.05);
    ok(men.every(c => Math.abs(c.x - (c._slab.x + c._slab.w / 2)) < 0.5 && Math.abs(c.y - (c._slab.y + c._slab.h / 2)) < 0.5),
       'and the ship keeps him there, frame after frame');
    const back = CrewMember.deserialise(men[1].serialise());
    ok(back._slabIdx === men[1]._slabIdx, 'his slab is in the save');
    sh.thawCrew(men[0]);
    ok(men[0]._slabIdx == null && men[0]._slab == null && men[0].roomId === bay.id, 'thawed, he leaves the slab for the deck');
    // the name only under the pointer
    const said = [];
    const realFT = ctx.fillText;
    ctx.fillText = function (t) { said.push(String(t)); };
    sb.Input.mouse.x = -100; sb.Input.mouse.y = -100;
    try { men[1].draw(ctx); } finally { ctx.fillText = realFT; }
    ok(!said.includes(men[1].name), 'three names do not stack over the slabs — none without the pointer');
    sb.Input.mouse.x = men[1]._slab.x + 2; sb.Input.mouse.y = men[1]._slab.y + 2;
    said.length = 0;
    ctx.fillText = function (t) { said.push(String(t)); };
    try { men[1].draw(ctx); } finally { ctx.fillText = realFT; }
    ok(said.includes(men[1].name), 'point at a slab and it says who is in it');
  }

  /* ── 3. DUCT CONTENTS BEHIND THE GRILLE ─────────────────────── */
  {
    const sh = new Ship('frigate', true, 170, 180);
    const order = [];
    const realV = sh._drawVents.bind(sh), realE = sh._drawEggs.bind(sh);
    sh._drawVents = (c, layer) => { order.push('vent:' + layer); };
    sh._drawEggs = () => order.push('eggs');
    sh.pests.push({ _climb: false, dead: false, draw: () => order.push('pest') });
    const cat = sb.makeCat();
    cat._ductY = 10; cat.draw = () => order.push('cat');
    sh.crew.push(cat);
    try { sh.draw(ctx); } catch (e) {}
    const front = order.indexOf('vent:front');
    ok(order.indexOf('vent:back') < order.indexOf('eggs') && order.indexOf('pest') < front && order.indexOf('cat') < front && order.indexOf('eggs') < front,
       `eggs, pests and the cat on a hunt are drawn between the duct's back and its slats (${order.join(' ')})`);
    ok(order.filter(o => o === 'cat').length === 1, 'the cat in the duct is drawn once, not again with the crew');
  }

  /* ── 4. NACELLES: BIGGER, FLUSH WITH THE STERN ─────────────── */
  ok(HULL_ART.NACELLE.h >= 20 && HULL_ART.NACELLE.overhang === 0 && HULL_ART.PAD_STERN <= HULL_GRID.TILE,
     `the nacelles are bigger (${HULL_ART.NACELLE.h} px) and do not stick out past the stern`);

  /* ── 5. THE SHIELD IS A HONEYCOMB ─────────────────────────── */
  {
    const sh = new Ship('frigate', true, 170, 180);
    sh._allocateDefaultPower();
    const ss = sh.getSystem('shields'); ss._shieldMax = 2; ss._shieldBars = 2;
    let hexes = 0, plainCore = 0;
    const real = { lineTo: ctx.lineTo, ellipse: ctx.ellipse, stroke: ctx.stroke };
    let segs = 0, lastEll = null;
    ctx.lineTo = function () { segs++; return real.lineTo && real.lineTo.apply(this, arguments); };
    ctx.ellipse = function () { lastEll = { lw: ctx.lineWidth, c: String(ctx.strokeStyle) }; return real.ellipse && real.ellipse.apply(this, arguments); };
    ctx.stroke = function () { if (lastEll && lastEll.c === '#4db8ff' && lastEll.lw === 2) plainCore++; lastEll = null; return real.stroke && real.stroke.apply(this, arguments); };
    try { sh._drawShield(ctx); } finally { Object.assign(ctx, real); }
    hexes = Math.floor(segs / 5);
    ok(hexes > 80, `the bubble is drawn as cells — ${hexes} hexagons for two layers`);
    ok(plainCore === 0, 'and the old solid ring ("an egg") is gone');
  }

  /* ── 6. A MEAL AND A DOSE YOU CAN SEE ──────────────────────── */
  {
    ok(!!CrewArt.STATES.heal && CrewArt.STATES.heal.view === 'front' && CrewArt.STATES.heal.poses.length >= 2,
       'a dose has frames of its own, facing us');
    ok(CrewArt.STATES.eat.poses.length >= 3, `a meal goes tube-up, chew, tube-down (${CrewArt.STATES.eat.poses.length} frames)`);
    const sh = new Ship('frigate', true, 170, 180);
    sb.makeStartingCrew().forEach(c => sh.addCrew(c));
    const m = sh.crew.find(c => c.isPlayer && !c.isPet);
    m._busyAct = 'heal'; m._busyT = 5; m._setAnim('idle');
    ok(m._animKey === 'heal', 'taking a dose, he is drawn taking it');
    const texts = [];
    const realFT = sb.Particles.floatText;
    sb.Particles.floatText = (x, y, t) => texts.push(t);
    try { for (let i = 0; i < 20; i++) m.update(0.05, sh); } finally { sb.Particles.floatText = realFT; }
    ok(texts.filter(t => t === '+').length >= 2, `green crosses rise off him while it works (${texts.length})`);
    m._busyT = 0; m._busyAct = null;
    m.update(0.05, sh);
    ok(m._animKey !== 'heal', 'and stop with it');
  }
})();

// ============================================================
section('316. The fight panels (130): the reactor lies down under the row (jj\'s sketch), their side on one panel top right — hull, pills, bubbles, commander and module strip — the shield charge in words, and a resource plate with an isotope and a ration tin');
// ============================================================
(function testUpdate130() {
  const sb = loadEngine();
  const { Ship, Renderer, Save, Commander } = sb;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const W = Renderer.getWidth(), H = Renderer.getHeight();
  const me = new Ship('frigate', true, 80, 120); me._allocateDefaultPower(); me.update(0.05);
  const foe = new Ship('enemy_frigate', false, Ship.ENEMY_STATION.x, Ship.ENEMY_STATION.y);
  foe._allocateDefaultPower(); foe.update(0.05);
  const draw = (o = {}) => captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: me, enemyShip: foe, ...o })));

  /* ── 1. A: THE CORE IN THE CORNER, ITS PIPS UNDER THE ROW ─── */
  /* Since update134 the default is the systems panel ('S', section 320);
     A, B and the column stay behind the switch and are checked here. */
  Renderer.setReactorLayout('A');
  ok(Renderer.reactorLayout() === 'A', `jj's sketch is still one switch away (${Renderer.reactorLayout()})`);
  let text = draw();
  const bar = Renderer.reactorBarRect();
  const zones = Renderer.getPowerClickZones();
  const core = zones.find(z => z.reactorToggle);
  const mods = zones.filter(z => z.sysToggleIndex !== undefined || z.sysActivateIndex !== undefined);
  ok(!!bar && !!core && core.x < 40 && core.y + core.h > H - 12,
     `the core's icon sits in the bottom-left corner and still SCRAMs (${core && Math.round(core.x)},${core && Math.round(core.y)})`);
  ok(mods.length > 0 && mods.every(z => z.y + z.h < bar.y),
     `every module icon is above the bar (bar at y ${bar && Math.round(bar.y)})`);
  ok(bar.x > core.x + core.w && bar.w > 120, `the bar runs right of the core, under the row (${Math.round(bar.x)}…${Math.round(bar.x + bar.w)})`);
  ok(bar.fills.length === Renderer.reactorPips(me).length &&
     Renderer.reactorPips(me).every((p, i) => bar.fills[i] === p.fill),
     'its pips are the core\'s own list, left to right');
  ok(text.some(t => t.t === 'Engines') && text.some(t => /^REACTOR \d+\/\d+$/.test(t.t)),
     'the names stay, and the bar says REACTOR free/rated beside it');
  ok(!zones.some(z => z.pip !== undefined && z.y > bar.y), 'no module pip is drawn down in the bar\'s row');

  /* ── 2. B: THE ROW STAYS, THE NAMES MAKE ROOM ─────────────── */
  Renderer.setReactorLayout('B');
  text = draw();
  const barB = Renderer.reactorBarRect();
  ok(!text.some(t => t.t === 'Engines' || t.t === 'Shields'), 'B: no module names under the icons');
  ok(Renderer.getPowerClickZones().filter(z => z.sysToggleIndex !== undefined).every(z => z.y + z.h < barB.y),
     'B: the bar lies where the names were, under the icons');
  Renderer.setReactorLayout('column');
  draw();
  ok(Renderer.reactorBarRect() === null, 'and the old column is still one switch away');
  Renderer.setReactorLayout('A');
  ok(Renderer.setReactorLayout('sideways') === 'A', 'a layout that does not exist changes nothing');

  /* ── 3. THEIR PANEL: EVERYTHING OF THEIRS, TOP RIGHT ──────── */
  const cap = Commander.fromCrew({ id: 'f', name: 'Vor', race: 'phoenix', skills: {} });
  cap.level = 6; Commander.setEnemy(cap);
  text = draw();
  const P = Renderer.enemyPanelRect();
  const inP = (x, y) => P && x >= P.x && x <= P.x + P.w && y >= P.y && y <= P.y + P.h;
  ok(!!P && P.x > W * 0.55 && P.y < 20, `their panel is in the top-right corner (${P && Math.round(P.x)},${P && Math.round(P.y)})`);
  const ev = text.filter(t => t.t === 'EVADE' || t.t === 'OXYGEN');
  ok(ev.length >= 2 && ev.filter(t => t.x > W / 2).every(t => inP(t.x, t.y)), 'their EVADE and OXYGEN are on it');
  const badge = text.find(t => /^Phoenix L6$/.test(t.t));
  ok(!!badge && inP(badge.x, badge.y), `their commander's badge is on it (${badge && badge.t})`);
  const eb = Renderer.enemyReactorBar();
  ok(!!eb && inP(eb.x, eb.y) && inP(eb.x + eb.w, eb.y + eb.h), 'their reactor bar is on it');
  ok(eb.fills.length === Renderer.reactorPips(foe).length, 'one pip per unit of their core');
  const fb = foe.roomBounds();
  ok(P.y + P.h < fb.y, `and the whole panel ends above their hull (${Math.round(P.y + P.h)} < ${Math.round(fb.y)})`);
  Commander.setEnemy(null);
  text = draw();
  ok(!text.some(t => /^Phoenix L6$/.test(t.t)), 'no commander, no badge');

  /* ── 4. THE SHIELD CHARGE IN WORDS ────────────────────────── */
  const ss = me.getSystem('shields');
  ok(me.shieldMax > 0, `test setup: our shields are up to a layer (${me.shieldMax})`);
  ss._shieldBars = 0; ss._shieldTimer = 0.62 * (ss._shieldNeed ?? 7);
  text = draw();
  let ours = Renderer.chargeStrips().find(c => c.isPlayer);
  ok(!!ours && ours.txt === 'CHARGING 62%' && Math.abs(ours.prog - 0.62) < 1e-9,
     `our charge strip fills to 62% and says so (${ours && ours.txt})`);
  ok(text.some(t => t.t === 'CHARGING 62%'), 'and the words are on screen');
  ss._shieldBars = ss.shieldMax;
  draw();
  ours = Renderer.chargeStrips().find(c => c.isPlayer);
  ok(ours && ours.txt === 'SHIELDS UP' && ours.prog === 1, 'full: SHIELDS UP');
  me.setPower('shields', 0); me.update(0.05);
  draw();
  ours = Renderer.chargeStrips().find(c => c.isPlayer);
  ok(!me.shieldMax || (ours && ours.txt === 'NO POWER'), `switched off: NO POWER, or no layers left to show (${ours && ours.txt})`);
  me._allocateDefaultPower(); me.update(0.05);

  /* ── 5. OUR PANEL HOLDS OUR READOUTS ──────────────────────── */
  text = draw();
  const O = Renderer.ourPanelRect();
  const ourEv = text.find(t => t.t === 'EVADE' && t.x < W / 2);
  ok(!!O && !!ourEv && ourEv.x > O.x && ourEv.y < O.y + O.h, 'our EVADE sits on our own panel');
  ok(O.y + O.h <= 108, `and the panel ends above the crew list (${O.y + O.h})`);

  /* ── 6. THE RESOURCE PLATE ────────────────────────────────── */
  ['he3', 'ration', 'fuel', 'credits'].forEach(k =>
    ok(Array.isArray(Renderer.STAT_ICONS[k]) && Renderer.statIconSVG(k, '#fff').length > 40, `a ${k} pictogram, on canvas and in SVG`));
  ok(JSON.stringify(Renderer.STAT_ICONS.he3) !== JSON.stringify(Renderer.STAT_ICONS.ore) &&
     JSON.stringify(Renderer.STAT_ICONS.ration) !== JSON.stringify(Renderer.STAT_ICONS.eating),
     'He3 is no longer the cut stone, and the stock in the hold is not the crewman\'s mess tin');
  text = draw();
  ok(['He2 ', 'He3 ', ' CC', 'SEC '].every(w => text.some(t => t.t.includes(w))), 'the same words on the plate as before');
  const icons = Renderer.hudIcons();
  ok(['credits', 'fuel', 'he3', 'ration'].every(k => icons.includes(k)) && !icons.includes('ore'),
     `the plate draws the new pictograms, not the old stone (${[...new Set(icons)].join(' ')})`);
  Renderer.setReactorLayout('S');         // back to the default (update134)
})();

// ============================================================
section('317. The chase on the title screen is a fight (131): your own hull as fitted and manned, a fitted raider behind it, real shots, shields that fall and come back, nothing damaged, and the roof lifts under the pointer');
// ============================================================
(function testUpdate131() {
  const sb = loadEngine();
  const { Save, Game, Ship, Base, UI, WeaponArt, Input } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const SDate = require('vm').runInContext('Date', sb);
  const SMath = require('vm').runInContext('Math', sb);
  Save.reset?.(); Save.load(); T.STATE = 'menu';
  const realNow = SDate.now;
  let ms = 48000 * 3000 + 26000;                  // mid-pass: both hulls on the screen
  const tick = (n, dt = 0.05) => { for (let i = 0; i < n; i++) { ms += dt * 1000; SDate.now = () => ms; T._menuFightTick(dt, ms / 1000); } };
  try {
    /* ── 1. YOUR HULL AS SHE IS, MANNED BY HER OWN ────────────── */
    Save.startRun();
    const fitted = new Ship('frigate', true, 0, 0);
    const empty = fitted.rooms.find(r => r.type === 'empty');
    if (empty) fitted.addModuleAt('medbay', empty.id);
    const crew = sb.makeStartingCrew().slice(0, 2).map(c => c.serialise());
    Save.updateRun({ shipKey: 'frigate', ship: fitted.serialise(), crew });
    const quietNotes = [], buildSounds = [];
    const realNotify = UI.notify;
    UI.notify = (t) => quietNotes.push(t);
    const sfx0 = sb.Audio.sfx, keep0 = {};
    Object.keys(sfx0).forEach(k => { if (typeof sfx0[k] === 'function') { keep0[k] = sfx0[k]; sfx0[k] = () => buildSounds.push(k); } });
    let you;
    try { you = T._menuShipFor(); } finally { UI.notify = realNotify; Object.assign(sfx0, keep0); }
    ok(buildSounds.length === 0, `walking her men to their posts makes no sound on the title screen (${buildSounds.slice(0, 3).join(', ')})`);
    ok(you && you.getSystem('medbay') && T._menuShipSource().data === Save.getRun().ship,
       'the hull that flies past is the contract\'s own record — the module bought out there is on her');
    ok(you.crew.length === 2, `and her own two men are aboard (${you.crew.length})`);
    ok(quietNotes.length === 0 && you.isPreview, 'manned in silence, as a picture — no clocks run on her');
    ok(T._menuShipFor() === you, 'kept while the record is the same');
    Save.updateRun({ ship: fitted.serialise() });
    ok(T._menuShipFor() !== you, 'and built again the moment the record changes (the update68 lesson)');
    you = T._menuShipFor();
    ok(you.weaponMounts().every(m => m.dir === -1), 'your guns point back over the stern, at the raider');

    /* ── 2. THE RAIDER IS FITTED FOR A FIGHT ──────────────────── */
    const foe = T._menuFoeShip();
    const kinds = new Set(foe.weapons.filter(Boolean).map(w => w.defKey));
    ok(foe.getSystem('shields') && foe.shieldBars > 0, `the raider carries a shield, up (${foe.shieldBars})`);
    ok(kinds.size >= 2, `and a mixed rack — the new guns (${[...kinds].join(', ')})`);
    ok(foe.weaponMounts().every(m => m.dir === 1) && foe.crew.length > 0, 'its guns point forward, at you, and it is crewed');

    /* ── 3. THEY FIGHT — AND NOTHING IS DAMAGED ───────────────── */
    const hull0 = [you.hull, foe.hull];
    const lv0 = JSON.stringify([you, foe].map(sh => sh.systems.map(x => x.damagedLevels)));
    const hp0 = JSON.stringify([you, foe].map(sh => sh.crew.map(c => c.hp)));
    const sounds = [];
    const sfx = sb.Audio.sfx, realSfx = {};
    Object.keys(sfx).forEach(k => { if (typeof sfx[k] === 'function') { realSfx[k] = sfx[k]; sfx[k] = () => sounds.push(k); } });
    const sides = new Set(), fx = new Set();
    const realAdd = WeaponArt.add;
    WeaponArt.add = function (f) { fx.add(f.kind); return realAdd.apply(this, arguments); };
    try {
      for (let i = 0; i < 200; i++) { tick(1); T._menuFight().shots.forEach(p => sides.add(p.fromPlayer ? 'you' : 'foe')); }
    } finally { WeaponArt.add = realAdd; Object.assign(sfx, realSfx); }
    ok(sides.has('you') && sides.has('foe'), `both hulls fire (${[...sides].join(' + ')}; ${T._menuFight().fired} shots)`);
    // every shot ends on a plate OR on a bubble — either is the fight's own effect (update135: a run where
    // every bolt met a shield read as a failure)
    ok(fx.has('muzzle') && (fx.has('laser') || fx.has('heavy') || fx.has('ion') || fx.has('missile') || fx.has('shield')),
       `the same muzzle flashes and blasts as a fight (${[...fx].join(' ')})`);
    ok(T._menuFight().shots.every(p => p instanceof sb.Projectile), 'each shot a real Projectile');
    ok(you.hull === hull0[0] && foe.hull === hull0[1] &&
       JSON.stringify([you, foe].map(sh => sh.systems.map(x => x.damagedLevels))) === lv0 &&
       JSON.stringify([you, foe].map(sh => sh.crew.map(c => c.hp))) === hp0,
       'and nothing is damaged: hulls, modules and men exactly as they were');
    ok(sounds.length === 0, `the title screen fights in silence (${sounds.slice(0, 4).join(', ')})`);
    const allGuns = [you, foe].flatMap(sh => sh.weapons.filter(Boolean));
    ok(allGuns.every(w => w.charge >= 0 && w.charge <= 1 && !w.armed) && allGuns.some(w => w.charge > 0.05),
       'the charge boxes on the guns fill as they charge (picture only — never armed)');

    /* ── 4. A SHIELD FALLS AND COMES BACK ─────────────────────── */
    {
      const ss = foe.getSystem('shields');
      ss._shieldBars = ss._shieldMax;
      const f = T._menuFlyby(ms / 1000, you, foe);
      const e = foe.shieldEllipse();
      const c = T._menuToConvoy(f, 'foe', e.cx, e.cy);
      const p = new sb.Projectile({ x: c.x + e.rx + 40, y: c.y, targetX: c.x, targetY: c.y, speed: 400,
                                    type: 'laser', def: sb.WEAPON_DEFS.laser_basic, defKey: 'laser_basic', fromPlayer: true });
      p._menu = { target: 'foe', room: foe.rooms[0] };
      T._menuFight().shots.length = 0; T._menuFight().queue.length = 0;
      T._menuFight().shots.push(p);
      const keepR = SMath.random; SMath.random = () => 0.99;      // no dodge
      const lit = [];
      WeaponArt.add = function (f2) { lit.push(f2.kind); return realAdd.apply(this, arguments); };
      const before = foe.shieldBars;
      try { for (let i = 0; i < 20 && foe.shieldBars === before; i++) tick(1); }
      finally { SMath.random = keepR; WeaponArt.add = realAdd; }
      ok(foe.shieldBars === before - 1 && lit.includes('shield'), `a laser on the bubble knocks a layer down and lights the honeycomb (${before} → ${foe.shieldBars})`);
      // …and one that is dodged flies on past, the bubble untouched
      const bars = foe.shieldBars;
      const q = new sb.Projectile({ x: c.x + e.rx + 40, y: c.y, targetX: c.x, targetY: c.y, speed: 400,
                                    type: 'laser', def: sb.WEAPON_DEFS.laser_basic, defKey: 'laser_basic', fromPlayer: true });
      q._menu = { target: 'foe', room: foe.rooms[0] };
      T._menuFight().shots.length = 0; T._menuFight().queue.length = 0;
      T._menuFight().shots.push(q);
      const keepR2 = SMath.random; SMath.random = () => 0;
      const missed = [];
      WeaponArt.add = function (f2) { missed.push(f2.kind); return realAdd.apply(this, arguments); };
      try { for (let i = 0; i < 20 && !q.flyOn; i++) tick(1); }
      finally { SMath.random = keepR2; WeaponArt.add = realAdd; }
      ok(q.flyOn && missed.includes('miss') && foe.shieldBars === bars, 'a dodged shot flies on past, the bubble untouched');
      // wait with the hulls off the screen, so no new shot takes it down again
      const keepMs = ms; ms = 48000 * 3000 + 500;
      T._menuFight().shots.length = 0; T._menuFight().queue.length = 0;
      tick(Math.ceil(T._menuFightCfg().shieldBack / 0.05) + 2);
      ms = keepMs;
      ok(foe.shieldBars >= before, `and the layer comes back (${foe.shieldBars})`);
      ok(!(foe._shieldWaves ?? []).length, 'and the wave the hit started has run out (update142)');
    }

    /* ── 5. OFF THE SCREEN, NOBODY FIRES ──────────────────────── */
    {
      ms = 48000 * 3000 + 500;                    // the start of a pass: both off the left edge
      T._menuFight().shots.length = 0; T._menuFight().queue.length = 0;
      const n0 = T._menuFight().fired;
      tick(60);
      ok(T._menuFight().fired === n0, 'no firing while they are off the screen');
      ms = 48000 * 3000 + 26000;
    }

    /* ── 6. THE ROOF LIFTS UNDER THE POINTER ──────────────────── */
    {
      tick(1);
      const f = T._menuFlyby(ms / 1000, you, foe);
      const r = T._menuHullRect(f.foe);
      Input.mouse.x = r.x + r.w / 2; Input.mouse.y = r.y + r.h / 2;
      tick(10);
      ok(T._menuFight().hovered === 'foe' && foe.roofAlpha === 0 && you.roofAlpha === 1,
         'over the raider: its roof comes off and you see its men; yours stays on');
      const ry = T._menuHullRect(T._menuFlyby(ms / 1000, you, foe));
      Input.mouse.x = ry.x + ry.w / 2; Input.mouse.y = ry.y + ry.h / 2;
      tick(10);
      ok(you.roofAlpha === 0 && foe.roofAlpha === 1, 'over yours: the same for your hull');
      Input.mouse.x = 5; Input.mouse.y = 5;
      tick(2);
      ok(you.roofAlpha > 0 && you.roofAlpha < 1, 'the roof goes back on — eased, not snapped');
      tick(10);
      ok(you.roofAlpha === 1, 'and is shut again');
      T.menuConfirm = true;
      Input.mouse.x = ry.x + ry.w / 2; Input.mouse.y = ry.y + ry.h / 2;
      tick(10);
      ok(T._menuFight().hovered === null && you.roofAlpha === 1, 'with the NEW GAME question up, nothing lifts');
      T.menuConfirm = false;
    }

    /* ── 6b. THE MENU'S OWN LOOP RUNS THE FIGHT ───────────────── */
    {
      const n0 = T._menuFight().fired;
      Input.mouse.x = 5; Input.mouse.y = 5;
      for (let i = 0; i < 200; i++) { ms += 50; SDate.now = () => ms; T._updateMenu(0.05); }
      ok(T._menuFight().fired > n0, `the title screen's own update drives it (${T._menuFight().fired - n0} shots)`);
    }

    /* ── 7. NO CONTRACT: THE FIRST HULL IN THE HANGAR, AS FITTED ── */
    {
      Save.updateRun({ shipKey: null, ship: null });
      const src = T._menuShipSource();
      const e0 = Base.ships()[0];
      ok(src.key === (e0?.key ?? 'scout') && src.data === (e0?.data ?? null), 'no contract: the hangar\'s first record');
    }
  } finally { SDate.now = realNow; }
})();

// ============================================================
section('318. A longer, wider sector (132): nine columns by five rows, eight jumps to the far edge, five entry lanes, the boss in the middle row, no more stations than before, and the screen and the click on one rectangle');
// ============================================================
(function testUpdate132() {
  const sb = loadEngine();
  const { SectorMap, Save, Game, Renderer, Ship, UI, Input } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();
  const G = SectorMap.GRID;

  /* ── 1. THE GRID ─────────────────────────────────────────── */
  ok(G.cols === 9 && G.rows === 5, `nine columns by five rows (${G.cols}×${G.rows})`);
  const maps = [];
  for (let i = 1; i <= 400; i++) maps.push(new SectorMap(1, i * 7919 + 13, null, 3, true));
  ok(maps.every(m => new Set(m.nodes.map(n => n.col)).size === G.cols), 'every column has nodes on every map');
  ok(maps.every(m => m.startNodes.length === G.rows), `five entry lanes to pick from in sector 1 (${maps[0].startNodes.length})`);
  ok(maps.every(m => m.nodes.every(n => n.row >= 0 && n.row < G.rows && n.x >= 0 && n.x <= G.w && n.y >= 0 && n.y <= G.h)),
     'every node inside the map rectangle');

  /* ── 2. EIGHT JUMPS, AND NO DEAD ENDS ────────────────────── */
  const hops = (m) => {
    let front = m.startNodes.map(n => n.id), d = 0;
    const exits = new Set(m.nodes.filter(n => n.col === G.cols - 1).map(n => n.id));
    while (front.length && d < 30) {
      if (front.some(id => exits.has(id))) return d;
      front = [...new Set(front.flatMap(id => m.getNode(id).next))]; d++;
    }
    return -1;
  };
  ok(maps.every(m => hops(m) === G.cols - 1), `from an entry node to the far edge is ${G.cols - 1} jumps (was 5)`);
  ok(maps.every(m => m.nodes.every(n => (n.col === 0 || n.prev.length > 0) && (n.col === G.cols - 1 || n.next.length > 0))),
     'no node without a way in or a way out');

  /* ── 3. THE BOSS IN THE MIDDLE ROW ───────────────────────── */
  const fin = new SectorMap(3, 4242, 1, 3, true);
  const boss = fin.nodes.filter(n => n.type === 'boss');
  ok(boss.length === 1 && boss[0].row === SectorMap.MID_LANE && SectorMap.MID_LANE === 2,
     `one boss, in the middle of five rows (row ${boss[0]?.row})`);

  /* ── 4. NO MORE STATIONS THAN BEFORE (jj) ────────────────── */
  const stores = maps.map(m => m.nodes.filter(n => n.type === 'store').length);
  const two = stores.filter(k => k === 2).length / stores.length;
  ok(stores.every(k => k >= 1 && k <= 2), 'one or two stations per sector, as before');
  ok(two > 0.05 && two < 0.3, `and two only as often as on the old map (~16%): ${(two * 100).toFixed(0)}%`);
  ok(SectorMap.STORE_THIN === 3, 'the station is thinned three to one against the rest');

  /* ── 5. THE SCREEN AND THE CLICK ON ONE RECTANGLE ────────── */
  const W = Renderer.getWidth(), H = Renderer.getHeight();
  const org = SectorMap.origin(W, H);
  ok(org.x === Math.round((W - G.w) / 2), 'the map is centred');
  const m = new SectorMap(1, 99, null, 3, true);
  const shifts = [];
  const realT = ctx.translate;
  ctx.translate = function (x, y) { shifts.push([x, y]); return realT.apply(this, arguments); };
  try { Renderer.drawMapScreen(m, null, null); } finally { ctx.translate = realT; }
  ok(shifts.some(([x, y]) => x === org.x && y === org.y), `the screen draws the map at SectorMap.origin (${org.x}, ${org.y})`);
  const sh = new Ship('frigate', true, 80, 120);
  sh._allocateDefaultPower();
  sb.makeStartingCrew().forEach(c => sh.addCrew(c));     // a crewless hull is a lost one
  T.playerShip = sh; T.sectorMap = m; T.STATE = 'map';
  const lane = m.startNodes.find(n => n.row === 3);
  const notes = [];
  const realNotify = UI.notify;
  UI.notify = (t) => notes.push(String(t));
  Input.mouse.x = lane.x + org.x; Input.mouse.y = lane.y + org.y; Input.mouse.leftPressed = true;
  try { T._updateMap(0.016); } finally { Input.mouse.leftPressed = false; UI.notify = realNotify; }
  ok(m.currentId === lane.id, 'a click on a node where it is drawn picks it');
  ok(notes.some(t => /LOWER/.test(t)) && SectorMap.laneName(3) === 'LOWER', `and the notice names the lane (${notes.find(t => /lane/.test(t))})`);

  /* ── 6. A NEW SECTOR WITH NO LANE ON RECORD STARTS IN THE MIDDLE ── */
  Save.updateRun({ mission: 'patrol', finalSector: 3, sector: 1, lane: undefined });
  T._nextSector();
  ok(T.sectorMap.current()?.row === SectorMap.MID_LANE, `no lane on record: the middle lane (${T.sectorMap.current()?.row})`);
})();

// ============================================================
section('319. jj\'s answers (133): no HP boxes over a man at his console in full health, a very rare antiviral serum, and a sign for each corporation');
// ============================================================
(function testUpdate133() {
  const sb = loadEngine();
  const { Ship, Save, Game, Renderer, CrewMember, CARGO_ITEMS } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };

  /* ── 1. THE BOXES GO QUIET AT THE CONSOLE ────────────────── */
  {
    const m = new CrewMember({ name: 'Ola', race: 'aquarius', isPlayer: true });
    m.x = 100; m.y = 100;
    const boxes = () => {
      let n = 0; const real = Renderer.drawPips;
      Renderer.drawPips = function () { n++; return real.apply(this, arguments); };
      try { quiet(() => m.draw(ctx)); } finally { Renderer.drawPips = real; }
      return n;
    };
    m._animKey = 'operate'; m.hp = m.maxHp;
    ok(boxes() === 0 && m._hpBarHidden === true, 'at his console, unhurt: no HP boxes over him');
    m.hp = m.maxHp - 1;
    ok(boxes() === 1 && !m._hpBarHidden, 'one point down and the boxes are back');
    m.hp = m.maxHp; m._animKey = 'idle';
    ok(boxes() === 1, 'off the console, unhurt: the boxes stay (the rule from update38)');
  }

  /* ── 2. THE SERUM ────────────────────────────────────────── */
  {
    const d = CARGO_ITEMS.antiviral_serum;
    ok(d && d.kind === 'cure' && d.w === 1 && d.h === 1, 'Antiviral Serum: one cell, a cure');
    const table = sb.cargoRollTable(1), tot = table.reduce((a, [, w]) => a + w, 0);
    const w = (table.find(([k]) => k === 'antiviral_serum') ?? [])[1] ?? 0;
    ok(w === 1 && w / tot < 0.012, `very rare in a wreck — ${(100 * w / tot).toFixed(2)}% a roll (jj: "bardzo rzadki")`);
    ok(sb.cargoRollTable(5).find(([k]) => k === 'antiviral_serum')[1] === 1, 'and no commoner deeper in');
    const sh = new Ship('frigate', true, 0, 0);
    sh.crew.length = 0;
    const a = new CrewMember({ name: 'A', race: 'terra', isPlayer: true }), b = new CrewMember({ name: 'B', race: 'terra', isPlayer: true });
    sh.addCrew(a); sh.addCrew(b);
    T.playerShip = sh;
    const item = sh.cargo.add('antiviral_serum');
    ok(!!item, 'it goes into the hold');
    let r = T._unpackCargo(item);
    ok(!r.ok && /Nobody/.test(r.message), 'with nobody bitten it is not spent');
    a.virus = true; a.virusT = 200; b.virus = true; b.virusT = 40;
    r = T._unpackCargo(item);
    ok(r.ok && r.consumed && !b.virus && a.virus, `the man with the least time left gets it (${r.message})`);
    ok(b.virusT === sb.VIRUS_SECONDS, 'his clock is put back where a healthy man\'s is');
    ok(/serum/.test(CARGO_ITEMS.medkit.desc), 'the medkit\'s card says where the cure is now');
  }

  /* ── 3. A SIGN FOR EACH HOUSE ────────────────────────────── */
  {
    const keys = ['aquarius', 'pegasus', 'terra', 'phoenix'];
    const shapes = keys.map(k => JSON.stringify(Renderer.STAT_ICONS['corp_' + k]));
    ok(shapes.every(x => x && x !== 'undefined') && new Set(shapes).size === 4, 'four corporations, four different signs');
    const drawn = [];
    const real = Renderer.drawStatIcon;
    const icons0 = () => { quiet(() => Renderer.drawHUD({ playerShip: T.playerShip })); return Renderer.hudIcons(); };
    keys.forEach(k => {
      const ok1 = Renderer.drawCorpGlyph(ctx, { race: k }, 0, 0, 10);
      drawn.push(ok1);
    });
    ok(drawn.every(Boolean) && Renderer.drawCorpGlyph(ctx, { race: 'cat_black' }, 0, 0, 10) === false,
       'every house draws its sign; a cat has none');
    const sh = new Ship('frigate', true, 0, 0);
    sh.crew.length = 0;
    keys.forEach(k => sh.addCrew(new CrewMember({ name: k, race: k, isPlayer: true })));
    T.playerShip = sh;
    const seen = icons0();
    ok(keys.every(k => seen.includes('corp_' + k)), `the fight's crew list shows each man's sign (${seen.filter(x => /^corp_/.test(x)).join(' ')})`);
    // …before the NAME, not on the face (update133b, jj)
    const n0 = Renderer.hudIcons().length;
    Renderer.drawCrewPortrait(ctx, sh.crew[0], 0, 0, 40);
    ok(Renderer.hudIcons().length === n0, 'the portrait itself carries no sign — the face stays clean');
    Renderer.drawCrewCard(ctx, sh.crew[2], 0, 0, 'M');
    ok(Renderer.hudIcons().slice(n0).includes('corp_terra'), 'a crew card puts the sign before his name');
    const cap = sb.Commander.fromCrew({ id: 'e', name: 'Vor', race: 'phoenix', skills: {} });
    sb.Commander.setEnemy(cap);
    const foe = new Ship('enemy_frigate', false, Ship.ENEMY_STATION.x, Ship.ENEMY_STATION.y);
    // our crew list carries a Phoenix of its own — count with and without their commander
    sb.Commander.setEnemy(null);
    quiet(() => Renderer.drawHUD({ playerShip: sh, enemyShip: foe }));
    const without = Renderer.hudIcons().filter(x => x === 'corp_phoenix').length;
    sb.Commander.setEnemy(cap);
    quiet(() => Renderer.drawHUD({ playerShip: sh, enemyShip: foe }));
    const withCap = Renderer.hudIcons().filter(x => x === 'corp_phoenix').length;
    ok(withCap === without + 1, `and their commander's badge carries his house's sign (${without} → ${withCap})`);
    sb.Commander.setEnemy(null);
  }
})();

// ============================================================
section('320. The systems panel (134, jj: Starfield\'s "SHIP SYSTEMS"): a framed column per module, the core under them all, and the hull, evasion, air, shields and gravity on its top edge — in one plate, bottom left');
// ============================================================
(function testUpdate134() {
  const sb = loadEngine();
  const { Ship, Save, Game, Renderer, Input } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const W = Renderer.getWidth(), H = Renderer.getHeight();
  const sh = new Ship('frigate', true, 80, 120);
  sh._allocateDefaultPower(); sb.makeStartingCrew().forEach(c => sh.addCrew(c)); sh.update(0.05);
  T.playerShip = sh;
  const draw = () => captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: sh })));

  /* ── 1. ONE PLATE, BOTTOM LEFT ───────────────────────────── */
  ok(Renderer.reactorLayout() === 'S', `the systems panel is the layout (${Renderer.reactorLayout()})`);
  let text = draw();
  const P = Renderer.sysPanelRect();
  ok(P && P.x < 20 && P.y + P.h <= H - 4 && P.y > H * 0.6, `bottom left, inside the screen (${P && [P.x, P.y, P.w, P.h].join(',')})`);
  ok(Renderer.ourPanelRect() === null && !text.some(t => t.t === 'EVADE' && t.x < W / 2),
     'no separate hull / EVADE / OXYGEN panel top left any more');
  const inP = (x, y) => x >= P.x && x <= P.x + P.w && y >= P.y && y <= P.y + P.h;
  const hullTxt = text.find(t => t.t === `${sh.hull}/${sh.hullMax}`);
  ok(hullTxt && inP(hullTxt.x, hullTxt.y), 'the hull is on the panel, with its number');
  ['EVD', 'O₂', 'SHD', 'GRAV ON'].forEach(w => {
    const t = text.find(d => d.t === w);
    ok(t && inP(t.x, t.y), `${w} is on the panel`);
  });
  ok(text.some(t => t.t === `${Math.round(sh.evasion * 100)}%`), 'with the evasion figure');

  /* ── 2. THE CREW LIST TAKES THE FREED SPACE ──────────────── */
  const rows = Renderer.getPowerClickZones().filter(z => z.crewRef);
  ok(rows.length && Math.min(...rows.map(z => z.y)) < 40, `the crew list starts at the top now (${Math.min(...rows.map(z => z.y))})`);
  ok(Renderer.leftColumnFloor(sh) <= P.y - 8, 'and stops above the panel');

  /* ── 3. A COLUMN PER MODULE; THE CORE UNDER THEM ─────────── */
  const zones = Renderer.getPowerClickZones();
  const mods = sh.systems.filter(x => x.maxPower > 0 && x.type !== 'reactor');
  const toggles = zones.filter(z => z.sysToggleIndex !== undefined || z.sysActivateIndex !== undefined);
  ok(toggles.length === mods.length && toggles.every(z => inP(z.x, z.y)), `a square icon per module, on the panel (${toggles.length}/${mods.length})`);
  mods.forEach(m => {
    const pz = zones.filter(z => z.sysIndex === sh.systems.indexOf(m));
    ok(pz.length === m.maxPower - m.damagedLevels, `${m.type}: a clickable pip per working level (${pz.length})`);
  });
  ok(['ENG', 'SHD', 'HELM', 'O₂'].every(l => text.some(t => t.t === l)), 'short names under the columns');
  const bar = Renderer.reactorBarRect();
  const core = zones.find(z => z.reactorToggle);
  ok(bar && core && inP(bar.x, bar.y) && inP(core.x, core.y) && bar.y > Math.max(...zones.filter(z => z.sysIndex !== undefined).map(z => z.y)),
     'the core\'s bar runs under every column, its icon still SCRAMs');
  ok(bar.fills.length === Renderer.reactorPips(sh).length && Renderer.reactorPips(sh).every((p, i) => bar.fills[i] === p.fill),
     'its pips are the core\'s own list');
  const gunZ = zones.filter(z => z.weapon !== undefined);
  ok(gunZ.length > 0 && gunZ.every(z => z.x > P.x + P.w), 'the gun cards start right of the panel');

  /* ── 4. A CLICK ON A PIP STILL SETS THE POWER ────────────── */
  {
    const med = sh.getSystem('medbay');
    const before = med.power;
    const z = zones.find(q => q.sysIndex === sh.systems.indexOf(med) && q.pip === 0);
    Input.mouse.x = z.x + z.w / 2; Input.mouse.y = z.y + z.h / 2;
    T.STATE = 'combat';
    quiet(() => T._handlePowerBarClick());
    sh.update(0.05);
    ok(med.power !== before, `a click on the medbay's bottom pip changes its power (${before} → ${med.power})`);
    T.STATE = 'menu';
  }

  /* ── 5. THE SHIELDS AND THE GRAVITY IN WORDS ─────────────── */
  {
    const ss = sh.getSystem('shields');
    ss._shieldBars = 0; ss._shieldTimer = 0.4 * (ss._shieldNeed ?? 7);
    text = draw();
    const st = Renderer.chargeStrips().find(c => c.isPlayer);
    ok(st && st.txt === 'CHARGING 40%' && text.some(t => t.t === '40%'), `a layer coming back says how far (${st && st.txt})`);
    ss._shieldBars = ss._shieldMax;
    sh.getSystem('engines').damagedLevels = sh.getSystem('engines').level; sh.update(0.05);
    text = draw();
    ok(!sh.gravityActive && text.some(t => t.t === '⚠ ZERO-G'), 'engines out: ⚠ ZERO-G on the panel');
    sh.getSystem('engines').damagedLevels = 0; sh.update(0.05);
  }
})();

// ============================================================
section('321. Their systems panel (135): the same rows, smaller, top right, nothing clickable; and a crook conned pays karma');
// ============================================================
(function testUpdate135() {
  const sb = loadEngine();
  const { Ship, Save, Renderer, Commander } = sb;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const W = Renderer.getWidth();
  const me = new Ship('frigate', true, 80, 120); me._allocateDefaultPower(); me.update(0.05);
  const foe = new Ship('enemy_frigate', false, Ship.ENEMY_STATION.x, Ship.ENEMY_STATION.y);
  foe._allocateDefaultPower(); foe.update(0.05);
  const draw = (e = foe) => captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: me, enemyShip: e })));

  ok(Renderer.reactorLayout() === 'S', 'the systems panel is on');
  const zonesMine = (() => { draw(null); return Renderer.getPowerClickZones().length; })();
  let text = draw();
  const P = Renderer.enemyPanelRect();
  const inP = (x, y) => P && x >= P.x && x <= P.x + P.w && y >= P.y && y <= P.y + P.h;
  ok(P && P.x + P.w <= W - 4 && P.y < 20 && P.x > W * 0.55, `their panel sits top right, on the screen (${P && [P.x, P.y, P.w, P.h].join(',')})`);
  const hull = text.find(t => t.t === `${foe.hull}/${foe.hullMax}`);
  ok(hull && inP(hull.x, hull.y), 'their hull, with its number');
  ok(['EVD', 'O₂', 'SHD'].every(w => text.some(t => t.t === w && inP(t.x, t.y))), 'their EVD, O₂ and SHD on it');
  const mods = foe.systems.filter(x => x.maxPower > 0 && x.type !== 'reactor');
  const shortNames = ['HELM', 'ENG', 'O₂', 'SHD', 'W1', 'W2', 'WPN', 'MED'];
  const labels = text.filter(t => inP(t.x, t.y) && shortNames.includes(t.t));
  ok(labels.length >= mods.length - 1, `a column per module of theirs (${labels.map(t => t.t).join(' ')})`);
  const eb = Renderer.enemyReactorBar();
  ok(eb && inP(eb.x, eb.y) && eb.fills.length === Renderer.reactorPips(foe).length, 'their core\'s bar under the columns, one pip per unit');
  ok(Renderer.getPowerClickZones().length === zonesMine, 'nothing on their panel can be clicked');
  const st = Renderer.chargeStrips().find(c => !c.isPlayer);
  ok(!foe.shieldMax || (st && st.x + st.w <= W - 4), 'their shield blocks end on the screen');
  const fb = foe.roomBounds();
  ok(Renderer.enemyStripBottom() >= fb.y + fb.h, 'the log still keeps clear of their hull');
  // …and in the old layouts behind the switch (their strip in the old panel, update130)
  Renderer.setReactorLayout('A');
  draw();
  ok(Renderer.enemyStripBottom() >= fb.y + fb.h, 'the old panel keeps the log clear of their hull too');
  Renderer.setReactorLayout('S');

  const cap = Commander.fromCrew({ id: 'e', name: 'Vor', race: 'phoenix', skills: {} });
  cap.level = 4; Commander.setEnemy(cap);
  text = draw();
  const badge = text.find(t => t.t === 'Phoenix L4');
  ok(badge && inP(badge.x, badge.y), 'their commander\'s badge is on their panel');
  Commander.setEnemy(null);
  const mech = new Ship('enemy_mech', false, 850, 120);
  mech._allocateDefaultPower();
  text = draw(mech);
  ok((mech.armor ?? 0) > 0 && text.some(t => t.t === 'ARMOUR' && inP(t.x, t.y)), `a mech says ARMOUR on its panel (${mech.armor})`);

  /* ── A CROOK CONNED ─────────────────────────────────────── */
  ok(Commander.KARMA.CON_A_CROOK > 0 && Commander.KARMA.ROBBERY < 0,
     `saying yes to a wanted pirate and opening fire pays karma (+${Commander.KARMA.CON_A_CROOK}); robbing the helpless still costs (${Commander.KARMA.ROBBERY})`);
})();

// ============================================================
section('322. The event window (136, jj: "dana osoba niby rusza ustami a tekst się pisze tak jakby gadała"): a face that talks, text that types, choices that wait');
// ============================================================
(function testUpdate136() {
  const sb = loadEngine();
  const { Game, EventView, CrewArt, EVENTS, Input, Renderer, Commander } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const { player } = makeCombat(sb);
  T.playerShip = player;
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  ok(typeof EventView === 'object' && typeof EventView.draw === 'function', 'eventview.js is loaded');
  const gsrc = require('fs').readFileSync(require('path').join(__dirname, '..', 'js', 'game.js'), 'utf8');
  ok(/name: 'EventView',\s*src: 'js\/eventview\.js'/.test(gsrc), 'and a stale index.html gets it from the late loader');

  /* ── WHO SAYS WHICH WORD ──────────────────────────────── */
  const txt = 'He waits. "Pay up," he says.';
  const own = EventView.owners(txt, true, true);
  ok(own[0] === 'us' && own[txt.indexOf('waits')] === 'us', 'the narration is ours');
  ok(own[txt.indexOf('Pay')] === 'them' && own[txt.indexOf('"')] === 'them', 'what is inside the quotes is theirs, quote marks and all');
  ok(own[txt.indexOf('says')] === 'us', 'and after the closing quote it is ours again');
  ok(EventView.owners(txt, true, false).every(o => o === 'us'), 'with nobody on the other end, every word is ours');
  ok(EventView.owners(txt, false, false).every(o => o === null), 'and with nobody at all, nobody speaks');

  /* ── THE MOUTH FOLLOWS THE LETTER ─────────────────────── */
  ok(EventView.mouthFor('a') === 'b' && EventView.mouthFor('O') === 'b', 'a vowel opens the mouth wide');
  ok(EventView.mouthFor('t') === 'a' && EventView.mouthFor('7') === 'a', 'a consonant half');
  ok(EventView.mouthFor(' ') === null && EventView.mouthFor('.') === null, 'a space or a stop shuts it');
  ok(EventView.delayAfter('.', ' ') > EventView.delayAfter('a', 'b') * 4, 'a full stop is a breath, not a letter');
  ok(EventView.delayAfter(',', ' ') > EventView.delayAfter('a', 'b'), 'a comma a shorter one');

  /* ── THE TEXT TYPES ITSELF ────────────────────────────── */
  const ev = {
    title: 'A test', text: 'Our sensors see a ship. "Hand it over," their captain says, "and nobody gets hurt."',
    speaker: { seed: 77, role: 'PIRATE', hostile: true },
    choices: [{ label: 'Hand it over', result: {} }, { label: 'Fight', result: { karma: 5 } }],
  };
  EventView.reset();
  T.event = ev; T.STATE = 'event';
  const rep = T._eventReporter();
  ok(rep && rep.rec && !rep.rec.dead && rep.rec.name, `one of ours reports it (${rep && rep.name}, ${rep && rep.role})`);
  const pilot = player.crew.find(c => player.getRoomById(c.roomId)?.type === 'piloting');
  if (pilot) ok(rep.rec === pilot && rep.role === 'PILOT', 'the man at the helm, when there is one');
  let shown = captureText(ctx, () => quiet(() => T._drawEvent(ctx)));
  const v = EventView.view();
  ok(v && v.ev === ev && v.idx <= 1, `the first frame shows next to nothing (${v && v.idx} letters)`);
  ok(shown.some(t => t.t === rep.name), 'our man\'s name is under his face');
  ok(shown.some(t => t.t === 'PIRATE'), 'and the other side\'s role under theirs');
  ok(shown.some(t => t.t === 'Hand it over') && shown.some(t => t.t === 'Fight'), 'the choices can be read while he talks');
  EventView.update(0.3, ev);
  const mid = v.idx;
  ok(mid > 5 && mid < 30, `after 0.3 s about fifteen letters are out, not the whole thing (${mid} of ${ev.text.length})`);
  ok(!EventView.done(), 'he is still talking');
  ok(EventView.speaking() === 'us', 'and it is our man talking — the narration');
  // he reaches the quote
  for (let i = 0; i < 200 && v.own[Math.max(0, v.idx - 1)] !== 'them'; i++) EventView.update(0.02, ev);
  EventView.update(0.02, ev);
  ok(EventView.speaking() === 'them', 'at the quote it is their captain talking');
  let opened = false, ourShut = true;
  for (let i = 0; i < 30 && v.own[Math.max(0, v.idx - 1)] === 'them'; i++) {
    EventView.update(0.02, ev);
    if (EventView.speaking() === 'them' && v.mouth.them.shape) opened = true;
    if (v.mouth.us.shape && v.own[Math.max(0, v.idx - 1)] === 'them') ourShut = false;
  }
  ok(opened, 'and his mouth moves while his words go out');
  ok(ourShut, 'while ours stays shut');

  /* ── A CLICK WHILE HE TALKS FINISHES THE SENTENCE ─────── */
  const rects = () => EventView.draw(ctx, ev, { reporter: rep, hasCommander: false, mouse: { x: -1, y: -1 }, W: Renderer.getWidth(), H: Renderer.getHeight() });
  const L = quiet(() => rects());
  const c0 = L.choices[0];
  Input.mouse.x = c0.x + 20; Input.mouse.y = c0.y + 10; Input.mouse.leftPressed = true;
  quiet(() => T._drawEvent(ctx));
  Input.mouse.leftPressed = false;
  ok(T.STATE === 'event' && T.event === ev, 'a click on a choice while he talks does NOT take it');
  ok(EventView.done() && v.idx === ev.text.length, 'it finishes what he was saying');
  shown = captureText(ctx, () => quiet(() => T._drawEvent(ctx)));
  ok(shown.some(t => /CHOOSE/.test(t.t)), 'and the footer says the choices are open now');

  /* ── …AND A KEY TAKES ONE ─────────────────────────────── */
  sb.Input.isPressed = (c) => c === 'Digit2';
  quiet(() => T._drawEvent(ctx));
  sb.Input.isPressed = () => false;
  ok(T.event !== ev || T.STATE !== 'event', `"2" on the keyboard takes the second choice (state ${T.STATE})`);

  /* ── THE CLICK THAT OPENED IT DOES NOT SKIP IT ────────── */
  EventView.reset();
  const ev2 = { title: 'Again', text: 'A long enough sentence to still be typing.', choices: [{ label: 'Go', result: {} }] };
  T.event = ev2; T.STATE = 'event';
  Input.mouse.leftPressed = true;
  quiet(() => T._drawEvent(ctx));
  Input.mouse.leftPressed = false;
  ok(!EventView.done(), 'the click that landed on the map node a frame ago does not skip his first word');

  /* ── THE OLD RULES STILL HOLD ON THE NEW WINDOW ───────── */
  EventView.update(5, ev2);
  ok(EventView.done(), 'given time, he finishes on his own');

  /* ── A LINE IN QUOTES HAS A FACE TO SAY IT ────────────── */
  const quoted = EVENTS.filter(e => /"/.test(e.text));
  ok(quoted.length >= 5, `several events have somebody else speaking (${quoted.length})`);
  quoted.forEach(e => ok(e.speaker && (e.speaker.role || e.speaker.name),
    `"${e.title}": the words in quotes have a speaker (${e.speaker && e.speaker.role})`));
  const foe = T._foeSpeaker('ON CHANNEL');
  ok(foe && foe.hostile && foe.role === 'ON CHANNEL', 'a hostile channel has a hostile face');
  ok(/speaker: _foeSpeaker\('ON CHANNEL'\)/.test(gsrc) && /speaker: _foeSpeaker\('ENEMY VESSEL'\)/.test(gsrc),
     'the hail and the surrender both put their man on screen');
  ok(/role: 'WANTED'/.test(gsrc) && /role: 'ENEMY COMMANDER'/.test(gsrc), 'the wanted pirate and a beaten commander speak for themselves');

  /* ── EVERY EVENT FITS THE SCREEN ──────────────────────── */
  const W = Renderer.getWidth(), H = Renderer.getHeight();
  const all = [...EVENTS, { title: 'Four doors', text: 'x '.repeat(300), speaker: { seed: 1, role: 'X' },
    choices: [1, 2, 3, 4].map(i => ({ label: 'Choice ' + i, result: {} })) }];
  all.forEach(e => {
    EventView.reset(); EventView.open(e, { reporter: rep });
    const L2 = EventView.layout(e, W, H, s => s.length * 7);
    const P = L2.panel;
    const inside = P.x >= 0 && P.y >= 0 && P.x + P.w <= W && P.y + P.h <= H;
    const last = L2.choices[L2.choices.length - 1];
    const textEnd = L2.text.y + 24 + (L2.lines.length - 1) * 21;
    ok(inside && (!last || last.y + last.h < P.y + P.h - 20) && textEnd < L2.text.y + L2.text.h
       && L2.choices.every((r, i) => i === 0 || r.y >= L2.choices[i - 1].y + L2.choices[i - 1].h)
       && (!L2.choices[0] || L2.choices[0].y > L2.text.y + L2.text.h),
       `"${e.title}": panel on screen, text in its box, choices under it and apart`);
  });
  EventView.reset();

  /* ── THE FACE ITSELF ──────────────────────────────────── */
  const paint = (f) => { const out = []; const g = { fillRect: (x, y, w, h) => out.push([x, y, w, h, g.fillStyle].join()), set fillStyle(v) { this._f = v; }, get fillStyle() { return this._f; },
    save() {}, restore() {}, beginPath() {}, arc() {}, fill() {}, stroke() {} }; CrewArt.portrait(g, 0, 0, '#4db8ff', f, 48); return out; };
  const face = CrewArt.faceOf(1234, null);
  const rest = paint({ ...face, beard: 'none', mouth: 'flat' });
  const wide = paint({ ...face, beard: 'none', mouth: 'flat', talk: 'b' });
  const half = paint({ ...face, beard: 'none', mouth: 'flat', talk: 'a' });
  ok(wide.join('|') !== rest.join('|') && half.join('|') !== wide.join('|'), 'a wide mouth, a half one and a shut one are three pictures');
  ok(!wide.some(r => r.startsWith('20,29,8,1,')), 'the resting mouth is not painted under a talking one');
  const bearded = paint({ ...face, beard: 'full', mouth: 'flat', talk: 'b' });
  const beardAt = bearded.findIndex(r => r.startsWith('15,26,18,9,'));
  const mouthAt = bearded.findIndex(r => r.startsWith('20,27,8,4,'));
  ok(beardAt >= 0 && mouthAt > beardAt, 'a full beard parts when he speaks — the mouth is painted over it');
  const shut = paint({ ...face, glasses: 'none', blink: true });
  const open = paint({ ...face, glasses: 'none' });
  ok(shut.length > open.length, 'and he blinks');
  const lids = [...Array(240)].map((_, i) => EventView.blinking(5, i / 40));
  ok(lids.some(Boolean) && lids.filter(Boolean).length < lids.length / 10, 'now and then — not with his eyes shut half the time');

})();

// ============================================================
section('323. Regolith (137, brief §2.3, jj: "z tymi kolorami to dobry pomysł"): a grey moon, four colours that mean something, a switch in the options');
// ============================================================
(function testUpdate137() {
  const sb = loadEngine();
  const { Game, Palette, Save, Renderer, Input, EventView, CrewArt } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  Save.load();
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  ok(typeof Palette === 'object' && Palette.STATE.amber === '#E0A230' && Palette.STATE.red === '#D9463C'
     && Palette.STATE.green === '#3FA86B' && Palette.STATE.pale === '#8FB6D1', 'the four colours are the brief\'s four');
  const gsrc = require('fs').readFileSync(require('path').join(__dirname, '..', 'js', 'game.js'), 'utf8');
  ok(/name: 'Palette',\s*src: 'js\/palette\.js'/.test(gsrc), 'and a stale index.html gets it from the late loader');

  /* ── WHICH JOB A COLOUR IS DOING ──────────────────────── */
  const job = (c) => Palette.classify(Palette.parse(c));
  [['#4db8ff', 'pale'], ['#1aff8c', 'green'], ['#4dd8c0', 'green'], ['#ff5566', 'red'], ['#ff2d44', 'red'],
   ['#ffb020', 'amber'], ['#ffd700', 'amber'], ['#ff7c20', 'amber'], ['#cc44ff', 'grey'], ['#c8d8f0', 'grey'],
   ['rgba(13,17,32,0.96)', 'grey'], ['#1e2d4a', 'grey'], ['#7a90a8', 'grey']]
    .forEach(([c, j]) => ok(job(c) === j, `${c} is ${j} (${job(c)})`));

  /* ── CLASSIC IS THE GAME AS IT WAS ────────────────────── */
  Palette.set('classic');
  ok(['#4db8ff', 'rgba(26,140,255,0.3)', '#ff5566'].every(c => Palette.remap(c) === c), 'in CLASSIC every colour passes through');

  /* ── REGOLITH ─────────────────────────────────────────── */
  Palette.set('regolith');
  const lum = (c) => { const p = Palette.parse(c); return 0.299 * p.r + 0.587 * p.g + 0.114 * p.b; };
  const sample = ['#4db8ff', '#1aff8c', '#ff2d44', '#ffd700', '#cc44ff', '#c8d8f0', '#2a4060', '#0d1120', '#ff7c20', '#9fdcff'];
  ok(sample.every(c => lum(Palette.remap(c)) <= lum(c) + 3), 'no colour comes out brighter than it went in — a faint line stays faint');
  const near = (a, b) => { const p = Palette.parse(a), q = Palette.parse(b); return ['r', 'g', 'b'].every(k => Math.abs(p[k] - q[k]) <= 8); };
  ok(near(Palette.remap('#ff2d44'), Palette.STATE.red), `a bright red IS the state red (${Palette.remap('#ff2d44')})`);
  ok(Palette.remap('#cc44ff') !== '#cc44ff' && job(Palette.remap('#cc44ff')) === 'grey', 'the violet that meant nothing is grey');
  const panel = Palette.parse(Palette.remap('rgba(13,17,32,0.96)'));
  ok(panel && Math.abs(panel.a - 0.96) < 0.001 && Math.abs(panel.r - panel.b) <= 8 && panel.b - panel.r >= 0, 'a navy panel becomes a grey one, as see-through as it was');
  ok(Palette.remap('transparent') === 'transparent' && Palette.remap(null) === null, 'what it cannot read it leaves alone');
  ok(Palette.raw(() => Palette.remap('#4db8ff')) === '#4db8ff', 'and inside raw() nothing is touched');

  /* ── THE FILTER ON THE SCREEN ─────────────────────────── */
  const sctx = Renderer.getCtx();
  ok(Palette.installed(sctx), 'the screen\'s context wears the filter from the start');
  sctx.fillStyle = '#ff2d44';
  ok(sctx.fillStyle === Palette.remap('#ff2d44'), 'a colour set on the screen arrives translated');
  const gr = sctx.createLinearGradient(0, 0, 1, 1);
  ok(typeof gr.addColorStop === 'function', 'gradients still work');
  Palette.set('classic');
  sctx.fillStyle = '#ff2d44';
  ok(sctx.fillStyle === '#ff2d44', 'and in CLASSIC the screen gets what the game asked for');

  /* ── A FACE KEEPS ITS COLOURS ─────────────────────────── */
  Palette.set('regolith');
  const fills = [];
  const realRect = sctx.fillRect;
  sctx.fillRect = function () { fills.push(this.fillStyle); };
  try {
    const ev = { title: 'X', text: 'Hello.', choices: [{ label: 'OK', result: {} }] };
    EventView.reset();
    quiet(() => EventView.draw(sctx, ev, { reporter: { rec: { name: 'Sowa', race: 'phoenix', faceSeed: 42 }, name: 'Sowa', role: 'PILOT' } }));
    EventView.reset();
  } finally { sctx.fillRect = realRect; }
  const skin = CrewArt.faceOf(42, 'phoenix').skin;
  const sk = Palette.parse(skin);
  ok(fills.some(f => { const p = Palette.parse(String(f)); return p && p.r === sk.r && p.g === sk.g && p.b === sk.b; }),
     `his skin is his skin in regolith too (${skin})`);
  Palette.set('classic');

  /* ── SHELVED (update138, jj: "ta paleta regolit słabo na razie") ── */
  Save.setSetting('palette', 'regolith');
  ok(T._paletteMode() === 'classic', 'even a save that chose REGOLITH plays CLASSIC now');
  T._applyPalette();
  ok(Palette.mode() === 'classic', 'and the screen is in the colours it always had');
  Save.setSetting('palette', undefined);
  const text = captureText(ctx, () => quiet(() => T._drawOptions(ctx)));
  ok(!text.some(t => t.t === 'COLOURS' || t.t === 'REGOLITH'), 'the COLOURS switch is off the options screen');
  const back = T._optBackRect(), esc = text.find(t => t.t === 'ESC to go back');
  ok(esc && esc.y > back.y + back.h, `"ESC to go back" under the buttons (${esc && esc.y} vs ${back.y + back.h})`);
  Palette.set('classic');
  T.STATE = 'menu';
})();

// ============================================================
section('324. jj\'s list of 19.10 (138): a quiet pre-launch, their FTL clear of their panel, the hatch opens first, signs that say the name, the charge in the gun, a jump that is a jump');
// ============================================================
(function testUpdate138() {
  const sb = loadEngine();
  const { Game, Save, Base, BaseScreen, Ship, Audio, Renderer, CombatManager, UI, Input, Weapon, SectorMap } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.load();

  /* ── 1. THE PRE-LAUNCH IS QUIET ───────────────────────── */
  ok(typeof Audio.hush === 'function' && Audio.hushed() === false, 'Audio has a hush');
  ok(Audio.hush(() => Audio.hushed()) === true && Audio.hushed() === false, 'inside it the game is hushed, and after it is not');
  sb.makeStartingCrew().forEach(c => Base.addCrew(c.serialise ? c.serialise() : c));
  sb.makeStartingCrew().slice(0, 1).forEach(c => Base.addCrew(c.serialise ? c.serialise() : c));
  quiet(() => BaseScreen.open());
  BaseScreen._set({ picked: Base.crew().slice(0, 4).map(c => c.id) });
  // a PICTURE built = a new preview ship run through its settling loop
  let built = 0, heard = 0;
  const seenShips = new WeakSet();
  const realUpd = Ship.prototype.update;
  Ship.prototype.update = function () { if (this.isPreview && !seenShips.has(this)) { seenShips.add(this); built++; } return realUpd.apply(this, arguments); };
  const realCharge = Audio.sfx.weaponCharge;
  Audio.sfx.weaponCharge = function () { if (!Audio.hushed()) heard++; };
  try {
    for (const screen of [null, 'loadout', 'dest']) {
      BaseScreen._set({ screen });
      quiet(() => BaseScreen.draw(ctx));                 // warm
      built = 0; heard = 0;
      for (let i = 0; i < 20; i++) quiet(() => BaseScreen.draw(ctx));
      ok(built === 0, `${screen || 'hangar'}, four aboard: twenty frames build the picture of the ship no more times (${built})`);
      ok(heard === 0, `…and nothing of it is heard (${heard} charge chirps)`);
    }
    // back and forth between the hangar and the loadout: each keeps its picture
    built = 0;
    BaseScreen._set({ screen: null }); quiet(() => BaseScreen.draw(ctx));
    BaseScreen._set({ screen: 'loadout' }); quiet(() => BaseScreen.draw(ctx));
    BaseScreen._set({ screen: null }); quiet(() => BaseScreen.draw(ctx));
    BaseScreen._set({ screen: 'loadout' }); quiet(() => BaseScreen.draw(ctx));
    ok(built === 0, `hangar → loadout → hangar → loadout builds nothing new — one picture per place (${built})`);
    // a man posted elsewhere rebuilds the picture once — and not one sound of it is heard
    const realSfx = {};
    let anyHeard = 0;
    Object.keys(Audio.sfx).forEach(k => { realSfx[k] = Audio.sfx[k]; Audio.sfx[k] = function () { if (!Audio.hushed()) anyHeard++; }; });
    try {
      const id = BaseScreen._state().picked[0];
      BaseScreen._set({ posts: { [id]: 'oxygen' } });
      built = 0;
      quiet(() => BaseScreen.draw(ctx)); quiet(() => BaseScreen.draw(ctx));
      ok(built === 1 && anyHeard === 0, `posting a man to the O₂ bay builds it once and plays nothing (${built} built, ${anyHeard} heard)`);
      // and the hush is what keeps it quiet: the same forty seconds unhushed do make noise
      let raw = 0;
      Object.keys(Audio.sfx).forEach(k => { Audio.sfx[k] = function () { raw++; }; });
      const sh = new Ship(Base.ships()[0].key, true, 0, 0); sh._allocateDefaultPower(); sh.isPreview = true;
      sb.makeStartingCrew().forEach(c => sh.addCrew(c)); sh.assignStations?.();
      quiet(() => { for (let i = 0; i < 400; i++) sh.update(0.1); });
      ok(raw > 0, `test sanity: a ship's forty seconds unhushed are not silent (${raw} sounds)`);
    } finally { Object.keys(realSfx).forEach(k => { Audio.sfx[k] = realSfx[k]; }); }
  } finally {
    Ship.prototype.update = realUpd;
    Audio.sfx.weaponCharge = realCharge;
    BaseScreen._set({ screen: null, posts: {} });
  }

  /* ── 2. THEIR FTL UNDER THEIR PANEL ───────────────────── */
  {
    const { player, enemy } = makeCombat(sb);
    T.playerShip = player; T.enemyShip = enemy;
    CombatManager.enemyEscapeActive = true; CombatManager._enemyEscapeT = 4;
    const real = CombatManager.inProgress; CombatManager.inProgress = () => true;
    let seen;
    try { seen = captureText(ctx, () => quiet(() => T._drawCombat(ctx))); }
    finally { CombatManager.inProgress = real; CombatManager.enemyEscapeActive = false; }
    const P = Renderer.enemyPanelRect();
    const lab = seen.find(t => t.t === 'ENEMY FTL' || t.t === 'FTL ANCHORED');
    ok(P && lab, 'test setup: their panel and their FTL bar are both drawn');
    ok(lab && lab.y > P.y + P.h, `the FTL bar is under their panel, not on it (label at ${lab && lab.y}, panel ends ${P && P.y + P.h})`);
    ok(lab && lab.x >= P.x - 4 && lab.x < Renderer.getWidth(), 'and lined up with it on the right');
    CombatManager.end();
  }

  /* ── 3. THE CHARGE IS IN THE GUN ──────────────────────── */
  {
    const w = new Weapon('laser_basic'); w.charge = 0.5;
    const rects = [];
    const realFill = ctx.fillRect;
    ctx.fillRect = function (x, y, ww, hh) { rects.push({ x, y, w: ww, h: hh }); };
    try { quiet(() => w.draw(ctx, 100, 50, false, 1, { onHull: true })); } finally { ctx.fillRect = realFill; }
    const g = w._hullGauge;
    ok(g && g.x >= 100 && g.x + g.w <= 144 && g.y >= 50 && g.y + g.h <= 68, `the gauge sits inside the gun's 44 × 18 box (${g && [g.x, g.y, g.w, g.h].join(',')})`);
    ok(!rects.some(r => r.y < 50 && r.w === 5 && r.h === 5), 'none of the old 5 px boxes floats above the gun any more');
    const slow = new Weapon('cannon_basic');
    quiet(() => slow.draw(ctx, 0, 0, false, -1, { onHull: true }));
    ok(slow._hullGauge && slow._hullGauge.x + slow._hullGauge.w <= 44 && slow._hullGauge.x > 22 - 1,
       'a gun facing left carries it on its own housing, away from the muzzle');
    const { player } = makeCombat(sb);
    player.weapons = [new Weapon('laser_basic'), new Weapon('cannon_basic')];
    const m = player.weaponMounts();
    ok(m.length === 2 && m[1].x - m[0].x === 44 + 14, `the mounts are spaced by the gun, not by a strip over it (${m.length === 2 && m[1].x - m[0].x})`);
    CombatManager.end();
  }

  /* ── 4. SIGNS THAT SAY THE NAME ───────────────────────── */
  {
    const I = Renderer.STAT_ICONS;
    ok(I.corp_aquarius.length === 1 && I.corp_aquarius[0][0] === 'poly' && I.corp_aquarius[0][2] === true, 'Aquarius is a drop: one filled shape');
    ok(I.corp_terra.some(o => o[0] === 'circle') && I.corp_terra.filter(o => o[0] === 'line').length === 2, 'Terra is ⊕: the old sign for the Earth');
    ok(I.corp_phoenix[0][0] === 'poly' && I.corp_pegasus[0][0] === 'poly', 'Phoenix a flame, Pegasus a wing');
    const shapes = ['aquarius', 'pegasus', 'terra', 'phoenix'].map(k => JSON.stringify(I['corp_' + k]));
    ok(new Set(shapes).size === 4, 'four different signs');
  }

  /* ── 5. A JUMP IS A JUMP ──────────────────────────────── */
  {
    Save.startRun();
    const { player, enemy } = makeCombat(sb);
    T.sectorMap = new SectorMap(1, 7, SectorMap.MID_LANE);
    enemy.hull = 0; enemy.crew.length = 0;
    quiet(() => { for (let i = 0; i < 80; i++) T._updateCombat(0.05); });
    const real = Input.isPressed;
    Input.isPressed = (k) => k === 'Enter';
    try { quiet(() => T._updateCombat(0.05)); } finally { Input.isPressed = real; }
    ok(T.STATE === 'map' && T._mapView === 'map' && T._jumpPrompt, 'JUMP after a win opens the chart, asking where to');
    const seen = captureText(ctx, () => quiet(() => T._draw()));
    const lab = seen.find(t => /PICK YOUR DESTINATION/.test(t.t));
    const o = SectorMap.origin(Renderer.getWidth(), Renderer.getHeight());
    ok(lab && lab.y > o.y + SectorMap.GRID.h + 24, `the "where to?" sits under the chart, off its title row (${lab && lab.y})`);
    const r = T._jumpPromptRect();
    /* rewritten for update167: the bigger chart ends at 534 — the prompt sits under it, beside the ship panel, not over it */
    const hit = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
    ok(!hit(r, { x: 0, y: 540, w: 262, h: 180 }) && !hit(r, { x: 862, y: 588, w: 418, h: 132 }) && r.y + r.h < 600, 'and clear of the ship panel, the guns and the log');
    // M takes him to the ship; the prompt goes with it
    Input.isPressed = (k) => k === 'KeyM';
    try { quiet(() => T._updateMap(0.05)); } finally { Input.isPressed = real; }
    ok(T._mapView === 'ship' && !T._jumpPrompt, 'M shows the ship and puts the question away');
    void player;
  }
  {
    // THEY run: we have not jumped — the ship view, no question
    const { player, enemy } = makeCombat(sb);
    // put the chart up first, so a ship view afterwards is something the flight did
    T.STATE = 'map';
    if (T._mapView !== 'map') { const r0 = Input.isPressed; Input.isPressed = (k) => k === 'KeyM'; try { quiet(() => T._updateMap(0.05)); } finally { Input.isPressed = r0; } }
    ok(T._mapView === 'map', 'test setup: the chart is up');
    T.STATE = 'combat';
    const real = CombatManager.isEnemyFled;
    CombatManager.isEnemyFled = () => true;
    try { quiet(() => T._updateCombat(0.05)); } finally { CombatManager.isEnemyFled = real; }
    ok(T.STATE === 'map' && T._mapView === 'ship' && !T._jumpPrompt, `when THEY flee he is left looking at his ship (${T._mapView})`);
    void player; void enemy;
  }

  /* ── 6. THE HATCH OPENS FIRST ─────────────────────────── */
  /* (driven in section 279 with a real trip; here the rule itself) */
  {
    const gsrc = require('fs').readFileSync(require('path').join(__dirname, '..', 'js', 'game.js'), 'utf8');
    ok(/m\.phase = 'hatch'/.test(gsrc) && /if \(!m\.hatch\.open\)/.test(gsrc), 'a man for the crates waits in the hatch until it is open');
  }
  T.STATE = 'menu';
})();

// ============================================================
section('325. The node card (139, plan point 3: "mini animacje / obrazki w panelu info węzła"): a living picture, what the jump brings, what it costs');
// ============================================================
(function testUpdate139() {
  const sb = loadEngine();
  const { NodeView, SectorMap, Save, Renderer, Game } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.load(); Save.startRun();
  ok(typeof NodeView === 'object' && typeof NodeView.draw === 'function', 'nodeview.js is loaded');
  const gsrc = require('fs').readFileSync(require('path').join(__dirname, '..', 'js', 'game.js'), 'utf8');
  ok(/name: 'NodeView',\s*src: 'js\/nodeview\.js'/.test(gsrc), 'and a stale index.html gets it from the late loader');

  const m = new SectorMap(1, 11, SectorMap.MID_LANE);
  m.revealAll();
  const node = m.nodes.find(n => n.col === 3) || m.nodes[4];
  node.locked = false;
  const W = Renderer.getWidth(), H = Renderer.getHeight();
  const o = SectorMap.origin(W, H), G = SectorMap.GRID;
  const bounds = { x: o.x - 20, y: o.y - 40, w: G.w + 40, h: G.h + 64 };
  const card = (n, extra = {}) => {
    let res;
    const seen = captureText(ctx, () => { res = NodeView.draw(ctx, n, { sectorMap: m, at: { x: n.x + o.x, y: n.y + o.y }, bounds, t: 1.3, fuel: 4, ...extra }); });
    return { res, seen, txt: seen.map(s => s.t).join('|') };
  };

  /* ── EVERY TYPE HAS ITS OWN PICTURE AND ITS OWN WORDS ─── */
  const types = ['combat', 'store', 'event', 'nebula', 'asteroids', 'empty', 'exit', 'boss'];
  const words = new Set();
  types.forEach(ty => {
    node.type = ty;
    const { res, seen } = card(node);
    ok(res && res.kind === (ty === 'exit' && m.sector >= m.finalSector ? 'exitLast' : ty), `${ty}: its own picture (${res && res.kind})`);
    ok(res.lines.length === 2 && res.lines.every(l => l.length <= 38), `${ty}: two lines that fit the card (${res.lines.map(l => l.length)})`);
    ok(!seen.some(s => /…$/.test(s.t)), `${ty}: nothing cut short`);
    words.add(res.lines.join(' '));
    const R = res.rect;
    ok(R.x >= bounds.x && R.y >= bounds.y && R.x + R.w <= bounds.x + bounds.w && R.y + R.h <= bounds.y + bounds.h,
       `${ty}: the card stays on the chart (${R.x},${R.y})`);
  });
  ok(words.size >= types.length - 1, `the words differ from type to type (${words.size} kinds)`);
  // by the right-hand edge it opens to the left of the node, still on the chart
  {
    const edge = m.nodes.reduce((a, b) => (b.x > a.x ? b : a));
    const { res } = card(edge);
    const R = res.rect;
    ok(R.x + R.w <= bounds.x + bounds.w && R.x + R.w <= edge.x + o.x,
       `a node by the right edge opens its card to the left, on the chart (${R.x}..${R.x + R.w}, node at ${edge.x + o.x})`);
  }

  /* ── THE WORDS ARE THE GAME'S ODDS, NOT ITS SECRETS ────── */
  node.type = 'event';
  node.event = sb.EVENTS[0];
  const ev = card(node);
  ok(!ev.txt.includes(node.event.title), 'an event card never gives away which event it is');
  node.type = 'nebula';
  ok(/−2 power for BOTH/.test(card(node).txt), 'a nebula says what an ambush in it costs — the game\'s own −2');
  node.type = 'store';
  ok(/knowledge/.test(card(node).txt), 'a station says the commander rests there');

  /* ── THE MAN ON THE POSTER ─────────────────────────────── */
  node.type = 'combat';
  let list = Save.wanted();
  if (!list.length) { Save.addWanted(); list = Save.wanted(); }
  node.wantedId = list[0].id;
  const wc = card(node);
  ok(wc.res.kind === 'wanted' && wc.txt.includes(list[0].name), `a wanted node carries his name (${list[0].name})`);
  ok(wc.txt.includes(`${list[0].bounty} CC`) && wc.txt.includes(`${Math.round(list[0].bounty / 2)} dead`), 'and his price, alive and dead');
  ok(wc.seen.some(s => s.t === 'WANTED'), 'on a poster');
  node.wantedId = null;

  /* ── THE FOOT: WHAT IT COSTS, AND CAN HE ───────────────── */
  ok(/CLICK TO JUMP · 1 He2 \(4 aboard\)/.test(card(node).txt), 'a jump costs one He2, and the card says how much is aboard');
  ok(/tanks are dry/.test(card(node, { fuel: 0 }).txt), 'with the tanks dry it says so');
  m.currentId = node.id;
  ok(/YOU ARE HERE/.test(card(node).txt), 'the node he is on says so');
  m.currentId = null;

  /* ── A LIVING PICTURE: IT MOVES, AND IT IS THE SAME EVERY TIME ── */
  const paint = (ty, t) => {
    node.type = ty;
    const out = [];
    const keep = ctx.fillRect;
    ctx.fillRect = function (x, y, w, h) { out.push([Math.round(x), Math.round(y), Math.round(w), Math.round(h)].join()); };
    try { NodeView.drawPicture(ctx, node, t, { x: 0, y: 0, w: 256, h: 88 }, m); } finally { ctx.fillRect = keep; }
    return out.join('|');
  };
  ['combat', 'store', 'asteroids', 'empty'].forEach(ty => {
    ok(paint(ty, 1) !== paint(ty, 2.5), `${ty}: the picture moves`);
    ok(paint(ty, 1.7) === paint(ty, 1.7), `${ty}: and is the same picture at the same moment`);
  });

  /* ── ON THE SCREEN ─────────────────────────────────────── */
  T.sectorMap = m;
  quiet(() => Renderer.drawMapScreen(m, node.id, null));
  ok(Renderer.nodeCard() && Renderer.nodeCard().rect.w === NodeView.CARD.w, 'hovering a node on the chart draws the card');
  quiet(() => Renderer.drawMapScreen(m, null, null));
  ok(Renderer.nodeCard() === null, 'and nothing when nothing is hovered');
  const locked = m.nodes.find(n => n !== node);
  locked.locked = true;
  quiet(() => Renderer.drawMapScreen(m, locked.id, null));
  ok(Renderer.nodeCard() === null, 'nor for a node out of reach');
})();

// ============================================================
section('326. The picture of what happened (140, jj: "te img animacje nagród tam dalej brakuje, jest puste"): read off the ship before and after');
// ============================================================
(function testUpdate140() {
  const sb = loadEngine();
  const { Game, RewardView, Save, Ship, Renderer, Commander } = sb;
  const T = Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  ok(typeof RewardView === 'object' && typeof RewardView.draw === 'function', 'rewardview.js is loaded');
  const gsrc = require('fs').readFileSync(require('path').join(__dirname, '..', 'js', 'game.js'), 'utf8');
  ok(/name: 'RewardView',\s*src: 'js\/rewardview\.js'/.test(gsrc), 'and a stale index.html gets it from the late loader');

  Save.load(); Save.startRun(); Save.updateRun({ scrap: 100 });
  const ship = new Ship('frigate', true, Ship.PLAYER_STATION.x, Ship.PLAYER_STATION.y);
  ship._allocateDefaultPower();
  sb.makeStartingCrew().forEach(c => ship.addCrew(c));
  T.playerShip = ship;
  T.sectorMap = new sb.SectorMap(1, 7, sb.SectorMap.MID_LANE);
  const resolve = (result, label = 'Do it') => {
    T.STATE = 'event';
    T.event = { title: 'A test', text: '.', choices: [{ label, result }] };
    quiet(() => T._resolveEvent(0));
    return T.eventResult;
  };
  ok(T.eventResult !== undefined, 'test setup: the window can be read');

  /* ── THE PICTURE IS THE OUTCOME, NOT THE OFFER ─────────── */
  let r = resolve({ scrap: 12 });
  ok(r && r.pic.kind === 'cc' && r.pic.badge === '+12 CC', `credits in: the credits picture, +12 (${r && r.pic.kind} ${r && r.pic.badge})`);
  r = resolve({ scrap: -7 });
  ok(r.pic.kind === 'paid' && r.pic.badge === '-7 CC', `credits out: paid (${r.pic.badge})`);
  r = resolve({ crew: 1, scrap: 5 });
  ok(r.pic.kind === 'crew' && r.pic.rec && ship.crew.includes(r.pic.rec), 'a man joins: HIS face, over the credits that came with him');
  ship.crew = ship.crew.filter(c => !c.isPet);
  r = resolve({ pet: true });
  ok(r.pic.kind === 'pet' && r.pic.rec?.isPet, 'a cat comes aboard: the cat');
  r = resolve({ pet: true });
  ok(r.pic.kind !== 'pet', `a second cat is refused — and is not drawn coming aboard (${r.pic.kind})`);
  Save.updateRun({ scrap: 0 });
  ship.crew = ship.crew.filter(c => !c.isPet);
  r = resolve({ pet: true, cost: 40 });
  ok(r.pic.kind === 'nothing', `a cat he cannot pay for is not drawn either (${r.pic.kind})`);
  Save.updateRun({ scrap: 100 });
  r = resolve({ system_upgrade: 'engines' });
  ok(r.pic.kind === 'upgrade' && r.pic.sys?.type === 'engines' && /^LEVEL \d/.test(r.pic.badge), `a module upgraded: its icon, its new level (${r.pic.badge})`);
  r = resolve({ risk: 'crew_damage' });
  ok(r.pic.kind === 'hurt' && /^−\d+ HP$/.test(r.pic.badge), `somebody hurt: the hull struck (${r.pic.badge})`);
  r = resolve({ missiles: 3 });
  ok(r.pic.kind === 'missiles' && r.pic.badge === '+3 MSL', `rounds in (${r.pic.badge})`);
  r = resolve({});
  ok(r.pic.kind === 'nothing', 'nothing came of it: nothing drawn but dust');

  /* ── IT IS DRAWN, AND IT MOVES ─────────────────────────── */
  r = resolve({ scrap: 9 });
  const seen = captureText(ctx, () => quiet(() => T._drawEventResult(ctx))).map(o => o.t);
  ok(!seen.includes('— image —') && seen.filter(t => t === '+9 CC').length >= 2, 'the frame holds the picture and its badge, not "— image —"');
  const A = { x: 0, y: 0, w: 160, h: 160 };
  ['cc', 'fuel', 'missiles', 'hurt', 'karmaUp'].forEach(kind => {
    const paint = (t) => { const out = []; const keep = ctx.fillRect; ctx.fillRect = function (x, y, w, h) { out.push([x, y, w, h].map(Math.round).join()); }; try { RewardView.draw(ctx, { kind }, A, t); } finally { ctx.fillRect = keep; } return out.join('|'); };
    ok(paint(0.4) !== paint(1.3), `${kind}: the picture moves`);
    ok(paint(0.9) === paint(0.9), `${kind}: the same picture at the same moment`);
  });
  ok(Object.keys(RewardView.TINT).length >= 13, 'every kind has its colour');
  T.eventResult = null;
})();

// ============================================================
section('327. The base, first pass (141): the shop\'s rows clear of each other, whole skill names, posters with faces, what an upgrade adds, the free bunks');
// ============================================================
(function testUpdate141() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, CrewArt, SKILL_DEFS } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.load();
  Base.earn(2000);
  sb.makeStartingCrew().forEach(c => Base.addCrew(c.serialise ? c.serialise() : c));
  while (Save.wanted().length < 3 && Save.addWanted) Save.addWanted();
  quiet(() => BaseScreen.open());
  const draw = (tab) => { BaseScreen._set({ tab, screen: null }); return captureText(ctx, () => quiet(() => BaseScreen.draw(ctx))); };

  /* ── THE SHOP: ONE TILE A LINE (rewritten for update159: a tile each, its
     own container above its name, ×1 and ×5 under it) ── */
  {
    const seen = draw('SUPPLY');
    const buys = BaseScreen._zonesFor('buy'), tiles = BaseScreen.supplyRects().lines;
    const items = seen.filter(o => /^(He2|MISSILES|SURVEY PROBE|RATIONS) — \d+ CC$/.test(o.t));
    ok(items.length === 4, `four lines, whole names (${items.map(o => o.t).join(' / ')})`);
    items.forEach(o => {
      const tile = tiles.find(L => o.x >= L.x && o.x < L.x + L.w && o.y > L.y && o.y < L.y + L.h);
      const mine = buys.filter(z => tile && z.x >= tile.x && z.y >= tile.y && z.x + z.w <= tile.x + tile.w && z.y + z.h <= tile.y + tile.h);
      ok(!!tile && mine.length === 2 && mine.every(z => z.y > o.y), `"${o.t}": in its tile, its ×1 and ×5 under it (${mine.length})`);
      ok(buys.every(z => !(o.y - 9 < z.y + z.h && o.y > z.y && o.x < z.x + z.w && o.x + o.t.length * 6 > z.x)), `"${o.t}" is under no button`);
    });
  }

  /* ── THE CREW CARD: NAME, THEN RANK MARKS; WHOLE SKILL CODES ── */
  {
    const seen = draw('CREW');
    const rec = Base.crew()[0];
    const fileX = BaseScreen.barracksRects().card.x;       // update155: his file, right of the pods
    const name = seen.find(o => o.t === rec.name && o.x >= fileX);
    ok(name, 'test setup: his name is drawn');
    const cut = seen.filter(o => /^(Pilot|Repai|Shiel|Weapo|Firef|Comba|Engin|Breac)$/.test(o.t));
    ok(cut.length === 0, `no skill name cut at five letters (${cut.map(o => o.t).join(' ')})`);
    const codes = Object.keys(SKILL_DEFS).map(k => Renderer.skillShort(k));
    ok(codes.every(c => /^[A-Z]{3}$/.test(c)) && new Set(codes).size === codes.length, `three letters each, all different (${codes.join(' ')})`);
    ok(Object.values(SKILL_DEFS).every(d => seen.some(o => o.t === d.label && o.x >= fileX)), 'and his file names every skill in full (update155)');
    // the rank marks come after the name, not on it
    const marks = [];
    const keepIns = Renderer.drawRankInsignia;
    Renderer.drawRankInsignia = function (c, lvl, x, y, h) { marks.push({ x, y }); return keepIns.apply(this, arguments); };
    try { quiet(() => BaseScreen.draw(ctx)); } finally { Renderer.drawRankInsignia = keepIns; }
    const nameEnd = name.x + ctx.measureText(rec.name).width;
    const his = marks.filter(m => Math.abs(m.y - name.y) < 16 && m.x > name.x - 30 && m.x < name.x + 200);
    ok(his.length > 0 && his.every(m => m.x >= nameEnd), `the rank marks come after his name, not on it (marks at ${his.map(m => m.x)}, name ends ${nameEnd})`);
    // the free bunks
    const free = Base.barracksCap() - Base.crew().length;
    ok(free > 0 && seen.filter(o => o.t === 'free pod').length === free, `a free pod drawn for every empty one (${free})`);
  }

  /* ── WANTED: A POSTER WITH HIS FACE ───────────────────── */
  {
    /* rewritten for update160: a mugshot — his face bare (jj: "jak bardziej
       logicznie i realnie"), WANTED or HUNTED, the prices as a poster prints them */
    const faces = [];
    const keep = CrewArt.portraitCanvas;
    CrewArt.portraitCanvas = function (rec, opts) { faces.push({ name: rec?.name, bare: !!opts?.bare }); return keep.apply(this, arguments); };
    let seen;
    try { seen = draw('WANTED'); } finally { CrewArt.portraitCanvas = keep; }
    const list = Save.wanted();
    ok(list.every(w => faces.some(f => f.name === w.name && f.bare)), `a bare face on every poster (${faces.length} faces for ${list.length})`);
    ok(seen.filter(o => o.t === 'WANTED' || o.t === 'HUNTED').length >= list.length, 'each one says WANTED (or HUNTED)');
    list.forEach(w => ok(seen.some(o => o.t === `${w.bounty} CC ALIVE`) && seen.some(o => o.t === `${Math.round(w.bounty / 2)} body`), `${w.name}: both prices`));
    ok(seen.some(o => o.t === 'a name goes up after a contract') === (list.length < Save.WANTED_MAX), 'an empty peg where a poster is still to go up');
  }

  /* ── UPGRADES: OFFERED IN THE BUILDING THEY BUILD UP (update154 — the workshop's screen went) ── */
  {
    const kinds = Object.values(BaseScreen.ROOM_UPGRADES).flat().sort().join(',');
    ok(kinds === 'barracks,mess,pets,slot,warehouse', `every upgrade the workshop sold is offered in its own building (${kinds})`);
  }

  /* ── THE YARD'S WORDS OVER TWO LINES (on the card of a hull for sale, update154) ── */
  {
    const def = sb.Base.catalog().find(d => !sb.Base.get().ships.some(e => e.key === d.key));
    BaseScreen._set({ tab: 'HANGAR', screen: null, town: false });
    BaseScreen._act('yardView', def.key);
    const seen = draw('HANGAR');
    BaseScreen._act('yardView', def.key);
    const firstLine = seen.find(o => o.t && def.blurb.startsWith(o.t) && o.t.length > 6 && o.t !== def.blurb);
    ok(!def.blurb || firstLine, `a hull's blurb starts on one line and carries on to the next (${firstLine && firstLine.t})`);
  }
})();

// ============================================================
section('328. The bubble follows the hull (142, jj: "osłona teraz jest jajowata… da się zrobić, aby obejmowała bryłę statku", "1 warstwa to 1 lev, aby nie była za gruba", "weź pod uwagę broń na górze, aby osłona nie zasłaniała broni")');
// ============================================================
(function testUpdate142() {
  const sb = loadEngine();
  const { Ship } = sb;
  const ctx = initRenderer(sb);
  const HS = Ship.SHIELD_HEX;
  const HULL_GRID_MARGIN = (sb.HULL_GRID && sb.HULL_GRID.MARGIN) ?? 8;
  const distRect = (x, y, r) => Math.hypot(Math.max(r.x - x, 0, x - r.x - r.w), Math.max(r.y - y, 0, y - r.y - r.h));

  /* ── 1. AN L-SHAPED HULL GETS AN L, NOT AN EGG ───────────────── */
  {
    const sh = new Ship('scout', true, 120, 160);
    const b = sh.roomBounds();
    // the bend of the L: inside the room box, outside a one-layer bubble, yet inside the old egg
    Object.defineProperty(sh, 'shieldBars', { get: () => 1, configurable: true });
    const e = sh.shieldEllipse();
    let hole = null;
    for (let y = b.y + 2; y < b.y + b.h && !hole; y += 3)
      for (let x = b.x + 2; x < b.x + b.w && !hole; x += 3)
        if (sh.shieldDist(x, y) > Ship.shieldRadius(0) + HS && ((x - e.cx) / e.rx) ** 2 + ((y - e.cy) / e.ry) ** 2 <= 1) hole = { x, y };
    ok(!!hole, `a point in the bend of the L that the egg covered is outside the bubble now (${hole && hole.x},${hole && hole.y})`);
    ok(!hole || !sh.insideShield(hole.x, hole.y), 'and a shot there is not stopped by it');
    // the shape is the whole hull: the plate's rim, the nacelles and the bow
    {
      const g = sh.hullArtGeometry();
      const parts = [...g.engines, ...g.prows];
      ok(parts.length >= 3 && parts.every(r => sh.shieldDist(r.x + r.w / 2, r.y + r.h / 2) === 0),
         `the nacelles and the bow are inside the shape (${parts.length} parts)`);
      ok(sh.shieldDist(b.x - HULL_GRID_MARGIN + 1, b.y + 2) === 0, 'and so is the rim of the plate round the rooms');
    }
    // every cell of every layer sits at its layer's distance from the hull
    for (let k = 0; k < 3; k++) {
      const s = sh.shieldShape(), cells = sh.shieldCells(k, s), R = Ship.shieldRadius(k);
      const bad = cells.filter(c => { const d = sh.shieldDist(c.x + s.o.x, c.y + s.o.y, s); return d < R - HS * 0.76 || d >= R + HS * 0.76; });
      ok(cells.length > 60 && bad.length === 0, `layer ${k + 1}: ${cells.length} cells, all ${R} px off the hull (${bad.length} astray)`);
    }
  }

  /* ── 2. ONE ROW A LAYER, AND THE LAYERS APART ───────────────── */
  {
    const sh = new Ship('frigate', true, 170, 180);
    const s = sh.shieldShape();
    // a flat stretch of roof: the same top edge for a long way either side (no gun, no nacelle)
    const topAt = x => Math.min(...s.rects.filter(r => r.x <= x && x <= r.x + r.w).map(r => r.y));
    const reach = Ship.shieldRadius(2) + 24;
    let flat = null;
    for (let x = s.box.x + reach; x < s.box.x + s.box.w - reach && flat === null; x += 4) {
      const y0 = topAt(x);
      let same = true;
      for (let q = x - reach; q <= x + reach && same; q += 2) same = topAt(q) === y0;
      if (same) flat = x;
    }
    ok(flat !== null, `test setup: a flat stretch of roof at x ${flat}`);
    for (let k = 0; k < 3; k++) {
      const top = sh.shieldCells(k, s).filter(c => Math.abs(c.x - flat) < 12 && c.y < topAt(flat));
      const rows = new Set(top.map(c => c.y)).size;
      ok(top.length > 0 && rows === 1, `layer ${k + 1} is one row of cells along the top (${rows} rows)`);
    }
    const keyOf = c => c.x.toFixed(1) + ',' + c.y.toFixed(1);
    const l0 = new Set(sh.shieldCells(0, s).map(keyOf));
    ok(!sh.shieldCells(1, s).some(c => l0.has(keyOf(c))), 'and no cell belongs to two layers');
    ok(Ship.SHIELD_STEP > HS * 1.5, `the layers have a gap between them (${Ship.SHIELD_STEP} > ${HS * 1.5})`);
  }

  /* ── 3. OVER THE GUNS, NEVER THROUGH THEM ───────────────────── */
  {
    const sh = new Ship('frigate', true, 170, 180);
    if (!sh.weapons.filter(Boolean).length) sh.installWeapon('laser_basic', 0);
    const mounts = sh.weaponMounts();
    ok(mounts.length > 0, `test setup: guns on the roof (${mounts.length})`);
    const s = sh.shieldShape();
    let closest = Infinity;
    for (let k = 0; k < 3; k++) sh.shieldCells(k, s).forEach(c => mounts.forEach(m => {
      closest = Math.min(closest, distRect(c.x + s.o.x, c.y + s.o.y, m));
    }));
    ok(closest > HS + 2, `no hexagon lies on a gun — the nearest cell centre is ${closest.toFixed(1)} px off one`);
    ok(mounts.every(m => sh.shieldDist(m.x + m.w / 2, m.y) === 0), 'the guns are part of the shape the bubble keeps its distance from');
    // the top of the bubble above a gun is higher than above bare plate
    const m = mounts[0];
    const above = (x) => Math.min(...sh.shieldCells(0, s).filter(c => Math.abs(c.x + s.o.x - x) < HS).map(c => c.y + s.o.y));
    const bare = sh.rooms.reduce((a, r) => a + r.x, 0) / sh.rooms.length;
    ok(above(m.x + m.w / 2) < m.y, `over a gun the first layer rises above its top (${above(m.x + m.w / 2).toFixed(0)} < ${m.y})`);
    void bare;
  }

  /* ── 4. A SHOT IS STOPPED ON THE OUTERMOST STANDING LAYER ───── */
  {
    const sh = new Ship('frigate', true, 170, 180);
    const b = sh.roomBounds();
    const x = b.x + b.w / 2;
    const at = (bars, d) => {
      Object.defineProperty(sh, 'shieldBars', { get: () => bars, configurable: true });
      // straight up from the middle of the top: find the y at distance d
      let y = b.y; while (sh.shieldDist(x, y) < d) y -= 0.25;
      return sh.insideShield(x, y);
    };
    ok(at(2, Ship.shieldRadius(1)), 'two layers up: a shot on the second layer is stopped there');
    ok(!at(2, Ship.shieldRadius(1) + HS), 'and one a cell further out is not yet');
    ok(!at(1, Ship.shieldRadius(1)), 'with one layer left, the same point is outside the bubble');
  }

  /* ── 5. A HULL THAT MOVES KEEPS ITS CELLS ───────────────────── */
  {
    const sh = new Ship('hauler', true, 100, 100);
    const a = sh.shieldCells(0);
    sh.rooms.forEach(r => { r.x += 40; r.y += 12; });
    (sh.elevators?.shafts ?? []).forEach(q => { q.x += 40; });
    ok(sh.shieldCells(0) === a, 'moved 40 px across, the same cells — nothing recomputed');
    const s = sh.shieldShape();
    ok(s.o.x === sh.roomBounds().x, 'and they are drawn from the new corner');
  }

  /* ── 6. STRUCK: A WAVE OVER ITS OWN CELLS, ON THE FIGHT'S CLOCK ── */
  {
    const sh = new Ship('frigate', true, 170, 180);
    sh._allocateDefaultPower();
    const ss = sh.getSystem('shields'); ss._shieldMax = 2; ss._shieldBars = 2;
    const b = sh.roomBounds();
    sh.shieldStruck(b.x + b.w / 2, b.y - Ship.shieldRadius(1));
    ok(sh._shieldWaves.length === 1 && sh._shieldAlpha === 1, 'a hit starts one wave and lights the bubble');
    let fills = 0;
    const real = ctx.fill;
    ctx.fill = function () { fills++; return real && real.apply(this, arguments); };
    try { sh._drawShield(ctx); } finally { ctx.fill = real; }
    ok(fills >= 2 * 2 + 1, `drawn: haze and twinkle for each layer, and the wave where it struck (${fills} fills)`);
    sh._ageShieldWaves(Ship.SHIELD_WAVE_T + 0.01);
    ok(sh._shieldWaves.length === 0, 'and it is gone once its time is up');
    sh.shieldStruck(b.x + b.w / 2, b.y - Ship.shieldRadius(1));
    try { for (let i = 0; i < 20; i++) sh.update(0.05); } catch (e) { /* a ship alone may complain; the waves are what is asked */ }
    ok(sh._shieldWaves.length === 0, 'the ship\'s own update ages them out');
    // no ellipse anywhere in the drawing
    let ell = 0;
    const realE = ctx.ellipse;
    ctx.ellipse = function () { ell++; return realE && realE.apply(this, arguments); };
    try { sh._drawShield(ctx); } finally { ctx.ellipse = realE; }
    ok(ell === 0, 'not one ellipse in the bubble');
  }

  /* ── 7. THE BOSS STATION AND A HULL WITHOUT GUNS STILL GET ONE ── */
  {
    ['boss_station', 'enemy_raider'].forEach(key => {
      const sh = new Ship(key, false, 700, 160);
      const cells = sh.shieldCells(0);
      ok(cells.length > 40, `${key}: a bubble of ${cells.length} cells round it`);
    });
  }
})();

// ============================================================
section('329. The port is a promenade (143, jj: "zajmijmy się stacją … teraz jest słabo", "fajne może coś na wzór jak jest w Arc Raiders menu sklep i stragany typu bar"): six stalls, a face behind each counter, crates dragged off the quartermaster\'s counter, DEPART the only way out');
// ============================================================
(function testUpdate143() {
  const sb = loadEngine();
  const { Save, Ship, Station, PortView, LootScreen, CargoGrid, CargoItem, Renderer } = sb;
  const T = sb.Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const M = sb.Input.mouse;
  const click = (x, y, step) => { M.x = x; M.y = y; M.leftPressed = true; try { return step(); } finally { M.leftPressed = false; } };

  const fresh = (scrap = 400, seed = 777) => {
    Save.load(); Save.startRun(); Save.updateRun({ scrap });
    const ship = new Ship('scout', true, 80, 120);
    ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const st = new Station(2, seed);
    st.type = 'general';
    T.playerShip = ship; T.station = st;
    return { ship, st };
  };

  /* ── 1. ARRIVING: THE PROMENADE, NOT THE PANEL ─────────────── */
  {
    const { st } = fresh();
    const opened = [];
    const realOpen = sb.UI.openStation;
    sb.UI.openStation = function (...a) { opened.push(a[2] ?? null); };
    try {
      quiet(() => T._openPort());
      T.STATE = 'station';
      ok(T.portMode && PortView.isOpen() && opened.length === 0, 'a port opens on the promenade — the old panel is not put up');
      quiet(() => PortView.draw(ctx));
      const stalls = PortView._zonesFor('stall').map(z => z.arg);
      ok(stalls.join() === 'drydock,guns,qm,bar,clinic,broker', `six stalls to walk up to (${stalls.join()})`);
      ok(PortView._zonesFor('depart').length === 1, 'and DEPART');
      // every stall has a keeper, the same face every visit
      const a = PortView.vendor(2), b = PortView.vendor(2), c = PortView.vendor(3);
      ok(a.faceSeed === b.faceSeed && a.faceSeed !== c.faceSeed, 'a face behind each counter — the same one every time, a different one at the next stall');
      // the line under the pointer says what is in stock today, with today's price
      ok(PortView.stallLine('qm').includes(`He2 ${st.fuelCost()} CC`) || st.stock.fuel <= 0, `the quartermaster's line quotes He2 (${PortView.stallLine('qm')})`);
      ok(/hull \d+ CC a point/.test(PortView.stallLine('drydock')), `the drydock's line quotes plating (${PortView.stallLine('drydock')})`);
      ok(PortView.rumour().length > 10, 'somebody at the bar is talking');

      /* ── 2. A STALL'S PANEL IS CUT DOWN TO ITS TRADE ─────────── */
      const r = PortView.stallRect(4);       // CLINIC (the gunsmith is a counter since update145)
      M.x = r.x + r.w / 2; M.y = r.y + 60;
      quiet(() => T._step(0.016));          // the pointer is over it
      click(r.x + r.w / 2, r.y + 60, () => quiet(() => T._step(0.016)));
      /* update147: the clinic is its own room now, like the bar */
      ok(opened.length === 0 && PortView.view() === 'clinic',
         `the clinic opens its own room, not the panel (${PortView.view()}, panel ×${opened.length})`);
      PortView.closeBar();
      ok(T.STATE === 'station' && T.portMode, 'still in port');
    } finally { sb.UI.openStation = realOpen; }
    // the real panel, in stall mode: its tabs and its button
    sb.UI.openStation(st, T.playerShip, { tabs: ['repair', 'modules'], section: 'drydock', title: 'DRYDOCK', back: true });
    const el = sb.document.getElementById('station-screen');
    const html = String(el?.innerHTML ?? '');
    ok(/BACK TO THE PROMENADE/.test(html) && !/>DEPART</.test(html), 'opened from a stall the button goes back to the promenade');
    ok(/data-tab="modules"/.test(html) && !/data-tab="weapons"/.test(html) && !/data-tab="cargo"/.test(html), 'and only that stall\'s tabs are there');
    sb.UI.setStationTab?.('repair');
    const find = (e, re, out = []) => { if (!e) return out; if (e.textContent && re.test(e.textContent)) out.push(e); (e.children || []).forEach(k => find(k, re, out)); return out; };
    const root = sb.document.getElementById('station-content');
    ok(find(root, /^HULL REPAIR$/).length === 1, 'the drydock\'s repair tab has the plating');
    ok(find(root, /^He2 FUEL$/).length === 0 && find(root, /MEDICAL CLINIC/).length === 0,
       'and nothing of the quartermaster\'s or the clinic\'s');
    sb.UI.openStation(st, T.playerShip, { tabs: ['repair'], section: 'clinic', title: 'CLINIC', back: true });
    sb.UI.setStationTab?.('repair');
    const root2 = sb.document.getElementById('station-content');
    ok(find(root2, /MEDICAL CLINIC/).length === 1 && find(root2, /^HULL REPAIR$/).length === 0, 'the clinic: the clinic, not the plating');
    sb.UI.openStation(st, T.playerShip);
    sb.UI.setStationTab?.('repair');
    const root3 = sb.document.getElementById('station-content');
    ok(find(root3, /^He2 FUEL$/).length === 1 && find(root3, /^HULL REPAIR$/).length === 1, 'opened whole (a pirate\'s hold) it is the old panel, all of it');
    sb.UI.closeStation?.();
  }

  /* ── 3. THE COUNTER IS THE STOCK ─────────────────────────────── */
  {
    const { st } = fresh();
    st.stock.fuel = 20; st.stock.missiles = 7; st.stock.torpedoes = 2; st.stock.medkits = 3;
    st.stock.rations = { ration_pack: 6 }; st.stock.he3 = 2;
    const g = st.counterGrid();
    ok(g.countOf('fuel') === 20 && g.countOf('missiles') === 7 && g.countOf('torpedoes') === 2,
       'his counter carries exactly the He2, missiles and torpedoes in stock');
    ok(g.items.filter(i => i.defKey === 'medkit').length === 3 && g.countOf('food') === 6 && g.countOfTag('he3') === 2,
       'and the kits, the rations and the ore');
    st.stock.fuel = 400;
    const big = st.counterGrid();
    ok(big.countOf('fuel') === 400 && big.rows > 6, `a long counter grows rows rather than losing stock (${big.rows} rows)`);
    // prices are the buy buttons' prices — karma and all
    const tank = new CargoItem('he2_med'); tank.qty = 15;
    ok(st.counterPrice(tank) === st.fuelCost(15), 'a tank costs what fifteen He2 cost at the pump');
    const serum = new CargoItem('antiviral_serum');
    ok(st.counterPrice(serum) === null && st.counterSellPrice(serum) === null, 'a serum is not his trade');
    ok(st.counterSellPrice(tank) === Math.floor(st.fuelCost(15) / st._priceFactor() * 0.5), 'and he buys back at half');
  }

  /* ── 4. BUYING: A CRATE OFF HIS COUNTER INTO THE HOLD ─────────── */
  const openCounter = () => {
    quiet(() => T._openPort());
    T.STATE = 'station';
    quiet(() => T._openCounter());
    Renderer.init(sb.document.getElementById('game-canvas'));
    quiet(() => LootScreen.draw(Renderer.getCtx()));
    return LootScreen._grids();
  };
  const PITCH = LootScreen.CELL + LootScreen.GAP;
  const at = (which, it) => { const r = LootScreen._gridRect(which); return [r.x + (it.x - r.sx) * PITCH + 8, r.y + (it.y - r.sy) * PITCH + 8]; };
  const freeCell = (g, it) => { for (let y = 0; y < g.rows; y++) for (let x = 0; x < g.cols; x++) if (g.fits(it, x, y)) return { x, y }; return null; };
  const step = () => quiet(() => LootScreen.update(0.016));
  {
    const { ship, st } = fresh(400);
    st.stock.missiles = 8; st.stock.rations = { ration_pack: 5 };
    const grids = openCounter();
    ok(T.STATE === 'loot' && grids.wreck && grids.hold === ship.cargo, 'the quartermaster: his counter on the left, your own hold on the right');
    const rack = grids.wreck.items.find(i => i.def.kind === 'missiles');
    const price = st.counterPrice(rack), before = Save.getRun().scrap, held = ship.cargo.countOf('missiles');
    click(...at('wreck', rack), step);
    const dest = freeCell(ship.cargo, rack);
    const hr = LootScreen._gridRect('hold');
    click(hr.x + (dest.x - hr.sx) * PITCH + 8, hr.y + (dest.y - hr.sy) * PITCH + 8, step);
    ok(ship.cargo.items.includes(rack), 'the rack is in the hold');
    ok(Save.getRun().scrap === before - price, `and paid for: ${price} CC (${before} → ${Save.getRun().scrap})`);
    ok(st.stock.missiles === 8 - rack.qty && ship.cargo.countOf('missiles') === held + rack.qty, `his stock went down by what you carried off (${st.stock.missiles} left)`);

    // a double click on his counter sends it across — and that is a sale too
    const rack2 = grids.wreck.items.find(i => i.def.kind === 'missiles' && i !== rack) || grids.wreck.items.find(i => i.def.kind === 'food');
    if (rack2) {
      const p2 = st.counterPrice(rack2), b2 = Save.getRun().scrap;
      quiet(() => LootScreen.update(0.5));
      click(...at('wreck', rack2), step);
      click(...at('wreck', rack2), step);
      ok(ship.cargo.items.includes(rack2) && Save.getRun().scrap === b2 - p2, `double-clicked across: in the hold and paid for (${p2} CC)`);
    } else ok(true, '(nothing else on the counter to double-click)');

    /* ── 5. A PURSE TOO LIGHT: IT STAYS IN THE HAND ──────────────── */
    Save.updateRun({ scrap: 1 });
    const tank = grids.wreck.items.find(i => i.def.kind === 'fuel');
    const fuelBefore = st.stock.fuel, holdFuel = ship.cargo.countOf('fuel');
    click(...at('wreck', tank), step);
    const d2 = freeCell(ship.cargo, tank);
    click(hr.x + (d2.x - hr.sx) * PITCH + 8, hr.y + (d2.y - hr.sy) * PITCH + 8, step);
    ok(!ship.cargo.items.includes(tank) && Save.getRun().scrap === 1 && st.stock.fuel === fuelBefore && ship.cargo.countOf('fuel') === holdFuel,
       'one CC: the tank will not go in, nothing is charged, nothing leaves his stock');
    // double-click across is the same sale, refused the same way
    const rightClick = () => { M.rightDown = true; step(); M.rightDown = false; step(); };
    rightClick();
    ok(grids.wreck.items.includes(tank), 'put back on his counter');

    /* ── 6. SELLING: ONE OF YOURS ON HIS COUNTER ─────────────────── */
    Save.updateRun({ scrap: 100 });
    const kit = ship.cargo.add('medkit');
    const pay = st.counterSellPrice(kit), kits = st.stock.medkits;
    click(...at('hold', kit), step);
    const d3 = freeCell(grids.wreck, kit);
    const wr = LootScreen._gridRect('wreck');
    click(wr.x + (d3.x - wr.sx) * PITCH + 8, wr.y + (d3.y - wr.sy) * PITCH + 8, step);
    ok(grids.wreck.items.includes(kit) && Save.getRun().scrap === 100 + pay && st.stock.medkits === kits + 1,
       `a sealed kit sold across the counter: +${pay} CC, one more kit on his books`);
    // half a kit is not a kit
    const half = ship.cargo.add('medkit', null, 2);
    const r6 = st.transferAtCounter(half, 2, 'sell');
    ok(!r6.ok && /sealed/.test(r6.message), 'two doses of a kit: he will not take them');
    // and what is not his trade does not go on his counter at all
    const serum = ship.cargo.add('antiviral_serum');
    const sBefore = Save.getRun().scrap;
    click(...at('hold', serum), step);
    const d4 = freeCell(grids.wreck, serum);
    click(wr.x + (d4.x - wr.sx) * PITCH + 8, wr.y + (d4.y - wr.sy) * PITCH + 8, step);
    ok(!grids.wreck.items.includes(serum) && Save.getRun().scrap === sBefore, 'a serum: refused at the counter, no money moves');
    rightClick();
    ok(ship.cargo.items.includes(serum), 'and it is back in your hold');

    /* ── 7. HIS GOODS ARE NOT YOURS TO DUMP ─────────────────────── */
    const onCounter = grids.wreck.items[0];
    const n = grids.wreck.items.length;
    click(...at('wreck', onCounter), step);                     // pick it up …
    quiet(() => LootScreen.update(0.5));                        // (not a double click — that would be a sale)
    click(...at('wreck', onCounter), step);                     // … and put it back down
    quiet(() => LootScreen.draw(Renderer.getCtx()));
    const dump = LootScreen._zoneFor('dump');
    ok(!dump, 'THROW OVERBOARD is not offered for a crate on his counter');
    ok(grids.wreck.items.length === n, 'it is still there');
    ok(!LootScreen._zoneFor('takeAll'), 'and there is no TAKE ALL at a shop');

    /* ── 8. BACK: TO THE PROMENADE, AND THE SHIP SAVED ───────────── */
    const done = LootScreen._zoneFor('done');
    click(done.x + done.w / 2, done.y + done.h / 2, step);
    ok(T.STATE === 'station' && T.portMode && PortView.isOpen(), 'BACK returns to the promenade');
    const saved = sb.CargoGrid.deserialise(Save.getRun().ship.cargo);
    ok(saved.countOf('missiles') === ship.cargo.countOf('missiles'), 'what was bought is in the save');
  }

  /* ── 8b. A JUMP TO A PORT WITH THE FILMS OFF: THE PROMENADE TOO ── */
  {
    const { ship } = fresh();
    const keepFilms = sb.JumpScene?.enabled;
    if (sb.JumpScene) sb.JumpScene.enabled = false;
    const realOpen = sb.UI.openStation;
    const old = [];
    sb.UI.openStation = function () { old.push(1); };
    try {
      const map = new sb.SectorMap(1, 7, 1, 3, true);
      const start = map.startNodes[0];
      const node = map.getNode(start.next[0]);
      node.type = 'store';
      map.currentId = start.id; map.unlockNext();
      T.sectorMap = map; T.STATE = 'map'; T.enemyShip = null; T.playerShip = ship;
      ship.crew.filter(c => c.isPlayer).forEach(c => { c.roomId = ship.rooms.find(r => r.type === 'piloting')?.id ?? c.roomId; });
      quiet(() => T._addFuel(3));
      quiet(() => T._travelTo(node.id));
      ok(T.STATE === 'station' && T.portMode && PortView.isOpen() && old.length === 0,
         `no film: the jump lands on the promenade straight away (${T.STATE}, ${T.portMode}, old panel ×${old.length})`);
    } finally {
      sb.UI.openStation = realOpen;
      if (sb.JumpScene) sb.JumpScene.enabled = keepFilms;
      quiet(() => T._leavePort?.());
    }
  }

  /* ── 9. DEPART IS THE ONLY WAY OUT ──────────────────────────── */
  {
    fresh();
    quiet(() => T._openPort());
    T.STATE = 'station';
    quiet(() => T._step(0.016));
    ok(T.STATE === 'station', 'standing on the promenade does not leave port');
    quiet(() => PortView.draw(ctx));
    const d = PortView._zonesFor('depart')[0];
    click(d.x + 5, d.y + 5, () => quiet(() => T._step(0.016)));
    ok(T.STATE === 'map' && !T.portMode && !PortView.isOpen(), 'DEPART: out to the map');
  }

  /* ── 10. A PORT THAT WILL NOT DEAL WITH HIM ─────────────────── */
  {
    const { st } = fresh();
    st.refusal = () => 'They know your name here.';
    quiet(() => T._openPort());
    T.STATE = 'station';
    quiet(() => PortView.draw(ctx));
    ok(PortView.openStalls().length === 0 && PortView._zonesFor('stall').length === 0, 'every shutter down — nothing to click but DEPART');
    const seen = captureText(ctx, () => quiet(() => PortView.draw(ctx))).map(o => o.t);
    ok(seen.includes('DOCK CLOSED') && seen.includes('They know your name here.'), 'and it says why');
    quiet(() => T._openStall('qm'));
    ok(T.STATE === 'station', 'his counter will not open behind the shutter either');
    quiet(() => T._leavePort());
  }

  /* ── 11. A PIRATE'S HOLD IS NOT A PORT ───────────────────────── */
  {
    fresh();
    const got = [];
    const realOpen = sb.UI.openStation;
    sb.UI.openStation = function (...a) { got.push(a.length); };
    try {
      quiet(() => T._openPort());
      quiet(() => T._openBlackMarket(null));
      ok(!T.portMode && got.length === 1, 'the black market opens his hold in the old panel, no promenade');
    } finally { sb.UI.openStation = realOpen; }
    T.STATE = 'map';
  }
})();

// ============================================================
section('330. Beside the counter (144, the mock-up jj accepted: "reszta chyba ok"): the man behind it and the receipt; the BROKER is a counter too — put it down, it is sold, at one price with the old panel');
// ============================================================
(function testUpdate144() {
  const sb = loadEngine();
  const { Save, Ship, Station, PortView, LootScreen, CargoItem, Renderer } = sb;
  const T = sb.Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const M = sb.Input.mouse;
  const click = (x, y) => { M.x = x; M.y = y; M.leftPressed = true; try { quiet(() => LootScreen.update(0.016)); } finally { M.leftPressed = false; } quiet(() => LootScreen.update(0.5)); };
  const PITCH = LootScreen.CELL + LootScreen.GAP;
  const at = (which, it) => { const r = LootScreen._gridRect(which); return [r.x + (it.x - r.sx) * PITCH + 8, r.y + (it.y - r.sy) * PITCH + 8]; };
  const free = (which, g, it) => { const r = LootScreen._gridRect(which);
    for (let y = 0; y < g.rows; y++) for (let x = 0; x < g.cols; x++) if (g.fits(it, x, y)) return [r.x + (x - r.sx) * PITCH + 8, r.y + (y - r.sy) * PITCH + 8];
    return null; };
  const fresh = (type = 'general', scrap = 300) => {
    Save.load(); Save.startRun(); Save.updateRun({ scrap });
    const ship = new Ship('scout', true, 80, 120);
    ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const st = new Station(2, 4321); st.type = type;
    T.playerShip = ship; T.station = st;
    quiet(() => T._openPort()); T.STATE = 'station';
    return { ship, st };
  };
  const draw = () => { Renderer.init(sb.document.getElementById('game-canvas')); quiet(() => LootScreen.draw(Renderer.getCtx())); };

  /* ── 1. THE MAN BEHIND THE COUNTER, AND THE RECEIPT ─────────── */
  {
    const { ship, st } = fresh();
    const seen = [];
    const realK = PortView.drawKeeper, realL = PortView.drawLedger;
    PortView.drawKeeper = function (c, key, R) { seen.push(['keeper', key, R]); return realK.apply(this, arguments); };
    PortView.drawLedger = function (c, R) { seen.push(['ledger', R]); return realL.apply(this, arguments); };
    try { quiet(() => T._openCounter()); draw(); }
    finally { PortView.drawKeeper = realK; PortView.drawLedger = realL; }
    const k = seen.find(s => s[0] === 'keeper'), l = seen.find(s => s[0] === 'ledger');
    const cr = LootScreen._gridRect('wreck'), hr = LootScreen._gridRect('hold');
    ok(k && k[1] === 'qm' && k[2].x + k[2].w <= cr.x - 20, `the quartermaster himself, left of his counter (${k && k[2].x}..${k && k[2].x + k[2].w}, counter at ${cr.x})`);
    ok(l && l[1].x >= hr.x + hr.w + 20 && l[1].x + l[1].w <= 1270, 'the receipt, right of your hold, on the screen');
    // his name is a name, and his prices are the counter's
    const v = PortView.vendor(2);
    ok(sb.CREW_NAMES.includes(v.name), `he has a name off the crew list (${v.name})`);
    const rows = PortView.todayPrices('qm');
    if (st.stock.fuel > 0) ok(rows.some(r => r[0].startsWith('He2') && r[1] === `${st.fuelCost(1)} CC`), 'TODAY quotes He2 at the pump price');
    ok(rows.length > 0, `TODAY has rows (${rows.length})`);
    // the receipt: every crate across a counter, one line
    const tank = new CargoItem('he2_med'); tank.qty = 15;
    st.stock.fuel = Math.max(st.stock.fuel, 15);
    const before = st.ledger.length;
    const r = st.transferAtCounter(tank, 15, 'buy');
    ok(r.ok && st.ledger.length === before + 1 && st.ledger.at(-1).cc === -r.cost, `a purchase is a line on the receipt (${JSON.stringify(st.ledger.at(-1))})`);
    const r2 = st.transferAtCounter(tank, 15, 'sell');
    ok(r2.ok && st.ledger.at(-1).cc === r2.paid, 'and a sale is another, in the black');
    const text = captureText(ctx, () => PortView.drawLedger(ctx, { x: 980, y: 104, w: 280, h: 348 })).map(o => o.t);
    ok(text.includes('THIS VISIT') && text.includes(`-${r.cost} CC`) && text.includes(`+${r2.paid} CC`), 'the receipt shows both, with the amounts');
    ok(text.includes(`${Save.getRun().scrap} CC`), 'and the purse as it stands');
    // nothing to put beside a hold too wide for the room
    const big = new sb.CargoGrid(13, 4);
    LootScreen.openLoot(st.counterGrid(), big, { leftPanel: () => {}, rightPanel: () => {} });
    const sides = LootScreen.sidePanels();
    ok(!sides.right, 'a hold as wide as the screen leaves no room for the receipt — and none is drawn');
    quiet(() => LootScreen.forceClose());
    T.STATE = 'station';
    void ship;
  }

  /* ── 2. A KEEPER'S WORDS STAY IN HIS PANEL ───────────────────── */
  {
    fresh('science');
    const R = { x: 16, y: 104, w: 200, h: 348 };
    const t = captureText(ctx, () => PortView.drawKeeper(ctx, 'broker', R));
    const wide = t.filter(o => o.t.length * 6 > R.w - 8);
    ok(t.length > 5 && wide.length === 0, `every line of his fits a narrow panel (${wide.map(o => o.t).join(' | ')})`);
  }

  /* ── 3. THE BROKER: PUT IT DOWN, IT IS SOLD ─────────────────── */
  {
    const { ship, st } = fresh('general', 100);
    const ore = ship.cargo.add('he3_ore', null, 4);
    // through the promenade, like a player
    quiet(() => PortView.draw(ctx));
    const z = PortView._zonesFor('stall').find(q => q.arg === 'broker');
    M.x = z.x + 10; M.y = z.y + 60; M.leftPressed = true;
    try { quiet(() => T._step(0.016)); } finally { M.leftPressed = false; }
    const g = LootScreen._grids();
    ok(T.STATE === 'loot' && g.hold === ship.cargo && g.wreck.items.length === 0, 'the broker: an empty counter beside your hold');
    draw();
    const pay = st.brokerPrice(ore);
    ok(pay === ore.value('general'), `he pays what a trade hub pays for it (${pay} CC)`);
    click(...at('hold', ore));
    click(...free('wreck', g.wreck, ore));
    ok(g.wreck.items.includes(ore) && !ship.cargo.items.includes(ore) && Save.getRun().scrap === 100 + pay,
       `put on his counter: sold, +${pay} CC (${Save.getRun().scrap})`);
    ok(st.ledger.at(-1)?.cc === pay, 'and on the receipt');
    // sold is sold
    click(...at('wreck', ore));
    click(...free('hold', ship.cargo, ore));
    ok(!ship.cargo.items.includes(ore), 'he will not hand it back');
    ok(Save.getRun().scrap === 100 + pay, 'and no money goes back either');
    M.rightDown = true; quiet(() => LootScreen.update(0.016)); M.rightDown = false; quiet(() => LootScreen.update(0.016));
    // one of your own is not for sale
    const bag = ship.cargo.add('body_bag', { crewBody: true, name: 'Jett' });
    const cc = Save.getRun().scrap;
    click(...at('hold', bag));
    click(...free('wreck', g.wreck, bag));
    ok(!g.wreck.items.includes(bag), 'your own dead: not on his counter');
    ok(Save.getRun().scrap === cc, 'and no money');
    M.rightDown = true; quiet(() => LootScreen.update(0.016)); M.rightDown = false; quiet(() => LootScreen.update(0.016));
    ok(ship.cargo.items.includes(bag), 'he is back in your hold');
    // the panel under it says why
    click(...at('hold', bag));
    const why = captureText(ctx, () => quiet(() => LootScreen.draw(ctx))).map(o => o.t).join(' | ');
    ok(/not for sale — one of your own/.test(why), 'and the panel under it says why');
    M.rightDown = true; quiet(() => LootScreen.update(0.016)); M.rightDown = false; quiet(() => LootScreen.update(0.016));
    draw();
    const done = LootScreen._zoneFor('done');
    click(done.x + 5, done.y + 5);
    ok(T.STATE === 'station' && PortView.isOpen(), 'BACK to the promenade');
  }

  /* ── 4. A FLEET YARD SEIZES CONTRABAND ─────────────────────── */
  {
    const { ship, st } = fresh('military', 10);
    const ctb = ship.cargo.add('contraband');
    ok(st.brokerPrice(ctb) === 0 && st.brokerSeizes(ctb), 'at a fleet yard contraband is worth nothing to him — it is seized');
    const r = st.sellToBroker(ctb);
    ok(r.ok && r.seized && Save.getRun().scrap === 0, `customs take it and fine you — never below zero (${Save.getRun().scrap})`);
    const st2 = new Station(2, 99); st2.type = 'outpost';
    ok(st2.brokerPrice(ctb) === ctb.value('outpost') && !st2.brokerSeizes(ctb), 'a frontier outpost simply buys it');
  }

  /* ── 5. ONE PRICE: HIS COUNTER AND THE OLD PANEL ────────────── */
  {
    const { ship, st } = fresh('science', 50);
    const ore = ship.cargo.add('he3_ore', null, 3);
    sb.UI.openStation(st, ship, { tabs: ['cargo'] });
    sb.UI.setStationTab?.('cargo');
    const find = (e, re, out = []) => { if (!e) return out; if (e.textContent && re.test(e.textContent)) out.push(e); (e.children || []).forEach(k => find(k, re, out)); return out; };
    const root = sb.document.getElementById('station-content');
    const b = find(root, /^SELL\s+\d+ CC$/).find(x => true);
    const want = st.brokerPrice(ore);
    ok(b && b.textContent.includes(`${want} CC`), `the old CARGO list quotes the broker's own price (${b && b.textContent} vs ${want})`);
    if (b) (b._listeners.click ?? []).forEach(f => quiet(() => f({})));
    ok(!ship.cargo.items.includes(ore) && Save.getRun().scrap === 50 + want && st.ledger.at(-1)?.cc === want,
       'and selling there is the same sale: the money, the receipt');
    sb.UI.closeStation?.();
    ship.cargo.add('he3_ore', null, 2); ship.cargo.add('contraband');
    const sum = ship.cargo.items.reduce((n, it) => n + (st.brokerPrice(it) ?? 0), 0);
    ok(PortView.stallLine('broker') === `your hold is worth ~${sum} CC here`, `the promenade quotes his price too (${PortView.stallLine('broker')})`);
    // there is no broker panel left: the stall opens his counter
    const opened = [];
    const realOpen = sb.UI.openStation;
    sb.UI.openStation = function () { opened.push(1); };
    try { quiet(() => T._openStall('broker')); } finally { sb.UI.openStation = realOpen; }
    ok(opened.length === 0 && T.STATE === 'loot', 'the BROKER stall opens his counter, not the old list');
    quiet(() => LootScreen.forceClose()); T.STATE = 'station';
    quiet(() => T._leavePort());
  }
})();

// ============================================================
section('331. The gunsmith\'s rack (145): his guns in their crates, take one and it is in your hold, UNBOX & FIT bolts it on; yours sold at half go back on his rack; MOUNTS for what comes off a bay');
// ============================================================
(function testUpdate145() {
  const sb = loadEngine();
  const { Save, Ship, Station, PortView, LootScreen, CargoItem, Renderer, WEAPON_DEFS } = sb;
  const T = sb.Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const M = sb.Input.mouse;
  const click = (x, y) => { M.x = x; M.y = y; M.leftPressed = true; try { quiet(() => LootScreen.update(0.016)); } finally { M.leftPressed = false; } quiet(() => LootScreen.update(0.5)); };
  const PITCH = LootScreen.CELL + LootScreen.GAP;
  const at = (which, it) => { const r = LootScreen._gridRect(which); return [r.x + (it.x - r.sx) * PITCH + 8, r.y + (it.y - r.sy) * PITCH + 8]; };
  const free = (which, g, it) => { const r = LootScreen._gridRect(which);
    for (let y = 0; y < g.rows; y++) for (let x = 0; x < g.cols; x++) if (g.fits(it, x, y)) return [r.x + (x - r.sx) * PITCH + 8, r.y + (y - r.sy) * PITCH + 8];
    return null; };
  const draw = () => { Renderer.init(sb.document.getElementById('game-canvas')); quiet(() => LootScreen.draw(Renderer.getCtx())); };
  const keys = Object.keys(WEAPON_DEFS).filter(k => WEAPON_DEFS[k].cost > 0).slice(0, 3);
  const fresh = (scrap = 400) => {
    Save.load(); Save.startRun(); Save.updateRun({ scrap });
    const ship = new Ship('frigate', true, 80, 120);
    ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    // an empty bay to fit into
    for (let i = 0; i < ship.weaponRooms.length; i++) if (ship.weapons[i]) ship.weapons[i] = null;
    const st = new Station(2, 5150); st.type = 'general';
    st.stock.weapons = keys.map(k => ({ key: k, def: WEAPON_DEFS[k], sold: false }));
    T.playerShip = ship; T.station = st;
    quiet(() => T._openPort()); T.STATE = 'station';
    return { ship, st };
  };

  /* ── 1. HIS RACK IS HIS STOCK ───────────────────────────────── */
  {
    const { st } = fresh();
    st.stock.weapons[1].sold = true;
    const g = st.gunsmithGrid();
    ok(g.items.length === 2 && g.items.every(it => it.def.kind === 'weapon'), `a crate for every gun still on his rack (${g.items.length})`);
    ok(g.items.every(it => it.defKey === sb.cargoCrateForWeapon(it.meta)), 'each in the crate a yard boxes that gun in');
    ok(g.items.every(it => st.gunPrice(it) === st.weaponCost(st.stock.weapons[it._stock])), 'priced at the rack\'s own price, karma and all');
    ok(!g.items.some(it => it.meta === keys[1]), 'the one already sold is not on it');
    const rows = PortView.todayPrices('guns');
    ok(rows.length === 2 && rows.every(([, p]) => /\d+ CC/.test(p)), `ON THE RACK lists them (${rows.map(r => r.join(' ')).join(' / ')})`);
  }

  /* ── 2. BUYING ONE, AND BOLTING IT ON ───────────────────────── */
  {
    const { ship, st } = fresh(400);
    quiet(() => T._openStall('guns'));
    const g = LootScreen._grids();
    ok(T.STATE === 'loot' && g.hold === ship.cargo && g.wreck.items.length === 3, 'the gunsmith: his rack beside your hold');
    draw();
    const crate = g.wreck.items[0], price = st.gunPrice(crate), key = crate.meta, before = Save.getRun().scrap;
    click(...at('wreck', crate));
    click(...free('hold', ship.cargo, crate));
    ok(ship.cargo.items.includes(crate) && Save.getRun().scrap === before - price, `taken off his rack: in your hold, ${price} CC paid`);
    ok(st.stock.weapons.find(w => w.key === key).sold && st.ledger.at(-1)?.cc === -price, 'his stock marks it sold, the receipt has the line');
    ok(!st.gunsmithGrid().items.some(it => it.meta === key), 'and it is not on his rack next time');
    // the panel under it: the price first, before the gun's card cuts the line
    const t = captureText(ctx, () => { click(...at('wreck', g.wreck.items[0])); quiet(() => LootScreen.draw(ctx)); }).map(o => o.t);
    ok(t.some(x => /^PRICE \d+ CC — put it in your hold to buy/.test(x)), 'the price leads the line under a gun on his rack');
    M.rightDown = true; quiet(() => LootScreen.update(0.016)); M.rightDown = false; quiet(() => LootScreen.update(0.016));
    // UNBOX & FIT
    const empty = ship.weapons.findIndex((w, i) => i < ship.weaponRooms.length && !w);
    click(...at('hold', crate));
    M.rightDown = true; quiet(() => LootScreen.update(0.016)); M.rightDown = false; quiet(() => LootScreen.update(0.016));
    draw();
    const use = LootScreen._zoneFor('unpack');
    if (use) click(use.x + 5, use.y + 5);
    ok(empty >= 0 && ship.weapons[empty]?.defKey === key, `UNBOX & FIT: the ${key} is on bay ${empty + 1}`);
    ok(!ship.cargo.items.includes(crate), 'and the crate is gone from the hold');
  }

  /* ── 3. A PURSE TOO LIGHT; NOT HIS TRADE ───────────────────── */
  {
    const { ship, st } = fresh(1);
    const g = st.gunsmithGrid();
    const r = st.transferAtGunsmith(g.items[0], 'buy');
    ok(!r.ok && Save.getRun().scrap === 1 && !st.stock.weapons[0].sold, 'one CC: no gun, no change to his books');
    const rat = ship.cargo.add('ration_pack');
    ok(!st.transferAtGunsmith(rat, 'sell').ok, 'rations are not his trade');
    ok(st.gunSellPrice(rat) === null, 'and he quotes nothing for them');
  }

  /* ── 4. SELLING ONE OF YOURS: HALF, AND IT GOES ON HIS RACK ── */
  {
    const { ship, st } = fresh(10);
    const mine = ship.boxWeapon(keys[0]);
    const half = Math.floor(WEAPON_DEFS[keys[0]].cost * 0.5);
    ok(st.gunSellPrice(mine) === half, `he pays half its list price (${half} CC)`);
    quiet(() => T._openGunsmith());
    const g = LootScreen._grids();
    draw();
    click(...at('hold', mine));
    click(...free('wreck', g.wreck, mine));
    ok(g.wreck.items.includes(mine) && Save.getRun().scrap === 10 + half, `put on his rack: sold, +${half} CC`);
    const back = st.stock.weapons.at(-1);
    ok(back.key === keys[0] && !back.sold && st.gunPrice(mine) === st.weaponCost(back), 'it is his now — on his rack at his own price');
    // the same half the old CARGO panel's SELL pays
    const mine2 = ship.boxWeapon(keys[0]);
    const r = st.sellCargoWeapon(ship, Save.getRun(), mine2);
    ok(r.ok && r.message.includes(`${half} CC`), 'one price for a boxed gun: his rack and the old panel');
  }

  /* ── 5. MOUNTS: WHAT IS BOLTED ON, AND THE WAY TO UNBOLT IT ─── */
  {
    const { ship } = fresh();
    const rows = PortView.mountRows();
    ok(rows.length === ship.weaponRooms.length && rows[0][1] === (ship.weapons[0]?.def?.label ?? 'empty'), `YOUR MOUNTS: every bay and what is in it (${rows.map(r => r.join(' ')).join(' / ')})`);
    const seen = captureText(ctx, () => PortView.drawKeeper(ctx, 'guns', { x: 16, y: 104, w: 290, h: 348 })).map(o => o.t);
    ok(seen.includes('YOUR MOUNTS') && seen.includes('ON THE RACK'), 'his panel shows his rack and your bays');
    quiet(() => T._openGunsmith());
    draw();
    const z = LootScreen._zoneFor('extra');
    ok(!!z, 'MOUNTS ▶ beside BACK');
    const opened = [];
    const realOpen = sb.UI.openStation;
    sb.UI.openStation = function (...a) { opened.push(a[2]); };
    try { click(z.x + 5, z.y + 5); } finally { sb.UI.openStation = realOpen; }
    ok(!LootScreen.isOpen() && T.STATE === 'station', 'it closes his rack');
    ok(opened.length === 1 && opened[0]?.tabs?.join() === 'weapons' && opened[0].back, 'and opens the bays panel, with the way back to the promenade');
    quiet(() => T._leavePort());
  }
})();

// ============================================================
section('332. The Crater (146): hands looking for a berth sit in the booths — his card, his corporation, his fee, SIGN ON; the barkeep has what people say; one rule for a free bunk');
// ============================================================
(function testUpdate146() {
  const sb = loadEngine();
  const { Save, Ship, Station, PortView, CrewMember } = sb;
  const T = sb.Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const M = sb.Input.mouse;
  const tap = (x, y) => { M.x = x; M.y = y; M.leftPressed = true; try { quiet(() => T._step(0.016)); } finally { M.leftPressed = false; } };
  const hand = (name, race) => ({ name, skill: 'weapons', sold: false, member: new CrewMember({ name, race, skills: { weapons: { level: 1, xp: 0 } } }) });
  const fresh = (scrap = 300) => {
    Save.load(); Save.startRun(); Save.updateRun({ scrap });
    const ship = new Ship('scout', true, 80, 120);
    ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const st = new Station(2, 8080); st.type = 'general';
    st.stock.crew = [hand('Kessel', 'terra'), hand('Mara', 'phoenix')];
    T.playerShip = ship; T.station = st;
    quiet(() => T._openPort()); T.STATE = 'station';
    return { ship, st };
  };

  /* ── 1. THE STALL OPENS THE BAR, NOT THE PANEL ───────────────── */
  {
    fresh();
    const opened = [];
    const realOpen = sb.UI.openStation;
    sb.UI.openStation = function () { opened.push(1); };
    try { quiet(() => T._openStall('bar')); } finally { sb.UI.openStation = realOpen; }
    ok(PortView.view() === 'bar' && opened.length === 0 && T.STATE === 'station', 'THE CRATER opens the bar — its own room, not the old list');
    const seen = captureText(ctx, () => quiet(() => PortView.draw(ctx))).map(o => o.t);
    ok(seen.includes('Kessel') && seen.includes('Mara'), 'a booth for each hand, his name on his card');
    ok(seen.some(t => t.includes(sb.CORP_PERK_TEXT.terra.slice(0, 20))), 'what his corporation does for you, in words');
    ok(seen.includes(`${T.station.crewCost()} CC`), 'his signing fee');
    ok(seen.includes('WHAT PEOPLE SAY') && seen.includes('THIS VISIT') && seen.includes('ABOARD'), 'the barkeep, the receipt and the bunks');
    ok(PortView._zonesFor('hire').length === 2, 'SIGN ON for both');
    const r3 = PortView.rumours(3);
    ok(r3.length === 3 && new Set(r3).size === 3 && r3[0] === PortView.rumour(), 'three different things heard, the promenade\'s line first');
  }

  /* ── 2. SIGN ON ─────────────────────────────────────────────── */
  {
    const { ship, st } = fresh(300);
    quiet(() => T._openStall('bar'));
    quiet(() => PortView.draw(ctx));
    const before = ship.crew.filter(c => !c.dead).length, fee = st.crewCost();
    const z = PortView._zonesFor('hire').find(q => q.arg === 1);
    tap(z.x + 5, z.y + 5);
    ok(ship.crew.some(c => c.name === 'Mara') && ship.crew.filter(c => !c.dead).length === before + 1, 'SIGN ON: Mara is aboard');
    ok(Save.getRun().scrap === 300 - fee && st.stock.crew[1].sold, `the fee is paid (${fee} CC) and she is off the market`);
    ok(st.ledger.at(-1)?.cc === -fee && /Mara/.test(st.ledger.at(-1).label), 'and it is on the receipt');
    ok((Save.getRun().crew ?? []).some(c => c.name === 'Mara'), 'the save has her at once');
    quiet(() => PortView.draw(ctx));
    ok(!PortView._zonesFor('hire').some(q => q.arg === 1) && PortView.hireBlock(1) === 'HIRED', 'her booth says HIRED and cannot be pressed again');
  }

  /* ── 3. WHY NOT: THE PURSE, THE BUNKS ───────────────────────── */
  {
    const { ship, st } = fresh(10);
    quiet(() => T._openStall('bar'));
    ok(PortView.hireBlock(0) === `NEED ${st.crewCost() - 10} MORE CC`, `a light purse: it says how much more (${PortView.hireBlock(0)})`);
    quiet(() => PortView.draw(ctx));
    ok(PortView._zonesFor('hire').length === 0, 'and SIGN ON cannot be pressed');
    Save.updateRun({ scrap: 999 });
    while (ship.crew.filter(c => !c.dead).length < Station.CREW_ROOM) ship.addCrew(new CrewMember({ name: 'Filler' + ship.crew.length }));
    ok(st.crewRoomLeft(ship) === 0 && PortView.hireBlock(0) === 'NO BUNK FREE', 'eight aboard: NO BUNK FREE');
    ok(!st.buyCrew(0, ship, Save.getRun()).ok, 'and the station agrees');
    // a dead man does not take a bunk — one rule, the living count
    ship.crew.find(c => c.name.startsWith('Filler')).dead = true;
    ok(st.crewRoomLeft(ship) === 1 && PortView.hireBlock(0) === null, 'one of them dead: a bunk is free again');
    ok(st.buyCrew(0, ship, Save.getRun()).ok, 'and he can sign on');
  }

  /* ── 4. BACK, AND ESCAPE ────────────────────────────────────── */
  {
    fresh();
    quiet(() => T._openStall('bar'));
    quiet(() => PortView.draw(ctx));
    const b = PortView._zonesFor('back')[0];
    tap(b.x + 5, b.y + 5);
    ok(PortView.view() === 'port' && T.STATE === 'station', 'BACK: out on the promenade again');
    quiet(() => T._openStall('bar'));
    const realP = sb.Input.isPressed;
    sb.Input.isPressed = (k) => k === 'Escape';
    try { quiet(() => T._step(0.016)); } finally { sb.Input.isPressed = realP; }
    ok(PortView.view() === 'port', 'ESCAPE does the same');
    quiet(() => T._leavePort());
  }

  /* ── 5. AN EMPTY BAR ────────────────────────────────────────── */
  {
    const { st } = fresh();
    st.stock.crew = [];
    quiet(() => T._openStall('bar'));
    const seen = captureText(ctx, () => quiet(() => PortView.draw(ctx))).map(o => o.t);
    ok(seen.includes('Nobody is looking for a berth at this port.') && PortView._zonesFor('hire').length === 0, 'nobody at the tables: it says so');
    quiet(() => T._leavePort());
  }

  /* ── 6. ONE COPY OF WHAT A CORPORATION DOES ─────────────────── */
  {
    const { ship, st } = fresh();
    sb.UI.openStation(st, ship, { tabs: ['crew'] });
    sb.UI.setStationTab?.('crew');
    const find = (e, re, out = []) => { if (!e) return out; if (e.textContent && re.test(e.textContent)) out.push(e); (e.children || []).forEach(k => find(k, re, out)); return out; };
    const root = sb.document.getElementById('station-content');
    ok(find(root, new RegExp(sb.CORP_PERK_TEXT.phoenix.slice(0, 18))).length >= 1, 'the old hiring list reads the same words');
    sb.UI.closeStation?.();
    quiet(() => T._leavePort());
  }
})();

// ============================================================
section('333. The clinic and the drydock (147): the last two stalls are rooms — the ward with every hand and what is wrong with him, the services with their price or why not; the hull in its cradle, welded by the point; MODULES for the plans');
// ============================================================
(function testUpdate147() {
  const sb = loadEngine();
  const { Save, Ship, Station, PortView } = sb;
  const T = sb.Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const M = sb.Input.mouse;
  const tap = (z) => { quiet(() => PortView.draw(ctx)); M.x = z.x + 5; M.y = z.y + 5; M.leftPressed = true; try { quiet(() => T._step(0.016)); } finally { M.leftPressed = false; } };
  const fresh = (type = 'general', scrap = 300) => {
    Save.load(); Save.startRun(); Save.updateRun({ scrap });
    const ship = new Ship('scout', true, 80, 120);
    ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const st = new Station(2, 6060); st.type = type;
    T.playerShip = ship; T.station = st;
    quiet(() => T._openPort()); T.STATE = 'station';
    return { ship, st };
  };
  const people = (ship) => ship.crew.filter(c => c.isPlayer && !c.dead && !c.isPet);

  /* ── 1. THE CLINIC IS A ROOM ─────────────────────────────────── */
  {
    const { ship, st } = fresh('general');
    const [a, b] = people(ship);
    a.hp = Math.round(a.maxHp / 2); b.state = 'injured';
    const opened = [];
    const realOpen = sb.UI.openStation;
    sb.UI.openStation = function () { opened.push(1); };
    try { quiet(() => T._openStall('clinic')); } finally { sb.UI.openStation = realOpen; }
    ok(PortView.view() === 'clinic' && opened.length === 0, 'CLINIC opens its own room');
    const rows = PortView.patientRows();
    ok(rows.find(r => r.c === a)?.tag === 'HURT' && rows.find(r => r.c === b)?.tag === 'DOWN', `every hand on the ward, with what is wrong (${rows.map(r => r.c.name + ':' + r.tag).join(' ')})`);
    const seen = captureText(ctx, () => quiet(() => PortView.draw(ctx))).map(o => o.t);
    ok(seen.includes('ON THE WARD') && seen.includes('HURT') && seen.includes('DOWN'), 'and it is drawn');
    const sv = PortView.clinicServices();
    const treat = sv.find(v => v.key === 'treat');
    ok(treat.cost === st.clinicCost(ship) && treat.cost === 2 * Station.CLINIC_EACH && !treat.block, `TREAT ALL: two patients, ${treat.cost} CC — one price list`);
    ok(sv.find(v => v.key === 'quarantine').block === 'NOBODY CARRIES IT' && sv.find(v => v.key === 'fumigate').block === 'DUCTS CLEAN',
       'nothing for the ward or the ducts to do: it says so');
    // treat them, through the button
    const z = PortView._zonesFor('svc').find(q => q.arg.key === 'treat');
    tap(z);
    ok(a.hp === a.maxHp && b.state === 'ok' && Save.getRun().scrap === 300 - treat.cost, `treated: both on their feet, ${treat.cost} CC paid`);
    ok(st.ledger.at(-1)?.cc === -treat.cost && /treated/.test(st.ledger.at(-1).label), 'on the receipt');
    ok(PortView.clinicServices().find(v => v.key === 'treat').block === 'NOBODY TO TREAT', 'and now there is nobody to treat');
  }

  /* ── 2. THE WARD AND THE DUCTS: WHERE, AND FOR HOW MUCH ─────── */
  {
    const { ship, st } = fresh('military', 300);
    const c = people(ship)[0];
    c.virus = { t: 30 };
    quiet(() => T._openStall('clinic'));
    ok(PortView.patientRows().find(r => r.c === c).tag === 'VIRUS', 'a carrier is marked VIRUS');
    ok(PortView.clinicServices().find(v => v.key === 'quarantine').block === 'RESEARCH POSTS ONLY', 'a fleet yard has no ward');
    st.type = 'science';
    const q = PortView.clinicServices().find(v => v.key === 'quarantine');
    ok(!q.block && q.cost === st.quarantineCost(ship), `a research post does — ${q.cost} CC`);
    Save.updateRun({ scrap: 10 });
    ok(PortView.clinicServices().find(v => v.key === 'quarantine').block === `NEED ${q.cost - 10} MORE CC`, 'with the money short it says how much');
    Save.updateRun({ scrap: 300 });
    quiet(() => T._portService('quarantine'));
    ok(!c.virus && Save.getRun().scrap === 300 - q.cost, 'treated in the ward: the virus is out of him');
    // the ducts
    if (ship.pests) {
      ship.pests.push(...[0, 1].map(() => ({ alive: true, isRat: true })));
      st.type = 'military';
      ok(PortView.clinicServices().find(v => v.key === 'fumigate').block === 'NOT DONE HERE', 'a fleet yard will not go into your ducts');
      st.type = 'general';
      const f = PortView.clinicServices().find(v => v.key === 'fumigate');
      ok(!f.block && f.cost === Station.FUMIGATE_BASE + 2 * Station.FUMIGATE_EACH, `a trade hub will — ${f.cost} CC`);
      ship.pests.length = 0;          // stand-ins, not real vermin: they do not go into a save
    }
    quiet(() => T._leavePort());
  }

  /* ── 3. THE OLD PANEL READS THE SAME PRICE ──────────────────── */
  {
    const { ship, st } = fresh('general');
    people(ship)[0].hp = 10;
    sb.UI.openStation(st, ship);
    sb.UI.setStationTab?.('repair');
    const find = (e, re, out = []) => { if (!e) return out; if (e.textContent && re.test(e.textContent)) out.push(e); (e.children || []).forEach(k => find(k, re, out)); return out; };
    const root = sb.document.getElementById('station-content');
    const html = (e, out = []) => { if (!e) return out; if (e.innerHTML) out.push(String(e.innerHTML)); (e.children || []).forEach(k => html(k, out)); return out; };
    ok(html(root).some(h => h.includes(`${Station.CLINIC_EACH} CC each — ${st.clinicCost(ship)} CC total`)), 'the old clinic card quotes the same price');
    sb.UI.closeStation?.();
    quiet(() => T._leavePort());
  }

  /* ── 4. THE DRYDOCK: THE HULL IN ITS CRADLE, WELDED BY THE POINT ─ */
  {
    const { ship, st } = fresh('general', 300);
    ship.hull = ship.hullMax - 9; st.stock.hullRepair = 12;
    quiet(() => T._openStall('drydock'));
    ok(PortView.view() === 'drydock', 'DRYDOCK opens its own room');
    const seen = captureText(ctx, () => quiet(() => PortView.draw(ctx))).map(o => o.t);
    ok(seen.includes('IN THE CRADLE') && seen.includes(`${ship.hull} / ${ship.hullMax}`), 'the hull in the cradle, and what it is at');
    const w = PortView.weldOptions();
    ok(w.map(o => o.n).join() === '1,5,9' && w[2].label === 'ALL 9 HP' && w.every(o => o.cost === st.hullRepairCost(o.n)), `+1, +5, all 9 — at the yard's price (${w.map(o => o.label).join(' / ')})`);
    st.stock.hullRepair = 3;
    ok(PortView.weldOptions().map(o => o.n).join() === '1,3', 'only what the yard has plate for');
    st.stock.hullRepair = 12; Save.updateRun({ scrap: st.hullRepairCost(2) });
    ok(PortView.weldOptions().map(o => o.n).join() === '1,2', 'only what the purse can pay for');
    Save.updateRun({ scrap: 300 });
    quiet(() => PortView.draw(ctx));
    const z = PortView._zonesFor('svc').find(q => q.arg.key === 'weld' && q.arg.n === 5);
    const hp = ship.hull, cost = st.hullRepairCost(5);
    tap(z);
    ok(ship.hull === hp + 5 && Save.getRun().scrap === 300 - cost && st.stock.hullRepair === 7, `+5 HP welded, ${cost} CC, the yard has 7 left`);
    ok(st.ledger.at(-1)?.label === 'hull welded +5 HP' && st.ledger.at(-1).cc === -cost, 'on the receipt');
    ok(Save.getRun().ship?.hull === ship.hull, `and in the save at once (${Save.getRun().ship?.hull})`);
    ship.hull = ship.hullMax;
    ok(PortView.weldOptions().length === 0, 'a sound hull: nothing to weld');

    /* ── 5. MODULES, AND BACK ──────────────────────────────────── */
    const opened = [];
    const realOpen = sb.UI.openStation;
    sb.UI.openStation = function (...a) { opened.push(a[2]); };
    quiet(() => PortView.draw(ctx));
    const mz = PortView._zonesFor('modules')[0];
    try { tap(mz); }
    finally { sb.UI.openStation = realOpen; }
    /* update151: the plans are a room of the yard now, not the old panel */
    ok(opened.length === 0 && PortView.view() === 'plans', 'MODULES opens the plans — a room of the yard, not the old panel');
    quiet(() => PortView.draw(ctx));
    tap(PortView._zonesFor('back')[0]);
    ok(PortView.view() === 'drydock' && T.portMode, 'and BACK from them comes back to the yard, not the promenade');
    quiet(() => PortView.draw(ctx));
    tap(PortView._zonesFor('back')[0]);
    ok(PortView.view() === 'port', 'BACK: the promenade');
    quiet(() => T._openStall('drydock'));
    const realP = sb.Input.isPressed;
    sb.Input.isPressed = (k) => k === 'Escape';
    try { quiet(() => T._step(0.016)); } finally { sb.Input.isPressed = realP; }
    ok(PortView.view() === 'port', 'ESCAPE too');
    quiet(() => T._leavePort());
  }
})();

// ============================================================
section('334. Moored at home (148, jj: "menu SHIP i LOADOUT miało grafikę w tle tak, jakby statek był zadokowany do stacji na księżycu"): the bay on the moon behind her, the cradle, the gantry and the tube worked out from her own hull');
// ============================================================
(function testUpdate148() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, DockArt, Ship, SHIP_CATALOG } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  ok(typeof DockArt === 'object' && typeof DockArt.draw === 'function', 'dockart.js is loaded');

  /* ── 1. THE MOORINGS FIT EVERY HULL ─────────────────────────── */
  Object.keys(SHIP_CATALOG).forEach(key => {
    const sh = new Ship(key, true, 300, 300);
    if (!sh.weapons.filter(Boolean).length && sh.weaponRooms.length) sh.installWeapon('laser_basic', 0);
    const M = DockArt.moorings(sh);
    const g = sh.hullArtGeometry();
    const right = Math.max(...[...g.plate, ...g.engines, ...g.prows].map(r => r.x + r.w));
    const keel = (x) => Math.max(...g.plate.filter(r => r.x <= x && x <= r.x + r.w).map(r => r.y + r.h));
    const guns = sh.weaponMounts().map(m => [m.x - 10, m.x + m.w + 10]);
    ok(M && M.arms.length === 2 && M.arms.every(a => a.y === keel(a.x)), `${key}: both cradle arms meet her keel right under them`);
    ok(M.plugs.length >= 1 && M.plugs.every(p => !guns.some(([a, b]) => p.x >= a && p.x <= b)), `${key}: the umbilicals plug in clear of her guns (${M.plugs.length})`);
    /* update153: the tube is a jet bridge now and goes to her DOOR — an airlock on her bow
       side (section 339 says which); it still never meets her stern */
    const locks = sh.doors.filter(d => d.isAirlock);
    ok(M.tube.x > (g.bounds.x + g.bounds.w / 2) && M.tube.x <= right && locks.some(d => d.y === M.tube.y), `${key}: the jet bridge meets her on the bow side, level with one of her airlocks`);
  });

  /* ── 1b. A GUN WHERE A CABLE WOULD GO: THE CABLE MOVES ──────── */
  {
    const sh = new Ship('scout', true, 300, 300);
    const first = DockArt.moorings(sh).plugs[0];
    sh.weaponMounts = () => [{ x: first.x - 22, y: first.y - 20, w: 44, h: 18 }];
    const M = DockArt.moorings(sh);
    ok(M.plugs.length >= 1 && M.plugs.every(p => Math.abs(p.x - first.x) > 22 + 10 - 1), `a gun bolted where the first cable went: the cables plug in elsewhere (${M.plugs.map(p => Math.round(p.x)).join(',')} vs ${Math.round(first.x)})`);
  }

  /* ── 2. THE BAY IS PAINTED ONCE PER SIZE ────────────────────── */
  {
    const a = DockArt.bay(496, 330), b = DockArt.bay(496, 330), c = DockArt.bay(500, 330);
    ok(a && a === b && c !== a, 'the bay is painted once for a size and kept');
    ok(a.width === 248 && a.height === 165, 'at half the size, to be doubled crisp');
  }

  /* ── 3. IT STAYS INSIDE ITS RECTANGLE ───────────────────────── */
  {
    const sh = new Ship('scout', true, 600, 300);
    const R = { x: 392, y: 134, w: 496, h: 330 };
    const clips = [];
    const realRect = ctx.rect, realClip = ctx.clip;
    let last = null;
    ctx.rect = function (x, y, w, h) { last = [x, y, w, h]; return realRect?.apply(this, arguments); };
    ctx.clip = function () { clips.push(last); return realClip?.apply(this, arguments); };
    try { DockArt.draw(ctx, R, sh); } finally { ctx.rect = realRect; ctx.clip = realClip; }
    ok(clips.length >= 1 && clips[0].join() === [R.x, R.y, R.w, R.h].join(), 'clipped to the stage it is given');
  }

  /* ── 4. THE HANGAR AND THE LOADOUT DRAW HER IN THE BAY ──────── */
  {
    Save.load();
    quiet(() => BaseScreen.open());
    const seen = [];
    const realDraw = DockArt.draw;
    DockArt.draw = function (c, R, sh) { seen.push({ R, sh, order: seen.length }); return realDraw.apply(this, arguments); };
    const realShipDraw = Ship.prototype.draw;
    let shipAt = -1;
    Ship.prototype.draw = function () { if (shipAt < 0) shipAt = seen.length; return realShipDraw.apply(this, arguments); };
    try {
      BaseScreen._set({ tab: 'HANGAR', screen: null });
      quiet(() => BaseScreen.draw(ctx));
      ok(seen.length === 1 && seen[0].sh && seen[0].R.w > 200, `the hangar: the selected hull, moored (${seen.length})`);
      ok(shipAt === 1, 'and the bay is under her, not over her');
      seen.length = 0; shipAt = -1;
      quiet(() => BaseScreen._act('loadout'));
      ok(BaseScreen._state().loadout, 'test setup: the loadout is open');
      quiet(() => BaseScreen.draw(ctx));
      const R = BaseScreen.loadoutRects();
      ok(seen.length === 1 && seen[0].R.x === R.stage.x + 2 && seen[0].R.w === R.stage.w - 4, 'the loadout: moored in the middle panel');
      ok(shipAt === 1, 'under her there too');
      quiet(() => BaseScreen._act('loClose'));
    } finally { DockArt.draw = realDraw; Ship.prototype.draw = realShipDraw; }
  }
})();

// ============================================================
section('335. The base is a town (149, jj: "Base powinno wyglądać coś na wzór zamku w Heroes", "małe animacje jak najedziemy na budynek", "na cmentarzu stary system nagrobków plus latarnia"): nine doors, numbers on them, ESC back out, THE HILL on the cliff');
// ============================================================
(function testUpdate149() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, TownView, Input } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  ok(typeof TownView === 'object' && typeof TownView.draw === 'function', 'townview.js is loaded');
  Save.reset(); Save.load();
  Base.earn(500); Base.hireRecruit();

  const M = Input.mouse;
  const frame = () => quiet(() => BaseScreen.draw(ctx));
  const click = (x, y) => { M.x = x; M.y = y; M.leftPressed = true; const r = quiet(() => BaseScreen.update(0.05)); M.leftPressed = false; frame(); return r; };
  const key = (code) => { const real = Input.isPressed; Input.isPressed = (c) => c === code;
    try { return quiet(() => BaseScreen.update(0.05)); } finally { Input.isPressed = real; frame(); } };
  const away = () => { M.x = -100; M.y = -100; };
  const st = () => BaseScreen._state();

  /* ── 1. NINE PLACES, EVERY SCREEN BEHIND EXACTLY ONE DOOR ── */
  const B = TownView.BUILDINGS;
  const tabs = BaseScreen.TAB_GROUPS.flatMap(g => g.tabs.map(t => t[0]));
  ok(B.length === 9 && B.map(b => b.n).join() === '1,2,3,4,5,6,7,8,9', 'nine places, numbered 1 to 9');
  /* update154: the WORKSHOP stands closed — painted, but no screen and no door */
  const open = B.filter(b => !b.closed);
  ok(!B.some(b => b.closed) && B.find(b => b.key === 'works').tab === 'DISPATCH', 'no place is closed: the old workshop is DISPATCH (rewritten for update161)');
  ok(tabs.every(t => open.filter(b => b.tab === t).length === 1) && open.every(b => tabs.includes(b.tab)) && !tabs.includes('UPGRADES'),
     `every base screen has exactly one door (${open.map(b => b.tab).join(',')})`);

  /* ── 2. THE BASE OPENS ON THE TOWN ── */
  quiet(() => BaseScreen.open());
  away();
  const text = captureText(ctx, () => frame()).map(o => o.t);
  ok(st().town === true, 'the base opens on the town');
  ok(BaseScreen._zonesFor('tabGroup').length === 0 && BaseScreen._zonesFor('tab').length === 0, 'with no tab bar over it');
  const doors = BaseScreen._zonesFor('building');
  ok(tabs.every(t => doors.some(z => z.arg === t)), 'every door has a click zone');
  ok(doors.every(z => z.x >= 0 && z.y >= 52 && z.x + z.w <= 1280 && z.y + z.h <= 720), 'all of them on screen, under the title');
  ok(B.every(b => text.includes(b.name)) && open.every(b => text.includes(String(b.n))), 'every place is labelled, the open ones with their number');
  ok(!doors.some(z => z.arg === 'UPGRADES'), 'and the closed workshop has no click zone');
  ok(BaseScreen._zonesFor('loadout').length === 1 && text.includes('NEXT CONTRACT') && text.some(t => /Courier Run/.test(t)),
     'the next contract and LOADOUT are under the town');
  // the labels do not sit on one another
  {
    const L = B.map(b => TownView.labelRect(ctx, b.key));
    const clash = [];
    L.forEach((a, i) => L.forEach((c, j) => { if (j > i && a.x < c.x + c.w && c.x < a.x + a.w && a.y < c.y + c.h && c.y < a.y + a.h) clash.push(`${B[i].key}×${B[j].key}`); }));
    ok(!clash.length, `no two labels overlap (${clash.join(' ')})`);
  }

  /* ── 3. EVERY DOOR, CLICKED, OPENS ITS SCREEN; ESC AND ◀ TOWN WALK BACK ── */
  const opened = [];
  open.forEach((b, i) => {
    quiet(() => BaseScreen.open()); away(); frame();
    // half by the label, half by the building itself
    const z = i % 2 ? BaseScreen._zonesFor('building').find(q => q.arg === b.tab)
                    : TownView.bodyRect(b);
    const pt = i % 2 ? { x: z.x + z.w / 2, y: z.y + z.h / 2 }
                     : { x: z.x + z.w / 2, y: z.y + z.h / 2 };
    click(pt.x, pt.y);
    if (st().tab === b.tab && !st().town) opened.push(b.key);
  });
  ok(opened.length === 9, `every place opens its own screen (${opened.join(',')})`);
  quiet(() => BaseScreen.open()); away(); frame();
  click(...(() => { const z = TownView.bodyRect(B[2]); return [z.x + z.w / 2, z.y + z.h / 2]; })());
  ok(st().tab === 'CREW' && BaseScreen._zonesFor('tabGroup').length === 0 && BaseScreen._zonesFor('town').length === 1, 'behind a door: the screen in its room, and the way back');
  key('Escape');
  ok(st().town === true, 'ESCAPE walks back out into the town');
  key('Digit4');
  ok(st().tab === 'MESS' && !st().town, 'key 4 opens the mess');
  const back = BaseScreen._zonesFor('town');
  ok(back.length === 1, 'the screen has a ◀ TOWN button');
  click(back[0].x + back[0].w / 2, back[0].y + back[0].h / 2);
  ok(st().town === true, 'and it walks back to the town');
  key('Numpad9');
  ok(st().tab === 'MEMORIAL' && !st().town, 'the keypad works too: 9 is the hill');
  key('Escape');

  /* ── 4. NOTHING BEHIND THE TOWN ANSWERS ── */
  quiet(() => BaseScreen.open()); BaseScreen._set({ tab: 'HANGAR', town: true }); away(); frame();
  const before = st().interior;
  key('KeyI');
  ok(st().interior === before, '[I] does nothing in the town (the hangar is behind its door)');
  BaseScreen._set({ tab: 'HANGAR' }); key('KeyI');
  ok(st().interior !== before, '(and behind the door it does)');
  key('KeyI'); BaseScreen._set({ town: true });
  {
    for (let i = 0; i < 6; i++) Base.storeWeapon('laser_basic');
    BaseScreen._set({ tab: 'ARMOURY', town: true });
    const wheel = () => { M.scrollDelta = 1; quiet(() => BaseScreen.update(0.05)); M.scrollDelta = 0; };
    wheel();
    ok(st().rackScroll === 0, 'the wheel scrolls no list hidden behind the town');
    BaseScreen._set({ tab: 'ARMOURY' });
    const realRack = Base.armoury, long = Array.from({ length: 23 }, () => 'laser_basic');
    Base.armoury = () => long;                       // shelves enough to scroll (update157: a shelf at a time)
    try { wheel(); } finally { Base.armoury = realRack; }
    ok(st().crateRow === 1, `(and behind the armoury door it does: shelf ${st().crateRow})`);
    BaseScreen._set({ town: true });
  }
  ok(key('Enter') === null && st().loadout, 'ENTER still opens the loadout from the town');
  key('Escape');
  ok(!st().loadout && st().town, 'and ESCAPE out of the loadout lands back in the town');

  /* ── 5. HOVER: THE PLACE SAYS WHAT IT IS AND HOW IT STANDS ── */
  {
    quiet(() => BaseScreen.open());
    const h = TownView.bodyRect(B[0]);
    M.x = h.x + h.w / 2; M.y = h.y + h.h / 2;
    const said = captureText(ctx, () => frame()).map(o => o.t);
    const b = Base.get();
    ok(said.includes(B[0].blurb), 'the hangar under the pointer says what it is');
    ok(said.some(t => t.startsWith(`${b.ships.length}/${Base.shipSlots()} berths`)), 'and how many berths are taken');
    const hz = TownView.bodyRect(B[8]);
    Save.getGraveyard().push({ id: 'h1', name: 'Hoban', race: 'terra', buried: true }, { id: 'h2', name: 'Lost', race: 'terra', buried: false });
    M.x = hz.x + hz.w / 2; M.y = hz.y + hz.h / 2;
    const said2 = captureText(ctx, () => frame()).map(o => o.t);
    ok(said2.includes('1 buried · 1 not recovered'), `the hill counts its dead (${said2.find(t => /buried/.test(t))})`);
    Save.getGraveyard().length = 0;
    away();
  }

  /* ── 6. THE SMALL ANIMATIONS: ONLY THE PLACE UNDER THE POINTER MOVES ── */
  {
    const rects = [];
    const real = ctx.fillRect;
    const grab = (fn) => { rects.length = 0; ctx.fillRect = function (x, y, w, h) { rects.push({ x, y, w, h, c: ctx.fillStyle }); }; try { fn(); } finally { ctx.fillRect = real; } return rects.slice(); };
    const box = (rs) => rs.find(r => r.c === '#8a4a3a' && r.w === 9 && r.h === 5);
    const trolley = (rs) => rs.find(r => r.c === '#4a5262' && r.w === 9 && r.h === 6);
    const sup = TownView.bodyRect(B.find(b => b.key === 'supply'));
    const wk = TownView.bodyRect(B.find(b => b.key === 'works'));
    const at = (T, b) => grab(() => TownView.draw(ctx, { T, mx: b ? b.x + b.w / 2 : -1, my: b ? b.y + b.h / 2 : -1 }));
    const rest = at(100, null);
    ok(box(rest) && box(rest).y === 283 && trolley(rest) && trolley(rest).x === 264, 'at rest: the container on the ground, the trolley at the end of its beam');
    at(200, sup);
    const lifted = at(200.9, sup);
    ok(box(lifted) && box(lifted).y < 280, `hover the supply yard: the stacker lifts its container (${box(lifted) && box(lifted).y})`);
    ok(trolley(lifted).x === 264, 'and the workshop next door stays still');
    at(300, wk);
    const run = at(301.5, wk);
    /* update161: DISPATCH is open again — the pointer over it runs the trolley (as before 154) */
    ok(trolley(run).x !== 264, `hover DISPATCH: the trolley runs along its beam (${trolley(run).x})`);
    ok(box(run).y === 283, 'and the container is back on the ground');
    const win = (rs) => rs.filter(r => r.c === '#c8f4ff').length;
    const bar = TownView.bodyRect(B.find(b => b.key === 'barracks'));
    at(400, bar);
    const w1 = win(at(400.15, bar)), w2 = win(at(402, bar));
    ok(w1 > 0 && w2 > w1 && w2 === TownView.BARRACK_WINDOWS.length, `hover the barracks: the windows come on one by one (${w1} → ${w2})`);
  }

  /* ── 7. TOWN AND HILL ARE PAINTED ONCE ── */
  ok(TownView.town() && TownView.town() === TownView.town(), 'the town is painted once and kept');
  ok(TownView.hill(0) && TownView.hill(0) === TownView.hill(0) && TownView.hill(1) !== TownView.hill(0), 'each size of the hill once');

  /* ── 8. OUR PLOT: ROOM FOR EVERY MARKER, GROWING A TERRACE AT A TIME ── */
  {
    ok(TownView.hillTier(0) === 0 && TownView.hillTier(TownView.hillCapacity(0)) === 0 && TownView.hillTier(TownView.hillCapacity(0) + 1) === 1,
       `a small plot while there are few (${TownView.hillCapacity(0)}), a bigger one past that`);
    ok(TownView.hillSlots(30).length === 30 && TownView.hillSlots(100).length === 100, 'thirty dead, a hundred: every one has a place');
    const S = TownView.hillSlots(TownView.hillCapacity(2));
    const bad = [];
    S.forEach((a, i) => S.forEach((c, j) => { if (j > i && a.row === c.row && Math.abs(a.x - c.x) < 30) bad.push(`${i}/${j}`); }));
    ok(!bad.length, `markers on one terrace stand apart (${bad.slice(0, 4).join(' ')})`);
    ok(S.every(p => p.x > 0 && p.x < 1000 && p.y > 200 && p.y <= 720), 'on the hill, left of the cliff');
    ok(S.every(p => { const [a, b] = TownView.stairSpan(p.row); return p.x <= a || p.x >= b; }), 'none of them on the stair');
  }

  /* ── 9. THE HILL: THE OLD MARKERS, EACH WITH ITS LANTERN; NOT RECOVERED; THE CARD ── */
  {
    Save.reset(); Save.load();
    const G = Save.getGraveyard(); G.length = 0;
    ['Ada', 'Bo', 'Cy', 'Di', 'Ed'].forEach((n, i) => G.push({ id: 'g' + i, name: n, race: 'terra', buried: true, battles: i * 4, wins: i, kills: i, sector: 2 }));
    G.push({ id: 'gx', name: 'Gone', race: 'terra', buried: false, sector: 3 });
    quiet(() => BaseScreen.open());
    BaseScreen._act('building', 'MEMORIAL');
    away();
    const lamps = [];
    const realLamp = TownView.lantern;
    TownView.lantern = function (c, x, y) { lamps.push({ x, y }); return realLamp.apply(this, arguments); };
    let drawn;
    try { drawn = captureText(ctx, () => frame()).map(o => o.t); } finally { TownView.lantern = realLamp; }
    const z = BaseScreen._graves(), slots = TownView.hillSlots(5);
    ok(z.length === 5, `five markers on the hill (${z.length})`);
    ok(z.every(q => slots.some(p => Math.abs(q.x + q.w / 2 - p.x) <= 1 && q.y + q.h > p.y && q.y + q.h <= p.y + 8)), 'each one standing on a place of our plot');
    ok(lamps.length === 5 && slots.every(p => lamps.some(l => l.x === p.x && l.y === p.y)), `and a lantern lit by each (${lamps.length})`);
    ok(drawn.includes('NOT RECOVERED') && drawn.includes('Gone'), 'the men nobody carried home are listed on the cliff');
    ok(BaseScreen._zonesFor('tabGroup').length === 0 && BaseScreen._zonesFor('town').length === 1, '◀ TOWN is on the hill (no tab bar since update152)');
    ok(BaseScreen._zonesFor('loadout').length === 0, 'and no contract bar across our plot');
    const q = z.find(v => v.name === 'Cy');
    M.x = q.x + q.w / 2; M.y = q.y + q.h / 2;
    const card = captureText(ctx, () => frame()).map(o => o.t);
    ok(card.includes('Cy') && card.includes('R.I.P.') && card.includes('brought home and buried'), 'hover a marker: the same card as always');
    away();
    // a hill fuller than its plot says so
    for (let i = 0; i < 140; i++) G.push({ id: 'm' + i, name: 'M' + i, race: 'terra', buried: true });
    const full = captureText(ctx, () => frame()).map(o => o.t);
    ok(BaseScreen._graves().length === TownView.hillCapacity(2) && full.some(t => /more lie further up the hill/.test(t)),
       `a hill fuller than its plot says how many lie further up (${BaseScreen._graves().length} drawn)`);
    G.length = 0;
  }

  /* ── 10. CONTINUE IS IN THE TOWN WHILE A HULL IS OUT THERE ── */
  {
    Save.reset(); Save.load(); Save.startRun(); Save.updateRun({ shipKey: 'scout' });
    quiet(() => BaseScreen.open()); away(); frame();
    ok(st().town && BaseScreen._zonesFor('continue').length === 1, 'CONTINUE is on the town\'s bar while a contract is in the air');
    Save.endRun(false);
  }
})();

// ============================================================
section('336. Out of a counter and back into the port (150, jj: "wchodzę w jakiś handel i nie mogę wyjść… daję F5, do portu wrócić nie mogę… żeby do portu można było wejść, jeżeli dalej jesteśmy w tym samym miejscu w sektorze")');
// ============================================================
(function testUpdate150() {
  const sb = loadEngine();
  const { Save, Ship, Station, PortView, LootScreen, SectorMap, Input, Renderer, CrewMember } = sb;
  const T = sb.Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const M = Input.mouse;
  const frame = () => quiet(() => T._update(0.016));
  const press = (x, y) => { M.x = x; M.y = y; M.leftPressed = true; try { frame(); } finally { M.leftPressed = false; } };
  const key = (code) => { const real = Input.isPressed; Input.isPressed = (c) => c === code; try { frame(); } finally { Input.isPressed = real; } };
  const mid = (r) => [r.x + r.w / 2, r.y + r.h / 2];
  const promenade = () => T.STATE === 'station' && T.portMode && PortView.isOpen() && PortView.view() === 'port' && !LootScreen.isOpen();

  /* ── 0. A PORT IS KEPT WHOLE: NAME, KIND, SHELVES, RECEIPT ── */
  {
    const st = new Station(2, 4242);
    st.stock.fuel = 3;
    if (st.stock.weapons[0]) st.stock.weapons[0].sold = true;
    st.stock.crew.push({ name: 'Quill', skill: 'weapons', sold: false, member: new CrewMember({ name: 'Quill', skills: { weapons: { level: 1, xp: 0 } } }) });
    st._note('He2 cell', 1, -12);
    const back = Station.deserialise(JSON.parse(JSON.stringify(st.serialise())));
    ok(back instanceof Station && back.name === st.name && back.type === st.type && back.sector === 2, `the same port comes back (${back && back.name})`);
    ok(back.stock.fuel === 3 && back.stock.weapons.length === st.stock.weapons.length
       && back.stock.weapons.every((w, i) => w.def === st.stock.weapons[i].def && w.sold === st.stock.weapons[i].sold), 'its shelves as they were: what was bought is still gone');
    const q = back.stock.crew.find(c => c.name === 'Quill');
    ok(q && q.member instanceof CrewMember && q.member.name === 'Quill' && q.member.skills.weapons.level === 1, 'the man at the bar is the same man');
    ok(back.ledger.length === 1 && back.ledger[0].label === 'He2 cell', 'and this visit\'s receipt');
    ok(quiet(() => back.counterGrid()).items.length > 0 || back.stock.fuel === 0, 'and it trades: the counter is laid out off the kept shelves');
    ok(Station.deserialise(null) === null && Station.deserialise({}) === null, 'nothing kept is no port');
  }

  /* ── setup: a run, a hull with a manned helm and fuel, a port one jump in ── */
  const isStore = (m) => (id) => m.getNode(id)?.type === 'store';
  Save.reset(); Save.load(); Save.startRun();
  let start = null, portId = null;
  for (let seed = 1; seed < 300 && !portId; seed++) {
    const ship = new Ship('scout', true, 80, 120); ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    Save.updateRun({ seed, sector: 1, lane: null, mapProgress: null, port: null, scrap: 500,
                     ship: ship.serialise(), crew: ship.crew.map(c => c.serialise()) });
    T.station = null;
    quiet(() => T._continueRun());
    const m = T.sectorMap;
    start = m.startNodes.find(s => s.next.some(isStore(m)));
    if (start) portId = start.next.find(isStore(m));
  }
  ok(!!portId, `test setup: a sector with a port one jump in (${portId})`);
  const ship = T.playerShip;
  ship._allocateDefaultPower(); manCockpit(ship);
  ship.cargo.addStack('he2_med', 8);
  quiet(() => T._travelTo(start.id));
  quiet(() => T._travelTo(portId));
  for (let i = 0; i < 4 && !PortView.isOpen(); i++) frame();
  ok(T.STATE === 'station' && PortView.isOpen() && T.sectorMap.currentId === portId, 'test setup: docked at the port');
  const st0 = T.station;
  ok(st0.nodeId === portId, 'the port knows which node it stands at');
  ok(Save.getRun().port?.node === portId && Save.getRun().port?.data?.name === st0.name, 'and the run keeps it from the moment we dock');

  /* ── 1. BACK ON A COUNTER COMES BACK TO THE PROMENADE ── */
  quiet(() => PortView.draw(ctx));
  const stall = (k) => PortView._zonesFor('stall').find(z => z.arg === k);
  const backAt = () => {
    const t = captureText(ctx, () => quiet(() => LootScreen.draw(ctx))).find(o => o.t === 'BACK');
    return t ? [t.x, t.y - 4] : null;
  };
  press(...mid(stall('broker')));
  ok(T.STATE === 'loot' && LootScreen.isOpen(), 'the broker\'s counter opens');
  const b = backAt();
  const br = stall('broker');
  ok(b && sb.Utils.pointInRect(b[0], b[1], br.x, br.y, br.w, br.h), `(BACK lies right over the broker's stall: ${b})`);
  press(...b);
  ok(T.STATE === 'station' && !LootScreen.isOpen(), 'BACK closes his counter');
  frame(); frame();
  ok(promenade(), 'and we stand on the promenade — the same press does not open his counter again');

  /* every stall, in and out */
  const out = [];
  ['drydock', 'guns', 'qm', 'bar', 'clinic', 'broker'].forEach(k => {
    quiet(() => PortView.draw(ctx));
    const z = stall(k);
    if (!z) return;
    press(...mid(z)); frame();
    if (LootScreen.isOpen()) { const p = backAt(); if (p) press(...p); }
    else key('Escape');
    frame(); frame();
    if (promenade()) out.push(k);
  });
  ok(out.length === 6, `every stall lets you out again (${out.join(',')})`);

  /* ── 2. DEPART, AND THE WAY BACK IN ── */
  quiet(() => PortView.draw(ctx));
  press(...mid(PortView._zonesFor('depart')[0]));
  ok(T.STATE === 'map' && !PortView.isOpen(), 'DEPART: on the map, still at the port\'s node');
  ok(T._atPort() === true, 'the map knows there is a port where we stand');
  const said = captureText(ctx, () => quiet(() => T._draw())).map(o => o.t);
  ok(said.some(t => t === `DOCK AGAIN — ${st0.name.toUpperCase()}  [P]`), `the chart offers to dock again, by the port's name (${said.find(t => /DOCK AGAIN/.test(t))})`);
  const customs = [];
  const realCustoms = Station.prototype.customs;
  Station.prototype.customs = function (...a) { customs.push(this.name); return realCustoms.apply(this, a); };
  try {
    key('KeyP');
    frame();
    ok(promenade() && T.station === st0, 'P: back on the same promenade — the same port, as we left it');
    ok(customs.length === 0, 'no customs a second time: that was the arrival');
    quiet(() => PortView.draw(ctx));
    press(...mid(PortView._zonesFor('depart')[0]));
    press(...mid(T._dockRect()));
    frame();
    ok(promenade() && T.station === st0, 'the button under the chart does the same');
    quiet(() => PortView.draw(ctx));
    press(...mid(PortView._zonesFor('depart')[0]));
  } finally { Station.prototype.customs = realCustoms; }

  /* ── 3. F5: THE SAME PORT AFTER A RELOAD ── */
  const gone = st0.stock.weapons.length ? 0 : -1;
  if (gone === 0) st0.stock.weapons[0].sold = true;
  st0._note('test crate', 1, 5);
  quiet(() => T._saveShip());
  const name = st0.name, type = st0.type;
  T.station = null; T.playerShip = null; T.sectorMap = null;
  quiet(() => T._continueRun());
  ok(T.STATE === 'map' && T.sectorMap.currentId === portId, 'CONTINUE: on the map, at the port\'s node');
  ok(T.station && T.station !== st0 && T.station.name === name && T.station.type === type && T.station.nodeId === portId,
     `the port comes back with the run (${T.station && T.station.name})`);
  ok(gone < 0 || T.station.stock.weapons[0].sold === true, 'with what was bought there still gone');
  ok(T.station.ledger.some(l => l.label === 'test crate'), 'and the receipt of the visit');
  // the node itself is the gangway
  {
    manCockpit(T.playerShip);
    const node = T.sectorMap.current(), o = SectorMap.origin(Renderer.getWidth(), Renderer.getHeight());
    M.x = node.x + o.x; M.y = node.y + o.y;
    press(node.x + o.x, node.y + o.y);
    frame();
    ok(promenade() && T.station.name === name && T.sectorMap.currentId === portId, 'clicking the node we stand on walks back into the port — no jump, no He2');
    quiet(() => PortView.draw(ctx));
    press(...mid(PortView._zonesFor('depart')[0]));
  }

  /* ── 4. NOT HERE, NOT ANY MORE ── */
  {
    // a record from another sector is not this port
    const rec = Save.getRun().port;
    Save.updateRun({ port: { ...rec, sector: rec.sector + 1 } });
    T.station = null;
    quiet(() => T._continueRun());
    ok(T.station === null, 'a port kept from another sector is not brought back here');
    // a save from before this update: no record — the node is still a port, and P makes one
    Save.updateRun({ port: null });
    quiet(() => T._continueRun());
    manCockpit(T.playerShip);
    key('KeyP'); frame();
    ok(promenade() && T.station && T.station.nodeId === portId, 'a save from before this update: P still docks here');
    quiet(() => PortView.draw(ctx));
    press(...mid(PortView._zonesFor('depart')[0]));
    // the jump away forgets it
    T.playerShip.cargo.addStack('he2_med', 4);
    manCockpit(T.playerShip);
    const next = T.sectorMap.current().next.find(id => !isStore(T.sectorMap)(id)) ?? T.sectorMap.current().next[0];
    quiet(() => T._travelTo(next));
    ok(T.sectorMap.currentId === next, 'test setup: jumped on');
    ok(Save.getRun().port == null, 'the jump away leaves the port behind: the run keeps none');
    ok(T._atPort() === isStore(T.sectorMap)(next), 'and no way back into it from here');
  }
})();

// ============================================================
section('337. The plans: the drydock\'s module yard (151, jj: "okno upgrade modułów na stacji jest stare, przydałoby się coś fajnego, aby to dobrze wyglądało i łatwo czytelne")');
// ============================================================
(function testUpdate151() {
  const sb = loadEngine();
  const { Save, Ship, Station, PortView, Input, SYSTEM_DEFS } = sb;
  const T = sb.Game.__test;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const M = Input.mouse;
  const draw = () => quiet(() => PortView.draw(ctx));
  const frame = () => quiet(() => T._update(0.016));
  const press = (z) => { draw(); M.x = z.x + z.w / 2; M.y = z.y + z.h / 2; M.leftPressed = true; try { frame(); } finally { M.leftPressed = false; } M.x = -100; M.y = -100; draw(); };
  const key = (code) => { const real = Input.isPressed; Input.isPressed = (c) => c === code; try { frame(); } finally { Input.isPressed = real; } draw(); };
  const zone = (act, arg) => { draw(); return PortView._zonesFor(act).find(z => arg === undefined || JSON.stringify(z.arg) === JSON.stringify(arg)); };
  const said = () => captureText(ctx, draw).map(o => o.t);

  const fresh = (scrap = 400) => {
    Save.reset(); Save.load(); Save.startRun(); Save.updateRun({ scrap });
    const ship = new Ship('scout', true, 80, 120);
    ship._allocateDefaultPower();
    sb.makeStartingCrew().forEach(c => ship.addCrew(c));
    const st = new Station(2, 31337);
    st.type = 'general';
    st.stock.newModules = [{ type: 'cloaking', cost: 85, sold: false }, { type: 'medbay', cost: 70, sold: false }, { type: 'shields', cost: 900, sold: false },
                           { type: 'engines', cost: 50, sold: false }];      // one this hull already has
    st.stock.reactorUpgrade = true;
    T.playerShip = ship; T.station = st;
    quiet(() => T._openPort());
    T.STATE = 'station';
    quiet(() => T._openStall('drydock'));
    return { ship, st };
  };

  /* ── 1. MODULES OPENS THE PLANS — A ROOM, NOT THE OLD PANEL ── */
  let { ship, st } = fresh();
  const opened = [];
  const realOpen = sb.UI.openStation;
  sb.UI.openStation = function (...a) { opened.push(a); };
  try { press(zone('modules')); } finally { sb.UI.openStation = realOpen; }
  ok(PortView.view() === 'plans' && opened.length === 0, 'MODULES in the drydock opens the plans, on the canvas — the old panel stays shut');
  const firstMod = ship.rooms.find(r => r.type !== 'empty');
  ok(PortView.planState().sel === firstMod.id, `a module is picked from the start, so the card is never blank (${PortView.planState().sel})`);

  /* ── 2. YOUR SHIP: EVERY MODULE NAMED, ITS LEVEL IN PIPS, EVERY ROOM CLICKABLE ── */
  {
    const R = PortView.planRects();
    const rooms = ship.rooms.map(r => ({ r, z: zone('plRoom', r.id) }));
    ok(rooms.every(o => o.z), 'every room of the ship can be clicked');
    ok(rooms.every(o => o.z.x >= R.stage.x && o.z.y >= R.stage.y + 30 && o.z.x + o.z.w <= R.stage.x + R.stage.w && o.z.y + o.z.h <= R.stage.y + R.stage.h),
       'and the whole ship fits its stage');
    const lap = [];
    rooms.forEach((a, i) => rooms.forEach((b, j) => { if (j > i && a.z.x < b.z.x + b.z.w - 1 && b.z.x < a.z.x + a.z.w - 1 && a.z.y < b.z.y + b.z.h - 1 && b.z.y < a.z.y + a.z.h - 1) lap.push(`${a.r.id}×${b.r.id}`); }));
    ok(!lap.length, `no two rooms overlap on the stage (${lap.join(' ')})`);
    const t = said();
    ok(t.includes('ENGINES') && t.includes('COCKPIT') && t.includes('REACTOR') && t.includes('WEAPONS 1'), 'each module carries its name');
    ok(ship.rooms.some(r => r.type === 'empty') ? t.includes('EMPTY BAY') : true, 'an empty bay says so');
  }

  /* ── 3. THE CARD: PICTURE, NOW → NEXT, ONE UPGRADE WITH ITS PRICE ── */
  const engRoom = ship.rooms.find(r => r.type === 'engines'), eng = engRoom.system;
  press(zone('plRoom', engRoom.id));
  ok(PortView.planState().sel === engRoom.id, 'clicking the engines picks them');
  {
    const lv = eng.level, cost = st.systemUpgradeCost(eng);
    const t = said();
    ok(t.includes('ENGINES') && t.includes(`LEVEL ${lv} / ${eng.def.maxLevel}`), `the card names it and its level (${lv})`);
    const rows = PortView.planRows(engRoom);
    const pct = (n) => `+${Math.round(n * Ship.EVADE_ENGINE * 100)}%`;
    ok(rows[0].k === 'POWER BARS' && rows[0].now === `${lv}` && rows[0].next === `${lv + 1}`, 'NOW → NEXT: one more power bar');
    ok(rows[1].k === 'EVASION' && rows[1].now === pct(lv) && rows[1].next === pct(lv + 1), `and the evasion it buys, off the ship's own rule (${rows[1].now} → ${rows[1].next})`);
    ok(t.includes(rows[1].now) && t.includes(rows[1].next), 'both written on the card');
    ok(t.includes(`UPGRADE  ▶  ${cost} CC`) && t.includes(`400 CC → ${400 - cost} CC after`), 'one button, with the price and what is left after');

    press(zone('plUp'));
    ok(eng.level === lv + 1 && Save.getRun().scrap === 400 - cost, `UPGRADE: level ${lv} → ${eng.level}, ${cost} CC paid`);
    ok(st.ledger.at(-1)?.label === 'Engines +1' && st.ledger.at(-1).cc === -cost, 'on the receipt');
    const saved = (Save.getRun().ship?.systems ?? []).find(s => s.type === 'engines');
    ok(saved && saved.level === eng.level, 'and in the save at once');
    frame(); frame();
    ok(eng.level === lv + 1, 'one press, one level');
  }
  // no money: the reason, no button
  Save.updateRun({ scrap: 3 });
  {
    const cost = st.systemUpgradeCost(eng), t = said();
    ok(!zone('plUp') && t.includes(`NEED ${cost - 3} MORE CC`), 'short of CC: the card says by how much, and nothing to press');
  }
  // the top: MAX LEVEL, no next
  Save.updateRun({ scrap: 999 });
  eng.level = eng.def.maxLevel;
  {
    const t = said(), rows = PortView.planRows(engRoom);
    ok(!zone('plUp') && t.includes('MAX LEVEL') && rows.every(r => r.next === null) && t.includes('—'), 'at the top: MAX LEVEL, and no NEXT');
  }
  eng.level = 2;

  /* ── 4. THE REACTOR: ITS CARD AND THE SHORTCUT BY BACK ── */
  {
    const rRoom = ship.rooms.find(r => r.type === 'reactor');
    const L = PortView.planLevel(rRoom);
    ok(L.l === ship.reactor.level && L.m === ship.reactor.maxLevel && PortView.planRows(rRoom)[0].k === 'POWER', 'the reactor counts in power');
    const lv = ship.reactor.level, cost = st.reactorCost(ship), cc = Save.getRun().scrap;
    press(zone('plReactor'));
    ok(ship.reactor.level === lv + 1 && Save.getRun().scrap === cc - cost && st.ledger.at(-1)?.label === 'Reactor +1', `REACTOR +1 by BACK: ${lv} → ${ship.reactor.level}, ${cost} CC, on the receipt`);
    press(zone('plRoom', rRoom.id));
    const cost2 = st.reactorCost(ship);
    ok(said().includes(`UPGRADE  ▶  ${cost2} CC`), 'and its own card upgrades it too, at the seller\'s price');
    press(zone('plUp'));
    ok(ship.reactor.level === lv + 2, 'both ways');
  }

  /* ── 5. A NEW MODULE: PICK IT, THE EMPTY BAYS LIGHT UP, CLICK ONE ── */
  {
    const offers = PortView.planOffers();
    ok(offers.some(o => o.type === 'cloaking') && offers.some(o => o.kind === 'wpn') && !offers.some(o => o.type === 'engines'),
       `for sale: what this hull has not got, and a gun mount (${offers.map(o => o.label).join(', ')})`);
    ok(!zone('plOffer', offers.find(o => o.type === 'shields').key) && said().some(t => /need more/.test(t)), 'one he cannot pay for cannot be picked, and says so');
    const empty = ship.rooms.filter(r => r.type === 'empty');
    ok(empty.length >= 1, `test setup: an empty bay aboard (${empty.length})`);
    const cl = offers.find(o => o.type === 'cloaking');
    press(zone('plOffer', cl.key));
    ok(PortView.planState().offer === cl.key, 'picking the cloak');
    const t = said();
    ok(t.filter(x => x === 'INSTALL HERE').length === empty.length && t.includes('NEW: CLOAK'), 'every empty bay lights up, the card is the cloak\'s');
    // a module clicked instead: the pick is put back
    press(zone('plRoom', engRoom.id));
    ok(PortView.planState().offer === null && PortView.planState().sel === engRoom.id, 'clicking a module instead puts the plans back');
    press(zone('plOffer', cl.key));
    key('Escape');
    ok(PortView.planState().offer === null && PortView.view() === 'plans', 'ESC puts them back too, and stays in the yard');
    press(zone('plOffer', cl.key));
    const cc = Save.getRun().scrap, bay = empty[0];
    press(zone('plRoom', bay.id));
    ok(ship.getRoomById(bay.id).type === 'cloaking' && ship.getSystem('cloaking'), 'clicking a green bay fits the cloak there');
    ok(Save.getRun().scrap === cc - st.moduleCost(st.stock.newModules[0]) && st.stock.newModules[0].sold, 'paid for, and off his list');
    ok(st.ledger.at(-1)?.label === 'Cloak fitted', 'on the receipt');
    ok(PortView.planState().offer === null && PortView.planState().sel === bay.id, 'and the new module is the one picked');
    ok((Save.getRun().ship?.systems ?? []).some(s => s.type === 'cloaking'), 'saved at once');
    ok(!PortView.planOffers().some(o => o.type === 'cloaking'), 'it is not for sale any more');
  }

  /* ── 6. A GUN MOUNT INTO A FRESH HULL'S BAY ── */
  ({ ship, st } = fresh(999));
  press(zone('modules'));
  {
    const n = ship.weaponRooms.length, wpn = PortView.planOffers().find(o => o.kind === 'wpn');
    const bay = ship.rooms.find(r => r.type === 'empty');
    press(zone('plOffer', wpn.key));
    press(zone('plRoom', bay.id));
    ok(ship.weaponRooms.length === n + 1 && ship.getRoomById(bay.id).type === 'weapons', `a weapon mount fitted in the bay (${n} → ${ship.weaponRooms.length})`);
    ok(said().includes(`WEAPONS ${n + 1}`), 'and it is named on the ship');
  }

  /* ── 7. BACK AND ESC: TO THE YARD ── */
  press(zone('back'));
  ok(PortView.view() === 'drydock', 'BACK: the drydock');
  press(zone('modules'));
  key('Escape');
  ok(PortView.view() === 'drydock', 'ESC with nothing picked: the drydock');
})();

// ============================================================
section('338. Every building is a room (152, jj: "klikamy w hangar, to idziemy do hangaru, i exit — do wszystkich"): its own painted interior, its name, its keeper, the next contract, LOADOUT and ◀ TOWN — and no tab bar');
// ============================================================
(function testUpdate152() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, TownView, Input } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.reset(); Save.load();
  Base.earn(500); Base.hireRecruit();
  const ROOMS = ['HANGAR', 'ARMOURY', 'CREW', 'MESS', 'SUPPLY', 'WANTED', 'GATE'];     // the workshop is closed (update154)

  /* ── 1. EACH BUILDING HAS ITS OWN ROOM, PAINTED ONCE ── */
  ok(ROOMS.every(t => TownView.room(t) && TownView.room(t) === TownView.room(t)), 'every building\'s room is painted once and kept');
  ok(new Set(ROOMS.map(t => TownView.room(t))).size === ROOMS.length, 'and each one is its own');

  /* ── 2. EACH ONE HAS SOMEBODY IN IT — THE SAME PERSON EVERY VISIT ── */
  const K = ROOMS.map(t => TownView.keeper(t));
  ok(K.every(k => k && k.name && k.role && k.line && k.faceSeed > 0), 'a keeper for every building: a name, a role, a line, a face');
  ok(ROOMS.every(t => JSON.stringify(TownView.keeper(t)) === JSON.stringify(TownView.keeper(t))), 'the same keeper on every visit');
  ok(new Set(K.map(k => k.faceSeed)).size === ROOMS.length, 'and a different face in each building');

  /* ── 3. INSIDE: THE ROOM, ITS NAME, THE KEEPER, THE FOOT — NO TAB BAR ── */
  const painted = [];
  const realRoom = TownView.drawRoom;
  TownView.drawRoom = function (c, tab) { painted.push(tab); return realRoom.apply(this, arguments); };
  const bad = [];
  try {
    ROOMS.forEach(t => {
      quiet(() => BaseScreen.open());
      BaseScreen._act('building', t);
      painted.length = 0;
      const said = captureText(ctx, () => quiet(() => BaseScreen.draw(ctx))).map(o => o.t);
      const bd = TownView.BUILDINGS.find(q => q.tab === t), kp = TownView.keeper(t);
      const why = [];
      if (painted.join() !== t) why.push(`room ${painted.join()}`);
      if (!said.includes(bd.name)) why.push('name');
      if (!said.includes(`HOME BASE — ${bd.blurb}`)) why.push('blurb');
      if (!said.includes(`"${kp.name}"`) || !said.includes(kp.role.toUpperCase())) why.push('keeper');
      if (!said.some(x => x === kp.line || kp.line.startsWith(x))) why.push('line');
      if (!said.includes('NEXT CONTRACT')) why.push('contract');
      if (BaseScreen._zonesFor('loadout').length !== 1 || BaseScreen._zonesFor('town').length !== 1) why.push('foot');
      if (BaseScreen._zonesFor('tabGroup').length || BaseScreen._zonesFor('tab').length) why.push('tabs');
      if (why.length) bad.push(`${t}: ${why.join('/')}`);
    });
  } finally { TownView.drawRoom = realRoom; }
  ok(!bad.length, `every building: its room, its name, its keeper and his line, the contract, LOADOUT and ◀ TOWN, no tabs (${bad.join('; ')})`);

  /* ── 4. THE FOOT WORKS ── */
  quiet(() => BaseScreen.open());
  BaseScreen._act('building', 'SUPPLY');
  quiet(() => BaseScreen.draw(ctx));
  const M = Input.mouse;
  const press = (z) => { M.x = z.x + z.w / 2; M.y = z.y + z.h / 2; M.leftPressed = true; let r; try { r = quiet(() => BaseScreen.update(0.016)); } finally { M.leftPressed = false; M.x = -100; M.y = -100; } quiet(() => BaseScreen.draw(ctx)); return r; };
  press(BaseScreen._zonesFor('loadout')[0]);
  ok(BaseScreen._state().loadout, 'LOADOUT at the foot of a room opens the loadout');
  {
    painted.length = 0;
    TownView.drawRoom = function (c, tab) { painted.push(tab); return realRoom.apply(this, arguments); };
    try { quiet(() => BaseScreen.draw(ctx)); } finally { TownView.drawRoom = realRoom; }
    ok(painted.length === 0, 'and the room is not painted under it');
  }
  BaseScreen._act('loClose');
  quiet(() => BaseScreen.draw(ctx));
  press(BaseScreen._zonesFor('town')[0]);
  ok(BaseScreen._state().town, '◀ TOWN at the foot walks out');
  // CONTINUE while a hull is out there
  Save.startRun(); Save.updateRun({ shipKey: 'scout' });
  BaseScreen._act('building', 'HANGAR');
  quiet(() => BaseScreen.draw(ctx));
  ok(BaseScreen._zonesFor('continue').length === 1, 'CONTINUE is at the foot of a room while a contract is in the air');
  Save.endRun(false);
  quiet(() => BaseScreen.draw(ctx));
  ok(BaseScreen._zonesFor('continue').length === 0, 'and gone when nothing is');

  /* ── 5. THE SCREEN HAS MORE ROOM THAN THE OLD PANEL ── */
  {
    const panels = [];
    const real = ctx.roundRect;
    ctx.roundRect = function (x, y, w, h) { panels.push({ x, y, w, h }); return real?.apply(this, arguments); };
    try { quiet(() => BaseScreen.draw(ctx)); } finally { ctx.roundRect = real; }
    ok(panels.some(p => p.x === 16 && p.y === 62 && p.w === 1248 && p.h === 530), 'the screen\'s panel is 1248 × 530 (the old one was 1200 × 386)');
  }
})();

// ============================================================
section('339. The jet bridge goes to her door, and the Earth is the ruined one (153, jj: "ramię łączące port ze statkiem powinno być większe i łączyć się z drzwiami statku, taki rękaw jak w samolotach na lotnisku… pamiętaj aby zawsze ziemi tej używać po kataklizmie")');
// ============================================================
(function testUpdate153Dock() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, DockArt, Ship, SHIP_CATALOG, TownView, PortView, Station } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const M_ = sb.HULL_GRID.MARGIN;

  /* ── 1. THE BRIDGE MEETS AN AIRLOCK ON HER BOW WALL ── */
  const bowLocks = (sh) => sh.doors.filter(d => d.isAirlock && (() => { const r = sh.rooms.find(q => q.id === d.roomA); return r && d.x >= r.x + r.w - 1; })());
  const clear = (sh, d) => { const g = sh.hullArtGeometry();
    return ![...g.plate, ...g.prows, ...g.engines].some(r => r.y < d.y + 14 && d.y - 14 < r.y + r.h && r.x + r.w > d.x + M_ + 1); };
  const res = {};
  Object.keys(SHIP_CATALOG).forEach(key => {
    const sh = new Ship(key, true, 300, 300);
    const T = DockArt.moorings(sh).tube, L = bowLocks(sh), seen = L.filter(d => clear(sh, d));
    res[key] = T.hatch;
    ok(L.some(d => d.y === T.y), `${key}: the bridge is level with an airlock on her bow wall, not the stern one`);
    if (seen.length) {
      const low = Math.max(...seen.map(d => d.y));
      ok(T.hatch === true && T.y === low && T.x === seen.find(d => d.y === low).x + M_, `${key}: a door nothing stands in front of — the lowest one, the bridge right on her plate`);
    } else {
      const low = Math.max(...L.map(d => d.y));
      ok(T.hatch === false && T.y === low, `${key}: every bow door is behind her nose — the bridge meets the nose where the lowest one is`);
    }
  });
  ok(res.scout === true && res.isis === true, 'Bastet docks on her short lower deck, Isis into the notch of her middle deck (both doors in plain sight)');

  /* ── 2. AN ENEMY HULL (FACING LEFT) GETS IT MIRRORED ── */
  {
    const foe = new Ship('scout', false, 300, 300), F = DockArt.moorings(foe);
    const g = foe.hullArtGeometry();
    ok(F.tube.x < g.bounds.x + g.bounds.w / 2 && foe.doors.some(d => d.isAirlock && d.y === F.tube.y), 'a hull facing the other way: its bow is on the left and the bridge goes there');
  }

  /* ── 3. HER BOW IS MOVED CLEAR FOR THE BRIDGE, NEVER OFF THE STAGE ── */
  {
    const R = { x: 340, y: 64, w: 632, h: 526 }, cx = R.x + R.w / 2, J = DockArt.JB;
    Object.keys(SHIP_CATALOG).forEach(key => {
      const dx = DockArt.shiftFor(key, R, cx);
      const L = sb.SHIP_LAYOUTS[key].rooms, bx = Math.min(...L.map(r => r.x)), bw = Math.max(...L.map(r => r.x + r.w)) - bx;
      const sh = new Ship(key, true, Math.round(cx + dx - bw / 2 - bx), 300), M = DockArt.moorings(sh);
      ok(dx <= 0 && M.F.left >= R.x + 13, `${key}: moved ${Math.round(-dx)} px to the left at most, her stern still inside the bay`);
      const room = R.x + R.w - M.tube.x;
      ok(room >= J.CAB + J.FULL + J.WALL + 9 || M.F.left <= R.x + 15, `${key}: the bridge gets its whole length (${Math.round(room)} px) — or she is as far over as she goes`);
    });
    ok(DockArt.shiftFor('scout', { x: 0, y: 0, w: 1600, h: 600 }, 800) === 0, 'a bay wide enough: she stays in the middle');
  }

  /* ── 4. THE HANGAR AND THE LOADOUT: THE BELLOWS GO OVER HER, AFTER SHE IS DRAWN ── */
  {
    Save.reset(); Save.load();
    quiet(() => BaseScreen.open());
    const order = [];
    const rD = DockArt.draw, rO = DockArt.drawOver, rS = Ship.prototype.draw;
    DockArt.draw = function () { order.push('bay'); return rD.apply(this, arguments); };
    DockArt.drawOver = function () { order.push('over'); return rO.apply(this, arguments); };
    Ship.prototype.draw = function () { order.push('ship'); return rS.apply(this, arguments); };
    try {
      BaseScreen._set({ tab: 'HANGAR', screen: null, town: false });
      quiet(() => BaseScreen.draw(ctx));
      ok(order.join() === 'bay,ship,over', `the hangar: the bay under her, the bridge's bellows over her (${order.join()})`);
      order.length = 0;
      quiet(() => BaseScreen._act('loadout'));
      quiet(() => BaseScreen.draw(ctx));
      ok(order.slice(0, 3).join() === 'bay,ship,over', `the loadout too (${order.slice(0, 3).join()})`);
      quiet(() => BaseScreen._act('loClose'));
    } finally { DockArt.draw = rD; DockArt.drawOver = rO; Ship.prototype.draw = rS; }
  }

  /* ── 4b. IN THE HANGAR AND THE LOADOUT SHE REALLY IS MOVED OVER ── */
  {
    Save.reset(); Save.load(); Base.earn(1000);
    quiet(() => Base.buyShip('hauler'));
    quiet(() => BaseScreen.open());
    const J = DockArt.JB, want = J.CAB + J.FULL + J.WALL + 9;
    const idx = Base.get().ships.findIndex(e => e.key === 'hauler');
    const seen = [];
    const rD = DockArt.draw;
    DockArt.draw = function (c, R, sh) { seen.push({ R, sh }); return rD.apply(this, arguments); };
    try {
      BaseScreen._set({ tab: 'HANGAR', screen: null, town: false });
      quiet(() => BaseScreen._act('ship', idx));
      quiet(() => BaseScreen.draw(ctx));
      const fits = ({ R, sh }) => { const M = DockArt.moorings(sh); return R.x + R.w - M.tube.x >= want || M.F.left <= R.x + 15; };
      ok(seen.length === 1 && seen[0].sh.layoutKey === 'hauler' && fits(seen[0]), 'the hangar: Hapi moved over so the bridge reaches her (or as far over as she goes)');
      seen.length = 0;
      quiet(() => BaseScreen._act('loadout'));
      quiet(() => BaseScreen.draw(ctx));
      ok(seen.length >= 1 && fits(seen[0]), 'the loadout: the same');
      quiet(() => BaseScreen._act('loClose'));
    } finally { DockArt.draw = rD; }
  }

  /* ── 5. THE ONE EARTH: RUINED, IN THE DOCK, THE PORT WINDOW AND THE ORRERY ── */
  {
    ok(typeof TownView.ruinedEarth === 'function', 'the ruined Earth is one painter, shared');
    const calls = [];
    const real = TownView.ruinedEarth;
    TownView.ruinedEarth = function (g, px, py, pr) { calls.push({ px, py, pr }); return real.apply(this, arguments); };
    try {
      DockArt.bay(777, 401);
      ok(calls.length === 1, `the dock paints the ruined Earth over the moon (${calls.length})`);
      DockArt.bay(777, 401);
      ok(calls.length === 1, 'and only once for a size');
      calls.length = 0;
      const st = new Station(1, 4242), sh = new Ship('scout', true, 80, 120);
      PortView.open(st, sh); quiet(() => PortView.draw(ctx)); PortView.close();
      /* rewritten for update168: the port's window is the station at the dock now — the dock's own sky paints it too */
      ok(calls.length >= 1, `the port's window shows the ruined Earth too (${calls.length})`);
    } finally { TownView.ruinedEarth = real; }
    const E = BaseScreen.ORRERY_PLANETS.find(p => p.key === 'earth');
    const blue = (hex) => { const n = parseInt(hex.slice(1), 16); return (n & 255) > ((n >> 16) & 255) + 30; };
    ok(!blue(E.c1) && !blue(E.c2) && !/60,170,90/.test(JSON.stringify(E.bands)), 'the Earth on the system map is ash and scorched land, not blue and green');
  }
})();

// ============================================================
section('340. The hangar of the mockup, upgrades inside each building, the workshop closed, a gun off with a double-click, skills on every card, 500 CC to start (154, jj 21.10)');
// ============================================================
(function testUpdate154() {
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };

  /* ── 1. A NEW GAME HAS 500 CC (the tests keep an empty purse) ── */
  {
    const real = loadEngine({ realStart: true });
    real.Save.reset(); real.Save.load();
    ok(real.Base.cc() === 500, `a new game starts with 500 CC (${real.Base.cc()})`);
    const test = loadEngine();
    test.Save.reset(); test.Save.load();
    ok(test.Base.cc() === 0, 'the unit tests still start from an empty purse');
  }

  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, DockArt, TownView, SHIP_CATALOG } = sb;
  const ctx = initRenderer(sb);
  const M = sb.Input.mouse;
  const frame = () => quiet(() => BaseScreen.draw(ctx));
  const key = (code) => { const real = sb.Input.isPressed; sb.Input.isPressed = (c) => c === code;
    try { return quiet(() => BaseScreen.update(0.05)); } finally { sb.Input.isPressed = real; frame(); } };
  const st = () => BaseScreen._state();
  const zone = (act, arg) => BaseScreen._zonesFor(act).find(z => arg === undefined || JSON.stringify(z.arg) === JSON.stringify(arg));
  Save.reset(); Save.load();
  quiet(() => BaseScreen.open());
  BaseScreen._act('building', 'HANGAR'); M.x = -50; M.y = -50; frame();

  /* ── 2. THE LAYOUT OF THE MOCKUP ── */
  const R = BaseScreen.hangarRects();
  const inside = (a, b) => a.x >= b.x && a.y >= b.y && a.x + a.w <= b.x + b.w && a.y + a.h <= b.y + b.h;
  const meet = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
  const ROOM = { x: 16, y: 62, w: 1248, h: 530 };
  ok([R.stage, R.card, R.strip].every(r => inside(r, ROOM)) && !meet(R.stage, R.card) && !meet(R.stage, R.strip) && !meet(R.card, R.strip),
     'the cradle, the card and the strip all inside the room, none on another');
  ok(inside(R.interior, R.band) && zone('interior') && inside(zone('interior'), R.band),
     'INTERIOR [I] sits in the title band over the cradle — not on the picture (jj: "wchodzi na okno i grafikę")');
  ok(R.berthTiles.map(t => t.kind).join() === 'ship,empty,lock', `berths: her, an empty cradle, the next one behind a lock (${R.berthTiles.map(t => t.kind)})`);
  ok(R.yardTiles.every(t => !Base.get().ships.some(e => e.key === t.key)) && R.yardTiles.length >= 3, 'the shipyard: hulls you do not have');
  ok([...R.berthTiles, ...R.yardTiles].every(t => inside(t, R.strip)), 'every tile inside the strip');

  /* ── 3. A HULL FOR SALE, LOOKED AT IN THE CRADLE ── */
  const want = R.yardTiles[0].key;
  const seen = [];
  const rD = DockArt.draw;
  DockArt.draw = function (c, r, sh) { seen.push(sh?.layoutKey); return rD.apply(this, arguments); };
  let text;
  try {
    ok(!!zone('yardView', want), 'a hull for sale is a click');
    BaseScreen._act('yardView', want);
    seen.length = 0;
    text = captureText(ctx, () => frame()).map(o => o.t);
    ok(st().yardPick === want && seen[0] === want, `the cradle shows her (${seen[0]})`);
    ok(text.includes('FOR SALE') && text.includes('FOR SALE — ON VIEW'), 'with the ticket that says she is not yours yet');
    ok(text.some(t => t === (SHIP_CATALOG[Base.get().ships[0].key].label.toUpperCase())) && text.includes('→'), 'and the card compares her with the hull you fly');
    ok(!zone('buyShip'), 'no CC: no BUY');
    Base.earn(2000); frame();
    ok(!!zone('buyShip', want), 'with the CC: BUY on the card');
    key('Escape');
    ok(st().yardPick === null && !st().town, 'ESC puts your own ship back in the cradle — and stays in the hangar');
    key('Escape');
    ok(st().town === true, 'ESC again: the town');
  } finally { DockArt.draw = rD; }

  /* ── 4. BUY: SHE GOES INTO THE NEXT BERTH AND INTO THE CRADLE ── */
  BaseScreen._act('building', 'HANGAR'); frame();
  BaseScreen._act('yardView', want); frame();
  const cc0 = Base.cc(), price = SHIP_CATALOG[want].cost;
  const z = zone('buyShip', want);
  BaseScreen._act('buyShip', z.arg); frame();
  ok(Base.get().ships.length === 2 && Base.get().ships[1].key === want && Base.cc() === cc0 - price, 'bought: in berth 2, paid');
  ok(st().shipIdx === 1 && st().yardPick === null, 'and she is the one in the cradle now');
  ok(!BaseScreen.hangarRects().yardTiles.some(t => t.key === want), 'off the shipyard');
  // no berth left: the BUY is not offered
  const other = BaseScreen.hangarRects().yardTiles[0].key;
  BaseScreen._act('yardView', other);
  text = captureText(ctx, () => frame()).map(o => o.t);
  ok(!zone('buyShip') && text.includes('NO FREE BERTH'), 'every berth taken: NO FREE BERTH, and nothing to press');
  BaseScreen._act('yardView', other);

  /* ── 5. THE LOCK: A BERTH, BOUGHT HERE, WITH A QUESTION (jj: "coś w stylu potwierdzenia") ── */
  frame();
  const slots0 = Base.shipSlots(), lock = BaseScreen.hangarRects().berthTiles.find(t => t.kind === 'lock');
  const lz = BaseScreen._zonesFor('upgradeAsk').find(q => q.arg === 'slot' && q.x === lock.x);
  ok(!!lz, 'the locked berth is a button');
  const cost = Base.upgradeCost('slot'), cc1 = Base.cc();
  BaseScreen._act('upgradeAsk', 'slot'); frame();
  ok(st().confirm?.act === 'upgrade' && Base.shipSlots() === slots0 && Base.cc() === cc1, 'it asks first — nothing bought yet');
  text = captureText(ctx, () => frame()).map(o => o.t);
  ok(text.includes('BUILD') && text.some(t => t.includes(`${cost} CC`)), 'BUILD, and what it costs');
  BaseScreen._act('confirmNo'); frame();
  ok(Base.shipSlots() === slots0 && Base.cc() === cc1, 'CANCEL: nothing changes');
  BaseScreen._act('upgradeAsk', 'slot'); BaseScreen._act('confirmYes'); frame();
  ok(Base.shipSlots() === slots0 + 1 && Base.cc() === cc1 - cost, `BUILD: one more berth, ${cost} CC`);
  ok(BaseScreen.hangarRects().berthTiles.some(t => t.kind === 'empty'), 'and an empty cradle stands in it');

  /* ── 6. THE CARD'S WAYS ON: ARMOURY, BARRACKS, SUPPLY ── */
  const links = BaseScreen._zonesFor('building').map(q => q.arg);
  ok(['ARMOURY', 'CREW', 'SUPPLY'].every(t => links.includes(t)), `the card leads on to the armoury, the barracks and the shelf (${links.join(',')})`);
  BaseScreen._act('building', 'ARMOURY');
  ok(st().tab === 'ARMOURY', 'and they go there');

  /* ── 7. EACH BUILDING BUILDS ITSELF UP, FROM ITS KEEPER'S BOX ── */
  Base.earn(5000);
  Object.entries(BaseScreen.ROOM_UPGRADES).forEach(([tab, kinds]) => {
    BaseScreen._act('building', tab); frame();
    const ups = BaseScreen.roomUpgradeRects(tab);
    const K = { x: 16, y: 604, w: 600, h: 104 };
    ok(kinds.every(k => BaseScreen._zonesFor('upgradeAsk').some(q => q.arg === k && inside(q, K))), `${tab}: ${kinds.join(' and ')} offered in the keeper's box`);
    ok(ups.every((u, i) => ups.every((v, j) => i === j || !meet(u, v))), `${tab}: the buttons side by side, not on each other`);
  });
  BaseScreen._act('building', 'CREW');
  const bunks0 = Base.barracksCap();
  BaseScreen._act('upgradeAsk', 'barracks'); BaseScreen._act('confirmYes');
  ok(Base.barracksCap() === bunks0 + 2, 'the barracks: +2 bunks, built from inside');
  BaseScreen._act('building', 'ARMOURY'); frame();
  ok(BaseScreen._zonesFor('upgradeAsk').length === 0, 'a building with nothing to build offers nothing');

  /* ── 8. THE WORKSHOP: PAINTED, CLOSED — rewritten for update161: it is DISPATCH now ── */
  BaseScreen._act('town'); frame();
  ok(!BaseScreen._zonesFor('building').some(q => q.arg === 'UPGRADES') && BaseScreen._zonesFor('building').some(q => q.arg === 'DISPATCH'), 'no workshop screen; a door to DISPATCH');
  BaseScreen._act('building', 'UPGRADES');
  ok(st().town === true, 'and the old screen cannot be opened by name');
  text = captureText(ctx, () => frame()).map(o => o.t);
  ok(text.includes('DISPATCH'), 'DISPATCH stands in the town, labelled');
  key('Digit6');
  ok(st().town === false && st().tab === 'DISPATCH', 'and 6 opens it');
  BaseScreen._act('town'); frame();

  /* ── 9. A GUN OFF WITH A DOUBLE-CLICK (jj: "x2 klik i odinstalujemy") ── */
  {
    const press = (x, y) => { M.x = x; M.y = y; M.leftPressed = true; quiet(() => BaseScreen.update(0.05)); M.leftPressed = false; frame(); };
    const release = (x, y) => { M.x = x; M.y = y; M.leftReleased = true; quiet(() => BaseScreen.update(0.05)); M.leftReleased = false; frame(); };
    const click = (x, y) => { press(x, y); release(x, y); };
    const wait = () => quiet(() => BaseScreen.update(0.5));
    BaseScreen._act('ship', 0);
    BaseScreen._act('loadout'); frame();
    const fitted = () => Base.shipWeapons(0).length;
    const n0 = fitted(), shelf0 = Base.armoury().length;
    ok(n0 >= 1, 'test setup: a gun on mount 1');
    const m0 = BaseScreen.loadoutRects().mounts[0];
    wait(); click(m0.x + 10, m0.y + 10); click(m0.x + 10, m0.y + 10);
    ok(fitted() === n0 - 1 && Base.armoury().length === shelf0 + 1 && !st().hand, 'double-click on its mount card: off, onto the shelf');
    wait(); click(m0.x + 10, m0.y + 10);
    ok(!st().hand, 'an empty mount gives nothing to the hand');
    // …and back on, then off the ROOF of the ship in the picture
    const R2 = BaseScreen.loadoutRects(), vi = Base.armoury().length - 1;
    wait(); click(R2.rack.x + 100, R2.rack.y + vi * R2.rack.pitch + 30); click(R2.rack.x + 100, R2.rack.y + vi * R2.rack.pitch + 30);
    ok(fitted() === n0, 'test setup: a double-click on the rack fits it again');
    const roof = BaseScreen.loadoutRoof();
    const mounts = roof?.ship?.weaponMounts?.() ?? [];
    const g0 = mounts[0];
    if (g0) {
      wait(); click(g0.x + g0.w / 2, g0.y + g0.h / 2); click(g0.x + g0.w / 2, g0.y + g0.h / 2);
      ok(fitted() === n0 - 1 && !st().hand, 'double-click on the gun on her roof: off as well');
    } else ok(false, 'test setup: the gun on her roof');
    BaseScreen._act('loClose');
  }

  /* ── 10. WHAT THEY CAN DO, ON EVERY CARD (jj: "wszędzie powinno być te info") ── */
  {
    ok(typeof Renderer.drawSkillStrip === 'function', 'one skill strip, in the renderer');
    const rec = { skills: { repair: { level: 1 }, weapons: { level: 3 }, engines: { level: 2 }, piloting: { level: 0 } } };
    ok(Renderer.skillStripKeys(rec).join() === 'weapons,engines,repair', 'every skill he has, best first, none he has not');
    ok(Renderer.skillStripKeys(rec, 30).length === 1, 'and only what fits');
    Base.hireRecruit(); Base.hireRecruit();
    Base.crew().forEach((c, i) => { c.skills = c.skills || {}; c.skills.repair = { level: 1 + i % 3, xp: 0 }; });
    const strips = [];
    const real = Renderer.drawSkillStrip;
    Renderer.drawSkillStrip = function (c, r) { strips.push(r?.id ?? r?.name); return real.apply(this, arguments); };
    try {
      BaseScreen._act('loadout'); frame();
      ok(Base.crew().every(c => strips.includes(c.id)), `the loadout: every man staying home shows his skills (${strips.length})`);
      strips.length = 0;
      BaseScreen._act('crew', Base.crew()[0].id); frame();
      ok(strips.includes(Base.crew()[0].id), 'and the man on deck too');
      strips.length = 0;
      BaseScreen._act('toDest'); frame();
      const D = BaseScreen.destRects();
      ok(D.crew.h >= 34 && strips.includes(Base.crew()[0].id), 'the contract screen: who flies, and what he can do');
      ok(D.crew.y >= D.cards[D.cards.length - 1].y + D.cards[D.cards.length - 1].h && D.crew.y + D.crew.h <= D.back.y - 54,
         'between the contracts and FLYING WITH, on neither');
    } finally { Renderer.drawSkillStrip = real; }
    BaseScreen._act('toLoadout'); BaseScreen._act('loClose');
  }
})();

// ============================================================
section('341. The barracks are sleeping pods (155, jj: "łóżka pionowe takie, jak mają na stacjach orbitalnych … twarze załogantów bez hełmów … ilość łóżek odzwierciedla faktyczną ilość miejsc")');
// ============================================================
(function testUpdate155() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, CrewArt } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.reset(); Save.load(); Base.earn(5000);
  for (let i = 0; i < 3; i++) Base.hireRecruit();
  quiet(() => BaseScreen.open());
  BaseScreen._act('building', 'CREW');
  const frame = () => quiet(() => BaseScreen.draw(ctx));
  frame();

  /* ── 1. A POD FOR EVERY BUNK, A MAN IN EVERY POD HE HOLDS, THE NEXT TWO DASHED ── */
  const R = BaseScreen.barracksRects(), cap = Base.barracksCap(), crew = Base.crew();
  ok(R.pods.filter(p => p.kind !== 'ghost').length === cap, `as many pods as bunks (${cap})`);
  ok(R.pods.filter(p => p.kind === 'man').map(p => p.id).join() === crew.map(c => c.id).join(), 'each man in his own pod, in barracks order');
  ok(R.pods.filter(p => p.kind === 'free').length === cap - crew.length, 'the rest stand free');
  ok(R.pods.filter(p => p.kind === 'ghost').length === 2, 'and the next two — the sergeant\'s upgrade — dashed');
  const text = captureText(ctx, () => frame()).map(o => o.t);
  ok(text.includes('+2 PODS') && text.filter(t => t === 'free pod').length === cap - crew.length, 'labelled: "+2 PODS", "free pod"');
  ok(R.modules.every(m => R.pods.filter(p => p.module === m.module).length <= 2), 'two pods to a module');
  const inside = (a, b) => a.x >= b.x && a.y >= b.y && a.x + a.w <= b.x + b.w && a.y + a.h <= b.y + b.h;
  ok(R.pods.every(p => inside(p, R.area)) && !R.pods.some((p, i) => R.pods.some((q, j) => j > i && p.x < q.x + q.w && q.x < p.x + p.w && p.y < q.y + q.h && q.y < p.y + p.h)),
     'all inside the room, none on another');

  /* ── 2. FACES BARE AND ASLEEP; SKILLS UNDER EVERY MAN ── */
  {
    const faces = [], strips = [];
    const rP = CrewArt.portraitCanvas, rS = Renderer.drawSkillStrip;
    CrewArt.portraitCanvas = function (rec, o) { faces.push({ id: rec?.id, o }); return rP.apply(this, arguments); };
    Renderer.drawSkillStrip = function (c, rec) { strips.push(rec?.id); return rS.apply(this, arguments); };
    try { frame(); } finally { CrewArt.portraitCanvas = rP; Renderer.drawSkillStrip = rS; }
    ok(crew.every(c => faces.some(f => f.id === c.id && f.o?.bare && f.o?.asleep)), 'every man\'s face in his pod: bare and asleep');
    // …and the painter really gets them (a fresh man, so nothing is cached)
    const painted = [], rPt = CrewArt.portrait;
    CrewArt.portrait = function (g, x, y, col, f) { painted.push(f); return rPt.apply(this, arguments); };
    try { CrewArt.portraitCanvas({ id: 'zz9', name: 'Fresh', race: 'terra', faceSeed: 424242 }, { bare: true, asleep: true }); }
    finally { CrewArt.portrait = rPt; }
    ok(painted.length === 1 && painted[0].bare === true && painted[0].asleep === true, 'and the painter is handed bare and asleep');
    ok(crew.every(c => strips.includes(c.id)), 'and his skills under him');
  }
  {
    // the painter: no helmet glass (no arc), the lids down over the eyes
    const rec = crew[0], f = CrewArt.faceOf(CrewArt.seedOf(rec), rec.race);
    const rec2 = (on) => { const calls = { arc: 0, rects: [] }; const g = { fillRect: (x, y, w, h) => calls.rects.push([x, y, w, h]), beginPath() {}, arc() { calls.arc++; }, fill() {}, stroke() {}, save() {}, restore() {}, set fillStyle(v) {}, set strokeStyle(v) {}, set lineWidth(v) {} };
      CrewArt.portrait(g, 0, 0, '#4db8ff', { ...f, ...on }, 48); return calls; };
    const helmet = rec2({}), bare = rec2({ bare: true }), asleep = rec2({ bare: true, asleep: true });
    ok(helmet.arc > 0 && bare.arc === 0, 'bare: no helmet glass');
    ok(helmet.rects.some(r => r[0] === 0 && r[1] === 0 && r[2] === 48) && !bare.rects.some(r => r[0] === 0 && r[1] === 0 && r[2] === 48), 'and no backdrop — he is in his pod, not on a card');
    const lids = (c) => c.rects.filter(r => r[0] === 17 && r[1] === 19).length;
    ok(lids(asleep) > lids(bare), 'asleep: the lids are down');
  }

  /* ── 3. CLICK: HIS FILE; DOUBLE-CLICK: HE FLIES / HE STAYS ── */
  const M = sb.Input.mouse;
  const click = (x, y) => { M.x = x; M.y = y; M.leftPressed = true; quiet(() => BaseScreen.update(0.05)); M.leftPressed = false; frame(); };
  const wait = () => quiet(() => BaseScreen.update(0.6));
  const p1 = R.pods.find(p => p.id === crew[1].id);
  if (BaseScreen._state().picked.includes(crew[1].id)) BaseScreen._act('crew', crew[1].id);   // a fresh hand is ticked to fly; start him home
  click(p1.x + 40, p1.y + 60);
  ok(BaseScreen.bunkSel() === crew[1].id && !BaseScreen._state().picked.includes(crew[1].id), 'one click: his file, nothing else');
  click(p1.x + 40, p1.y + 60);
  ok(BaseScreen._state().picked.includes(crew[1].id), 'a second click straight after: he flies');
  wait(); click(p1.x + 40, p1.y + 60);
  ok(BaseScreen._state().picked.includes(crew[1].id), 'a click later is just a click');
  click(p1.x + 40, p1.y + 60);
  ok(!BaseScreen._state().picked.includes(crew[1].id), 'and a double-click again: he stays home');
  const file = captureText(ctx, () => frame()).filter(o => o.x >= R.card.x).map(o => o.t);
  ok(file.includes(crew[1].name) && file.includes('TAKE HIM ALONG') && file.includes('RENAME'), 'his file: his card, TAKE HIM ALONG, RENAME');
  ok(BaseScreen._zonesFor('crew').some(z => z.arg === crew[1].id) && BaseScreen._zonesFor('rename').some(z => z.arg === crew[1].id), 'and they are his buttons');

  /* ── 4. A NEW HAND: INTO A FREE POD, HIS FILE OPEN ── */
  BaseScreen._act('hire'); frame();
  const fresh = Base.crew()[Base.crew().length - 1];
  ok(BaseScreen.bunkSel() === fresh.id && BaseScreen.barracksRects().pods.some(p => p.id === fresh.id), 'hired: he has a pod, and his file is the one open');

  /* ── 5. A BIG BARRACKS SCROLLS BY ROWS ── */
  Base.get().barracksLvl = 7; frame();
  const big = BaseScreen.barracksRects();
  ok(big.rows === 3 && big.scrollMax === 1, `${Base.barracksCap()} pods + 2: three rows, one a scroll away`);
  BaseScreen._act('scrollCrew', 9); frame();
  ok(BaseScreen._state().crewScroll === 1 && BaseScreen.barracksRects().pods.some(p => p.kind === 'ghost'), 'it scrolls to the last row, and no further');
})();

// ============================================================
section('342. The mess is the commanders\' office and the pen (156, jj: "kapitan powinien być za biurkiem … biurko bardziej futurystyczne … office na księżycu, duże okno z tyłu i ruch gwiazd, czasem spadnie kometa")');
// ============================================================
(function testUpdate156() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, CrewArt, TownView } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.reset(); Save.load(); Base.earn(9000);
  for (let i = 0; i < 4; i++) Base.hireRecruit();
  const c1 = Base.promote(Base.crew()[0].id).commander;
  Base.buyUpgrade('mess');
  const c2 = Base.promote(Base.crew()[0].id).commander;
  c2.away = true;
  Base.adoptCat();
  quiet(() => BaseScreen.open());
  BaseScreen._act('building', 'MESS');
  const frame = () => quiet(() => BaseScreen.draw(ctx));
  frame();

  /* ── 1. A DESK FOR EVERY CHAIR, A BASKET FOR EVERY PEN, THE NEXT ONE DASHED ── */
  const R = BaseScreen.messRects();
  ok(R.desks.length === Base.messCap() + 1 && R.desks.filter(d => d.ghost).length === 1, `a desk for each of the ${Base.messCap()} chairs, and the next one dashed`);
  ok(R.baskets.length === Base.petCap() + 1 && R.baskets.filter(d => d.ghost).length === 1, `a basket for each of the ${Base.petCap()} pens, and the next one dashed`);
  const inside = (a, b) => a.x >= b.x && a.y >= b.y && a.x + a.w <= b.x + b.w && a.y + a.h <= b.y + b.h;
  const apart = (list) => !list.some((p, i) => list.some((q, j) => j > i && p.x < q.x + q.w && q.x < p.x + p.w && p.y < q.y + q.h && q.y < p.y + p.h));
  ok(R.desks.every(d => inside(d, R.office)) && apart(R.desks) && inside(R.window, R.office), 'the desks and the window inside the office, none on another');
  ok(R.baskets.every(d => inside(d, R.pen)) && apart(R.baskets) && inside(R.adopt, R.pen) && apart([...R.baskets, R.adopt]), 'the baskets and ADOPT inside the pen, none on another');
  ok(apart([R.office, R.pen, R.card]), 'office, pen and the candidates\' card apart');

  /* ── 2. HE SITS BEHIND HIS DESK; THE ONE AWAY HAS AN EMPTY CHAIR ── */
  {
    const calls = [], realFrames = CrewArt.frames;
    const rDI = ctx.drawImage, rQ = ctx.quadraticCurveTo;
    CrewArt.frames = function (seed) { calls.push({ k: 'frames', seed }); return realFrames.apply(this, arguments); };
    ctx.drawImage = function () { calls.push({ k: 'img' }); return rDI?.apply(this, arguments); };
    ctx.quadraticCurveTo = function () { calls.push({ k: 'desk' }); return rQ?.apply(this, arguments); };
    try { frame(); } finally { CrewArt.frames = realFrames; ctx.drawImage = rDI; ctx.quadraticCurveTo = rQ; }
    const seats = calls.filter(c => c.k === 'frames');
    ok(seats.length === 1 && seats[0].seed === CrewArt.seedOf(c1), 'the commander at home is drawn at his desk; the one on contract is not');
    const fi = calls.findIndex(c => c.k === 'frames'), di = calls.findIndex((c, i) => i > fi && c.k === 'desk');
    ok(fi >= 0 && di > fi, 'him first, then the desk — so it hides him from the waist down');
    const text = captureText(ctx, () => frame()).map(o => o.t);
    ok(text.some(t => t.includes(c2.name)) && text.some(t => /ON CONTRACT/.test(t)), 'the one away: his name, ON CONTRACT');
  }

  /* ── 3. WHAT YOU CAN DO AT A DESK, AND IN THE PEN ── */
  ok(BaseScreen._zonesFor('pickCommander').map(z => z.arg).join() === String(c1.id), 'FLY HIM for the one at home only');
  ok(BaseScreen._zonesFor('levelUp').concat(BaseScreen._zonesFor('cpu')).some(z => z.arg === c1.id), 'LEVEL UP or TABLETS at his desk');
  ok([c1.id, c2.id].every(id => BaseScreen._zonesFor('dossier').some(z => z.arg === id)), 'every commander\'s file one click away');
  const dz = BaseScreen._zonesFor('dossier').find(z => z.arg === c1.id), fz = BaseScreen._zonesFor('pickCommander')[0];
  BaseScreen._set({ commanderId: null });
  sb.Input.mouse.x = fz.x + 4; sb.Input.mouse.y = fz.y + 4; sb.Input.mouse.leftPressed = true;
  quiet(() => BaseScreen.update(0.016)); sb.Input.mouse.leftPressed = false;
  ok(BaseScreen._state().commanderId === c1.id && !BaseScreen._state().dossierId, 'a click on FLY HIM flies him — the desk under it does not open his file');
  ok(!!dz, 'the desk itself is the file');
  const pz = BaseScreen._zonesFor('pickPet');
  ok(pz.length === Base.pets().length, 'every cat in its basket is a click');
  frame();
  ok(!BaseScreen._zonesFor('adoptCat').length === (Base.pets().length >= Base.petCap() || Base.cc() < 60), 'ADOPT while a basket is free');

  /* ── 4. THE WINDOW: THE RUINED EARTH, THE STARS DRIFT, A COMET NOW AND THEN ── */
  {
    const earths = [], realE = TownView.ruinedEarth;
    TownView.ruinedEarth = function () { earths.push(1); return realE.apply(this, arguments); };
    try { frame(); } finally { TownView.ruinedEarth = realE; }
    ok(earths.length === 1, 'the ruined Earth hangs in the window (update153)');
    const streak = (t) => { BaseScreen._set({ blink: t }); const lines = []; const rL = ctx.lineTo;
      ctx.lineTo = function (x, y) { lines.push([x, y]); return rL?.apply(this, arguments); };
      try { frame(); } finally { ctx.lineTo = rL; } return lines; };
    const W = R.window, inW = ([x, y]) => x >= W.x && x <= W.x + W.w + 130 && y >= W.y - 50 && y <= W.y + W.h;
    const withComet = streak(1.0).filter(inW).length, without = streak(4.0).filter(inW).length;
    ok(withComet > without, `a comet crosses the glass now and then (${withComet} vs ${without} strokes)`);
  }

  /* ── 5. READY FOR THE CHAIR: HIS SKILLS, AND WHAT PROMOTION BUYS ── */
  {
    const strips = [], rS = Renderer.drawSkillStrip;
    Renderer.drawSkillStrip = function (c, rec) { strips.push(rec?.id); return rS.apply(this, arguments); };
    try { frame(); } finally { Renderer.drawSkillStrip = rS; }
    const pool = Base.promotable();
    ok(pool.slice(0, 3).every(c => strips.includes(c.id)), 'every candidate shows his skills');
    ok(BaseScreen._zonesFor('promote').length === 0 && captureText(ctx, () => frame()).some(o => /NO CHAIR/.test(o.t)), 'every chair taken: NO CHAIR, nothing to press');
  }
})();

// ============================================================
section('343. The armoury: every gun in its own crate (157, jj: "armory podobny schemat — skrzynie, a w skrzyniach broń")');
// ============================================================
(function testUpdate157() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.reset(); Save.load(); Base.earn(2000);
  ['laser_burst', 'ion_basic', 'missile_basic'].forEach(k => Base.storeWeapon(k));
  quiet(() => BaseScreen.open());
  BaseScreen._act('building', 'ARMOURY');
  const frame = () => quiet(() => BaseScreen.draw(ctx));
  frame();
  const rack = () => Base.armoury();

  /* ── 1. A CRATE FOR EVERY GUN, AND THE EMPTY ONE WAITING ── */
  const R = BaseScreen.armouryRects();
  ok(R.crates.length === rack().length + 1 && R.crates.slice(0, -1).every((c, i) => c.key === rack()[i]) && !R.crates[R.crates.length - 1].key,
     `a crate for each of the ${rack().length} guns, and an empty one for the next`);
  const inside = (a, b) => a.x >= b.x && a.y >= b.y && a.x + a.w <= b.x + b.w && a.y + a.h <= b.y + b.h;
  const apart = (l) => !l.some((p, i) => l.some((q, j) => j > i && p.x < q.x + q.w && q.x < p.x + p.w && p.y < q.y + q.h && q.y < p.y + p.h));
  ok(R.crates.every(c => inside(c, R.area)) && apart(R.crates), 'on the shelves, none on another');
  ok(R.mounts.length === Base.shipSlotCount(0) && R.mounts.every(m => inside(m, R.card)) && apart([R.gun, R.fit, R.sell, ...R.mounts]), 'her mounts under the gun\'s card, nothing on anything');
  {
    const icons = [], real = Renderer.drawWeaponIcon;
    Renderer.drawWeaponIcon = function (c, key) { icons.push(key); return real.apply(this, arguments); };
    try { frame(); } finally { Renderer.drawWeaponIcon = real; }
    ok(rack().every(k => icons.includes(k)), 'the gun in each crate is drawn');
  }

  /* ── 2. A CLICK PUTS ITS GUN ON THE CARD; THE CARD'S BUTTONS ARE FOR THAT GUN ── */
  BaseScreen._act('crate', 2); frame();
  ok(BaseScreen.crateSel() === 2, 'the crate picked');
  {
    const cards = [], real = Renderer.drawWeaponCard;
    Renderer.drawWeaponCard = function (c, key) { cards.push(key); return real.apply(this, arguments); };
    try { frame(); } finally { Renderer.drawWeaponCard = real; }
    ok(cards.length === 1 && cards[0] === rack()[2], 'its gun is the one weapon card on the right');
  }
  ok(BaseScreen._zonesFor('sellGun').map(z => z.arg).join() === '2', 'SELL is for it');
  ok(BaseScreen._zonesFor('fit').length === 0 && captureText(ctx, () => frame()).some(o => o.t === 'NO FREE MOUNT'), 'every mount taken: NO FREE MOUNT, nothing to press');

  /* ── 3. UNFIT: INTO A CRATE; DOUBLE-CLICK A CRATE: ONTO THE FREE MOUNT ── */
  const n0 = rack().length;
  ok(BaseScreen._zonesFor('unfit').map(z => z.arg).join() === '0', 'UNFIT on the fitted mount');
  BaseScreen._act('unfit', 0); frame();
  ok(rack().length === n0 + 1 && Base.shipWeapons(0).length === 0, 'unfitted: one more crate on the rack');
  ok(BaseScreen._zonesFor('fit').map(z => z.arg).join() === '2', 'a free mount: FIT for the gun on the card');
  const M = sb.Input.mouse, c2 = BaseScreen.armouryRects().crates.find(c => c.i === 1), want = rack()[1];
  const click = () => { M.x = c2.x + 40; M.y = c2.y + 70; M.leftPressed = true; quiet(() => BaseScreen.update(0.05)); M.leftPressed = false; frame(); };
  quiet(() => BaseScreen.update(0.6));
  click();
  ok(BaseScreen.crateSel() === 1 && Base.shipWeapons(0).length === 0, 'one click: only picked');
  click();
  ok(Base.shipWeapons(0).some(f => f.defKey === want) && rack().length === n0, 'a double-click: onto the free mount, off the rack');

  /* ── 4. SELL ASKS FIRST ── */
  BaseScreen._act('crate', 0); frame();
  const sold = rack()[0];
  BaseScreen._act('sellGun', BaseScreen._zonesFor('sellGun')[0].arg);
  ok(BaseScreen._state().confirm?.act === 'doSellGun' && rack().length === n0, 'SELL asks first');
  BaseScreen._act('confirmYes'); frame();
  ok(rack().length === n0 - 1, `and yes sells it (${sold})`);
  ok(BaseScreen.crateSel() < Math.max(1, rack().length), 'the pick stays on the rack');
})();

// ============================================================
section('344. The Moon Gate wakes (158, jj: "menu gate do ulepszenia, lepsza grafika, fajne efekty … dodaj ikony w ringu: znaki zodiaku i oryginalne znaki planet")');
// ============================================================
(function testUpdate158() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.reset(); Save.load();
  quiet(() => BaseScreen.open());
  BaseScreen._act('building', 'GATE');
  const frame = () => captureText(ctx, () => quiet(() => BaseScreen.draw(ctx)));
  const G = BaseScreen.gateRects();

  /* ── 1. TWENTY-FOUR SIGNS: THE ZODIAC AND THE PLANETS, TAKING TURNS ── */
  const S = BaseScreen.GATE_SIGNS, base = (c) => c.replace('︎', '');
  const ZOD = ['♈', '♉', '♊', '♋', '♌', '♍', '♎', '♏', '♐', '♑', '♒', '♓'];
  const PLN = ['☿', '♀', '♁', '♂', '♃', '♄', '♅', '♆', '♇'];
  ok(S.length === G.ring.seg && S.every(c => c.endsWith('︎')), `a sign on each of the ${G.ring.seg} segments, as text, not an emoji`);
  ok(ZOD.every(z => S.some(c => base(c) === z)) && S.filter((_, i) => i % 2 === 0).every(c => ZOD.includes(base(c))), 'the twelve of the zodiac, every other segment');
  ok(PLN.every(p => S.some(c => base(c) === p)), 'and the old signs of the planets, Mercury to Pluto, between them');
  const t0 = frame();
  const signs = t0.filter(o => S.includes(o.t));
  ok(signs.length === G.ring.seg, `all ${G.ring.seg} drawn round the ring (${signs.length})`);
  ok(signs.every(o => Math.abs(Math.hypot(o.x - G.ring.cx, o.y - 5 - G.ring.cy) - G.ring.r) < 3), 'each on the ring itself');

  /* ── 2. THE RING LIGHTS AS THE SHELF FILLS ── */
  const share = () => Number((frame().find(o => /^\d+%$/.test(o.t)) || { t: '-1%' }).t.slice(0, -1));
  ok(share() === 0, 'an empty shelf: 0%');
  const g = Base.warehouseGrid(); for (let i = 0; i < 40; i++) g.add('he3_ore'); Base.commitWarehouse(g);
  ok(share() === 20, `forty He-3 on the shelf: one part of five — 20% (${share()})`);
  const t1 = frame();
  ok(t1.some(o => /^\d+\/40$/.test(o.t) && Number(o.t.split('/')[0]) >= 40) && t1.some(o => o.t === 'COMPONENTS — from the warehouse shelf'), 'its socket reads full');

  /* ── 3. STILL NO BUILD, THE DESTINATIONS, THE ONE LINE ── */
  ok(t1.some(o => /DESTINATIONS/.test(o.t)) && t1.some(o => /LUNA/.test(o.t)), 'where it leads');
  ok(!BaseScreen._zonesFor('buildGate').length && t1.some(o => /Construction is not available in this version/.test(o.t)), 'no BUILD — only the line that says why');
  const inside = (a, b) => a.x >= b.x && a.y >= b.y && a.x + a.w <= b.x + b.w && a.y + a.h <= b.y + b.h;
  ok(G.parts.every(p => inside(p, G.area)) && inside(G.note, G.area) && inside(G.dest, G.area), 'everything inside the room');
  ok(G.ring.cx + G.ring.r + 14 < G.dest.x && G.dest.x + G.dest.w < G.parts[0].x, 'the ring, the destinations and the sockets side by side');
})();

// ============================================================
section('345. The warehouse is a rack at the hold\'s size, and a forklift brings what you buy (159, jj: "wielkość itemów musi być zachowana … musimy mieć standard; wszędzie ikony rzeczy, przy kupowaniu też … animacja z podjeżdżaniem fajny pomysł")');
// ============================================================
(function testUpdate159() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, LootScreen, CargoItem } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.reset(); Save.load(); Base.earn(3000);
  {
    const g = Base.warehouseGrid(); g.items = [];
    g.addStack('he2_med', 14); g.addStack('missile_rack', 8); g.addStack('ration_pack', 7);
    g.autoPlace(new CargoItem('plating')); g.autoPlace(new CargoItem('gun_crate', 'laser_burst'));
    Base.commitWarehouse(g);
  }
  quiet(() => BaseScreen.open());
  BaseScreen._act('building', 'SUPPLY');
  const drawn = [];
  const frame = () => {
    drawn.length = 0;
    const real = LootScreen.drawCargoItem;
    LootScreen.drawCargoItem = function (c, it, x, y) { drawn.push({ key: it.defKey, x, y, qty: it.qty }); return real.apply(this, arguments); };
    try { return captureText(ctx, () => quiet(() => BaseScreen.draw(ctx))); } finally { LootScreen.drawCargoItem = real; }
  };
  let txt = frame();
  const R = () => BaseScreen.supplyRects();
  const inside = (a, b) => a.x >= b.x && a.y >= b.y && a.x + a.w <= b.x + b.w && a.y + a.h <= b.y + b.h;

  /* ── 1. ONE STANDARD: THE HOLD'S CELL, THE HOLD'S PAINTER ── */
  const K = R().rack, g0 = Base.warehouseGrid();
  ok(K.cell === LootScreen.CELL && K.pitch === LootScreen.CELL + 4, `the rack is at the hold's size (${K.cell} + 4)`);
  ok(K.cols === g0.cols && K.rows === g0.rows && K.w === g0.cols * K.pitch - 4, `bay for bay, level for level the shelf (${K.cols}×${K.rows})`);
  ok(g0.items.every(it => drawn.some(d => d.key === it.defKey && d.x === K.x + it.x * K.pitch && d.y === K.y + it.y * K.pitch)),
     'every thing on the shelf is drawn by the hold\'s painter, in its own place');
  const picks = BaseScreen._zonesFor('shelfPick');
  ok(picks.length === g0.items.length && picks.every(z => inside(z, R().area)), 'each one can be clicked, inside the hall');
  ok(inside(K, R().area) && K.x + K.w < R().door.x && inside(R().door, R().area), 'the rack and the DELIVERIES door in the hall, apart');

  /* ── 2. THE SHOP SHOWS THE THING ITSELF ── */
  const C = R().card, inCard = drawn.filter(d => d.x >= C.x);
  ok(Object.values(BaseScreen.SUPPLY_KEYS).every(k => inCard.some(d => d.key === k)), 'each stock line shows its own container on the counter');
  ok(R().lines.every(L => inside(L, C) && inside(L.one, L) && inside(L.five, L)), 'four tiles on the counter, ×1 and ×5 in each');
  ok(BaseScreen._zonesFor('warehouse').length === 1 && inside(BaseScreen._zonesFor('warehouse')[0], C), 'PACK THE HOLD: the one way into the packing screen');

  /* ── 3. A CLICK PUTS IT ON THE COUNTER ── */
  const tank = g0.items.find(it => it.defKey === 'he2_med'), place = `${tank.x},${tank.y}`;
  BaseScreen._act('shelfPick', place); txt = frame();
  ok(BaseScreen.shelfSel() === place && txt.some(o => o.t === 'He2 Tank') && txt.some(o => o.t === `${tank.qty} of 15 in this one`), 'the tank on the counter, with what is in it');
  const tanks = g0.items.filter(it => it.defKey === 'he2_med').length;
  ok(drawn.filter(d => d.key === 'he2_med').length === tanks + 2, 'drawn there by the same painter (the rack, the He2 tile, and the counter)');
  BaseScreen._act('shelfPick', place); frame();
  ok(BaseScreen.shelfSel() === null, 'a second click puts it back');

  /* ── 4. BUYING: ONTO THE RACK, NEVER INTO A HOLD; THE FORKLIFT BRINGS IT ── */
  const hold0 = JSON.stringify(Base.packedHold?.() ?? null), n0 = Base.supply().fuel;
  BaseScreen._act('buy', ['fuel', 5]); frame();
  const runs = BaseScreen.liftRuns();
  ok(Base.supply().fuel === n0 + 5, 'bought: five more He2 on the shelf, at once');
  ok(JSON.stringify(Base.packedHold?.() ?? null) === hold0, 'and nothing went into the hold');
  ok(runs.length >= 1 && runs.every(r => r.key === 'he2_med'), `the forklift has the run(s) to make (${runs.length})`);
  const fresh = runs.find(r => r.fresh), [fx, fy] = fresh ? fresh.id.split(',').map(Number) : [-1, -1];
  ok(!!fresh && !drawn.some(d => d.key === 'he2_med' && d.x === K.x + fx * K.pitch && d.y === K.y + fy * K.pitch),
     'a new tank is not on the rack while it is still on the forks');
  ok(txt.length >= 0 && frame().some(o => /^delivering — \d+ runs? to go$/.test(o.t)), 'the hall says it is delivering');
  quiet(() => { for (let i = 0; i < 60 * runs.length; i++) BaseScreen.update(BaseScreen.LIFT.RUN / 50); });
  txt = frame();
  ok(BaseScreen.liftRuns().length === 0 && drawn.some(d => d.key === 'he2_med' && d.x === K.x + fx * K.pitch && d.y === K.y + fy * K.pitch),
     'run done: the tank stands in its place');
  for (let i = 0; i < 4; i++) BaseScreen._act('buy', ['food', 5]);
  BaseScreen._act('buy', ['missiles', 5]); BaseScreen._act('buy', ['scan', 5]); BaseScreen._act('buy', ['fuel', 5]);
  ok(BaseScreen.liftRuns().length <= BaseScreen.LIFT.MAX, `a queue, not a traffic jam (${BaseScreen.liftRuns().length} ≤ ${BaseScreen.LIFT.MAX})`);

  /* ── 5. THE NEXT BAY: ITS PRICE, A QUESTION, ONE MORE COLUMN ── */
  frame();
  const ghost = BaseScreen._zonesFor('upgradeAsk').find(z => z.arg === 'warehouse' && inside(z, R().area));
  ok(!!ghost && Math.abs(ghost.x - R().ghost.x) < 1, 'the dashed bay beside the rack can be pressed');
  BaseScreen._act('upgradeAsk', 'warehouse');
  ok(BaseScreen._state().confirm?.act === 'upgrade' && BaseScreen._state().confirm?.arg === 'warehouse', 'and it asks first');
  const cols0 = Base.warehouseGrid().cols;
  BaseScreen._act('confirmYes'); frame();
  ok(Base.warehouseGrid().cols === cols0 + 1 && R().rack.cols === cols0 + 1, `built: the rack is a bay longer (${cols0 + 1})`);
  Save.spendScrapBank(Base.cc()); frame();
  ok(!BaseScreen._zonesFor('upgradeAsk').some(z => inside(z, R().area)), 'poor: the dashed bay is only a picture');

  /* ── 6. A LONG RACK SCROLLS, A BAY AT A TIME ── */
  Base.get().warehouseLvl = 14; frame();
  const L = R().rack;
  ok(L.vis < L.cols && L.x + L.w < R().door.x && BaseScreen._zonesFor('rackScroll').length === 1, `more bays than the hall: ${L.vis} in view of ${L.cols}, ▶ to the rest`);
  BaseScreen._act('rackScroll', 1); frame();
  ok(R().rack.first === 1 && BaseScreen._zonesFor('rackScroll').length === 2, 'one bay on; now ◀ too');
  BaseScreen._act('rackScroll', 99); frame();
  ok(R().rack.first === L.cols - L.vis, 'and never past the last');
})();

// ============================================================
section('346. The marshal\'s office, and the hunt: a bounty taken, its chip in flight, its man first on the map (160, jj: "HUNT HIM … to jest potwierdzenie, że bierzesz kontrakt na niego … ikonka, że go ścigasz … można wziąć 2 max kontrakty, można je też zrezygnować")');
// ============================================================
(function testUpdate160() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, SectorMap, MapNode, CrewArt, Input } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.reset(); Save.load(); Base.earn(2000);
  while (Save.wanted().length < 3) Save.addWanted(2);
  const [a, b2, c] = Save.wanted();

  /* ── 1. THE REGISTER: TWO AT MOST, GIVEN UP, CLOSED BY THE DOCK ── */
  ok(Save.HUNT_MAX === 2 && Save.hunts().length === 0, 'no hunts on a new board; two at most');
  ok(Save.huntWanted(a.id) && Save.huntWanted(b2.id), 'two taken');
  ok(!Save.huntWanted(c.id) && !Save.huntWanted(a.id) && !Save.huntWanted('nobody'), 'a third, the same man twice, or a man not on the board: refused');
  ok(Save.hunts().map(w => w.id).join() === [a.id, b2.id].join() && Save.isHunted(a.id) && !Save.isHunted(c.id), 'the hunts are read off the board');
  Save.load();
  ok(Save.isHunted(a.id) && Save.isHunted(b2.id), 'and kept in the save');
  ok(Save.dropHunt(b2.id) && !Save.isHunted(b2.id) && Save.wantedById(b2.id), 'given up: no hunt, the poster stays');
  Save.huntWanted(b2.id);
  Save.deliverWanted(b2.id, 100);
  ok(!Save.isHunted(b2.id) && Save.hunts().length === 1, 'handed in: the hunt is over with him');

  /* ── 2. THE OFFICE: THE BOARD, THE FILE, THE QUESTION, THE LOADOUT ── */
  quiet(() => BaseScreen.open());
  BaseScreen._act('building', 'WANTED');
  const frame = () => captureText(ctx, () => quiet(() => BaseScreen.draw(ctx)));
  let t = frame();
  const R = BaseScreen.wantedRects(), inside = (p, q) => p.x >= q.x && p.y >= q.y && p.x + p.w <= q.x + q.w && p.y + p.h <= q.y + q.h;
  ok(R.posters.every(p => inside(p, R.board)) && inside(R.board, R.area) && R.cells.every(cl => inside(cl, R.area) && (cl.x + cl.w <= R.board.x || cl.x >= R.board.x + R.board.w)),
     'the board between the two cells, the posters on it');
  ok(BaseScreen._zonesFor('poster').length === Save.wanted().length, 'every poster can be clicked');
  {
    const sw = Save.wanted()[0]; Save.markSighted(sw.id, 'luna');
    const tt = captureText(ctx, () => Renderer.drawWantedPoster(ctx, sw, 0, 0));
    ok(tt.some(o => /^seen: /.test(o.t)) && !tt.some(o => o.t === 'no sighting yet'), 'a man who has been seen: his poster says where');
  }
  const ci = Save.wanted().findIndex(w => w.id === c.id);
  BaseScreen._act('poster', ci); t = frame();
  ok(BaseScreen.posterSel() === ci && t.some(o => o.t === c.name) && t.some(o => o.t === `${c.bounty} CC alive`), 'a click: his file on the right');
  ok(BaseScreen._zonesFor('huntAsk').map(z => z.arg).join() === c.id && !BaseScreen._zonesFor('dropAsk').length, 'HUNT HIM for him');
  BaseScreen._act('huntAsk', c.id);
  ok(BaseScreen._state().confirm?.act === 'hunt' && !Save.isHunted(c.id), 'it asks first');
  BaseScreen._act('confirmYes');
  ok(Save.isHunted(c.id) && BaseScreen._state().screen === 'loadout' && BaseScreen._state().mission === c.mission,
     'yes: hunted, the loadout open, his contract picked');
  BaseScreen._set({ screen: null }); BaseScreen._act('building', 'WANTED'); BaseScreen._act('poster', ci); t = frame();
  ok(BaseScreen._zonesFor('flyHunt').length === 1 && BaseScreen._zonesFor('dropAsk').length === 1 && t.some(o => o.t === 'HIS FILE · YOU HUNT HIM'), 'his file: FLY and GIVE UP');
  ok(t.filter(o => o.t === 'HUNTED').length === Save.hunts().length, 'his poster says HUNTED');
  // two running: no third
  Save.addWanted(2); t = frame();
  const free = Save.wanted().findIndex(w => !Save.isHunted(w.id));
  BaseScreen._act('poster', free); t = frame();
  ok(!BaseScreen._zonesFor('huntAsk').length && t.some(o => o.t === '2 HUNTS ALREADY'), 'two running: no third');
  BaseScreen._act('poster', ci);
  BaseScreen._act('dropAsk', c.id);
  ok(BaseScreen._state().confirm?.act === 'dropHunt' && Save.isHunted(c.id), 'GIVE UP asks first');
  BaseScreen._act('confirmYes');
  ok(!Save.isHunted(c.id) && Save.wantedById(c.id), 'and yes gives it up — he stays on the board');
  BaseScreen._set({ mission: 'courier' });
  BaseScreen._act('flyHunt', c.id);
  ok(BaseScreen._state().mission === c.mission && BaseScreen._state().screen === 'loadout', 'FLY: his contract, the loadout');
  BaseScreen._set({ screen: null }); BaseScreen._act('building', 'WANTED'); BaseScreen._act('poster', ci);

  {
    const keepW = Save.wanted().map(w => ({ ...w }));
    Save.wanted().forEach(w => Save.deliverWanted(w.id, 0));
    const te = frame();
    ok(te.some(o => o.t === 'THE BOARD IS EMPTY') && !BaseScreen._zonesFor('poster').length, 'an empty board says so in the file');
    keepW.forEach(w => { const n = Save.addWanted(1); if (n) Object.assign(n, w); });
  }
  /* ── 3. THE CELLS: WHOEVER WAS HANDED OVER, UNTIL THE NEXT CONTRACT ── */
  Base.returnFromRun({ shipEntry: { key: 'scout', data: { prisoners: [{ name: 'Held Man', bounty: 50, wantedId: null }] } }, crew: [], cc: 0 });
  t = frame();
  ok(Base.holding().map(p => p.name).join() === 'Held Man' && t.some(o => o.t === 'Held Man'), 'the man handed over sits in a cell, his name under it');
  ok(t.some(o => /handed over last time/.test(o.t)), 'and the room says why');

  /* ── 4. ON THE MAP: HE COMES FIRST, AND WEARS THE CROSSHAIR ── */
  Save.startRun();
  if (!Save.getRun().mission) Save.getRun().mission = 'patrol';
  const mission = Save.getRun().mission;
  Save.wanted().forEach(w => { w.mission = mission ?? w.mission; });
  Save.hunts().forEach(w => Save.dropHunt(w.id));
  const target = Save.wanted()[Save.wanted().length - 1];
  Save.huntWanted(target.id);
  let seated = 0, his = 0;
  for (let seed = 0; seed < 40; seed++) { const n = new SectorMap(2, seed, 1, 3, true).wantedNode(); if (n) { seated++; if (n.wantedId === target.id) his++; } }
  ok(seated > 0 && his === seated, `every sector that seats a poster seats the man you hunt (${his} of ${seated})`);
  Save.dropHunt(target.id);
  let others = 0;
  for (let seed = 0; seed < 40; seed++) { const n = new SectorMap(2, seed, 1, 3, true).wantedNode(); if (n && n.wantedId !== target.id) others++; }
  ok(others > 0, 'given up: the others turn up again');
  Save.huntWanted(target.id);
  {
    let seed = 0, map = null; while (seed < 80 && !(map = new SectorMap(2, seed, 1, 3, true)).wantedNode()) seed++;
    const node = map.wantedNode(), marks = [];
    node.locked = false;                                   // a node you can reach shows who is on it
    const keep = MapNode.drawCrosshair;
    MapNode.drawCrosshair = function () { marks.push(1); return keep.apply(this, arguments); };
    let txt; try { txt = captureText(ctx, () => node.draw(ctx, null, 'known')); } finally { MapNode.drawCrosshair = keep; }
    ok(marks.length === 1 && txt.some(o => o.t === `HUNTED · ${target.bounty} CC`), 'his node: the crosshair, HUNTED and his price');
    map.currentId = node.id;
    ok(Renderer.huntStatus(target, map).text === 'HE IS HERE', 'standing on his node: HE IS HERE');
  }

  /* ── 5. THE CHIP AND ITS POSTER ── */
  {
    const seen = [], keep = CrewArt.portraitCanvas;
    CrewArt.portraitCanvas = function (rec, o) { if (o?.bare) seen.push(rec?.name); return keep.apply(this, arguments); };
    try { quiet(() => Renderer.drawHUD({ playerShip: new sb.Ship('scout', true, 0, 0) })); } finally { CrewArt.portraitCanvas = keep; }
    ok(Save.hunts().length > 0 && Save.hunts().every(w => seen.includes(w.name)), `the HUD draws a chip with his face for every hunt (${seen.join(', ')})`);
  }
  const chips = Renderer.huntChipRects();
  ok(chips.length === Save.hunts().length && chips.every(r => r.x + r.size < 470 && r.y >= 0), 'a chip for every hunt, left of the resource plate');
  Input.mouse.x = 5; Input.mouse.y = 5;
  ok(Renderer.drawHuntTip(ctx, null) === null, 'no pointer on a chip: no poster');
  Input.mouse.x = chips[0].x + 4; Input.mouse.y = chips[0].y + 4;
  let id = null; t = captureText(ctx, () => { id = Renderer.drawHuntTip(ctx, null); });
  ok(id === chips[0].w.id && t.some(o => o.t === 'HUNTED') && t.some(o => o.t === `${chips[0].w.bounty} CC ALIVE`), 'the pointer on a chip: his poster');
  const other = Object.keys(sb.MISSIONS).find(k => k !== Save.getRun().mission && !sb.MISSIONS[k].noWanted);
  if (other) { chips[0].w.mission = other; ok(/^not here/.test(Renderer.huntStatus(chips[0].w, null).text), 'a hunt on another contract: "not here"'); }
  Input.mouse.x = Input.mouse.y = -99;
})();

// ============================================================
section('347. DISPATCH: jobs instead of side objectives — taken at the base, their sealed crates aboard, signed for at the port, fined when they fail (161, jj: "okno celów — powinniśmy je brać jak misje do wyboru … trzeba pobrać … grzywna powinna być, taka misja to nie żarty")');
// ============================================================
(function testUpdate161() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, CargoGrid, CargoItem, Station, SectorMap, Input } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.reset(); Save.load(); Base.earn(1000);
  const J = (o) => ({ id: `j${Math.random()}`, kind: 'cargo', client: 'Test Co.', crates: 1, port: 'any', sector: 1, pay: 100, fine: 50, taken: true, ...o });

  /* ── 1. THE BOARD ── */
  const offers = Base.jobs();
  ok(offers.length === Base.JOB_OFFERS && Base.JOB_MAX === 3, `${Base.JOB_OFFERS} offers on the board, up to 3 taken`);
  /* rewritten for update162: passengers are on the board too */
  /* rewritten for update163: and transports of convicts, for the prison */
  ok(offers.every(j => j.sector >= 1 && j.sector <= 2 && j.pay > 0 && !j.taken &&
       (j.kind === 'cargo' ? j.crates >= 1 && j.crates <= 3 && j.fine > 0 && j.fine < j.pay
        : j.kind === 'vip' ? j.crates === 0 && j.fine === j.pay
        : j.kind === 'convict' && j.crates === 0 && j.convicts.length >= 1 && j.convicts.length <= 2 && j.fine > 0 && j.fine < j.pay)),
     'each a job: sealed cargo (1-3 crates, a smaller fine), a passenger (no crates, the fine is the whole pay) or prisoners (1-2 convicts); sector 1-2');
  ok(offers.every(j => (j.kind === 'convict' ? ['prison'] : ['any', 'general', 'military', 'science', 'outpost']).includes(j.port)),
     'to any port, or one kind of port — a transport to the prison');
  ok(Base.takeJob(offers[0].id).ok && Base.jobs()[0].taken && !Base.takeJob(offers[0].id).ok, 'taken once; not twice');
  ok(Base.dropJob(offers[0].id).ok && !Base.jobs()[0].taken, 'dropped, no fine');
  Base.get().jobs = [J({ taken: false }), J({ taken: false }), J({ taken: false }), J({ taken: false })];
  Base.get().jobs.slice(0, 3).forEach(j => Base.takeJob(j.id));
  ok(!Base.takeJob(Base.get().jobs[3].id).ok, 'a fourth: refused');

  /* ── 2. THE OFFICE ── */
  Base.get().jobs = [J({ crates: 2, taken: true }), J({ taken: false, port: 'science', sector: 2 }), J({ taken: false })];
  quiet(() => BaseScreen.open());
  BaseScreen._act('building', 'DISPATCH');
  const drawn = [];
  const frame = () => {
    drawn.length = 0;
    const real = sb.LootScreen.drawCargoItem;
    sb.LootScreen.drawCargoItem = function (c, it, x, y) { drawn.push({ key: it.defKey, x, y }); return real.apply(this, arguments); };
    try { return captureText(ctx, () => quiet(() => BaseScreen.draw(ctx))); } finally { sb.LootScreen.drawCargoItem = real; }
  };
  let t = frame();
  const R = BaseScreen.dispatchRects(), inside = (a, b) => a.x >= b.x && a.y >= b.y && a.x + a.w <= b.x + b.w && a.y + a.h <= b.y + b.h;
  ok(BaseScreen._state().tab === 'DISPATCH' && R.cards.every(c => inside(c, R.area)) && inside(R.bay, R.area), 'the board and the loading bay in the office');
  ok(BaseScreen._zonesFor('jobTake').length === 2 && BaseScreen._zonesFor('jobDrop').length >= 1, 'TAKE on the open ones, DROP on the taken');
  ok(drawn.filter(d => d.key === 'sealed_crate').length >= 3 + 2, 'every card shows its crate, and the bay the two going aboard — the hold\'s one painter');
  ok(t.some(o => o.t === 'a science post') && t.some(o => o.t === 'in sector 2'), 'where it goes, in words');
  BaseScreen._act('jobPick', 1); t = frame();
  ok(BaseScreen.jobSel() === 1 && t.some(o => /reach/.test(o.t)) && t.some(o => /too short/.test(o.t)) && t.some(o => o.t === 'TAKE THIS JOB'), 'the sheet: where, will it fit (who reaches it, who is too short), TAKE');
  BaseScreen._act('jobTake', Base.get().jobs[1].id); frame();
  ok(Base.get().jobs[1].taken, 'TAKE takes it');

  /* ── 3. LAUNCH: THE CRATES GO ABOARD; A FARTHER JOB WAITS; NO ROOM REFUSES ── */
  Base.get().jobs = [J({ crates: 2, sector: 1 }), J({ sector: 2 }), J({ taken: false })];
  {
    const hold = new CargoGrid(4, 2);
    const res = quiet(() => Base.launch({ shipIndex: 0, crewIds: [], mission: 'courier', hold }));
    const crates = res.ok ? CargoGrid.deserialise(res.hold).items.filter(it => it.defKey === 'sealed_crate') : [];
    ok(res.ok && res.jobs.length === 1 && res.jobs[0].state === 'aboard' && crates.length === 2 && crates.every(c => c.meta.jobId === res.jobs[0].id),
       'courier (1 sector): the sector-1 job aboard, its two crates in the hold, tagged');
    ok(Base.get().jobs.some(j => j.taken && j.sector === 2) && !Base.get().jobs.some(j => j.id === res.jobs[0].id), 'the sector-2 job waits on the board, taken');
    Base.storeShip?.({ key: 'scout', data: null }, true);
  }
  {
    Base.get().jobs = [J({ crates: 3 })];
    const hold = new CargoGrid(2, 2), before = hold.items.length;
    const res = quiet(() => Base.launch({ shipIndex: 0, crewIds: [], mission: 'courier', hold }));
    ok(!res.ok && /No room in the hold/.test(res.message) && hold.items.length === before && Base.get().jobs[0].taken, 'no room: refused, nothing left in the hold, the job still taken');
  }

  /* ── 4. THE PORT SIGNS FOR IT ── */
  Save.startRun();
  const ship = new sb.Ship('scout', true, 0, 0);
  const jobA = J({ id: 'ja', crates: 2, port: 'science', sector: 1, pay: 120, state: 'aboard' });
  const jobB = J({ id: 'jb', crates: 1, port: 'any', sector: 2, state: 'aboard' });
  const jobC = J({ id: 'jc', crates: 2, port: 'any', sector: 1, pay: 80, state: 'aboard' });
  Save.updateRun({ jobs: [jobA, jobB, jobC], scrap: 10 });
  ship.cargo.items = [];
  [['ja', 2], ['jb', 1], ['jc', 1]].forEach(([id, n]) => { for (let k = 0; k < n; k++) ship.cargo.autoPlace(new CargoItem('sealed_crate', { jobId: id })); });
  const mil = new Station(1, 1, { type: 'military' }), sci = new Station(1, 2, { type: 'science' });
  ok(mil.type === 'military' && sci.type === 'science', 'a port is the kind the map rolled');
  let out = Base.deliverJobs(mil, ship, 1);
  ok(out.length === 1 && out[0].job.id === 'jc' && !out[0].ok && Save.getRun().jobs.find(j => j.id === 'jc').state === 'failed',
     'a fleet yard signs for the any-port job — one crate short: failed');
  ok(Save.getRun().jobs.find(j => j.id === 'ja').state === 'aboard', 'the science job: not here');
  out = Base.deliverJobs(sci, ship, 1);
  ok(out.length === 1 && out[0].ok && Save.getRun().scrap === 130 && !ship.cargo.items.some(it => it.meta?.jobId === 'ja'), 'the science post: delivered, paid into the purse, crates gone');
  ok(Base.deliverJobs(sci, ship, 1).length === 0 && Save.getRun().jobs.find(j => j.id === 'jb').state === 'aboard', 'nothing twice; the sector-2 job rides on');
  ok(Base.deliverJobs(new Station(2, 3, { blackMarket: true, owner: 'X' }), ship, 2).length === 0, 'a black market signs for nothing');

  /* ── 5. SETTLED AT THE END: THE FINE, THE KARMA, THE CRATES BACK ── */
  const cap = { id: 'c1', name: 'Cap', karma: 50 };
  const cc0 = Base.cc(), ids0 = Base.get().jobs.map(j => j.id);
  const rep = Base.settleJobs(ship, cap);
  ok(rep.length === 2 && rep.every(r => r.job.state === 'failed'), 'the failed one and the undelivered one: both failed');
  ok(Base.cc() === cc0 - rep.reduce((n, r) => n + r.fine, 0) && rep.every(r => r.fine === r.job.fine), 'the fines out of the CC');
  ok(cap.karma === 50 + 2 * Base.JOB_KARMA, `the commander takes the karma (${cap.karma})`);
  ok(!ship.cargo.items.some(it => it.def.tag === 'sealed'), 'and the crates go back to their owners');
  ok(Base.get().jobs.length === Base.JOB_OFFERS && Base.get().jobs.some(j => !ids0.includes(j.id)), 'new offers on the board');
  Save.spendScrapBank(Base.cc()); Save.updateRun({ jobs: [J({ state: 'aboard', fine: 500 })] });
  ok(Base.settleJobs(null, null)[0].fine === 0 && Base.cc() === 0, 'a broke commander pays what there is');

  /* ── 6. A SEAL IS NOT FOR SALE; A PORT HAS A KIND ON THE MAP ── */
  const crate = new CargoItem('sealed_crate', { jobId: 'x' });
  ok(['general', 'military', 'science', 'outpost'].every(p => !!crate.sellRefusal(p)) && crate.w === 2 && crate.h === 1, 'a sealed crate: 2×1, no port buys it');
  const m1 = new SectorMap(1, 7, 1, 3, true), m2 = new SectorMap(1, 7, 1, 3, true);
  const ports = m1.nodes.filter(n => n.type === 'store');
  ok(ports.length > 0 && ports.every(n => ['general', 'military', 'science', 'outpost'].includes(n.portType)), 'every port on the map has a kind');
  ok(ports.map(n => n.portType).join() === m2.nodes.filter(n => n.type === 'store').map(n => n.portType).join(), 'the same seed, the same kinds');
  ok(ports.every(n => n.label === sb.PORT_KIND_LABEL[n.portType]), 'and the map says which');

  /* ── 7. THE LOADOUT SAYS WHAT WILL HAPPEN ── */
  Base.earn(500);
  Base.get().jobs = [J({ crates: 3, sector: 1 }), J({ sector: 2 })];
  quiet(() => BaseScreen.open()); BaseScreen._set({ mission: 'courier', screen: 'loadout' });
  t = captureText(ctx, () => quiet(() => BaseScreen.draw(ctx)));
  ok(t.some(o => /^1 job waits at DISPATCH/.test(o.t)), 'a job the run does not reach: it waits');
  const checks = BaseScreen.briefingChecks().map(c => `${c.level}:${c.text}`);
  ok(checks.some(c => /^ok:1 job aboard — 6 cells kept for the crates/.test(c)), 'the crates: room kept');
  BaseScreen._state().hold.items = []; { const h = BaseScreen._state().hold; while (h.usedCells() < h.capacity - 2) { if (!h.autoPlace(new CargoItem('ration_pack'))) break; } }
  ok(BaseScreen.briefingChecks().some(c => c.level === 'bad' && /No room for the sealed crates — 6 cells needed/.test(c.text)), 'a full hold: no room, said before LAUNCH');

  /* ── 8. THE JOBS LINE, AND ITS TIP ── */
  Save.updateRun({ jobs: [J({ id: 'jt', crates: 3, port: 'science', sector: 2, state: 'aboard' })] });
  t = captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: ship })));
  ok(t.some(o => o.t === 'JOBS') && t.some(o => o.t === '▣×3 → science post · s2'), 'where OBJ was: JOBS and a chip for each');
  const chip = Renderer.jobChipRects()[0];
  Input.mouse.x = chip.x + 3; Input.mouse.y = chip.y + 3;
  let id = null; t = captureText(ctx, () => { id = Renderer.drawJobTip(ctx); });
  ok(id === 'jt' && t.some(o => /science post, sector 2/.test(o.t)) && t.some(o => /^pays \d+ CC on delivery · fine \d+ CC/.test(o.t)), 'the pointer on it: the job in full');
  Input.mouse.x = Input.mouse.y = -99;
})();

// ============================================================
section('348. A passenger: on the bridge, one of ours to every hazard and nobody\'s to order; delivered alive or the dearest failed job (162, jj: "transport pasażera — jakiś kapitan albo ktoś ważny, siedzi na mostku, bierna postać, ale ma HP, głód … pasażer je normalnie")');
// ============================================================
(function testUpdate162() {
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, CrewMember, Station, UI, Input, Game } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const { player, enemy } = makeCombat(sb);
  const T = Game.__test;
  Base.earn(1000);
  const job = { id: 'jv', kind: 'vip', client: 'Dr. Ilse Marrow', race: 'aquarius', crates: 0, port: 'science', sector: 1, pay: 210, fine: 210, state: 'aboard' };
  Save.updateRun({ jobs: [{ ...job }], scrap: 0 });

  /* ── 1. HE BOARDS: ON THE BRIDGE, A PASSENGER ── */
  const man = quiet(() => T._boardPassenger(job));
  const helm = player.getSystem('piloting').roomId;
  ok(man && player.crew.includes(man) && man.isPassenger && man.jobId === 'jv' && man.isPlayer && man.roomId === helm && man.homeRoomId === helm,
     'he comes aboard on the bridge, one of ours, a passenger tagged with his job');
  const back = CrewMember.deserialise(JSON.parse(JSON.stringify(man.serialise())));
  ok(back.isPassenger && back.jobId === 'jv', 'and a save keeps who he is');

  /* ── 2. NOBODY'S TO ORDER ── */
  UI.deselectCrew(); UI.selectCrew(man);
  ok(UI.getSelectedCrewAll().length === 0, 'he cannot be selected');
  UI.selectCrewGroup(player.crew.filter(c => c.isPlayer));
  ok(UI.getSelectedCrewAll().length > 0 && !UI.getSelectedCrewAll().includes(man), 'nor swept up with the crew');
  ok(!Renderer.crewRoster({ playerShip: player }).includes(man), 'he is not on the crew list');
  quiet(() => player.assignStations());
  ok(man.homeRoomId === helm && !player.crewOperating(helm).includes(man), 'no post, and standing on the bridge does not make him its pilot');
  const graves = Save.getGraveyard().length;
  Save.addToGraveyard(man);
  ok(Save.getGraveyard().length === graves, 'and he is not ours to bury');

  /* ── 3. ONE OF OURS TO EVERY HAZARD, AND HE DOES NO WORK ── */
  player.fires.start(helm, man.x, man.y);
  man.task = 'idle'; man.assignTask?.('idle');
  for (let i = 0; i < 5; i++) quiet(() => man.update(0.1, player));
  ok(man.task !== 'fire', 'a fire in his room: he does not fight it');
  player.fires.clear();
  ok(typeof man.hungerPerSec === 'function' && man.hungerPerSec() > 0, 'he gets hungry, like the crew');
  const boarder = enemy.crew.find(c => c.alive);
  enemy.crew = enemy.crew.filter(c => c !== boarder);
  boarder.x = man.x + 6; boarder.y = man.y; boarder.roomId = man.roomId; boarder.inRoom = true; man.inRoom = true;
  player.addCrew(boarder, true);
  const hp0 = man.hp, bHp0 = boarder.hp;
  for (let i = 0; i < 60; i++) { quiet(() => { man.update(0.1, player); boarder.update(0.1, player); }); }
  ok(man.hp < hp0, `a boarder's blade reaches him (${Math.round(hp0)} → ${Math.round(man.hp)})`);
  ok(boarder.hp === bHp0, 'and he swings at nobody');
  player.crew = player.crew.filter(c => c !== boarder);
  ok(T._menuActsFor({ ...man, dead: true, isPassenger: true, isPrisoner: false, frozen: false }).join() === 'eject', 'dead, he is ejected — not bagged for our hill');
  ok(T._playerCrewAliveCount() === player.crew.filter(c => c.isPlayer && c.alive && !c.isPassenger).length, 'he does not keep the ship crewed');

  /* ── 4. DELIVERED ALIVE ── */
  man.hp = Math.max(1, man.hp);
  let out = Base.deliverJobs(new Station(1, 1, { type: 'military' }), player, 1);
  ok(out.length === 0 && player.crew.includes(man), 'the wrong kind of port: he stays aboard');
  out = Base.deliverJobs(new Station(1, 2, { type: 'science' }), player, 1);
  ok(out.length === 1 && out[0].ok && !player.crew.includes(man) && Save.getRun().scrap === 210, 'the science post: he steps off, 210 CC');

  /* ── 5. DEAD: THE JOB FAILS AT ONCE; SETTLED DEARER ── */
  const job2 = { ...job, id: 'jw', client: 'Envoy Teodor Kask' };
  Save.updateRun({ jobs: [{ ...job2 }] });
  const man2 = quiet(() => T._boardPassenger(job2));
  ok(Base.passengerDeaths(player).length === 0, 'alive: nothing to report');
  man2.hp = 0; man2.dead = true;
  const died = Base.passengerDeaths(player);
  ok(died.length === 1 && Save.getRun().jobs[0].state === 'failed' && Save.getRun().jobs[0].why === 'he died aboard', 'dead: the job fails at once');
  ok(Base.passengerDeaths(player).length === 0, 'and only once');
  const cap = { id: 'cv', name: 'Cap', karma: 50 }, cc0 = Base.cc();
  const rep = Base.settleJobs(player, cap);
  ok(rep.length === 1 && Base.cc() === cc0 - 210 && cap.karma === 50 + Base.VIP_KARMA && Base.VIP_KARMA < Base.JOB_KARMA, `settled: the whole pay as the fine, and dearer karma (${Base.VIP_KARMA})`);
  ok(!player.crew.some(c => c.isPassenger), 'and he is off the ship');
  const job3 = { ...job, id: 'jx', client: 'Prof. Aldo Brin' };
  Save.updateRun({ jobs: [{ ...job3 }] });
  quiet(() => T._boardPassenger(job3));
  Base.settleJobs(player, null);
  ok(!player.crew.some(c => c.isPassenger), 'a passenger alive at the end of the contract leaves too — his job failed');

  /* ── 6. THE LINE, THE TIP, THE OFFICE, THE LOADOUT ── */
  Save.updateRun({ jobs: [{ ...job, id: 'jy', state: 'aboard' }] });
  const man4 = quiet(() => T._boardPassenger({ ...job, id: 'jy' })); man4.hp = 40;
  let t = captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: player })));
  ok(t.some(o => o.t === '☺ Marrow → science post · s1 · 40hp'), 'his chip: name, where, HP');
  const chip = Renderer.jobChipRects()[0]; Input.mouse.x = chip.x + 2; Input.mouse.y = chip.y + 2;
  t = captureText(ctx, () => Renderer.drawJobTip(ctx));
  ok(t.some(o => o.t === 'PASSENGER · Dr. Ilse Marrow') && t.some(o => /HP 40\/\d+ · fed \d+%/.test(o.t)), 'his tip: HP and how fed he is');
  Input.mouse.x = Input.mouse.y = -99;
  Base.get().jobs = [{ ...job, id: 'jz', taken: true, sector: 1 }];
  quiet(() => BaseScreen.open()); BaseScreen._act('building', 'DISPATCH');
  const faces = [], crates = [], keep = sb.CrewArt.portraitCanvas, keepItem = sb.LootScreen.drawCargoItem;
  sb.CrewArt.portraitCanvas = function (rec, o) { faces.push(`${rec?.name}|${!!o?.bare}`); return keep.apply(this, arguments); };
  sb.LootScreen.drawCargoItem = function (c, it) { crates.push(it.defKey); return keepItem.apply(this, arguments); };
  try { t = captureText(ctx, () => quiet(() => BaseScreen.draw(ctx))); } finally { sb.CrewArt.portraitCanvas = keep; sb.LootScreen.drawCargoItem = keepItem; }
  ok(t.some(o => o.t === 'PASSENGER') && t.some(o => o.t === 'a seat on the bridge') && t.some(o => o.t === 'eats with the crew · has HP') && faces.filter(f => f === 'Dr. Ilse Marrow|true').length >= 2,
     'DISPATCH: his card and the gangway, his bare face on both');
  ok(!crates.includes('sealed_crate'), 'and no crate for a man');
  BaseScreen._set({ screen: 'loadout', mission: 'courier' });
  BaseScreen._state().hold.items = BaseScreen._state().hold.items.filter(it => it.def.kind !== 'food');
  ok(BaseScreen.briefingChecks().some(c => c.level === 'warn' && /^Dr\. Ilse Marrow eats with the crew — no rations packed/.test(c.text)), 'LOADOUT: no rations, and he eats');
})();

// ============================================================
section('349. The prison: a node of its own, built as a hull (the standard for structures); convicts carried frozen and signed in, captives paid and questioned, a warden who sells the map; the way to every job in the sector on the map (163, jj: "wiezienie na podstawie modulow statkow, ta sama wielkosc plus winda … jak dostajemy misje czy kontrakt to mamy odslonieta droge")');
// ============================================================
(function testUpdate163() {
  const fs = require('fs'), path = require('path'), ROOT = path.join(__dirname, '..');
  const sb = loadEngine();
  const { Save, Base, BaseScreen, Renderer, Ship, SectorMap, CrewArt, Prison, PrisonView, Input, Game, NodeView, HULL_GRID } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const T = Game.__test;

  /* ── 1. THE BLOCK IS A HULL, IN A BOOK OF ITS OWN ── */
  ok(sb.STRUCTURE_LAYOUTS?.prison_block && !sb.SHIP_LAYOUTS.prison_block && sb.layoutOf('prison_block') === sb.STRUCTURE_LAYOUTS.prison_block,
     'the prison is a structure: built by the hull code, kept out of every list of ships');
  const pb = new Ship('prison_block', true, 0, 0);
  ok(pb.rooms.length === 15 && pb.rooms.every(r => r.w === HULL_GRID.MODULE_W && r.h === HULL_GRID.MODULE_H) && (pb.elevators?.shafts?.length ?? 0) >= 1 && pb.armor === 2,
     'fifteen modules of the ship size, a lift, plating — a man in a cell is the size of a man aboard');
  const art = k => pb.rooms.filter(r => r.art === k).length;
  ok(art('cell') === 6 && ['security', 'warden', 'intake', 'decon', 'mess'].every(k => art(k) === 1),
     'its own rooms: six cells, security, the warden, intake, decon, the mess');
  ok(pb.getSystem('engines') && pb.getRoomById('p_gravity').type === 'engines' && pb.getSystem('carbonite')?.roomId === 'p_freezer'
     && pb.getSystem('oxygen') && pb.getSystem('weapons'),
     'the gravity generator is the engines module, the freezer the carbonite bay; air and a gun');
  const png = f => { const b = fs.readFileSync(f); return { w: b.readUInt32BE(16), h: b.readUInt32BE(20) }; };
  const man = JSON.parse(fs.readFileSync(path.join(ROOT, 'art/manifest.json'), 'utf8'));
  const artBad = [];
  ['security', 'warden', 'intake', 'decon', 'mess', 'cell'].forEach(k => ['', '_terra', '_phoenix', '_aquarius', '_pegasus'].forEach(y => {
    const n = `room_${k}${y}`, f = path.join(ROOT, 'art', n + '.png');
    if (!fs.existsSync(f)) return artBad.push(n + ' missing');
    const s = png(f); if (s.w !== 100 || s.h !== 50) artBad.push(`${n} ${s.w}x${s.h}`);
    if (!man.sprites.includes(n)) artBad.push(n + ' not listed');
  }));
  ok(artBad.length === 0, `every block room painted like a module (100x50, each yard), listed (${artBad.slice(0, 3).join('; ') || 'all'})`);
  const painter = fs.readFileSync(path.join(ROOT, 'tools/room_painter.js'), 'utf8');
  ok(/security:\s*'#/.test(painter) && /EMBLEMS = \{/.test(painter) && /lamps\(g, S\)/.test(painter),
     'painted by the module painter: an emblem each, the air lamps\' housing in every one, no names on the walls');
  const cellRoom = pb.getRoomById('p_cell1'), shown = [];
  const keepArt = sb.moduleArt;
  try {
    sb.moduleArt = (t) => { shown.push(t); return null; };
    quiet(() => pb._drawEmptyRoom(ctx, cellRoom));
  } finally { sb.moduleArt = keepArt; }
  ok(shown[0] === 'cell', 'an empty room with a kind asks for the picture of its kind');

  /* ── 2. INMATES ARE BARE ── */
  const rec = (bare) => {
    const fills = [];
    const g = { set fillStyle(v) { this._f = v; }, get fillStyle() { return this._f; }, fillRect() { fills.push(this._f); },
                save() {}, restore() {}, beginPath() {}, arc() {}, stroke() {}, fill() {}, strokeStyle: '', lineWidth: 1 };
    CrewArt.paint(g, 2, 2, '#e07020', { ...CrewArt.faceOf(77, 'terra'), bare }, 'idle', 0);
    CrewArt.paint(g, 2, 2, '#e07020', { ...CrewArt.faceOf(77, 'terra'), bare }, 'walk', 0);
    CrewArt.paint(g, 2, 2, '#e07020', { ...CrewArt.faceOf(77, 'terra'), bare }, 'operate', 0);
    return fills;
  };
  ok(rec(false).includes('rgb(182,192,208)') && !rec(true).includes('rgb(182,192,208)'), 'a man on duty carries his bottles; an inmate has none, and no glass');
  const a1 = CrewArt.anim('idle', { name: 'X', race: 'terra', bare: true, suitColor: () => '#e07020' });
  const a2 = CrewArt.anim('idle', { name: 'X', race: 'terra', suitColor: () => '#e07020' });
  ok(a1.frames[0] !== a2.frames[0], 'and his frames are his own, not the helmeted ones out of the cache');

  /* ── 3. THE NODE ON THE MAP ── */
  Save.load(); Save.startRun();
  let some = 0, bad = 0;
  for (let i = 0; i < 60; i++) {
    const m = new SectorMap(1, 5000 + i, null, 2, true), p = m.prisonNode();
    if (p) { some++; if (p.col <= 1 || p.col >= SectorMap.GRID.cols - 1 || p.wantedId) bad++; }
    if (m.nodes.some(n => n.type === 'store' && !n.portType)) bad++;
  }
  ok(some >= 6 && some <= 36 && bad === 0, `about a third of the sectors hold a prison (${some}/60), never on the first hop or the last column; every port has a kind`);
  Save.updateRun({ jobs: [{ id: 'jT', kind: 'convict', sector: 1, state: 'aboard', port: 'prison', convicts: [{ name: 'A' }] }] });
  let all = 0;
  for (let i = 0; i < 60; i++) if (new SectorMap(1, 5000 + i, null, 2, true).prisonNode()) all++;
  ok(all === 60, `and always where a transport is going (${all}/60)`);
  const m1 = new SectorMap(1, 4242, null, 2, true), m2 = new SectorMap(1, 4242, null, 2, true);
  ok(m1.prisonNode().id === m2.prisonNode().id, 'the same seed, the same prison — a reload does not move it');
  ok(sb.NODE_TYPES.prison.weight === 0 && NodeView.blurb(m1.prisonNode(), m1).join(' ').length > 10, 'never rolled, only seated; the node card says what it is');

  /* ── 4. THE WAY THERE ── */
  const p1 = m1.prisonNode();
  ok(m1.visibilityOf(p1) !== 'known', 'test setup: the prison is not known yet');
  const added = m1.revealRoute([p1.id]);
  ok(m1.visibilityOf(p1) === 'known' && added.length >= 2, `the lane to it is on the map (${added.length} nodes)`);
  let id = p1.id, chain = 0;
  while (id && added.includes(id)) { const n = m1.getNode(id); if (n.col === 0) break; id = n.prev.find(x => added.includes(x)); chain++; }
  ok(id && m1.getNode(id).col === 0, 'all the way from a start of the sector');
  const back = new SectorMap(1, 4242, null, 2, true);
  back.restoreProgress(JSON.parse(JSON.stringify(m1.serialiseProgress())));
  ok(back.visibilityOf(back.getNode(p1.id)) === 'known', 'and a save keeps it known');

  /* ── 5. THE JOB AT DISPATCH ── */
  const realR = sb.Math.random;
  /* rewritten for update165: convicts are offered only to a hangar with a carbonite bay */
  const slabHull = (() => { const s2 = new Ship('frigate', true, 0, 0); s2.addModuleAt('carbonite', 'r_crew1'); return { key: 'frigate', data: JSON.parse(JSON.stringify(s2.serialise())) }; })();
  Base.get().ships.push(slabHull);
  try { sb.Math.random = () => 0.1; Base.get().jobs = null; Base.jobs(); } finally { sb.Math.random = realR; Base.get().ships.pop(); }
  const cj = Base.jobs();
  ok(cj.length === Base.JOB_OFFERS && cj.every(j => j.kind === 'convict' && j.port === 'prison' && j.crates === 0 && j.convicts.length >= 1 && j.convicts.length <= 2
       && j.convicts.every(c => c.name && c.race) && j.fine > 0 && j.fine < j.pay),
     'a PRISONERS job: one or two named convicts, for the prison, no crates, a fine under the pay');
  const j0 = cj[0];
  ok(Base.jobWhere(j0) === `the prison, sector ${j0.sector}` && Base.convictsOf(j0) === j0.convicts.length && Base.jobKarma(j0) === Base.CONVICT_KARMA && Base.CONVICT_KARMA < 0,
     'delivered to "the prison"; karma of its own');
  ok(!Base.jobFitsPort(j0, { type: 'general' }, j0.sector) && Base.jobFitsPort(j0, { isPrison: true }, j0.sector) && !Base.jobFitsPort({ ...j0, port: 'any', kind: 'cargo' }, { isPrison: true }, j0.sector),
     'a port does not sign for convicts, the prison signs for nothing else');
  const scout = { key: 'scout', data: null };
  const withBay = (() => { const s = new Ship('frigate', true, 0, 0); s.addModuleAt('carbonite', 'r_crew1'); s.getSystem('carbonite').level = 2; return { key: 'frigate', data: JSON.parse(JSON.stringify(s.serialise())) }; })();
  ok(Base.slabsOf(scout) === 0 && Base.slabsOf(withBay) === 2, 'the slabs on a hull: its carbonite bay\'s levels');
  Base.get().jobs.forEach(j => { j.taken = false; }); Base.takeJob(j0.id);
  const r0 = quiet(() => Base.launch({ shipIndex: 0, mission: 'patrol', hold: new sb.CargoGrid(12, 12) }));
  ok(!r0.ok && /carbonite slab/.test(r0.message), `a hull without the slabs is refused at the launch: "${r0.message}"`);

  /* ── 6. ABOARD: INTO THE SLABS ── */
  const { player } = makeCombat(sb);
  player.addModuleAt('carbonite', 'r_crew1'); player.getSystem('carbonite').level = 2;
  const job = { id: 'jc', kind: 'convict', client: 'Luna Penal Authority', convicts: [{ name: 'Kerr Duval', race: 'terra' }, { name: 'Lio Varga', race: 'phoenix' }], crates: 0, port: 'prison', sector: 1, pay: 220, fine: 165, state: 'aboard' };
  Save.updateRun({ jobs: [{ ...job }], scrap: 0, sector: 1 });
  player.prisoners = [];
  const n = quiet(() => T._boardConvicts(job));
  ok(n === 2 && player.prisoners.filter(p => p.jobId === 'jc').length === 2 && player.prisoners.every(p => p.race && p.bounty === 0),
     'both convicts in the slabs, tagged with the job');
  ok(player.getSystem('carbonite').power >= 1, 'and the bay lit for them, as far as the reactor has spare');
  T.playerShip = player;
  let t = captureText(ctx, () => quiet(() => Renderer.drawHUD({ playerShip: player })));
  ok(t.some(o => o.t === '⛓×2/2 → prison · s1'), 'the JOBS chip: men aboard, of how many, where to');

  /* ── 7. THE INTAKE ── */
  while (Save.wanted().length < 1) Save.addWanted(1);
  const w = Save.wanted()[0];
  player.prisoners.push({ id: w.id, name: w.name, bounty: w.bounty, wantedId: w.id, escapeT: 0 });
  let rows = Base.intakeRows(player, 1);
  ok(rows.length === 3 && rows.filter(r => r.kind === 'job' && r.ok).length === 2 && rows.find(r => r.kind === 'wanted')?.pay === w.bounty,
     'the intake signs for the transport and for the man off the board, at his bounty');
  ok(Base.intakeRows(player, 2).filter(r => r.kind === 'job').every(r => !r.ok && /sector 1/.test(r.why)), 'another sector\'s prison will not take them');
  let h = Base.handOver(player, 'cv_jc_0', 1);
  ok(h.ok && h.pay === 0 && /1 more/.test(h.message) && Save.getRun().jobs[0].state === 'aboard', 'one of two signed in: no pay yet');
  h = Base.handOver(player, 'cv_jc_1', 1);
  ok(h.ok && h.pay === 220 && Save.getRun().jobs[0].state === 'delivered' && Save.getRun().scrap === 220, 'the last one in: the job is paid into the purse');
  const posters = Save.wanted().length;
  h = Base.handOver(player, w.id, 1);
  ok(h.ok && h.pay === w.bounty && Save.getRun().scrap === 220 + w.bounty && Save.wanted().length === posters - 1 && !player.prisoners.length,
     'the wanted man: the full bounty here and now, and his poster comes down');

  /* ── 8. ONE GETS AWAY ── */
  Save.updateRun({ jobs: [{ ...job, id: 'je' }], scrap: 0 });
  player.prisoners = [];
  quiet(() => T._boardConvicts({ ...job, id: 'je' }));
  const runner = new sb.CrewMember({ name: 'Kerr Duval', race: 'terra', isPlayer: false, isPrisoner: true });
  runner.jobId = 'je'; runner.bounty = 0;
  player.prisoners = player.prisoners.filter(p => p.name !== 'Kerr Duval');
  player.addCrew(runner, true);
  const before = Save.wanted().length;
  quiet(() => player._prisonerGone(runner));
  ok(Save.getRun().jobs[0].state === 'failed' && /got away/.test(Save.getRun().jobs[0].why) && (Save.wanted().length === before + 1 || before >= 12),
     'out of the airlock: the transport has failed, and he is on the WANTED board');
  const cc0 = Base.cc();
  const rep = quiet(() => Base.settleJobs(player, null));
  ok(rep.length === 1 && Base.cc() === cc0 - Math.min(cc0, 165) && !player.prisoners.some(p => p.jobId), 'at the end: the fine, and the court takes back the one still in a slab');
  player.prisoners = []; quiet(() => player.setPower('carbonite', 2));
  const caught2 = new sb.CrewMember({ name: 'Lio Varga', race: 'phoenix', isPlayer: false, isPrisoner: true });
  caught2.jobId = 'je'; player.addCrew(caught2, true);
  const rc = quiet(() => player.returnToCell(caught2));
  ok(rc.ok && player.prisoners.some(p => p.jobId === 'je' && p.race === 'phoenix'), 'walked back into his slab, he is still the court\'s man');
  player.prisoners = [];

  /* ── 9. THE PRISON SCREEN ── */
  Save.updateRun({ jobs: [], scrap: 300, sector: 1 });
  const map = new SectorMap(1, 777, null, 2, true);
  if (!map.prisonNode()) { const n2 = map.nodes.find(x => x.col === 3 && x.type !== 'store'); n2.type = 'prison'; }
  T.sectorMap = map;
  while (Save.wanted().length < 2) Save.addWanted(1);
  const w2 = Save.wanted()[0];
  player.prisoners = [{ id: w2.id, name: w2.name, bounty: w2.bounty, wantedId: w2.id, escapeT: 0 }];
  quiet(() => T._openPrison(map.prisonNode()));
  ok(T.STATE === 'prison' && T.prison?.isPrison && PrisonView.isOpen() && T.prison.nodeId === map.prisonNode().id, 'the node opens the prison');
  t = captureText(ctx, () => quiet(() => PrisonView.draw(ctx)));
  ok(['INTAKE', 'INTERROGATION', 'THE WARDEN', 'DEPART ▶'].every(s => t.some(o => o.t === s)) && t.some(o => o.t === w2.name), 'three counters and the way out; your captive at the intake');
  const press = (act) => { const z = PrisonView._zonesFor(act)[0]; Input.mouse.x = z.x + 3; Input.mouse.y = z.y + 3; Input.mouse.leftPressed = true; quiet(() => T._updatePrison(0.016)); Input.mouse.leftPressed = false; return z; };
  ok(PrisonView._zonesFor('ask').length === 1 && PrisonView._zonesFor('warden').length === 1 && PrisonView._zonesFor('hand').length === 1, 'he can be questioned, handed over; the warden will deal');
  const hidden0 = map.hiddenNodes().length;
  press('ask');
  ok(map.revealed && map.hiddenNodes().length === 0 && hidden0 > 0 && T.prison.asked && !player.prisoners.length && Save.getRun().scrap === 300 + w2.bounty,
     'the interrogation: the whole sector on the map, free — and he is signed in after, at his bounty');
  quiet(() => PrisonView.draw(ctx));
  /* rewritten for update166: on a known map the warden still has his secret to sell — until he has sold it */
  const tw = captureText(ctx, () => quiet(() => PrisonView.draw(ctx))).map(o => o.t).join('|');
  ok(PrisonView._zonesFor('ask').length === 0 && PrisonView.askRefusal() && /seen all of the lanes/.test(tw)
     && (map.secretNode() ? PrisonView._zonesFor('warden').length === 1 && /one place off the lanes/.test(tw) : PrisonView._zonesFor('warden').length === 0),
     'once a visit; the lanes all known — the warden sells only what no probe shows');
  map.secretKnown = true; quiet(() => PrisonView.draw(ctx));
  ok(PrisonView._zonesFor('warden').length === 0 && /nothing on this map/.test(PrisonView.wardenRefusal()), 'and when that is told too, he has nothing left');
  const map2 = new SectorMap(1, 778, null, 2, true);
  if (!map2.prisonNode()) { const n2 = map2.nodes.find(x => x.col === 3 && x.type !== 'store'); n2.type = 'prison'; }
  T.sectorMap = map2;
  quiet(() => T._openPrison(map2.prisonNode()));
  const price = Prison.wardenPrice(1), purse = Save.getRun().scrap;
  quiet(() => PrisonView.draw(ctx));
  /* rewritten for update165: 40 + 20 a sector */
  ok(price === 60 && Prison.wardenPrice(3) === 100, 'the warden: 40 and 20 a sector');
  press('warden');
  ok(map2.revealed && Save.getRun().scrap === purse - price && T.prison.sold, 'paid: every place he knows, on the map');
  Save.updateRun({ scrap: 10 });
  const map3 = new SectorMap(1, 779, null, 2, true);
  if (!map3.prisonNode()) { const n2 = map3.nodes.find(x => x.col === 3 && x.type !== 'store'); n2.type = 'prison'; }
  T.sectorMap = map3; T.prison = null;
  quiet(() => T._openPrison(map3.prisonNode())); quiet(() => PrisonView.draw(ctx));
  ok(PrisonView._zonesFor('warden').length === 0 && /CC — you have 10/.test(PrisonView.wardenRefusal()), 'short of his price: no deal');
  press('depart');
  ok(T.STATE === 'map' && !PrisonView.isOpen(), 'DEPART: back to the map');
  map3.currentId = map3.prisonNode().id;
  ok(T._atPort() && quiet(() => T._redock()) && T.STATE === 'prison' && T.prison.nodeId === map3.prisonNode().id, 'and back to its gate from the map, the same block');

  /* ── 10. THE ROUTE, IN THE GAME ── */
  Save.updateRun({ jobs: [{ ...job, id: 'jr', state: 'aboard' }] });
  const map4 = new SectorMap(1, 4242, null, 2, true);
  T.sectorMap = map4;
  const got = T._revealJobRoutes();
  ok(got.includes(map4.prisonNode().id) && map4.visibilityOf(map4.prisonNode()) === 'known', 'a transport aboard: its prison and the lane to it are on the map');
  const st = map4.nodes.find(x => x.type === 'store');
  Save.updateRun({ jobs: [{ id: 'jp', kind: 'cargo', crates: 1, port: st.portType, sector: 1, state: 'aboard' }] });
  T._revealJobRoutes();
  ok(map4.visibilityOf(st) === 'known', 'a crate for a kind of port: that port and its lane too');

  /* ── 11. THE BLOCK LIVES ── */
  const ph = [0, 6.2, 7, 9, 14 + 7.5].map(x => PrisonView.huntPhase(x).phase);
  ok(ph.join(',') === 'watch,creep,run,back,run' && PrisonView.huntPhase(7).lucky !== PrisonView.huntPhase(21).lucky,
     'the cat: watches, creeps, runs the mouse to its hole, comes back — and gets it every other time');
  const pc = [0, 1, 3, 5, 8, 12].map(x => PrisonView.pace(x, 10, 40, 10, 1));
  ok(pc.every(p => p.x >= 10 && p.x <= 40) && pc.some(p => p.moving) && pc.some(p => !p.moving), 'the men pace their cells, and stop');
  ok(Object.keys(PrisonView.heldCells()).length >= 2, 'some cells held, behind their fields');

  /* ── 12. DISPATCH AND THE LOADOUT ── */
  Base.get().jobs = [{ ...job, id: 'jd', taken: true }];
  quiet(() => BaseScreen.open()); BaseScreen._act('building', 'DISPATCH');
  const faces = [], keep = CrewArt.portraitCanvas;
  CrewArt.portraitCanvas = function (r, o) { faces.push(`${r?.name}|${!!o?.bare}`); return keep.apply(this, arguments); };
  try { t = captureText(ctx, () => quiet(() => BaseScreen.draw(ctx))); } finally { CrewArt.portraitCanvas = keep; }
  ok(t.some(o => o.t === 'PRISONERS') && t.some(o => o.t === '2 convicts · 2 carbonite slabs') && faces.filter(f => f === 'Kerr Duval|true').length >= 2,
     'DISPATCH: the card and the gangway, bare faces');
  BaseScreen._set({ screen: 'loadout', mission: 'patrol' });
  ok(BaseScreen.briefingChecks().some(c => c.level === 'bad' && /2 convicts to carry, 0 carbonite slabs/.test(c.text)) || Base.slabsOf(Base.get().ships[0]) > 0,
     'LOADOUT: no slabs for them is a red line');
})();

// ============================================================
section('350. A passenger in cream with a gold mark; the notices in the header, one at a time (164, jj: "kremowy z hełmem i znaczkiem", "toasty zasłaniają karty")');
// ============================================================
(function testUpdate164() {
  const sb = loadEngine();
  const { UI, Renderer, CrewMember, Ship, CrewArt } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };

  /* ── 1. THE PASSENGER ── */
  const vip = new CrewMember({ name: 'Dr. Ilse Marrow', race: 'aquarius', isPlayer: true, isPassenger: true, jobId: 'jv' });
  const hand = new CrewMember({ name: 'Faye Holt', race: 'terra', isPlayer: true });
  ok(vip.suitColor() === CrewMember.PASSENGER_SUIT && CrewMember.PASSENGER_SUIT === '#d9d2c0' && hand.suitColor() !== CrewMember.PASSENGER_SUIT,
     'a passenger wears civilian cream; the crew keep their own colour');
  const fills = [];
  const keepFill = ctx.fill;
  ctx.fill = function () { fills.push(String(ctx.fillStyle)); return keepFill?.apply(this, arguments); };
  const sh = new Ship('scout', true, 80, 120), r = sh.rooms[0];
  [vip, hand].forEach(c => { c.x = r.cx; c.y = sh.floorWalkY(r.floor, r.cy); c.roomId = r.id; });
  let vipGold, handGold, shownGold;
  try {
    fills.length = 0; quiet(() => vip.draw(ctx)); vipGold = fills.includes('#ffd700');
    fills.length = 0; quiet(() => hand.draw(ctx)); handGold = fills.includes('#ffd700');
    vip.nameShown = () => true; fills.length = 0; quiet(() => vip.draw(ctx)); shownGold = fills.includes('#ffd700');
  } finally { ctx.fill = keepFill; delete vip.nameShown; }
  ok(vipGold && !handGold, 'the gold mark over him, over nobody else');
  ok(!shownGold, 'and not while his name is up there instead');
  const a = CrewArt.anim('idle', vip), b = CrewArt.anim('idle', { name: vip.name, race: vip.race, bare: true, suitColor: () => CrewMember.PASSENGER_SUIT });
  ok(a.frames[0] !== b.frames[0] && !vip.bare, 'his helmet stays on (aboard, the air is the same air)');

  /* ── 2. THE NOTICES ── */
  const B = UI.NOTIF_BOX;
  ok(B.y >= 0 && B.y + B.h <= 50 && B.x >= 400 && B.x + B.w <= 1040, 'the notice box is in the header strip, between title and numbers');
  UI.update?.(99);
  while (UI.notices().length) UI.update(5);
  UI.notify('first', 'info'); UI.notify('second', 'warn'); UI.notify('third', 'good');
  let t = captureText(ctx, () => UI.draw(ctx, {}));
  ok(t.some(o => o.t === 'third') && !t.some(o => o.t === 'first' || o.t === 'second') && t.some(o => o.t === '+2'),
     'one at a time: the newest, and how many wait (+2)');
  ok(t.filter(o => o.t === 'third').every(o => o.y >= B.y && o.y <= B.y + B.h && o.x >= B.x), 'drawn inside the header box');
  UI.update(3);
  ok(UI.notices().length === 3 && UI.notices()[0].life === UI.notices()[1].life, 'only the one on show runs its clock');
  UI.update(1.1);
  t = captureText(ctx, () => UI.draw(ctx, {}));
  ok(t.some(o => o.t === 'second') && t.some(o => o.t === '+1'), 'its time up, the next one has its turn');
  for (let i = 0; i < 10; i++) UI.notify('n' + i, 'info');
  UI.update(0.01);
  ok(UI.notices().length <= 6, `the queue is short (${UI.notices().length})`);
  UI.notify('A very long notice that keeps going and going, about the egg case that split open in the hold and the spiders loose aboard and what the crew should do about it now.', 'alert');
  t = captureText(ctx, () => UI.draw(ctx, {}));
  const lines = t.filter(o => Math.abs(o.x - (B.x + 12)) < 1);
  ok(lines.length === 2 && lines[1].t.endsWith('…'), 'two lines at most — the rest is in the log');
  UI.draw(ctx, { logPanel: true });
  ok(UI.notices().length === 0, 'on the map and in a fight they go to the log window, as before');
})();

// ============================================================
section('351. The jobs, balanced (165, jj: "dodaj A … mniej ok … dokładanie C też"): no convicts for a hangar with no slabs; the warden cheaper; a passenger pays better');
// ============================================================
(function testUpdate165() {
  const sb = loadEngine();
  const { Save, Base, Ship, Prison } = sb;
  Save.reset(); Save.load();
  const realR = sb.Math.random;
  const board = (r) => { try { sb.Math.random = () => r; Base.get().jobs = null; return Base.jobs(); } finally { sb.Math.random = realR; } };
  ok(Base.get().ships.every(e => Base.slabsOf(e) === 0), 'test setup: a hangar with no carbonite bay');
  let jobs = board(0.1);
  ok(jobs.length === Base.JOB_OFFERS && jobs.every(j => j.kind !== 'convict'), 'no slabs on any hull: no PRISONERS offers — the share goes to the others');
  const s2 = new Ship('frigate', true, 0, 0); s2.addModuleAt('carbonite', 'r_crew1');
  Base.get().ships.push({ key: 'frigate', data: JSON.parse(JSON.stringify(s2.serialise())) });
  jobs = board(0.1);
  ok(jobs.every(j => j.kind === 'convict'), 'a hull with a bay in the hangar: the prisoners come back to the board');
  Base.get().ships.pop();
  ok(Prison.wardenPrice(1) === 60 && Prison.wardenPrice(2) === 80 && Prison.wardenPrice(3) === 100, 'the warden: 40 + 20 a sector (60 / 80 / 100)');
  jobs = board(0.4);
  const v = jobs[0];
  ok(v.kind === 'vip' && v.sector === 1 && v.port !== 'any' && v.pay === 200 && v.fine === v.pay, `a passenger: 90 + 80 a sector, +30 for a kind of port (${v.pay}); the fine is still the whole pay`);
})();

// ============================================================
section('352. The warden\'s secret: one node per sector off the lanes, dark to every probe, seal and interrogation — told only by the warden; a cache, a silent wreck or a quiet berth (166, jj: "naczelnik da info, gdzie jest ukryty sektor, a sonda tego nie daje … mechanika ok")');
// ============================================================
(function testUpdate166() {
  const sb = loadEngine();
  const { Save, SectorMap, Game, PrisonView, NodeView, Station, Input } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  const T = Game.__test;
  Save.load(); Save.startRun();

  /* ── 1. ONE PER SECTOR, OFF THE LANES ── */
  let one = 0, bad = 0;
  const kinds = new Set();
  for (let i = 0; i < 60; i++) {
    const m = new SectorMap(1 + i % 3, 8000 + i, null, 3, true), s = m.nodes.filter(n => n.secret);
    if (s.length === 1) one++;
    s.forEach(n => {
      kinds.add(n.secretKind);
      const a = m.getNode(n.prev[0]), b = m.getNode(n.next[0]);
      if (n.type !== 'secret' || !a || !b || b.col !== a.col + 1 || !a.next.includes(n.id) || !b.prev.includes(n.id)) bad++;
      if (m.nodes.some(o => o !== n && Math.hypot(o.x - n.x, o.y - n.y) <= 44)) bad++;
    });
  }
  ok(one >= 57 && bad === 0, `one secret a sector (${one}/60), in a gap between two columns, tied to a node each side (${bad} bad)`);
  ok(['cache', 'wreck', 'haven'].every(k => kinds.has(k)), 'a smugglers\' cache, a silent wreck or a quiet berth');
  const m = new SectorMap(1, 8003, null, 3, true), sn = m.secretNode();
  ok(sn && new SectorMap(1, 8003, null, 3, true).secretNode().x === sn.x, 'the same seed, the same secret');
  ok(sn.label === sb.SECRET_LABEL[sn.secretKind] && sb.NODE_TYPES.secret.weight === 0, 'named for what it is; never rolled');

  /* ── 2. NO PROBE SHOWS IT ── */
  m.revealAll();
  ok(m.visibilityOf(sn) === 'dark' && !m.hiddenNodes().includes(sn), 'a burnt probe: every lane known, the secret still dark (and no seal can draw it)');
  ok(m.revealSecret() && m.visibilityOf(sn) === 'known' && !m.revealSecret(), 'the warden\'s word: it is on the chart (once)');
  const back = new SectorMap(1, 8003, null, 3, true);
  back.restoreProgress(JSON.parse(JSON.stringify(m.serialiseProgress())));
  ok(back.visibilityOf(back.secretNode()) === 'known', 'and a save keeps it told');

  /* ── 3. THE WARDEN SELLS IT ── */
  const { player } = makeCombat(sb);
  Save.updateRun({ scrap: 300, sector: 1, jobs: [] });
  const map = new SectorMap(1, 8011, null, 3, true);
  if (!map.prisonNode()) map.nodes.find(x => x.col === 3 && !x.secret && x.type !== 'store').type = 'prison';
  map.revealAll();
  T.sectorMap = map; T.prison = null;
  quiet(() => T._openPrison(map.prisonNode()));
  ok(PrisonView.secret() === !!map.secretNode() && !PrisonView.wardenRefusal(), 'on a surveyed map the warden still has something to sell');
  quiet(() => PrisonView.draw(ctx));
  const z = PrisonView._zonesFor('warden')[0];
  Input.mouse.x = z.x + 3; Input.mouse.y = z.y + 3; Input.mouse.leftPressed = true; quiet(() => T._updatePrison(0.016)); Input.mouse.leftPressed = false;
  ok(map.secretKnown && map.visibilityOf(map.secretNode()) === 'known' && Save.getRun().scrap === 300 - sb.Prison.wardenPrice(1), 'paid: the secret on the chart');
  const m2 = new SectorMap(1, 8012, null, 3, true);
  if (!m2.prisonNode()) m2.nodes.find(x => x.col === 3 && !x.secret && x.type !== 'store').type = 'prison';
  T.sectorMap = m2; T.prison = null;
  while (Save.wanted().length < 1) Save.addWanted(1);
  const w = Save.wanted()[0];
  player.prisoners = [{ id: w.id, name: w.name, bounty: w.bounty, wantedId: w.id, escapeT: 0 }];
  quiet(() => T._openPrison(m2.prisonNode())); quiet(() => PrisonView.draw(ctx));
  const za = PrisonView._zonesFor('ask')[0];
  Input.mouse.x = za.x + 3; Input.mouse.y = za.y + 3; Input.mouse.leftPressed = true; quiet(() => T._updatePrison(0.016)); Input.mouse.leftPressed = false;
  ok(m2.revealed && !m2.secretKnown, 'an interrogation shows every lane — not the warden\'s secret');

  /* ── 4. WHAT IS THERE ── */
  const kindNode = (k) => { const n = new SectorMap(1, 8020, null, 3, true).secretNode(); n.secretKind = k; return n; };
  let docked = null;
  const keepDock = sb.DockingGame?.open;
  if (sb.DockingGame) sb.DockingGame.open = (o) => { docked = o; };
  try {
    quiet(() => T._openSecret(kindNode('cache')));
    ok(docked && /CACHE/.test(docked.title), 'the cache: a dock');
    docked = null; quiet(() => T._openSecret(kindNode('wreck')));
    ok(docked && /WRECK/.test(docked.title), 'the silent wreck: a dock with its clock');
  } finally { if (sb.DockingGame) sb.DockingGame.open = keepDock; }
  const mh = new SectorMap(1, 8020, null, 3, true), hn = mh.secretNode(); hn.secretKind = 'haven';
  T.sectorMap = mh; T.station = null; T.STATE = 'map';
  quiet(() => T._openSecret(hn));
  ok(T.STATE === 'station' && T.station?.haven && T.station.refusal() === null && T.station.nodeId === hn.id, 'the quiet berth: a port that shuts its dock on nobody');
  const keepRef = sb.Commander.portRefuses; sb.Commander.portRefuses = () => true;
  try { ok(T.station.refusal() === null && !!new Station(1, 5).refusal(), 'even a commander every honest port turns away'); } finally { sb.Commander.portRefuses = keepRef; }
  mh.currentId = hn.id; T.STATE = 'map'; T.station = null;
  ok(T._atPort() && quiet(() => T._redock()) && T.station.haven, 'and back up its gangway from the map, still quiet');
  ok(NodeView.kindOf(hn, mh) === 'haven' && NodeView.blurb(hn, mh).join(' ').length > 10, 'the node card says what it is');
})();

// ============================================================
section('353. The sector map as a chart of the moon: a bigger chart, its ground painted once per map and tinted by sector, the fog over it, quiet markers with names only where they matter (167, jj: "coś à la mapa księżyca, kratery … natłok ikonek … szarość się gryzie z kolorowymi ikonami")');
// ============================================================
(function testUpdate167() {
  const sb = loadEngine();
  const { SectorMap, MapNode, MapTerrain, Renderer, Save } = sb;
  const ctx = initRenderer(sb);
  Save.load(); Save.startRun();
  const G = SectorMap.GRID, W = Renderer.getWidth(), H = Renderer.getHeight(), o = SectorMap.origin(W, H), P = SectorMap.panelOf(o);

  /* ── 1. BIGGER, AND CLEAR OF THE HUD ── */
  ok(G.w === 920 && G.h === 376 && G.cols === 9 && G.rows === 5, 'a bigger chart (920 × 376), the same nine by five');
  const hit = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
  const HUD = [{ x: 8, y: 12, w: 108, h: 140 }, { x: 470, y: 8, w: 466, h: 50 }, { x: 924, y: 50, w: 308, h: 24 }, { x: 8, y: 540, w: 250, h: 172 }, { x: 278, y: 636, w: 140, h: 54 }, { x: 866, y: 588, w: 406, h: 100 }];
  ok(HUD.every(b => !hit(P, b)), `its panel (${P.x},${P.y} ${P.w}×${P.h}) covers none of the HUD`);

  /* ── 2. THE GROUND ── */
  const m = new SectorMap(1, 8003, null, 3, true);
  const at = (n) => ({ x: n.x + o.x - P.x, y: n.y + o.y - P.y });
  const g1 = MapTerrain.ground(m, P, at), k1 = MapTerrain._keys().ground;
  ok(g1 && g1.width === P.w && g1.height === P.h, 'painted the size of the panel');
  ok(MapTerrain.ground(m, P, at) === g1, 'once: the next frame reuses it');
  ok(MapTerrain.ground(new SectorMap(2, 8003, null, 3, true), P, at) !== g1 && MapTerrain._keys().ground !== k1, 'a new sector paints new ground');
  ok(MapTerrain.tintOf(1).a !== MapTerrain.tintOf(2).a && MapTerrain.tintOf(2).a !== MapTerrain.tintOf(3).a && MapTerrain.tintOf(9) === MapTerrain.tintOf(3),
     'each sector its own tint (grey, warmer, basalt)');
  ok(MapTerrain.placeOf(1) !== MapTerrain.placeOf(2), 'and its own place on the moon');
  ok(MapTerrain.fog(m, P, at, m.visibilityMap()) && !MapTerrain.fog(Object.assign(new SectorMap(1, 8003, null, 3, true), { revealed: true }), P, at, new Map()),
     'fog over an unsurveyed sector, none over a surveyed one');

  /* ── 3. THE SCREEN ── */
  const t = captureText(ctx, () => Renderer.drawMapScreen(m, null, null));
  ok(t.some(x => /SECTOR 1 MAP/.test(x.t)) && t.some(x => x.t === MapTerrain.placeOf(1)) && t.some(x => x.t === '100 km') && t.some(x => x.t === 'N'),
     'the title, where on the moon, a compass and a scale');

  /* ── 4. QUIET MARKERS, NAMES WHERE THEY MATTER ── */
  const s = new SectorMap(1, 8003, null, 3, true);
  s.currentId = s.startNodes[2].id; s.getNode(s.currentId).visited = true; s.unlockNext(); s.revealAll();
  const cur = s.current(), next = s.reachable()[0];
  const plain = s.nodes.find(n => n.locked && !n.visited && n.type === 'event' && !n.wantedId);
  const port = s.nodes.find(n => n.type === 'store');
  ok(MapNode.named(cur, s.currentId) && MapNode.named(next, s.currentId) && MapNode.named(port, s.currentId) && !MapNode.named(plain, s.currentId),
     'a name where you stand, where you can go, on a port — not on every event');
  ok(MapNode.radius(next, s.currentId) > MapNode.radius(plain, s.currentId), 'where you can go is drawn bigger');
  ok(MapNode.mute('#ff2d44') !== '#ff2d44' && /^rgb\(/.test(MapNode.mute('#ff2d44')), 'the rest in muted colour');
  const t2 = captureText(ctx, () => Renderer.drawMapScreen(s, null, null)).map(x => x.t);
  ok(t2.includes(port.label) && t2.filter(x => x === 'Event').length < s.nodes.filter(n => n.type === 'event').length,
     'on screen: the port named, most events only their sign');
})();

// ============================================================
section('354. The port is a hull (168, jj: "tak … inne kształty … może być więcej dział"): four kinds, four shapes, the stalls are its rooms, the room of the stall under the pointer lit, its line in the foot of the screen');
// ============================================================
(function testUpdate168() {
  const fs = require('fs'), path = require('path'), ROOT = path.join(__dirname, '..');
  const sb = loadEngine();
  const { Ship, Station, PortView, StationScene, STATION_HULLS, CrewArt, Input, Save } = sb;
  const ctx = initRenderer(sb);
  const quiet = (fn) => { const l = console.log, w = console.warn; console.log = console.warn = () => {}; try { return fn(); } finally { console.log = l; console.warn = w; } };
  Save.load(); Save.startRun();

  /* ── 1. FOUR KINDS, FOUR SHAPES ── */
  const kinds = ['general', 'military', 'science', 'outpost'];
  ok(kinds.every(k => sb.STRUCTURE_LAYOUTS['station_' + k] && !sb.SHIP_LAYOUTS['station_' + k]), 'a hull for every kind of port — structures, not ships');
  const hulls = Object.fromEntries(kinds.map(k => [k, new Ship('station_' + k, true, 0, 0)]));
  const shape = (sh) => sh.rooms.map(r => `${Math.round(r.x)},${Math.round(r.y)}`).sort().join('|');
  ok(new Set(kinds.map(k => shape(hulls[k]))).size === 4, 'and every one its own shape');
  ok(kinds.every(k => Object.values(STATION_HULLS.STALL_ROOMS).every(ids => hulls[k].getRoomById(ids[0]))), 'every stall is a room on every kind');
  ok(kinds.every(k => hulls[k].getRoomById('s_gate')?.art === 'gate' && hulls[k].getRoomById('s_gate').floor === 1), 'a gate where the bridge seals on, in the middle deck');
  const guns = (sh) => sh.rooms.filter(r => r.type === 'weapons' || r.type === 'artillery').length;
  ok(guns(hulls.military) > guns(hulls.general) && guns(hulls.military) >= 4, `a fleet yard bristles (${guns(hulls.military)} gun decks)`);
  ok(!hulls.outpost.getRoomById('s_customs') && Math.max(...hulls.outpost.rooms.map(r => r.x)) < Math.max(...hulls.general.rooms.map(r => r.x)), 'an outpost: narrow, and nobody checks papers');
  ok(hulls.science.rooms.filter(r => r.art === 'lab').length >= 2, 'a science post: labs');
  ok(StationScene.layoutKey('military') === 'station_military' && StationScene.layoutKey('nonsense') === 'station_general', 'a port of no known kind is a trade port');

  /* ── 2. THEIR ROOMS, PAINTED ── */
  const man = JSON.parse(fs.readFileSync(path.join(ROOT, 'art/manifest.json'), 'utf8'));
  const bad = [];
  ['bar', 'storage', 'broker', 'customs', 'gate', 'dock', 'lab', 'quarters'].forEach(k => ['', '_terra', '_phoenix', '_aquarius', '_pegasus'].forEach(y => {
    const n = `room_${k}${y}`, f = path.join(ROOT, 'art', n + '.png');
    if (!fs.existsSync(f)) return bad.push(n + ' missing');
    const b = fs.readFileSync(f); if (b.readUInt32BE(16) !== 100 || b.readUInt32BE(20) !== 50) bad.push(n + ' size');
    if (!man.sprites.includes(n)) bad.push(n + ' not listed');
  }));
  ok(bad.length === 0, `the port's own rooms, painted like modules, every yard (${bad.slice(0, 3).join('; ') || 'all'})`);

  /* ── 3. THE WINDOW ── */
  const st = new Station(1, 4242, { type: 'military' }), sh = new Ship('scout', true, 80, 120);
  PortView.open(st, sh);
  const anims = [], keep = CrewArt.anim;
  CrewArt.anim = function (state, rec) { anims.push({ state, bare: !!rec?.bare, name: rec?.name }); return keep.apply(this, arguments); };
  try { quiet(() => PortView.draw(ctx)); } finally { CrewArt.anim = keep; }
  ok(StationScene._state().key.startsWith('station_military|'), 'the window shows this port\'s hull');
  ok(anims.some(a => /^Patron/.test(a.name)) && anims.filter(a => /^Patron/.test(a.name)).every(a => a.bare) && anims.filter(a => /^Hand /.test(a.name)).every(a => !a.bare), 'off duty in the bar, bare; on duty at the counters, in helmets');
  // the stall under the pointer
  const i = PortView.STALLS.findIndex(s => s.key === 'bar'), r = PortView.stallRect(i);
  Input.mouse.x = r.x + 20; Input.mouse.y = r.y + 60; quiet(() => PortView.update(0.016));
  const rects = [], keepR = ctx.strokeRect;
  ctx.strokeRect = function (x, y, w, h) { rects.push({ x, y, w, h }); return keepR.apply(this, arguments); };
  let t;
  try { t = captureText(ctx, () => quiet(() => PortView.draw(ctx))); } finally { ctx.strokeRect = keepR; }
  const bars = StationScene.stallRooms('bar');
  ok(bars.length >= 1 && bars.every(b => rects.some(q => Math.abs(q.x - (b.x + 1)) < 0.5 && Math.abs(q.y - (b.y + 1)) < 0.5)), 'the bar under the pointer: its room on the station lit');
  ok(t.some(o => o.t === PortView.stallLine('bar') && o.y > 660) && !t.some(o => o.t === PortView.stallLine('bar') && o.y < 400), 'its line in the foot of the screen, not over the window');
  Input.mouse.x = Input.mouse.y = -99;
  PortView.close();
})();

// ============================================================
section('355. A drive that will not spin up says what is wrong and what to do (169, autoplay: 50 s in front of "Engines offline" with the engines shot to pieces)');
// ============================================================
(function testUpdate169() {
  const sb = loadEngine();
  const { Save, Base, Game, CargoGrid, CargoItem } = sb;
  initRenderer(sb);
  const T = Game.__test;
  const l = console.log; console.log = () => {};
  let P, eng, pil, room;
  try {
    Save.reset(); Save.load(); Base.earn(3000);
    const hold = new CargoGrid(5, 3); for (let k = 0; k < 3; k++) hold.autoPlace(new CargoItem('he2_med'));
    const res = Base.launch({ shipIndex: 0, crewIds: Base.crew().map(c => c.id), mission: 'patrol', hold });
    T._startContract(res); T._travelTo(T.sectorMap.startNodes[0].id);
    for (let k = 0; k < 40; k++) T._update(0.05);
    P = T.playerShip; eng = P.getSystem('engines'); pil = P.getSystem('piloting');
    room = P.rooms.find(r => r.system === eng);
    manCockpit(P);
  } finally { console.log = l; }
  ok(T._jumpRefusal() === null, `a sound ship, a hand at the helm: she jumps (${T._jumpRefusal()})`);
  eng.damagedLevels = eng.level;
  const w = T._jumpRefusal();
  ok(/Engines wrecked/.test(w) && /repair/.test(w) && /engine room/.test(w), `wrecked engines: send a hand in (${w})`);
  eng.damagedLevels = 0; eng.update(0.01); eng.power = 1; eng._ionLocks = [30]; eng.ionDamage = 1;
  ok(/Engines ion-locked/.test(T._jumpRefusal() ?? ''), `ion-locked: wait (${T._jumpRefusal()})`);
  eng._ionLocks = []; eng.ionDamage = 0; eng.power = 0;
  ok(/Engines offline — route reactor power/.test(T._jumpRefusal() ?? ''), `merely unpowered: the reactor (${T._jumpRefusal()})`);
  eng.power = 1;
  pil.damagedLevels = pil.level;
  ok(/Cockpit wrecked — send a hand into the cockpit/.test(T._jumpRefusal() ?? ''), `the cockpit too (${T._jumpRefusal()})`);
  pil.damagedLevels = 0;
  // and the advice is true: a hand sent into the engine room mends them on the map
  eng.damagedLevels = eng.level;
  const hand = P.crew.find(c => c.isPlayer && !c.isPet);
  hand.moveToOnShip(P, room.cx, room.cy);
  let t = 0; console.log = () => {};
  try { for (; t < 1200 && eng.effectivePower() <= 0; t++) T._update(0.05); } finally { console.log = l; }
  ok(eng.effectivePower() > 0 && t * 0.05 < 40, `and it is true: one hand in the engine room has them turning in ${(t * 0.05).toFixed(1)} s`);
  ok(w.length <= 90, 'the sentence fits the header toast');
})();

// ============================================================
section('356. The moon under every fight (170, jj: bunker "niżej … żeby statek atakował z góry", "bardziej zintegrowany", and "regolit nie powinien zasłaniać modułów"; the fight in motion only to the eye)');
// ============================================================
(function testUpdate170() {
  const sb = loadEngine();
  const { Save, Base, Game, CargoGrid, CargoItem, Ship, CombatGround } = sb;
  const ctx = initRenderer(sb);
  const T = Game.__test;
  const l = console.log;
  const fight = (rnd) => {
    Save.reset(); Save.load(); Base.earn(3000);
    const hold = new CargoGrid(5, 3); for (let k = 0; k < 3; k++) hold.autoPlace(new CargoItem('he2_med'));
    const res = Base.launch({ shipIndex: 0, crewIds: Base.crew().map(c => c.id), mission: 'patrol', hold });
    T._startContract(res);
    Save.getRun().sector = 2;
    const keep = sb.Math.random; sb.Math.random = () => rnd;
    try { T._startCombat('normal', false); } finally { sb.Math.random = keep; }
    return T.enemyShip;
  };
  let bunker, ship, P;
  console.log = () => {};
  try { bunker = fight(0.01); P = T.playerShip; } finally { console.log = l; }
  ok(typeof CombatGround === 'object' && CombatGround.HORIZON === 400 && CombatGround.DROP > 0, 'CombatGround is loaded');
  ok(!!bunker?.layout?.grounded, `a grounded foe drawn (${bunker?.layout?.name})`);
  const bb = bunker.roomBounds(), pb = P.roomBounds();
  ok(bb.y >= Ship.ENEMY_STATION.y + CombatGround.DROP - 1, `the bunker stands low (${bb.y})`);
  ok(bb.y > pb.y + pb.h / 2 && bb.y + bb.h <= 700, `below the middle of our hull, still on the screen (${bb.y}…${bb.y + bb.h})`);
  ok(bb.y + bb.h > CombatGround.HORIZON, 'its foot is on the plain, below the horizon');
  ok(!CombatGround.moving(P, bunker), 'over a bunker the ground stands still');
  // the frame: the plain first, then each hull between its under and its over
  const order = [];
  const keep = { draw: CombatGround.draw, under: CombatGround.under, over: CombatGround.over };
  CombatGround.draw = function (...a) { order.push('ground:' + a[3]); return keep.draw.apply(this, a); };
  CombatGround.under = function (c, sh) { order.push('under:' + (sh.isPlayer ? 'P' : 'E')); return keep.under.apply(this, arguments); };
  CombatGround.over = function (c, sh) { order.push('over:' + (sh.isPlayer ? 'P' : 'E')); return keep.over.apply(this, arguments); };
  let threw = null;
  console.log = () => {};
  try { T._draw(); } catch (e) { threw = e; } finally { console.log = l; Object.assign(CombatGround, keep); }
  ok(!threw, 'the frame draws: ' + (threw?.message ?? 'ok'));
  ok(order[0] === 'ground:false', `the plain comes first, still (${order.slice(0, 1)})`);
  const iu = order.indexOf('under:E'), io = order.indexOf('over:E');
  ok(iu > 0 && io > iu && order.includes('under:P') && order.includes('over:P'), `each hull: under, then over (${order.join(' ')})`);
  ok(CombatGround._key() === '2', `the ground is painted for the sector (${CombatGround._key()})`);
  // NOTHING OF THE GROUND OVER A ROOM: every point "over" draws lies below the lowest floor
  const ys = [];
  const spy = ['moveTo', 'lineTo', 'fillRect', 'rect', 'ellipse', 'arc'];
  const real = {}; spy.forEach(k => { real[k] = ctx[k]; ctx[k] = function (x, y, w, h) { ys.push(k === 'fillRect' || k === 'rect' ? y : y); return real[k]?.apply(this, arguments); }; });
  try { CombatGround.over(ctx, bunker); } finally { spy.forEach(k => { ctx[k] = real[k]; }); }
  const floor = bb.y + bb.h;
  ok(ys.length > 0 && Math.min(...ys) >= floor, `in front of the hull only what lies below its lowest floor (${Math.min(...ys)} ≥ ${floor})`);
  ok(CombatGround.LIP_GAP >= 0, 'the lip keeps clear of the floor');
  // a hull that flies stays where it always was, and the ground slides under the two of them
  console.log = () => {};
  try { ship = fight(0.9); } finally { console.log = l; }
  ok(!ship.layout?.grounded && ship.roomBounds().y < Ship.ENEMY_STATION.y + CombatGround.DROP, `a flying foe is not dropped (${ship.layout?.name}, ${ship.roomBounds().y})`);
  ok(CombatGround.moving(T.playerShip, ship), 'two hulls in the air: the ground slides');
  ok(!CombatGround.moving(T.playerShip, null), 'no foe: no slide');
  const ys2 = []; const r2 = ctx.fillRect; ctx.fillRect = function (x, y) { ys2.push(y); return r2.apply(this, arguments); };
  try { CombatGround.over(ctx, ship); } finally { ctx.fillRect = r2; }
  ok(ys2.length === 0, 'over a flying hull nothing is drawn at all');
  // a mech drives: nothing over its treads either
  let mech; console.log = () => {};
  try { mech = fight(0.13); } finally { console.log = l; }
  ok(!!mech?.layout?.tracks, `a mech drawn (${mech?.layout?.name})`);
  const ys3 = []; const r3 = ctx.fillRect, f3 = ctx.fill; ctx.fillRect = function (x, y) { ys3.push(y); return r3.apply(this, arguments); }; ctx.fill = function () { ys3.push('fill'); return f3?.apply(this, arguments); };
  try { CombatGround.over(ctx, mech); } finally { ctx.fillRect = r3; ctx.fill = f3; }
  ok(ys3.length === 0, 'over a mech nothing is drawn (its treads stay clear)');
  // while the film still hides her, no shadow of her on the plain
  const JS = sb.JumpScene, keepP = JS.placement, calls = [];
  const keepU = CombatGround.under;
  JS.placement = () => ({ visible: false, dx: 0, sx: 1 });
  CombatGround.under = function (c, sh) { calls.push(sh.isPlayer ? 'P' : 'E'); };
  console.log = () => {};
  try { T._draw(); } finally { console.log = l; JS.placement = keepP; CombatGround.under = keepU; }
  ok(calls.length === 0, `no ground for a hull the film hides (${calls.join(',')})`);
})();

// ============================================================
section('357. The tractor beam: Lunar Customs hold you (171, jj: "promień ściągający jak z Endoru"; mk_tractor — "OK")');
// ============================================================
(function testUpdate171() {
  const sb = loadEngine();
  const { Save, Base, Game, CargoGrid, CargoItem, Ship, SYSTEM_DEFS, SHIP_LAYOUTS, CombatManager, UI, Renderer } = sb;
  const ctx = initRenderer(sb);
  const T = Game.__test;
  const l = console.log;
  const said = []; const keepNotify = UI.notify; UI.notify = (m) => { said.push(String(m)); };
  const fight = (rnd, hot) => {
    Save.reset(); Save.load(); Base.earn(3000);
    const hold = new CargoGrid(5, 3); for (let k = 0; k < 3; k++) hold.autoPlace(new CargoItem('he2_med'));
    if (hot) hold.autoPlace(new CargoItem('contraband'));
    const res = Base.launch({ shipIndex: 0, crewIds: Base.crew().map(c => c.id), mission: 'patrol', hold });
    T._startContract(res);
    Save.getRun().sector = 2;
    const keep = sb.Math.random; sb.Math.random = () => rnd;
    try { T._startCombat('normal', false); } finally { sb.Math.random = keep; }
    for (let k = 0; k < 120 && !CombatManager.isActive(); k++) T._updateCombat(0.05);    // through the opening film
    return T.enemyShip;
  };
  const run = (secs) => { for (let k = 0; k < secs * 20 && T.STATE === 'combat'; k++) T._updateCombat(0.05); };
  try {
    console.log = () => {};
    // ── the module and the hull ──
    ok(SYSTEM_DEFS.tractor?.maxLevel === 3 && SYSTEM_DEFS.tractor.lockTimes.join() === '30,25,20', 'TRACTOR: levels 1–3, 30 / 25 / 20 s to drag you in');
    const L = SHIP_LAYOUTS.customs_cruiser;
    ok(L?.label === 'Maat' && L.customs && L.armor === 2 && L.rooms.some(r => r.type === 'tractor'), 'the customs cruiser: Maat, armoured, a TRACTOR room');
    ok(Renderer.systemGlyph('tractor') !== '?', 'the tractor has a glyph');
    // ── who you meet ──
    let E = fight(0.25, true);
    ok(E?.layoutKey === 'customs_cruiser' || E?.layout?.label === 'Maat', `contraband in the hold: customs at a 0.25 roll (${E?.layout?.label})`);
    ok(E.hullMax >= 28, `a lot of hull — winning is the long way out (${E.hullMax})`);
    const E2 = fight(0.25, false);
    ok(E2?.layout?.label !== 'Maat', `a clean hold at the same roll: no customs (${E2?.layout?.label})`);
    // ── held ──
    E = fight(0.25, true);
    const tr = E.getSystem('tractor');
    for (let k = 0; k < 40 && tr.effectivePower() <= 0; k++) T._updateCombat(0.05);   // their captain routes power to it
    ok(tr.effectivePower() > 0 && CombatManager.tractorLocked(), `the beam runs and holds us (power ${tr.effectivePower()})`);
    ok(/TRACTOR/.test(T._jumpRefusal() ?? ''), `no jump while held: "${T._jumpRefusal()}"`);
    const total = CombatManager.tractor.total;
    ok(total === SYSTEM_DEFS.tractor.lockTimes[tr.level - 1], `the clock is the level's (${total} s at level ${tr.level})`);
    // the frame says it: the banner and the dead RETREAT
    const txt = captureText(ctx, () => T._draw()).map(d => d.t).join(' | ');
    ok(/TRACTOR LOCK — LUNAR CUSTOMS/.test(txt) && /boarding inspection in 0:\d\d/.test(txt), 'the banner: who holds us, and the clock');
    ok(/TRACTOR LOCK/.test(txt) && !/RETREAT \[R\]/.test(txt), 'RETREAT says TRACTOR LOCK while held');
    // customs do not shoot first
    const P = T.playerShip, hull0 = P.hull;
    let theirShots = 0;
    for (let k = 0; k < 160 && T.STATE === 'combat'; k++) {
      T._updateCombat(0.05);
      theirShots += CombatManager._projectiles.filter(p => !p.fromPlayer && !p.fromField && !p._counted171 && (p._counted171 = true)).length;
    }
    ok(theirShots === 0 && P.hull === hull0 && !CombatManager.customsProvoked, `eight seconds held and not one shot fired at us (${theirShots} shots, hull ${hull0} → ${P.hull})`);
    ok(CombatManager.tractor.left < total - 7, `the clock runs while held (${CombatManager.tractor.left.toFixed(1)} s left)`);
    // ── the inspection: contraband seized, a fine, and they let go ──
    const scrap0 = Save.getRun().scrap;
    run(total + 2);
    ok(T.STATE !== 'combat', `the clock ran out: the fight is over (${T.STATE})`);
    ok(!P.cargo.items.some(it => it.def?.contraband), 'customs seized the contraband');
    ok(Save.getRun().scrap < scrap0, `and took a fine (${scrap0} → ${Save.getRun().scrap})`);
    ok(said.some(m => /Customs seized/.test(m)), 'and said so');
    // ── a clean hold is waved on ──
    said.length = 0;
    E = fight(0.25, true);
    T.playerShip.cargo.items.filter(it => it.def?.contraband).forEach(it => T.playerShip.cargo.remove(it));
    const sc1 = Save.getRun().scrap;
    run(40);
    ok(T.STATE !== 'combat' && Save.getRun().scrap === sc1 && said.some(m => /hold is clean/.test(m)), `a clean hold: waved on, nothing taken (${said.filter(m => /clean/.test(m)).join('')})`);
    // ── break the beam: the drive is free ──
    said.length = 0;
    E = fight(0.25, true);
    run(2);
    const t2 = E.getSystem('tractor');
    // a beam with no power holds nothing
    const pw = t2.power; t2.power = 0;
    ok(!CombatManager.tractorLocked(), 'starved of power: it holds nothing');
    t2.power = pw;
    ok(CombatManager.tractorLocked(), 'powered again: held again');
    // shot away (and — for the clock alone — with customs not yet provoked by it)
    const keepHurt = CombatManager._customsHurt; CombatManager._customsHurt = () => false;
    t2.damagedLevels = t2.level; t2.update?.(0.01);
    ok(!CombatManager.tractorLocked(), 'its levels shot away: the beam breaks');
    ok(!/TRACTOR/.test(T._jumpRefusal() ?? ''), `and the drive is free (${T._jumpRefusal()})`);
    run(0.2);
    ok(said.some(m => /TRACTOR is down/.test(m)), 'and the game says so');
    const left = CombatManager.tractor.left; run(3);
    ok(Math.abs(CombatManager.tractor.left - left) < 1e-9 && !CombatManager.customsProvoked, 'the clock stops while the beam is down');
    CombatManager._customsHurt = keepHurt;
    // ── shoot at customs: they shoot back, and nobody inspects anything ──
    said.length = 0;
    E = fight(0.25, true);
    run(1);
    E.hull -= 2;
    run(0.2);
    ok(CombatManager.customsProvoked && said.some(m => /fired on customs/.test(m)), 'hurt them: provoked, and told so');
    const l2 = CombatManager.tractor.left; run(4);
    ok(CombatManager.tractor.left === l2, 'provoked: no more inspection clock');
    const h2 = T.playerShip.hull; run(25);
    ok(T.playerShip.hull < h2 || T.STATE !== 'combat', `provoked: they open fire (hull ${h2} → ${T.playerShip.hull})`);
    // ── review fixes ──
    // a rock of the field is nobody's shot: harm from it does not provoke them
    E = fight(0.25, true); run(1);
    CombatManager._fieldHitEnemy = true; E.hull -= 2; run(0.5);
    ok(!CombatManager.customsProvoked, 'a rock hit them: not provoked');
    CombatManager._shotAtEnemy = true; run(0.2);
    ok(CombatManager.customsProvoked, 'our shot landed on them: provoked');
    // unprovoked, their crew still work: a broken beam gets mended
    E = fight(0.25, true); run(1);
    const t3 = E.getSystem('tractor'), keepH = CombatManager._customsHurt; CombatManager._customsHurt = () => false;
    t3.damagedLevels = t3.level; t3.update?.(0.01);
    ok(!CombatManager.tractorLocked(), 'beam down');
    // and a jump begun while it is down is lost when it holds again
    ok(CombatManager.initiateRetreat(1) && CombatManager.state === 'retreating', 'we start the jump while it is down');
    t3.damagedLevels = 0; t3.update?.(0.01);
    for (let k = 0; k < 40 && CombatManager.state === 'retreating'; k++) T._updateCombat(0.05);
    ok(CombatManager.state === 'active' && said.some(m => /TRACTOR has us again/.test(m)), `mended mid-spool: the charge is lost, we are held (${CombatManager.state})`);
    // nobody standing in the beam's room: somebody has to be SENT (the crew AI)
    { const away = E.rooms.find(r => r.system?.type === 'engines');
      E.crew.filter(c => c.alive && c.roomId === t3.roomId).forEach(c => {
        c.roomId = away.id; c.x = away.cx; c.y = E.floorWalkY(away.floor, away.cy); c._waypoints = [];
      }); }
    t3.damagedLevels = t3.level; t3.update?.(0.01);
    let mended = false; for (let k = 0; k < 900 && !mended && T.STATE === 'combat'; k++) { T._updateCombat(0.05); mended = t3.workingLevels > 0; }
    ok(mended, 'unprovoked customs still repair their ship (the AI runs, only the guns are held)');
    CombatManager._customsHurt = keepH;
    // the first contract promises one gun: no two-gun cruiser on it
    Save.reset(); Save.load(); Base.earn(3000);
    { const hold = new CargoGrid(5, 3); hold.autoPlace(new CargoItem('contraband'));
      const res = Base.launch({ shipIndex: 0, crewIds: Base.crew().map(c => c.id), mission: 'courier', hold });
      T._startContract(res); Save.getRun().sector = 2;
      const keep = sb.Math.random; sb.Math.random = () => 0.25;
      try { T._startCombat('normal', false); } finally { sb.Math.random = keep; } }
    ok(T.enemyShip?.layout?.label !== 'Maat', `courier run: no customs cruiser (${T.enemyShip?.layout?.label})`);
  } finally { console.log = l; UI.notify = keepNotify; }
})();

// ============================================================
section('27. Engine boots and runs a frame');
// ============================================================
(async function testEngineBoots() {
  const sb = loadEngine();
  try {
    await sb.Game.init();
    await new Promise((resolve) => setTimeout(resolve, 60));
    ok(true, 'engine ran init + at least one update/draw tick without throwing');
  } catch (e) {
    ok(false, 'Game.init()/loop threw: ' + (e && e.stack || e));
  }
})().then(settleAsyncSections).then(() => {
  console.log(`\n${passed} passed, ${failures} failed`);
  process.exit(failures ? 1 : 0);
});
